/*
 * MLX91219 Hall-Effect Current Sensor reader via ADS1115 ADC on Raspberry Pi 4.
 *
 * Wiring:
 *   MLX91219 VCC  -> 3.3 V (Pin 1)
 *   MLX91219 GND  -> GND   (Pin 6)
 *   MLX91219 AOUT -> ADS1115 AIN0 (Pin 2)
 *   ADS1115 VDD   -> 3.3 V (Pin 1)
 *   ADS1115 GND   -> GND   (Pin 6)
 *   ADS1115 SDA   -> GPIO2 (Pin 3)
 *   ADS1115 SCL   -> GPIO3 (Pin 5)
 *   ADS1115 ADDR  -> GND  (I2C address 0x48)
 *
 * Build:  gcc -O2 -Wall -o mlx91219_adc mlx91219_adc.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ADS1115 register addresses ---- */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* ---- ADS1115 config bit fields ---- */
#define ADS1115_CFG_OS_SINGLE   0x8000  /* assert single-shot start bit       */
#define ADS1115_CFG_MUX_AIN0    0x4000  /* single-ended AIN0 vs GND           */
#define ADS1115_CFG_PGA_4_096V  0x0200  /* programmable gain ±4.096 V          */
#define ADS1115_CFG_MODE_SS    0x0100  /* single-shot mode                    */
#define ADS1115_CFG_DR_128SPS  0x0080  /* 128 SPS data rate                   */
#define ADS1115_CFG_CQUE_NONE  0x0003  /* disable comparator                   */

/* ---- ADS1115 PGA full-scale range ---- */
#define ADS1115_PGA_4_096V  4.096

/* ---- I2C / ADS1115 constants ---- */
#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_CONV_REG 0x00
#define ADS1115_CONFIG_REG 0x01

#define SAMPLE_PERIOD_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register (MSB first).
 * Returns 0 on success, -1 on error.
 */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register (MSB first).
 * Returns 0 on success, -1 on error.
 */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success and stores the raw 16-bit code in *raw_out;
 * returns -1 on error.
 */
static int ads1115_read_ain0(int fd, int16_t *raw_out)
{
    uint16_t config = ADS1115_CFG_OS_SINGLE
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096V
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128SPS
                    | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_CONFIG_REG, config) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t raw;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    *raw_out = (int16_t)raw;
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* ---- Install SIGINT handler for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the I2C bus ---- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire the ADS1115 slave address ---- */
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* ---- Verify the ADS1115 is present by reading the config register ---- */
    uint16_t cfg_readback;
    if (ads1115_read_reg(fd, ADS1115_CONFIG_REG, &cfg_readback) != 0) {
        fprintf(stderr, "ADS1115 not responding at address 0x%02X "
                        "(sensor absent or wiring issue).\n", ADS1115_ADDR);
        goto cleanup;
    }

    printf("ADS1115 detected (config register = 0x%04X).\n", cfg_readback);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(fd, &raw) != 0) {
            fprintf(stderr, "ADC read error; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        /*
         * Convert raw 16-bit signed value to current.
         * ADS1115 PGA = ±4.096 V  -> LSB = 4.096 V / 32768 ≈ 0.000125 V.
         * raw / 32768.0 gives the voltage across the MLX91219.
         * MLX91219 sensitivity ~ 0.1 A/V at 4.096 V.
         */
        float voltage = (float)raw / 32768.0f * ADS1115_PGA_4_096V;
        float current = voltage * 0.1f;

        printf("Current: %.4f A  (raw: %d)\n", current, raw);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

