#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONV_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONFIG_AIN0 0x4000
#define ADS1115_CONFIG_OS 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 100
#define BUZZER_DURATION_MS 2000
#define LOG_FILE "fire_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set flame sensor pin mode\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state\n");
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X (code %d)\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_ads1115(void) {
    uint16_t config = ADS1115_CONFIG_OS | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register\n");
        return -1;
    }
    return 0;
}

static int read_ads1115(float *temperature) {
    char reg = ADS1115_CONV_REG;
    char buf[2];
    int16_t raw;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to set ADS1115 conversion register pointer\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion register\n");
        return -1;
    }
    raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (raw * 4.096f) / 32768.0f;
    return 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush() failed\n");
        return -1;
    }
    return 0;
}

static void activate_buzzer(int duration_ms) {
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to activate buzzer\n");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to deactivate buzzer\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (init_gpio() < 0) {
        return 1;
    }
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }
    if (init_ads1115() < 0) {
        cleanup();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }
    printf("Fire detection system started. Press Ctrl+C to exit.\n");
    int flame_last = 0;
    uint32_t last_debounce_time = 0;
    while (running) {
        int flame = gpioRead(FLAME_SENSOR_PIN);
        if (flame < 0) {
            fprintf(stderr, "Error: gpioRead failed on flame sensor pin %d\n", FLAME_SENSOR_PIN);
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }
        uint32_t now = gpioTick();
        if (flame && (now - last_debounce_time) > (DEBOUNCE_MS * 1000)) {
            last_debounce_time = now;
            if (flame != flame_last) {
                flame_last = flame;
                float temperature;
                if (read_ads1115(&temperature) == 0) {
                    if (temperature > TEMP_THRESHOLD) {
                        if (log_event("Flame detected!") < 0) {
                            fprintf(stderr, "Warning: failed to log flame event\n");
                        }
                        printf("Flame detected! Temperature: %.2f C\n", temperature);
                    } else {
                        if (log_event("Flame detected!") < 0) {
                            fprintf(stderr, "Warning: failed to log flame event\n");
                        }
                        printf("Flame detected!\n");
                    }
                } else {
                    fprintf(stderr, "Warning: ADC read failed, skipping fire detection\n");
                }
            }
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

