/*
 * MLX91219 current monitor with MCP3008 ADC and cooling fan control.
 *
 * Hardware (Raspberry Pi 5):
 *   - MCP3008 ADC on SPI0 CE0 (spidev0.0), 1 MHz, mode 0, 8 bits/word.
 *   - MLX91219 VOUT -> MCP3008 CH0.
 *   - Cooling fan on GPIO18 (BCM).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c \
 *       -lgpiod -lrt
 *
 * Run:
 *   ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE          0          /* SPI mode 0 */

#define MCP3008_CHANNEL   0          /* MCP3008 single-ended channel 0 */

#define FAN_GPIO_LINE     18         /* BCM 18 */
#define GPIO_CHIP_NAME    "gpiochip4" /* Pi 5 main GPIO controller */
#define GPIO_CHIP_FALLBACK "gpiochip0"

#define CURRENT_THRESHOLD 2000       /* ADC counts (adjust per sensor) */
#define LOG_FILE          "current_log.txt"
#define SAMPLE_PERIOD_S   1          /* seconds */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_fan_line = NULL;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ MCP3008 read ----------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* ------------------------------ Logging ---------------------------------- */

static void log_current(int adc_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, ADC: %d\n", ts, adc_value);
    fclose(fp);
}

/* ------------------------------ Fan control ------------------------------ */

static int fan_set(int on)
{
    if (!g_fan_line) {
        fprintf(stderr, "Fan GPIO line not initialized\n");
        return -1;
    }
    if (gpiod_line_set_value(g_fan_line, on ? 1 : 0) < 0) {
        fprintf(stderr, "Failed to set fan GPIO: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------ Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_fan_line) {
        (void)gpiod_line_set_value(g_fan_line, 0);
        gpiod_line_release(g_fan_line);
        g_fan_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        /* Fallback: try gpiochip0 on older kernels */
        g_chip = gpiod_chip_open_by_name(GPIO_CHIP_FALLBACK);
    }
    if (!g_chip) {
        fprintf(stderr, "Cannot open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_fan_line = gpiod_chip_get_line(g_chip, FAN_GPIO_LINE);
    if (!g_fan_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", FAN_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_fan_line, "current_monitor", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                FAN_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc = mcp3008_read(g_spi_fd, MCP3008_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; skipping sample.\n");
        } else if (adc == 0 || adc == 0x3FF) {
            fprintf(stderr, "ADC value 0x%03X (sensor absent or bus fault).\n", adc);
        } else {
            log_current(adc);
            int fan_on = (adc > CURRENT_THRESHOLD) ? 1 : 0;
            if (fan_set(fan_on) < 0) {
                fprintf(stderr, "Fan control failed; continuing.\n");
            }
            printf("ADC: %4d  Fan: %s\n", adc, fan_on ? "ON" : "OFF");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

