 *
 * Reads a Honeywell/SGX MICS-4514 dual-element MOS NO2/CO sensor via I2C
 * (e.g. ADS1115 ADC) and logs CO concentration (ppm) to co_log.txt every 5 s.
 *
 * Wiring:
 *   MICS-4514 SDA  -> I2C bus 1 SDA (GPIO 2 / pin 3)
 *   MICS-4514 SCL  -> I2C bus 1 SCL (GPIO 3 / pin 5)
 *   MICS-4514 VDD  -> 3.3 V
 *   MICS-4514 GND  -> GND
 *   ADS1115 SDA    -> I2C bus 1 SDA (GPIO 2 / pin 3)
 *   ADS1115 SCL    -> I2C bus 1 SCL (GPIO 3 / pin 5)
 *   ADS1115 ADDR   -> GND (I2C address 0x48)
 *   ADS1115 AIN0   -> MICS-4514 analog out
 *   ADS1115 VDD    -> 3.3 V
 *   ADS1115 GND    -> GND
 *
 * Build: gcc -O2 -Wall -o co_logger co_logger.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: single-shot, AIN0, +/-4.096 V, 128 SPS, continuous */
#define ADS1115_CFG_BASE 0x8000  /* OS bit */
#define ADS1115_CFG_MUX  0x4000  /* AIN0 vs GND */
#define ADS1115_CFG_PGA  0x0200  /* +/-4.096 V */
#define ADS1115_CFG_DR   0x0080  /* 128 SPS */
#define ADS1115_CFG      (ADS1115_CFG_BASE | ADS1115_CFG_MUX | ADS1115_CFG_PGA | ADS1115_CFG_DR)

#define LOG_FILE        "co_log.txt"
#define SAMPLE_INTERVAL 5       /* seconds */
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write 16-bit value to ADS1115 register */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing ADS1115 reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read 16-bit value from ADS1115 register */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting ADS1115 reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Trigger a single conversion and read the raw 16-bit result */
static int ads1115_read_raw(int fd, int16_t *raw_out)
{
    uint16_t cfg = ADS1115_CFG;
    uint16_t conv;
    int retries = 0;

    /* Write config to start a single-shot conversion */
    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, cfg) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    /* Poll OS bit (bit 15) until conversion completes */
    for (retries = 0; retries < MAX_RETRIES; retries++) {
        if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &conv) < 0)
            return -1;
        if (conv & 0x8000)
            break;
        usleep(10000);
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "ADS1115 conversion timeout\n");
        return -1;
    }

    /* Read conversion result */
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &conv) < 0)
        return -1;

    *raw_out = (int16_t)conv;
    return 0;
}

/* Convert raw ADC value to CO ppm using a calibrated logarithmic curve */
static float raw_to_ppm(int16_t raw)
{
    /* Placeholder logarithmic curve; replace with calibrated curve from datasheet */
    float resistance = 10.0f * (float)raw;
    float ppm = 100.0f * powf(10.0f, -(resistance / 1000.0f));
    return ppm;
}

/* Append a timestamped CO concentration to the log file */
static int log_co_ppm(float ppm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f ppm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, ppm);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire ADS1115 device */
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error acquiring I2C bus address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MICS-4514 CO Sensor Logger started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw;
        float ppm;

        if (ads1115_read_raw(fd, &raw) < 0) {
            fprintf(stderr, "Error reading CO sensor data (I2C bus error or sensor absent).\n");
        } else {
            ppm = raw_to_ppm(raw);
            printf("CO: %.2f ppm (raw: %d)\n", ppm, raw);

            if (log_co_ppm(ppm) < 0) {
                fprintf(stderr, "Error logging CO concentration.\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return ret;
}

