#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4B
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *ox, uint16_t *red) {
    char buf[4];
    int bytes = i2cReadDevice(handle, buf, 4);
    if (bytes != 4) {
        fprintf(stderr, "Error reading I2C data: expected 4 bytes, got %d\n", bytes);
        return -1;
    }
    *ox = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    *red = ((uint16_t)(buf[2] & 0xFF) << 8) | (uint16_t)(buf[3] & 0xFF);
    return 0;
}

static float calculate_co_ppm(uint16_t ox) {
    return (float)ox * 0.1f;
}

static int log_co_data(const char *filename, float co_ppm) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f ppm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    } else {
        fprintf(fp, "(time error), %.2f ppm\n", co_ppm);
    }
    fclose(fp);
    return 0;
}

static int check_threshold(float co_ppm) {
    return (co_ppm >= CO_THRESHOLD) ? 1 : 0;
}

static int log_alert(const char *filename, float co_ppm) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, CO threshold exceeded: %.2f ppm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    } else {
        fprintf(fp, "(time error), CO threshold exceeded: %.2f ppm\n", co_ppm);
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ox = 0, red = 0;
        if (read_sensor_data(i2c_handle, &ox, &red) != 0) {
            fprintf(stderr, "Sensor read error, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_SEC, 0);
            continue;
        }

        float co_ppm = calculate_co_ppm(ox);
        printf("CO: %.2f ppm (OX=%u, RED=%u)\n", co_ppm, ox, red);

        if (log_co_data(LOG_FILE, co_ppm) != 0) {
            fprintf(stderr, "Warning: failed to log CO data\n");
        }

        if (check_threshold(co_ppm)) {
            if (log_alert(ALERT_FILE, co_ppm) != 0) {
                fprintf(stderr, "Warning: failed to log alert\n");
            }
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_SEC, 0);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

