/*
 * Raspberry Pi 4 Model B — Dual IMP23ABSU Analog MEMS Microphone Logger
 *
 * Wiring:
 *   IMP23ABSU VDD  -> 3.3 V (Pin 1)
 *   IMP23ABSU GND  -> GND  (Pin 6)
 *   IMP23ABSU SDA  -> GPIO2 / BCM2 (Pin 3)
 *   IMP23ABSU SCL  -> GPIO3 / BCM3 (Pin 5)
 *   IMP23ABSU OUT  -> Analog signal (0–3.3 V, 0–1.65 V)
 *
 * Build:  gcc -O2 -Wall -o mic_logger mic_logger.c -lpigpio -lrt
 * Run:    sudo ./mic_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define MIC1_ADDR            0x50
#define MIC2_ADDR            0x51
#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define LOG_FILE             "audio_log.txt"
#define ERROR_VALUE          (-999.0f)
#define MAX_READ_RETRIES     3

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  init_gpio(void);
static int  init_i2c(int bus, int addr);
static float read_microphone(int handle);
static void log_data(float avg1, float avg2);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = init_i2c(I2C_BUS, MIC1_ADDR);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for microphone 1 (0x%02X). Exiting.\n", MIC1_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = init_i2c(I2C_BUS, MIC2_ADDR);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for microphone 2 (0x%02X). Exiting.\n", MIC2_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging microphone data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float avg1 = read_microphone(g_i2c_handle1);
        float avg2 = read_microphone(g_i2c_handle2);

        log_data(avg1, avg2);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_i2c(int bus, int addr)
{
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

/* ------------------------------------------------------------------ */
static float read_microphone(int handle)
{
    int raw = 0;
    int retries = 0;

    while (retries < MAX_READ_RETRIES) {
        raw = i2cReadWordData(handle, 0x00);
        if (raw >= 0) {
            break;
        }
        fprintf(stderr, "I2C read error (handle %d): %d, retry %d/%d\n",
                handle, raw, retries + 1, MAX_READ_RETRIES);
        retries++;
        gpioDelay(1000); /* 1 ms backoff */
    }

    if (raw < 0) {
        fprintf(stderr, "I2C read failed after %d retries (handle %d). Returning error value.\n",
                MAX_READ_RETRIES, handle);
        return ERROR_VALUE;
    }

    /* Convert raw 16-bit ADC value to dB (simplified linear mapping). */
    /* IMP23ABSU: 0 V -> 0 dB, 1.65 V -> 1.0 dB. */
    float voltage = (float)raw / 65535.0f * 3.3f;
    float level   = voltage * 1.0f; /* Linear approximation */

    return level;
}

/* ------------------------------------------------------------------ */
static void log_data(float avg1, float avg2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            avg1, avg2);

    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioTerminate();
}

