code:
/*
 * audio_monitor.c — Raspberry Pi 4 Model B
 *
 * Samples two ADMP401 MEMS microphones via an MCP3008 ADC on SPI0:
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   MCP3008 CH0  -> Mic 1 out
 *   MCP3008 CH1  -> Mic 2 out
 *   LED + 330 Ω -> GPIO27 (BCM) -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_monitor audio_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz — well within MCP3008 limits */
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE          SPI_MODE_0

#define MCP3008_CHANNELS  2U
#define NUM_SAMPLES       100U       /* 100 samples × 1 ms = 100 ms window */
#define SAMPLE_DELAY_US   1000U      /* 1 ms between samples */
#define LED_ON_TIME_MS    500U       /* LED on duration when threshold exceeded */
#define HIGH_THRESHOLD    1000.0f    /* RMS threshold in ADC counts */
#define LOG_FILE          "audio_events.csv"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Signal handler ---------------------------- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI helpers ------------------------------- */
static int spi_init(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out)
{
    if (channel >= MCP3008_CHANNELS) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static int log_data(const char *filename, float mic1_rms, float mic2_rms)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, mic1_rms, mic2_rms) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ----------------------------- RMS --------------------------------------- */
static float calculate_rms(const int16_t *samples, size_t n)
{
    double sum_sq = 0.0;
    for (size_t i = 0; i < n; i++)
        sum_sq += (double)samples[i] * samples[i];
    return (float)sqrt(sum_sq / (double)n);
}

/* ----------------------------- LED control ------------------------------- */
static int led_init(struct gpiod_chip *chip, struct gpiod_line *line)
{
    if (gpiod_line_request_output(line, "audio_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void led_set(struct gpiod_line *line, int on)
{
    if (gpiod_line_set_value(line, on ? 1 : 0) < 0)
        fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- SPI --- */
    int spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0)
        return EXIT_FAILURE;

    /* --- GPIO (chip 0, line 8 = CE0, line 9 = CE1, line 27 = LED) --- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, 27);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(27): %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (led_init(chip, led) < 0) {
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Open log file (write header if empty) --- */
    bool log_exists = (access(LOG_FILE, F_OK) == 0);
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        led_set(led, 0);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (!log_exists) {
        fprintf(log_fp, "timestamp,mic1_rms,mic2_rms\n");
        fflush(log_fp);
    }
    fclose(log_fp);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    int16_t mic1_samples[NUM_SAMPLES];
    int16_t mic2_samples[NUM_SAMPLES];

    while (g_running) {
        bool threshold_exceeded = false;

        for (size_t i = 0; i < NUM_SAMPLES && g_running; i++) {
            uint16_t v1 = 0, v2 = 0;
            if (mcp3008_read(spi_fd, 0, &v1) < 0) {
                fprintf(stderr, "Mic1 read failed at sample %zu\n", i);
                goto cleanup;
            }
            if (mcp3008_read(spi_fd, 1, &v2) < 0) {
                fprintf(stderr, "Mic2 read failed at sample %zu\n", i);
                goto cleanup;
            }
            mic1_samples[i] = (int16_t)v1;
            mic2_samples[i] = (int16_t)v2;
            usleep(SAMPLE_DELAY_US);
        }

        if (!g_running)
            break;

        float mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        float mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        if (log_data(LOG_FILE, mic1_rms, mic2_rms) < 0)
            fprintf(stderr, "Logging failed\n");

        if (mic1_rms > HIGH_THRESHOLD || mic2_rms > HIGH_THRESHOLD) {
            threshold_exceeded = true;
            printf("Threshold exceeded! Mic1: %.2f, Mic2: %.2f\n",
                   mic1_rms, mic2_rms);
        }

        if (threshold_exceeded) {
            led_set(led, 1);
            usleep(LED_ON_TIME_MS * 1000U);
            led_set(led, 0);
        }
    }

cleanup:
    led_set(led, 0);
