static int ads1115_read_raw(int fd, int16_t *raw_out)
{
    uint16_t val;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &val) < 0) return -1;

    /* Check OS bit (bit 15) to confirm conversion is complete */
    if (!(val & 0x8000)) {
        fprintf(stderr, "ADS1115 conversion not complete (OS=0)\n");
        return -1;
    }

    *raw_out = (int16_t)val;
    return 0;
}

/* ---- Convert raw ADC count to current (A) ---- */
static float raw_to_current(int16_t raw)
{
    return ((float)raw / ADS1115_PGA_4V_MAX_COUNT) * 4.096f;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_led_fd >= 0) {
        if (g_led_fd >= 0) {
            if (write(g_led_fd, "0", 1) < 0)
                perror("Failed to turn off LED during cleanup");
        }
        close(g_led_fd);
        g_led_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize ADS1115 ---- */
    if (ads1115_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed – sensor may be absent or bus error.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open LED GPIO ---- */
    g_led_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (g_led_fd < 0) {
        perror("open(/sys/class/gpio/gpio17/value)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize circular buffer ---- */
    CircularBuffer cb;
    cb_init(&cb);

    printf("Monitoring MLX91204 current sensor via ADS1115 (I2C 0x%02X)...\n", ADS1115_ADDR);
    printf("Sampling at %d Hz, threshold %.1f A. Press Ctrl+C to exit.\n",
           SAMPLE_RATE_HZ, CURRENT_THRESHOLD);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "Read error – continuing.\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        float current = raw_to_current(raw);
        cb_add(&cb, current);

        float avg = cb_average(&cb);
        printf("Current: %.4f A | Avg: %.4f A | Threshold: %.1f A\n",
               current, avg, CURRENT_THRESHOLD);

        /* Threshold check – active-high LED */
        if (avg > CURRENT_THRESHOLD) {
            const char on = '1';
            if (write(g_led_fd, &on, 1) < 0) perror("LED on");
        } else {
            const char off = '0';
            if (write(g_led_fd, &off, 1) < 0) perror("LED off");
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

