#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ATIME_2_4MS 0xFF
#define TCS34725_AGAIN_1X 0x00
#define TCS34725_ID_VALUE 0x44

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_COMMAND_BIT), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (cmd) for reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write_byte(fd, TCS34725_ATIME, TCS34725_ATIME_2_4MS) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_CONTROL, TCS34725_AGAIN_1X) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_word(fd, TCS34725_CDATA, clear) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_RDATA, red) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_GDATA, green) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_BDATA, blue) < 0) return -1;
    return 0;
}

static int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint16_t id = 0;
    if (i2c_read_word(i2c_fd, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Failed to read sensor ID register\n");
        close(i2c_fd);
        return 1;
    }
    if ((id & 0xFF) != TCS34725_ID_VALUE) {
        fprintf(stderr, "Sensor ID mismatch: got 0x%02X, expected 0x%02X\n", id & 0xFF, TCS34725_ID_VALUE);
        close(i2c_fd);
        return 1;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize TCS34725 sensor\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open color_log.csv: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
        fflush(log_file);
    }

    int consecutive_failures = 0;
    while (running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read(i2c_fd, &clear, &red, &green, &blue) == 0) {
            consecutive_failures = 0;
            if (log_data(log_file, clear, red, green, blue) < 0) {
                fprintf(stderr, "Logging failed, exiting\n");
                break;
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Read failed (%d consecutive)\n", consecutive_failures);
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Too many consecutive failures, exiting\n");
                break;
            }
        }
        sleep(1);
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    return 0;
}

