/*
 * MLX91211 Current Sensor Monitor — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0/GPIO8, SCLK/GPIO11, MOSI/GPIO10, MISO/GPIO9)
 *   - MLX91211 analog output -> MCP3008 CH0
 *   - Motor shutdown control -> GPIO17 (BCM)
 *
 * Behavior:
 *   Samples the current sensor once every second, converts the ADC value
 *   to amperes, writes a timestamped line to current_log.csv, and toggles
 *   the motor-enable line on GPIO17 when the measured current exceeds
 *   10.0 A.  Handles SIGINT/SIGTERM for clean shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        0

#define MCP3008_CHANNEL 0
#define OVERCURRENT_THRESHOLD 10.0f
#define MOTOR_GPIO_LINE 17
#define LOG_FILE        "current_log.csv"
#define SAMPLE_PERIOD_S 1
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_init(const char *device, uint32_t speed, uint8_t bits, uint8_t mode)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t  tx = mode;
    uint8_t  rx = 0;
    uint8_t  len = 1;
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)&tx;
    tr.rx_buf        = (unsigned long)&rx;
    tr.len           = len;
    tr.speed_hz      = speed;
    tr.bits_per_word = bits;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE (mode): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer, SPI mode 0, MSB-first).
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low nibble)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int spi_fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "mcp3008_read: invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI read attempt %d/%d failed: %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }

    fprintf(stderr, "SPI read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

static int gpio_init(struct gpiod_chip **chip, struct gpiod_line **line)
{
    *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!*chip) {
        *chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!*chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, MOTOR_GPIO_LINE);
    if (!*line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                MOTOR_GPIO_LINE, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(*line, "mlx91211-motor", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        *line = NULL;
        return -1;
    }

    return 0;
}

static void gpio_set(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "gpiod_line_set_value(%d): %s\n", value, strerror(errno));
    }
}

static void gpio_release(struct gpiod_chip *chip, struct gpiod_line *line)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_open(const char *path)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }

    /* Check if file is empty so we can write a header */
    off_t sz = lseek(fd, 0, SEEK_END);
    if (sz < 0) {
        fprintf(stderr, "lseek: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (sz == 0) {
        const char *header = "Timestamp,Current_A\n";
        if (write(fd, header, strlen(header)) < 0) {
            fprintf(stderr, "write(header): %s\n", strerror(errno));
            close(fd);
            return -1;
        }
    }

    if (lseek(fd, 0, SEEK_END) < 0) {
        fprintf(stderr, "lseek after header: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int log_write(int fd, const char *ts, float current)
{
    char line[128];
    int len = snprintf(line, sizeof(line), "%s,%.4f\n", ts, current);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "log_write: snprintf failed\n");
        return -1;
    }

    if (write(fd, line, (size_t)len) < 0) {
        fprintf(stderr, "write(log): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* SPI */
    int spi_fd = spi_init(SPI_DEVICE, SPI_SPEED_HZ, SPI_BITS, SPI_MODE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    /* GPIO */
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *motor_line = NULL;
    if (gpio_init(&gpio_chip, &motor_line) < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* Log file */
    int log_fd = log_open(LOG_FILE);
    if (log_fd < 0) {
        gpio_release(gpio_chip, motor_line);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int rc = EXIT_SUCCESS;

    while (g_running) {
        int adc = mcp3008_read(spi_fd, MCP3008_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* Convert 10-bit ADC to amperes (example calibration) */
        float current = (float)adc * 0.1f;

        /* Timestamp */
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "time(): %s\n", strerror(errno));
            sleep(SAMPLE_PERIOD_S);
            continue;
        }
        struct tm tmv;
        if (localtime_r(&now, &tmv) == NULL) {
            fprintf(stderr, "localtime_r failed\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }
        char ts[32];
        if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv) == 0) {
            fprintf(stderr, "strftime failed\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* Log */
        if (log_write(log_fd, ts, current) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        /* Overcurrent protection */
        if (current > OVERCURRENT_THRESHOLD) {
            fprintf(stderr, "OVERCURRENT: %.4f A — disabling motor\n", current);
            gpio_set(motor_line, 0);
            log_write(log_fd, ts, current);
            sleep(SAMPLE_PERIOD_S);
            gpio_set(motor_line, 1);
            fprintf(stderr, "Motor re-enabled\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    /* Cleanup */
    fprintf(stderr, "Shutting down...\n");
    gpio_set(motor_line, 0);
    gpio_release(gpio_chip, motor_line);
    close(spi_fd);
    close(log_fd);
    return rc;
}

