/*
 * MLX90817 absolute pressure logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   MLX90817 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   MLX90817 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   MLX90817 VDD  -> 3.3 V (pin 1)
 *   MLX90817 GND  -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o pressure_logger pressure_logger.c -li2c
 *
 * The MLX90817 is an absolute-pressure sensor family; the driver below
 * implements a minimal subset of the register map (pressure, temperature,
 * device ID) to read the absolute pressure.  The MLX90817 family is
 * proprietary and the register map is not publicly documented; this code
 * assumes a 16-bit register address space and a 16-bit data word.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MAX_READ_ERRORS 10        /* consecutive I2C read failures before abort */

/* MLX90817 register addresses (example values; adjust per your datasheet) */
#define MLX90817_REG_PRESSURE  0x00
#define MLX90817_REG_TEMP      0x02
#define MLX90817_REG_ID        0x0F

#define MLX90817_ID_VALUE      0x9081

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

/*
 * Write a 16-bit register address, then read `len` bytes.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_reg16(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c read reg 0x%02X: %s (got %zd of %zu)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/*
 * Write a 16-bit register address, then write `val` as a 16-bit big-endian
 * value, then read `len` bytes.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val, uint8_t *buf, size_t len)
{
    uint8_t wbuf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, wbuf, sizeof(wbuf)) != (ssize_t)sizeof(wbuf)) {
        fprintf(stderr, "i2c write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) < 0) {
        fprintf(stderr, "i2c read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_pressure(int fd, float *pressure_kpa)
{
    uint8_t id_buf[2];
    uint8_t data[2];

    /* Verify device identity */
    if (i2c_read_reg16(fd, MLX90817_REG_ID, id_buf, sizeof(id_buf)) < 0)
        return -1;

    uint16_t id = ((uint16_t)id_buf[0] << 8) | id_buf[1];
    if (id != MLX90817_ID_VALUE) {
        fprintf(stderr, "Sensor ID mismatch: got 0x%04X, expected 0x%04X\n",
                id, MLX90817_ID_VALUE);
        return -1;
    }

    /* Read pressure (example register; adjust per datasheet) */
    if (i2c_read_reg16(fd, MLX90817_REG_PRESSURE, data, sizeof(data)) < 0)
        return -1;

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *pressure_kpa = (float)raw / 100.0f;   /* adjust scaling factor */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }

    /* Write header only if file is empty */
    long pos = ftell(fp);
    if (pos == 0) {
        fprintf(fp, "timestamp,pressure_kPa\n");
        fflush(fp);
    }
    return 0;
}

static int log_write(FILE *fp, float pressure)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (!gmtime_r(&now, &tm_utc)) {
        fprintf(stderr, "gmtime_r: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (g_running) {
        float pressure;
        if (read_pressure(g_i2c_fd, &pressure) == 0) {
            consecutive_errors = 0;
            if (log_write(g_log_fp, pressure) < 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error #%d\n", consecutive_errors);
            if (consecutive_errors >= MAX_READ_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }

        sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

