code:
/*
 * Raspberry Pi 4 Model B — MLX90834 pressure monitor
 *
 * Hardware:
 *   - ADS1115 ADC on I2C bus 1 (SDA=GPIO2, SCL=GPIO3, ADDR=0x48)
 *   - MLX90834 pressure sensor on ADS1115 AIN0 (single-ended)
 *   - NTC thermistor on ADS1115 AIN1 (single-ended)
 *   - Warning LED on GPIO17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pressure_monitor pressure_monitor.c -lm
 *
 * The MLX90834 is a SENT-MEMS pressure sensor.  It outputs a digital
 * signal proportional to the applied pressure.  We read the sensor
 * via the ADS1115 ADC, which provides a 16-bit signed code that
 * corresponds to the sensor's digital output.  The ADS1115 is configured
 * for single-ended reads on AIN0 and AIN1, with a programmable gain
 * factor and a 128 SPS data rate.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ADS1115 register addresses ---- */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* ---- ADS1115 config bit fields ---- */
#define ADS1115_CFG_OS_BEGIN    0x8000  /* assert OS bit to start conversion */
#define ADS1115_CFG_MUX_AIN0   0x4000  /* single-ended AIN0 vs GND */
#define ADS1115_CFG_MUX_AIN1   0x5000  /* single-ended AIN1 vs GND */
#define ADS1115_CFG_PGA_4V     0x0200  /* PGA = ±4.096 V */
#define ADS1115_CFG_MODE_SS   0x0100  /* single-shot mode */
#define ADS1115_CFG_DR_128SPS 0x0080  /* 128 SPS data rate */
#define ADS1115_CFG_CQUE_NONE 0x0003  /* disable comparator */

/* ---- ADS1115 I2C address ---- */
#define ADS1115_I2C_ADDR 0x48

/* ---- GPIO pin definitions ---- */
#define GPIO_WARNING_LED 17

/* ---- Application constants ---- */
#define I2C_BUS            "/dev/i2c-1"
#define PRESSURE_THRESHOLD 105.0f   /* kPa */
#define SAMPLE_PERIOD_S    1.0
#define MAX_RETRIES        3
#define PRESSURE_SCALE     0.1f     /* kPa per LSB (example calibration) */
#define TEMP_SCALE         0.1f     /* °C per LSB (example calibration) */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write16: write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read16: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read16: read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADS1115                                                             */
/* ------------------------------------------------------------------ */
static int ads1115_init(int fd)
{
    /* Single-shot, AIN0 single-ended, PGA ±4.096 V, 128 SPS, comparator off */
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4V | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Allow the first conversion to complete at 128 SPS */
    usleep(10000);
    return 0;
}

static int ads1115_read_channel(int fd, uint16_t mux, float *out)
{
    uint16_t config;
    uint16_t raw;
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Build config for the requested channel */
        config = ADS1115_CFG_OS_BEGIN | mux | ADS1115_CFG_PGA_4V |
                 ADS1115_CFG_MODE_SS | ADS1115_CFG_DR_128SPS |
                 ADS1115_CFG_CQUE_NONE;

        if (i2c_write16(fd, ADS1115_REG_CONFIG, config) != 0) {
            usleep(10000);
            continue;
        }

        /* Wait for conversion to complete (~8 ms at 128 SPS) */
        usleep(10000);

        /* Read conversion result */
        if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) != 0) {
            usleep(10000);
            continue;
        }

        /* Convert raw 16-bit signed value to signed float */
        int16_t signed_val = (int16_t)raw;
        *out = (float)signed_val;
        return 0;
    }

    fprintf(stderr, "ads1115_read_channel: failed after %d retries (mux=0x%04X)\n",
            MAX_RETRIES, mux);
    return -1;
}

/* ------------------------------------------------------------------ */
/* GPIO                                                                */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "gpio_init: open /dev/gpiochip0 failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Request GPIO17 as output, initially LOW */
    if (gpioctl_request_line(fd, GPIO_WARNING_LED, GPIOCTL_REQUEST_LINE_OUTPUT,
                             "pressure_monitor") < 0) {
        fprintf(stderr, "gpio_init: request GPIO17 failed: %s\n",
                strerror(errno));
        close(fd);
        return -1;
    }

    if (gpioctl_set_line_value(fd, GPIO_WARNING_LED, 0) < 0) {
        fprintf(stderr, "gpio_init: set GPIO17 LOW failed: %s\n",
                strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static void gpio_set(int fd, int value)
{
    if (fd >= 0) {
        if (gpioctl_set_line_value(fd, GPIO_WARNING_LED, value) < 0)
            fprintf(stderr, "gpio_set: failed: %s\n", strerror(errno));
    }
}

static void gpio_cleanup(int fd)
{
    if (fd >= 0) {
        gpioctl_release_line(fd, GPIO_WARNING_LED);
        close(fd);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                ADS1115_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    /* ---- Initialize ADS1115 ---- */
    if (ads1115_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADS1115 initialization failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    /* ---- Initialize GPIO ---- */
    int gpio_fd = gpio_init();
    if (gpio_fd < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        goto cleanup;
    }

    printf("Pressure monitoring started.  Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float pressure = 0.0f;
        float temperature = 0.0f;
        bool pressure_ok = false;
        bool temp_ok = false;

        /* Read pressure channel (AIN0) */
        if (ads1115_read_channel(g_i2c_fd, ADS1115_CFG_MUX_AIN0, &pressure) == 0) {
            pressure_ok = true;
        } else {
            fprintf(stderr, "Pressure read failed; skipping cycle\n");
        }

        /* Read temperature channel (AIN1) */
        if (ads1115_read_channel(g_i2c_fd, ADS1115_CFG_MUX_AIN1, &temperature) == 0) {
            temp_ok = true;
        } else {
            fprintf(stderr, "Temperature read failed; skipping cycle\n");
        }

        if (pressure_ok && temp_ok) {
            float pressure_kPa = pressure * PRESSURE_SCALE;
            float temp_C = temperature * TEMP_SCALE;

            printf("Pressure: %.2f kPa, Temperature: %.2f C\n",
                   pressure_kPa, temp_C);

            if (pressure_kPa > PRESSURE_THRESHOLD) {
                gpio_set(gpio_fd, 1);
                printf("WARNING: Pressure exceeds %.1f kPa!\n",
                       PRESSURE_THRESHOLD);
            } else {
                gpio_set(gpio_fd, 0);
            }
        }

        /* Sleep for the sample period, but wake early on signal */
        struct timespec ts = { (long)SAMPLE_PERIOD_S, 0 };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running)
            ;
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    gpio_set(gpio_fd, 0);
    gpio_cleanup(gpio_fd);
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return ret;
}

