/*
 * MLX91209 Hall-effect current sensor monitor via MCP3008 ADC on Raspberry Pi 3 B+.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (BCM)
 *   MCP3008 DOUT -> GPIO9  (BCM)
 *   MCP3008 DIN  -> GPIO10 (BCM)
 *   MCP3008 CS   -> GPIO8  (BCM)
 *   MCP3008 CH0  -> MLX91209 analog output
 *   GPIO27       -> Motor shutdown control (active HIGH)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -lgpiod -lm
 *
 * Run:
 *   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_MODE          SPI_MODE_0
#define SPI_BITS_PER_WORD 8

#define MCP3008_CHANNEL   0          /* Single-ended channel 0 */
#define ADC_MAX_VALUE     1023       /* 10-bit ADC */

#define CURRENT_THRESHOLD_A  10.0f   /* Overcurrent threshold (A) */
#define SAMPLE_INTERVAL_MS   100     /* Sampling interval (ms) */

#define MOTOR_SHUTDOWN_PIN   27      /* BCM 27 */
#define GPIO_CHIP_NAME       "gpiochip0"

#define LOG_FILE_NAME        "current_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static FILE    *g_log_file = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_motor_line = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  spi_init(void);
static int  read_mcp3008(int channel, int *adc_value);
static float adc_to_current(int adc_value);
static void log_current(float current);
static void shutdown_motor(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- SPI --------------------------------------- */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int read_mcp3008(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* ----------------------------- Current ----------------------------------- */
static float adc_to_current(int adc_value)
{
    /*
     * MLX91209: 0 V -> 0 A, 4.5 V -> 10 A.
     * 10-bit ADC: 0..1023 counts, 0..4.096 V reference.
     * Linear: current = (adc / 1023.0) * 10.0
     */
    return ((float)adc_value / (float)ADC_MAX_VALUE) * CURRENT_THRESHOLD_A;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error: writing to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
    }
}

/* ----------------------------- Motor control ----------------------------- */
static void shutdown_motor(void)
{
    if (g_motor_line != NULL) {
        if (gpiod_line_set_value(g_motor_line, 1) < 0) {
            fprintf(stderr, "Error: failed to set motor line HIGH: %s\n", strerror(errno));
        } else {
            printf("Motor shutdown initiated (GPIO27 HIGH).\n");
        }
    }
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_motor_line != NULL) {
        gpiod_line_set_value(g_motor_line, 0);
        gpiod_line_release(g_motor_line);
        g_motor_line = NULL;
    }
    if (g_chip != NULL) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    int  adc_value = 0;
    float current = 0.0f;

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize SPI --- */
    if (spi_init() < 0) {
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    /* --- Initialize GPIO for motor shutdown --- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (g_chip == NULL) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name(%s): %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_motor_line = gpiod_chip_get_line(g_chip, MOTOR_SHUTDOWN_PIN);
    if (g_motor_line == NULL) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d): %s\n",
                MOTOR_SHUTDOWN_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_motor_line, "current_monitor", 0) < 0) {
        fprintf(stderr, "Error: gpiod_line_request_output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Logging to %s every %d ms.\n",
           LOG_FILE_NAME, SAMPLE_INTERVAL_MS);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        if (read_mcp3008(MCP3008_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Error: SPI read failed; continuing.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        current = adc_to_current(adc_value);
        log_current(current);

        if (current > CURRENT_THRESHOLD_A) {
            printf("OVERCURRENT DETECTED: %.2f A > %.2f A\n",
                   current, CURRENT_THRESHOLD_A);
            shutdown_motor();
            break;
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    /* --- Cleanup --- */
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

