/*
 * Raspberry Pi 4 Model B – MLX90830 pressure logger
 *
 * Hardware:
 *   - ADS1115 16-bit ADC on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *   - MLX90830 analog output wired to ADS1115 AIN0
 *   - MLX90830 VDD = 3.3 V, VOUT = 0–100 kPa
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pressure_logger pressure_logger.c -lm
 *
 * Run:
 *   ./pressure_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ADS1115 constants ---- */
#define ADS1115_I2C_ADDR        0x48
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15    OS       = 1  (begin single conversion)
 *   Bits 14:12 MUX      = 100 (AIN0 single-ended)
 *   Bits 11:9  PGA      = 001 (±4.096 V)
 *   Bit  8     MODE     = 1  (single-shot)
 *   Bits  7:5  DR       = 100 (128 SPS)
 *   Bit  4     COMP_MODE= 0
 *   Bit  3     COMP_POL = 0
 *   Bit  2     COMP_LAT = 0
 *   Bits 1:0   COMP_QUE = 11 (disable comparator)
 *
 * Binary: 1100 1000 0000 0000 = 0xC800
 */
#define ADS1115_CONFIG_BASE     0xC800

/* ---- Application constants ---- */
#define I2C_BUS                 "/dev/i2c-1"
#define LOG_FILE                "pressure_log.txt"
#define SAMPLE_PERIOD_US        1000000  /* 1 Hz */
#define MIN_PRESSURE_KPA        0.0
#define MAX_PRESSURE_KPA        100.0
#define ADC_FULL_SCALE          32767.0  /* 16-bit signed, ±4.096 V range */
#define ADC_VREF                4.096
#define ADC_PGA                 4.096    /* PGA = ±4.096 V */

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register (big-endian on the bus). */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_write_reg(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register (big-endian on the bus). */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg(0x%02X): write: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_read_reg(0x%02X): read: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single conversion on AIN0 and read the raw 16-bit result. */
static int ads1115_read_ain0(int fd, int16_t *raw_out)
{
    uint16_t config = ADS1115_CONFIG_BASE;
    uint16_t conv;
    int16_t  raw;

    /* Start a single-shot conversion on AIN0. */
    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for the conversion to complete (~8 ms at 128 SPS). */
    usleep(10000);

    /* Poll the OS bit (bit 15) until it reads 1. */
    for (int i = 0; i < 10; i++) {
        if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &conv) != 0)
            return -1;
        if (conv & 0x8000)
            break;
        usleep(1000);
    }
    if (!(conv & 0x8000)) {
        fprintf(stderr, "ads1115_read_ain0: conversion timeout\n");
        return -1;
    }

    /* Read the conversion result. */
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &conv) != 0)
        return -1;

    raw = (int16_t)conv;
    *raw_out = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC count to pressure (kPa). */
static double raw_to_pressure(int16_t raw)
{
    double voltage = ((double)raw / ADC_FULL_SCALE) * ADC_VREF;
    return (voltage / ADC_PGA) * 1000.0;  /* kPa */
}

/* ------------------------------------------------------------------ */
static void log_pressure(FILE *fp, double pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f kPa\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    int16_t raw;
    double pressure;

    /* ---- Signal handling ---- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                ADS1115_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stdout, "Pressure logger started. Logging to %s. Press Ctrl+C to stop.\n",
            LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (ads1115_read_ain0(g_i2c_fd, &raw) != 0) {
            fprintf(stderr, "ADC read error – skipping sample.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        pressure = raw_to_pressure(raw);

        if (pressure < MIN_PRESSURE_KPA || pressure > MAX_PRESSURE_KPA) {
            fprintf(stderr, "Pressure out of range: %.2f kPa (raw=%d)\n",
                    pressure, raw);
        } else {
            log_pressure(g_log_fp, pressure);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    fprintf(stdout, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

