    if (g_ce_line) gpiod_line_set_value(g_ce_line, 0);

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | ADC_CHANNEL) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = { 0 };
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        if (g_ce_line) gpiod_line_set_value(g_ce_line, 1);
        return -1;
    }

    if (g_ce_line) gpiod_line_set_value(g_ce_line, 1);

    *adc_value = ((uint16_t)(rx[1] & 0x0F) << 8) | rx[2];
    return 0;
}

static float adc_to_celsius(uint16_t adc_value)
{
    float voltage = ((float)adc_value / ADC_RESOLUTION) * ADC_VREF;
    return (voltage - 0.5f) * 100.0f;
}

static int log_temperature(float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_spi_fd >= 0) { close(g_spi_fd); g_spi_fd = -1; }
    if (g_ce_line) { gpiod_line_release(g_ce_line); g_ce_line = NULL; }
    if (g_chip) { gpiod_chip_close(g_chip); g_chip = NULL; }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) return 1;
    if (gpio_init() < 0) { cleanup(); return 1; }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,temperature_celsius\n");
        fflush(g_log_fp);
    }

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t adc_value = 0;
        if (read_adc(&adc_value) < 0) {
            fprintf(stderr, "ADC read error; retrying in %d s.\n", SAMPLE_PERIOD_S);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);

        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(stderr, "Warning: temperature %.2f C out of range [-40, 125] - sensor absent or wiring fault?\n", temperature);
        } else if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Logging error.\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return 0;
}

