/*
 * ADXL335 accelerometer reader via MCP3008 ADC on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   ADXL335 VCC -> 3.3 V (Pin 1)
 *   ADXL335 GND -> GND  (Pin 9)
 *   ADXL335 X   -> MCP3008 CH0
 *   ADXL335 Y   -> MCP3008 CH1
 *   ADXL335 Z   -> MCP3008 CH2
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF-> 3.3 V
 *   MCP3008 AGND-> GND
 *   MCP3008 DGND-> GND
 *   MCP3008 CLK -> SPI0 SCLK (GPIO11 / Pin 23)
 *   MCP3008 DOUT-> SPI0 MISO (GPIO9  / Pin 21)
 *   MCP3008 DIN -> SPI0 MOSI (GPIO10 / Pin 19)
 *   MCP3008 CS  -> SPI0 CE0  (GPIO8  / Pin 24)
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_detect impact_detect.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_MODE          SPI_MODE_0
#define SPI_BITS_PER_WORD 8

#define ADC_CHANNEL_X     0
#define ADC_CHANNEL_Y     1
#define ADC_CHANNEL_Z     2

#define IMPACT_THRESHOLD  1000.0f    /* raw ADC count above which an impact is flagged */
#define SAMPLE_RATE_HZ    100.0f
#define SAMPLE_PERIOD_US  (1000000U / (uint32_t)SAMPLE_RATE_HZ)

#define LOG_FILE          "impact_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  spi_init(void);
static int  spi_read_channel(uint8_t channel, uint16_t *value);
static void log_data(uint16_t x, uint16_t y, uint16_t z);
static void log_impact(uint16_t x, uint16_t y, uint16_t z);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- SPI --------------------------------------- */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success and stores the 10-bit value in *value.
 * Returns -1 on SPI transfer failure or invalid data.
 */
static int spi_read_channel(uint8_t channel, uint16_t *value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }
    if (value == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result:
     *   rx[1] bits 1..0  -> upper 2 data bits
     *   rx[2]           -> lower 8 data bits
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;  /* we manage CS manually */

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed on channel %u: %s\n",
                channel, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    if (raw > 1023) {
        fprintf(stderr, "ADC channel %u returned out-of-range value %u\n",
                channel, raw);
        return -1;
    }

    *value = raw;
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(uint16_t x, uint16_t y, uint16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    fprintf(g_log_fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            (unsigned)x, (unsigned)y, (unsigned)z);
    fflush(g_log_fp);
}

static void log_impact(uint16_t x, uint16_t y, uint16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    fprintf(g_log_fp, "%04d-%02d-%02d %02d:%02d:%02d,IMPACT DETECTED,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            (unsigned)x, (unsigned)y, (unsigned)z);
    fflush(g_log_fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        uint16_t x = 0, y = 0, z = 0;
        int err = 0;

        if (spi_read_channel(ADC_CHANNEL_X, &x) < 0) err = 1;
        if (spi_read_channel(ADC_CHANNEL_Y, &y) < 0) err = 1;
        if (spi_read_channel(ADC_CHANNEL_Z, &z) < 0) err = 1;

        if (err) {
            fprintf(stderr, "ADC read error — continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(x, y, z);

        if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
            log_impact(x, y, z);
            printf("IMPACT DETECTED (X=%u Y=%u Z=%u)\n", (unsigned)x, (unsigned)y, (unsigned)z);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

