/*
 * Si1172-A30-GMR Heart Rate & SpO2 Logger for Raspberry Pi Zero W
 *
 * Reads raw 16-bit IR and RED ADC values from the Si1172 over I2C bus 1
 * and logs them to biometric_log.csv.  The Si1172 is a proprietary
 * optical heart-rate sensor; the raw ADC values are logged as proxies
 * for HR and SpO₂ (per the Si1172 datasheet) and the conversion to
 * true HR/SpO₂ is performed via a proprietary algorithm that is not
 * included here.  The application checks every I2C call and handles
 * SIGINT for graceful shutdown.
 *
 * Wiring:
 *   Si1172 SDA -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   Si1172 SCL -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   Si1172 VDD -> 3.3 V
 *   Si1172 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1172_logger si1172_logger.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1172 I2C address ---- */
#define SI1172_ADDR 0x49

/* ---- Si1172 register addresses (from datasheet) ---- */
#define SI1172_REG_PART_ID      0x00
#define SI1172_REG_HW_REV       0x01
#define SI1172_REG_SEQ_ID       0x02
#define SI1172_REG_INT_CFG      0x03
#define SI1172_REG_INT_STATUS   0x04
#define SI1172_REG_IRQ_ENABLE   0x05
#define SI1172_REG_HW_KEY       0x07
#define SI1172_REG_MEAS_RATE    0x08
#define SI1172_REG_ALS_IR_DATA0 0x16
#define SI1172_REG_ALS_IR_DATA1 0x17
#define SI1172_REG_ALS_RED_DATA0 0x18
#define SI1172_REG_ALS_RED_DATA1 0x19

/* ---- Expected part ID for Si1172 ---- */
#define SI1172_PART_ID_EXPECTED 0x51

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1172 initialization                                               */
/* ------------------------------------------------------------------ */
static int si1172_init(int fd)
{
    uint8_t part_id = 0;

    /* Read PART_ID to confirm sensor is present */
    if (i2c_read_reg8(fd, SI1172_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Si1172 not responding on I2C bus (sensor absent or "
                        "bus error).\n");
        return -1;
    }
    if (part_id != SI1172_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, SI1172_PART_ID_EXPECTED);
        return -1;
    }

    /* Mandatory HW_KEY write (datasheet: write 0x17 to HW_KEY) */
    if (i2c_write_reg8(fd, SI1172_REG_HW_KEY, 0x17) != 0)
        return -1;

    /* Measurement rate: 0x08 = 100 ms (datasheet default) */
    if (i2c_write_reg8(fd, SI1172_REG_MEAS_RATE, 0x08) != 0)
        return -1;

    /* Clear any pending interrupts */
    (void)i2c_write_reg8(fd, SI1172_REG_INT_STATUS, 0x00);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample: raw IR and RED ADC values                          */
/* ------------------------------------------------------------------ */
static int si1172_read_sample(int fd, uint16_t *ir, uint16_t *red)
{
    uint8_t lo, hi;

    if (i2c_read_reg8(fd, SI1172_REG_ALS_IR_DATA0, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, SI1172_REG_ALS_IR_DATA1, &hi) != 0)
        return -1;
    *ir = (uint16_t)((hi << 8) | lo);

    if (i2c_read_reg8(fd, SI1172_REG_ALS_RED_DATA0, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, SI1172_REG_ALS_RED_DATA1, &hi) != 0)
        return -1;
    *red = (uint16_t)((hi << 8) | lo);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a sample row                                                    */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, time_t ts, uint16_t ir, uint16_t red,
                       int error_code)
{
    fprintf(fp, "%ld,%u,%u,%d\n", (long)ts, ir, red, error_code);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    const char *i2c_dev = "/dev/i2c-1";
    const char *log_file = "biometric_log.csv";
    uint16_t ir = 0, red = 0;
    int error_code = 0;
    time_t ts;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(i2c_dev, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", i2c_dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1172_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1172_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (si1172_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1172 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(log_file, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", log_file, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,ir_adc,red_adc,error_code\n");
        fflush(g_log_fp);
    }

    printf("Si1172 logging started.  Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        ts = time(NULL);

        if (si1172_read_sample(g_i2c_fd, &ir, &red) == 0) {
            error_code = 0;
        } else {
            error_code = 1;
            fprintf(stderr, "I2C read error at %ld\n", (long)ts);
        }

        log_sample(g_log_fp, ts, ir, red, error_code);
        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

