/*
 * Raspberry Pi 4 Model B — Honeywell SpiroQuant A+ ES1-005 Mass Flow Sensor
 * SPI0 / MCP3008 ADC, channel 0 (CE0 / GPIO8), 1 MHz, mode 0
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lm
 * Run:    ./flow_monitor   (requires write permission to ./flow_log.csv)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* MCP3008 channel 0 (CE0 / GPIO8)          */
#define SPI_SPEED      1000000    /* 1 MHz                                      */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words        */
#define ADC_MAX        1023       /* 10-bit ADC                                 */
#define FLOW_MIN       0.0f       /* L/min                                      */
#define FLOW_MAX       5.0f       /* L/min                                      */
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_PERIOD  1.0        /* seconds between samples                   */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE  *g_log = NULL;
static int    g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  initialize(void);
static int  read_adc(int channel, int *adc_value);
static float convert_to_flow_rate(int adc_value);
static void log_flow_rate(float flow_rate);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Initialization ----------------------------- */
static int initialize(void)
{
    /* --- pigpio library -------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    /* --- SPI device ------------------------------------------------------ */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[ERROR] spiOpen failed (channel %d, %d Hz, flags %d): %s\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, pigpio_error(g_spi_handle));
        gpioTerminate();
        return -1;
    }

    /* --- Log file -------------------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log) == 0) {
        fprintf(g_log, "timestamp,flow_rate\n");
        fflush(g_log);
    }

    return 0;
}

/* ----------------------------- ADC read ---------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_adc(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "[ERROR] Invalid ADC channel %d (must be 0-7).\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret < 0) {
        fprintf(stderr, "[ERROR] spiXfer failed: %s\n", pigpio_error(ret));
        return -1;
    }
    if (ret != 3) {
        fprintf(stderr, "[ERROR] spiXfer short transfer: %d bytes.\n", ret);
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

/* ----------------------------- Flow conversion ---------------------------- */
static float convert_to_flow_rate(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    /* Linear approximation: 0 V -> 0 L/min, 3.3 V -> 5 L/min */
    return ((float)adc_value / (float)ADC_MAX) * (FLOW_MAX - FLOW_MIN);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_flow_rate(float flow_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[ERROR] clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate);
    fflush(g_log);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        int adc_value = 0;

        if (read_adc(SPI_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "[WARN] ADC read failed; skipping sample.\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Sensor-absent / fault detection */
        if (adc_value == 0) {
            fprintf(stderr, "[WARN] ADC reads 0 — sensor absent or wiring fault.\n");
        } else if (adc_value == ADC_MAX) {
            fprintf(stderr, "[WARN] ADC saturated — sensor absent or wiring fault.\n");
        }

        float flow_rate = convert_to_flow_rate(adc_value);

        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "[WARN] Flow rate %.2f L/min out of range [%.1f, %.1f].\n",
                    flow_rate, FLOW_MIN, FLOW_MAX);
        } else {
            log_flow_rate(flow_rate);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

