/*
 * Raspberry Pi Zero W – TDK ICP-10125 I2C Temperature & Pressure Logger
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   ICP-10125 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10125_logger icp10125_logger.c
 * Run:    ./icp10125_logger   (requires r/w access to /dev/i2c-1)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ICP-10125 constants (per datasheet) ---- */
#define I2C_BUS          "/dev/i2c-1"
#define ICP10125_ADDR    0x70          /* 7-bit I2C address (ADDR pin tied to GND) */

/* Measurement command (high-precision mode, 1.5 ms conversion) */
#define CMD_MEASURE_HP   0x36

/* Conversion time for high-precision mode (1.5 ms) */
#define CONV_TIME_MS     1.5

/* Sampling interval */
#define SAMPLE_INTERVAL  5

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits and resources are freed */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Millisecond sleep (POSIX.1-2008)                                  */
/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and claim the sensor's address                     */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "[ERROR] open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* Write a single command byte to the sensor                           */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write(0x%02X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the sensor                            */
/* ------------------------------------------------------------------ */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "[ERROR] I2C read: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "[ERROR] I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-4 polynomial 0x13, init 0x00 (per ICP-10125 datasheet)          */
/* ------------------------------------------------------------------ */
static uint8_t crc4(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x08)
                crc = (uint8_t)((crc << 1) ^ 0x13);
            else
                crc = (uint8_t)(crc << 1);
            crc &= 0x0F;
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one measurement from the ICP-10125                             */
/* Returns 0 on success, -1 on error.                                  */
/* pressure_pa, temp_c are set to the calibrated values.               */
/* ------------------------------------------------------------------ */
static int read_icp10125(int fd, float *pressure_pa, float *temp_c)
{
    uint8_t data[6];

    /* Issue high-precision measurement command */
    if (i2c_write_cmd(fd, CMD_MEASURE_HP) < 0)
        return -1;

    /* Wait for conversion to complete */
    sleep_ms((unsigned int)CONV_TIME_MS);

    /* Read 6 bytes: P_MSB, P_LSB, P_CRC, T_MSB, T_LSB, T_CRC */
    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    /* CRC check on pressure data */
    if (crc4(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }

    /* CRC check on temperature data */
    if (crc4(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    /* Assemble 16-bit raw values (big-endian) */
    uint16_t p_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t t_raw = ((uint16_t)data[3] << 8) | data[4];

    /* ---- Calibration (per datasheet) ---- */
    /* Scale factors from datasheet (high-precision mode) */
    const float P_SCALE = 0.002f;   /* 2 Pa per LSB */
    const float T_SCALE = 0.002f;   /* 2 °C per LSB */

    *pressure_pa = (float)p_raw * P_SCALE;
    *temp_c      = (float)t_raw * T_SCALE;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to the CSV file and stdout                            */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float pressure_pa, float temp_c)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temp_c);
    fflush(fp);

    printf("%s  Pressure: %.2f Pa  Temperature: %.2f °C\n",
           ts, pressure_pa, temp_c);
}

/* ------------------------------------------------------------------ */
/* Cleanup – close I2C and CSV file                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus and claim the sensor's address */
    g_i2c_fd = i2c_open(I2C_BUS, ICP10125_ADDR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] Cannot open I2C bus %s – sensor may be absent.\n",
                I2C_BUS);
        return EXIT_FAILURE;
    }

    /* Open CSV log file in append mode */
    g_log_fp = fopen("environmental_data.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "[ERROR] fopen(environmental_data.csv): %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,pressure_pa,temperature_c\n");
        fflush(g_log_fp);
    }

    printf("ICP-10125 logger started.  Bus=%s  Addr=0x%02X  Interval=%d s\n",
           I2C_BUS, ICP10125_ADDR, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float pressure_pa = 0.0f;
        float temp_c      = 0.0f;

        if (read_icp10125(g_i2c_fd, &pressure_pa, &temp_c) == 0) {
            log_data(g_log_fp, pressure_pa, temp_c);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed – will retry in %d s.\n",
                    SAMPLE_INTERVAL);
        }

        /* Sleep for the sampling interval, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep_ms(1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

