#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNELS 8
#define NUM_MICROPHONES 2
#define SAMPLE_RATE 1000
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel >= MCP3008_CHANNELS) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_audio_samples(int spi_handle, int *samples, int num_microphones) {
    for (int i = 0; i < num_microphones; i++) {
        int raw = read_mcp3008(spi_handle, i);
        if (raw < 0) {
            fprintf(stderr, "Error: Failed to read from microphone %d\n", i);
            return -1;
        }
        samples[i] = raw;
    }
    return 0;
}

static void apply_noise_cancellation(int *samples, int num_microphones, int gain) {
    if (gain <= 0) return;

    int avg = (samples[0] + samples[1]) / 2;
    for (int i = 0; i < num_microphones; i++) {
        samples[i] -= (avg * gain) / 100;
    }
}

static void print_audio_samples(int *samples, int num_microphones) {
    for (int i = 0; i < num_microphones; i++) {
        printf("%d", samples[i]);
        if (i < num_microphones - 1) {
            printf(",");
        }
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return 1;
    }

    int gain1 = atoi(argv[1]);
    int gain2 = atoi(argv[2]);

    if (gain1 < 0 || gain1 > 100 || gain2 < 0 || gain2 > 100) {
        fprintf(stderr, "Error: Gain values must be between 0 and 100\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int samples[NUM_MICROPHONES];

    while (running) {
        if (read_audio_samples(spi_handle, samples, NUM_MICROPHONES) == 0) {
            apply_noise_cancellation(samples, NUM_MICROPHONES, gain1);
            print_audio_samples(samples, NUM_MICROPHONES);
        } else {
            fprintf(stderr, "Error: Failed to read audio samples\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

