/*
 * Raspberry Pi 4 Model B — Vegetronix VH400 soil moisture logger
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 CE0 (CE0 = GPIO8, MOSI=GPIO10, MISO=GPIO9, SCLK=GPIO11)
 *   - VH400 analog output -> MCP3008 CH0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o moisture_logger moisture_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./moisture_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz — well within MCP3008 3.3–5 V limit */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD  60         /* seconds between readings */
#define LOG_FILE       "moisture_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;            /* let main loop exit cleanly */
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (Mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] low 2 bits + rx[2] 8 bits → 10-bit result
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01,
                            (unsigned char)((0x08 | channel) << 4),
                            0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

/* ------------------------------------------------------------------ */
/* ISO 8601 UTC timestamp                                              */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *timestamp, int adc_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, adc_value) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VH400 soil moisture logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; retrying next cycle.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        char timestamp[32];
        if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Failed to generate timestamp; skipping log.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_data(timestamp, adc_value) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        printf("%s  ADC CH%d = %d\n", timestamp, ADC_CHANNEL, adc_value);

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

