#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define LED_GPIO       17
#define WATER_HIGH     75
#define WATER_LOW      70
#define SAMPLE_US      100000
#define LOOP_US        5000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((channel & 0x07) << 4 | 0x80),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_percentage(int adc_value) {
    return (float)adc_value / 1023.0f * 100.0f;
}

static void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

static void log_water_level(float percentage) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n",
            timestamp, percentage);
    fflush(json_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    json_file = fopen("water_levels.json", "w");
    if (json_file == NULL) {
        perror("Failed to open water_levels.json");
        spiClose(spi_handle);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fputs("[\n", json_file);

    int led_state = 0;

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float percentage = calculate_percentage(adc_value);

        if (percentage > WATER_HIGH && led_state == 0) {
            control_led(1);
            led_state = 1;
        } else if (percentage < WATER_LOW && led_state == 1) {
            control_led(0);
            led_state = 0;
        }

        log_water_level(percentage);

        gpioDelay(LOOP_US);
    }

    fprintf(stderr, "\nShutting down...\n");

    fseek(json_file, -2, SEEK_CUR);
    fputs("]\n", json_file);
    fclose(json_file);
    json_file = NULL;

    spiClose(spi_handle);
    spi_handle = -1;

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

