#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <stdint.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_CALIBRATION 300
#define DEFAULT_MAX_CALIBRATION 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_EMAIL_RECIPIENT ""
#define DEFAULT_MSMTP_CONFIG_FILE ""
#define DEFAULT_SPI_SPEED 500000
#define DEFAULT_SPI_BITS_PER_WORD 8
#define DEFAULT_SPI_MODE 0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(int channel, int speed, int bits_per_word, int mode) {
    char spi_device[32];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev0.%d", channel);

    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", spi_device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx_buf[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = DEFAULT_SPI_SPEED,
        .bits_per_word = DEFAULT_SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

static int calculate_moisture_percentage(int adc_value, int min_calibration, int max_calibration) {
    if (max_calibration <= min_calibration) {
        fprintf(stderr, "Invalid calibration range: max_calibration (%d) <= min_calibration (%d)\n", max_calibration, min_calibration);
        return -1;
    }

    int moisture = (int)(((float)(adc_value - min_calibration) / (float)(max_calibration - min_calibration)) * 100.0);
    if (moisture < 0) moisture = 0;
    if (moisture > 100) moisture = 100;
    return moisture;
}

static int log_data(const char *filename, int moisture_percentage) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

