static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device '%s': %s\n",
                device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, uint8_t channel, uint16_t *adc_value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u (must be 0-7)\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: 0x80 | (channel << 4)  (single-ended + channel select)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   Byte 1: bits 7..2 undefined, bit 1 = null bit, bit 0 = MSB of result
     *   Byte 2: bits 7..0 = LSB of result
     */
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float calculate_moisture_percentage(uint16_t adc_value)
{
    /*
     * DFRobot Soil Moisture Sensor v2.0:
     *   ADC value ~700-1023  -> dry soil
     *   ADC value ~200-600   -> wet soil
     *   ADC value ~0-200     -> very wet soil (saturated)
     */
    if (adc_value > 1023) adc_value = 1023;
    if (adc_value < 0)   adc_value = 0;

    float pct = 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
    if (pct < 0.0f)   pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor (MCP3008 ADC) - Reading ADC0 every %d seconds\n",
           SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(spi_fd, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Error reading ADC channel %u. Retrying in %d seconds...\n",
                    ADC_CHANNEL, SAMPLE_PERIOD_S);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float moisture_pct = calculate_moisture_percentage(adc_value);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_buf[32];
        strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("[%s] ADC0: %4u  Moisture: %5.1f%%\n",
               time_buf, adc_value, moisture_pct);
        fflush(stdout);

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    if (close(spi_fd) < 0) {
        fprintf(stderr, "Warning: error closing SPI device: %s\n", strerror(errno));
    }
    return EXIT_SUCCESS;
}

