/*
 * MLX90823 pressure sensor reader via MCP3008 ADC on Raspberry Pi 4.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO,  Pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI,  Pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,   Pin 24)
 *   MCP3008 CH0  -> MLX90823 VOUT
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90823_reader mlx90823_reader.c
 *
 * Run:
 *   ./mlx90823_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz – well within MCP3008 limits */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX         1023       /* 10-bit ADC */
#define ADC_VREF        3.3f       /* MCP3008 VREF tied to 3.3 V */

#define SAMPLE_PERIOD_S 1          /* seconds between readings */
#define MAX_CONSECUTIVE_ERRORS 10

/* ------------------------------------------------------------------ */
/* Globals for signal-safe cleanup                                    */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* ------------------------------------------------------------------ */
/* Sensor logic                                                        */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX) * ADC_VREF;
}

/*
 * Detect sensor-absent / wiring-fault conditions.
 *   ADC stuck at 0 V  -> sensor absent or wiring fault
 *   ADC stuck at 3.3 V -> sensor shorted to VREF
 */
static bool is_sensor_absent(int adc_value)
{
    return (adc_value == 0) || (adc_value == ADC_MAX);
}

static void log_reading(float voltage)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    printf("[%s] MLX90823 Voltage: %.4f V (ADC: %d)\n", ts, voltage, adc_value);
    fflush(stdout);
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
