        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        return EXIT_FAILURE;
    }

    if (spi_init(&spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Data Acquisition\n");
    printf("SPI: %s | Mode: %d | Speed: %d Hz | Channel: %d\n",
           SPI_DEVICE, SPI_MODE, SPI_SPEED_HZ, MCP3008_CHANNEL);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = 0;

        if (read_mcp3008(spi_fd, MCP3008_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            break;
        }

        if (adc_value == 0 || adc_value == 1023) {
