        }

        log_data(adc_value);

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

    return ret;
}

