/*
 * Raspberry Pi 3 Model B+ — Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 / GPIO8), 1 MHz, mode 0
 *   - VH400 analog output -> MCP3008 CH0 (single-ended)
 *   - 12 V water pump via relay on GPIO17 (BCM, active-high)
 *
 * Behaviour:
 *   - Samples every 5 s (driver library timer)
 *   - Turns pump ON  when moisture < 300, OFF when moisture > 600
 *   - Logs every reading + pump state change to a 20-entry circular buffer
 *   - Graceful shutdown on SIGINT / SIGTERM
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* SPI0 CE0 (BCM 8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* mode 0, active-low CE */

#define PUMP_GPIO        17         /* BCM 17 */
#define PUMP_ON          1
#define PUMP_OFF         0

#define MOISTURE_LOW     300        /* turn pump ON  below this */
#define MOISTURE_HIGH    600        /* turn pump OFF above this */

#define BUFFER_SIZE      20
#define SAMPLE_PERIOD_S  5          /* seconds between samples */

/* ----------------------------- Data Structures --------------------------- */

typedef struct {
    time_t timestamp;
    int    moisture;
    int    pump_state;
} LogEntry;

typedef struct {
    LogEntry entries[BUFFER_SIZE];
    int      head;   /* next write slot */
    int      count;  /* number of valid entries (<= BUFFER_SIZE) */
} CircularBuffer;

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static int      g_pump_state = PUMP_OFF;
static CircularBuffer g_log_buffer;

/* ----------------------------- Prototypes -------------------------------- */

static void  signal_handler(int sig);
static int   read_mcp3008(int channel);
static void  control_pump(int moisture);
static void  log_data(int moisture, int pump_state);
static void  print_buffer(void);
static void  timer_callback(void *userdata);

/* ----------------------------- Signal Handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MCP3008 Read ------------------------------ */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low 8 bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d): %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

/* ----------------------------- Pump Control ------------------------------ */

static void control_pump(int moisture)
{
    int new_state = (moisture < MOISTURE_LOW) ? PUMP_ON : PUMP_OFF;

    if (new_state != g_pump_state) {
        int rc = gpioWrite(PUMP_GPIO, new_state);
        if (rc < 0) {
            fprintf(stderr, "gpioWrite(%d) failed: %s\n",
                    PUMP_GPIO, pigpio_error(rc));
        } else {
            g_pump_state = new_state;
            printf("Pump %s\n", g_pump_state ? "ON" : "OFF");
        }
    }
}

/* ----------------------------- Logging ----------------------------------- */

static void log_data(int moisture, int pump_state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    g_log_buffer.entries[g_log_buffer.head].timestamp = now;
    g_log_buffer.entries[g_log_buffer.head].moisture   = moisture;
    g_log_buffer.entries[g_log_buffer.head].pump_state = pump_state;

    g_log_buffer.head = (g_log_buffer.head + 1) % BUFFER_SIZE;
    if (g_log_buffer.count < BUFFER_SIZE)
        g_log_buffer.count++;
}

static void print_buffer(void)
{
    printf("\n--- Log Buffer (%d entries) ---\n", g_log_buffer.count);
    for (int i = 0; i < g_log_buffer.count; i++) {
        int idx = (g_log_buffer.head - g_log_buffer.count + i + BUFFER_SIZE)
                  % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        if (localtime_r(&g_log_buffer.entries[idx].timestamp, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            strncpy(ts, "???", sizeof(ts));
            ts[sizeof(ts) - 1] = '\0';
        }
        printf("[%s] Moisture: %4d  Pump: %s\n",
               ts,
               g_log_buffer.entries[idx].moisture,
               g_log_buffer.entries[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

/* ----------------------------- Timer Callback ---------------------------- */

static void timer_callback(void *userdata)
{
    (void)userdata;

    int moisture = read_mcp3008(0);
    if (moisture < 0) {
        fprintf(stderr, "Sensor read failed; skipping cycle.\n");
        return;
    }

    control_pump(moisture);
    log_data(moisture, g_pump_state);
    print_buffer();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "gpioInitialise() failed: %s\n", pigpio_error(rc));
        return EXIT_FAILURE;
    }

