/*
 * MAX30102 Pulse Oximeter Monitor for Raspberry Pi Zero W
 *
 * Build:  gcc -O2 -Wall -Wextra -o max30102_monitor max30102_monitor.c -li2c
 * Run:    sudo ./max30102_monitor   (root needed for /dev/i2c-1 access)
 *
 * The MAX30102 is configured for SpO2 and heart-rate sampling once per second.
 * Alerts below 95% SpO2 or above 100 BPM are logged to health_log.txt with
 * ISO-8601 timestamps.  SIGINT/SIGTERM triggers clean shutdown.
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MAX30102 register definitions ---- */
#define MAX30102_I2C_ADDR        0x57
#define MAX30102_REG_INTR_STATUS_1 0x00
#define MAX30102_REG_INTR_STATUS_2 0x01
#define MAX30102_REG_INTR_ENABLE_1 0x02
#define MAX30102_REG_FIFO_WR_PTR  0x04
#define MAX30102_REG_OVF_COUNTER  0x05
#define MAX30102_REG_FIFO_RD_PTR  0x06
#define MAX30102_REG_FIFO_DATA    0x07
#define MAX30102_REG_FIFO_CONFIG  0x08
#define MAX30102_REG_MODE_CONFIG  0x09
#define MAX30102_REG_SPO2_CONFIG  0x0A
#define MAX30102_REG_LED1_PA      0x0C
#define MAX30102_REG_LED2_PA      0x0D
#define MAX30102_REG_PART_ID      0xFF

#define MAX30102_PART_ID          0x15
#define MAX30102_MODE_SPO2_HR     0x03
#define MAX30102_SPO2_ADC_RGE     0x20
#define MAX30102_SPO2_SR_100      0x03
#define MAX30102_FIFO_TEMP_OFF    0x00
#define MAX30102_FIFO_A_FULL_4    0x0F
#define MAX30102_INTR_MASK        0x00
#define MAX30102_LED1_RED_0_6     0x0F
#define MAX30102_LED2_IR_0_6      0x0F

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "health_log.txt"
#define SAMPLE_PERIOD  1   /* seconds */
#define SPO2_THRESHOLD 95.0f
#define HR_THRESHOLD   100.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int max30102_init(int fd)
{
    uint8_t part_id = 0;

    if (i2c_read_reg8(fd, MAX30102_REG_PART_ID, &part_id) != 0)
        return -1;

    if (part_id != MAX30102_PART_ID) {
        fprintf(stderr,
                "MAX30102 Part ID mismatch: got 0x%02X, expected 0x%02X\n",
                part_id, MAX30102_PART_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, MAX30102_REG_INTR_ENABLE_1, MAX30102_INTR_MASK) != 0)
        return -1;
    if (i2c_write_reg8(fd, MAX30102_REG_FIFO_WR_PTR, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, MAX30102_REG_OVF_COUNTER, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, MAX30102_REG_FIFO_RD_PTR, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, MAX30102_REG_FIFO_CONFIG,
                       MAX30102_FIFO_TEMP_OFF | MAX30102_FIFO_A_FULL_4) != 0)
        return -1;
    if (i2c_write_reg8(fd, MAX30102_REG_MODE_CONFIG,
                       MAX30102_MODE_SPO2_HR) != 0)
        return -1;
    if (i2c_write_reg8(fd, MAX30102_REG_SPO2_CONFIG,
                       MAX30102_SPO2_ADC_RGE | MAX30102_SPO2_SR_100) != 0)
        return -1;
    if (i2c_write_reg8(fd, MAX30102_REG_LED1_PA, MAX30102_LED1_RED_0_6) != 0)
        return -1;
    if (i2c_write_reg8(fd, MAX30102_REG_LED2_PA, MAX30102_LED2_IR_0_6) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_fifo_sample(int fd, uint32_t *red, uint32_t *ir)
{
    uint8_t wr_ptr = 0, rd_ptr = 0, ovf = 0;
    uint8_t data[6];

    if (i2c_read_reg8(fd, MAX30102_REG_FIFO_WR_PTR, &wr_ptr) != 0)
        return -1;
    if (i2c_read_reg8(fd, MAX30102_REG_OVF_COUNTER, &ovf) != 0)
        return -1;
    if (i2c_read_reg8(fd, MAX30102_REG_FIFO_RD_PTR, &rd_ptr) != 0)
        return -1;

    if (ovf == 0 && wr_ptr == rd_ptr)
        return 1;                       /* no data available yet */

    if (wr_ptr == rd_ptr) {
        if (i2c_write_reg8(fd, MAX30102_REG_OVF_COUNTER, 0x00) != 0)
            return -1;
        if (i2c_read_reg8(fd, MAX30102_REG_OVF_COUNTER, &ovf) != 0)
            return -1;
        if (ovf == 0)
            return 1;
    }

    if (i2c_read_reg8(fd, MAX30102_REG_FIFO_DATA, &data[0]) != 0)
        return -1;
    if (i2c_read_reg8(fd, MAX30102_REG_FIFO_DATA, &data[1]) != 0)
        return -1;
    if (i2c_read_reg8(fd, MAX30102_REG_FIFO_DATA, &data[2]) != 0)
        return -1;
    if (i2c_read_reg8(fd, MAX30102_REG_FIFO_DATA, &data[3]) != 0)
        return -1;
    if (i2c_read_reg8(fd, MAX30102_REG_FIFO_DATA, &data[4]) != 0)
        return -1;
    if (i2c_read_reg8(fd, MAX30102_REG_FIFO_DATA, &data[5]) != 0)
        return -1;

    *red = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
    *ir  = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_alert(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", ts, msg);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void log_data(float spo2, float hr)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s SpO2: %.2f%%, HR: %.2f BPM\n", ts, spo2, hr);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MAX30102_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                MAX30102_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (max30102_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MAX30102 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MAX30102 initialized. Monitoring SpO2 and HR (Ctrl+C to exit)...\n");

    while (g_running) {
        uint32_t red = 0, ir = 0;
        int rc = read_fifo_sample(g_i2c_fd, &red, &ir);

        if (rc == 0) {
            float spo2 = 0.0f, hr = 0.0f;
            /* Placeholder formulas — replace with real algorithm */
            spo2 = (float)red / 1000.0f;
            hr   = (float)ir  / 1000.0f;

            if (spo2 < SPO2_THRESHOLD || hr > HR_THRESHOLD) {
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "Alert: SpO2=%.2f%%, HR=%.2f BPM", spo2, hr);
                log_alert(msg);
                printf("%s\n", msg);
            } else {
                log_data(spo2, hr);
            }
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error — continuing.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

