/*
 * MCP3008 3-channel SPI logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Analog input 0
 *   MCP3008 CH1  -> Analog input 1
 *   MCP3008 CH2  -> Analog input 2
 *
 * Build:  gcc -O2 -Wall -o analog_logger analog_logger.c -lpigpio -lrt
 * Run:    sudo ./analog_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)  */
#define SPI_SPEED      1000000    /* 1 MHz              */
#define SPI_FLAGS      0          /* Mode 0, active-low CE handled by pigpio */

#define NUM_CHANNELS   3
#define SAMPLE_PERIOD  500000     /* 500 ms in microseconds */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup happens   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one single-ended channel from the MCP3008                     */
/* Returns 0–1023 on success, -1 on SPI error, -2 on invalid channel  */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d (must be 0–7)\n", channel);
        return -2;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   Byte 2: 0x00                       (clock out remaining bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in the lower nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed on channel %d (returned %d)\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to voltage (3.3 V reference)                      */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    return (float)adc_value * 3.3f / 1024.0f;
}

/* ------------------------------------------------------------------ */
/* Append a CSV row: Timestamp,Channel,Voltage                          */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int channel, float voltage)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "gmtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.4f\n", timestamp, channel, voltage) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    g_log_file = fopen("analog_log.csv", "a");
    if (g_log_file == NULL) {
        perror("fopen(\"analog_log.csv\")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long file_size = ftell(g_log_file);
        if (file_size == 0) {
            fprintf(g_log_file, "Timestamp,Channel,Voltage\n");
            fflush(g_log_file);
        }
    } else {
        perror("fseek");
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MCP3008 logger started. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int read_errors = 0;

        for (int ch = 0; ch < NUM_CHANNELS; ch++) {
            int adc_value = -1;

            for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
                adc_value = read_mcp3008(ch);
                if (adc_value >= 0)
                    break;

                fprintf(stderr, "Read attempt %d failed on channel %d\n",
                        attempt + 1, ch);
                gpioDelay(10000);  /* 10 ms backoff */
            }

            if (adc_value < 0) {
                fprintf(stderr, "Channel %d read failed after %d attempts\n",
                        ch, MAX_RETRIES);
                read_errors++;
                continue;
            }

            float voltage = adc_to_voltage(adc_value);
            if (log_data(g_log_file, ch, voltage) != 0) {
                fprintf(stderr, "Logging failed for channel %d\n", ch);
            }
        }

        if (read_errors == NUM_CHANNELS) {
            fprintf(stderr, "All channels failed after %d attempts; "
                            "continuing to next cycle\n", MAX_RETRIES);
        }

        /* Sleep 500 ms; pigpio's gpioDelay is microseconds */
        gpioDelay(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

