/*
 * MQ-2 gas sensor monitor via MCP3008 ADC on Raspberry Pi.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MQ-2 analog output
 *   Buzzer +     -> GPIO24 (Pin 18)
 *   Buzzer -     -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mq2_buzzer mq2_buzzer.c -lpigpio -lrt
 * Run:
 *   sudo ./mq2_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM GPIO8)                       */
#define SPI_SPEED      1000000    /* 1 MHz SPI clock                             */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words         */

#define BUZZER_PIN     24         /* BCM GPIO24 (active buzzer)                  */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0              */
#define ADC_THRESHOLD  500        /* ADC count threshold (safe / danger)        */
#define SAMPLE_US     500000     /* 500 ms between samples                      */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;            /* let main loop exit cleanly                 */
}

/* --------------------------- MCP3008 read -------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low 8 bits)
 * Result: 10-bit value = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Reset GPIO states to a safe condition */
    gpioWrite(BUZZER_PIN, 0);
    gpioSetMode(BUZZER_PIN, PI_INPUT);
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Initialize pigpio daemon/library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure buzzer pin --- */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_PIN, 0);   /* ensure buzzer is off at start */

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MQ-2 gas sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — continuing\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        bool danger = (adc_value >= ADC_THRESHOLD);
        if (gpioWrite(BUZZER_PIN, danger ? 1 : 0) != 0) {
            fprintf(stderr, "GPIO write failed on pin %d\n", BUZZER_PIN);
        }

        printf("ADC: %4d  Buzzer: %s\n",
               adc_value, danger ? "ON" : "OFF");

        gpioDelay(SAMPLE_US);   /* 500 ms */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    gpioTerminate();
    return EXIT_SUCCESS;
}

