        fprintf(stderr, "Error opening CS GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }

    if (write(fd, value ? "0" : "1", 1) < 0) {
        fprintf(stderr, "Error writing CS GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(FILE *fp, int s1, int s2, int s3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, s1, s2, s3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    if (cs_init() < 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        if (fprintf(g_log_fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            fprintf(stderr, "Error writing header to log file: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        fflush(g_log_fp);
    }

    printf("Soil Moisture Logger started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = -1, s2 = -1, s3 = -1;

        cs_write(0, 0);
        s1 = read_mcp3008(g_spi_fd, 0);
        cs_write(0, 1);

        cs_write(1, 0);
        s2 = read_mcp3008(g_spi_fd, 0);
        cs_write(1, 1);

        cs_write(2, 0);
        s3 = read_mcp3008(g_spi_fd, 0);
        cs_write(2, 1);

        if (log_data(g_log_fp, s1, s2, s3) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

