/*
 * irrigation.c — Raspberry Pi 4 Model B
 *
 * Reads a Vegetronix VH400 soil-moisture sensor via an MCP3008 ADC on SPI0
 * (CE0 / GPIO 8, 1 MHz, mode 0), compares the analog value to a threshold,
 * and activates a relay-driven pump on GPIO 18 for a configured duration
 * when the moisture level is below the threshold.  Logs every event to
 * irrigation.log and exits cleanly on SIGINT / SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o irrigation irrigation.c -lm
 * Run:    ./irrigation [-t threshold] [-d pump_duration] [-s sleep_interval]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_MODE          SPI_MODE_0
#define SPI_BITS_PER_WORD 8

#define PUMP_GPIO         18          /* BCM pin */
#define PUMP_ON           1
#define PUMP_OFF          0

#define DEFAULT_THRESHOLD 30.0f      /* percent of 3.3 V range */
#define DEFAULT_DURATION  10          /* seconds */
#define DEFAULT_SLEEP     60          /* seconds */
#define MAX_RETRIES       3
#define LOG_FILE          "irrigation.log"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* --------------------------- Function prototypes -------------------------- */
static int  spi_init(void);
static int  read_mcp3008(int channel, int *out_value);
static float voltage_to_moisture(int adc_value);
static void log_event(const char *msg);
static void pump_on(void);
static void pump_off(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- SPI ------------------------------------- */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low 8 bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                    attempt, MAX_RETRIES, strerror(errno));
            if (attempt < MAX_RETRIES) {
                usleep(100000); /* 100 ms back-off */
            }
            continue;
        }

        int adc = ((rx[1] & 0x03) << 8) | rx[2];
        if (adc < 0 || adc > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", adc);
            continue;
        }

        *out_value = adc;
        return 0;
    }

    return -1;
}

/* --------------------------- Moisture logic ------------------------------- */
static float voltage_to_moisture(int adc_value)
{
    /*
     * Vegetronix VH400: dry air ~0 V, fully saturated soil ~3.3 V.
     * We map 0..1023 to 0..100 %.
     */
    return (float)adc_value / 1023.0f * 100.0f;
}

/* ------------------------------- Logging ---------------------------------- */
static void log_event(const char *msg)
{
    if (g_log_fp == NULL) {
        return;
    }

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    fprintf(g_log_fp, "[%s] %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------- Pump control ----------------------------- */
static void pump_on(void)
{
    if (g_spi_fd >= 0) {
        if (gpioWrite(PUMP_GPIO, PUMP_ON) < 0) {
            log_event("ERROR: failed to set pump GPIO high");
            return;
        }
    }
    log_event("Pump turned ON");
}

static void pump_off(void)
{
    if (g_spi_fd >= 0) {
        if (g_gpioWrite(PUMP_GPIO, PUMP_OFF) < 0) {
            log_event("ERROR: failed to set pump GPIO low");
            return;
        }
    }
    log_event("Pump turned OFF");
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    pump_off();

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- main ----------------------------------- */
int main(int argc, char *argv[])
{
    int opt;
    float threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP;

    while ((opt = getopt(argc, argv, "t:d:s:h")) != -1) {
        switch (opt) {
        case 't':
            threshold = (float)atof(optarg);
            if (threshold < 0.0f || threshold > 100.0f) {
                fprintf(stderr, "Threshold must be between 0 and 100\n");
                return EXIT_FAILURE;
            }
            break;
        case 'd':
            duration = atoi(optarg);
            if (duration <= 0) {
                fprintf(stderr, "Pump duration must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 's':
            sleep_interval = atoi(optarg);
            if (sleep_interval <= 0) {
                fprintf(stderr, "Sleep interval must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [-t threshold_percent] [-d pump_duration_s] [-s sleep_interval_s]\n",
                    argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        log_event("ERROR: SPI initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize pigpio for manual GPIO control on the Pi */
    if (gpioInitialise() < 0) {
        log_event("ERROR: pigpio initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO as output, ensure pump is off */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        log_event("ERROR: failed to set pump GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    pump_off();

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Irrigation system started");

    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(0, &adc_value) < 0) {
            log_event("ERROR: MCP3008 read failed after retries");
            sleep(sleep_interval);
            continue;
        }

        float moisture = voltage_to_moisture(adc_value);
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture: %.2f%% (ADC: %d)", moisture, adc_value);
        log_event(msg);

        if (moisture < threshold) {
            log_event("Moisture below threshold — activating pump");
            pump_on();
            /* Sleep in 1-second increments so signals are caught promptly */
            for (int i = 0; i < duration && g_running; ++i) {
                sleep(1);
            }
            pump_off();
            log_event("Pump deactivated");
        }

        if (g_running) {
            sleep(sleep_interval);
        }
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

