/*
 * Raspberry Pi 3 Model B+ — Honeywell SS49E Hall-effect sensor monitor
 *
 * Hardware:
 *   - ADS1115 16-bit ADC on I2C bus 1 (address 0x48)
 *   - SS49E  linear sensor on AIN0 (single-ended)
 *   - Motor shutdown indicator LED / buzzer on GPIO27 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./hall_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/*
 * Config word (0x8483):
 *   Bit 15    OS       = 1 (begin single conversion)
 *   Bits 14:12 MUX     = 100 (AIN0 single-ended)
 *   Bits 11:9  PGA     = 001 (+/-4.096 V)
 *   Bit  8     MODE    = 1 (single-shot)
 *   Bits 7:5   DR      = 100 (128 SPS)
 *   Bit  4     COMP_MODE
 *   Bit  3     COMP_POL
 *   Bit  2     COMP_LAT
 *   Bits 1:0   COMP_QUE = 11 (disable comparator)
 */
#define ADS1115_CONFIG_BASE  0x8483

#define GPIO_SHUTDOWN        27
#define BUFFER_SIZE          60
#define VOLTAGE_THRESHOLD    3.3f   /* SS49E output rail (V) */
#define GAUSS_THRESHOLD      500.0f /* Gauss */
#define SAMPLE_PERIOD_US     1000000 /* 1 Hz */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Circular buffer --------------------------- */

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    memset(cb->buffer, 0, sizeof(cb->buffer));
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ----------------------------- Signal handling --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 helpers --------------------------- */

/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio's i2cWriteWordData sends the 16-bit value as-is (big-endian on wire).
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    int rc = i2cWriteWordData(handle, reg, value);
    if (rc < 0) {
        syslog(LOG_ERR, "i2cWriteWordData(reg=0x%02X, val=0x%04X) failed: %s",
               reg, value, strerror(errno));
    }
    return rc;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * pigpio's i2cReadWordData returns the raw 16-bit word (big-endian).
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        syslog(LOG_ERR, "i2cReadWordData(reg=0x%02X) failed: %s",
               reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success and stores the raw ADC code in *raw; -1 on error.
 */
static int ads1115_read_ain0(int handle, int16_t *raw)
{
    uint16_t config = ADS1115_CONFIG_BASE;
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0) return -1;

    /* Conversion takes ~8 ms at 128 SPS; wait 10 ms to be safe. */
    gpioDelay(10000);

    uint16_t cfg_read = 0;
    if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg_read) < 0) return -1;

    /* OS bit (bit 15) indicates conversion complete. */
    if (!(cfg_read & 0x8000)) {
        syslog(LOG_ERR, "ADS1115 conversion not complete (cfg=0x%04X)", cfg_read);
        return -1;
    }

    uint16_t conv = 0;
    if (ads1115_read_reg(handle, ADS1115_REG_CONV, &conv) < 0) return -1;

    *raw = (int16_t)conv;
    return 0;
}

/*
 * Convert raw ADC code to Gauss.
 * SS49E output is proportional to magnetic field; 4.096 V corresponds to
 * 500 Gauss for a 1.5 V sensor output.  We scale linearly.
 */
static float raw_to_gauss(int16_t raw)
{
    const float vref = 4.096f;
    const float gauss_per_v = 500.0f / 1.5f;
    float voltage = (float)raw * vref / 32768.0f;
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > VOLTAGE_THRESHOLD) voltage = VOLTAGE_THRESHOLD;
    return voltage * gauss_per_v;
}

/* ----------------------------- GPIO helpers ------------------------------ */

static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        return -1;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(GPIO%d, OUTPUT) failed", GPIO_SHUTDOWN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GPIO_SHUTDOWN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite(GPIO%d, 0) failed", GPIO_SHUTDOWN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void gpio_shutdown(void)
{
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        closelog();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen(bus=%d, addr=0x%02X) failed: %s",
               I2C_BUS, ADS1115_ADDR, strerror(errno));
        gpio_shutdown();
        closelog();
        return EXIT_FAILURE;
    }

    CircularBuffer cb;
    cb_init(&cb);

    syslog(LOG_INFO, "Hall-effect monitor started (ADS1115 @ 0x%02X, GPIO%d)",
           ADS1115_ADDR, GPIO_SHUTDOWN);

    while (g_running) {
        int16_t raw = 0;
        if (ads1115_read_ain0(g_i2c_handle, &raw) < 0) {
            syslog(LOG_WARNING, "ADC read failed; skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        cb_add(&cb, gauss);

        float avg = cb_average(&cb);
        syslog(LOG_INFO, "Raw=%d  Gauss=%.2f  Avg=%.2f", raw, gauss, avg);

        if (avg > GAUSS_THRESHOLD) {
            syslog(LOG_CRIT, "Threshold exceeded (%.2f Gauss > %.1f Gauss) — SHUTDOWN",
                   avg, GAUSS_THRESHOLD);
            gpioWrite(GPIO_SHUTDOWN, 1);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(GPIO_SHUTDOWN, 0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpio_shutdown();
    closelog();
    return EXIT_SUCCESS;
}

code:
/*
 * Raspberry Pi Zero W — Soil Moisture Monitor & Watering Controller
 *
 * Hardware:
 *   - Vegetronix VH400 soil moisture sensor  -> MCP3008 ADC channel 0
 *   - MCP3008 ADC                           -> SPI0 CE0 (GPIO8), SCLK (GPIO11), MOSI (GPIO10), MISO (GPIO9)
 *   - Relay module (active-high)            -> GPIO18 (BCM)
 *
 * Behavior:
 *   - Reads the ADC every 60 s.
 *   - Drains the pump for 10 s when moisture < 300.
 *   - Logs each event with a timestamp to watering_events.txt.
 *   - On SIGINT/SIGTERM: pump off, resources released, exit cleanly.
 *
 * Build: gcc -O2 -Wall -Wextra -o watering watering.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */

#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION  10       /* seconds */
#define POLL_INTERVAL      60      /* seconds */

#define PUMP_GPIO         18       /* BCM 18 */
#define LOG_FILE          "watering_events.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_pump_state  = 0;     /* 0 = off, 1 = on */

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize_spi(void);
static int  read_mcp3008(int channel, int *out_value);
static int  control_pump(int state);
static void log_event(int moisture_level);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI init ---------------------------------- */
static int initialize_spi(void)
{
    /*
     * pigpio's spiOpen flags: bits 0-1 = mode, bit 2 = CE active-low.
     * Mode 0 (CPOL=0, CPHA=0) => flags = 0.
     */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- MCP3008 read ------------------------------- */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7).\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (don't-care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null, null, null, null, B9, B8, B7, B6]
     *   rx[2] = [B5, B4, B3, B2, B1, B0, 0, 0]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed (returned %d).\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);

    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "Error: ADC value out of range (%d).\n", adc_value);
        return -1;
    }

    *out_value = adc_value;
    return 0;
}

/* ----------------------------- Pump control ------------------------------- */
static int control_pump(int state)
{
    if (state != 0 && state != 1) {
        fprintf(stderr, "Error: invalid pump state %d (must be 0 or 1).\n", state);
        return -1;
    }

    if (gpioWrite(PUMP_GPIO, state) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed.\n", PUMP_GPIO, state);
        return -1;
    }

    g_pump_state = state;
    printf("Pump %s.\n", state ? "activated" : "deactivated");
    return 0;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_event(int moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Moisture Level: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);

    fclose(fp);
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_pump_state) {
        control_pump(0);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO as output, initially off */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(PUMP_GPIO, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed during init.\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture_level = 0;

        if (read_mcp3008(ADC_CHANNEL, &moisture_level) != 0) {
            fprintf(stderr, "Error reading moisture level. Retrying in %d seconds.\n",
                    POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        printf("Moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating pump.\n");
            if (control_pump(1) != 0) {
                fprintf(stderr, "Error activating pump. Continuing.\n");
            } else {
                /* Drain pump for the configured duration */
                for (int i = 0; i < WATERING_DURATION && g_running; i++) {
                    sleep(1);
                }
                if (control_pump(0) != 0) {
                    fprintf(stderr, "Error deactivating pump.\n");
                }
            }
        }

        log_event(moisture_level);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

