/*
 * Rain sensor reader using MCP3008 ADC on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,  Pin 24)
 *   MCP3008 CH0  -> YL-83 analog output (Pin 34)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rain_reader rain_reader.c -lpigpio -lrt
 * Run:
 *   sudo ./rain_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC: 0..1023 */
#define VREF           3.3        /* Reference voltage */

#define SAMPLE_PERIOD  1          /* seconds between samples */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- MCP3008 helpers ----------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer, SPI mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed on channel %d (ret=%d): %s\n",
                channel, ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/*
 * Map raw ADC value to rainfall intensity (0 = dry, 1 = wet).
 * YL-83 output is proportional to moisture; a higher ADC value means
 * more water is on the sensor.  We use a simple linear mapping.
 */
static float adc_to_intensity(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    /* Dry -> 0, wet -> 1 */
    return (float)adc_value / (float)ADC_MAX_VALUE;
}

/* ------------------------------- Logging --------------------------------- */

static void log_data(int adc_value, float intensity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s  ADC: %4d  Intensity: %6.3f\n", timestamp, adc_value, intensity);
    fflush(stdout);
}

/* ------------------------------- Cleanup ---------------------------------- */

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- main ----------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d): %s\n",
                g_spi_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rain sensor reader started.  SPI0 CE0 @ %d Hz, channel %d.\n",
           SPI_SPEED, ADC_CHANNEL);
    printf("Press Ctrl-C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = mcp3008_read(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Skipping sample due to SPI read error.\n");
        } else {
            float intensity = adc_to_intensity(adc_value);
            log_data(adc_value, intensity);
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

