 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Potentiometer wiper
 *   Motor PWM    -> GPIO18 (hardware PWM0)
 *
 * Build: gcc -O2 -Wall -o pot_pwm pot_pwm.c -lpigpio -lrt
 * Run:   sudo ./pot_pwm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM GPIO8)                       */
#define SPI_SPEED      1000000    /* 1 MHz                                      */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words        */

#define PWM_GPIO       18         /* BCM GPIO18 (hardware PWM0)                 */
#define PWM_FREQ       1000       /* 1 kHz                                      */
#define PWM_RANGE      1023       /* 10-bit resolution                          */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0             */
#define SAMPLE_PERIOD  100000     /* 100 ms between samples                     */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* let main loop exit cleanly                 */
}

/* --------------------------- MCP3008 read -------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int spi_handle, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;          /* 0..1023 on success, -1 on error            */
}

/* ------------------------------- PWM setup ------------------------------- */
static int setup_pwm(int gpio, int freq, int range)
{
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", gpio);
        return -1;
    }
    if (gpioSetPWMfrequency(gpio, freq) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%d, %d) failed\n", gpio, freq);
        return -1;
    }
    if (gpioSetPWMrange(gpio, range) < 0) {
        fprintf(stderr, "gpioSetPWMrange(%d, %d) failed\n", gpio, range);
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    /* Ensure PWM is off before releasing pigpio */
    gpioPWM(PWM_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on GPIO18 --- */
    if (setup_pwm(PWM_GPIO, PWM_FREQ, PWM_RANGE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MCP3008 potentiometer -> PWM motor control running.\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            /* Transient SPI error: keep running, but warn */
            fprintf(stderr, "ADC read error — continuing\n");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        /* Map 0..1023 ADC to 0..1023 PWM duty cycle */
        int pwm_value = adc_value;

        if (gpioPWM(PWM_GPIO, pwm_value) < 0) {
            fprintf(stderr, "gpioPWM(%d, %d) failed\n", PWM_GPIO, pwm_value);
        }

        printf("ADC: %4d  PWM: %4d\n", adc_value, pwm_value);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD);   /* 100 ms */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

