#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48
#define LED_GPIO       17
#define SAMPLE_US      100000   /* 100 ms */
#define LED_BLINK_US   50000    /* 50 ms  */
#define LED_BLINK_CNT  20       /* 50 ms * 20 = 1 s */

/* ADS1115 register addresses */
#define ADS_REG_CONV   0x00
#define ADS_REG_CONFIG 0x01

/* Config register bit fields */
#define ADS_CFG_OS     0x8000  /* Operational status / single-shot start */
#define ADS_CFG_MUX   0x4000  /* AIN0 single-ended */
#define ADS_CFG_PGA   0x0200  /* PGA gain = 4.096 V */
#define ADS_CFG_MODE  0x0100  /* Single-shot mode */
#define ADS_CFG_DR    0x0080  /* 128 SPS */
#define ADS_CFG_CQUE  0x0003  /* Disable comparator */

#define PGA_4_096V    4.096f
#define HALL_SENSITIVITY 0.1f  /* SS49E: 0.1 Gauss/V */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an ADS1115 register (big-endian on the bus). */
static int ads_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);
    if (i2cWriteDevice(handle, buf, 3) < 0)
        return -1;
    return 0;
}

/* Read a 16-bit value from an ADS1115 register (big-endian on the bus). */
static int ads_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0)
        return -1;
    if (i2cReadDevice(handle, buf, 2) != 2)
        return -1;
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Trigger a single-shot conversion and read the raw ADC result. */
static int ads_read_raw(int handle, int16_t *raw)
{
    uint16_t config = ADS_CFG_OS | ADS_CFG_MUX | ADS_CFG_PGA |
                      ADS_CFG_MODE | ADS_CFG_DR | ADS_CFG_CQUE;

    if (ads_write_reg(handle, ADS_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    gpioDelay(10000);

    uint16_t cfg;
    for (int i = 0; i < 10; i++) {
        if (ads_read_reg(handle, ADS_REG_CONFIG, &cfg) < 0)
            return -1;
        if (cfg & ADS_CFG_OS)
            break;
        gpioDelay(1000);
    }
    if (!(cfg & ADS_CFG_OS))
        return -1;  /* timeout */

    uint16_t conv;
    if (ads_read_reg(handle, ADS_REG_CONV, &conv) < 0)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

static float raw_to_gauss(int16_t raw)
{
    float voltage = (float)raw * PGA_4_096V / 32768.0f;
    return voltage / HALL_SENSITIVITY;
}

static void blink_led(int gpio, int count)
{
    for (int i = 0; i < count && g_running; i++) {
        gpioWrite(gpio, 1);
        gpioDelay(LED_BLINK_US);
        gpioWrite(gpio, 0);
        gpioDelay(LED_BLINK_US);
    }
}

int main(int argc, char *argv[])
{
    float threshold = 100.0f;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = (float)atof(argv[++i]);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Error: threshold must be positive.\n");
                return EXIT_FAILURE;
            }
        } else {
            fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (err=%d).\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field (threshold: %.1f Gauss). Press Ctrl+C to exit.\n",
           threshold);

    while (g_running) {
        int16_t raw;
        if (ads_read_raw(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: I2C read failed (errno=%d).\n", errno);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        printf("Magnetic field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED.\n");
            blink_led(LED_GPIO, LED_BLINK_CNT);
        }

        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

