/*
 * Soil Moisture Monitor — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0, CE0 (GPIO8, physical pin 24, BCM)
 *   - HL-69 analog soil moisture sensor on MCP3008 channel 0
 *   - Relay module on GPIO17 (BCM), active-high
 *
 * Behavior:
 *   - Reads ADC every 60 s, hysteresis control: pump ON  when moisture < 30 %,
 *     pump OFF when moisture > 35 %.
 *   - Publishes moisture to MQTT topic "soil_moisture".
 *   - Subscribes to MQTT topic "pump_control" for "pump_on" / "pump_off".
 *   - Logs to syslog; exits cleanly on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>

#include <pigpio.h>
#include <mosquitto.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define PUMP_GPIO        17         /* BCM 17 */
#define PUMP_ON          1
#define PUMP_OFF         0

#define MOISTURE_LOW     30         /* % — turn pump ON below this */
#define MOISTURE_HIGH    35         /* % — turn pump OFF above this */

#define MQTT_HOST        "localhost"
#define MQTT_PORT        1883
#define MQTT_CLIENT_ID   "soil_moisture_monitor"
#define MQTT_TOPIC       "soil_moisture"
#define MQTT_CTRL_TOPIC  "pump_control"

#define SAMPLE_PERIOD_S  60         /* seconds between readings */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */

/* ----------------------------- Globals ---------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static struct mosquitto *g_mqtt = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static int  read_mcp3008(int channel);
static int  moisture_percent(int adc_value);
static void control_pump(int on);
static void publish_moisture(int moisture);
static void on_mqtt_connect(struct mosquitto *m, void *ud,
                            int rc, int flags);
static void on_mqtt_disconnect(struct mosquitto *m, void *ud,
                               int rc, int flags);
static void on_mqtt_message(struct mosquitto *m, void *ud,
                            const struct mosquitto_message *msg);
static void on_mqtt_subscribe(struct mosquitto *m, void *ud,
                              int mid, int qos_count, const int *granted_qos);
static void on_mqtt_unsubscribe(struct mosquitto *m, void *ud,
                                int mid);
static void signal_handler(int sig);

/* ----------------------------- SPI / MCP3008 ----------------------------- */

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel %d", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, MSB-first):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   Byte 0: undefined
     *   Byte 1: bits 7..2 undefined, bit 1 = null bit, bit 0 = MSB of result
     *   Byte 2: bits 7..0 = low 8 bits of result
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        syslog(LOG_ERR, "spiXfer failed (ret=%d): %s", ret, strerror(errno));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc;
}

/* ----------------------------- Moisture logic ---------------------------- */

/*
 * Convert 10-bit ADC value to percentage (0–100).
 * Returns -1 if the value is out of the expected range.
 */
static int moisture_percent(int adc_value)
{
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1;
    }
    return (int)(((float)adc_value / 1023.0f) * 100.0f);
}

/* ----------------------------- Pump control ------------------------------ */

static void control_pump(int on)
{
    int rc = gpioWrite(PUMP_GPIO, on ? PUMP_ON : PUMP_OFF);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(%d) failed: %s", on, pigpio_error(rc));
    } else {
        syslog(LOG_INFO, "Pump %s", on ? "ON" : "OFF");
    }
}

/* ----------------------------- MQTT publishing --------------------------- */

static void publish_moisture(int moisture)
{
    if (!g_mqtt) {
        syslog(LOG_ERR, "MQTT not connected; cannot publish");
        return;
    }

    char payload[16];
    int len = snprintf(payload, sizeof(payload), "%d", moisture);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "MQTT payload formatting failed");
        return;
    }

    int rc = mosquitto_publish(g_mqtt, NULL, MQTT_TOPIC,
                               (int)strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_publish failed: %s", mosquitto_strerror(rc));
    }
}

/* ----------------------------- MQTT callbacks ---------------------------- */

static void on_mqtt_connect(struct mosquitto *m, void *ud,
                            int rc, int flags)
{
    (void)ud; (void)flags;

    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(rc));
        return;
    }

    syslog(LOG_INFO, "MQTT connected");

    int rc_sub = mosquitto_subscribe(m, NULL, MQTT_CTRL_TOPIC, 0);
    if (rc_sub != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(rc_sub));
    } else {
        syslog(LOG_INFO, "Subscribed to %s", MQTT_CTRL_TOPIC);
    }
}

static void on_mqtt_disconnect(struct mosquitto *m, void *ud,
                               int rc, int flags)
{
    (void)m; (void)ud; (void)flags;

    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        syslog(LOG_WARNING, "MQTT unexpected disconnect: %s",
               mosquitto_strerror(rc));
    }
}

static void on_mqtt_message(struct mosquitto *m, void *ud,
                            const struct mosquitto_message *msg)
{
    (void)m; (void)ud;

    if (!msg || !msg->payload || msg->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT message received");
        return;
    }

    /* Ensure NUL-terminated payload for safe string comparison */
    char buf[32];
    int len = msg->payloadlen < (int)sizeof(buf) - 1
              ? msg->payloadlen : (int)sizeof(buf) - 1;
    memcpy(buf, msg->payload, len);
    buf[len] = '\0';

    syslog(LOG_INFO, "Received MQTT message on %s: %s", msg->topic, buf);

    if (strcmp(msg->topic, MQTT_CTRL_TOPIC) != 0) {
        syslog(LOG_WARNING, "Unexpected topic: %s", msg->topic);
        return;
    }

    if (strcmp(buf, "pump_on") == 0) {
        control_pump(1);
    } else if (strcmp(buf, "pump_off") == 0) {
        control_pump(0);
    } else {
        syslog(LOG_WARNING, "Unknown command: %s", buf);
    }
}

static void on_mqtt_subscribe(struct mosquitto *m, void *ud,
                              int mid, int qos_count, const int *granted_qos)
{
    (void)m; (void)ud; (void)mid; (void)qos_count; (void)granted_qos;
    syslog(LOG_INFO, "MQTT subscription acknowledged");
}

static void on_mqtt_unsubscribe(struct mosquitto *m, void *ud,
                                int mid)
{
    (void)m; (void)ud; (void)mid;
    syslog(LOG_INFO, "MQTT unsubscription acknowledged");
}

/* ----------------------------- Signal handling --------------------------- */

static void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal %d received; shutting down", sig);
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(%d) failed", PUMP_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, PUMP_OFF);

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        syslog(LOG_ERR, "spiOpen failed: %s", pigpio_error(g_spi_handle));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* --- MQTT init --- */
    mosquitto_lib_init();
    g_mqtt = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mqtt) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mqtt, on_mqtt_connect);
    mosquitto_disconnect_callback_set(g_mqtt, on_mqtt_disconnect);
    mosquitto_message_callback_set(g_mqtt, on_mqtt_message);
    mosquitto_subscribe_callback_set(g_mqtt, on_mqtt_subscribe);
    mosquitto_unsubscribe_callback_set(g_mqtt, on_mqtt_unsubscribe);

    int rc = mosquitto_connect(g_mqtt, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mqtt);
        spiClose(g_spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(g_mqtt);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_loop_start failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(g_mqtt);
        mosquitto_destroy(g_mqtt);
        spiClose(g_spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Soil moisture monitor started");

    /* --- Main loop --- */
    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            syslog(LOG_ERR, "SPI read failed; skipping cycle");
        } else {
            int moisture = moisture_percent(adc);
