        return 1;
    }

    set_motor_pwm(MOTOR1_PIN, 0);
    set_motor_pwm(MOTOR2_PIN, 0);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int noise_level = read_mcp3008_channel(0);
        if (noise_level < 0) {
            fprintf(stderr, "Error reading noise level, skipping iteration.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (noise_level > NOISE_THRESHOLD) {
            set_motor_pwm(MOTOR1_PIN, 100);
            set_motor_pwm(MOTOR2_PIN, 100);
            log_vibration_event();
        } else {
            set_motor_pwm(MOTOR1_PIN, 0);
            set_motor_pwm(MOTOR2_PIN, 0);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

