/*
 * Raspberry Pi 4 Model B — Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 / BCM GPIO 8), 1 MHz, 3.3 V VDD
 *   - Vegetronix VH400 on MCP3008 channel 0 (single-ended)
 *   - Relay module on BCM GPIO 17 (active-high), driven by water pump
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o moisture moisture.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./moisture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM GPIO 8)                 */
#define SPI_SPEED      1000000    /* 1 MHz                                 */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words   */

#define PUMP_GPIO      17         /* BCM GPIO 17 — relay control           */
#define MOISTURE_THRESHOLD 30    /* % — water when below this             */
#define SAMPLE_INTERVAL_S  60    /* seconds between readings              */
#define MAX_RETRIES        3      /* SPI read retries per sample           */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes -------------------------- */
static int  read_mcp3008(int channel, int *out_value);
static void control_pump(int gpio_pin, bool on);
static void log_data(int moisture_level);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- MCP3008 --------------------------------- */
/*
 * Read a single-ended channel (0–7) from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on failure.
 *
 * MCP3008 SPI protocol (Mode 0, MSB-first):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   Byte 2: 0x00                       (clock out remaining bits)
 *   Response: bits 9..0 are in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        int ret = spiXfer(g_spi_handle, tx, rx, 3);
        if (ret == 3) {
            *out_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
            return 0;
        }
        fprintf(stderr, "Warning: SPI transfer failed (attempt %d/%d, ret=%d)\n",
                attempt, MAX_RETRIES, ret);
        if (attempt < MAX_RETRIES) {
            time_sleep(0.1);          /* brief back-off before retry */
        }
    }

    return -1;
}

/* ------------------------------- Pump control ----------------------------- */
static void control_pump(int gpio_pin, bool on)
{
    if (gpioWrite(gpio_pin, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", gpio_pin, on ? 1 : 0);
    }
}

/* ------------------------------- Logging ---------------------------------- */
static void log_data(int moisture_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Moisture level: %d%%\n", timestamp, moisture_level);
    fflush(stdout);
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is off before releasing resources */
    if (g_spi_handle >= 0) {
        control_pump(PUMP_GPIO, false);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* let main loop exit cleanly */
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* --- Initialize pigpio daemon/library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO as output, initially OFF --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(PUMP_GPIO, false);

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen(channel=%d, speed=%d) failed (handle=%d)\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction failed; signals may not be caught cleanly\n");
    }

    printf("Soil moisture monitoring started.\n");
    printf("  SPI0 CE0 @ %d Hz, MCP3008 ch0, pump on BCM GPIO %d\n", SPI_SPEED, PUMP_GPIO);
    printf("  Threshold: %d%%, sample interval: %d s\n", MOISTURE_THRESHOLD, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        int moisture_level = 0;

        if (read_mcp3008(0, &moisture_level) == 0) {
            log_data(moisture_level);

            if (moisture_level < MOISTURE_THRESHOLD) {
                control_pump(PUMP_GPIO, true);
                printf("  -> Watering system activated (moisture %d%% < %d%%)\n",
                       moisture_level, MOISTURE_THRESHOLD);
            } else {
                control_pump(PUMP_GPIO, false);
                printf("  -> Watering system deactivated (moisture %d%% >= %d%%)\n",
                       moisture_level, MOISTURE_THRESHOLD);
            }
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: failed to read moisture after %d retries\n", MAX_RETRIES);
            /* Keep pump OFF on read failure for safety */
            control_pump(PUMP_GPIO, false);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; ++i) {
            time_sleep(1.0);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

