/*
 * Door-Opening Simulator using Raspberry Pi Zero W
 *
 * Hardware:
 *   - GP2Y0A21YK0F IR distance sensor -> MCP3008 ADC channel 0
 *   - MCP3008 on SPI0 (CE0), 1 MHz, 3.3 V VDD/VREF
 *   - Relay on GPIO17 (BCM), active-high
 *
 * Behavior:
 *   Polls the ADC every 100 ms.  When the distance (cm) falls below 20,
 *   energizes the relay for 1 s, debounces for 1 s, and logs the event.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_sim door_sim.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE          SPI_MODE_0

#define ADC_CHANNEL       0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE     1023       /* 10-bit ADC */

#define DISTANCE_THRESHOLD_CM 20.0f
#define DEBOUNCE_DELAY_S      1
#define POLL_INTERVAL_MS      100

#define RELAY_GPIO_LINE    17         /* BCM 17 */
#define LOG_FILE           "door_events.log"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Signal handler ---------------------------- */

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ----------------------------- SPI helpers ------------------------------- */

static int spi_init(const char *device, uint32_t speed_hz)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = speed_hz;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low 8 bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int mcp3008_read(int spi_fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value < 0 || value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", value);
        return -1;
    }
    return value;
}

/* ----------------------------- Distance conversion ----------------------- */

/*
 * GP2Y0A21YK0F IR distance sensor (analog output, 3.3 V supply):
 *   ~10 cm -> ~0.3 V
 *   ~80 cm -> ~2.0 V
 *   ~100 cm -> ~3.0 V
 *   ~120 cm -> ~3.5 V
 *   ~150 cm -> ~4.0 V
 *
 * ADC 10-bit: 0..1023 counts.  3.3 V reference.
 *   0   -> ~0.0 V
 *   1023-> ~3.3 V
 *   512 -> ~1.65 V  (approx 50 cm)
 *
 * Linear approximation: distance_cm = (value / 1023.0) * 100 cm.
 */
static float adc_to_distance_cm(int adc_value)
{
    if (adc_value < 0) return -1.0f;
    return (float)adc_value / (float)ADC_MAX_VALUE * 100.0f;
}

/* ----------------------------- Logging ----------------------------------- */

static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }

    fclose(fp);
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI --- */
    int spi_fd = spi_init(SPI_DEVICE, SPI_SPEED_HZ);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip and request relay line --- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_GPIO_LINE);
    if (!relay_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                RELAY_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "door_sim", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Door opening simulator started.  Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; retrying in %d ms...\n",
                    POLL_INTERVAL_MS);
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        float distance_cm = adc_to_distance_cm(adc_value);

        if (distance_cm < 0.0f) {
            fprintf(stderr, "Distance conversion error\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        printf("Distance: %.2f cm\n", distance_cm);

        if (distance_cm < DISTANCE_THRESHOLD_CM) {
            printf("Door opening triggered!\n");

            if (gpiod_line_set_value(relay_line, 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value(1): %s\n",
                        strerror(errno));
            } else {
                log_event("Door opening triggered");
            }

            /* Debounce: hold relay energized for 1 s, then de-energize */
            sleep(DEBOUNCE_DELAY_S);

            if (gpiod_line_set_value(relay_line, 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(0): %s\n",
                        strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

