#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define VALVE_GPIO     17
#define PWM_FREQ       100
#define PWM_RANGE      100
#define LOG_FILE       "irrigation.log"
#define SAMPLE_COUNT   3
#define SAMPLE_DELAY   5
#define ADC_CHANNEL    0

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((channel & 0x07) << 4 | 0x80),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int set_valve_position(int position)
{
    if (position < 0 || position > PWM_RANGE) {
        fprintf(stderr, "Invalid valve position %d (must be 0-%d)\n",
                position, PWM_RANGE);
        return -1;
    }

    if (gpioPWM(VALVE_GPIO, position) < 0) {
        fprintf(stderr, "gpioPWM failed for GPIO %d\n", VALVE_GPIO);
        return -1;
    }
    return 0;
}

static void log_data(int r1, int r2, int r3, int avg, int pos)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file,
            "%s, R1=%d, R2=%d, R3=%d, Avg=%d, Pos=%d\n",
            ts, r1, r2, r3, avg, pos);
    fflush(g_log_file);
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioPWM(VALVE_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen log file");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Irrigation controller started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_DELAY);

    while (g_running) {
        int r1 = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        int r2 = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        int r3 = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (r1 < 0 || r2 < 0 || r3 < 0) {
            fprintf(stderr, "ADC read error — skipping cycle\n");
            sleep(SAMPLE_DELAY);
            continue;
        }

        int avg = (r1 + r2 + r3) / SAMPLE_COUNT;

        int pos = (avg * PWM_RANGE) / 1023;
        if (pos > PWM_RANGE) pos = PWM_RANGE;
        if (pos < 0)         pos = 0;

        if (set_valve_position(pos) != 0) {
            fprintf(stderr, "Failed to set valve position\n");
        }

        log_data(r1, r2, r3, avg, pos);
        printf("R1=%d R2=%d R3=%d Avg=%d Pos=%d\n", r1, r2, r3, avg, pos);

        sleep(SAMPLE_DELAY);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

