#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define SAMPLE_INTERVAL 5
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE 1
#define RETRY_DELAY_MAX 32

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d): %s\n", ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    return 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_data(const char *timestamp, float moisture_percentage, int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%s,%.2f,%d\n", timestamp, moisture_percentage, adc_value);
    fclose(fp);
}

static void log_error(const char *timestamp, const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%s,ERROR,%s\n", timestamp, message);
    fclose(fp);
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;
        int delay = RETRY_DELAY_BASE;

        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying (%d/%d) in %d seconds...\n", retries, MAX_RETRIES, delay);
                sleep(delay);
                delay = (delay * 2 > RETRY_DELAY_MAX) ? RETRY_DELAY_MAX : delay * 2;
            }
        }

        if (adc_value < 0) {
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));
            log_error(timestamp, "SPI communication failed after retries");
            fprintf(stderr, "Failed to read ADC value after %d retries. Skipping sample.\n", MAX_RETRIES);
        } else {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));
            log_data(timestamp, moisture_percentage, adc_value);
            printf("%s - Moisture: %.2f%% (ADC: %d)\n", timestamp, moisture_percentage, adc_value);
        }

        if (running) {
            sleep(SAMPLE_INTERVAL);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nSoil moisture monitoring stopped.\n");
    return EXIT_SUCCESS;
}

