#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define CONFIG_FILE "theremin_config.txt"
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 30000

#define DEFAULT_FREQ_MIN 100
#define DEFAULT_FREQ_MAX 1000
#define DEFAULT_FREQ_STEP 10
#define DEFAULT_VOL_MIN 0.1
#define DEFAULT_VOL_MAX 1.0
#define DEFAULT_VOL_STEP 0.1

#define SOUND_SPEED 34300.0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int pwm_fd = -1;

typedef struct {
    double freq_min;
    double freq_max;
    double freq_step;
    double vol_min;
    double vol_max;
    double vol_step;
} Config;

static Config config = {
    DEFAULT_FREQ_MIN, DEFAULT_FREQ_MAX, DEFAULT_FREQ_STEP,
    DEFAULT_VOL_MIN, DEFAULT_VOL_MAX, DEFAULT_VOL_STEP
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        return -1;
    }
    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI mode");
        close(spi_fd); spi_fd = -1; return -1;
    }
    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI bits");
        close(spi_fd); spi_fd = -1; return -1;
    }
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI speed");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int pwm_init(void) {
    pwm_fd = open("/sys/class/pwm/pwm0/enable", O_WRONLY);
    if (pwm_fd < 0) {
        perror("open PWM enable");
        return -1;
    }
    if (write(pwm_fd, "1", 1) < 0) {
        perror("PWM enable");
        close(pwm_fd); pwm_fd = -1; return -1;
    }
    int period = 1000000;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwm0/period");
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open PWM period");
        return -1;
    }
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", period);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("PWM period");
        close(fd); return -1;
    }
    close(fd);
    return 0;
}

static int read_ldr(void) {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer");
        return -1;
    }
    int val = ((rx[1] & 0x03) << 8) | rx[2];
    return val;
}

static double measure_distance(void) {
    if (gpioWrite(TRIG_PIN, 0) < 0) return -1.0;
    gpioDelay(5);
    if (gpioWrite(TRIG_PIN, 1) < 0) return -1.0;
    gpioDelay(10);
    if (gpioWrite(TRIG_PIN, 0) < 0) return -1.0;
    uint32_t start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start > TIMEOUT_US) return -1.0;
    }
    uint32_t pulse_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - pulse_start > TIMEOUT_US) return -1.0;
    }
    uint32_t pulse_end = gpioTick();
    double elapsed = (double)(pulse_end - pulse_start) / 1000000.0;
    return (elapsed * SOUND_SPEED) / 2.0;
}

static double map_distance_to_frequency(double distance) {
    if (distance < 0) return -1.0;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    double norm = distance / MAX_DISTANCE;
    return config.freq_min + (config.freq_max - config.freq_min) * norm;
}

static double map_ldr_to_volume(double ldr) {
    if (ldr < 0) return -1.0;
    if (ldr > 1023) ldr = 1023;
    double norm = ldr / 1023.0;
    return config.vol_min + (config.vol_max - config.vol_min) * norm;
}

static void set_tone(double freq, double vol) {
    if (freq < 0 || vol < 0) return;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwm0/duty_cycle");
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open PWM duty");
        return;
    }
    long duty = (long)(vol * 1000000.0);
    char buf[32];
    snprintf(buf, sizeof(buf), "%ld", duty);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("PWM duty");
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwm0/period");
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open PWM period");
        return;
    }
    long period = (long)(1000000.0 / freq);
    char buf2[32];
    snprintf(buf2, sizeof(buf2), "%ld", period);
    if (write(fd, buf2, strlen(buf2)) < 0) {
        perror("PWM period");
    }
    close(fd);
}

static void save_config(const char *fn) {
    FILE *fp = fopen(fn, "w");
    if (!fp) {
        perror("save config");
        return;
    }
    fprintf(fp, "%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            config.freq_min, config.freq_max, config.freq_step,
            config.vol_min, config.vol_max, config.vol_step);
    fclose(fp);
}

static int load_config(const char *fn) {
    FILE *fp = fopen(fn, "r");
    if (!fp) return -1;
    if (fscanf(fp, "%lf,%lf,%lf,%lf,%lf,%lf",
               &config.freq_min, &config.freq_max, &config.freq_step,
               &config.vol_min, &config.vol_max, &config.vol_step) != 6) {
        fclose(fp); return -1;
    }
    if (config.freq_min < 0 || config.freq_max < 0 ||
        config.vol_min < 0 || config.vol_max < 0 ||
        config.freq_min >= config.freq_max ||
        config.vol_min >= config.vol_max) {
        fclose(fp); return -1;
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }
    if (pwm_init() < 0) {
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        goto cleanup;
    }
    if (gpioWrite(TRIG_PIN, 0) < 0) goto cleanup;
    if (load_config(CONFIG_FILE) < 0) {
        fprintf(stderr, "Using defaults\n");
    }
    double last_freq = -1.0;
    double last_vol = -1.0;
    while (running) {
        double distance = measure_distance();
        double ldr = (double)read_ldr();
        if (distance < 0 || ldr < 0) {
            fprintf(stderr, "Sensor error, retaining last values\n");
        } else {
            double freq = map_distance_to_frequency(distance);
            double vol = map_ldr_to_volume(ldr);
            if (freq >= 0 && vol >= 0) {
                last_freq = freq;
                last_vol = vol;
            } else {
                fprintf(stderr, "Mapping error, retaining last values\n");
            }
        }
        set_tone(last_freq, last_vol);
        gpioDelay(10000);
    }
cleanup:
    if (pwm_fd >= 0) {
        write(pwm_fd, "0", 1);
        close(pwm_fd);
    }
    if (spi_fd >= 0) close(spi_fd);
    gpioTerminate();
    save_config(CONFIG_FILE);
    return 0;
}

