#include <signal.h>
#include <pigpio.h>

#define MOTOR1_ENABLE 18
#define MOTOR2_ENABLE 24
#define MOTOR1_DIR 23
#define MOTOR2_DIR 25

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

#define ACCELERATION_TIME 2
#define HOLD_TIME 2
#define DECELERATION_TIME 2
#define PAUSE_TIME 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_pot_to_speed(int pot_value) {
    if (pot_value < 0) pot_value = 0;
    if (pot_value > 1023) pot_value = 1023;
    return (int)(((float)pot_value / 1023.0f) * 255.0f);
}

static void set_motor_speed(int enable_pin, int direction_pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    if (gpioPWM(enable_pin, speed) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on pin %d\n", enable_pin);
    }
    if (gpioWrite(direction_pin, speed > 0 ? 1 : 0) != 0) {
        fprintf(stderr, "Error: Failed to set direction on pin %d\n", direction_pin);
    }
}

static void accelerate_motor(int enable_pin, int direction_pin, int target_speed) {
    int current_speed = 0;
    int step = 5;

    while (current_speed < target_speed && running) {
        current_speed += step;
        if (current_speed > target_speed) current_speed = target_speed;
        set_motor_speed(enable_pin, direction_pin, current_speed);
        gpioDelay(10000);
    }
}

static void decelerate_motor(int enable_pin, int direction_pin, int target_speed) {
    int current_speed = 255;
    int step = 5;

    while (current_speed > target_speed && running) {
        current_speed -= step;
        if (current_speed < target_speed) current_speed = target_speed;
        set_motor_speed(enable_pin, direction_pin, current_speed);
        gpioDelay(10000);
    }
    set_motor_speed(enable_pin, direction_pin, 0);
}

static void reverse_direction(int motor1_dir, int motor2_dir) {
    gpioWrite(motor1_dir, !gpioRead(motor1_dir));
    gpioWrite(motor2_dir, !gpioRead(motor2_dir));
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);

    while (running) {
        int pot1 = read_mcp3008(spi_handle, POT1_CHANNEL);
        int pot2 = read_mcp3008(spi_handle, POT2_CHANNEL);

        if (pot1 < 0 || pot2 < 0) {
            fprintf(stderr, "Error: Failed to read potentiometers, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        int speed1 = map_pot_to_speed(pot1);
        int speed2 = map_pot_to_speed(pot2);

        accelerate_motor(MOTOR1_ENABLE, MOTOR1_DIR, speed1);
        accelerate_motor(MOTOR2_ENABLE, MOTOR2_DIR, speed2);

        gpioDelay(HOLD_TIME * 1000000);

        decelerate_motor(MOTOR1_ENABLE, MOTOR1_DIR, 0);
        decelerate_motor(MOTOR2_ENABLE, MOTOR2_DIR, 0);

        gpioDelay(PAUSE_TIME * 1000000);

        reverse_direction(MOTOR1_DIR, MOTOR2_DIR);

        gpioDelay(500000);
    }

    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIR, 0);
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIR, 0);

    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

