#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define CALIBRATION_DURATION 5
#define DEBOUNCE_DELAY_US 10000
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_noise_level(void) {
    int sum = 0;
    int num_samples = 0;

    printf("Calibrating ambient noise level for %d seconds...\n", CALIBRATION_DURATION);
    for (int i = 0; i < CALIBRATION_DURATION * 10 && running; i++) {
        int sample = read_mcp3008(MCP3008_CHANNEL);
        if (sample < 0) {
            fprintf(stderr, "Error: Failed to read MCP3008 during calibration\n");
            return -1;
        }
        sum += sample;
        num_samples++;
        gpioDelay(100000);
    }

    if (!running) return -1;

    if (num_samples == 0) {
        fprintf(stderr, "Error: No samples collected during calibration\n");
        return -1;
    }

    int baseline = sum / num_samples;
    printf("Calibration complete. Baseline noise level: %d\n", baseline);
    return baseline;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }

    int baseline = calibrate_noise_level();
    if (baseline < 0) {
        fprintf(stderr, "Error: Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting sound level monitoring. Press Ctrl+C to exit.\n");

    int last_led_state = 0;
    uint32_t last_debounce_time = 0;

    while (running) {
        int sound_level = read_mcp3008(MCP3008_CHANNEL);
        if (sound_level < 0) {
            fprintf(stderr, "Error: Failed to read MCP3008\n");
            break;
        }

        int difference = sound_level - baseline;
        int sound_detected = (difference > 0);

        if (sound_detected) {
            uint32_t now = gpioTick();
            if (now - last_debounce_time > DEBOUNCE_DELAY_US) {
                int new_led_state = sound_detected ? 1 : 0;
                if (new_led_state != last_led_state) {
                    gpioWrite(LED_PIN, new_led_state);
                    last_led_state = new_led_state;
                }
                last_debounce_time = now;
            }
        } else {
            gpioWrite(LED_PIN, 0);
            last_led_state = 0;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

