#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double voltage_to_airflow(double voltage) {
    if (voltage <= 0.0) return 0.0;
    if (voltage >= 3.3) return 0.0;

    double airflow = 0.0;
    if (voltage < 0.5) {
        airflow = 0.0;
    } else if (voltage < 1.0) {
        airflow = 0.5 * (voltage - 0.5);
    } else if (voltage < 1.5) {
        airflow = 0.5 * (voltage - 1.0);
    } else if (voltage < 2.0) {
        airflow = 0.5 * (voltage - 1.5);
    } else {
        airflow = 0.5 * (voltage - 2.0);
    }
    return airflow;
}

static void log_data(double airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, airflow);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            log_error("ADC read failed");
        } else {
            double voltage = (double)adc_value * (3.3 / 1023.0);
            double airflow = voltage_to_airflow(voltage);
            log_data(airflow);
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nCleaning up...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    return 0;
}

