#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_GPIO_LINE    8          /* BCM 8, physical pin 24 */
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)
#define LOG_FILE        "audio_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_init(int *fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000; /* 1 MHz */
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int spi_fd, int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_sample(FILE *fp, long long timestamp_ns, int adc_value)
{
    if (fprintf(fp, "%lld|%d\n", timestamp_ns, adc_value) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    struct timespec next_deadline;
    long long next_deadline_ns;

    if (install_signal_handlers() < 0)
        goto fail;

    /* --- GPIO setup for manual chip-select (BCM 8) --- */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        goto fail;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        goto fail;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        goto fail;
    }

    /* --- SPI setup --- */
    if (spi_init(&spi_fd) < 0)
        goto fail;

    /* --- Log file --- */
    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto fail;
    }

    /* --- Timing setup --- */
    next_deadline.tv_sec  = 0;
    next_deadline.tv_nsec = SAMPLE_PERIOD_NS;
    next_deadline_ns = SAMPLE_PERIOD_NS;

    printf("Sampling MCP3008 channel 0 at %d Hz. Press Ctrl+C to stop.\n",
           SAMPLE_RATE_HZ);

    while (g_running) {
        /* Manual CS low */
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }

        int adc_value = 0;
        if (mcp3008_read(spi_fd, 0, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        /* Manual CS high */
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("gpiod_line_set_value(1)");
            break;
        }

        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &now) < 0) {
            perror("clock_gettime");
            break;
        }

        long long ts_ns = (long long)now.tv_sec * 1000000000LL + now.tv_nsec;

        if (log_sample(log_fp, ts_ns, adc_value) < 0)
            break;

        /* Sleep until next deadline */
        next_deadline_ns -= (ts_ns - next_deadline_ns);
        if (next_deadline_ns < 0)
            next_deadline_ns = SAMPLE_PERIOD_NS;

        next_deadline.tv_sec  = 0;
        next_deadline.tv_nsec = next_deadline_ns;

        while (g_running) {
            struct timespec rem;
            int rc = nanosleep(&next_deadline, &rem);
            if (rc == 0)
                break;
            if (errno != EINTR) {
                perror("nanosleep");
                goto fail;
            }
            /* Interrupted by signal; update deadline and retry */
            if (!g_running)
                break;
            next_deadline = rem;
        }
    }

    /* --- Cleanup --- */
    if (log_fp) {
        fflush(log_fp);
        fclose(log_fp);
    }
    if (spi_fd >= 0)
        close(spi_fd);
    if (cs_line)
        gpiod_line_release(cs_line);
    if (chip)
        gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return 0;

fail:
    if (log_fp) {
        fflush(log_fp);
        fclose(log_fp);
    }
    if (spi_fd >= 0)
        close(spi_fd);
    if (cs_line)
        gpiod_line_release(cs_line);
    if (chip)
        gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

