/*
 * ADXL335 + MCP3008 SPI Accelerometer Reader with Kalman Filter
 * Board: Raspberry Pi 4 Model B
 * Wiring:
 *   ADXL335 VCC -> 3.3V (Pin 1)
 *   ADXL335 GND -> GND  (Pin 9)
 *   ADXL335 XOUT -> MCP3008 CH0
 *   ADXL335 YOUT -> MCP3008 CH1
 *   ADXL335 ZOUT -> MCP3008 CH2
 *   MCP3008 VDD -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 9)
 *   MCP3008 CLK  -> GPIO11 (SCLK, BCM 11)
 *   MCP3008 DOUT -> GPIO9  (MISO,  BCM 9)
 *   MCP3008 DIN  -> GPIO10 (MOSI,  BCM 10)
 *   MCP3008 CS   -> GPIO8  (CE0,   BCM 8)
 *   MCP3008 DGND -> GND  (Pin 9)
 * Build: gcc -O2 -Wall -o adxl335_kalman adxl335_kalman.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define GPIO_CS         8
#define GPIO_CS_OFFSET  8

#define SAMPLE_RATE_HZ  10
#define SAMPLE_DELAY_US (1000000U / SAMPLE_RATE_HZ)

#define ADC_MAX         1023
#define VREF            3.3f
#define ADC_GAIN        0.003f   /* 3.3 V / 1024 counts */

#define KALMAN_Q        0.001f
#define KALMAN_R        0.1f
#define KALMAN_P        1.0f

#define NUM_AXES        3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_us(uint32_t us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static int spi_xfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_export(int pin)
{
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY && errno != EEXIST) {
            fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
            return -1;
        }
        fd = open("/sys/class/gpio/unexport", O_WRONLY);
        if (fd < 0) {
            fprintf(stderr, "Failed to unexport GPIO %d: %s\n", pin, strerror(errno));
            return -1;
        }
        if (write(fd, "8", 1) < 0 && errno != EINVAL) {
            fprintf(stderr, "Failed to unexport GPIO %d: %s\n", pin, strerror(errno));
            close(fd);
            return -1;
        }
        close(fd);
        fd = open("/sys/class/gpio/export", O_WRONLY);
        if (fd < 0) {
            fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
            return -1;
        }
    }
    if (write(fd, "8", 1) < 0 && errno != EBUSY && errno != EEXIST) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        fprintf(stderr, "Failed to set direction on %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(int pin, int value)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, value ? "1" : "0", 1) < 0) {
        fprintf(stderr, "Failed to set value on %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_init(void)
{
    if (gpio_export(GPIO_CS_OFFSET) < 0) return -1;
    if (gpio_set_direction(GPIO_CS_OFFSET, "out") < 0) return -1;
    if (gpio_set_value(GPIO_CS_OFFSET, 1) < 0) return -1;
    return 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel, int *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    if (gpio_set_value(GPIO_CS_OFFSET, 0) < 0) return -1;
    if (spi_xfer(fd, tx, rx, 3) < 0) {
        gpio_set_value(GPIO_CS_OFFSET, 1);
        return -1;
    }
    if (gpio_set_value(GPIO_CS_OFFSET, 1) < 0) return -1;

    *out = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float kalman_filter(float new_measurement, float *state, float *covariance)
{
    float prediction = *state;
    *covariance += KALMAN_Q;

    float kalman_gain = *covariance / (KALMAN_R + *covariance);
    prediction += kalman_gain * (new_measurement - prediction);
    *covariance -= kalman_gain * *covariance;

    *state = prediction;
    return prediction;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_fd = spi_init();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpio_set_value(GPIO_CS_OFFSET, 0);
        gpio_export(GPIO_CS_OFFSET);
        return EXIT_FAILURE;
    }

    float kalman_state[NUM_AXES] = {0.0f};
    float kalman_covariance[NUM_AXES] = {1.0f};

    printf("ADXL335 + MCP3008 SPI Accelerometer Reader (Kalman Filter)\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int raw[NUM_AXES];
        bool read_error = false;

        for (int i = 0; i < NUM_AXES; i++) {
            if (read_mcp3008(spi_fd, i, &raw[i]) < 0) {
                read_error = true;
                break;
            }
        }

        if (read_error) {
            fprintf(stderr, "SPI read error, retrying...\n");
            sleep_us(SAMPLE_DELAY_US);
            continue;
        }

        float g[NUM_AXES];
        for (int i = 0; i < NUM_AXES; i++) {
            g[i] = (float)raw[i] * ADC_GAIN;
        }

        float filtered[NUM_AXES];
        for (int i = 0; i < NUM_AXES; i++) {
            filtered[i] = kalman_filter(g[i], &kalman_state[i], &kalman_covariance[i]);
        }

        printf("X: %7.3f g, Y: %7.3f g, Z: %7.3f g\n",
               filtered[0], filtered[1], filtered[2]);
        fflush(stdout);

        sleep_us(SAMPLE_DELAY_US);
    }

    printf("\nExiting...\n");
    close(spi_fd);
    gpio_set_value(GPIO_CS_OFFSET, 0);
    gpio_export(GPIO_CS_OFFSET);
    return EXIT_SUCCESS;
}

