#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO        17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE         "watering.log"
#define SPI_CHANNEL      0
#define SPI_SPEED        500000
#define SPI_FLAGS        0
#define SAMPLE_INTERVAL  60
#define ADC_CHANNEL      0
#define ADC_MAX          1023

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_pump_state = 0;

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: invalid ADC channel requested");
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        log_event("Error: SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void control_pump(int state) {
    if (state == g_pump_state) return;
    if (gpioWrite(PUMP_GPIO, state) < 0) {
        log_event("Error: failed to write pump GPIO");
        return;
    }
    g_pump_state = state;
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump %s", state ? "ON" : "OFF");
    log_event(msg);
}

static void cleanup(void) {
    if (g_pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        g_pump_state = 0;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);
    g_pump_state = 0;

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            log_event("Error: ADC read failed; skipping cycle");
        } else {
            int moisture = (adc * 100) / ADC_MAX;
            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture: %d%% (ADC: %d)", moisture, adc);
            log_event(msg);

            if (moisture < MOISTURE_THRESHOLD && !g_pump_state) {
                control_pump(1);
            } else if (moisture >= MOISTURE_THRESHOLD && g_pump_state) {
                control_pump(0);
            }
        }
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    log_event("Program terminated");
    cleanup();
    return EXIT_SUCCESS;
}

