/*
 * rpi_led_control.c — MQTT LED controller for Raspberry Pi 4 Model B
 *
 * Build:  gcc -O2 -Wall -Wextra -o rpi_led_control rpi_led_control.c \
 *              -ljson-c -lmosquitto -lpigpio -lpthread
 *
 * Requires: libjson-c-dev, libmosquitto-dev, pigpio (libpigpio-dev)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>
#include <pigpio.h>

#include <json-c/json.h>

#include <mosquitto.h>

#define MQTT_HOST      "mqtt.eclipseprojects.io"
#define MQTT_PORT      1883
#define MQTT_TOPIC     "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN       17
#define MAX_PAYLOAD    256
#define MAX_RECONNECT  60

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_msg(const char *level, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] [%s] %s\n", ts, level, msg);
}

/* ------------------------------------------------------------------ */
/* GPIO                                                                */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        log_msg("ERROR", "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_msg("ERROR", "Failed to set GPIO17 as output");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        log_msg("ERROR", "Failed to initialise GPIO17 LOW");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void gpio_set_led(int state)
{
    if (gpioWrite(GPIO_PIN, state ? 1 : 0) != 0) {
        log_msg("ERROR", "gpioWrite failed for LED control");
    }
}

static void gpio_cleanup(void)
{
    gpio_set_led(0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* JSON parsing                                                       */
/* ------------------------------------------------------------------ */
static int parse_led_state(const char *payload, int payload_len)
{
    json_object *root = json_tokener_parse_len(payload, payload_len);
    if (!root) {
        log_msg("ERROR", "JSON parse failed");
        return -1;
    }

    json_object *led_obj = NULL;
    if (!json_object_object_get_ex(root, "led_state", &led_obj)) {
        log_msg("ERROR", "JSON key 'led_state' not found");
        json_object_put(root);
        return -1;
    }

    if (!json_object_is_type(led_obj, json_type_boolean)) {
        log_msg("ERROR", "JSON value 'led_state' is not a boolean");
        json_object_put(root);
        return -1;
    }

    int state = json_object_get_boolean(led_obj);
    json_object_put(root);
    return state;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                     */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata,
                       int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        log_msg("INFO", "Connected to MQTT broker");
        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            log_msg("ERROR", "Failed to subscribe to topic");
        }
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "Connect error: %s",
                 mosquitto_connack_string(result));
        log_msg("ERROR", buf);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata,
                          int rc)
{
    (void)mosq;
    (void)userdata;
    if (rc == 0) {
        log_msg("INFO", "Disconnected cleanly");
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "Unexpected disconnect: %s",
                 mosquitto_strerror(rc));
        log_msg("ERROR", buf);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (!message || !message->payload || message->payloadlen <= 0) {
        log_msg("ERROR", "Empty or invalid MQTT message received");
        return;
    }

    int led_state = parse_led_state((const char *)message->payload,
                                    message->payloadlen);
    if (led_state < 0) {
        log_msg("ERROR", "Invalid payload received");
        return;
    }

    gpio_set_led(led_state);
    printf("LED set to %s\n", led_state ? "ON" : "OFF");
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        log_msg("ERROR", "mosquitto_new failed");
        gpio_cleanup();
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf), "mosquitto_connect failed: %s",
                 mosquitto_strerror(rc));
        log_msg("ERROR", buf);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        gpio_cleanup();
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(g_mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf), "mosquitto_loop_start failed: %s",
                 mosquitto_strerror(rc));
        log_msg("ERROR", buf);
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        gpio_cleanup();
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    log_msg("INFO", "MQTT client started, waiting for messages...");

    while (g_running) {
        sleep(1);
    }

    log_msg("INFO", "Shutting down...");

    mosquitto_loop_stop(g_mosq, false);
    mosquitto_disconnect(g_mosq);
    mosquitto_destroy(g_mosq);
    g_mosq = NULL;

    gpio_cleanup();
    mosquitto_lib_cleanup();

    log_msg("INFO", "Clean exit");
    return EXIT_SUCCESS;
}

