#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    18
#define POLL_DELAY_US    100000   /* 100 ms */
#define ALARM_DURATION_US 1000000 /* 1 s   */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int ret;
    int sound_level;
    int prev_sound = -1; /* force first print */

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        fprintf(stderr, "Ensure pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }

    /* Configure sound sensor pin as input */
    ret = gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n", SOUND_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alarm LED pin as output */
    ret = gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (code %d).\n", ALARM_LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    ret = gpioWrite(ALARM_LED_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d (code %d).\n", ALARM_LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started.\n");
    printf("  Sensor DO : GPIO%d\n", SOUND_SENSOR_PIN);
    printf("  Alarm LED : GPIO%d\n", ALARM_LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        /* Read sound sensor digital output */
        sound_level = gpioRead(SOUND_SENSOR_PIN);
        if (sound_level < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d (code %d).\n", SOUND_SENSOR_PIN, sound_level);
            break;
        }

        /* KY-038 DO goes LOW when sound exceeds threshold */
        if (sound_level == 0) {
            printf("Sound detected! (DO=0)\n");
            fflush(stdout);

            /* Turn alarm LED on */
            ret = gpioWrite(ALARM_LED_PIN, 1);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to turn on alarm LED (code %d).\n", ret);
                break;
            }

            /* Wait for alarm duration, checking for shutdown signal */
            uint32_t elapsed = 0;
            while (running && elapsed < ALARM_DURATION_US) {
                gpioDelay(10000); /* 10 ms chunks */
                elapsed += 10000;
            }

            /* Turn alarm LED off */
            ret = gpioWrite(ALARM_LED_PIN, 0);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to turn off alarm LED (code %d).\n", ret);
                break;
            }
        } else {
            /* Print only on state change to avoid flooding the console */
            if (sound_level != prev_sound) {
                printf("Sound level: %d\n", sound_level);
                fflush(stdout);
                prev_sound = sound_level;
            }
        }

        /* 100 ms delay between reads */
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: ensure LED is off and release pigpio resources */
    gpioWrite(ALARM_LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

