    ret = gpioWrite(ALARM_LED_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d (code %d).\n", ALARM_LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started.\n");
    printf("  Sensor DO : GPIO%d\n", SOUND_SENSOR_PIN);
    printf("  Alarm LED : GPIO%d\n", ALARM_LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        /* Read sound sensor digital output */
        sound_level = gpioRead(SOUND_SENSOR_PIN);
        if (sound_level < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d (code %d).\n", SOUND_SENSOR_PIN, sound_level);
            break;
        }

        /* KY-038 DO goes LOW when sound exceeds threshold */
        if (sound_level == 0) {
            printf("Sound detected! (DO=0)\n");
            fflush(stdout);

            /* Turn alarm LED on */
            ret = gpioWrite(ALARM_LED_PIN, 1);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to turn on alarm LED (code %d).\n", ret);
                break;
            }

            /* Wait for alarm duration, checking for shutdown signal */
            uint32_t elapsed = 0;
            while (running && elapsed < ALARM_DURATION_US) {
                gpioDelay(10000); /* 10 ms chunks */
                elapsed += 10000;
            }

            /* Turn alarm LED off */
            ret = gpioWrite(ALARM_LED_PIN, 0);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to turn off alarm LED (code %d).\n", ret);
                break;
            }
        } else {
            /* Print only on state change to avoid flooding the console */
            if (sound_level != prev_sound) {
                printf("Sound level: %d\n", sound_level);
                fflush(stdout);
                prev_sound = sound_level;
            }
        }

        /* 100 ms delay between reads */
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: ensure LED is off and release pigpio resources */
    gpioWrite(ALARM_LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

