#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP   "/dev/gpiochip0"
#define GPIO_LINE   17
#define LOG_FILE    "/var/log/vibration_shutdown.log"
#define CONSUMER    "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }

    if (fclose(fp) != 0) {
        perror("fclose log file");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    int chip_fd = open(GPIO_CHIP, O_RDWR);
    if (chip_fd < 0) {
        perror("open " GPIO_CHIP);
        return EXIT_FAILURE;
    }

    struct gpio_get_line_info gil;
    memset(&gil, 0, sizeof(gil));
    gil.line_offset = GPIO_LINE;

    if (ioctl(chip_fd, GPIO_GET_LINEINFO, &gil) < 0) {
        perror("GPIO_GET_LINEINFO");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    if (gil.line_count < 1) {
        fprintf(stderr, "GPIO line %d not available on %s\n", GPIO_LINE, GPIO_CHIP);
        close(chip_fd);
        return EXIT_FAILURE;
    }

    struct gpio_request_line req;
    memset(&req, 0, sizeof(req));
    req.line_offset = GPIO_LINE;
    req.consumer = CONSUMER;
    req.request_type = GPIO_LINE_REQUEST_EVENT_FALLING_EDGE;

    if (ioctl(chip_fd, GPIO_REQUEST_LINE, &req) < 0) {
        perror("GPIO_REQUEST_LINE");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    printf("Monitoring SW-420 vibration sensor on GPIO%d (BCM) for falling edges...\n", GPIO_LINE);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        struct gpio_event_event_buffer event_buffer;
        memset(&event_buffer, 0, sizeof(event_buffer));

        int ret = ioctl(chip_fd, GPIO_GET_LINEEVENT, &event_buffer);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("GPIO_GET_LINEEVENT");
            break;
        }

        if (ret == 0) {
            continue;
        }

        struct gpio_event_event *event = &event_buffer.events[0];
        if (event->event_type == GPIO_EVENT_FALLING_EDGE) {
            char timestamp[32];
            time_t t = time(NULL);
            struct tm tm;
            if (localtime_r(&t, &tm)) {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
            } else {
                snprintf(timestamp, sizeof(timestamp), "unknown");
            }

            char log_message[128];
            snprintf(log_message, sizeof(log_message),
                     "Vibration detected at %s (GPIO%d)", timestamp, GPIO_LINE);

            if (log_event(log_message) != 0) {
                fprintf(stderr, "Failed to log event.\n");
            }

            printf("%s\n", log_message);

            if (system("sudo shutdown -h now") == -1) {
                perror("system() shutdown");
            }
            break;
        }
    }

    if (ioctl(chip_fd, GPIO_RELEASE_LINE, &req) < 0) {
        perror("GPIO_RELEASE_LINE");
    }
    if (close(chip_fd) < 0) {
        perror("close gpiochip");
    }

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

