/*
 * BMP280 altitude logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   BMP280 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   BMP280 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   BMP280 VDD  -> 3.3 V (NOT 5 V)
 *   BMP280 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_logger bmp280_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- BMP280 register map ---- */
#define BMP280_REG_ID          0xD0
#define BMP280_REG_RESET       0xE0
#define BMP280_REG_CTRL_MEAS   0xF4
#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB       0x88

#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_CMD       0xB6

/* ---- Calibration coefficients ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1)  return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

/* ---- BMP280 driver ---- */
typedef struct {
    int32_t  t_fine;
    bmp280_calib_t cal;
} bmp280_t;

static int bmp280_init(bmp280_t *dev, int fd)
{
    uint8_t id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &id) != 0) {
        fprintf(stderr, "Error: cannot read BMP280 chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: BMP280 not found (chip ID=0x%02X, expected 0x%02X)\n",
                id, BMP280_CHIP_ID);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg8(fd, BMP280_REG_RESET, BMP280_RESET_CMD) != 0) {
        fprintf(stderr, "Error: BMP280 reset write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000); /* 2 ms settle after reset */

    /* Config: t_sb=0.5ms (000), filter=4 (010), spi3w_en=0 */
    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, 0x04) != 0) {
        fprintf(stderr, "Error: BMP280 config write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Ctrl: osrs_t=x1 (001), osrs_p=x1 (001), mode=normal (11) -> 0x27 */
    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error: BMP280 ctrl write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Read calibration block (24 bytes from 0x88) */
    uint8_t cal[24];
    if (i2c_read_burst(fd, BMP280_REG_CALIB, cal, sizeof(cal)) != 0) {
        fprintf(stderr, "Error: BMP280 calibration read failed: %s\n", strerror(errno));
        return -1;
    }

    dev->cal.dig_T1 = (uint16_t)(cal[0]  | (cal[1]  << 8));
    dev->cal.dig_T2 = (int16_t)(cal[2]  | (cal[3]  << 8));
    dev->cal.dig_T3 = (int16_t)(cal[4]  | (cal[5]  << 8));
    dev->cal.dig_P1 = (uint16_t)(cal[6]  | (cal[7]  << 8));
    dev->cal.dig_P2 = (int16_t)(cal[8]  | (cal[9]  << 8));
    dev->cal.dig_P3 = (int16_t)(cal[10] | (cal[11] << 8));
    dev->cal.dig_P4 = (int16_t)(cal[12] | (cal[13] << 8));
    dev->cal.dig_P5 = (int16_t)(cal[14] | (cal[15] << 8));
    dev->cal.dig_P6 = (int16_t)(cal[16] | (cal[17] << 8));
    dev->cal.dig_P7 = (int16_t)(cal[18] | (cal[19] << 8));
    dev->cal.dig_P8 = (int16_t)(cal[20] | (cal[21] << 8));
    dev->cal.dig_P9 = (int16_t)(cal[22] | (cal[23] << 8));

    return 0;
}

static int bmp280_read_raw(bmp280_t *dev, int32_t *raw_t, int32_t *raw_p)
{
    uint8_t d[6];
    if (i2c_read_burst(g_i2c_fd, BMP280_REG_PRESS_MSB, d, 6) != 0) {
        fprintf(stderr, "Error: BMP280 data read failed: %s\n", strerror(errno));
        return -1;
    }
    *raw_p = ((int32_t)d[0] << 12) | ((int32_t)d[1] << 4) | (d[2] >> 4);
    *raw_t = ((int32_t)d[3] << 12) | ((int32_t)d[4] << 4) | (d[5] >> 4);
    return 0;
}

/* Returns temperature in degrees Celsius; sets *t_fine for altitude calc. */
static int32_t bmp280_compensate_temp(bmp280_t *dev, int32_t raw_t)
{
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)dev->cal.dig_T1 << 1)))
            * ((int32_t)dev->cal.dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)dev->cal.dig_T1))
              * ((raw_t >> 4) - ((int32_t)dev->cal.dig_T1))) >> 12)
            * ((int32_t)dev->cal.dig_T3)) >> 14;
    dev->t_fine = var1 + var2;
    return (dev->t_fine * 5 + 128) >> 8; /* centi-degrees */
}

/* Returns pressure in Pa; uses t_fine from the previous call. */
static uint32_t bmp280_compensate_press(bmp280_t *dev, int32_t raw_p)
{
    int64_t var1, var2, p;
    var1 = ((int64_t)dev->t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)dev->cal.dig_P6;
    var2 = var2 + ((var1 * (int64_t)dev->cal.dig_P5) << 17);
    var2 = var2 + (((int64_t)dev->cal.dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)dev->cal.dig_P3) >> 8)
          + ((var1 * (int64_t)dev->cal.dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)dev->cal.dig_P1) >> 33;
    if (var1 == 0) return 0; /* avoid div-by-zero */
    p = 1048576 - raw_p;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)dev->cal.dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)dev->cal.dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)dev->cal.dig_P7) << 4);
    return (uint32_t)p; /* Pa */
}

static float bmp280_compensate_altitude(bmp280_t *dev, uint32_t pressure_pa)
{
    /* Approximate geometric altitude from sea level (1013.25 hPa). */
    return 44330.0f * (1.0f - powf((float)pressure_pa / 101325.0f, 0.1903f));
}

/* ---- Logging ---- */
static int log_open(FILE **fp)
{
    *fp = fopen("altitude_log.txt", "a");
    if (!*fp) {
        fprintf(stderr, "Error: cannot open altitude_log.txt: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void log_write(FILE *fp, float altitude)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, altitude);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: cannot open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x76) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave 0x76: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Initialize sensor */
    bmp280_t bmp;
    if (bmp280_init(&bmp, g_i2c_fd) != 0) {
        fprintf(stderr, "Error: BMP280 initialization failed.\n");
        cleanup();
        return 1;
    }

    /* Open log file */
    if (log_open(&g_log_fp) != 0) {
        cleanup();
        return 1;
    }

    printf("BMP280 initialized. Logging altitude to altitude_log.txt every 5 s.\n");
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(&bmp, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "Warning: read failed, retrying next cycle.\n");
            sleep(5);
            continue;
        }

        int32_t temp_c = bmp280_compensate_temp(&bmp, raw_t);
        uint32_t press_pa = bmp280_compensate_press(&bmp, raw_p);
        float alt = bmp280_compensate_altitude(&bmp, press_pa);

        log_write(g_log_fp, alt);
        printf("Altitude: %.2f m\n", alt);

        /* Sleep 5 s, but wake early on signal */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

