#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define BUFFER_SIZE     120
#define SAMPLE_INTERVAL 5
#define ADC_CHANNEL     0
#define ADC_MAX         1023.0f
#define LM35_SCALE      10.0f

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    g_spi_fd = fd;
    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static float read_temperature(void)
{
    if (g_spi_fd < 0) {
        fprintf(stderr, "SPI device not initialized\n");
        return -1.0f;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | ADC_CHANNEL) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    if (spi_transfer(tx, rx, sizeof(tx)) < 0) {
        return -1.0f;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return ((float)adc_value / ADC_MAX) * LM35_SCALE;
}

static void buffer_add(float *buffer, int size, float value)
{
    for (int i = 0; i < size - 1; i++) {
        buffer[i] = buffer[i + 1];
    }
    buffer[size - 1] = value;
}

static void buffer_print(const float *buffer, int size)
{
    for (int i = 0; i < size; i++) {
        printf("Temperature: %.2f °C\n", buffer[i]);
    }
}

static int buffer_save(const float *buffer, int size, const char *filename)
{
    FILE *fp = fopen(filename, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t elements = (size_t)size;
    size_t written = fwrite(buffer, sizeof(float), elements, fp);
    if (written != elements) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fseek(fp, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Error seeking in file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    float temperature_buffer[BUFFER_SIZE];
    memset(temperature_buffer, 0, sizeof(temperature_buffer));

    while (g_running) {
        float temperature = read_temperature();

        if (temperature < 0.0f) {
            fprintf(stderr, "Error reading temperature, skipping sample\n");
        } else {
            buffer_add(temperature_buffer, BUFFER_SIZE, temperature);
            buffer_print(temperature_buffer, BUFFER_SIZE);

            if (buffer_save(temperature_buffer, BUFFER_SIZE, "temp_log.dat") < 0) {
                fprintf(stderr, "Error saving temperature data to file\n");
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("\nExiting gracefully...\n");
    return 0;
}

