#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define RAIN_THRESHOLD 5
#define PWM_RANGE 255
#define PWM_DUTY 150
#define MOTOR_FORWARD_TIME 3
#define POLL_INTERVAL 1

#define GPIO_CHIP "gpiochip0"
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_ENA_PIN 27

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *in1_line = NULL;
static struct gpiod_line *in2_line = NULL;
static struct gpiod_line *ena_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    if (!in1_line || !in2_line || !ena_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(in1_line, "rain-motor", 0) < 0 ||
        gpiod_line_request_output(in2_line, "rain-motor", 0) < 0 ||
        gpiod_line_request_output(ena_line, "rain-motor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO lines as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_rain_level(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void control_motor(int rain_level) {
    if (rain_level > RAIN_THRESHOLD) {
        printf("Rain level exceeded threshold. Closing window.\n");
        gpiod_line_set_value(in1_line, 0);
        gpiod_line_set_value(in2_line, 1);
        gpiod_line_set_value(ena_line, PWM_DUTY);
        sleep(MOTOR_FORWARD_TIME);
        gpiod_line_set_value(ena_line, 0);
        gpiod_line_set_value(in1_line, 0);
        gpiod_line_set_value(in2_line, 0);
    } else {
        printf("Rain level below threshold. Opening window.\n");
        gpiod_line_set_value(in1_line, 1);
        gpiod_line_set_value(in2_line, 0);
        gpiod_line_set_value(ena_line, PWM_DUTY);
        sleep(MOTOR_FORWARD_TIME);
        gpiod_line_set_value(ena_line, 0);
        gpiod_line_set_value(in1_line, 0);
        gpiod_line_set_value(in2_line, 0);
    }
}

static void cleanup(void) {
    if (in1_line) gpiod_line_set_value(in1_line, 0);
    if (in2_line) gpiod_line_set_value(in2_line, 0);
    if (ena_line) gpiod_line_set_value(ena_line, 0);

    if (in1_line) gpiod_line_release(in1_line);
    if (in2_line) gpiod_line_release(in2_line);
    if (ena_line) gpiod_line_release(ena_line);
    if (chip) gpiod_chip_close(chip);

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Error reading rain sensor.\n");
        } else {
            log_rain_level(rain_level);
            control_motor(rain_level);
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

