/*
 * MAX9814 Electret Microphone Clap Detector for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MAX9814 OUT  -> BCM GPIO26 (ADC0)
 *   MAX9814 VDD  -> 3.3 V (Pin 1)
 *   MAX9814 GND  -> GND   (Pin 6)
 *   LED anode    -> BCM GPIO16 (Pin 36) via 330 ohm resistor
 *   LED cathode  -> GND
 *
 * Build: gcc -O2 -Wall -Wextra -o clap_detector clap_detector.c -lpigpio -lrt
 * Run:   sudo ./clap_detector
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADC_GPIO          26
#define LED_GPIO          16
#define SAMPLE_RATE_HZ    1000
#define SAMPLE_PERIOD_US  (1000000 / SAMPLE_RATE_HZ)
#define ADC_CHANNEL       0
#define ADC_RANGE         1024
#define THRESHOLD         500
#define DEBOUNCE_MS       50
#define LED_ON_MS         500
#define POLL_DELAY_US     10000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single sample from the pigpio ADC on the given channel.
 * Returns 0 on success, -1 on error.
 */
static int read_adc(int channel, int *value)
{
    int raw = gpioReadADC(channel);
    if (raw < 0) {
        fprintf(stderr, "Error: gpioReadADC failed on channel %d (rc=%d)\n",
                channel, raw);
        return -1;
    }
    *value = raw;
    return 0;
}

/*
 * Detect a clap event by detecting a local maximum in the sample buffer.
 * Returns 1 if a clap is detected, 0 otherwise.
 */
static int detect_clap(const int *buffer, int size)
{
    if (size < 3)
        return 0;

    for (int i = 1; i < size - 1; i++) {
        if (buffer[i] > buffer[i - 1] && buffer[i] > buffer[i + 1])
            return 1;
    }
    return 0;
}

static void log_timestamped_event(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Clap detected!\n", ts);
    } else {
        printf("[unknown time] Clap detected!\n");
    }
    fflush(stdout);
}

int main(void)
{
    int buffer[DEBOUNCE_MS * SAMPLE_RATE_HZ / 1000];
    int buffer_index = 0;
    bool clap_active = false;
    struct timespec last_event_time = {0, 0};

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure ADC GPIO as input --- */
    if (gpioSetMode(ADC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ADC GPIO %d as input.\n", ADC_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO as output and ensure it starts OFF --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED GPIO %d to LOW.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = 0;
        if (read_adc(ADC_CHANNEL, &adc_value) != 0) {
            /* Bus error: turn off LED and back off pigpio */
            gpioWrite(LED_GPIO, 0);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        buffer[buffer_index] = adc_value;
        buffer_index = (buffer_index + 1) % (DEBOUNCE_MS * SAMPLE_RATE_HZ / 1000);

        if (detect_clap(buffer, DEBOUNCE_MS * SAMPLE_RATE_HZ / 1000)) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            long elapsed_ms = (now.tv_sec - last_event_time.tv_sec) * 1000L +
                              (now.tv_nsec - last_event_time.tv_nsec) / 1000000L;

            if (!clap_active || elapsed_ms >= DEBOUNCE_MS) {
                clap_active = true;
                last_event_time = now;

                log_timestamped_event();

                if (gpioWrite(LED_GPIO, 1) != 0) {
                    fprintf(stderr, "Warning: failed to turn on LED.\n");
                }
                gpioDelay(LED_ON_MS * 1000); /* 500 ms */
                if (gpioWrite(LED_GPIO, 0) != 0) {
                    fprintf(stderr, "Warning: failed to turn off LED.\n");
                }
            }
        } else {
            clap_active = false;
        }

        gpioDelay(POLL_DELAY_US); /* 10 ms */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

