#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_US 1000000
#define RETRY_DELAY_US 1000000

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int export_gpio(int pin) {
    char buf[64];
    FILE *fp;

    snprintf(buf, sizeof(buf), "/sys/class/gpio/export");
    fp = fopen(buf, "w");
    if (!fp) {
        if (errno == EBUSY) return 0;
        perror("fopen(export)");
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

static int unexport_gpio(int pin) {
    char buf[64];
    FILE *fp;

    snprintf(buf, sizeof(buf), "/sys/class/gpio/unexport");
    fp = fopen(buf, "w");
    if (!fp) {
        perror("fopen(unexport)");
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

static int set_gpio_direction(int pin, const char *dir) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (!fp) {
        perror("fopen(direction)");
        return -1;
    }
    fprintf(fp, "%s", dir);
    fclose(fp);
    return 0;
}

static int read_gpio_value(int pin) {
    char path[64];
    FILE *fp;
    int value;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "r");
    if (!fp) {
        perror("fopen(value)");
        return -1;
    }
    if (fscanf(fp, "%d", &value) != 1) {
        fprintf(stderr, "fscanf(value) failed\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return value;
}

static int log_distance(int distance) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("localtime");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return -1;
    }
    fprintf(fp, "%s, %d\n", timestamp, distance);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (export_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO%d\n", GPIO_PIN);
        return EXIT_FAILURE;
    }

    if (set_gpio_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO%d direction\n", GPIO_PIN);
        unexport_gpio(GPIO_PIN);
        return EXIT_FAILURE;
    }

    printf("Feeder control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int distance = read_gpio_value(GPIO_PIN);
        if (distance < 0) {
            fprintf(stderr, "Error reading GPIO%d, retrying in 1s...\n", GPIO_PIN);
            usleep(RETRY_DELAY_US);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance, retrying in 1s...\n");
            usleep(RETRY_DELAY_US);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    unexport_gpio(GPIO_PIN);
    printf("GPIO%d unexported.\n", GPIO_PIN);
    return EXIT_SUCCESS;
}

