#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define ADC_CHANNEL    0
#define LED_PIN        21
#define THRESHOLD      10.0f
#define LOG_FILE       "magnetic_log.txt"
#define SAMPLE_US      100000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_magnetic_field(int adc_value)
{
    /* Placeholder linear conversion; adjust for your specific sensor */
    return (float)adc_value * 0.1f;
}

static void log_reading(FILE *fp, float field)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f mT\n", ts, field);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen log file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float field = adc_to_magnetic_field(adc);
        log_reading(log_fp, field);

        if (field > THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_US);
    }

    /* Graceful cleanup */
    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_fp);

    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

