#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* mode 0, active-low CE */
#define ADC_CHANNEL    0
#define VREF           5.0
#define MAX_VOLTAGE    5.0
#define MIN_VOLTAGE    0.0
#define SAMPLE_PERIOD  100000   /* microseconds (100 ms) */
#define LOG_FILE       "current_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static double adc_to_voltage(int adc_value)
{
    return ((double)adc_value / 1023.0) * VREF;
}

static double voltage_to_current(double voltage)
{
    /*
     * MLX91211: 0.1–5.0 V corresponds to 0–20 A.
     * Linear approximation: 0.1 V -> 0 A, 5.0 V -> 20 A.
     */
    return (voltage - 0.1) / 4.9 * 20.0;
}

static void log_current(FILE *fp, double current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s %.2f A\n", timestamp, current);
    fflush(fp);
}

int main(void)
{
    int spi_handle = -1;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI bus --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        goto cleanup_gpio;
    }

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        goto cleanup_spi;
    }

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("MLX91211 current sensor logging started. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error; skipping sample\n");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
            fprintf(stderr, "Warning: voltage %.2f V out of range [%.1f, %.1f]; skipping sample\n",
                    voltage, MIN_VOLTAGE, MAX_VOLTAGE);
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        double current = voltage_to_current(voltage);
        log_current(log_fp, current);

        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

    /* --- Cleanup --- */
    if (log_fp != NULL) {
        fclose(log_fp);
    }
cleanup_spi:
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

