#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio_pin) {
    int value = 1;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int v = gpioRead(gpio_pin);
        if (v < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(v));
            return -1;
        }
        if (v == 0) value = 0;
        if (i < DEBOUNCE_READINGS - 1) gpioDelay(DEBOUNCE_DELAY_US);
    }
    return value;
}

static void log_sensor_data(int sensor1_value, int sensor2_value) {
    printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_value, sensor2_value);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor data, exiting\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        log_sensor_data(sensor1_value, sensor2_value);

        if (sensor1_value == 0 && sensor2_value == 0) {
            printf("ALERT: Both sensors detect object\n");
            fflush(stdout);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

