/*
 * PIR Motion Detector with Camera Capture for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   HC-SR501 VCC -> 5V (Pin 2 or 4)
 *   HC-SR501 GND -> GND (Pin 6)
 *   HC-SR501 OUT -> GPIO17 (Pin 11, BCM 17)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pir_cam pir_cam.c -lpthread
 *
 * Run:
 *   sudo ./pir_cam
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <pthread.h>
#include <gpiod.h>

#define PIR_PIN          17
#define POLL_INTERVAL_MS 50
#define DEBOUNCE_MS      200
#define CAPTURE_DIR      "/home/pi/security_cam"
#define MAX_FILENAME     256
#define MAX_CMDLINE      512

static volatile sig_atomic_t g_running = 1;
static pthread_mutex_t      g_log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void log_msg(int priority, const char *msg)
{
    pthread_mutex_lock(&g_log_mutex);
    syslog(priority, "%s", msg);
    pthread_mutex_unlock(&g_log_mutex);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        log_msg(LOG_ERR, "Target path exists but is not a directory");
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        log_msg(LOG_ERR, "Failed to create capture directory");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename)
{
    char command[MAX_CMDLINE];
    char dir_arg[64];
    char file_arg[64];

    snprintf(dir_arg, sizeof(dir_arg), "--location=%s", CAPTURE_DIR);
    snprintf(file_arg, sizeof(file_arg), "--filename=%s", filename);

    snprintf(command, sizeof(command),
             "libcamera-still --nopreview --timeout 1000 %s %s 2>&1",
             dir_arg, file_arg);

    log_msg(LOG_INFO, "Capturing image...");
    int status = system(command);
    if (status == -1) {
        log_msg(LOG_ERR, "system() failed to launch libcamera-still");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        log_msg(LOG_ERR, "libcamera-still exited with non-zero status");
        return -1;
    }
    log_msg(LOG_INFO, "Image captured successfully");
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo);
}

static int generate_filename(char *filename, size_t len)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    return snprintf(filename, len, "%s_%s.jpg", ts, "motion");
}

int main(void)
{
    openlog("pir_cam", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_msg(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_msg(LOG_ERR, "Failed to open gpiochip4");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_msg(LOG_ERR, "Failed to get GPIO17 line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input_flags(pir_line, "pir_cam",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) != 0) {
        log_msg(LOG_ERR, "Failed to request GPIO17 as input with pull-down");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    log_msg(LOG_INFO, "PIR motion detector started (GPIO17)");

    int last_state = gpiod_line_get_value(pir_line);
    if (last_state < 0) {
        log_msg(LOG_ERR, "Initial read of PIR line failed");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int current_state = gpiod_line_get_value(pir_line);
        if (current_state < 0) {
            log_msg(LOG_ERR, "Failed to read PIR line");
            break;
        }

        if (current_state != last_state) {
            log_msg(LOG_INFO, "Motion detected (state change)");
            usleep(DEBOUNCE_MS * 1000);

            int confirmed = gpiod_line_get_value(pir_line);
            if (confirmed < 0) {
                log_msg(LOG_ERR, "Failed to re-read PIR line after debounce");
                break;
            }
            if (confirmed == current_state) {
                char filename[MAX_FILENAME];
                if (generate_filename(filename, sizeof(filename)) < 0) {
                    log_msg(LOG_ERR, "Filename generation failed");
                    break;
                }

                if (capture_image(filename) == 0) {
                    char log_msg_buf[256];
                    snprintf(log_msg_buf, sizeof(log_msg_buf),
                             "Motion captured: %s", filename);
                    log_msg(LOG_INFO, log_msg_buf);
                } else {
                    log_msg(LOG_ERR, "Image capture failed");
                }
            }
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_msg(LOG_INFO, "Shutting down...");
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

