#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH  192
#define IMAGE_HEIGHT 108
#define NUM_BUFFERS  4
#define IMAGE_FILE   "image.jpg"

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_streamparm parm;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    enum v4l2_buf_type type;
    enum v4l2_field field;
    unsigned char *buffer = NULL;
    unsigned char *mmap_ptr = NULL;
    size_t buffer_size = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    memset(&fmtdesc, 0, sizeof(fmtdesc));
    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    while (xioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0) {
        if (fmtdesc.pixelformat == V4L2_PIX_FMT_MJPEG) {
            break;
        }
        fmtdesc.index++;
    }
    if (fmtdesc.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "MJPEG format not supported\n");
        goto cleanup;
    }

    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;
    frmsize.pixel_format = fmtdesc.pixelformat;
    while (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE &&
            frmsize.discrete.width == IMAGE_WIDTH &&
            frmsize.discrete.height == IMAGE_HEIGHT) {
            break;
        }
        frmsize.index++;
    }
    if (frmsize.index >= 0x7FFFFFFF) {
        fprintf(stderr, "Frame size %dx%d not found\n", IMAGE_WIDTH, IMAGE_HEIGHT);
        goto cleanup;
    }

    memset(&frmival, 0, sizeof(frmival));
    frmival.index = 0;
    frmival.pixel_format = fmtdesc.pixelformat;
    frmival.width = IMAGE_WIDTH;
    frmival.height = IMAGE_HEIGHT;
    while (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            break;
        }
        frmival.index++;
    }
    if (frmival.index >= 0x7FFFFFFF) {
        fprintf(stderr, "Frame interval not found\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    memset(&parm, 0, sizeof(parm));
    parm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    parm.parm.capture.timeperframe.numerator = 1;
    parm.parm.capture.timeperframe.denominator = 30;
    if (xioctl(fd, VIDIOC_S_PARM, &parm) == -1) {
        perror("VIDIOC_S_PARM");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    buffer = calloc(req.count, sizeof(*buffer));
    if (!buffer) {
        perror("calloc");
        goto cleanup;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }
        mmap_ptr = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (mmap_ptr == MAP_FAILED) {
            perror("mmap");
            mmap_ptr = NULL;
            goto cleanup;
        }
        buffer[i] = (unsigned char)(uintptr_t)mmap_ptr;
        buffer_size += buf.length;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    if (stop_flag) {
        goto streamoff;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto streamoff;
    }

    if (buf.bytesused > 0) {
        FILE *fp = fopen(IMAGE_FILE, "wb");
        if (!fp) {
            perror("fopen(" IMAGE_FILE ")");
            goto streamoff;
        }
        size_t written = fwrite(buffer, 1, buf.bytesused, fp);
        if (written != (size_t)buf.bytesused) {
            perror("fwrite");
            fclose(fp);
            goto streamoff;
        }
        if (fclose(fp) != 0) {
            perror("fclose");
            goto streamoff;
        }
        printf("Saved %zu bytes to %s\n", written, IMAGE_FILE);
        ret = EXIT_SUCCESS;
    } else {
        fprintf(stderr, "No data in frame\n");
    }

streamoff:
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
    }

cleanup:
    if (mmap_ptr && mmap_ptr != MAP_FAILED) {
        munmap(mmap_ptr, buffer_size);
    }
    if (buffer) {
        free(buffer);
    }
    if (fd != -1) {
        close(fd);
    }
    return ret;
}

