/*
 * Pan-tilt mount controller for Raspberry Pi using software PWM on
 * the GPIO hardware PWM bus (BCM 4/5) and active-low buttons with
 * internal pull-ups (BCM 6-9).  50 Hz PWM period, 1-2 ms pulse width
 * (duty 50-100), mid-position 75, range 25-125.
 *
 * Build:  gcc -O2 -Wall -o pan_tilt pan_tilt.c -lpigpio -lrt
 * Run:    sudo ./pan_tilt
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN      4
#define TILT_SERVO_PIN     5

#define TILT_UP_PIN        6
#define TILT_DOWN_PIN      7
#define PAN_LEFT_PIN       8
#define PAN_RIGHT_PIN      9

#define PWM_FREQ_HZ        50
#define PWM_RANGE          1000
#define PWM_DUTY_MIN       50
#define PWM_DUTY_MAX       100
#define PWM_DUTY_MID       75
#define PWM_PULSE_MIN_US   1000   /* 1.0 ms */
#define PWM_PULSE_MAX_US   2000   /* 2.0 ms */
#define POLL_DELAY_US      50000  /* 50 ms */
#define DEBOUNCE_US        20000  /* 20 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", PAN_SERVO_PIN);
        return -1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", TILT_SERVO_PIN);
        return -1;
    }

    if (gpioSetMode(TILT_UP_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TILT_UP_PIN);
        return -1;
    }
    if (gpioSetMode(TILT_DOWN_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TILT_DOWN_PIN);
        return -1;
    }
    if (gpioSetMode(PAN_LEFT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", PAN_LEFT_PIN);
        return -1;
    }
    if (gpioSetMode(PAN_RIGHT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", PAN_RIGHT_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", TILT_UP_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", TILT_DOWN_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", PAN_LEFT_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", PAN_RIGHT_PIN);
        return -1;
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", PAN_SERVO_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", TILT_SERVO_PIN);
        return -1;
    }

    if (gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", PAN_SERVO_PIN);
        return -1;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", TILT_SERVO_PIN);
        return -1;
    }

    return 0;
}

static int set_servo_pulse(int pin, int duty_percent)
{
    if (duty_percent < PWM_DUTY_MIN) duty_percent = PWM_DUTY_MIN;
    if (duty_percent > PWM_DUTY_MAX) duty_percent = PWM_DUTY_MAX;

    int pulse_us = PWM_PULSE_MIN_US +
                   (duty_percent * (PWM_PULSE_MAX_US - PWM_PULSE_MIN_US) /
                    (PWM_DUTY_MAX - PWM_DUTY_MIN));

    if (gpioPWM(pin, duty_percent) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on GPIO%d.\n", pin);
        return -1;
    }
    return 0;
}

static int clamp(int val, int lo, int hi)
{
    if (val < lo) return lo;
    if (val > hi) return hi;
    return val;
}

static int read_button(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", pin);
        return -1;
    }
    return v;
}

static void debounce_delay(void)
{
    gpioDelay(DEBOUNCE_US);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    int pan_pos = PWM_DUTY_MID;
    int tilt_pos = PWM_DUTY_MID;

    if (set_servo_pulse(PAN_SERVO_PIN, pan_pos) < 0 ||
        set_servo_pulse(TILT_SERVO_PIN, tilt_pos) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt control ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        int up    = read_button(TILT_UP_PIN);
        int down  = read_button(TILT_DOWN_PIN);
        int left  = read_button(PAN_LEFT_PIN);
        int right = read_button(PAN_RIGHT_PIN);

        if (up < 0 || down < 0 || left < 0 || right < 0) {
            break;
        }

        if (up == 0) {
            tilt_pos = clamp(tilt_pos + 5, PWM_DUTY_MIN, PWM_DUTY_MAX);
            if (set_servo_pulse(TILT_SERVO_PIN, tilt_pos) < 0) break;
            debounce_delay();
        } else if (down == 0) {
            tilt_pos = clamp(tilt_pos - 5, PWM_DUTY_MIN, PWM_DUTY_MAX);
            if (set_servo_pulse(TILT_SERVO_PIN, tilt_pos) < 0) break;
            debounce_delay();
        } else if (left == 0) {
            pan_pos = clamp(pan_pos - 5, PWM_DUTY_MIN, PWM_DUTY_MAX);
            if (set_servo_pulse(PAN_SERVO_PIN, pan_pos) < 0) break;
            debounce_delay();
        } else if (right == 0) {
            pan_pos = clamp(pan_pos + 5, PWM_DUTY_MIN, PWM_DUTY_MAX);
            if (set_servo_pulse(PAN_SERVO_PIN, pan_pos) < 0) break;
            debounce_delay();
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Stop servos and release pigpio */
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

