        } else if (down == 0) {
            tilt_pos = clamp(tilt_pos - 5, PWM_DUTY_MIN, PWM_DUTY_MAX);
            if (set_servo_pulse(TILT_SERVO_PIN, tilt_pos) < 0) break;
            debounce_delay();
        } else if (left == 0) {
            pan_pos = clamp(pan_pos - 5, PWM_DUTY_MIN, PWM_DUTY_MAX);
            if (set_servo_pulse(PAN_SERVO_PIN, pan_pos) < 0) break;
            debounce_delay();
        } else if (right == 0) {
            pan_pos = clamp(pan_pos + 5, PWM_DUTY_MIN, PWM_DUTY_MAX);
            if (set_servo_pulse(PAN_SERVO_PIN, pan_pos) < 0) break;
            debounce_delay();
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Stop servos and release pigpio */
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

