#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define VIDEO_DEVICE "/dev/video0"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define JPEG_QUALITY 75
#define BLUR_RADIUS 3
#define TIMEOUT_SEC 2

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void blur_image(unsigned char *src, unsigned char *dst, int width, int height, int radius) {
    int i, j, k, l;
    int sum_r, sum_g, sum_b;
    int x, y;
    int offset;
    int channels = 3;
    int kernel_size = 2 * radius + 1;
    int kernel_area = kernel_size * kernel_size;
    float kernel[kernel_size * kernel_size];
    float kernel_sum = 0.0f;

    for (i = 0; i < kernel_size; i++) {
        for (j = 0; j < kernel_size; j++) {
            int dx = i - radius;
            int dy = j - radius;
            float dist = sqrtf((float)(dx * dx + dy * dy));
            if (dist > radius) {
                kernel[i * kernel_size + j] = 0.0f;
            } else {
                kernel[i * kernel_size + j] = (float)(radius * radius - dist * dist) / (radius * radius);
                kernel_sum += kernel[i * kernel_size + j];
            }
        }
    }

    for (y = 0; y < height; y++) {
        for (x = 0; x < width; x++) {
            sum_r = sum_g = sum_b = 0;
            for (i = 0; i < kernel_size; i++) {
                for (j = 0; j < kernel_size; j++) {
                    int nx = x + i - radius;
                    int ny = y + j - radius;
                    if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        offset = (ny * width + nx) * channels;
                        sum_r += (int)src[offset] * kernel[i * kernel_size + j];
                        sum_g += (int)src[offset + 1] * kernel[i * kernel_size + j];
                        sum_b += (int)src[offset + 2] * kernel[i * kernel_size + j];
                    }
                }
            }
            offset = (y * width + x) * channels;
            dst[offset] = (unsigned char)(sum_r / kernel_sum);
            dst[offset + 1] = (unsigned char)(sum_g / kernel_sum);
            dst[offset + 2] = (unsigned char)(sum_b / kernel_sum);
        }
    }
}

static int encode_jpeg(unsigned char *image, int width, int height, int quality, unsigned char **out, size_t *out_size) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    unsigned char *row_pointer[1];
    int row_stride = width * 3;
    unsigned char *jpeg_buffer = NULL;
    unsigned long jpeg_size = 0;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_mem_dest(&cinfo, &jpeg_buffer, &jpeg_size);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &image[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    *out = jpeg_buffer;
    *out_size = jpeg_size;
    return 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    unsigned char *buffers = NULL;
    unsigned char *rgb_image = NULL;
    unsigned char *blurred_image = NULL;
    unsigned char *jpeg_image = NULL;
    size_t jpeg_size = 0;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = CAPTURE_WIDTH;
    fmt.fmt.pix.height = CAPTURE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffers = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffers == MAP_FAILED) {
        perror("mmap");
        buffers = NULL;
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    do {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = TIMEOUT_SEC;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("select");
            goto cleanup;
        }
        if (r == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            goto cleanup;
        }
    } while (running);

    if (!running) goto cleanup;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    int image_size = CAPTURE_WIDTH * CAPTURE_HEIGHT * 3;
    rgb_image = (unsigned char *)malloc(image_size);
    if (!rgb_image) {
        perror("malloc");
        goto cleanup;
    }

    int yuyv_size = CAPTURE_WIDTH * CAPTURE_HEIGHT * 2;
    unsigned char *yuyv_image = (unsigned char *)malloc(yuyv_size);
    if (!yuyv_image) {
        perror("malloc");
        goto cleanup;
    }

    memcpy(yuyv_image, buffers, yuyv_size);

    for (int i = 0; i < CAPTURE_HEIGHT; i++) {
        for (int j = 0; j < CAPTURE_WIDTH; j++) {
            int y = i * CAPTURE_WIDTH + j;
            int u = yuyv_size + (i / 2) * CAPTURE_WIDTH + (j / 2) * 2;
            int v = u + 1;

            int r, g, b;
            r = (int)(yuyv_image[y * 2] + 1.370705 * (yuyv_image[v] - 128));
            g = (int)(yuyv_image[y * 2] - 0.698001 * (yuyv_image[u] - 128) - 0.337633 * (yuyv_image[v] - 128));
            b = (int)(yuyv_image[y * 2] + 1.732446 * (yuyv_image[u] - 128));

            if (r < 0) r = 0; if (r > 255) r = 255;
            if (g < 0) g = 0; if (g > 255) g = 255;
            if (b < 0) b = 0; if (b > 255) b = 255;

            int rgb_offset = (i * CAPTURE_WIDTH + j) * 3;
            rgb_image[rgb_offset] = (unsigned char)b;
            rgb_image[rgb_offset + 1] = (unsigned char)g;
            rgb_image[rgb_offset + 2] = (unsigned char)r;
        }
    }

    blurred_image = (unsigned char *)malloc(image_size);
    if (!blurred_image) {
        perror("malloc");
        goto cleanup;
    }

    blur_image(rgb_image, blurred_image, CAPTURE_WIDTH, CAPTURE_HEIGHT, BLUR_RADIUS);

    if (encode_jpeg(blurred_image, CAPTURE_WIDTH, CAPTURE_HEIGHT, JPEG_QUALITY, &jpeg_image, &jpeg_size) != 0) {
        fprintf(stderr, "Failed to encode JPEG\n");
        goto cleanup;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char filename[64];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        goto cleanup;
    }

    if (fwrite(jpeg_image, 1, jpeg_size, fp) != jpeg_size) {
        perror("fwrite");
        fclose(fp);
        goto cleanup;
    }

    fclose(fp);
    printf("Image saved as %s\n", filename);
    ret = 0;

cleanup:
    if (jpeg_image) free(jpeg_image);
    if (blurred_image) free(blurred_image);
    if (rgb_image) free(rgb_image);
    if (yuyv_image) free(yuyv_image);
    if (buffers) munmap(buffers, buf.length);
    if (fd != -1) close(fd);
    return ret;
}

