        fprintf(stderr, "Error opening %s: %s\n", VIDEO_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", VIDEO_DEVICE);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Camera: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Capabilities: 0x%08lx\n", cap.capabilities);

    struct v4l2_frmivalenum frmival;
    struct v4l2_frmsizeenum frmsize;
    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;

    printf("\nSupported resolutions:\n");
    while (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        if (frmsize.type != V4L2_FRMSIZE_TYPE_DISCRETE) {
            frmsize.index++;
            continue;
        }

        printf("  %ux%u\n", frmsize.discrete.width, frmsize.discrete.height);

        memset(&frmival, 0, sizeof(frmival));
        frmival.index = 0;
        frmival.width = frmsize.discrete.width;
        frmival.height = frmsize.discrete.height;

        printf("    Frame intervals:\n");
        while (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
            if (frmival.type != V4L2_FRMIVAL_TYPE_DISCRETE) {
                frmival.index++;
                continue;
            }
            printf("      %u/%u fps\n", frmival.discrete.numerator,
                   frmival.discrete.denominator);
            frmival.index++;
        }
        if (errno != EINVAL) {
            fprintf(stderr, "Error enumerating frame intervals: %s\n",
                    strerror(errno));
        }

        frmsize.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
    }

    struct v4l2_queryctrl queryctrl;
    memset(&queryctrl, 0, sizeof(queryctrl));
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (xioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        printf("\nAutofocus supported: %s\n",
               (queryctrl.flags & V4L2_CTRL_FLAG_DISABLED) ? "no" : "yes");
    } else if (errno != EINVAL) {
        fprintf(stderr, "Error querying focus control: %s\n", strerror(errno));
    } else {
        printf("\nAutofocus supported: no (control absent)\n");
    }

    close(fd);
    return EXIT_SUCCESS;
}

