#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  4
#define TILT_SERVO_PIN 5

#define BUTTON_UP    6
#define BUTTON_DOWN  7
#define BUTTON_LEFT  8
#define BUTTON_RIGHT 9

#define PULSE_MIN 1000
#define PULSE_MAX 2000
#define PULSE_CENTER 1500
#define PULSE_STEP 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", PAN_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", TILT_SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUTTON_UP, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", BUTTON_UP);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BUTTON_DOWN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", BUTTON_DOWN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BUTTON_LEFT, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", BUTTON_LEFT);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BUTTON_RIGHT, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", BUTTON_RIGHT);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON_UP, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", BUTTON_UP);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_DOWN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", BUTTON_DOWN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_LEFT, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", BUTTON_LEFT);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_RIGHT, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", BUTTON_RIGHT);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Controller\n");
    printf("  Pan servo : GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("  Buttons   : UP=GPIO%d, DOWN=GPIO%d, LEFT=GPIO%d, RIGHT=GPIO%d\n",
           BUTTON_UP, BUTTON_DOWN, BUTTON_LEFT, BUTTON_RIGHT);
    printf("  Pulse range: %d-%d us, center: %d us\n", PULSE_MIN, PULSE_MAX, PULSE_CENTER);
    printf("Press Ctrl+C to exit.\n");

    int pan_pos = PULSE_CENTER;
    int tilt_pos = PULSE_CENTER;

    while (g_running) {
        if (gpioRead(BUTTON_UP) == 0) {
            pan_pos += PULSE_STEP;
            if (pan_pos > PULSE_MAX) pan_pos = PULSE_MAX;
            gpioServo(PAN_SERVO_PIN, pan_pos);
            gpioDelay(100000);
        }
        if (gpioRead(BUTTON_DOWN) == 0) {
            pan_pos -= PULSE_STEP;
            if (pan_pos < PULSE_MIN) pan_pos = PULSE_MIN;
            gpioServo(PAN_SERVO_PIN, pan_pos);
            gpioDelay(100000);
        }
        if (gpioRead(BUTTON_LEFT) == 0) {
            tilt_pos -= PULSE_STEP;
            if (tilt_pos < PULSE_MIN) tilt_pos = PULSE_MIN;
            gpioServo(TILT_SERVO_PIN, tilt_pos);
            gpioDelay(100000);
        }
        if (gpioRead(BUTTON_RIGHT) == 0) {
            tilt_pos += PULSE_STEP;
            if (tilt_pos > PULSE_MAX) tilt_pos = PULSE_MAX;
            gpioServo(TILT_SERVO_PIN, tilt_pos);
            gpioDelay(100000);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

