#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gphoto2/gphoto2.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_MS 100
#define CAPTURE_QUALITY 85
#define MAX_FILENAME_LEN 256
#define MAX_JSON_LEN 512
#define MAX_IP_LEN 64
#define MAX_PORT_LEN 8

static volatile sig_atomic_t running = 1;
static GPContext *gp_context = NULL;
static GPPortInfoList *port_info_list = NULL;
static GPList *camera_list = NULL;
static GPLogFunc log_func = NULL;
static GPLogFunc log_func_data = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_func_wrapper(GPLogLevel level, const char *domain, const char *message, void *data) {
    (void)level; (void)domain; (void)data;
    fprintf(stderr, "[gphoto2] %s\n", message);
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory.\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    GPContext *ctx = gp_context;
    if (!ctx) return -1;
    GPPortInfoList *pil = port_info_list;
    if (!pil) return -1;
    GPList *cl = camera_list;
    if (!cl) return -1;

    int num_cameras = gp_list_count(cl);
    if (num_cameras <= 0) {
        fprintf(stderr, "No cameras found.\n");
        return -1;
    }

    int camera_id = 0;
    char *camera_name = gp_list_get_name(cl, camera_id);
    if (!camera_name) {
        fprintf(stderr, "Failed to get camera name.\n");
        return -1;
    }

    GPLogFunc old_log = gp_log_func();
    if (old_log) gp_log_func(log_func_wrapper);
    GPLogFunc old_log_data = gp_log_func_data();
    if (old_log_data) gp_log_func_data(log_func_wrapper);

    GPContext *cam_ctx = gp_context_new();
    if (!cam_ctx) {
        fprintf(stderr, "Failed to create camera context.\n");
        gp_log_func(old_log);
        gp_log_func_data(old_log_data);
        return -1;
    }

    GPResult res = gp_camera_new(&cam_ctx);
    if (res != GP_OK) {
        fprintf(stderr, "Failed to create camera object: %s\n", gp_result_as_string(res));
        gp_context_unref(cam_ctx);
        gp_log_func(old_log);
        gp_log_func_data(old_log_data);
        return -1;
    }

    res = gp_camera_set_port_info_list(cam_ctx, pil);
    if (res != GP_OK) {
        fprintf(stderr, "Failed to set port info list: %s\n", gp_result_as_string(res));
        gp_camera_unref(cam_ctx);
        gp_log_func(old_log);
        gp_log_func_data(old_log_data);
        return -1;
    }

    res = gp_camera_set_camera_list(cam_ctx, cl);
    if (res != GP_OK) {
        fprintf(stderr, "Failed to set camera list: %s\n", gp_result_as_string(res));
        gp_camera_unref(cam_ctx);
        gp_log_func(old_log);
        gp_log_func_data(old_log_data);
        return -1;
    }

    res = gp_camera_set_camera(cam_ctx, camera_id);
    if (res != GP_OK) {
        fprintf(stderr, "Failed to set camera: %s\n", gp_result_as_string(res));
        gp_camera_unref(cam_ctx);
        gp_log_func(old_log);
        gp_log_func_data(old_log_data);
        return -1;
    }

    res = gp_camera_init(cam_ctx, GP_CAMERA_INIT_NORMAL);
    if (res != GP_OK) {
        fprintf(stderr, "Failed to initialize camera: %s\n", gp_result_as_string(res));
        gp_camera_unref(cam_ctx);
        gp_log_func(old_log);
        gp_log_func_data(old_log_data);
        return -1;
    }

    GPPort *port = NULL;
    res = gp_port_new(&port);
    if (res != GP_OK) {
        fprintf(stderr, "Failed to create port: %s\n", gp_result_as_string(res));
        gp_camera_exit(cam_ctx, GP_CAMERA_EXIT_SHUTDOWN);
        gp_camera_unref(cam_ctx);
        gp_log_func(old_log);
        gp_log_func_data(old_log_data);
        return -1;
    }

    res = gp_camera_get_port(cam_ctx, &port);
    if (res != GP_OK) {
        fprintf(stderr, "Failed to get camera port: %s\n", gp_result_as_string(res));
        gp_port_unref(port);
        gp_camera_exit(cam_ctx, GP_CAMERA_EXIT_SHUTDOWN);
        gp_camera_unref(cam_ctx);
        gp_log_func(old_log);
        gp_log_func_data(old_log_data);
        return -1;
    }

    res = gp_camera_capture(cam_ctx, GP_CAPTURE_IMAGE, &port);
    if (res != GP_OK) {
        fprintf(stderr, "Failed to capture image: %s\n", gp_result_as_string(res));
        gp_port_unref(port);
        gp_camera_exit(cam_ctx, GP_CAMERA_EXIT_SHUTDOWN);
        gp_camera_unref(cam_ctx);
        gp_log_func(old_log);
        gp_log_func_data(old_log_data);
        return -1;
    }

    res = gp_camera_download(cam_ctx, GP_DOWNLOAD_FILE, filename, &port);
    if (res != GP_OK) {
        fprintf(stderr, "Failed to download image: %s\n", gp_result_as_string(res));
        gp_port_unref(port);
        gp_camera_exit(cam_ctx, GP_CAMERA_EXIT_SHUTDOWN);
        gp_camera_unref(cam_ctx);
        gp_log_func(old_log);
