                    "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":\"detected\",\"gpio_pin\":%d}",
                    filename, timestamp, PIR_GPIO);

                printf("Sending HTTP request...\n");
                if (send_http_request(ip_address, port_str, filename, json_payload) != 0) {
                    fprintf(stderr, "Failed to send HTTP request.\n");
                }
            } else {
                fprintf(stderr, "Failed to capture image.\n");
            }

            sleep(DEBOUNCE_SEC);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");

    gpioTerminate();

    if (camera_list) {
        gp_list_unref(camera_list);
        camera_list = NULL;
    }
    if (port_info_list) {
        gp_port_info_list_unref(port_info_list);
        port_info_list = NULL;
    }
    if (gp_context) {
        gp_camera_exit(gp_context, GP_CAMERA_EXIT_SHUTDOWN);
        gp_camera_unref(gp_context);
        gp_context = NULL;
    }

    if (log_func_data) gp_log_func_data(log_func_data);
    if (log_func) gp_log_func(log_func);

    return 0;
}

