#define PIR_GPIO_LINE 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define CAPTURE_TIMEOUT_MS 2000
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int capture_image(void) {
    char filename[64];
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    snprintf(filename, sizeof(filename), "%04d%02d%02d_%02d%02d%02d_%03d.jpg",
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec, (int)(t % 1000));

    char command[512];
    snprintf(command, sizeof(command),
             "raspistill -o %s/%s -w 640 -h 480 -q 85 --timeout %d --nopreview",
             IMAGE_DIR, filename, CAPTURE_TIMEOUT_MS);

    int status = system(command);
    if (status == -1) {
        log_event("Error: system() failed to launch raspistill.");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        char msg[256];
        snprintf(msg, sizeof(msg), "Error: raspistill exited with status %d.", WEXITSTATUS(status));
        log_event(msg);
        return -1;
    }
    char msg[256];
    snprintf(msg, sizeof(msg), "Image captured: %s/%s", IMAGE_DIR, filename);
    log_event(msg);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        log_event("Error: Failed to open gpiochip0.");
        return 1;
    }

    line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        log_event("Error: Failed to get GPIO line.");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, "motion_monitor") < 0) {
        fprintf(stderr, "Error requesting falling edge events on GPIO %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        log_event("Error: Failed to request falling edge events.");
        goto cleanup;
    }

    log_event("Motion detection started on GPIO17.");

    while (program_running) {
        struct timespec ts = {0, POLL_TIMEOUT_MS * 1000000L};
        int ev = gpiod_line_event_wait(line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            log_event("Error: Failed to wait for GPIO event.");
            break;
        }
        if (ev == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            log_event("Error: Failed to read GPIO event.");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        struct timespec debounce_ts = {0, DEBOUNCE_MS * 1000000L};
        int debounced = 0;
        while (program_running && !debounced) {
            int ev2 = gpiod_line_event_wait(line, &debounce_ts);
            if (ev2 < 0) {
                if (errno == EINTR) break;
                fprintf(stderr, "Error waiting for debounce: %s\n", strerror(errno));
                log_event("Error: Failed to wait for debounce.");
                break;
            }
            if (ev2 == 0) {
                debounced = 1;
                break;
            }
            struct gpiod_line_event event2;
            if (gpiod_line_event_read(line, &event2) < 0) {
                fprintf(stderr, "Error reading debounce event: %s\n", strerror(errno));
                log_event("Error: Failed to read debounce event.");
                break;
            }
            if (event2.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                debounced = 0;
            } else {
                debounced = 1;
            }
        }
        if (!debounced) continue;

        log_event("Motion detected.");
        if (capture_image() != 0) {
            log_event("Error: Image capture failed.");
        }
    }

    log_event("Motion detection stopped.");
    ret = 0;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

