#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define CROPPED_WIDTH  200
#define CROPPED_HEIGHT 150
#define CAPTURE_WIDTH  640
#define CAPTURE_HEIGHT 480
#define CROP_X         0
#define CROP_Y         0
#define CAPTURE_FORMAT V4L2_PIX_FMT_YUYV
#define CAPTURE_FIELD  V4L2_FIELD_NONE
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer = NULL;
    FILE *out = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open " VIDEO_DEVICE);
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = CAPTURE_WIDTH;
    fmt.fmt.pix.height = CAPTURE_HEIGHT;
    fmt.fmt.pix.pixelformat = CAPTURE_FORMAT;
    fmt.fmt.pix.field = CAPTURE_FIELD;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }
    if (fmt.fmt.pix.pixelformat != CAPTURE_FORMAT) {
        fprintf(stderr, "Device does not support YUYV\n");
        goto cleanup;
    }
    if (fmt.fmt.pix.field != CAPTURE_FIELD) {
        fprintf(stderr, "Device does not support progressive capture\n");
        goto cleanup;
    }
    if (fmt.fmt.pix.width != CAPTURE_WIDTH || fmt.fmt.pix.height != CAPTURE_HEIGHT) {
        fprintf(stderr, "Device did not accept requested resolution\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    int r;
    do {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = CAPTURE_TIMEOUT_SEC;
        tv.tv_usec = 0;
        r = select(fd + 1, &fds, NULL, NULL, &tv);
    } while (r == -1 && errno == EINTR && !g_stop);

    if (g_stop) {
        fprintf(stderr, "Interrupted by signal\n");
        goto streamoff;
    }
    if (r == -1) {
        perror("select");
        goto streamoff;
    }
    if (r == 0) {
        fprintf(stderr, "Capture timeout\n");
        goto streamoff;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto streamoff;
    }

    if (buf.bytesused < (size_t)(CAPTURE_WIDTH * CAPTURE_HEIGHT * 2)) {
        fprintf(stderr, "Incomplete frame: %u bytes\n", buf.bytesused);
        goto streamoff;
    }

    out = fopen("cropped.yuv", "wb");
    if (!out) {
        perror("fopen cropped.yuv");
        goto streamoff;
    }

    size_t expected = (size_t)CROPPED_WIDTH * CROPPED_HEIGHT * 2;
    size_t written = 0;
    for (int y = CROP_Y; y < CROP_Y + CROPPED_HEIGHT && written < expected; y++) {
        for (int x = CROP_X; x < CROP_X + CROPPED_WIDTH && written < expected; x++) {
            unsigned char y0 = ((unsigned char *)buffer)[(y * CAPTURE_WIDTH + x) * 2];
            unsigned char u  = ((unsigned char *)buffer)[(y * CAPTURE_WIDTH + x) * 2 + 1];
            unsigned char y1 = ((unsigned char *)buffer)[(y * CAPTURE_WIDTH + x) * 2 + 2];
            unsigned char v  = ((unsigned char *)buffer)[(y * CAPTURE_WIDTH + x) * 2 + 3];
            if (fputc(y0, out) == EOF || fputc(u, out) == EOF || fputc(y1, out) == EOF || fputc(v, out) == EOF) {
                perror("fputc");
                goto streamoff;
            }
            written += 4;
        }
    }

    if (written != expected) {
        fprintf(stderr, "Short write: %zu bytes\n", written);
        goto streamoff;
    }

    ret = EXIT_SUCCESS;

streamoff:
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
    }

cleanup:
    if (out) fclose(out);
    if (buffer && buffer != MAP_FAILED) munmap(buffer, buf.length);
    if (fd != -1) close(fd);
    return ret;
}

