#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  17
#define TILT_SERVO_PIN 18

#define SERVO_MIN_PULSEWIDTH  500
#define SERVO_MAX_PULSEWIDTH  2500
#define SERVO_NEUTRAL_PULSEWIDTH 1500
#define SERVO_MIN_ANGLE       0
#define SERVO_MAX_ANGLE       180

#define STEP_SIZE 5
#define STEP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int angle_to_pulsewidth(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
        return -1;
    }
    return SERVO_MIN_PULSEWIDTH +
           (int)(((float)angle / (float)SERVO_MAX_ANGLE) *
                 (float)(SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH));
}

static int set_servo_angle(int pin, int angle) {
    int pw = angle_to_pulsewidth(angle);
    if (pw < 0) return -1;
    if (gpioServo(pin, pw) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pw=%d)\n", pin, pw);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    set_servo_angle(PAN_SERVO_PIN, 90);
    set_servo_angle(TILT_SERVO_PIN, 90);
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    int pan_angle  = 90;
    int tilt_angle = 90;

    if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0 ||
        set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
        cleanup();
        return 1;
    }

    printf("Servo control ready. Press arrow keys (up/down/left/right) or 'q' to quit.\n");
    fflush(stdout);

    while (running) {
        int c = getchar();
        if (c == EOF) {
            break;
        }

        if (c == 'q') {
            break;
        }

        if (c == '\033') {
            int c2 = getchar();
            if (c2 == '[') {
                int c3 = getchar();
                switch (c3) {
                    case 'A': /* up */
                        pan_angle += STEP_SIZE;
                        if (pan_angle > SERVO_MAX_ANGLE) pan_angle = SERVO_MAX_ANGLE;
                        break;
                    case 'B': /* down */
                        pan_angle -= STEP_SIZE;
                        if (pan_angle < SERVO_MIN_ANGLE) pan_angle = SERVO_MIN_ANGLE;
                        break;
                    case 'C': /* right */
                        tilt_angle += STEP_SIZE;
                        if (tilt_angle > SERVO_MAX_ANGLE) tilt_angle = SERVO_MAX_ANGLE;
                        break;
                    case 'D': /* left */
                        tilt_angle -= STEP_SIZE;
                        if (tilt_angle < SERVO_MIN_ANGLE) tilt_angle = SERVO_MIN_ANGLE;
                        break;
                    default:
                        break;
                }
                if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0 ||
                    set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
                    fprintf(stderr, "Error: failed to set servo angles\n");
                }
            }
        }
    }

    cleanup();
    return 0;
}

