#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OLED_WIDTH  128
#define OLED_HEIGHT 64
#define OLED_PAGES  (OLED_HEIGHT / 8)

#define I2C_BUS "/dev/i2c-1"
#define OLED_ADDR 0x3C

#define FONT_WIDTH  5
#define FONT_HEIGHT 7

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, const unsigned char *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int oled_command(int fd, unsigned char cmd) {
    unsigned char buf[2] = {0x00, cmd};
    return i2c_write(fd, buf, 2);
}

static int oled_data(int fd, unsigned char data) {
    unsigned char buf[2] = {0x40, data};
    return i2c_write(fd, buf, 2);
}

static int oled_init(int fd) {
    static const unsigned char init_cmds[] = {
        0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40,
        0x8D, 0x14, 0x20, 0x00, 0xA1, 0xC8, 0xDA, 0x12,
        0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6,
        0xAF
    };
    for (size_t i = 0; i < sizeof(init_cmds); i++) {
        if (oled_command(fd, init_cmds[i]) < 0) return -1;
    }
    return 0;
}

static int oled_clear(int fd) {
    for (int p = 0; p < OLED_PAGES; p++) {
        if (oled_command(fd, 0xB0 + p) < 0) return -1;
        if (oled_command(fd, 0x00) < 0) return -1;
        if (oled_command(fd, 0x10) < 0) return -1;
        for (int c = 0; c < OLED_WIDTH; c++) {
            if (oled_data(fd, 0x00) < 0) return -1;
        }
    }
    return 0;
}

static int oled_set_cursor(int fd, int col, int page) {
    if (oled_command(fd, 0xB0 + page) < 0) return -1;
    if (oled_command(fd, 0x00 + (col & 0x0F)) < 0) return -1;
    if (oled_command(fd, 0x10 + ((col >> 4) & 0x0F)) < 0) return -1;
    return 0;
}

static int oled_draw_char(int fd, int col, int page, char c) {
    if (c < 32 || c > 126) c = '?';
    const unsigned char *glyph = (const unsigned char *)font5x7 + (c - 32) * FONT_WIDTH;
    if (oled_set_cursor(fd, col, page) < 0) return -1;
    for (int i = 0; i < FONT_WIDTH; i++) {
        if (oled_data(fd, glyph[i]) < 0) return -1;
    }
    return 0;
}

static int oled_draw_string(int fd, int col, int page, const char *str) {
    int x = col;
    int y = page;
    for (size_t i = 0; str[i] != '\0' && x < OLED_WIDTH; i++) {
        if (oled_draw_char(fd, x, y, str[i]) < 0) return -1;
        x += FONT_WIDTH;
        if (x >= OLED_WIDTH) {
            x = 0;
            y++;
            if (y >= OLED_PAGES) y = 0;
            if (oled_set_cursor(fd, x, y) < 0) return -1;
        }
    }
    return 0;
}

static int oled_draw_bitmap(int fd, int col, int page, const unsigned char *bitmap, int w, int h) {
    if (oled_set_cursor(fd, col, page) < 0) return -1;
    for (int p = 0; p < h; p++) {
        if (oled_command(fd, 0xB0 + page + p) < 0) return -1;
        if (oled_command(fd, 0x00 + (col & 0x0F)) < 0) return -1;
        if (oled_command(fd, 0x10 + ((col >> 4) & 0x0F)) < 0) return -1;
        for (int c = 0; c < w; c++) {
            if (oled_data(fd, bitmap[p * w + c]) < 0) return -1;
        }
    }
    return 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open CPU temperature file: %s\n", strerror(errno));
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse CPU temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli / 1000;
}

static int read_cpu_usage(void) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open /proc/stat: %s\n", strerror(errno));
        return -1;
    }
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Failed to parse /proc/stat\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    static unsigned long long prev_idle = 0, prev_total = 0;
    unsigned long long idle_now = idle + iowait;
    unsigned long long total_now = user + nice + system + idle_now + irq + softirq + steal;
    unsigned long long total_diff = total_now - prev_total;
    unsigned long long idle_diff = idle_now - prev_idle;
    if (total_diff == 0) return 0;
    unsigned long long usage = (total_diff - idle_diff) * 100 / total_diff;
    prev_idle = idle_now;
    prev_total = total_now;
    return (int)usage;
}

static void draw_cpu_temp(int fd, int temp) {
    char buf[32];
    snprintf(buf, sizeof(buf), "CPU: %d.%d C", temp, (temp * 10) % 10);
    oled_draw_string(fd, 0, 0, buf);
}

static void draw_cpu_usage(int fd, int usage) {
    char buf[32];
    snprintf(buf, sizeof(buf), "Usage: %d%%", usage);
    oled_draw_string(fd, 0, 1, buf);
}

static void draw_error(int fd, const char *msg) {
    oled_draw_string(fd, 0, 0, msg);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, OLED_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OLED_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (oled_init(fd) < 0) {
        fprintf(stderr, "OLED initialization failed\n");
        close(fd);
        return 1;
    }
    if (oled_clear(fd) < 0) {
        fprintf(stderr, "OLED clear failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        int temp = read_cpu_temp();
        int usage = read_cpu_usage();

        if (temp < 0 || usage < 0) {
            draw_error(fd, "Read error");
        } else {
            draw_cpu_temp(fd, temp);
            draw_cpu_usage(fd, usage);
        }

        for (int p = 0; p < OLED_PAGES; p++) {
            if (oled_command(fd, 0xB0 + p) < 0) break;
            if (oled_command(fd, 0x00) < 0) break;
            if (oled_command(fd, 0x10) < 0) break;
            for (int c = 0; c < OLED_WIDTH; c++) {
                if (oled_data(fd, 0xFF) < 0) break;
            }
        }

        sleep(1);
    }

    oled_clear(fd);
    close(fd);
    return 0;
}

