static int oled_draw_bitmap(int fd, int col, int page, const unsigned char *bitmap, int w, int h) {
    if (oled_set_cursor(fd, col, page) < 0) return -1;
    for (int p = 0; p < h; p++) {
        if (oled_command(fd, 0xB0 + page + p) < 0) return -1;
        if (oled_command(fd, 0x00 + (col & 0x0F)) < 0) return -1;
        if (oled_command(fd, 0x10 + ((col >> 4) & 0x0F)) < 0) return -1;
        for (int c = 0; c < w; c++) {
            if (oled_data(fd, bitmap[p * w + c]) < 0) return -1;
        }
    }
    return 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open CPU temperature file: %s\n", strerror(errno));
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse CPU temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli / 1000;
}

static int read_cpu_usage(void) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open /proc/stat: %s\n", strerror(errno));
        return -1;
    }
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Failed to parse /proc/stat\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    static unsigned long long prev_idle = 0, prev_total = 0;
    unsigned long long idle_now = idle + iowait;
    unsigned long long total_now = user + nice + system + idle_now + irq + softirq + steal;
    unsigned long long total_diff = total_now - prev_total;
    unsigned long long idle_diff = idle_now - prev_idle;
    if (total_diff == 0) return 0;
    unsigned long long usage = (total_diff - idle_diff) * 100 / total_diff;
    prev_idle = idle_now;
    prev_total = total_now;
    return (int)usage;
}

static void draw_cpu_temp(int fd, int temp) {
    char buf[32];
    snprintf(buf, sizeof(buf), "CPU: %d.%d C", temp, (temp * 10) % 10);
    oled_draw_string(fd, 0, 0, buf);
}

static void draw_cpu_usage(int fd, int usage) {
    char buf[32];
    snprintf(buf, sizeof(buf), "Usage: %d%%", usage);
    oled_draw_string(fd, 0, 1, buf);
}

static void draw_error(int fd, const char *msg) {
    oled_draw_string(fd, 0, 0, msg);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, OLED_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OLED_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (oled_init(fd) < 0) {
        fprintf(stderr, "OLED initialization failed\n");
        close(fd);
        return 1;
    }
    if (oled_clear(fd) < 0) {
        fprintf(stderr, "OLED clear failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        int temp = read_cpu_temp();
        int usage = read_cpu_usage();

        if (temp < 0 || usage < 0) {
            draw_error(fd, "Read error");
        } else {
            draw_cpu_temp(fd, temp);
            draw_cpu_usage(fd, usage);
        }

        for (int p = 0; p < OLED_PAGES; p++) {
            if (oled_command(fd, 0xB0 + p) < 0) break;
            if (oled_command(fd, 0x00) < 0) break;
            if (oled_command(fd, 0x10) < 0) break;
            for (int c = 0; c < OLED_WIDTH; c++) {
                if (oled_data(fd, 0xFF) < 0) break;
            }
        }

        sleep(1);
    }

    oled_clear(fd);
    close(fd);
    return 0;
}

