#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 20

#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static double total_volume = 0.0;
static double flow_rate = 0.0;
static double previous_volume = 0.0;
static double pulse_count = 0.0;
static double last_pulse_time = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_strobe(int data) {
    int hi = data | ENABLE | LCD_BACKLIGHT;
    int lo = (data & ~ENABLE) | LCD_BACKLIGHT;
    i2cWriteByte(i2c_fd, hi);
    gpioDelay(1);
    i2cWriteByte(i2c_fd, lo);
    gpioDelay(1);
}

static void lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;
    i2cWriteByte(i2c_fd, bits_high);
    lcd_strobe(bits_high);
    i2cWriteByte(i2c_fd, bits_low);
    lcd_strobe(bits_low);
}

static void lcd_string(const char *s) {
    while (*s) {
        lcd_byte((uint8_t)*s++, LCD_CHR);
    }
}

static void lcd_clear(void) {
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_init(void) {
    gpioDelay(50000);
    lcd_byte(0x33, LCD_CMD);
    lcd_byte(0x32, LCD_CMD);
    lcd_byte(0x28, LCD_CMD);
    lcd_byte(0x0C, LCD_CMD);
    lcd_byte(0x06, LCD_CMD);
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_set_cursor(int col, int row) {
    int row_offsets[] = {0x00, 0x40};
    lcd_byte(0x80 | (col + row_offsets[row]), LCD_CMD);
}

static void lcd_print_flow_rate(double flow) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", flow);
    lcd_clear();
    lcd_string(buffer);
}

static void lcd_print_total_volume(double volume) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", volume);
    lcd_set_cursor(0, 1);
    lcd_string(buffer);
}

static void lcd_print_error(const char *msg) {
    lcd_clear();
    lcd_string(msg);
}

static void lcd_print_warning(const char *msg) {
    lcd_clear();
    lcd_string(msg);
}

static void lcd_print_info(const char *msg) {
    lcd_clear();
    lcd_string(msg);
}

static void lcd_print_data(double flow, double volume) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", flow);
    lcd_set_cursor(0, 0);
    lcd_string(buffer);
    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", volume);
    lcd_set_cursor(0, 1);
    lcd_string(buffer);
}

static void lcd_update(double flow, double volume) {
    if (i2c_fd < 0) {
        return;
    }
    lcd_print_data(flow, volume);
}

static void lcd_cleanup(void) {
    if (i2c_fd >= 0) {
        lcd_clear();
        lcd_string("Shutting down...");
        i2cClose(i2c_fd);
        i2c_fd = -1;
    }
}

static void cleanup(void) {
    lcd_cleanup();
    gpioTerminate();
}

static void calculate_flow_rate(double current_time) {
    double time_diff = current_time - last_pulse_time;
    if (time_diff > 0.0) {
        flow_rate = (pulse_count / time_diff) * 60.0;
    } else {
        flow_rate = 0.0;
    }
    last_pulse_time = current_time;
    pulse_count = 0.0;
}

static void calculate_total_volume(double current_time) {
    double time_diff = current_time - previous_volume;
    if (time_diff > 0.0) {
        total_volume += (pulse_count / time_diff) * 60.0;
    }
    previous_volume = current_time;
}

static void gpio_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        pulse_count++;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(GPIO_PIN, gpio_callback) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO%d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n", I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();
    lcd_print_info("Water Flow Monitor");

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double current_time = ts.tv_sec + (ts.tv_nsec / 1000000000.0);
    last_pulse_time = current_time;
    previous_volume = current_time;

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        current_time = ts.tv_sec + (ts.tv_nsec / 1000000000.0);

        calculate_flow_rate(current_time);
        calculate_total_volume(current_time);

        printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);

        lcd_update(flow_rate, total_volume);

        time_t sleep_time = 1;
        while (sleep_time > 0 && running) {
            sleep_time = sleep(sleep_time);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

