/*
 * Anemometer + Wind Vane → 16x2 LCD display
 * Board: Raspberry Pi 4 Model B
 *   - Anemometer pulse: GPIO17 (BCM), rising edge interrupt
 *   - Wind vane: MCP3008 ADC channel 0, SPI0/CE0, mode 0, 1 MHz
 *   - LCD: PCF8574 backpack on I2C bus 1
 *
 * Build: gcc -O2 -Wall -o wind wind.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <linux/spi/spi.h>
#include <linux/i2c.h>

#define ANEMOMETER_GPIO 17
#define SAMPLE_WINDOW_MS 500
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define LCD_I2C_ADDR 0x27
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04
#define LCD_WIDTH 16
#define MCP3008_CHANNEL 0

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static volatile uint32_t last_pulse_tick = 0;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_isr(void) {
    uint32_t now = (uint32_t)clock();
    if (last_pulse_tick == 0 || (now - last_pulse_tick) >= 1000) {
        pulse_count = 1;
    } else {
        pulse_count++;
    }
    last_pulse_tick = now;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *byte) {
    if (read(fd, byte, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read block failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd | LCD_BACKLIGHT), (uint8_t)(cmd | LCD_BACKLIGHT | LCD_ENABLE) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write cmd failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(1000);
    return 0;
}

static int i2c_write_data(int fd, uint8_t data) {
    uint8_t buf[2] = { (uint8_t)(data | LCD_BACKLIGHT), (uint8_t)(data | LCD_BACKLIGHT | LCD_ENABLE) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write data failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(1000);
    return 0;
}

static int lcd_init(int fd) {
    usleep(50000);
    if (i2c_write_cmd(fd, 0x33)) return -1;
    if (i2c_write_cmd(fd, 0x32)) return -1;
    if (i2c_write_cmd(fd, 0x28)) return -1;
    if (i2c_write_cmd(fd, 0x0C)) return -1;
    if (i2c_write_cmd(fd, 0x06)) return -1;
    if (i2c_write_cmd(fd, 0x01)) return -1;
    usleep(2000);
    return 0;
}

static int lcd_clear(int fd) {
    return i2c_write_cmd(fd, 0x01);
}

static int lcd_set_cursor(int fd, int col, int row) {
    uint8_t addr = (row == 0) ? 0x00 : 0x40;
    addr += (uint8_t)col;
    return i2c_write_cmd(fd, 0x80 | addr);
}

static int lcd_print(int fd, const char *str) {
    while (*str) {
        if (i2c_write_data(fd, (uint8_t)*str++)) return -1;
    }
    return 0;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static const char *wind_direction(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) return "ERROR";
    if (adc_value < 341) return "N";
    if (adc_value < 682) return "NE";
    if (adc_value < 1023) return "E";
    return "ERROR";
}

static void display_wind_data(int lcd_fd, float wind_speed, const char *direction) {
    char line1[17];
    char line2[17];
    snprintf(line1, sizeof(line1), "Wind: %.2f m/s", wind_speed);
    snprintf(line2, sizeof(line2), "Dir: %s", direction);
    lcd_clear(lcd_fd);
    lcd_set_cursor(lcd_fd, 0, 0);
    lcd_print(lcd_fd, line1);
    lcd_set_cursor(lcd_fd, 0, 1);
    lcd_print(lcd_fd, line2);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int lcd_fd = open(I2C_BUS, O_RDWR);
    if (lcd_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(lcd_fd, I2C_SLAVE, LCD_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", LCD_I2C_ADDR, strerror(errno));
        close(lcd_fd);
        return 1;
    }
    if (lcd_init(lcd_fd) < 0) {
        fprintf(stderr, "LCD init failed\n");
        close(lcd_fd);
        return 1;
    }

    int spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_BUS, strerror(errno));
        close(lcd_fd);
        return 1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI config failed: %s\n", strerror(errno));
        close(spi_fd);
        close(lcd_fd);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        close(spi_fd);
        close(lcd_fd);
        return 1;
    }
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_UP);
    if (gpioSetISRFunc(ANEMOMETER_GPIO, RISING_EDGE, 0, pulse_isr) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d\n", ANEMOMETER_GPIO);
        gpioTerminate();
        close(spi_fd);
        close(lcd_fd);
        return 1;
    }

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000 + (now.tv_nsec - start.tv_nsec) / 1000000;
        if (elapsed_ms >= SAMPLE_WINDOW_MS) {
            uint32_t count = pulse_count;
            pulse_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start);
            float wind_speed = (float)count * 0.5f;
            int adc = read_mcp3008(spi_fd, MCP3008_CHANNEL);
            const char *dir = "ERROR";
            if (adc >= 0 && adc <= 1023) {
                dir = wind_direction(adc);
            } else {
                fprintf(stderr, "ADC read error or sensor absent (adc=%d)\n", adc);
            }
            display_wind_data(lcd_fd, wind_speed, dir);
        }
        usleep(10000);
    }

    gpioSetISRFunc(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL);
    gpioTerminate();
    close(spi_fd);
    close(lcd_fd);
    return 0;
}

