/*
 * Water Flow Monitor — Raspberry Pi 3 Model B+
 * Sensor : YF-S201 water flow sensor (pulse output)
 * Wiring : YF-S201 D0 -> GPIO17 (BCM 17, physical pin 11)
 *          LCD1602 I2C  -> I2C bus 1 (SDA=GPIO2, SCL=GPIO3, physical pins 3/5)
 * Build  : gcc -O2 -Wall -o flow_monitor flow_monitor.c -lgpiod -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <stdbool.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_PIN        17
#define I2C_BUS         "/dev/i2c-1"
#define LCD_ADDR        0x27
#define LCD_WIDTH       16
#define SAMPLE_PERIOD_S 1
#define MAX_NOISE_SECONDS 10

/* LCD commands */
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME   0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_FUNCTIONSET  0x20
#define LCD_SETDDRAMADDR 0x80

/* LCD display control flags */
#define LCD_DISPLAYON    0x04
#define LCD_CURSOROFF    0x00
#define LCD_BLINKOFF     0x00
#define LCD_2LINE        0x08
#define LCD_5x8DOTS      0x00

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ---- I2C / LCD helpers ---- */

static int i2c_write_byte(int fd, unsigned char byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_send_nibble(int fd, unsigned char nibble, bool rs)
{
    unsigned char upper = (nibble & 0xF0) | rs;
    unsigned char lower = ((nibble << 4) & 0xF0) | rs;

    if (i2c_write_byte(fd, upper) < 0) return -1;
    sleep_ms(2);
    if (i2c_write_byte(fd, upper | 0x04) < 0) return -1; /* enable pulse */
    sleep_ms(2);
    if (i2c_write_byte(fd, upper) < 0) return -1;
    sleep_ms(2);

    if (i2c_write_byte(fd, lower) < 0) return -1;
    sleep_ms(2);
    if (i2c_write_byte(fd, lower | 0x04) < 0) return -1;
    sleep_ms(2);
    if (i2c_write_byte(fd, lower) < 0) return -1;
    sleep_ms(2);

    return 0;
}

static int lcd_send_command(int fd, unsigned char cmd)
{
    return lcd_send_nibble(fd, cmd & 0xF0, 0);
}

static int lcd_send_data(int fd, unsigned char data)
{
    return lcd_send_nibble(fd, data & 0xF0, 1);
}

static int lcd_init(int fd)
{
    sleep_ms(50);
    if (lcd_send_nibble(fd, 0x30, 0) < 0) return -1;
    sleep_ms(5);
    if (lcd_send_nibble(fd, 0x30, 0) < 0) return -1;
    sleep_ms(1);
    if (lcd_send_nibble(fd, 0x30, 0) < 0) return -1;
    sleep_ms(1);
    if (lcd_send_nibble(fd, 0x20, 0) < 0) return -1; /* 4-bit mode */
    sleep_ms(1);

    if (lcd_send_command(fd, LCD_FUNCTIONSET | LCD_2LINE | LCD_5x8DOTS) < 0) return -1;
    if (lcd_send_command(fd, LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF) < 0) return -1;
    if (lcd_send_command(fd, LCD_CLEARDISPLAY) < 0) return -1;
    sleep_ms(2);
    if (lcd_send_command(fd, LCD_ENTRYMODESET | 0x02) < 0) return -1; /* right-to-left */
    return 0;
}

static int lcd_set_cursor(int fd, int col, int row)
{
    unsigned char addr = (row == 0) ? 0x00 : 0x40;
    addr += (unsigned char)col;
    return lcd_send_command(fd, LCD_SETDDRAMADDR | addr);
}

static int lcd_print(int fd, const char *str)
{
    while (*str) {
        if (lcd_send_data(fd, (unsigned char)*str++) < 0) return -1;
    }
    return 0;
}

/* ---- Flow measurement ---- */

static void flow_rate_to_lpm(double pulses, double period_s, double *lpm)
{
    *lpm = (pulses / period_s) * 60.0;
}

static void format_lpm(double lpm, char *buf, size_t len)
{
    snprintf(buf, len, "%.2f L/min", lpm);
}

/* ---- GPIO setup ---- */

static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

static int setup_gpio(void)
{
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input(gpio_line, "water-flow") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        gpio_line = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        close(i2c_fd);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    if (lcd_init(i2c_fd) < 0) {
        fprintf(stderr, "LCD initialization failed.\n");
        close(i2c_fd);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    int pulse_count = 0;
    time_t last_pulse_time = time(NULL);
    time_t last_noise_time = time(NULL);
    bool sensor_present = true;

    while (g_running) {
        time_t now = time(NULL);

        if (gpiod_line_get_value(gpio_line) == 1) {
            pulse_count++;
            last_pulse_time = now;
            last_noise_time = now;
            sensor_present = true;
        } else {
            if (difftime(now, last_pulse_time) > MAX_NOISE_SECONDS) {
                if (sensor_present) {
                    fprintf(stderr, "Warning: no pulses for %d seconds — sensor may be disconnected.\n",
                            MAX_NOISE_SECONDS);
                    sensor_present = false;
                }
            }
        }

        if (difftime(now, last_pulse_time) >= SAMPLE_PERIOD_S) {
            double lpm;
            flow_rate_to_lpm((double)pulse_count, SAMPLE_PERIOD_S, &lpm);

            char lpm_str[16];
            format_lpm(lpm, lpm_str, sizeof(lpm_str));

            lcd_set_cursor(i2c_fd, 0, 0);
            lcd_print(i2c_fd, "Flow Rate:");
            lcd_set_cursor(i2c_fd, 0, 1);
            lcd_print(i2c_fd, lpm_str);

            printf("Flow Rate: %s\n", lpm_str);

            pulse_count = 0;
            last_pulse_time = now;
        }

        sleep_ms(100);
    }

    printf("\nShutting down...\n");
    lcd_set_cursor(i2c_fd, 0, 0);
    lcd_print(i2c_fd, "Shutting down...");
    sleep_ms(2000);

    close(i2c_fd);
    cleanup_gpio();

    printf("Water flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

