#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

static const int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set row pin %d as output\n", row_pins[i]);
            return -1;
        }
        if (gpioWrite(row_pins[i], 0) < 0) {
            fprintf(stderr, "Error: failed to write row pin %d\n", row_pins[i]);
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set col pin %d as output\n", col_pins[i]);
            return -1;
        }
        if (gpioWrite(col_pins[i], 1) < 0) {
            fprintf(stderr, "Error: failed to write col pin %d\n", col_pins[i]);
            return -1;
        }
    }

    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(row_pins[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpioWrite(col_pins[i], 1);
    }
    gpioTerminate();
}

static void display_frame(const int frame[NUM_ROWS][NUM_COLS]) {
    for (int r = 0; r < NUM_ROWS; r++) {
        for (int c = 0; c < NUM_COLS; c++) {
            if (gpioWrite(row_pins[r], frame[r][c]) < 0) {
                fprintf(stderr, "Error: failed to write row pin %d\n", row_pins[r]);
                cleanup_gpio();
                exit(EXIT_FAILURE);
            }
            if (gpioWrite(col_pins[c], frame[r][c] ? 0 : 1) < 0) {
                fprintf(stderr, "Error: failed to write col pin %d\n", col_pins[c]);
                cleanup_gpio();
                exit(EXIT_FAILURE);
            }
        }
        gpioDelay(SCAN_DELAY_US);
    }
}

static void wave_animation_left(void) {
    int frame[NUM_ROWS][NUM_COLS] = {0};
    for (int i = 0; i < NUM_COLS; i++) {
        for (int r = 0; r < NUM_ROWS; r++) {
            frame[r][(r + i) % NUM_COLS] = 1;
        }
        display_frame(frame);
    }
}

static void wave_animation_right(void) {
    int frame[NUM_ROWS][NUM_COLS] = {0};
    for (int i = 0; i < NUM_COLS; i++) {
        for (int r = 0; r < NUM_ROWS; r++) {
            frame[r][(NUM_COLS - 1 - (r + i)) % NUM_COLS] = 1;
        }
        display_frame(frame);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Running wave animations. Press Ctrl+C to exit.\n");

    while (running) {
        wave_animation_left();
        if (!running) break;
        wave_animation_right();
    }

    cleanup_gpio();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

