 * row anodes are HIGH.  A 150 ms delay is inserted between columns.
 *
 * Build:  gcc -O2 -Wall -Wextra -o led_wave led_wave.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define NUM_ROWS    8
#define NUM_COLS    8
#define DELAY_MS    150          /* column-to-column delay            */
#define CONSUMER    "led_wave"   /* libgpiod consumer label           */

/* Row anode  -> GPIO 2, 3, 4, 17, 27, 22, 10, 9  */
static const unsigned int row_offsets[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};

/* Column cathode -> GPIO 14, 15, 18, 23, 24, 25, 8, 7 */
static const unsigned int col_offsets[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    while (nanosleep(&ts, &ts) < 0 && errno == EINTR) {
        /* retry on signal interruption */
    }
}

/* ------------------------------------------------------------------ */
static void clear_matrix(struct gpiod_line *col_lines[NUM_COLS],
                         struct gpiod_line *row_lines[NUM_ROWS])
{
    for (int r = 0; r < NUM_ROWS; r++) {
        if (gpiod_line_set_value(row_lines[r], 0) < 0) {
            fprintf(stderr, "Warning: failed to set row %d LOW: %s\n",
                    r, strerror(errno));
        }
    }
    for (int c = 0; c < NUM_COLS; c++) {
        if (gpiod_line_set_value(col_lines[c], 1) < 0) {
            fprintf(stderr, "Warning: failed to set col %d HIGH: %s\n",
                    c, strerror(errno));
        }
    }
}

/* ------------------------------------------------------------------ */
static void set_row(struct gpiod_line *row_lines[NUM_ROWS], int row, int on)
{
    if (gpiod_line_set_value(row_lines[row], on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: failed to set row %d %s: %s\n",
                row, on ? "HIGH" : "LOW", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
static void set_col(struct gpiod_line *col_lines[NUM_COLS], int col, int on)
{
    if (gpiod_line_set_value(col_lines[col], on ? 0 : 1) < 0) {
        fprintf(stderr, "Warning: failed to set col %d %s: %s\n",
                col, on ? "LOW" : "HIGH", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
static void wave_animation(struct gpiod_line *col_lines[NUM_COLS],
                           struct gpiod_line *row_lines[NUM_ROWS])
{
    int direction = 1;   /* +1 = left-to-right, -1 = right-to-left */
    int col = 0;

    while (g_running) {
        clear_matrix(col_lines, row_lines);

        /* Light the LEDs in the current column */
        for (int r = 0; r < NUM_ROWS; r++) {
            set_row(row_lines, r, 1);
            sleep_ms(DELAY_MS);
        }

        /* Advance to the next column */
        col += direction;
        if (col >= NUM_COLS) {
            col = NUM_COLS - 2;
            direction = -1;
        } else if (col < 0) {
            col = 1;
            direction = 1;
        }

        /* Clear the matrix before the next column */
        clear_matrix(col_lines, row_lines);
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *col_lines[NUM_COLS] = {NULL};
    struct gpiod_line *row_lines[NUM_ROWS] = {NULL};
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() < 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get column cathode lines */
    for (int c = 0; c < NUM_COLS; c++) {
        col_lines[c] = gpiod_chip_get_line(chip, col_offsets[c]);
        if (!col_lines[c]) {
            fprintf(stderr, "Failed to get column line %u: %s\n",
                    col_offsets[c], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(col_lines[c], CONSUMER, 1) < 0) {
            fprintf(stderr, "Failed to request col %u as output: %s\n",
                    col_offsets[c], strerror(errno));
            goto cleanup;
        }
    }

    /* Get row anode lines */
    for (int r = 0; r < NUM_ROWS; r++) {
        row_lines[r] = gpiod_chip_get_line(chip, row_offsets[r]);
        if (!row_lines[r]) {
            fprintf(stderr, "Failed to get row line %u: %s\n",
                    row_offsets[r], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(row_lines[r], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request row %u as output: %s\n",
                    row_offsets[r], strerror(errno));
            goto cleanup;
        }
    }

    /* Ensure matrix is blank at start */
    clear_matrix(col_lines, row_lines);

    /* Run the wave animation */
    wave_animation(col_lines, row_lines);

    ret = EXIT_SUCCESS;

cleanup:
    /* Turn off all LEDs and release lines */
    clear_matrix(col_lines, row_lines);

    for (int c = 0; c < NUM_COLS; c++) {
        if (col_lines[c]) {
            gpiod_line_release(col_lines[c]);
        }
    }
    for (int r = 0; r < NUM_ROWS; r++) {
        if (row_lines[r]) {
            gpiod_line_release(row_lines[r]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

