#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75031_ADDR  0x5A
#define LOG_FILE       "depth_log.csv"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

/* MLX75031 register addresses (16-bit, big-endian on the bus) */
#define REG_MODEL_ID    0x00
#define REG_RANGE_CFG   0x01
#define REG_RANGE_DATA  0x04
#define REG_RANGE_STATUS 0x05
#define REG_SOFT_RESET  0x1F

#define EXPECTED_MODEL_ID 0x7503

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address + 1 byte payload to the sensor. */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Write a 16-bit register address + 0-byte payload to the sensor (read-modify-write). */
static int i2c_write_reg8_zero(int fd, uint16_t reg)
{
    uint8_t buf[2];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write (zero) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single 8-bit register from the sensor. */
static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *out)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* Read a 16-bit little-endian register from the sensor. */
static int i2c_read_reg16_le(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* Initialize the MLX75031 sensor: verify model ID, soft-reset, configure range. */
static int mlx75031_init(int fd)
{
    uint8_t model_id;
    if (i2c_read_reg8(fd, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID register.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%04X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("MLX75031 model ID verified: 0x%02X\n", model_id);

    /* Soft reset */
    if (i2c_write_reg8(fd, REG_SOFT_RESET, 0x01) != 0)
        return -1;
    usleep(2000);  /* 2 ms settle */

    /* Range configuration: continuous measurement, 1000 µs integration */
    if (i2c_write_reg8(fd, REG_RANGE_CFG, 0x00) != 0)
        return -1;

    return 0;
}

/* Read a distance measurement from the sensor. */
static int mlx75031_read_distance(int fd, int16_t *distance_mm)
{
    uint8_t status;
    if (i2c_read_reg8(fd, REG_RANGE_STATUS, &status) != 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* Measurement not ready yet */
        return 1;
    }

    uint16_t raw;
    if (i2c_read_reg16_le(fd, REG_RANGE_DATA, &raw) != 0)
        return -1;

    *distance_mm = (int16_t)raw;
    return 0;
}

/* Append a timestamped distance reading to the CSV log. */
static int log_data(FILE *fp, int16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Graceful shutdown: close I2C handle, close log file, release sensor. */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Release the sensor interface (if any) */
    system("echo 0 > /sys/bus/i2c/devices/i2c-1/device0/delete");
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MLX75031 device */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n",
                MLX75031_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (mlx75031_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MLX75031 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode) */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Distance_mm\n");
        fflush(g_log_fp);
    }

    printf("Starting data acquisition (Ctrl+C to stop)...\n");

    while (g_running) {
        int16_t distance_mm;
        int rc = mlx75031_read_distance(g_i2c_fd, &distance_mm);

        if (rc == 0) {
            if (log_data(g_log_fp, distance_mm) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error; attempting re-initialization.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            usleep(1000000);  /* 1 s back-off */
            g_i2c_fd = open(I2C_BUS, O_RDWR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Re-open I2C failed: %s\n", strerror(errno));
                break;
            }
            if (ioctl(g_i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
                fprintf(stderr, "Re-acquire I2C failed: %s\n", strerror(errno));
                close(g_i2c_fd);
                g_i2c_fd = -1;
                break;
            }
            if (mlx75031_init(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-init sensor failed.\n");
                close(g_i2c_fd);
                g_i2c_fd = -1;
                break;
            }
        }
        /* rc == 1: measurement not ready; just wait */

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

