#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN  4
#define LED_PIN     17
#define LOG_FILE    "proximity.log"
#define POLL_MS     100
#define LED_ON_MS   100

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_event(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s Object detected\n", ts) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int blink_led(struct gpiod_line *led)
{
    if (gpiod_line_set_value(led, 1) < 0) {
        fprintf(stderr, "Failed to set LED on: %s\n", strerror(errno));
        return -1;
    }
    usleep(LED_ON_MS * 1000);
    if (gpiod_line_set_value(led, 0) < 0) {
        fprintf(stderr, "Failed to set LED off: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip2");
    }
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip1");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open any GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor) {
        fprintf(stderr, "Failed to get sensor line %d: %s\n", SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor, "proximity_sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "proximity_led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        gpiod_line_release(sensor);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int prev = gpiod_line_get_value(sensor);
    if (prev < 0) {
        fprintf(stderr, "Initial sensor read failed: %s\n", strerror(errno));
        gpiod_line_release(sensor);
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int cur = gpiod_line_get_value(sensor);
        if (cur < 0) {
            fprintf(stderr, "Sensor read error: %s\n", strerror(errno));
            break;
        }

        if (prev == 1 && cur == 0) {
            printf("Object detected!\n");
            if (log_event(LOG_FILE) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
            if (blink_led(led) < 0) {
                fprintf(stderr, "LED blink failed; continuing.\n");
            }
        }

        prev = cur;
        usleep(POLL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(sensor);
    gpiod_line_release(led);
    gpiod_chip_close(chip);

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

