#define SI1145_REG_ALS_IR_DATA1 0x25
#define SI1145_REG_PS1_DATA0 0x26
#define SI1145_REG_PS1_DATA1 0x27
#define SI1145_REG_PS2_DATA0 0x28
#define SI1145_REG_PS2_DATA1 0x29
#define SI1145_REG_PS3_DATA0 0x2A
#define SI1145_REG_PS3_DATA1 0x2B
#define SI1145_REG_ALS_UV_DATA0 0x2C
#define SI1145_REG_ALS_UV_DATA1 0x2D

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PSALS_FORCE 0x07
#define SI1145_CMD_PS_PAUSE 0x0B
#define SI1145_CMD_PSALS_PAUSE 0x0F
#define SI1145_CMD_PS_AUTO 0x0D
#define SI1145_CMD_PSALS_AUTO 0x0E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int data = i2cReadByteData(handle, reg);
    if (data < 0) {
        fprintf(stderr, "Error reading I2C register 0x%02X: %d\n", reg, data);
    }
    return data;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing I2C register 0x%02X: %d\n", reg, result);
    }
    return result;
}

static int si1145_init(int handle) {
    int part_id = i2c_read_byte(handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2c_write_byte(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_PS_RATE, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_PS_LED21, 0x0F) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_PS_LED3, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_PS1_ADCMUX, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_PS2_ADCMUX, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_PS3_ADCMUX, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_ALS_VIS_ADCMUX, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_ALS_IR_ADCMUX, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_ALS_UV_ADCMUX, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_COMMAND, SI1145_CMD_PSALS_AUTO) < 0) return -1;

    return 0;
}

static int si1145_read_proximity(int handle, uint16_t *proximity) {
    if (i2c_write_byte(handle, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;
    gpioDelay(10000);

    int low = i2c_read_byte(handle, SI1145_REG_PS1_DATA0);
    int high = i2c_read_byte(handle, SI1145_REG_PS1_DATA1);
    if (low < 0 || high < 0) return -1;

    *proximity = (uint16_t)((high << 8) | low);
    return 0;
}

static int si1145_read_ambient_light(int handle, uint16_t *ambient_light) {
    if (i2c_write_byte(handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    gpioDelay(10000);

    int low = i2c_read_byte(handle, SI1145_REG_ALS_VIS_DATA0);
    int high = i2c_read_byte(handle, SI1145_REG_ALS_VIS_DATA1);
    if (low < 0 || high < 0) return -1;

    *ambient_light = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        uint16_t proximity = 0;
        uint16_t ambient_light = 0;

        if (si1145_read_proximity(i2c_handle, &proximity) < 0) {
            fprintf(stderr, "Error reading proximity\n");
        } else if (si1145_read_ambient_light(i2c_handle, &ambient_light) < 0) {
            fprintf(stderr, "Error reading ambient light\n");
        } else {
            log_data(log_file, proximity, ambient_light);
        }

        gpioDelay(1000000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

