/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring:
 *   TRIGGER -> GPIO17 (BCM)
 *   ECHO    -> GPIO27 (BCM) via 1k/2k voltage divider (5V -> 3.3V)
 *   VCC     -> 5V, GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c
 * Run:    ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27

#define SPEED_OF_SOUND   34300.0          /* cm/s at 20 C */
#define MIN_DISTANCE     2.0              /* cm */
#define MAX_DISTANCE     400.0            /* cm */
#define WATER_THRESHOLD  15.0             /* cm */
#define LOG_FILE         "distance_log.txt"
#define SAMPLE_PERIOD_S  60              /* seconds between samples */
#define TRIGGER_PULSE_US 10              /* 10 us trigger pulse */
#define ECHO_TIMEOUT_US  30000           /* 30 ms max echo wait */
#define ECHO_PULSE_US    30000           /* 30 ms max echo pulse width */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    else
        snprintf(buf, len, "UNKNOWN");
}

static void log_message(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log) {
        fprintf(g_log, "%s %s\n", ts, msg);
        fflush(g_log);
    }
    fprintf(stderr, "%s %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   >= 0  : distance in cm
 *   -1.0  : timeout (echo never went high)
 *   -2.0  : timeout (echo stayed high)
 *   -3.0  : out of range
 */
static float measure_distance(void)
{
    /* Issue a 10 us trigger pulse. */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        log_message("Error: gpioWrite(TRIGGER, 1) failed");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        log_message("Error: gpioWrite(TRIGGER, 0) failed");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout). */
    uint32_t start_tick = gpioTick();
    uint32_t deadline  = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            log_message("Error: echo never went high (sensor absent?)");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (with timeout). */
    deadline = echo_start + ECHO_PULSE_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            log_message("Error: echo stuck high (timeout)");
            return -2.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    float distance = (pulse_us / 1000000.0f) * SPEED_OF_SOUND / 2.0f;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        log_message("Error: reading out of range");
        return -3.0;
    }
    return distance;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ---------------------------------------- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low. */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* --- Open log file --------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        float distance = -1.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            distance = measure_distance();
            if (distance >= 0.0f) {
                ok = 1;
                break;
            }
            gpioDelay(100000);  /* 100 ms backoff */
        }

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (ok) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "%s Distance: %.2f cm", ts, distance);
            log_message(msg);

            if (distance < WATER_THRESHOLD) {
                log_message("Time to water the plant!");
            }
        } else {
            log_message("Error: all measurement attempts failed");
        }

        /* Sleep SAMPLE_PERIOD_S, but wake early on signal. */
        for (int s = 0; s < SAMPLE_PERIOD_S && g_running; ++s)
            sleep(1);
    }

    /* --- Cleanup ---------------------------------------------------- */
    log_message("Program shutting down");
    gpioWrite(TRIGGER_PIN, 0);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

