#define SI1182_REG_PS20_DATA1  0x3F

#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t tmp;
    if (read(fd, &tmp, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = tmp;
    return 0;
}

static int init_si1182(int fd) {
    if (i2c_write_reg8(fd, SI1182_REG_HW_KEY, 0x17) < 0) return -1;
    if (i2c_write_reg8(fd, SI1182_REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE0, 0x08) < 0) return -1;
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1182_REG_PS_RATE, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, SI1182_REG_PS_LED21, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, SI1182_REG_PS_LED3, 0x0F) < 0) return -1;
    return 0;
}

static int read_proximity(int fd, uint16_t *prox) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, SI1182_REG_PS1_DATA0, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, SI1182_REG_PS1_DATA1, &hi) < 0) return -1;
    *prox = ((uint16_t)hi << 8) | lo;
    return 0;
}

static float calculate_bpm(uint16_t prox) {
    if (prox == 0) return 0.0f;
    return 60.0f / ((float)prox / 1000.0f);
}

static void log_data(FILE *fp, float bpm) {
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    fprintf(fp, "%s,%.2f\n", ts, bpm);
    fflush(fp);
}

