    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", SI1182_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (init_si1182(fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        close(fd);
        return 1;
    }

    FILE *fp = fopen("heartrate.csv", "a");
    if (!fp) {
        fprintf(stderr, "fopen(heartrate.csv) failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t prox;
        if (read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Warning: proximity read failed, skipping sample.\n");
        } else {
            float bpm = calculate_bpm(prox);
            log_data(fp, bpm);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    fclose(fp);
    close(fd);
    return 0;
}

