#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L0X_ADDR   0x29
#define GPIO_PIN        17
#define LOG_FILE        "distance_log.txt"
#define POLL_TIMEOUT_MS 100

/* VL53L0X register addresses */
#define REG_IDENTIFICATION_MODEL_ID      0x00C0
#define REG_SYSTEM_INTERRUPT_CLEAR       0x0086
#define REG_SYSTEM_INTERRUPT_CONFIG      0x0044
#define REG_SYSTEM_INTERRUPT_STATUS      0x0044
#define REG_RESULT_INTERRUPT_STATUS      0x0044
#define REG_RESULT_RANGE_STATUS          0x0089
#define REG_RESULT_DISTANCE              0x0096
#define REG_SYSTEM_MODE_START            0x0080

#define EXPECTED_MODEL_ID                0xEA

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int vl53l0x_init(int fd)
{
    uint8_t model_id = 0;
    if (i2c_read_reg8(fd, REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID — sensor may be absent or bus error.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X).\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;
    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CONFIG, 0x04) != 0) return -1;
    if (i2c_write_reg8(fd, REG_SYSTEM_MODE_START, 0x00) != 0) return -1;
    return 0;
}

static int vl53l0x_read_distance(int fd, uint16_t *distance_mm)
{
    if (i2c_write_reg8(fd, REG_SYSTEM_MODE_START, 0x01) != 0) return -1;

    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint8_t status = 0;
        if (i2c_read_reg8(fd, REG_RESULT_INTERRUPT_STATUS, &status) != 0) return -1;
        if (status & 0x01) break;
        usleep(1000);
        if (i == POLL_TIMEOUT_MS - 1) {
            fprintf(stderr, "Distance measurement timeout.\n");
            return -1;
        }
    }

    uint16_t dist = 0;
    if (i2c_read_reg16(fd, REG_RESULT_DISTANCE, &dist) != 0) return -1;

    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;

    *distance_mm = dist;
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L0X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

