    /* Main loop */
    while (!terminate) {
        float distance = 0.0f;
        int rc = read_distance(i2c_handle, &distance);

        if (rc == 0) {
            int led_state = (distance < DISTANCE_THRESHOLD) ? 1 : 0;
            gpioWrite(GPIO_LED, led_state);
            log_data(distance, led_state);
        } else if (rc < 0) {
            /* I2C / bus error – turn LED off for safety */
            gpioWrite(GPIO_LED, 0);
            fprintf(stderr, "[Sensor] read error – continuing\n");
