/*
 * Raspberry Pi Zero W – TDK InvenSense ICU-20201 ultrasonic ToF sensor
 * reader with LED threshold control and timestamped logging.
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   ICU-20201 SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   LED anode     -> GPIO 17 (with ~330 Ω series resistor to GND)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icu20201_led icu20201_led.c -li2c -lpigpio -lrt
 *
 * Run:
 *   sudo ./icu20201_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define I2C_ADDR            0x32          /* ICU-20201 7-bit I2C address      */
#define GPIO_LED            17            /* BCM pin for the LED              */
#define DISTANCE_THRESHOLD  20.0f         /* cm                              */
#define SAMPLE_PERIOD_US    100000        /* 100 ms                          */
#define LOG_FILE            "distance_log.txt"

/* ICU-20201 register map (subset used here) */
#define REG_MODEL_ID        0x00
#define REG_MODEL_ID_VAL    0x2020
#define REG_DISTANCE        0x10
#define REG_STATUS          0x1A
#define REG_SOFT_RESET      0x1B
#define REG_CONFIG          0x1C
#define REG_RANGE_TIMING    0x1D
#define REG_POWER_MODE      0x1E

/* ----------------------------- Globals ----------------------------------- */
static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg16(int handle, uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val & 0xFF);
    buf[2] = (char)((val >> 8) & 0xFF);
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[I2C] write16 reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ----------------------------- Sensor init ------------------------------- */
static int sensor_init(int handle)
{
    uint16_t model_id = 0;

    /* Verify sensor identity */
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id) != 0)
        return -1;
    if (model_id != REG_MODEL_ID_VAL) {
        fprintf(stderr, "[Sensor] unexpected model ID 0x%04X (expected 0x%04X)\n",
                model_id, REG_MODEL_ID_VAL);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x0001) != 0)
        return -1;
    gpioDelay(2000);  /* 2 ms settle */

    /* Configure: enable ranging, set timing */
    if (i2c_write_reg16(handle, REG_CONFIG, 0x0001) != 0)   /* enable */
        return -1;
    if (i2c_write_reg16(handle, REG_RANGE_TIMING, 0x000A) != 0) /* ~5 ms */
        return -1;

    /* Start continuous ranging */
    if (i2c_write_reg16(handle, REG_POWER_MODE, 0x0001) != 0)
        return -1;

    return 0;
}

/* ----------------------------- Distance read ----------------------------- */
static int read_distance(int handle, float *distance_cm)
{
    uint16_t status = 0, dist_raw = 0;

    if (i2c_read_reg16(handle, REG_STATUS, &status) != 0)
        return -1;

    if ((status & 0x0001) == 0) {
        /* Ranging not complete yet */
        return 1;  /* non-fatal */
    }

    if (i2c_read_reg16(handle, REG_DISTANCE, &dist_raw) != 0)
        return -1;

    *distance_cm = (float)dist_raw / 10.0f;
    return 0;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_data(float distance, int led_state)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "[Log] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(log_file, "%s, Distance: %.2f cm, LED: %s\n",
            ts, distance, led_state ? "ON" : "OFF");
    fflush(log_file);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        /* Put sensor in standby before closing */
        (void)i2c_write_reg16(i2c_handle, REG_POWER_MODE, 0x0000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[I2C] open failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init(i2c_handle) != 0) {
        fprintf(stderr, "[Sensor] init failed – check wiring and sensor presence\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "[GPIO] setMode %d failed\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "[Log] open %s failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[Signal] install failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance monitor running.  Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        float distance = 0.0f;
        int rc = read_distance(i2c_handle, &distance);

        if (rc == 0) {
            int led_state = (distance < DISTANCE_THRESHOLD) ? 1 : 0;
            gpioWrite(GPIO_LED, led_state);
            log_data(distance, led_state);
        } else if (rc < 0) {
            /* I2C / bus error – turn LED off for safety */
            gpioWrite(GPIO_LED, 0);
            fprintf(stderr, "[Sensor] read error – continuing\n");
        }
        /* rc == 1: ranging not ready yet – just wait */

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * Si1182-GMR Proximity & Ambient Light Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   Si1182 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o si1182_logger si1182_logger.c -li2c
 * Run:    ./si1182_logger   (requires root or i2c group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1182 I2C address ---- */
#define SI1182_ADDR 0x60

/* ---- Si1182 register addresses ---- */
#define SI1182_REG_PART_ID      0x00
#define SI1182_REG_HW_REV       0x01
#define SI1182_REG_SEQ_ID       0x02
#define SI1182_REG_INT_CFG      0x03
#define SI1182_REG_INT_EN       0x04
#define SI1182_REG_IRQ_STATUS   0x05
#define SI1182_REG_HW_KEY       0x07
#define SI1182_REG_MEAS_RATE    0x08
#define SI1182_REG_ALS_RATE     0x09
#define SI1182_REG_PS_RATE      0x0A
#define SI1182_REG_PS_LED21     0x0F
#define SI1182_REG_PS_LED3      0x10
#define SI1182_REG_PS1_DATA     0x11
#define SI1182_REG_PS2_DATA     0x12
#define SI1182_REG_ALS_DATA     0x13
#define SI1182_REG_COMMAND      0x18

/* ---- Si1182 command codes ---- */
#define SI1182_CMD_RESET        0x01
#define SI1182_CMD_PS_FORCE     0x05
#define SI1182_CMD_ALS_FORCE    0x06
#define SI1182_CMD_PSALS_FORCE  0x07

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */

/* Write one byte to a register; returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a register; returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1182 driver                                                        */
/* ------------------------------------------------------------------ */

/* Reset the sensor; returns 0 on success, -1 on error. */
static int si1182_reset(int fd)
{
    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_RESET) != 0)
        return -1;
    usleep(10000); /* allow reset to complete */
    return 0;
}

/* Force a single proximity + ALS measurement; returns 0 on success. */
static int si1182_force_measurement(int fd)
{
    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_PSALS_FORCE) != 0)
        return -1;
    usleep(10000); /* allow conversion to complete */
    return 0;
}

/* Read a 16-bit little-endian register; returns 0 on success. */
static int si1182_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                              */
/* ------------------------------------------------------------------ */

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Proximity: %u, Ambient: %u\n",
            timestamp, proximity, ambient);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Install signal handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence with PART_ID ---- */
    uint8_t part_id;
    if (i2c_read_reg8(g_i2c_fd, SI1182_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Si1182 not responding on bus (sensor absent or bus error).\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    printf("Si1182 detected (PART_ID = 0x%02X).\n", part_id);

    /* ---- Open log file ---- */
    g_log_fp = fopen("biometric_log.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (si1182_reset(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1182 reset failed.\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Configure measurement rates (0x0F = 500 ms, 0x0F = 500 ms) */
    if (i2c_write_reg8(g_i2c_fd, SI1182_REG_MEAS_RATE, 0x0F) != 0 ||
        i2c_write_reg8(g_i2c_fd, SI1182_REG_ALS_RATE,  0x0F) != 0 ||
        i2c_write_reg8(g_i2c_fd, SI1182_REG_PS_RATE,   0x0F) != 0) {
        fprintf(stderr, "Failed to configure measurement rates.\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Enable PS1 and ALS interrupts (clear any pending) */
    if (i2c_write_reg8(g_i2c_fd, SI1182_REG_INT_EN, 0x03) != 0) {
        fprintf(stderr, "Failed to enable interrupts.\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t proximity = 0, ambient = 0;
        int ok = 0;

        /* Retry force measurement up to 3 times on transient errors */
        for (int attempt = 0; attempt < 3 && g_running; attempt++) {
            if (si1182_force_measurement(g_i2c_fd) == 0) {
                if (si1182_read16(g_i2c_fd, SI1182_REG_PS1_DATA, &proximity) == 0 &&
                    si1182_read16(g_i2c_fd, SI1182_REG_ALS_DATA, &ambient) == 0) {
                    ok = 1;
                    break;
                }
            }
            usleep(10000); /* back off before retry */
        }

        if (ok) {
            log_data(g_log_fp, proximity, ambient);
        } else {
            fprintf(stderr, "Failed to read sensor data after 3 retries.\n");
        }

        /* Sleep 500 ms (interruptible by SIGINT) */
        for (int i = 0; i < 50 && g_running; i++)
            usleep(10000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

