                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a register; returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1182 driver                                                        */
/* ------------------------------------------------------------------ */

/* Reset the sensor; returns 0 on success, -1 on error. */
static int si1182_reset(int fd)
{
    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_RESET) != 0)
        return -1;
    usleep(10000); /* allow reset to complete */
    return 0;
}

/* Force a single proximity + ALS measurement; returns 0 on success. */
static int si1182_force_measurement(int fd)
{
    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_PSALS_FORCE) != 0)
        return -1;
    usleep(10000); /* allow conversion to complete */
    return 0;
}

/* Read a 16-bit little-endian register; returns 0 on success. */
static int si1182_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                              */
/* ------------------------------------------------------------------ */

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Proximity: %u, Ambient: %u\n",
            timestamp, proximity, ambient);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Install signal handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence with PART_ID ---- */
    uint8_t part_id;
    if (i2c_read_reg8(g_i2c_fd, SI1182_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Si1182 not responding on bus (sensor absent or bus error).\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    printf("Si1182 detected (PART_ID = 0x%02X).\n", part_id);

    /* ---- Open log file ---- */
    g_log_fp = fopen("biometric_log.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (si1182_reset(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1182 reset failed.\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Configure measurement rates (0x0F = 500 ms, 0x0F = 500 ms) */
    if (i2c_write_reg8(g_i2c_fd, SI1182_REG_MEAS_RATE, 0x0F) != 0 ||
        i2c_write_reg8(g_i2c_fd, SI1182_REG_ALS_RATE,  0x0F) != 0 ||
        i2c_write_reg8(g_i2c_fd, SI1182_REG_PS_RATE,   0x0F) != 0) {
        fprintf(stderr, "Failed to configure measurement rates.\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Enable PS1 and ALS interrupts (clear any pending) */
    if (i2c_write_reg8(g_i2c_fd, SI1182_REG_INT_EN, 0x03) != 0) {
        fprintf(stderr, "Failed to enable interrupts.\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t proximity = 0, ambient = 0;
        int ok = 0;

        /* Retry force measurement up to 3 times on transient errors */
        for (int attempt = 0; attempt < 3 && g_running; attempt++) {
            if (si1182_force_measurement(g_i2c_fd) == 0) {
                if (si1182_read16(g_i2c_fd, SI1182_REG_PS1_DATA, &proximity) == 0 &&
                    si1182_read16(g_i2c_fd, SI1182_REG_ALS_DATA, &ambient) == 0) {
                    ok = 1;
                    break;
                }
            }
            usleep(10000); /* back off before retry */
        }

        if (ok) {
            log_data(g_log_fp, proximity, ambient);
        } else {
            fprintf(stderr, "Failed to read sensor data after 3 retries.\n");
        }

        /* Sleep 500 ms (interruptible by SIGINT) */
        for (int i = 0; i < 50 && g_running; i++)
            usleep(10000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

