#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICU20201_ADDR  0x32
#define WHO_AM_I       0x01
#define WHO_AM_I_VAL   0x01
#define DIST_REG       0x04
#define GPIO_LED       17
#define LOG_FILE       "tof_log.txt"
#define POLL_MS        50

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int init_sensor(int fd) {
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, DIST_REG, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, DIST_REG + 1, &hi) < 0) return -1;
    *distance = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void log_data(uint16_t distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    } else {
        fprintf(fp, "[timestamp error], Distance: %u mm\n", distance);
    }
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int threshold = 100;
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Error: threshold must be a positive integer\n");
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICU20201_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave 0x%02X: %s\n", ICU20201_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", GPIO_LED);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    printf("ICU-20201 distance monitoring started (threshold: %d mm). Press Ctrl+C to exit.\n", threshold);

    while (running) {
        uint16_t distance;
        if (read_distance(i2c_fd, &distance) < 0) {
            fprintf(stderr, "Error: I2C read failed: %s\n", strerror(errno));
            gpioWrite(GPIO_LED, 0);
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        if (distance < (uint16_t)threshold) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        log_data(distance);
        gpioDelay(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

