/*
 * Raspberry Pi Zero W — Omron B5L-LD50-07050 3D TOF intrusion detector
 *
 * Wiring:
 *   B5L SDA  -> Pi GPIO2  (I2C1 SDA, pin 3)
 *   B5L SCL  -> Pi GPIO3  (I2C1 SCL, pin 5)
 *   B5L VDD  -> 3.3 V
 *   B5L GND  -> GND
 *
 * I2C bus: /dev/i2c-1  (Pi Zero W hardware I2C)
 * Sensor address: 0x50 (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o intrusion intrusion.c
 *
 * The B5L-LD50-07050 is a 3D TOF sensor with a documented command protocol.
 * A 4-byte command frame is written to trigger a measurement, and a 15-byte
 * response is read back.  The 16-bit distance is encoded in bytes 11 and 12
 * of the response (big-endian).
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_ADDR       0x50
#define LOG_FILE       "intrusion_log.txt"
#define DIST_THRESHOLD 1000          /* mm — intrusion detected below this */
#define SAMPLES        10
#define SAMPLE_DELAY   100           /* ms between samples */
#define MEAS_DELAY     10            /* ms after command write */
#define RESP_LEN       15            /* bytes in the documented response */
#define CMD_LEN        4             /* bytes in the command frame */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_resp(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        if (n < 0)
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
/*
 * Send the 4-byte command frame to request a measurement.
 * Returns 0 on success, -1 on error.
 */
static int b5l_trigger_measurement(int fd)
{
    uint8_t cmd[CMD_LEN] = { 0x01, 0x02, 0x03, 0x04 };
    return i2c_write_cmd(fd, cmd, sizeof(cmd));
}

/*
 * Read the 15-byte response and extract the 16-bit big-endian distance.
 * Returns 0 on success and stores the distance in *distance_mm, -1 on error.
 */
static int b5l_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t resp[RESP_LEN];
    if (i2c_read_resp(fd, resp, sizeof(resp)) != 0)
        return -1;

    /* Verify the header byte matches the documented value */
    if (resp[0] != 0x55) {
        fprintf(stderr, "Unexpected response header 0x%02X (expected 0x55)\n",
                resp[0]);
        return -1;
    }

    *distance_mm = ((uint16_t)resp[11] << 8) | resp[12];
    return 0;
}

/*
 * Sample the sensor `samples` times, compute the average distance,
 * and return 0 if the average is below the threshold, 1 otherwise.
 */
static int detect_intrusion(int fd, int samples, int threshold_mm)
{
    long sum = 0;
    int  valid = 0;

    for (int i = 0; i < samples && g_running; i++) {
        if (b5l_trigger_measurement(fd) != 0) {
            fprintf(stderr, "Measurement trigger failed (cycle %d)\n", i + 1);
            continue;
        }

        /* Wait for the sensor to complete the measurement */
        usleep(MEAS_DELAY * 1000);

        uint16_t dist;
        if (b5l_read_distance(fd, &dist) != 0) {
            fprintf(stderr, "Distance read failed (cycle %d)\n", i + 1);
            continue;
        }

        sum += (long)dist;
        valid++;
        usleep(SAMPLE_DELAY * 1000);
    }

    if (valid == 0)
        return 1;  /* no valid samples — treat as no intrusion */

    long avg = sum / valid;
    return (avg < threshold_mm) ? 0 : 1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_intrusion(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, Distance: %u mm\n", ts, distance_mm) < 0)
        perror("fprintf");
    if (fflush(fp) != 0)
        perror("fflush");

    printf("Intrusion detected! Distance: %u mm\n", distance_mm);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
