/*
 * VL53L0X Time-of-Flight distance reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VL53L0X SDA  -> GPIO2  (I2C bus 1 SDA)
 *   VL53L0X SCL  -> GPIO3  (I2C bus 1 SCL)
 *   VL53L0X VDD  -> 3.3 V
 *   VL53L0X GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l0x_reader vl53l0x_reader.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- VL53L0X register map (16-bit addresses, big-endian on the bus) ---- */
#define VL53L0X_REG_MODEL_ID          0x010Fu
#define VL53L0X_REG_RANGE_STATUS      0x0089u
#define VL53L0X_REG_RESULT_INTERRUPT 0x0046u
#define VL53L0X_REG_RESULT_DISTANCE  0x0096u
#define VL53L0X_REG_SYSTEM_MODE      0x0080u
#define VL53L0X_REG_SYSTEM_INTERRUPT 0x0046u
#define VL53L0X_REG_SYSTEM_RANGE     0x0082u

#define VL53L0X_MODEL_ID             0xEAu
#define VL53L0X_RANGE_STATUS_READY   0x01u
#define VL53L0X_RANGE_STATUS_ERR     0x04u

#define I2C_BUS        "/dev/i2c-1"
#define VL53L0X_ADDR   0x29
#define POLL_MS        100
#define LOOP_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf))
        return -1;
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint8_t *dst, size_t len)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr))
        return -1;
    if (read(fd, dst, len) != (ssize_t)len)
        return -1;
    return 0;
}

static int i2c_read16_16(int fd, uint16_t reg, uint16_t *dst)
{
    uint8_t buf[2];
    if (i2c_read16(fd, reg, buf, sizeof(buf)) < 0)
        return -1;
    *dst = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int vl53l0x_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read16(fd, VL53L0X_REG_MODEL_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: cannot read model ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Error: model ID mismatch (got 0x%02X, expected 0x%02X)\n",
                id, VL53L0X_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X)\n", id);

    /* Clear any pending interrupt */
    if (i2c_write16(fd, VL53L0X_REG_SYSTEM_INTERRUPT, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt: %s\n", strerror(errno));
    }

    /* Start continuous ranging (bit 0 = range mode, bit 1 = back-to-back) */
    if (i2c_write16(fd, VL53L0X_REG_SYSTEM_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: cannot start ranging: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l0x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int waited = 0;

    /* Poll RESULT_INTERRUPT_STATUS for up to POLL_MS ms */
    while (waited < POLL_MS) {
        if (i2c_read16(fd, VL53L0X_REG_RESULT_INTERRUPT, &status, 1) < 0) {
            fprintf(stderr, "Warning: I2C read of status failed: %s\n", strerror(errno));
            return -1;
        }
        if (status & VL53L0X_RANGE_STATUS_READY)
            break;
        if (status & VL53L0X_RANGE_STATUS_ERR) {
            fprintf(stderr, "Warning: sensor reported error status 0x%02X\n", status);
            return -1;
        }
        usleep(1000);
        waited++;
    }

    if (waited >= POLL_MS) {
        fprintf(stderr, "Warning: timeout waiting for measurement\n");
        return -1;
    }

    if (i2c_read16_16(fd, VL53L0X_REG_RESULT_DISTANCE, distance_mm) < 0) {
        fprintf(stderr, "Warning: I2C read of distance failed: %s\n", strerror(errno));
        return -1;
    }

    /* Clear the interrupt so the next measurement can signal */
    if (i2c_write16(fd, VL53L0X_REG_SYSTEM_INTERRUPT, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt: %s\n", strerror(errno));
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave 0x%02X: %s\n",
                VL53L0X_ADDR, strerror(errno));
        goto cleanup;
    }

    if (vl53l0x_init(fd) < 0) {
        fprintf(stderr, "Error: VL53L0X initialization failed\n");
        goto cleanup;
    }

    printf("Starting continuous distance readings (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t dist = 0;
        if (vl53l0x_read_distance(fd, &dist) < 0) {
            fprintf(stderr, "Warning: read failed, continuing...\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("%s Distance: %u mm\n", ts, dist);
            fflush(stdout);
        }
        usleep(LOOP_MS * 1000);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        /* Put sensor in standby mode before closing */
        (void)i2c_write16(fd, VL53L0X_REG_SYSTEM_MODE, 0x00);
        close(fd);
    }
    return rc;
}

