/*
 * Si1182 proximity reader for Raspberry Pi 3 Model B+
 * I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor address 0x49 (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_prox si1182_prox.c -li2c
 * Run:    sudo ./si1182_prox   (root needed for /dev/i2c-1 on older kernels)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x49
#define PROX_REG       0x18   /* 16-bit proximity result, little-endian */
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single byte to a register, checking for NACK (sensor absent).
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                    reg, strerror(errno));
        else
            fprintf(stderr, "I2C write to reg 0x%02X: short write (%zd bytes)\n",
                    reg, n);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit little-endian value from a register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    ssize_t n = write(fd, &reg_buf, 1);
    if (n != 1) {
        if (n < 0)
            fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                    reg, strerror(errno));
        else
            fprintf(stderr, "I2C write (reg select 0x%02X): short write (%zd bytes)\n",
                    reg, n);
        return -1;
    }

    uint8_t data[2];
    n = read(fd, data, sizeof(data));
    if (n != (ssize_t)sizeof(data)) {
        if (n < 0)
            fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                    reg, strerror(errno));
        else
            fprintf(stderr, "I2C read from reg 0x%02X: short read (%zd bytes)\n",
                    reg, n);
        return -1;
    }

    *out = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

int main(void)
{
    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the I2C bus --- */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire the Si1182 slave address --- */
    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Verify sensor presence with a register read --- */
    uint16_t dummy;
    if (i2c_read_reg16(fd, PROX_REG, &dummy) != 0) {
        fprintf(stderr, "Si1182 not responding at 0x%02X — sensor absent or wiring fault.\n",
                SI1182_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity reader started (I2C addr 0x%02X on %s).\n",
           SI1182_ADDR, I2C_BUS);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        uint16_t prox;
        if (i2c_read_reg16(fd, PROX_REG, &prox) == 0) {
            printf("Proximity: %u\n", prox);
        } else {
            fprintf(stderr, "Read error — continuing.\n");
        }
        usleep(POLL_MS * 1000);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (close(fd) != 0)
        fprintf(stderr, "Warning: close() failed: %s\n", strerror(errno));

    return EXIT_SUCCESS;
}

