static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%04X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- OPT3101 driver ---- */

static int opt3101_init(int fd)
{
    uint16_t chip_id = 0;
    if (i2c_read_reg16(fd, REG_CHIP_ID, &chip_id) != 0) {
        fprintf(stderr, "Cannot read CHIP_ID register.\n");
        return -1;
    }
    if (chip_id != REG_CHIP_ID_VAL) {
        fprintf(stderr, "Unexpected CHIP_ID 0x%04X (expected 0x%04X). "
                        "Sensor not present or wrong device.\n",
                chip_id, REG_CHIP_ID_VAL);
        return -1;
    }
    printf("OPT3101 detected (CHIP_ID = 0x%04X).\n", chip_id);

    /* Minimal configuration: enable channel 0 and start ranging. */
    if (i2c_write_reg16(fd, REG_DEVICE_CONFIG, 0x0001) != 0)
        return -1;
    return 0;
}

static int opt3101_read_distance(int fd, uint16_t *distance)
{
    uint16_t status = 0;
    if (i2c_read_reg16(fd, REG_RESULT_STATUS, &status) != 0)
        return -1;
    if ((status & 0x0001) == 0) {
        /* Ranging not complete yet. */
        return 1;
    }
    if (i2c_read_reg16(fd, REG_RESULT_DISTANCE, distance) != 0)
        return -1;
    return 0;
}

static int opt3101_read_ambient(int fd, uint16_t *ambient)
{
    if (i2c_read_reg16(fd, REG_RESULT_AMBIENT, ambient) != 0)
        return -1;
    return 0;
}

static void opt3101_print_status(uint16_t status)
{
    printf("  STATUS: 0x%04X", status);
    if (status & 0x0001) printf(" RANGE_DONE");
    if (status & 0x0002) printf(" RANGE_ERR");
    if (status & 0x0004) printf(" AMBIENT_DONE");
    if (status & 0x0008) printf(" AMBIENT_ERR");
    if (status & 0x0010) printf(" CONFIG_ERR");
    if (status & 0x0020) printf(" CONFIG_DONE");
    if (status & 0x0040) printf(" CONFIG_ERR");
    if (status & 0x0080) printf(" CONFIG_DONE");
    if (status & 0x0100) printf(" CONFIG_ERR");
    if (status & 0x0200) printf(" CONFIG_DONE");
    if (status & 0x0400) printf(" CONFIG_ERR");
    if (status & 0x0800) printf(" CONFIG_DONE");
    if (status & 0x1000) printf(" CONFIG_ERR");
    if (status & 0x2000) printf(" CONFIG_DONE");
    if (status & 0x4000) printf(" CONFIG_ERR");
    if (status & 0x8000) printf(" CONFIG_DONE");
    printf("\n");
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3101_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                OPT3101_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    if (opt3101_init(fd) != 0) {
        fprintf(stderr, "OPT3101 initialization failed.\n");
        goto cleanup;
    }

    printf("Starting periodic readings (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t distance = 0, ambient = 0;
        int rc_dist = opt3101_read_distance(fd, &distance);
        int rc_amb  = opt3101_read_ambient(fd, &ambient);

        if (rc_dist == 0) {
            uint16_t status = 0;
            if (i2c_read_reg16(fd, REG_RESULT_STATUS, &status) == 0)
                opt3101_print_status(status);
            printf("Distance: %u mm  |  Ambient: %u\n", distance, ambient);
        } else if (rc_dist < 0) {
            fprintf(stderr, "Distance read error.\n");
        }
        /* rc_dist == 1: ranging not complete yet, skip this cycle. */

        usleep(500000); /* 500 ms */
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

