/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VCC  -> 5V  (Pin 2 or 4)
 *   GND  -> GND (Pin 6)
 *   TRIG -> GPIO17 (BCM 17, Pin 11)
 *   ECHO -> GPIO18 (BCM 18, Pin 12) via 1k ohm resistor to GND
 *
 * NOTE: The HC-SR04 is rated for 5V logic. The Raspberry Pi GPIO is 3.3V
 * tolerant. To protect the sensor, use a 1k ohm resistor between the
 * ECHO pin and GND. The 1k resistor limits the ECHO signal to ~3.3V
 * (5V - 1k * 0.7 = 3.3V), which is well within the Pi's acceptable range.
 *
 * Build: gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10
#define READ_INTERVAL_S  1
#define ECHO_TIMEOUT_US  200000   /* 200 ms max wait for echo edges */
#define MAX_PULSE_US     38000    /* HC-SR04 max range ~5.1 m -> ~38 ms */
#define MIN_PULSE_US     0
#define SPEED_OF_SOUND   34300.0  /* cm/s at 20 C */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read distance in centimetres from the HC-SR04.
 * Returns >= 0 on success, -1.0 on timeout / invalid pulse.
 */
static float read_distance(void)
{
    /* Issue a 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (start of pulse) */
    uint32_t start_tick = 0;
    uint32_t deadline   = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (end of pulse) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    }
    uint32_t end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;

    if (pulse_us <= MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: invalid pulse duration %u us (out of range)\n",
                pulse_us);
        return -1.0f;
    }

    /* distance = (pulse_us * speed_of_sound) / 2 / 1e6 */
    return (float)pulse_us * SPEED_OF_SOUND / 20000.0f;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after power-up */
    gpioDelay(100000); /* 100 ms */

    printf("HC-SR04 distance sensor reader started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Interval: %d s\n",
           TRIGGER_PIN, ECHO_PIN, READ_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float distance = read_distance();

        if (distance >= 0.0f) {
            time_t now = time(NULL);
            struct tm tm_info;
            char time_buf[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(time_buf, sizeof(time_buf),
                         "%Y-%m-%d %H:%M:%S", &tm_info);
                printf("[%s] Distance: %.2f cm\n", time_buf, distance);
            } else {
                printf("[timestamp error] Distance: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Warning: failed to read distance this cycle\n");
        }

        /* Sleep for the remainder of the 1 s interval */
        gpioDelay((READ_INTERVAL_S * 1000000) % 1000000);
    }

    /* Clean up GPIO resources */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

