/*
 * IWR1443 mmWave Radar Intrusion Detection System
 * Board:  Raspberry Pi 3 Model B+
 * UART:   /dev/serial0 (default 115200 baud)
 * LED:    GPIO 17 (BCM)
 * Log:    intrusion_log.csv
 *
 * Build:  gcc -O2 -Wall -Wextra -o intrusion intrusion.c -lpthread
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <pthread.h>

#define UART_DEVICE        "/dev/serial0"
#define BAUD_RATE          B115200
#define LED_GPIO           17
#define DISTANCE_THRESHOLD 1.0f   /* meters */
#define ALERT_DURATION_MS  2000
#define LOG_FILE           "intrusion_log.csv"
#define FRAME_HEADER_LEN   8
#define FRAME_DATA_LEN     128    /* 64 16-bit little-endian bins */
#define FRAME_TOTAL_LEN    (FRAME_HEADER_LEN + FRAME_DATA_LEN)
#define POLL_TIMEOUT_MS    1000
#define MAX_RETRIES        3

/* TI mmWave SDK 3.x magic word: 0x02030405 0x0807060504 */
static const uint8_t MAGIC_WORD[FRAME_HEADER_LEN] = {
    0x05, 0x04, 0x06, 0x08, 0x05, 0x04, 0x06, 0x08
};

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp = NULL;
static pthread_mutex_t g_log_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* UART setup                                                          */
/* ------------------------------------------------------------------ */
static int init_uart(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | CSTOPB | CRTSCTS);

    tty.c_iflag  = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK |
                     ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag  = 0;
    tty.c_oflag  = 0;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;   /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* Binary log entry                                                    */
/* ------------------------------------------------------------------ */
static int log_intrusion(float distance)
{
    time_t rawtime;
    struct tm tm_info;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    pthread_mutex_lock(&g_log_mutex);
    if (g_log_fp == NULL) {
        g_log_fp = fopen(LOG_FILE, "a");
        if (g_log_fp == NULL) {
            perror("fopen log");
            pthread_mutex_unlock(&g_log_mutex);
            return -1;
        }
    }
    pthread_mutex_unlock(&g_log_mutex);

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, distance) < 0) {
        perror("fprintf log");
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Alert LED                                                          */
/* ------------------------------------------------------------------ */
static void trigger_alert(int duration_ms)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed; LED will not pulse\n");
        return;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return;
    }

    if (gpioWrite(LED_GPIO, 1) != 0) {
        fprintf(stderr, "gpioWrite on failed\n");
        gpioTerminate();
        return;
    }

    /* Sleep in 100 ms slices so we can exit promptly on signal */
    int remaining = duration_ms;
    while (remaining > 0 && g_running) {
        int chunk = (remaining > 100) ? 100 : remaining;
        usleep(chunk * 1000);
        remaining -= chunk;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite off failed\n");
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Frame processing                                                    */
/* ------------------------------------------------------------------ */
static int find_magic_word(const uint8_t *buf, size_t len)
{
    if (len < FRAME_HEADER_LEN) return -1;

    for (size_t i = 0; i + FRAME_HEADER_LEN <= len; i++) {
        if (memcmp(buf + i, MAGIC_WORD, FRAME_HEADER_LEN) == 0)
            return (int)i;
    }
    return -1;
}

static int process_frame(const uint8_t *frame)
{
    if (frame == NULL) return -1;

    /* Validate CRC (placeholder: check 4-byte CRC field at offset 8) */
    uint32_t crc = 0;
    for (int i = 0; i < 4; i++)
        crc = (crc << 8) ^ ((crc >> 24) ^ frame[8 + i]) & 0xFFFFFFFF;
    if (crc != 0) {
        fprintf(stderr, "CRC mismatch (0x%08X)\n", crc);
        return -1;
    }

    /* Range profile: 64 16-bit little-endian bins starting at offset 12 */
    for (int i = 0; i < 64; i++) {
        uint16_t bin = (uint16_t)(frame[12 + 2 * i] |
                                  (frame[13 + 2 * i] << 8));
        if (bin > 0 && bin <= 1000) {  /* sanity: 0–1 m to 1 km */
            float dist = bin * 0.01f;  /* 1 cm per bin */
            if (dist <= DISTANCE_THRESHOLD) {
                printf("Target detected at %.2f m\n", dist);
                if (log_intrusion(dist) != 0)
                    fprintf(stderr, "Failed to log intrusion\n");
                trigger_alert(ALERT_DURATION_MS);
                return 0;
            }
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        fprintf(stderr, "UART initialization failed\n");
        return EXIT_FAILURE;
    }

    printf("IWR1443 intrusion detection started. Press Ctrl+C to exit.\n");

    uint8_t rxbuf[512];
    size_t  rxlen = 0;

    while (g_running) {
        ssize_t n = read(g_uart_fd, rxbuf + rxlen, sizeof(rxbuf) - rxlen);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(POLL_TIMEOUT_MS * 1000);
                continue;
            }
            perror("read UART");
            break;
        }
        if (n == 0) {
            usleep(POLL_TIMEOUT_MS * 1000);
            continue;
        }

        rxlen += (size_t)n;

        /* Try to find the magic word */
        int idx = find_magic_word(rxbuf, rxlen);
        if (idx < 0) {
            /* Discard all but the last FRAME_TOTAL_LEN bytes */
            if (rxlen > FRAME_TOTAL_LEN) {
                memmove(rxbuf, rxbuf + rxlen - FRAME_TOTAL_LEN, FRAME_TOTAL_LEN);
                rxlen = FRAME_TOTAL_LEN;
            }
            continue;
        }

        /* Shift so magic word is at rxbuf[0] */
        if (idx > 0) {
            memmove(rxbuf, rxbuf + idx, rxlen - idx);
            rxlen -= idx;
        }

        /* Need at least the full frame */
        if (rxlen < FRAME_TOTAL_LEN) {
            usleep(POLL_TIMEOUT_MS * 1000);
            continue;
        }

        /* Process the frame */
        process_frame(rxbuf);

        /* Shift to next potential header */
        memmove(rxbuf, rxbuf + FRAME_TOTAL_LEN, rxlen - FRAME_TOTAL_LEN);
        rxlen -= FRAME_TOTAL_LEN;
    }

    /* Cleanup */
    if (g_uart_fd >= 0) {
        tcflush(g_uart_fd, TCIOFLUSH);
        close(g_uart_fd);
    }
    if (g_log_fp != NULL) {
        pthread_mutex_lock(&g_log_mutex);
        fclose(g_log_fp);
        g_log_fp = NULL;
        pthread_mutex_unlock(&g_log_mutex);
    }
    pthread_mutex_destroy(&g_log_mutex);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

