/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 ultrasonic ToF sensor
 * I2C bus 1, GPIO 17 alert output.
 *
 * Build:  gcc -O2 -Wall -Wextra -o chirp_monitor chirp_monitor.c -li2c -lgpiod
 * Run:    sudo ./chirp_monitor   (root needed for /dev/i2c-1 and /dev/gpiochip0)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- Chirp ICU-20201 constants (datasheet) ---- */
#define I2C_BUS          "/dev/i2c-1"
#define ICU20201_ADDR    0x60          /* 7-bit I2C address */

/* Register map (datasheet) */
#define REG_MODEL_ID      0x00
#define REG_MODEL_ID_VAL  0x2020
#define REG_HW_REV        0x01
#define REG_HW_REV_VAL    0x01
#define REG_DIST_LSB      0x04
#define REG_DIST_MSB      0x05
#define REG_STATUS        0x06
#define REG_CTRL          0x07
#define REG_CTRL_SOFT_RST 0x01
#define REG_CTRL_START    0x02
#define REG_CTRL_MODE     0x03
#define REG_CTRL_MODE_CONT 0x00
#define REG_CTRL_MODE_SINGLE 0x01

#define DISTANCE_THRESHOLD_CM 10.0f
#define ALERT_GPIO_LINE  17          /* BCM 17 */
#define LOG_FILE         "distance_log.txt"
#define POLL_DELAY_MS    100

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_alert_line = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor driver                                                       */
/* ------------------------------------------------------------------ */
static int icu20201_init(int fd)
{
    uint8_t model_id = 0, hw_rev = 0;

    if (i2c_read_reg8(fd, REG_MODEL_ID, &model_id) < 0)
        return -1;
    if (model_id != REG_MODEL_ID_VAL) {
        fprintf(stderr, "Wrong model ID: 0x%04X (expected 0x%04X)\n",
                model_id, REG_MODEL_ID_VAL);
        return -1;
    }

    if (i2c_read_reg8(fd, REG_HW_REV, &hw_rev) < 0)
        return -1;
    if (hw_rev != REG_HW_REV_VAL) {
        fprintf(stderr, "Wrong hardware revision: 0x%02X (expected 0x%02X)\n",
                hw_rev, REG_HW_REV_VAL);
        return -1;
    }

    /* Software reset */
    if (i2c_write_reg8(fd, REG_CTRL, REG_CTRL_SOFT_RST) < 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    /* Start continuous measurement mode */
    if (i2c_write_reg8(fd, REG_CTRL_MODE, REG_CTRL_MODE_CONT) < 0)
        return -1;

    return 0;
}

static int icu20201_read_distance(int fd, float *distance_cm)
{
    uint8_t status = 0, dist_lsb = 0, dist_msb = 0;

    if (i2c_read_reg8(fd, REG_STATUS, &status) < 0)
        return -1;

    /* Bit 0 of STATUS indicates data ready */
    if (!(status & 0x01))
        return 1;  /* not ready yet */

    if (i2c_read_reg8(fd, REG_DIST_LSB, &dist_lsb) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_DIST_MSB, &dist_msb) < 0)
        return -1;

    uint16_t raw = ((uint16_t)dist_msb << 8) | dist_lsb;
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance_cm);
    } else {
        fprintf(fp, "(time-error), Distance: %.2f cm\n", distance_cm);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Alert GPIO                                                          */
/* ------------------------------------------------------------------ */
static void set_alert(int on)
{
    if (g_alert_line)
        gpiod_line_set_value(g_alert_line, on ? 1 : 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_alert_line) {
        gpiod_line_set_value(g_alert_line, 0);
        gpiod_line_release(g_alert_line);
        g_alert_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICU20201_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ICU20201_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (icu20201_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ICU-20201 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request alert line */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_alert_line = gpiod_chip_get_line(g_chip, ALERT_GPIO_LINE);
    if (!g_alert_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                ALERT_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_alert_line, "chirp_alert", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                ALERT_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring distance (threshold %.1f cm). Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD_CM);

