                ALERT_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_alert_line, "chirp_alert", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                ALERT_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring distance (threshold %.1f cm). Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD_CM);

    /* Main loop */
    while (g_running) {
        float distance = 0.0f;
        int rc = icu20201_read_distance(g_i2c_fd, &distance);

        if (rc == 0) {
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
            set_alert(distance < DISTANCE_THRESHOLD_CM);
        } else if (rc < 0) {
