/*
 * Parking-assistance system using VL53L1X on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL  -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c \
 *       -lpigpio -lpthread -lrt
 *
 * Run:
 *   sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define LOG_FILE             "distance_log.csv"
#define POLL_DELAY_US        100000   /* 100 ms */
#define MAX_DISTANCE_MM      20000    /* sanity cap for out-of-range readings */

/* ---- VL53L1X register map (16-bit addresses, big-endian on the bus) ---- */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_MODE_START       0x0007
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK  0x0096
#define VL53L1X_REG_RESULT_FINAL_SPAD       0x0098
#define VL53L1X_REG_RESULT_FINAL_SIGMA      0x009A
#define VL53L1X_REG_RESULT_FINAL_RANGE_MM   0x009C

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address + 1 byte payload.                   */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_write8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address, then N bytes.                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_read(int handle, uint16_t reg, uint8_t *dst, size_t n)
{
    char addr[2];
    addr[0] = (char)(reg >> 8);
    addr[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)dst, (int)n) != (int)n) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%04X, %zu bytes) failed\n",
                reg, n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X driver.                                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write8(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(2000);  /* 2 ms settle */

    /* Start continuous ranging */
    if (vl53l1x_write8(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the latest distance in millimetres.                            */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2];

    /* Check if data is ready (bit 0 of RESULT_RANGE_STATUS) */
    if (vl53l1x_read(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* No new data yet — treat as out-of-range */
        *distance_mm = 0;
        return 0;
    }

    /* Read 2-byte distance (big-endian) */
    if (vl53l1x_read(handle, VL53L1X_REG_RESULT_FINAL_RANGE_MM, data, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row.  Creates + writes header if the file is new.    */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    int  file_exists = (fseek(fp, 0, SEEK_END) == 0);
    long pos = ftell(fp);

    if (file_exists && pos > 0) {
        /* File already exists and contains data — do not write header */
        if (fprintf(fp, "%ld,%u\n", (long)time(NULL), distance_mm) < 0) {
            fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
            return -1;
        }
    } else {
        /* New file — write header and one row */
        if (fprintf(fp, "timestamp,distance_mm\n") < 0) {
            fprintf(stderr, "[ERROR] fprintf header failed: %s\n", strerror(errno));
            return -1;
        }
        if (fprintf(fp, "%ld,%u\n", (long)time(NULL), distance_mm) < 0) {
            fprintf(stderr, "[ERROR] fprintf first row failed: %s\n", strerror(errno));
            return -1;
        }
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parking guidance message.                                           */
/* ------------------------------------------------------------------ */
static void parking_guidance(uint16_t distance_mm)
{
    if (distance_mm < 300) {
        printf("STOP! Obstacle within 300 mm.\n");
    } else if (distance_mm < 600) {
        printf("APPROACH! Obstacle 300-600 mm.\n");
    } else if (distance_mm < 1200) {
        printf("SLOW! Obstacle 600-1200 mm.\n");
    } else {
        printf("CLEAR! Obstacle >1200 mm.\n");
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] fopen(%s): %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking assistance started.  Logging to %s.  Ctrl+C to exit.\n",
           LOG_FILE);
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "[ERROR] Distance read failed — continuing.\n");
        } else {
            if (distance_mm > MAX_DISTANCE_MM) {
                fprintf(stderr, "[WARN] Distance %u mm exceeds sanity cap — "
                                "out of range or sensor fault.\n", distance_mm);
                distance_mm = 0;
            }

            if (log_distance(g_log_file, distance_mm) != 0) {
                fprintf(stderr, "[ERROR] Logging failed — continuing.\n");
            }

            parking_guidance(distance_mm);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    fflush(stdout);

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

