/*
 * CH201 Ultrasonic ToF Distance Sensor + LED Blink Demo
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO 2 = SDA, GPIO 3 = SCL)
 * Sensor: TDK InvenSense CH201 (I2C address 0x30)
 * LED:    GPIO 18 (BCM), via 330 ohm resistor to 3.3 V
 *
 * Build:  gcc -O2 -Wall -o ch201_led ch201_led.c -lpigpio -lrt
 * Run:    sudo ./ch201_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define CH201_I2C_ADDR       0x30
#define LED_GPIO             18
#define SAMPLE_PERIOD_US     100000          /* 100 ms between samples */
#define LED_HALF_CYCLE_US    10000           /* 10 ms per half-cycle       */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000           /* 10 ms between retries      */
#define MAX_DISTANCE_MM      4000            /* CH201 max range            */

/* CH201 register addresses (16-bit, big-endian on the bus) */
#define CH201_REG_MODEL_ID   0x00
#define CH201_REG_SYS_CTRL   0x01
#define CH201_REG_SYS_STATUS 0x02
#define CH201_REG_RANGE_CFG  0x03
#define CH201_REG_RANGE_DATA 0x04
#define CH201_REG_LED_FREQ   0x05

#define CH201_MODEL_ID       0x01
#define CH201_SYS_CTRL_SOFT_RESET 0x01
#define CH201_SYS_CTRL_START      0x02
#define CH201_RANGE_CFG_DEFAULT   0x00
#define CH201_LED_FREQ_DEFAULT    0x00

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal Handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C Helpers --------------------------------- */
static int i2c_write_reg16(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_reg16(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* --------------------------- CH201 Driver -------------------------------- */
static int ch201_init(int handle)
{
    uint8_t model_id = 0;
    uint8_t status   = 0;

    /* Soft-reset */
    if (i2c_write_reg16(handle, CH201_REG_SYS_CTRL, CH201_SYS_CTRL_SOFT_RESET) < 0) {
        fprintf(stderr, "CH201 soft-reset write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000);  /* 2 ms settle */

    /* Verify model ID */
    if (i2c_read_reg16(handle, CH201_REG_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "CH201 model-ID read failed: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != CH201_MODEL_ID) {
        fprintf(stderr, "CH201 model-ID mismatch: got 0x%02X, expected 0x%02X\n",
                model_id, CH201_MODEL_ID);
        return -1;
    }

    /* Clear any pending errors */
    if (i2c_read_reg16(handle, CH201_REG_SYS_STATUS, &status, 1) < 0) {
        fprintf(stderr, "CH201 sys-status read failed: %s\n", strerror(errno));
        return -1;
    }

    /* Configure range */
    if (i2c_write_reg16(handle, CH201_REG_RANGE_CFG, CH201_RANGE_CFG_DEFAULT) < 0) {
        fprintf(stderr, "CH201 range-config write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg16(handle, CH201_REG_SYS_CTRL, CH201_SYS_CTRL_START) < 0) {
        fprintf(stderr, "CH201 start write failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(2000);  /* 2 ms for first measurement */
    return 0;
}

static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t data[2] = {0, 0};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(handle, CH201_REG_RANGE_DATA, data, 2) == 2) {
            *distance_mm = ((uint16_t)data[0] << 8) | data[1];
            return 0;
        }
        fprintf(stderr, "CH201 read failed (attempt %d/%d): %s\n",
                retries + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(RETRY_DELAY_US);
        retries++;
    }
    return -1;
}

static int ch201_set_led_frequency(int handle, uint8_t freq)
{
    return i2c_write_reg16(handle, CH201_REG_LED_FREQ, freq);
}

/* ------------------------------- LED ------------------------------------- */
static void led_set_frequency(uint16_t distance_mm)
{
    /*
     * Blink faster as distance decreases.
     * CH201 LED_FREQ: 0x00 = 1000 Hz, 0x01 = 500 Hz, 0x02 = 250 Hz, 0x03 = 125 Hz,
     * 0x04 = 62.5 Hz, 0x05 = 31.25 Hz, 0x06 = 15.625 Hz, 0x07 = 7.8125 Hz.
     * We map 0–4000 mm to 0x00 (1000 Hz) at far, 0x07 (7.8125 Hz) at near.
     */
    uint8_t freq = (distance_mm < MAX_DISTANCE_MM) ? 0x07 : 0x00;
    if (ch201_set_led_frequency(g_i2c_handle, freq) < 0) {
        fprintf(stderr, "LED frequency write failed: %s\n", strerror(errno));
    }
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X: %s\n",
                I2C_BUS, CH201_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (ch201_init(g_i2c_handle) < 0) {
        fprintf(stderr, "CH201 initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance sensor + LED blink running. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance_mm = 0;
        if (ch201_read_distance(g_i2c_handle, &distance_mm) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            printf("%s  Distance: %4u mm  LED: %s\n",
                   ts, distance_mm,
                   (distance_mm < MAX_DISTANCE_MM) ? "ON" : "OFF");

            led_set_frequency(distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
        }

        /* Keep LED on for one half-cycle, then off for the other half */
        gpioWrite(LED_GPIO, 1);
        gpioDelay(LED_HALF_CYCLE_US);
        gpioWrite(LED_GPIO, 0);
        gpioDelay(LED_HALF_CYCLE_US);
    }

    /* --------------------------- Cleanup ------------------------------- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

