    if (ch201_init(g_i2c_handle) < 0) {
        fprintf(stderr, "CH201 initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance sensor + LED blink running. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance_mm = 0;
        if (ch201_read_distance(g_i2c_handle, &distance_mm) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            printf("%s  Distance: %4u mm  LED: %s\n",
                   ts, distance_mm,
                   (distance_mm < MAX_DISTANCE_MM) ? "ON" : "OFF");

            led_set_frequency(distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
        }

        /* Keep LED on for one half-cycle, then off for the other half */
        gpioWrite(LED_GPIO, 1);
        gpioDelay(LED_HALF_CYCLE_US);
        gpioWrite(LED_GPIO, 0);
        gpioDelay(LED_HALF_CYCLE_US);
    }

    /* --------------------------- Cleanup ------------------------------- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

