#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x5A
#define LOG_FILE "distance_log.csv"
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_MS 20

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t bytes = read(fd, buf, len);
    if (bytes < 0 || (size_t)bytes != len) {
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance) {
    uint8_t cmd = 0x01;
    uint8_t data[2];

    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, 2) < 0) {
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

static int log_data(const char *filename, int distance) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d\n", timestamp, distance);
    fclose(fp);
    return 0;
}

int main(void) {
    int fd = -1;
    int distance;
    int retries;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MLX75030_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        retries = 0;
        distance = -1;

        while (retries < MAX_RETRIES && distance < 0) {
            if (read_distance(fd, &distance) < 0) {
                fprintf(stderr, "Error reading distance (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
                retries++;
                usleep(10000);
            }
        }

        if (distance >= 0) {
            if (log_data(LOG_FILE, distance) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    if (fd >= 0) {
        close(fd);
    }

    printf("\nProgram terminated gracefully.\n");
    return 0;
}

