#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define POLL_DELAY_US     10000   /* 10 ms */
#define LOG_FILE_NAME     "proximity_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 UTC timestamp into caller-provided buffer         */
/* ------------------------------------------------------------------ */
static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Append a single log line: timestamp, sensor_id, event_type         */
/* ------------------------------------------------------------------ */
static int log_event(int sensor_id, const char *event_type)
{
    char timestamp[32];

    get_iso8601_timestamp(timestamp, sizeof(timestamp));

    if (fprintf(log_file, "%s, Sensor %d, %s\n",
                timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor with software debounce:                              */
/*   - Read the pin twice (with a short delay between reads)           */
/*   - If both reads agree, return the value                           */
/*   - If they differ, treat the second read as the valid reading      */
/* ------------------------------------------------------------------ */
static int read_sensor_debounced(int gpio_pin)
{
    int first = gpioRead(gpio_pin);
    if (first < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n",
                gpio_pin, pigpio_error(first));
        return -1;
    }

    gpioDelay(DEBOUNCE_DELAY_US);

    int second = gpioRead(gpio_pin);
    if (second < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n",
                gpio_pin, pigpio_error(second));
        return -1;
    }

    /* If the second read disagrees with the first, treat the second
       read as the valid reading (debounce heuristic). */
    if (first != second) {
        return second;
    }

    return first;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;

    /* ---- Initialise pigpio ---- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n",
                pigpio_error(ret));
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity monitoring started.  Sensor 1=GPIO%d, Sensor 2=GPIO%d\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    int prev_state1 = -1;
    int prev_state2 = -1;

    while (program_running) {
        int s1 = read_sensor_debounced(SENSOR_1_GPIO);
        int s2 = read_sensor_debounced(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* ---- Log state transitions ---- */
        if (s1 != prev_state1) {
            if (log_event(1, s1 == 1 ? "DETECTED" : "CLEARED") != 0) {
                fprintf(stderr, "Logging failed for sensor 1\n");
            }
            prev_state1 = s1;
        }
        if (s2 != prev_state2) {
            if (log_event(2, s2 == 1 ? "DETECTED" : "CLEARED") != 0) {
                fprintf(stderr, "Logging failed for sensor 2\n");
            }
            prev_state2 = s2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
    log_file = NULL;

    /* Release pigpio resources */
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

