#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x60
#define MEAS_STATUS    0x00
#define MEAS_CMD       0x01
#define MEAS_CMD_START 0x01
#define MEAS_TIMEOUT_MS 50
#define SAMPLE_DELAY_MS 500
#define CSV_FILENAME   "distance_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_byte: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_byte: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int ch101_start_measurement(int fd)
{
    return i2c_write_byte(fd, MEAS_CMD, MEAS_CMD_START);
}

static int ch101_wait_measurement(int fd)
{
    uint8_t status;
    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 5) {
        if (i2c_read_byte(fd, MEAS_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            return 0;
        usleep(5000);
    }
    fprintf(stderr, "CH101 measurement timeout after %d ms\n", MEAS_TIMEOUT_MS);
    return -1;
}

static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    if (ch101_start_measurement(fd) != 0)
        return -1;
    if (ch101_wait_measurement(fd) != 0)
        return -1;
