#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29

#define VL53L5CX_REG_SOFTWARE_RESET 0x0000
#define VL53L5CX_REG_SYSTEM_MODE 0x0080
#define VL53L5CX_REG_RANGE_CONFIG 0x0081
#define VL53L5CX_REG_RANGE_STATUS 0x0082
#define VL53L5CX_REG_RANGE_DATA 0x0083

#define VL53L5CX_SOFT_RESET 0x00
#define VL53L5CX_SYSTEM_MODE_SINGLE_RANGE 0x01
#define VL53L5CX_RANGE_CONFIG_8X8 0x00

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select) for reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l5cx_init(int fd) {
    if (i2c_write_reg16(fd, VL53L5CX_REG_SOFTWARE_RESET, VL53L5CX_SOFT_RESET) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, VL53L5CX_REG_RANGE_CONFIG, VL53L5CX_RANGE_CONFIG_8X8) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_MODE, VL53L5CX_SYSTEM_MODE_SINGLE_RANGE) < 0) return -1;
    return 0;
}

static int vl53l5cx_read_zones(int fd, uint16_t *distances) {
    uint8_t status;
    if (i2c_read_reg16(fd, VL53L5CX_REG_RANGE_STATUS, &status, 1) < 0) return -1;
    if ((status & 0x01) == 0) {
        fprintf(stderr, "Sensor not ready (status=0x%02X)\n", status);
        return -1;
    }
    uint8_t data[64];
    if (i2c_read_reg16(fd, VL53L5CX_REG_RANGE_DATA, data, 64) < 0) return -1;
    for (int i = 0; i < 64; i++) {
        distances[i] = (uint16_t)data[i];
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L5CX_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (vl53l5cx_init(fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed\n");
        close(fd);
        return 1;
    }

    printf("VL53L5CX initialized. Logging 64 zone distances every 500ms...\n");

    while (running) {
        uint16_t distances[64];
        if (vl53l5cx_read_zones(fd, distances) == 0) {
            printf("Zone Distances: ");
            for (int i = 0; i < 64; i++) {
                printf("%u ", distances[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Failed to read zone distances\n");
        }
        usleep(500000);
    }

    printf("\nExiting...\n");
    close(fd);
    return 0;
}

