/*
 * MLX75030 ToF distance sensor reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   MLX75030 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   MLX75030 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   MLX75030 VDD  -> 3.3 V
 *   MLX75030 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75030_reader mlx75030_reader.c -li2c
 * Run:    sudo ./mlx75030_reader   (or ensure user is in the 'i2c' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MLX75030 register map (subset) ---- */
#define MLX75030_I2C_ADDR        0x32
#define MLX75030_REG_MODEL_ID    0x00
#define MLX75030_REG_DIST_LSB    0x04
#define MLX75030_REG_DIST_MSB    0x05
#define MLX75030_REG_STATUS      0x06
#define MLX75030_REG_CONFIG      0x0A
#define MLX75030_REG_RANGE_CFG   0x0B
#define MLX75030_REG_INT_CFG     0x0C
#define MLX75030_REG_INT_STATUS  0x0D
#define MLX75030_REG_INT_CLEAR   0x0E

#define I2C_BUS_NAME   "/dev/i2c-1"
#define SAMPLE_PERIOD_MS  100
#define MAX_RETRIES       3
#define RETRY_DELAY_MS    10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (write(fd, buf, sizeof(buf)) == (ssize_t)sizeof(buf))
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg select 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        uint8_t val;
        if (read(fd, &val, 1) != 1) {
            fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        *out = val;
        return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* MLX75030 driver                                                     */
/* ------------------------------------------------------------------ */

static int mlx75030_init(int fd)
{
    uint8_t model_id = 0;
    if (i2c_read_reg8(fd, MLX75030_REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Cannot read MODEL_ID — sensor may be absent or bus error.\n");
        return -1;
    }
    printf("MLX75030 detected (MODEL_ID = 0x%02X).\n", model_id);

    /* Minimal configuration: enable range measurement, set default range. */
    if (i2c_write_reg8(fd, MLX75030_REG_RANGE_CFG, 0x01) != 0) {
        fprintf(stderr, "Failed to write RANGE_CFG.\n");
        return -1;
    }
    if (i2c_write_reg8(fd, MLX75030_REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Failed to write CONFIG.\n");
        return -1;
    }
    return 0;
}

static int mlx75030_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t dist_lsb = 0, dist_msb = 0;

    if (i2c_read_reg8(fd, MLX75030_REG_DIST_LSB, &dist_lsb) != 0)
        return -1;
    if (i2c_read_reg8(fd, MLX75030_REG_DIST_MSB, &dist_msb) != 0)
        return -1;

    *distance_mm = ((uint16_t)dist_msb << 8) | dist_lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MLX75030_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (mlx75030_init(fd) != 0) {
        fprintf(stderr, "MLX75030 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Starting distance measurements (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t distance = 0;
        if (mlx75030_read_distance(fd, &distance) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            struct tm tm_info;
            localtime_r(&ts.tv_sec, &tm_info);
            char time_buf[32];
            strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
