/*
 * VL53L4CX time-of-flight distance reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   VL53L4CX SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   VL53L4CX SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   VL53L4CX VDD  -> 3.3 V
 *   VL53L4CX GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l4cx_reader vl53l4cx_reader.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./vl53l4cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- VL53L4CX register map (16-bit addresses, big-endian on the bus) ---- */
#define VL53L4CX_I2C_ADDR        0x29
#define VL53L4CX_REG_SOFT_RESET  0x0000
#define VL53L4CX_REG_SYSTEM_CTRL 0x0001
#define VL53L4CX_REG_SYSTEM_INT  0x0002
#define VL53L4CX_REG_RESULT_DIST 0x0014
#define VL53L4CX_REG_RESULT_INT  0x0016

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register (pigpio i2cWriteI2CBlockData sends data as    */
/* bytes, so we build the 16-bit address and payload ourselves).       */
/* ------------------------------------------------------------------ */
static int vl53l4cx_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)((reg >> 8) & 0xFF);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;

    if (i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2) < 0) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (big-endian on the bus).                     */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];

    addr[0] = (char)((reg >> 8) & 0xFF);
    addr[1] = (char)(reg & 0xFF);

    if (i2cWriteI2CBlockData(handle, addr[0], &addr[1], 1) < 0) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadI2CBlockData(handle, addr[0], data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L4CX sensor.                                      */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int handle)
{
    /* Soft reset: write 0x00 then 0x01 to the reset register. */
    if (vl53l4cx_write_reg16(handle, VL53L4CX_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    if (vl53l4cx_write_reg16(handle, VL53L4CX_REG_SOFT_RESET, 0x01) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Start continuous ranging (bit 0 = VL53L4CX_SYSRANGE_START). */
    if (vl53l4cx_write_reg16(handle, VL53L4CX_REG_SYSTEM_CTRL, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit distance value from the result register.              */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t raw;
    if (vl53l4cx_read_reg16(handle, VL53L4CX_REG_RESULT_DIST, &raw) < 0)
        return -1;

    *distance_mm = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the interrupt status register.                                 */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_interrupt(int handle, uint16_t *status)
{
    return vl53l4cx_read_reg16(handle, VL53L4CX_REG_SYSTEM_INT, status);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, VL53L4CX_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus 1, addr 0x%02X): %s\n",
                VL53L4CX_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l4cx_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L4CX initialized. Polling every 500 ms. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t status = 0;
        uint16_t distance = 0;

        if (vl53l4cx_read_interrupt(g_i2c_handle, &status) < 0) {
            fprintf(stderr, "Failed to read interrupt status; retrying.\n");
            gpioDelay(500000);
            continue;
        }

        if ((status & 0x01) == 0) {
            /* No new measurement ready yet. */
            gpioDelay(500000);
            continue;
        }

        if (vl53l4cx_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "Failed to read distance; retrying.\n");
            gpioDelay(500000);
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("clock_gettime");
            gpioDelay(500000);
            continue;
        }

        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);

        char timestamp[40];
        strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info);

        printf("Timestamp: %s.%06ld, Distance: %u mm\n",
               timestamp, ts.tv_nsec / 1000, distance);

        fflush(stdout);

        /* Clear the interrupt so the next measurement can be reported. */
        (void)vl53l4cx_write_reg16(g_i2c_handle, VL53L4CX_REG_SYSTEM_INT, 0x00);

        gpioDelay(500000); /* 500 ms */
    }

    /* ---- Graceful cleanup ---- */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

