#define REG_SYSTEM_MODE      0x0001
#define REG_RANGE_CONFIG     0x005E
#define REG_RESULT_INT_STA   0x0044
#define REG_RESULT_RANGE     0x0062

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
