}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers (VL53L1X uses 16-bit register addresses)      */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* VL53L1X initialization                                              */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: soft reset write failed\n");
        return -1;
    }
    gpioDelay(2000);                       /* 2 ms settle */

    /* Clear any pending interrupt */
    uint8_t int_sta;
    if (i2c_read_reg16(handle, REG_RESULT_INT_STA, &int_sta, 1) < 0) {
        fprintf(stderr, "Error: failed to read interrupt status\n");
        return -1;
    }

    /* Set continuous ranging mode */
    if (i2c_write_reg16(handle, REG_SYSTEM_MODE, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set continuous mode\n");
        return -1;
    }

    /* Configure timing budget (e.g., 50 ms) */
    if (i2c_write_reg16(handle, REG_RANGE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set timing budget\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance (mm) with retry                                       */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle)
{
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        /* Trigger a single measurement */
        if (i2c_write_reg16(handle, REG_SYSTEM_MODE, 0x01) < 0) {
            fprintf(stderr, "Error: trigger write failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000);               /* 10 ms backoff */
            continue;
        }

        /* Poll for data-ready (bit 0 of RESULT_INT_STA) */
        for (int i = 0; i < 50; i++) {
            if (i2c_read_reg16(handle, REG_RESULT_INT_STA, buf, 1) < 0) {
                fprintf(stderr, "Error: interrupt status read failed (attempt %d)\n", retries + 1);
                retries++;
                gpioDelay(10000);
                break;
            }
            if (buf[0] & 0x01) {
                /* Read 2-byte distance (big-endian) */
                if (i2c_read_reg16(handle, REG_RESULT_RANGE, buf, 2) < 0) {
                    fprintf(stderr, "Error: distance read failed (attempt %d)\n", retries + 1);
                    retries++;
                    gpioDelay(10000);
                    break;
                }
                return (buf[0] << 8) | buf[1];
            }
            gpioDelay(2000);                /* 2 ms poll interval */
        }

        /* If we got here, the measurement didn't complete */
        retries++;
        gpioDelay(10000);
    }

    fprintf(stderr, "Error: distance read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure buzzer GPIO */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
