    gpioWrite(BUZZER_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int distance = vl53l1x_read_distance(g_i2c_handle);

        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            gpioWrite(BUZZER_GPIO, (distance < DISTANCE_THRESHOLD) ? 1 : 0);
        } else {
            fprintf(stderr, "Warning: distance read failed, skipping cycle\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

