/*
 * Parking-assist system for Raspberry Pi 4 Model B.
 *
 * HC-SR04 ultrasonic sensor:
 *   Trigger -> GPIO 23 (BCM)
 *   Echo    -> GPIO 24 (BCM)
 *
 * SG90 servo:
 *   Control -> GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lpigpio -lrt
 * Run:    sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN  23
#define ECHO_PIN     24
#define SERVO_PIN    17

/* ---- Physical constants ---- */
#define SPEED_OF_SOUND_CM_PER_S  34300.0
#define MIN_DISTANCE_CM          2.0
#define MAX_DISTANCE_CM          400.0
#define MIN_ANGLE_DEG            -90.0
#define MAX_ANGLE_DEG            90.0

/* ---- Timing constants ---- */
#define TRIGGER_PULSE_US         10
#define ECHO_TIMEOUT_US          50000   /* 50 ms */
#define LOOP_DELAY_US            200000  /* 200 ms */
#define TRIGGER_SETTLE_US        1000    /* 1 ms */

/* ---- Sentinel values ---- */
#define DISTANCE_ERROR           (-1.0f)
#define SERVO_ERROR              (-1000)

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_initialized = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; defer cleanup to main()             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read distance from HC-SR04                                          */
/* Returns distance in cm on success, DISTANCE_ERROR on timeout/error  */
/* ------------------------------------------------------------------ */
static float read_distance(void)
{
    /* Issue 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return DISTANCE_ERROR;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return DISTANCE_ERROR;
    }

    /* Wait for echo rising edge (timeout if stuck low) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout (sensor absent or not responding)\n");
            return DISTANCE_ERROR;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout if stuck high) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return DISTANCE_ERROR;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    float distance_cm = (pulse_us * SPEED_OF_SOUND_CM_PER_S) / 2000000.0f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return DISTANCE_ERROR;
    }
    return distance_cm;
}

/* ------------------------------------------------------------------ */
/* Map distance to servo angle and drive the servo                     */
/* Returns 0 on success, SERVO_ERROR on gpioWrite failure              */
/* ------------------------------------------------------------------ */
static int set_servo_angle(float distance_cm)
{
    if (distance_cm < 0.0f) {
        fprintf(stderr, "Error: invalid distance for servo calculation\n");
        return SERVO_ERROR;
    }

    float angle = MIN_ANGLE_DEG +
                  (distance_cm - MIN_DISTANCE_CM) *
                  (MAX_ANGLE_DEG - MIN_ANGLE_DEG) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
    if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;

    /* SG90: 500 µs pulse = 0°, 2500 µs pulse = 180° */
    int pulse_us = (int)(500.0f + (angle / 180.0f) * 2400.0f);
    if (pulse_us < 500 || pulse_us > 2500) {
        fprintf(stderr, "Error: servo pulse %d µs out of range\n", pulse_us);
        return SERVO_ERROR;
    }

    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d µs\n", pulse_us);
        return SERVO_ERROR;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to sensor_data.log           */
/* ------------------------------------------------------------------ */
static void log_data(float distance_cm)
{
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        perror("Error opening sensor_data.log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_cm);

    if (fclose(fp) != 0) {
        perror("Error closing sensor_data.log");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — release servo and terminate pigpio                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_initialized) {
        /* Stop servo pulses (pulse 0 disables output) */
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_initialized = 1;

    /* ---- Configure GPIO modes ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as input\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: cannot initialise trigger low\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float distance = read_distance();

        if (distance >= 0.0f) {
            if (set_servo_angle(distance) == 0) {
                log_data(distance);
                printf("Distance: %.2f cm | Servo: %.1f°\n",
                       distance, MIN_ANGLE_DEG +
                       (distance - MIN_DISTANCE_CM) *
                       (MAX_ANGLE_DEG - MIN_ANGLE_DEG) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
            } else {
                fprintf(stderr, "Error: failed to set servo angle\n");
            }
        } else {
            fprintf(stderr, "Error: failed to read distance\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

