/*
 * VL53L1X distance monitor with buzzer alert.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: VL53L1X on address 0x29
 * Buzzer: GPIO23 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_monitor vl53l1x_monitor.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <sys/wait.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define BUZZER_GPIO          23
#define DISTANCE_THRESHOLD   100          /* mm */
#define POLL_INTERVAL_US     50000        /* 50 ms */
#define TIMING_BUDGET_US     50000        /* 50 ms */
#define MSG_QUEUE_KEY        0x12345678
#define MSG_QUEUE_ID         -1
#define MSG_QUEUE_SIZE       10
#define MSG_QUEUE_MSG_SIZE   256

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET       0x0003
#define REG_SYSTEM_MODE      0x0001
#define REG_RANGE_CONFIG     0x005E
#define REG_RESULT_INT_STA   0x0044
#define REG_RESULT_RANGE     0x0062

/* ---- Data structures ---- */
typedef struct {
    long    mtype;
    char    mtext[MSG_QUEUE_MSG_SIZE];
} msgbuf_t;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static int  g_msg_queue_id = MSG_QUEUE_ID;
static bool g_pigpio_inited = false;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg16(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "i2c_read_reg16 read(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- VL53L1X driver ---- */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);                       /* 1 ms settle */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);                      /* 10 ms */

    /* Set timing budget to 50 ms (0x005E = 0x0000 0000 0000 0000 0000 0000 0000 0000) */
    if (i2c_write_reg16(handle, REG_RANGE_CONFIG, 0x00) < 0) return -1;

    /* Start continuous ranging */
    if (i2c_write_reg16(handle, REG_SYSTEM_MODE, 0x40) < 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2];
    int     elapsed = 0;

    /* Poll data-ready bit (bit 0 of RESULT_INT_STA) */
    while (elapsed < TIMING_BUDGET_US) {
        if (i2c_read_reg16(handle, REG_RESULT_INT_STA, &status, 1) < 0)
            return -1;
        if (status & 0x01) break;
        gpioDelay(1000);                   /* 1 ms */
        elapsed += 1000;
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "VL53L1X timeout: data not ready\n");
        return -1;
    }

    /* Read 2-byte distance (big-endian) */
    if (i2c_read_reg16(handle, REG_RESULT_RANGE, data, 2) < 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];

    /* Clear interrupt */
    if (i2c_write_reg16(handle, REG_RESULT_INT_STA, 0x01) < 0)
        return -1;

    return 0;
}

/* ---- Message queue ---- */
static int msg_queue_init(void)
{
    key_t key = MSG_QUEUE_KEY;
    int   id  = msgget(key, IPC_CREAT | 0666);
    if (id < 0) {
        perror("msgget");
        return -1;
    }
    return id;
}

static int msg_queue_send(int id, const char *msg)
{
    msgbuf_t msgbuf;
    msgbuf.mtype = 1;
    strncpy(msgbuf.mtext, msg, MSG_QUEUE_MSG_SIZE - 1);
    msgbuf.mtext[MSG_QUEUE_MSG_SIZE - 1] = '\0';

    if (msgsnd(id, &msgbuf, strlen(msg) + 1, 0) < 0) {
        perror("msgsnd");
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_msg_queue_id != MSG_QUEUE_ID && g_msg_queue_id >= 0) {
        msgctl(g_msg_queue_id, IPC_RMID, NULL);
        g_msg_queue_id = MSG_QUEUE_ID;
    }
    if (g_pigpio_inited) {
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure buzzer GPIO */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);

    /* Initialize message queue */
    g_msg_queue_id = msg_queue_init();
    if (g_msg_queue_id < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance = 0;
        char     msg[MSG_QUEUE_MSG_SIZE];

        if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
            snprintf(msg, sizeof(msg), "Distance: %u mm", distance);
            printf("%s\n", msg);

            if (msg_queue_send(g_msg_queue_id, msg) < 0) {
                fprintf(stderr, "Failed to send message to queue\n");
            }

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
            gpioWrite(BUZZER_GPIO, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

