/*
 * Parking sensor — HC-SR04 on Raspberry Pi 3 Model B+
 *   Trigger: BCM 17  Echo: BCM 27  Buzzer: BCM 22
 *   Library: pigpio (interrupt-driven, no busy-wait)
 *
 * Build:  gcc -O2 -Wall -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:    sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define TRIGGER_PULSE_US 10          /* HC-SR04 requires >=10 us HIGH pulse */
#define ECHO_TIMEOUT_US  30000       /* 30 ms — covers ~5 m round trip */
#define SAMPLE_PERIOD_US 100000      /* 100 ms between readings */
#define BUZZER_THRESHOLD_CM 30.0f
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f

/* ------------------------------------------------------------------ */
/* Shared state between ISR and main thread                           */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_pulse_start = 0;
static volatile uint32_t g_pulse_end   = 0;
static volatile bool     g_echo_seen   = false;
static volatile bool     g_echo_active = false;
static volatile bool     g_running     = true;

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static uint32_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0;
    }
    return (uint32_t)(ts.tv_sec * 1000000ULL + ts.tv_nsec / 1000ULL);
}

static void trigger_pulse(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0)
        fprintf(stderr, "Warning: gpioWrite(trigger HIGH) failed\n");
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0)
        fprintf(stderr, "Warning: gpioWrite(trigger LOW) failed\n");
}

/* ------------------------------------------------------------------ */
/* ISR                                                                 */
/* ------------------------------------------------------------------ */

static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)userdata;

    if (gpio != ECHO_PIN)
        return;

    if (level == 1) {
        /* Rising edge — echo pulse starts */
        g_pulse_start = tick;
        g_echo_seen   = false;
        g_echo_active = true;
    } else if (level == 0 && g_echo_active) {
        /* Falling edge — echo pulse ends */
        g_pulse_end   = tick;
        g_echo_seen   = true;
        g_echo_active = false;
    }
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                               */
/* ------------------------------------------------------------------ */

/*
 * pigpio ticks are 32-bit microseconds and wrap every ~71.6 min.
 * This helper computes (b - a) modulo 2^32 so the subtraction is
 * correct even across a wraparound.
 */
static uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* unsigned subtraction wraps correctly */
}

static float calculate_distance_cm(uint32_t pulse_us)
{
    /*
     * Speed of sound ≈ 343 m/s = 0.0343 cm/µs.
     * distance_cm = (pulse_us * 0.0343) / 2
     */
    return (float)pulse_us * 0.0343f / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Ensure buzzer is off */
    gpioWrite(BUZZER_PIN, 0);

    /* Release ISR */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    /* Close pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --------------------------------------- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(buzzer) failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure known initial states -------------------------------- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* --- Register ISR ----------------------------------------------- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx(echo) failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling -------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking sensor ready.  Trigger=BCM%d  Echo=BCM%d  Buzzer=BCM%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        /* Reset echo tracking */
        g_echo_seen   = false;
        g_echo_active = false;

        trigger_pulse();

        /* Wait for echo with timeout */
        uint32_t wait_start = now_us();
        while (!g_echo_seen && g_running) {
            if (tick_diff(wait_start, now_us()) > ECHO_TIMEOUT_US)
                break;
            gpioDelay(100);  /* poll every 100 µs */
        }

        if (!g_running)
            break;

        if (!g_echo_seen) {
            printf("Sensor absent: no echo received within %d µs.\n",
                   ECHO_TIMEOUT_US);
        } else {
            uint32_t pulse_us = tick_diff(g_pulse_start, g_pulse_end);
            float distance = calculate_distance_cm(pulse_us);

            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                printf("Invalid reading: %.2f cm (out of range)\n", distance);
            } else {
                printf("Distance: %.2f cm\n", distance);
                if (distance < BUZZER_THRESHOLD_CM) {
                    if (gpioWrite(BUZZER_PIN, 1) < 0)
                        fprintf(stderr, "Warning: gpioWrite(buzzer ON) failed\n");
                } else {
                    if (gpioWrite(BUZZER_PIN, 0) < 0)
                        fprintf(stderr, "Warning: gpioWrite(buzzer OFF) failed\n");
                }
            }
        }

        /* Sleep for the remainder of the 100 ms period */
        uint32_t elapsed = tick_diff(wait_start, now_us());
        if (elapsed < SAMPLE_PERIOD_US)
            gpioDelay(SAMPLE_PERIOD_US - elapsed);
    }

    /* --- Cleanup ----------------------------------------------------- */
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

