/*
 * Gate Controller for Raspberry Pi Zero W
 * Sensor : VL53L1X ToF (I2C bus 1, address 0x29)
 * Servo  : SG90 on GPIO18 (hardware PWM)
 * Log    : gate_log.txt
 *
 * Build  : gcc -O2 -Wall -o gate gate.c -lpigpio -lrt
 * Run    : sudo ./gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define SERVO_PIN            18          /* BCM 18 — hardware PWM capable */
#define DISTANCE_THRESHOLD   20          /* cm */
#define LOG_FILE             "gate_log.txt"
#define POLL_DELAY_US        100000      /* 100 ms */
#define RETRY_COUNT          3
#define RETRY_DELAY_US       100000      /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_MODE_START       0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0086
#define VL53L1X_REG_GPIO_HV_MUX_CTRL        0x0030
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0046
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG     0x0080
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT 0x0081
#define VL53L1X_REG_SYSTEM_THRESHOLD_HIGH   0x0084
#define VL53L1X_REG_SYSTEM_THRESHOLD_LOW    0x0085

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static int  vl53l1x_write16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read16(int handle, uint16_t reg, uint16_t *value);
static int  vl53l1x_read8(int handle, uint16_t reg, uint8_t *value);
static int  vl53l1x_init(int handle);
static int  vl53l1x_start_ranging(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance);
static void log_event(const char *event);
static void signal_handler(int sig);
static void cleanup(void);
static void servo_set_angle(int angle);
static void force_open(void);
static void force_close(void);
static void status_request(void);

/* ----------------------------- I2C helpers ------------------------------- */
static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *value)
{
    char reg_buf[2];
    char data[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;

    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_read8(int handle, uint16_t reg, uint8_t *value)
{
    char reg_buf[2];
    char data[1];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 1) != 1)
        return -1;

    *value = (uint8_t)data[0];
    return 0;
}

/* ----------------------------- VL53L1X driver ----------------------------- */
static int vl53l1x_init(int handle)
{
    uint8_t id = 0;
    int     retries = RETRY_COUNT;

    /* Verify sensor identity */
    if (vl53l1x_read8(handle, 0x010F, &id) < 0) {
        log_event("ERROR: Failed to read VL53L1X ID register");
        return -1;
    }
    if (id != 0x01) {
        log_event("ERROR: VL53L1X not detected (ID mismatch)");
        return -1;
    }

    /* Software reset */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        log_event("ERROR: Failed to write soft reset");
        return -1;
    }
    gpioDelay(2000); /* 2 ms */

    /* Clear any pending interrupt */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        log_event("ERROR: Failed to clear interrupt");
        return -1;
    }

    /* Configure GPIO high voltage (required for proper operation) */
    if (vl53l1x_write16(handle, VL53L1X_REG_GPIO_HV_MUX_CTRL, 0x01) < 0) {
        log_event("ERROR: Failed to configure GPIO HV mux");
        return -1;
    }

    /* Set inter-measurement period to 100 ms (0x0064 = 100 ms in ms units) */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT, 0x0064) < 0) {
        log_event("ERROR: Failed to set inter-measurement");
        return -1;
    }

    /* Set range timing budget to 50 ms (0x0032 = 50 ms in ms units) */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x0032) < 0) {
        log_event("ERROR: Failed to set range config");
        return -1;
    }

    /* Set interrupt config: new sample ready */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x04) < 0) {
        log_event("ERROR: Failed to set interrupt config");
        return -1;
    }

    /* Start ranging */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0) {
        log_event("ERROR: Failed to start ranging");
        return -1;
    }

    gpioDelay(10000); /* 10 ms for first measurement */

    return 0;
}

static int vl53l1x_start_ranging(int handle)
{
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0) {
        log_event("ERROR: Failed to start ranging");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t  status = 0;
    int      retries = RETRY_COUNT;

    /* Poll for data-ready interrupt */
    while (retries-- > 0) {
        if (vl53l1x_read8(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
            log_event("ERROR: Failed to read interrupt status");
            return -1;
        }
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (status == 0) {
        log_event("ERROR: No data ready after polling");
        return -1;
    }

    /* Read 16-bit distance */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, distance) < 0) {
        log_event("ERROR: Failed to read distance");
        return -1;
    }

    /* Clear interrupt to allow next measurement */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        log_event("ERROR: Failed to clear interrupt");
        return -1;
    }

    return 0;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_event(const char *event)
{
    if (!log_file)
        return;

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

/* ----------------------------- Servo -------------------------------------- */
static void servo_set_angle(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;

    /* SG90: 500–2500 us pulse width maps to 0–180 degrees */
    int pulse_width = 500 + (angle * 2000 / 180);
    gpioServo(SERVO_PIN, pulse_width);
}

/* ----------------------------- Remote control ----------------------------- */
static void force_open(void)
{
    log_event("FORCE_OPEN: Gate opening");
    servo_set_angle(90);
}

static void force_close(void)
{
    log_event("FORCE_CLOSE: Gate closing");
    servo_set_angle(0);
}

static void status_request(void)
{
    log_event("STATUS_REQUEST: Gate status requested");
}

/* ----------------------------- Signal / cleanup --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_event("INFO: Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0); /* Stop servo PWM */
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("ERROR: Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "ERROR: Failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, VL53L1X_ADDR);
        fclose(log_file);
        log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "ERROR: VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure servo pin */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioServo(SERVO_PIN, 0); /* Ensure servo is off */

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("INFO: Gate controller started");

    /* Main loop */
    while (running) {
        uint16_t distance = 0;

        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            if (distance < DISTANCE_THRESHOLD) {
                log_event("OBJECT_DETECTED: Object within 20 cm");
                force_open();
            } else {
                log_event("PATH_CLEAR: No object detected");
                force_close();
            }
        } else {
            log_event("ERROR: Distance read failed");
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * HC-SR04 Ultrasonic Distance Measurement — Raspberry Pi 4 Model B
 *
 * Wiring (BCM numbering):
 *   TRIG -> GPIO 23 (physical pin 16)
 *   ECHO -> GPIO 24 (physical pin 18)  [5 V tolerant; use level shifter if
 *                                     sensor output is 5 V]
 *
 * The HC-SR04 echo line is 5 V and the Pi tolerates 3.3 V.  A level shifter
 * or divider is required between the two signals.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN        23          /* BCM 23 — trigger output */
#define ECHO_PIN        24          /* BCM 24 — echo input   */

#define TRIG_PULSE_US   10          /* 10 µs trigger pulse   */
#define SAMPLE_PERIOD   200000      /* 200 ms between samples */
#define TIMEOUT_US      60000       /* 60 ms max echo wait   */
#define MIN_PULSE_US    100         /* reject noise / timeout */
#define MAX_PULSE_US    30000       /* reject no-object / too long */
#define LOG_FILE        "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_distance(float distance_cm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    printf("[%s] Distance: %.2f cm\n", ts, distance_cm);
    if (g_log_fp) {
        fprintf(g_log_fp, "%s,%.2f\n", ts, distance_cm);
        fflush(g_log_fp);
    }
}

static void log_warning(const char *msg)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(stderr, "[%s] WARNING: %s\n", ts, msg);
    if (g_log_fp) {
        fprintf(g_log_fp, "%s,WARNING,%s\n", ts, msg);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (rising/falling edge)                          */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_seen   = false;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_rising_tick  = tick;
        g_echo_seen    = false;
    } else if (level == 0) {
        g_falling_tick = tick;
        g_echo_seen    = true;
    }
    /* level == 2 (timeout) is ignored here; handled in main loop */
}

/* ------------------------------------------------------------------ */
/* Distance calculation with 32-bit tick wraparound                     */
/* ------------------------------------------------------------------ */

static float calculate_distance_cm(uint32_t pulse_us)
{
    /*
     * Speed of sound ≈ 343 m/s.  Distance = (pulse_us / 1e6) * 343 / 2.
     * pigpio ticks are microseconds; the formula is exact for 32-bit
     * unsigned arithmetic.
     */
    return (float)pulse_us * 343.0f / 2.0f / 1000000.0f;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Release the echo pin alert before terminating pigpio */
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure TRIG as output, ECHO as input ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN (BCM %d) as output.\n", TRIG_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN (BCM %d) as input.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN.\n");
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise TRIG_PIN LOW.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(50);  /* let line settle */

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback for ECHO ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG: BCM %d | ECHO: BCM %d | Sampling: %d ms | Log: %s\n",
           TRIG_PIN, ECHO_PIN, SAMPLE_PERIOD / 1000, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset per-sample state */
        g_rising_tick  = 0;
        g_falling_tick = 0;
        g_echo_seen    = false;

        /* Generate 10 µs trigger pulse */
        if (gpioWrite(TRIG_PIN, 1) != 0) {
            log_warning("Failed to set TRIG high");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }
        gpioDelay(TRIG_PULSE_US);
        if (gpioWrite(TRIG_PIN, 0) != 0) {
            log_warning("Failed to set TRIG low");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (!g_echo_seen && g_running) {
            if ((gpioTick() - wait_start) > TIMEOUT_US) {
                log_warning("Timeout: no echo received within 60 ms");
                gpioDelay(SAMPLE_PERIOD);
                break;
            }
            gpioDelay(100);  /* poll every 100 µs */
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            log_warning("Timeout: echo never arrived");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        /* Compute pulse width with 32-bit wraparound handling */
        uint32_t pulse_us = g_falling_tick - g_rising_tick;
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            log_warning("Out-of-range pulse width — noise or timeout");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        float distance = calculate_distance_cm(pulse_us);
        log_distance(distance);
        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

