/*
 * Smart Parking Gate — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   VL53L1X ToF sensor  -> I2C bus 1 (GPIO2/SDA, GPIO3/SCL)
 *   Servo PWM signal    -> GPIO18 (BCM)
 *   VL53L1X shutdown    -> GPIO23 (BCM)
 *   VL53L1X interrupt   -> GPIO24 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o parking_gate parking_gate.c -lpigpio -lrt
 * Run:
 *   sudo ./parking_gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define VL53L1X_SHUTDOWN_PIN 23
#define VL53L1X_INT_PIN      24

#define SERVO_PIN            18
#define SERVO_OPEN_US        1500   /*  90°  */
#define SERVO_CLOSE_US       1000   /*  0°   */

#define DISTANCE_THRESHOLD_OPEN  50   /* cm — open when object within this */
#define DISTANCE_THRESHOLD_CLOSE 60   /* cm — close when object exceeds this */

#define LOG_FILE             "parking_log.txt"
#define POLL_DELAY_US        50000   /* 50 ms between sensor polls */
#define DEBOUNCE_DELAY_US    50000   /* 50 ms after an interrupt */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_gpio(void);
static int  init_i2c(void);
static int  init_vl53l1x(void);
static int  read_distance(uint16_t *distance_mm);
static void control_servo(bool open);
static void log_event(bool open, uint16_t distance_mm);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- GPIO init --------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(VL53L1X_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set shutdown pin mode.\n");
        return -1;
    }
    if (gpioWrite(VL53L1X_SHUTDOWN_PIN, 0) < 0) {
        fprintf(stderr, "Error: cannot write shutdown pin.\n");
        return -1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set servo pin mode.\n");
        return -1;
    }
    if (gpioServo(SERVO_PIN, SERVO_CLOSE_US) < 0) {
        fprintf(stderr, "Error: cannot start servo PWM.\n");
        return -1;
    }

    if (gpioSetMode(VL53L1X_INT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set interrupt pin mode.\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- VL53L1X init ------------------------------ */
static int init_vl53l1x(void)
{
    /* Put the sensor into standby (active low) to allow configuration. */
    if (gpioWrite(VL53L1X_SHUTDOWN_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set shutdown low.\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms */

    /* Read model ID to confirm the sensor is present. */
    int model_id = i2cReadByteData(g_i2c_handle, 0x010F);
    if (model_id < 0) {
        fprintf(stderr, "Error: failed to read model ID (I2C error).\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    /* Minimal configuration: set I2C standard mode, no interrupts. */
    if (i2cWriteByteData(g_i2c_handle, 0x0001, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write register 0x0001.\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, 0x0002, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write register 0x0002.\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, 0x001D, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write register 0x001D.\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, 0x001E, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write register 0x001E.\n");
        return -1;
    }

    /* Clear any pending interrupt. */
    if (i2cWriteByteData(g_i2c_handle, 0x001F, 0x01) < 0) {
        fprintf(stderr, "Error: failed to write register 0x001F.\n");
        return -1;
    }

    /* Start ranging (bit 0 = VL53L1X_RANGING_START). */
    if (i2cWriteByteData(g_i2c_handle, 0x0018, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }

    /* Allow the first measurement to complete. */
    gpioDelay(50000);

    return 0;
}

/* ----------------------------- Read distance ----------------------------- */
static int read_distance(uint16_t *distance_mm)
{
    char buf[2];
    int  n = i2cReadI2CBlockData(g_i2c_handle, 0x0014, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d.\n", n);
        return -1;
    }
    *distance_mm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ----------------------------- Servo control ----------------------------- */
static void control_servo(bool open)
{
    int pulse_width = open ? SERVO_OPEN_US : SERVO_CLOSE_US;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Warning: gpioServo failed for pulse %d us.\n", pulse_width);
    }
}

/* ----------------------------- Log event --------------------------------- */
static void log_event(bool open, uint16_t distance_mm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (g_log_file) {
        fprintf(g_log_file, "%s - Gate %s - Distance: %u mm\n",
                timestamp, open ? "OPEN" : "CLOSED", distance_mm);
        fflush(g_log_file);
    }
    printf("%s - Gate %s - Distance: %u mm\n",
           timestamp, open ? "OPEN" : "CLOSED", distance_mm);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioServo(SERVO_PIN, 0);   /* stop PWM */
    gpioWrite(VL53L1X_SHUTDOWN_PIN, 0);
    gpioTerminate();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Parking Gate started. Press Ctrl+C to exit.\n");

    bool gate_open = false;

    while (g_running) {
        uint16_t distance_mm = 0;
        if (read_distance(&distance_mm) < 0) {
            fprintf(stderr, "Error: distance read failed — sensor may be absent or bus error.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int distance_cm = distance_mm / 10;

        if (distance_cm <= DISTANCE_THRESHOLD_OPEN && !gate_open) {
            control_servo(true);
            log_event(true, distance_mm);
            gate_open = true;
        } else if (distance_cm > DISTANCE_THRESHOLD_CLOSE && gate_open) {
            control_servo(false);
            log_event(false, distance_mm);
            gate_open = false;
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

