/*
 * Raspberry Pi 4 Model B – VL53L1X time-of-flight gate controller
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   VL53L1X SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   Gate open   -> GPIO 18 (active HIGH)
 *   Gate close  -> GPIO 19 (active HIGH)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gate gate.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define GATE_OPEN_PIN        18
#define GATE_CLOSE_PIN       19
#define DISTANCE_THRESHOLD_MM 200   /* 20 cm */
#define POLL_INTERVAL_US     500000 /* 500 ms */
#define LOG_FILE             "gate_events.log"

/* VL53L1X 16-bit register addresses (from ST UG-1037 / ST API) */
#define VL53L1X_REG_SOFT_RESET       0x0003
#define VL53L1X_REG_SYSTEM_MODE      0x0080
#define VL53L1X_REG_RANGE_START      0x0087
#define VL53L1X_REG_RESULT_INT_STA   0x0044
#define VL53L1X_REG_RESULT_RANGE_VAL 0x0096
#define VL53L1X_REG_RESULT_STATUS    0x0089
#define VL53L1X_REG_VHV_CONFIG       0x0030
#define VL53L1X_REG_PHASECAL         0x0041
#define VL53L1X_REG_RANGE_CONFIG     0x005E
#define VL53L1X_REG_INTERMEAS_MS     0x006B

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- VL53L1X helpers ----------------------------- */
/*
 * Write a 16-bit register on the VL53L1X.
 * pigpio's i2cWriteI2CBlockData() sends the register address followed by the
 * data payload, so we prepend the 16-bit address as two bytes.
 */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;
    if (i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2) < 0)
        return -1;
    return 0;
}

/*
 * Read a 16-bit register on the VL53L1X.
 * We send the 16-bit address, then read 2 bytes back.
 */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    char data[2];

    addr[0] = (char)(reg >> 8);
    addr[1] = (char)(reg & 0xFF);

    if (i2cWriteI2CBlockData(handle, addr[0], &addr[1], 1) < 0)
        return -1;

    if (i2cReadI2CBlockData(handle, addr[0], data, 2) != 2)
        return -1;

    *value = (uint8_t)data[0];
    return 0;
}

/*
 * Read a 16-bit register (big-endian) on the VL53L1X.
 */
static int vl53l1x_read_reg16_be(int handle, uint16_t reg, uint16_t *value)
{
    uint8_t lo, hi;
    if (vl53l1x_read_reg16(handle, reg, &lo) < 0)
        return -1;
    if (vl53l1x_read_reg16(handle, reg + 1, &hi) < 0)
        return -1;
    *value = ((uint16_t)hi << 8) | lo;
    return 0;
}

/*
 * Initialise the VL53L1X sensor.
 * Returns 0 on success, -1 on failure.
 */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    /* Verify the device is present by reading the model ID register. */
    if (vl53l1x_read_reg16(handle, 0x010F, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read VL53L1X model ID (sensor absent or bus error).\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    /* Soft reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Soft reset write failed.\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms settle */

    /* Clear any pending interrupt */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_RESULT_INT_STA, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to clear interrupt status.\n");
        return -1;
    }

    /* Set timing budget to 50 ms (0x006B = 50 ms in ms units) */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_INTERMEAS_MS, 50) < 0) {
        fprintf(stderr, "Error: Failed to set inter-measurement time.\n");
        return -1;
    }

    /* Set ranging frequency to 50 Hz (0x005E = 50 Hz) */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG, 50) < 0) {
        fprintf(stderr, "Error: Failed to set ranging frequency.\n");
        return -1;
    }

    /* Start ranging */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_RANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    return 0;
}

/*
 * Read a distance measurement in millimetres.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;

    /* Poll the data-ready bit in the status register (bit 0). */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_STATUS, &status) < 0) {
        fprintf(stderr, "Error: Failed to read result status.\n");
        return -1;
    }

    if ((status & 0x01) == 0) {
        /* Data not ready yet – not an error, just skip. */
        return 0;
    }

    /* Read the 16-bit range result. */
    if (vl53l1x_read_reg16_be(handle, VL53L1X_REG_RESULT_RANGE_VAL, distance_mm) < 0) {
        fprintf(stderr, "Error: Failed to read range value.\n");
        return -1;
    }

    /* Clear the interrupt so the next measurement can be flagged. */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_RESULT_INT_STA, 0x01) < 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt status after read.\n");
    }

    return 0;
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *event)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (g_log_file) {
        fprintf(g_log_file, "%s %s\n", ts, event);
        fflush(g_log_file);
    }
    printf("%s %s\n", ts, event);
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    gpioTerminate();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Register signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode. */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins. */
    if (gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);

    /* Open I2C bus 1 at address 0x29. */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise the VL53L1X sensor. */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started: VL53L1X gate controller running.");

    int gate_open = 0;

    while (g_running) {
        uint16_t distance_mm = 0;

        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) < 0) {
            log_event("Error: I2C read failure – sensor may be absent or bus error.");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (distance_mm > 0 && distance_mm < DISTANCE_THRESHOLD_MM) {
            if (!gate_open) {
                gpioWrite(GATE_OPEN_PIN, 1);
                gpioWrite(GATE_CLOSE_PIN, 0);
                log_event("Gate opened");
                gate_open = 1;
            }
        } else {
            if (gate_open) {
                gpioWrite(GATE_OPEN_PIN, 0);
                gpioWrite(GATE_CLOSE_PIN, 1);
                log_event("Gate closed");
                gate_open = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down.");
    cleanup();
    return EXIT_SUCCESS;
}

