code:
/*
 * Raspberry Pi 4 Model B — VL53L1X time-of-flight sensor → DC motor control
 *
 * Hardware:
 *   - VL53L1X on I2C bus 1, address 0x29 (SDA=GPIO2, SCL=GPIO3)
 *   - DC motor: forward  → GPIO17 (BCM)
 *               backward → GPIO18 (BCM)
 *   - Distance trigger → GPIO24 (BCM) — rising edge triggers a single
 *                        distance measurement and motor control.
 *
 * Behaviour:
 *   - On a rising edge of GPIO24 the VL53L1X is triggered to perform a
 *     single measurement.  The program polls the status register until
 *     the data-ready bit is set, then reads the 16-bit distance value.
 *   - If distance < 100 mm the motor runs forward; if distance > 300 mm
 *     the motor runs backward; otherwise the motor is stopped.
 *   - All state changes and distance measurements are logged to stdout.
 *   - SIGINT / SIGTERM triggers a clean shutdown: I2C handles are closed,
 *     the motor is stopped, and the VL53L1X API cleanup is called.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin / GPIO definitions (BCM numbering) ---- */
#define MOTOR_FORWARD_PIN  17
#define MOTOR_BACKWARD_PIN 18
#define TRIGGER_PIN        24

/* ---- VL53L1X constants ---- */
#define VL53L1X_ADDR        0x29
#define VL53L1X_REG_SOFT_RESET       0x0003
#define VL53L1X_REG_SYSTEM_START     0x0000
#define VL53L1X_REG_RESULT_STATUS    0x0089
#define VL53L1X_REG_RESULT_DISTANCE  0x0096
#define VL53L1X_REG_IDENTIFICATION   0x010F
#define VL53L1X_IDENT_VALUE          0xEACC

/* ---- Motor states ---- */
typedef enum {
    MOTOR_STOP,
    MOTOR_FORWARD,
    MOTOR_BACKWARD
} motor_state_t;

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a 16-bit register address followed by a single byte value.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    for (int attempt = 0; attempt < 3; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 3)
            return 0;
        fprintf(stderr, "I2C write to 0x%04X failed (attempt %d, rc=%d)\n",
                reg, attempt + 1, rc);
        if (attempt < 2)
            gpioDelay(1000 << attempt); /* 1 ms, 2 ms, 4 ms backoff */
    }
    return -1;
}

/*
 * Read a single byte from a 16-bit register address.
 * Returns 0 on success and stores the byte in *out; -1 on failure.
 */
static int i2c_read_byte(int handle, uint16_t reg, uint8_t *out)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    for (int attempt = 0; attempt < 3; attempt++) {
        int rc = i2cWriteDevice(handle, addr, 2);
        if (rc != 2) {
            fprintf(stderr, "I2C write (addr) to 0x%04X failed (attempt %d, rc=%d)\n",
                    reg, attempt + 1, rc);
            if (attempt < 2)
                gpioDelay(1000 << attempt);
            continue;
        }
        rc = i2cReadDevice(handle, (char *)out, 1);
        if (rc == 1)
            return 0;
        fprintf(stderr, "I2C read from 0x%04X failed (attempt %d, rc=%d)\n",
                reg, attempt + 1, rc);
        if (attempt < 2)
            gpioDelay(1000 << attempt);
    }
    return -1;
}

/*
 * Read a 16-bit little-endian value from a 16-bit register address.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int i2c_read_word(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    for (int attempt = 0; attempt < 3; attempt++) {
        int rc = i2cWriteDevice(handle, addr, 2);
        if (rc != 2) {
            fprintf(stderr, "I2C write (addr) to 0x%04X failed (attempt %d, rc=%d)\n",
                    reg, attempt + 1, rc);
            if (attempt < 2)
                gpioDelay(1000 << attempt);
            continue;
        }
        char data[2];
        rc = i2cReadDevice(handle, data, 2);
        if (rc == 2) {
            *out = (uint16_t)((uint8_t)data[0] | ((uint8_t)data[1] << 8));
            return 0;
        }
        fprintf(stderr, "I2C read from 0x%04X failed (attempt %d, rc=%d)\n",
                reg, attempt + 1, rc);
        if (attempt < 2)
            gpioDelay(1000 << attempt);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */

/*
 * Initialise the VL53L1X: soft-reset, verify identity, start
 * continuous ranging mode.
 * Returns 0 on success, -1 on failure.
 */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (i2c_write_byte(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "VL53L1X soft reset write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    /* Verify identity */
    uint16_t id = 0;
    if (i2c_read_word(handle, VL53L1X_REG_IDENTIFICATION, &id) != 0) {
        fprintf(stderr, "VL53L1X identification read failed\n");
        return -1;
    }
    if (id != VL53L1X_IDENT_VALUE) {
        fprintf(stderr, "VL53L1X identification mismatch: 0x%04X (expected 0x%04X)\n",
                id, VL53L1X_IDENT_VALUE);
        return -1;
    }

    /* Start continuous ranging mode */
    if (i2c_write_byte(handle, VL53L1X_REG_SYSTEM_START, 0x00) != 0) {
        fprintf(stderr, "VL53L1X start measurement write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    return 0;
}

/*
 * Trigger a single measurement and read the 16-bit distance.
 * Returns 0 on success and stores the distance in *distance_mm;
 * -1 on failure.
 */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    /* Trigger a single measurement */
    if (i2c_write_byte(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "VL53L1X trigger measurement failed\n");
        return -1;
    }

    /* Poll the status register until data-ready bit (bit 0) is set */
    uint16_t status = 0;
    for (int i = 0; i < 100; i++) {
        if (i2c_read_word(handle, VL53L1X_REG_RESULT_STATUS, &status) != 0) {
            fprintf(stderr, "VL53L1X status read failed\n");
            return -1;
        }
        if (status & 0x0001)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(status & 0x0001)) {
        fprintf(stderr, "VL53L1X data-ready timeout\n");
        return -1;
    }

    /* Read 16-bit distance */
    if (i2c_read_word(handle, VL53L1X_REG_RESULT_DISTANCE, distance_mm) != 0) {
        fprintf(stderr, "VL53L1X distance read failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Motor control                                                       */
/* ------------------------------------------------------------------ */
static void motor_set(motor_state_t state)
{
    switch (state) {
    case MOTOR_FORWARD:
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        printf("Motor: forward\n");
        break;
    case MOTOR_BACKWARD:
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 1);
        printf("Motor: backward\n");
        break;
    case MOTOR_STOP:
    default:
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        printf("Motor: stopped\n");
        break;
    }
}

/* ------------------------------------------------------------------ */
/* ISR — rising edge on trigger pin                                   */
/* ------------------------------------------------------------------ */
static void trigger_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;

    static uint16_t last_distance = 0;
    uint16_t distance = 0;
    motor_state_t motor_state = MOTOR_STOP;

    if (vl53l1x_read_distance(g_i2c_handle, &distance) != 0) {
        fprintf(stderr, "Distance read failed — stopping motor\n");
        motor_set(MOTOR_STOP);
        return;
    }

    printf("Distance: %u mm\n", distance);

    if (distance < 100) {
        motor_state = MOTOR_FORWARD;
    } else if (distance > 300) {
        motor_state = MOTOR_BACKWARD;
    } else {
        motor_state = MOTOR_STOP;
    }

    if (motor_state != MOTOR_STOP && last_distance == 0) {
        /* First valid reading — start the motor */
        motor_set(motor_state);
    } else if (motor_state != MOTOR_STOP && motor_state != last_distance) {
        /* State changed — log and apply */
        motor_set(motor_state);
    }

    last_distance = motor_state;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    motor_set(MOTOR_STOP);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs, initially off */
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    motor_set(MOTOR_STOP);

    /* Configure trigger pin as input with pull-down */
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_DOWN);

    /* Open I2C bus 1 at address 0x29 */
    g_i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed — sensor may be absent\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO%d\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X motor control running.  Trigger GPIO24 (rising edge).\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop — sleep until signal */
    while (g_running)
        gpioDelay(100000); /* 100 ms */

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

