/*
 * Proximity-based interactive art installation for Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - MPR121 capacitive touch sensor on /dev/i2c-1 (I2C bus 1, GPIO2=SDA, GPIO3=SCL)
 *   - 4-bit LED pattern on GPIO17, GPIO18, GPIO27, GPIO22 (BCM numbering)
 *
 * Behavior:
 *   Polls the MPR121 touch status register every 50 ms.  When any electrode
 *   detects proximity, drives the 4-bit LED pattern and logs the event to
 *   stdout with a timestamp.  Handles I2C bus errors, sensor-absent detection,
 *   and clean resource release on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS          "/dev/i2c-1"
#define MPR121_ADDR      0x5A

#define LED_BIT_0        17
#define LED_BIT_1        18
#define LED_BIT_2        27
#define LED_BIT_3        22

#define POLL_INTERVAL_MS 50

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG0     0x5E
#define MPR121_SOFTRESET      0x80

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line *g_led_lines[4] = { NULL, NULL, NULL, NULL };

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers -------------------------------- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ----------------------------- MPR121 init -------------------------------- */

static int mpr121_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(1000); /* allow reset to complete */

    /* Verify sensor is present by reading back the reset register */
    uint8_t reset_val = 0;
    if (i2c_read_reg8(fd, MPR121_SOFTRESET, &reset_val) < 0)
        return -1;
    if (reset_val != 0x63) {
        fprintf(stderr, "MPR121 soft-reset verification failed (got 0x%02X, expected 0x63)\n",
                reset_val);
        return -1;
    }

    /* Enable all 12 electrodes, baseline tracking, 16 µA charge current */
    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x0C) < 0)
        return -1;

    return 0;
}

/* ----------------------------- LED helpers -------------------------------- */

static void led_set_pattern(uint8_t pattern)
{
    for (int i = 0; i < 4; i++) {
        if (g_led_lines[i])
            gpiod_line_set_value(g_led_lines[i], (pattern >> i) & 1);
    }
}

/* ----------------------------- Logging ------------------------------------ */

static void log_event(uint8_t electrode)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
