static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line *g_led_lines[4] = { NULL, NULL, NULL, NULL };

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers -------------------------------- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ----------------------------- MPR121 init -------------------------------- */

static int mpr121_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(1000); /* allow reset to complete */

    /* Verify sensor is present by reading back the reset register */
    uint8_t reset_val = 0;
    if (i2c_read_reg8(fd, MPR121_SOFTRESET, &reset_val) < 0)
        return -1;
