#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG 0x5E
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_MHD_F 0x2F
#define MPR121_NHD_F 0x30
#define MPR121_NCL_F 0x31
#define MPR121_FDL_F 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) error: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) error: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, MPR121_SOFTRESET, &id) < 0) return -1;
    if (id != 0x5A) {
        fprintf(stderr, "MPR121 not found (ID: 0x%02X, expected 0x5A)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, MPR121_ECR, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_MHD_R, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHD_R, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCL_R, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDL_R, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_MHD_F, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHD_F, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCL_F, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDL_F, 0x02) < 0) return -1;
    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg8(fd, MPR121_E0TTH + i * 2, 0x0F) < 0) return -1;
        if (i2c_write_reg8(fd, MPR121_E0RTH + i * 2, 0x0A) < 0) return -1;
    }
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ECR, 0x8F) < 0) return -1;
    return 0;
}

static int mpr121_read_touch(int fd, uint16_t *touch_status) {
    uint8_t low, high;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &low) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &high) < 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_proximity_event(FILE *fp, uint16_t touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s - Proximity event detected (touch status: 0x%04X)\n", timestamp, touch_status);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, MPR121_ECR, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return 1;
    }
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);
    printf("Proximity detector running. Press Ctrl+C to exit.\n");
    while (running) {
        uint16_t touch_status;
        if (mpr121_read_touch(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            usleep(100000);
            continue;
        }
        if (touch_status != 0) {
            log_proximity_event(log_file, touch_status);
            gpioWrite(LED_GPIO, 1);
            usleep(1000000);
            gpioWrite(LED_GPIO, 0);
        }
        usleep(10000);
    }
    gpioWrite(LED_GPIO, 0);
    cleanup();
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

