#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define SPEED_OF_SOUND 343.0
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  400.0
#define TIMEOUT_US    30000
#define TRIGGER_PULSE_US 10
#define TRIGGER_SETTLE_US 5
#define LOOP_DELAY_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(TRIGGER_SETTLE_US);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_pulse_width(void) {
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    return (double)(end_tick - start_tick);
}

static double calculate_distance(double pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0;
}

static void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "gmtime() failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "gmtime() failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

int main(void) {
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();
        double pulse_width = measure_pulse_width();

        if (pulse_width < 0) {
            log_error("Timeout waiting for echo pulse");
        } else {
            double distance = calculate_distance(pulse_width);
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                log_error("Distance out of range");
            } else {
                log_distance(distance);
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

