/* Sanity bounds for the echo pulse width (µs).
 * ~58 µs -> ~1 cm   (speed of sound ~343 m/s)
 * ~25 ms -> ~4 m    (round trip)
 * We use 1 cm as the minimum accepted distance. */
#define MIN_PULSE_US     58
#define MAX_PULSE_US     25000

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t    g_pulse_start = 0;
static volatile uint32_t    g_pulse_end   = 0;
static volatile bool        g_echo_seen   = false;
static FILE                *g_log_fp      = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo ISR                                                             */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_pulse_start = tick;
        g_echo_seen   = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_pulse_end = tick;
        g_echo_seen = true;
    }
    /* level == 2 indicates a watchdog timeout — ignore */
}

/* ------------------------------------------------------------------ */
/* pigpio helpers                                                       */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN LOW.\n");
        return -1;
    }

    /* Allow the sensor to settle after power-up */
    gpioDelay(10000); /* 10 ms */

    return 0;
}

static int init_isr(void)
{
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n",
                ECHO_PIN);
        return -1;
    }
    return 0;
}

static void trigger_pulse(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to set TRIGGER_PIN HIGH.\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to set TRIGGER_PIN LOW.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Distance calculation                                                */
/* ------------------------------------------------------------------ */
static float pulse_width_us(uint32_t start, uint32_t end)
{
    /* Handle 32-bit tick wrap-around */
    uint32_t diff = end - start;          /* unsigned subtraction wraps */
    return (float)diff;
}

static bool validate_pulse(float pulse_us)
{
    if (pulse_us < MIN_PULSE_US) {
        fprintf(stderr, "Warning: echo pulse too short (%.1f µs, < %d µs).\n",
                pulse_us, MIN_PULSE_US);
        return false;
    }
    if (pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Warning: echo pulse too long (%.1f µs, > %d µs).\n",
                pulse_us, MAX_PULSE_US);
        return false;
    }
    return true;
}

static float pulse_to_meters(float pulse_us)
{
    /* speed of sound ~343 m/s => 1 µs = 1/343 ≈ 1.19e-6 m/µs
     * round-trip distance = (pulse_us / 2) * m/µs */
    return (pulse_us / 2.0f) * 1.19e-6f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int open_log(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static void log_reading(float distance_m)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Distance: %.2f m\n", timestamp, distance_m);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable ISR first so no callbacks fire during teardown */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;

    /* Install signal handlers for clean shutdown */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (init_isr() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (open_log() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, log=%s\n", TRIGGER_PIN, ECHO_PIN,
           LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        g_echo_seen = false;

        trigger_pulse();

        /* Wait for the echo pulse to complete or timeout */
        uint32_t waited = 0;
        const uint32_t timeout_us = 30000; /* 30 ms max wait */

        while (g_running && !g_echo_seen) {
            if (waited >= timeout_us) {
                fprintf(stderr, "Error: echo timeout — no object detected "
                                "or sensor absent.\n");
                break;
            }
            gpioDelay(1000); /* 1 ms */
            waited += 1000;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            continue; /* timeout, skip this sample */
        }

        uint32_t start = g_pulse_start;
        uint32_t end   = g_pulse_end;

        float pulse_us = pulse_width_us(start, end);
        if (!validate_pulse(pulse_us)) {
            continue;
        }

        float distance_m = pulse_to_meters(pulse_us);
        log_reading(distance_m);

        printf("Distance: %.2f m\n", distance_m);

        /* Sleep for the remainder of the 1 s period */
        uint32_t elapsed = 0;
        while (g_running && elapsed < SAMPLE_PERIOD_US) {
            uint32_t chunk = (SAMPLE_PERIOD_US - elapsed > 10000)
                             ? 10000 : (SAMPLE_PERIOD_US - elapsed);
            gpioDelay(chunk);
            elapsed += chunk;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

