/*
 * VL53L1X time-of-flight distance reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1 SDA)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1 SCL)
 *   VL53L1X XSHUT-> GPIO27 (BCM) - active-high to enable the sensor
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_reader vl53l1x_reader.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- VL53L1X constants (per datasheet) ---- */
#define VL53L1X_ADDR        0x29          /* 7-bit I2C address */
#define I2C_BUS             1             /* /dev/i2c-1 on RPi 4 */
#define GPIO_XSHUT          27            /* BCM pin for XSHUT */
#define POLL_DELAY_US       100000        /* 100 ms between readings */
#define MAX_DISTANCE_MM     4000          /* sensor's max range */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET      0x0003
#define REG_VHV_CONFIG      0x0008
#define REG_PHASE_CAL       0x0009
#define REG_RANGE_START     0x0000
#define REG_RESULT_INT_ST   0x0044
#define REG_RESULT_RANGE    0x0062
#define REG_RESULT_STATUS   0x0089

/* Range-start control bits */
#define RANGE_START_MODE_SINGLE 0x01
#define RANGE_START_CLEAR       0x01

/* Status register bits */
#define STATUS_RANGE_VALID      0x01
#define STATUS_NEW_SAMPLE       0x01

/* Soft-reset value */
#define SOFT_RESET_VALUE        0x00

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address + 1 byte value.                     */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        syslog(LOG_ERR, "i2cWriteDevice failed for reg 0x%04X: %s",
               reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes starting at the given 16-bit register address.     */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        syslog(LOG_ERR, "i2cWriteDevice (addr) failed for reg 0x%04X: %s",
               reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        syslog(LOG_ERR, "i2cReadDevice failed for reg 0x%04X: %s",
               reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L1X: power on, soft-reset, configure registers.  */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* 1. Soft reset */
    if (vl53l1x_write_reg(handle, REG_SOFT_RESET, SOFT_RESET_VALUE) != 0)
        return -1;
    gpioDelay(2000);  /* 2 ms settle after reset */

    /* 2. Clear any pending interrupt */
    uint8_t int_st = 0;
    if (vl53l1x_read_reg(handle, REG_RESULT_INT_ST, &int_st, 1) != 0)
        return -1;

    /* 3. Configure VHV and phase calibration (example defaults) */
    if (vl53l1x_write_reg(handle, REG_VHV_CONFIG, 0x01) != 0)
        return -1;
    if (vl53l1x_write_reg(handle, REG_PHASE_CAL, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single measurement and read the distance.                */
/* Returns distance in mm on success, -1 on error.                    */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle)
{
    uint8_t status = 0;
    uint8_t range_buf[2];
    int distance = -1;

    /* 1. Start a single measurement */
    if (vl53l1x_write_reg(handle, REG_RANGE_START, RANGE_START_MODE_SINGLE) != 0)
        return -1;

    /* 2. Poll for data-ready (new-sample bit) */
    for (int i = 0; i < 100; i++) {
        if (vl53l1x_read_reg(handle, REG_RESULT_INT_ST, &status, 1) != 0)
            return -1;
        if (status & STATUS_NEW_SAMPLE)
            break;
        gpioDelay(2000);  /* 2 ms */
    }
    if (!(status & STATUS_NEW_SAMPLE)) {
        syslog(LOG_ERR, "VL53L1X measurement timeout");
        return -1;
    }

    /* 3. Read 2-byte distance result */
    if (vl53l1x_read_reg(handle, REG_RESULT_RANGE, range_buf, 2) != 0)
        return -1;

    distance = ((int)range_buf[0] << 8) | (int)range_buf[1];

    /* 4. Clear the interrupt so the next measurement can signal */
    if (vl53l1x_write_reg(handle, REG_RESULT_INT_ST, RANGE_START_CLEAR) != 0)
        syslog(LOG_WARNING, "Failed to clear interrupt status");

    return distance;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Configure XSHUT pin as output and drive high ---- */
    if (gpioSetMode(GPIO_XSHUT, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed for GPIO%d", GPIO_XSHUT);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_XSHUT, 1);  /* active-high: sensor enabled */
    gpioDelay(2000);           /* 2 ms settle */

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed on bus %d addr 0x%02X: %s",
               I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X reader started (I2C bus %d, addr 0x%02X)",
           I2C_BUS, VL53L1X_ADDR);

    /* ---- Main loop ---- */
    while (g_running) {
        int distance = vl53l1x_read_distance(g_i2c_handle);

        if (distance >= 0) {
            if (distance > MAX_DISTANCE_MM) {
                syslog(LOG_WARNING, "Distance out of range: %d mm", distance);
            } else {
                syslog(LOG_INFO, "Distance: %d mm", distance);
            }
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    syslog(LOG_INFO, "Shutting down");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioWrite(GPIO_XSHUT, 0);  /* power down */
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

