    /* ---- Main loop ---- */
    while (g_running) {
        int distance = vl53l1x_read_distance(g_i2c_handle);

        if (distance >= 0) {
            if (distance > MAX_DISTANCE_MM) {
                syslog(LOG_WARNING, "Distance out of range: %d mm", distance);
            } else {
                syslog(LOG_INFO, "Distance: %d mm", distance);
            }
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    syslog(LOG_INFO, "Shutting down");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioWrite(GPIO_XSHUT, 0);  /* power down */
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

