#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define SERVO_MIN_PULSEWIDTH 500
#define SERVO_MAX_PULSEWIDTH 2500
#define SERVO_CENTER_ANGLE 90
#define MOVING_AVG_SIZE 5
#define ECHO_TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_width = 0;
static volatile bool new_pulse = false;
static volatile uint32_t last_tick = 0;
static volatile bool echo_state = false;

static double distance_history[MOVING_AVG_SIZE];
static int history_index = 0;
static int history_count = 0;

static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        last_tick = tick;
        echo_state = true;
    } else if (level == 0 && echo_state) {
        uint32_t diff = tick - last_tick;
        pulse_width = diff;
        new_pulse = true;
        echo_state = false;
    }
}

static double moving_average(double new_value) {
    distance_history[history_index] = new_value;
    history_index = (history_index + 1) % MOVING_AVG_SIZE;
    if (history_count < MOVING_AVG_SIZE) {
        history_count++;
    }
    double sum = 0.0;
    for (int i = 0; i < history_count; i++) {
        sum += distance_history[i];
    }
    return sum / history_count;
}

static double calculate_distance(uint32_t pulse_width_us) {
    if (pulse_width_us == 0) {
        return -1.0;
    }
    double distance = (double)pulse_width_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;
    }
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle %d\n", angle);
        return -1;
    }
    int pulsewidth = SERVO_MIN_PULSEWIDTH + (angle * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH) / 180);
    if (gpioServo(SERVO_PIN, pulsewidth) < 0) {
        fprintf(stderr, "Error: Failed to set servo pulsewidth\n");
        return -1;
    }
    return 0;
}

static int log_data(double distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set echo callback\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Distance_cm,ServoAngle_deg\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set signal handler\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (set_servo_angle(SERVO_CENTER_ANGLE) < 0) {
        fprintf(stderr, "Error: Failed to set initial servo angle\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_tick = gpioTick();
        bool timed_out = false;
        while (!new_pulse && running) {
            if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
                timed_out = true;
                break;
            }
            gpioDelay(100);
        }

        uint32_t pulse_width_us = 0;
        bool got_pulse = false;
        if (new_pulse) {
            pulse_width_us = pulse_width;
            got_pulse = true;
        } else if (timed_out) {
            fprintf(stderr, "Warning: Echo timeout\n");
        }

        double distance = -1.0;
        if (got_pulse) {
            distance = calculate_distance(pulse_width_us);
            if (distance < 0) {
                fprintf(stderr, "Warning: Invalid distance reading\n");
            }
        }

        double filtered_distance = moving_average(distance);

        if (set_servo_angle((int)filtered_distance) < 0) {
            fprintf(stderr, "Error: Failed to set servo angle\n");
        }

        if (log_data(filtered_distance, (int)filtered_distance) < 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        new_pulse = false;
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

