/*
 * VL53L1X distance monitor with LED warning on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   LED anode -> GPIO17 (BCM) via 330 Ω resistor -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_monitor vl53l1x_monitor.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29          /* 7-bit address, shifted left by 1 */
#define LED_GPIO             17
#define DISTANCE_THRESHOLD   200           /* mm */
#define BUFFER_SIZE          10
#define POLL_DELAY_US        50000         /* 50 ms */
#define INIT_TIMEOUT_MS      100           /* max wait for sensor to respond */

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET       0x0003
#define REG_VHV_CONFIG       0x0008
#define REG_PHASE_CAL        0x0009
#define REG_RANGE_CONFIG     0x005E
#define REG_INTERMEAS_MS     0x006B
#define REG_SYSTEM_MODE      0x0080
#define REG_RESULT_INT_STA   0x0044
#define REG_RESULT_RANGE     0x0096

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Circular buffer ---- */
typedef struct {
    int  data[BUFFER_SIZE];
    int  head;
    int  count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void cb_push(CircularBuffer *cb, int value) {
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t value) {
    char buf[3] = { (char)reg_hi, (char)reg_lo, (char)value };
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int i2c_read_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t *buf, uint32_t len) {
    char addr[2] = { (char)reg_hi, (char)reg_lo };
    if (i2cWriteDevice(i2c_handle, addr, 2) < 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

/* ---- VL53L1X driver ---- */
static int vl53l1x_write8(uint8_t reg_hi, uint8_t reg_lo, uint8_t value) {
    return i2c_write_reg16(reg_hi, reg_lo, value);
}

static int vl53l1x_read8(uint8_t reg_hi, uint8_t reg_lo, uint8_t *buf, uint32_t len) {
    return i2c_read_reg16(reg_hi, reg_lo, buf, len);
}

static int vl53l1x_init(void) {
    uint8_t buf[1];

    /* 1. Soft reset */
    if (vl53l1x_write8(0x00, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(2000);                       /* 2 ms settle */
    if (vl53l1x_write8(0x00, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(2000);

    /* 2. Verify device identity (optional, but good practice) */
    if (vl53l1x_read8(0x00, 0x010F, buf, 1) < 0) return -1;
    if (buf[0] != 0x01) {
        fprintf(stderr, "Warning: unexpected device ID 0x%02X (expected 0x01)\n", buf[0]);
    }

    /* 3. Set VHV configuration */
    if (vl53l1x_write8(0x00, REG_VHV_CONFIG, 0x01) < 0) return -1;

    /* 4. Set phase calibration */
    if (vl53l1x_write8(0x00, REG_PHASE_CAL, 0x40) < 0) return -1;

    /* 5. Set range timing budget ~50 ms (0x006B = 0x006B) */
    if (vl53l1x_write8(0x00, REG_INTERMEAS_MS, 0x00) < 0) return -1;
    if (vl53l1x_write8(0x00, REG_RANGE_CONFIG, 0x00) < 0) return -1;

    /* 6. Start ranging (bit 0 = 0x01) */
    if (vl53l1x_write8(0x00, REG_SYSTEM_MODE, 0x01) < 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(int *distance_mm) {
    uint8_t buf[2];
    uint8_t status;

    /* Poll data-ready bit (bit 0 of RESULT_INT_STA) */
    if (vl53l1x_read8(0x00, REG_RESULT_INT_STA, &status, 1) < 0) return -1;
    if ((status & 0x01) == 0) return 1;     /* not ready yet */

    /* Read 16-bit range result (big-endian) */
    if (vl53l1x_read8(0x00, REG_RESULT_RANGE, buf, 2) < 0) return -1;

    *distance_mm = (buf[0] << 8) | buf[1];

    /* Clear interrupt by writing 0x01 to RESULT_INT_STA */
    if (vl53l1x_write8(0x00, REG_RESULT_INT_STA, 0x01) < 0) return -1;

    return 0;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ---- Main ---- */
int main(void) {
    CircularBuffer distance_buffer;
    int distance;
    int rc;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Initialize circular buffer */
    cb_init(&distance_buffer);

    /* Register signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        rc = vl53l1x_read_distance(&distance);
        if (rc == 0) {
            cb_push(&distance_buffer, distance);
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Warning: I2C read error\n");
        }
        /* rc == 1: data not ready, just wait */

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

