    if (fd < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction: %s\n", GPIO_PIN, strerror(errno));
        return -1;
    }
    if (write(fd, "in", 2) != 2) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PIN, strerror(errno));
