#include <linux/i2c-dev.h>
#include <pthread.h>
#include <getopt.h>

#define DEFAULT_I2C_ADDRESS 0x48
#define DEFAULT_THRESHOLD 1000
#define LOG_FILE "proximity.log"
#define GPIO_PIN 27
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", i2c_address, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            fprintf(stderr, "Failed to export GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            return -1;
        }
    } else {
        char buf[16];
        snprintf(buf, sizeof(buf), "%d", GPIO_PIN);
        if (write(fd, buf, strlen(buf)) < 0 && errno != EBUSY) {
            fprintf(stderr, "Failed to export GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            close(fd);
            return -1;
        }
        close(fd);
    }
    usleep(100000);
    fd = open("/sys/class/gpio/gpio27/direction", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction: %s\n", GPIO_PIN, strerror(errno));
        return -1;
    }
    if (write(fd, "in", 2) != 2) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PIN, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

