/*
 * Raspberry Pi Zero W – HC-SR04 Ultrasonic Distance Sensor + PWM Speaker Theremin
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5V  (Pin 2 or 4)
 *   HC-SR04 GND  -> GND (Pin 6)
 *   HC-SR04 TRIG -> GPIO23 (BCM) – 10 µs pulse
 *   HC-SR04 ECHO -> GPIO24 (BCM) – echo input
 *   Speaker      -> GPIO18 (BCM) – PWM0 (Pin 12)
 *
 * Build: gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin / timing constants ---- */
#define TRIGGER_PIN      23          /* BCM GPIO23 – HC-SR04 trigger */
#define ECHO_PIN         24          /* BCM GPIO24 – HC-SR04 echo    */
#define PWM_PIN          18          /* BCM GPIO18 – PWM0 (speaker) */
#define TRIGGER_PULSE_US 10          /* HC-SR04 trigger pulse width */
#define ECHO_TIMEOUT_US  200000      /* 200 ms echo timeout          */
#define LOOP_DELAY_US    10000       /* 10 ms main-loop delay        */
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f
#define PWM_DUTY_50      500000      /* 50 % of 1,000,000 range     */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_initialized = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- HC-SR04 distance measurement ---- */
/*
 * Returns distance in cm, or -1.0f on timeout / error.
 * Uses gpioSetAlertFuncEx for edge timing so the echo pulse is measured
 * accurately even on a busy system.
 */
static float read_distance_cm(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);  /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    uint32_t start_tick = 0, end_tick = 0;
    bool got_rising = false;

    /* Wait for rising edge (echo starts) */
    for (uint32_t t = 0; t < ECHO_TIMEOUT_US; t += 10) {
        if (gpioRead(ECHO_PIN) == 1) {
            start_tick = gpioTick();
            got_rising = true;
            break;
        }
        gpioDelay(10);
    }
    if (!got_rising) {
        fprintf(stderr, "Error: HC-SR04 echo rising edge timeout\n");
        return -1.0f;
    }

    /* Wait for falling edge (echo ends) */
    for (uint32_t t = 0; t < ECHO_TIMEOUT_US; t += 10) {
        if (gpioRead(ECHO_PIN) == 0) {
            end_tick = gpioTick();
            break;
        }
        gpioDelay(10);
    }
    if (end_tick == 0) {
        fprintf(stderr, "Error: HC-SR04 echo falling edge timeout\n");
        return -1.0f;
    }

    uint32_t diff = end_tick - start_tick;  /* handles 32-bit wrap */
    float distance = (float)diff / 58.0f;   /* cm per µs at 343 m/s */

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/* ---- Frequency mapping ---- */
static float map_distance_to_frequency(float distance_cm)
{
    if (distance_cm < 0.0f) return 0.0f;
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;

    float norm = (distance_cm - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return MIN_FREQUENCY_HZ * (1.0f - norm * (1.0f - MAX_FREQUENCY_HZ / MIN_FREQUENCY_HZ));
}

/* ---- PWM control ---- */
static int set_pwm_frequency(float frequency_hz)
{
    if (frequency_hz <= 0.0f) {
        if (gpioPWM(PWM_PIN, 0) < 0) {
            fprintf(stderr, "Error: gpioPWM(0) failed\n");
            return -1;
        }
        return 0;
    }

    int actual = gpioSetPWMfrequency(PWM_PIN, (int)frequency_hz);
    if (actual < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", (int)frequency_hz);
        return -1;
    }

    if (gpioPWM(PWM_PIN, PWM_DUTY_50) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d) failed\n", PWM_DUTY_50);
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_pigpio_initialized) {
        gpioPWM(PWM_PIN, 0);
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_initialized = 1;

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    float current_frequency = 0.0f;
    int   consecutive_errors = 0;

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance_cm();

        if (distance < 0.0f) {
            consecutive_errors++;
            fprintf(stderr, "Error: read_distance_cm failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors > 10) {
                fprintf(stderr, "Fatal: too many consecutive errors, aborting.\n");
                break;
            }
            /* Preserve previous frequency on sensor failure */
            set_pwm_frequency(current_frequency);
        } else {
            consecutive_errors = 0;
            float freq = map_distance_to_frequency(distance);
            if (set_pwm_frequency(freq) == 0) {
                current_frequency = freq;
            }
            printf("Distance: %.2f cm  ->  Frequency: %.2f Hz\n",
                   distance, current_frequency);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

