            consecutive_errors++;
            fprintf(stderr, "Error: read_distance_cm failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors > 10) {
                fprintf(stderr, "Fatal: too many consecutive errors, aborting.\n");
