            }
            /* Preserve previous frequency on sensor failure */
            set_pwm_frequency(current_frequency);
        } else {
            consecutive_errors = 0;
            float freq = map_distance_to_frequency(distance);
            if (set_pwm_frequency(freq) == 0) {
                current_frequency = freq;
