/*
 * Theremin-style instrument using an HC-SR04 ultrasonic sensor and a piezo buzzer.
 *
 * Hardware (Raspberry Pi 3 Model B+):
 *   - HC-SR04 trigger  -> GPIO23 (BCM)
 *   - HC-SR04 echo     -> GPIO24 (BCM) with pull-down
 *   - Piezo buzzer     -> PWM0  -> GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN  23
#define ECHO_PIN     24
#define BUZZER_PIN   18

/* ---- Physical constants ---- */
#define SPEED_OF_SOUND_CM_PER_US  0.0343   /* cm/µs at 20 °C */
#define MIN_DISTANCE_CM           5.0
#define MAX_DISTANCE_CM           50.0
#define MIN_FREQUENCY_HZ          200.0
#define MAX_FREQUENCY_HZ          2000.0
#define ECHO_TIMEOUT_US           100000   /* 100 ms */
#define LOOP_DELAY_US             10000    /* 10 ms  */
#define TRIGGER_PULSE_US          10
#define TRIGGER_SETTLE_US         2

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_initialized = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure all GPIO pins                       */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    g_pigpio_initialized = 1;

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set trigger pin %d as output.\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set echo pin %d as input.\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set buzzer pin %d as output.\n", BUZZER_PIN);
        return -1;
    }

    /* Pull-down on echo so the line idles low when sensor is absent */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on echo pin %d.\n", ECHO_PIN);
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: cannot initialise trigger pin %d low.\n", TRIGGER_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Measure distance using the HC-SR04                                   */
/* Returns distance in cm, or -1.0 on timeout/error                     */
/* ------------------------------------------------------------------ */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* --- Trigger: 10 µs low pulse --- */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low.\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_SETTLE_US);

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high.\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to reset trigger low.\n");
        return -1.0f;
    }

    /* --- Wait for echo rising edge --- */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo pulse start timeout (sensor absent or wiring fault).\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* --- Wait for echo falling edge --- */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo pulse end timeout.\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance_cm = (pulse_us * SPEED_OF_SOUND_CM_PER_US) / 2.0f;

    /* Sanity-check range */
    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f].\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance_cm;
}

/* ------------------------------------------------------------------ */
/* Map distance to frequency (linear clamped)                          */
/* ------------------------------------------------------------------ */
static float map_distance_to_frequency(float distance_cm)
{
    if (distance_cm < 0.0f) return 0.0f;

    float freq = (distance_cm - MIN_DISTANCE_CM) *
                 (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM) +
                 MIN_FREQUENCY_HZ;

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;
    return freq;
}

/* ------------------------------------------------------------------ */
/* Generate a tone on the buzzer at the given frequency (Hz)           */
/* ------------------------------------------------------------------ */
static void generate_tone(float frequency_hz)
{
    if (frequency_hz <= 0.0f) {
        gpioPWM(BUZZER_PIN, 0);
        return;
    }

    /*
     * gpioPWM on a hardware-PWM-capable pin (GPIO18) generates a
     * hardware-generated square wave at the given frequency.
     * pigpio's hardware PWM resolution is 1,000,000 steps (0–1,000,000).
     */
    unsigned frequency_steps = (unsigned)(frequency_hz * 1000.0f);
    if (frequency_steps > 1000000) frequency_steps = 1000000;

    if (gpioSetPWMfrequency(BUZZER_PIN, frequency_steps) < 0) {
        fprintf(stderr, "Warning: failed to set PWM frequency on pin %d.\n", BUZZER_PIN);
        return;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {   /* 50 % duty cycle */
        fprintf(stderr, "Warning: failed to start PWM on pin %d.\n", BUZZER_PIN);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_initialized) {
        gpioPWM(BUZZER_PIN, 0);   /* silence buzzer */
        gpioWrite(TRIGGER_PIN, 0);
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Theremin ready.\n");
    printf("  Trigger: GPIO%d | Echo: GPIO%d | Buzzer: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("  Distance range: %.0f–%.0f cm | Frequency range: %.0f–%.0f Hz\n",
           MIN_DISTANCE_CM, MAX_DISTANCE_CM, MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
    printf("Press Ctrl+C to exit.\n\n");

    float last_valid_distance = -1.0f;

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read failed; reusing last valid distance.\n");
            if (last_valid_distance < 0.0f) {
                fprintf(stderr, "No valid reading yet; skipping iteration.\n");
                gpioDelay(LOOP_DELAY_US);
                continue;
            }
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        float frequency = map_distance_to_frequency(distance);
        generate_tone(frequency);

        printf("Distance: %6.2f cm  |  Frequency: %6.2f Hz\n",
               distance, frequency);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

