/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W
 * Trigger: GPIO17 (BCM), Echo: GPIO18 (BCM)
 * Build:  gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define SPEED_OF_SOUND   34300.0          /* cm/s at ~20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define THRESHOLD_CM     10.0
#define LOOP_DELAY_US    500000           /* 500 ms */
#define ECHO_TIMEOUT_US  50000            /* 50 ms */
#define TRIGGER_PULSE_US 10
#define TRIGGER_SETTLE_US 5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Measure the echo pulse duration in microseconds.
 * Returns:
 *   > 0  : pulse duration in microseconds
 *   -1   : timeout (no echo received)
 *   -2   : pigpio read error
 */
static int measure_echo_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo to go HIGH (rising edge) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1;                 /* timeout */
    }
    start_tick = gpioTick();

    /* Wait for echo to go LOW (falling edge) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1;                 /* timeout */
    }
    end_tick = gpioTick();

    return (int)(end_tick - start_tick);
}

static double calculate_distance_cm(int pulse_us)
{
    /* distance = (pulse_us / 1e6) * speed / 2 */
    return ((double)pulse_us / 1.0e6) * SPEED_OF_SOUND / 2.0;
}

int main(void)
{
    int rc;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(TRIGGER_SETTLE_US);

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Loop: %d ms\n",
           TRIGGER_PIN, ECHO_PIN, LOOP_DELAY_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main measurement loop --- */
    while (g_running) {
        /* 10 µs trigger pulse */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        int pulse_us = measure_echo_us();

        if (pulse_us < 0) {
            if (pulse_us == -1)
                printf("Invalid reading (timeout)\n");
            else
                printf("Invalid reading (read error)\n");
        } else {
            double distance = calculate_distance_cm(pulse_us);

            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                printf("Invalid reading (out of range: %.2f cm)\n", distance);
            } else {
                printf("Distance: %.2f cm", distance);
                if (distance < THRESHOLD_CM)
                    printf("  [Too close!]");
                printf("\n");
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

