/*
 * Raspberry Pi 4 Model B - TDK InvenSense ICU-20201 Ultrasonic ToF Sensor
 * SPI Read Program (Mode 0, 1 MHz, CS on GPIO8)
 *
 * Reads distance continuously, logs timestamp + distance to CSV.
 * Handles SPI errors, sensor absent conditions, and graceful shutdown.
 *
 * Build: gcc -O2 -Wall -o icu20201_spi icu20201_spi.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define CS_GPIO_LINE    8          /* BCM GPIO8 = SPI CE0 */
#define CSV_FILENAME    "distance_log.csv"
#define READ_DELAY_MS   100
#define MAX_DISTANCE_MM 5000
#define MIN_DISTANCE_MM 200

/* ICU-20201 SPI command set (example placeholders) */
#define CMD_READ_DISTANCE 0x01
#define CMD_INIT          0x80
#define CMD_RESET         0x7F

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_log_fp = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_cs_line = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
static int spi_xfer(const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)(uintptr_t)tx;
    tr.rx_buf        = (unsigned long)(uintptr_t)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI mode set failed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI bits set failed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI speed set failed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    /* Open GPIO8 (BCM) for manual CS control */
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        fprintf(stderr, "gpiochip4 open failed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }
    g_cs_line = gpiod_chip_get_line(g_chip, CS_GPIO_LINE);
    if (!g_cs_line) {
        fprintf(stderr, "CS GPIO line %d get failed: %s\n",
                CS_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL;
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }
    if (gpiod_line_request_output(g_cs_line, "icu20201_spi", 1) < 0) {
        fprintf(stderr, "CS line request failed: %s\n", strerror(errno));
        g_cs_line = NULL;
        gpiod_chip_close(g_chip); g_chip = NULL;
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    uint8_t tx[2] = { CMD_INIT, 0x00 };
    uint8_t rx[2] = { 0 };
    if (spi_xfer(tx, rx, sizeof(tx)) < 0) {
        fprintf(stderr, "Sensor init command failed\n");
        return -1;
    }
    usleep(10000);  /* 10 ms settle */

    tx[0] = CMD_RESET; tx[1] = 0x00;
    if (spi_xfer(tx, rx, sizeof(tx)) < 0) {
        fprintf(stderr, "Sensor reset command failed\n");
        return -1;
    }
    usleep(10000);

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_distance(uint16_t *distance_mm)
{
    uint8_t tx[2] = { CMD_READ_DISTANCE, 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_xfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    if (raw < MIN_DISTANCE_MM || raw > MAX_DISTANCE_MM) {
        fprintf(stderr, "Distance out of range: %u mm\n", raw);
        return -1;
    }
    *distance_mm = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_data(uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(g_log_fp, "%s,%u\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_spi() < 0)
        return EXIT_FAILURE;

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed - continuing indefinitely\n");
    }

    g_log_fp = fopen(CSV_FILENAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "Timestamp,Distance_mm\n");
    fflush(g_log_fp);

    printf("ICU-20201 SPI reader started. Logging to %s. Ctrl+C to stop.\n",
           CSV_FILENAME);

    while (g_running) {
        uint16_t dist = 0;
        if (read_distance(&dist) == 0) {
            if (log_data(dist) < 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            fprintf(stderr, "Read failed - continuing\n");
        }
        usleep(READ_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

