/*
 * Si1175 ALS logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si1175 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   Si1175 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   Si1175 VDD  -> 3.3 V
 *   Si1175 GND  -> GND
 *
 * Default I2C address: 0x49 (ADDR pin tied to GND).
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1175_logger si1175_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1175_ADDR    0x49

/* Si1175 register addresses (from datasheet) */
#define REG_PART_ID     0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_COMMAND    0x30
#define REG_RESPONSE   0x20
#define REG_HW_KEY     0x07

/* Command register opcodes */
#define CMD_RESET      0x01
#define CMD_ALS_FORCE  0x06

/* Expected PART_ID for Si1175 */
#define SI1175_PART_ID 0x75

#define LOG_FILE       "proximity_log.csv"
#define SAMPLE_PERIOD  5   /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
