{
    uint8_t lo, hi;
    if (i2c_read_reg(fd, reg, &lo) < 0)
        return -1;
    if (i2c_read_reg(fd, reg + 1, &hi) < 0)
        return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

