    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (write(fd, buf, sizeof(buf)) == (ssize_t)sizeof(buf))
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1120 register.  Returns 0 on success, -1 err. */
static int si1120_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, out, 1) == 1)
                return 0;
        }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int si1120_init(int fd)
{
    uint8_t part_id = 0;

    /* Reset the device */
    if (si1120_write_reg(fd, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        return -1;
    }
    usleep(10000);  /* allow reset to complete */

    /* Verify part ID */
    if (si1120_read_reg(fd, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read Si1120 part ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected Si1120 part ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID);
        return -1;
    }

    /* Write HW_KEY to enable proper operation */
    if (si1120_write_reg(fd, SI1120_REG_HW_KEY, SI1120_HW_KEY_VAL) != 0) {
        fprintf(stderr, "Failed to write Si1120 HW_KEY\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int si1120_read_als_vis(int fd, uint16_t *als)
{
    uint8_t lsb = 0, msb = 0;
    if (si1120_read_reg(fd, SI1120_REG_ALS_VIS_LSB, &lsb) != 0)
        return -1;
    if (si1120_read_reg(fd, SI1120_REG_ALS_VIS_MSB, &msb) != 0)
        return -1;
    *als = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int si1120_read_ps1(int fd, uint16_t *ps)
{
    uint8_t lsb = 0, msb = 0;
    if (si1120_read_reg(fd, SI1120_REG_PS1_LSB, &lsb) != 0)
        return -1;
    if (si1120_read_reg(fd, SI1120_REG_PS1_MSB, &msb) != 0)
        return -1;
    *ps = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
    else
        snprintf(buf, len, "1970-01-01 00:00:00");
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *f, uint16_t als, uint16_t ps)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(f, "%s, ALS_VIS=%u, PS1=%u\n", ts, als, ps);
    fflush(f);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire Si1120 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1120_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI1120_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1120_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1120 logger started.  Sampling every %d ms.  Press Ctrl-C to stop.\n",
           SAMPLE_MS);

    /* Main sampling loop */
    while (g_running) {
        uint16_t als = 0, ps = 0;
        int als_ok = si1120_read_als_vis(g_i2c_fd, &als);
        int ps_ok  = si1120_read_ps1(g_i2c_fd, &ps);

        if (als_ok == 0 && ps_ok == 0) {
            log_data(g_log, als, ps);
        } else {
            fprintf(stderr, "Sensor read error (ALS=%s, PS=%s)\n",
                    als_ok == 0 ? "ok" : "fail",
                    ps_ok  == 0 ? "ok" : "fail");
        }

        /* Sleep in 10 ms increments so SIGINT is caught promptly */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 10)
            usleep(10 * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

