/*
 * Si1182-A-GM biometric sensor logger for Raspberry Pi 3 Model B+
 * Uses standard Linux I2C ioctl interface (no wiringPi dependency).
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   Si1182 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o si1182_logger si1182_logger.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1182 register definitions (per datasheet) ---- */
#define SI1182_I2C_BUS        "/dev/i2c-1"
#define SI1182_I2C_ADDR       0x60          /* Si1182 default I2C address */

#define SI1182_REG_PART_ID    0x00
#define SI1182_REG_HW_REV     0x01
#define SI1182_REG_SEQ_ID     0x02
#define SI1182_REG_INT_CFG    0x03
#define SI1182_REG_INT_EN     0x04
#define SI1182_REG_INT_ST     0x05
#define SI1182_REG_MEAS_RATE  0x08
#define SI1182_REG_ALS_RATE   0x09
#define SI1182_REG_PS_RATE    0x0A
#define SI1182_REG_PS_LED21   0x0F
#define SI1182_REG_PS_LED3    0x10
#define SI1182_REG_PS1_DATA   0x11
#define SI1182_REG_PS2_DATA   0x12
#define SI1182_REG_ALS_DATA   0x13
#define SI1182_REG_COMMAND    0x18

#define SI1182_CMD_RESET      0x01
#define SI1182_CMD_PS_FORCE   0x0B
#define SI1182_CMD_ALS_FORCE  0x0C

#define SI1182_PART_ID        0x82          /* expected part ID for Si1182-A-GM */

#define LOG_FILE_NAME         "biometric_log.txt"
#define SAMPLE_PERIOD_MS      100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1182 register; returns 0 on success, -1 on error. */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1182 register; returns 0 on success, -1 on error. */
static int si1182_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair (low byte at reg, high at reg+1). */
static int si1182_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1182_read_reg(fd, reg, &lo) < 0) return -1;
    if (si1182_read_reg(fd, reg + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int si1182_init(int fd)
{
    uint8_t part_id = 0;

    /* 1. Software reset */
    if (si1182_write_reg(fd, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0)
        return -1;
    usleep(10000);  /* allow reset to complete */

    /* 2. Verify part ID */
    if (si1182_read_reg(fd, SI1182_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X). "
                        "Sensor not present or wrong device.\n",
                part_id, SI1182_PART_ID);
        return -1;
    }

    /* 3. Configure measurement rate registers (per datasheet) */
    if (si1182_write_reg(fd, SI1182_REG_MEAS_RATE, 0x0A) < 0) return -1; /* 100 ms */
    if (si1182_write_reg(fd, SI1182_REG_ALS_RATE,  0x0A) < 0) return -1;
    if (si1182_write_reg(fd, SI1182_REG_PS_RATE,   0x0A) < 0) return -1;

    /* 4. Configure LED current for proximity sensors (LED1 + LED2) */
    if (si1182_write_reg(fd, SI1182_REG_PS_LED21, 0x0F) < 0) return -1; /* ~22 mA */
    if (si1182_write_reg(fd, SI1182_REG_PS_LED3,  0x0F) < 0) return -1;

    /* 5. Clear any pending interrupts */
    (void)si1182_write_reg(fd, SI1182_REG_INT_ST, 0x00);

    return 0;
}

/* ------------------------------------------------------------------ */
static int si1182_read_lux(int fd, float *lux_out)
{
    uint16_t als_data = 0;
    if (si1182_read_reg16(fd, SI1182_REG_ALS_DATA, &als_data) < 0)
        return -1;

    /* Lux conversion: raw / 100  (datasheet scaling factor) */
    *lux_out = (float)als_data / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static int si1182_read_proximity(int fd, uint16_t *prox_out)
{
    uint16_t ps1_data = 0;
    if (si1182_read_reg16(fd, SI1182_REG_PS1_DATA, &ps1_data) < 0)
        return -1;
    *prox_out = ps1_data;
    return 0;
}

/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t cur = strlen(buf);
    snprintf(buf + cur, len - cur, ".%03ld", ts.tv_nsec / 1000000);
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const char *ts, float lux, uint16_t prox)
{
    fprintf(fp, "%s,%.2f,%u\n", ts, lux, prox);
    fflush(fp);
    printf("%s,%.2f,%u\n", ts, lux, prox);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(SI1182_I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SI1182_I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1182_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Si1182 logger started. Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME, SAMPLE_PERIOD_MS);

    while (g_running) {
        char ts[32];
        float lux;
        uint16_t prox;

        get_timestamp(ts, sizeof(ts));

        if (si1182_read_lux(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "%s: Error reading lux data.\n", ts);
        } else if (si1182_read_proximity(g_i2c_fd, &prox) < 0) {
            fprintf(stderr, "%s: Error reading proximity data.\n", ts);
        } else {
            log_data(g_log_fp, ts, lux, prox);
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* Cleanup */
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

