#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_PS_LED21 0x0F
#define SI1145_REG_PS1_DATA0 0x22
#define SI1145_REG_PS1_DATA1 0x23

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, ERROR: %s (errno: %d)\n", timestamp, message, errno);
        fflush(log_file);
    }
    fprintf(stderr, "%s, ERROR: %s (errno: %d)\n", timestamp, message, errno);
}

static int si1145_write_reg(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int si1145_read_reg(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        log_error("I2C read failed");
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int si1145_init(void) {
    uint8_t part_id = 0;

    if (si1145_read_reg(SI1145_REG_PART_ID, &part_id) < 0) {
        log_error("Failed to read Part ID");
        return -1;
    }

    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (si1145_write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        log_error("Failed to write HW_KEY");
        return -1;
    }

    if (si1145_write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        log_error("Failed to write MEAS_RATE0");
        return -1;
    }

    if (si1145_write_reg(SI1145_REG_PS_LED21, 0x0F) < 0) {
        log_error("Failed to write PS_LED21");
        return -1;
    }

    return 0;
}

static int read_proximity(uint16_t *proximity) {
    uint8_t data0 = 0, data1 = 0;

    if (si1145_read_reg(SI1145_REG_PS1_DATA0, &data0) < 0) {
        return -1;
    }
    if (si1145_read_reg(SI1145_REG_PS1_DATA1, &data1) < 0) {
        return -1;
    }

    *proximity = ((uint16_t)data1 << 8) | data0;
    return 0;
}

static void log_proximity(uint16_t proximity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, Proximity: %u\n", timestamp, proximity);
        fflush(log_file);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t proximity = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (read_proximity(&proximity) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    usleep(100000);
                }
            }
        }

        if (success) {
            log_proximity(proximity);
        } else {
            log_error("Failed to read proximity after multiple retries");
            break;
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nCleaning up...\n");

    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

