code:
/*
 * HC-SR04 ultrasonic distance measurement with buzzer alert.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (C API)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO17 (BCM)
 *   HC-SR04 ECHO -> GPIO18 (BCM)
 *   Buzzer      -> GPIO27 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04_buzzer hcsr04_buzzer.c -lpigpio -lrt
 * Run:
 *   sudo ./hcsr04_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define BUZZER_PIN       27

#define DISTANCE_THRESHOLD_CM  20.0f
#define SOUND_SPEED_CM_PER_US  0.0343f   /* 343 m/s in cm/us */
#define TRIGGER_PULSE_US       10
#define SAMPLE_PERIOD_US       1000000   /* 1 s */
#define ECHO_TIMEOUT_US        30000     /* 30 ms max echo wait */

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                      */
/* ------------------------------------------------------------------ */

typedef struct {
    volatile uint32_t start_tick;
    volatile uint32_t end_tick;
    volatile bool     got_rising;
    volatile bool     got_falling;
} echo_state_t;

static echo_state_t g_echo;

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (runs in pigpio callback thread)                */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)userdata;

    if (gpio != ECHO_PIN) {
        return;
    }

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_echo.start_tick   = tick;
        g_echo.got_rising   = true;
        g_echo.got_falling  = false;
    } else if (level == 0 && g_echo.got_rising) {
        /* Falling edge: echo pulse ends */
        g_echo.end_tick     = tick;
        g_echo.got_falling  = true;
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
    }
}

static float calculate_distance_cm(uint32_t pulse_us)
{
    return (float)pulse_us * SOUND_SPEED_CM_PER_US / 2.0f;
}

static void control_buzzer(float distance_cm)
{
    int level = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
    if (gpioWrite(BUZZER_PIN, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER, %d) failed\n", level);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure known initial states --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* --- Register echo alert callback --- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  Trigger: GPIO%d | Echo: GPIO%d | Buzzer: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("  Threshold: %.1f cm | Sample period: 1 s\n",
           DISTANCE_THRESHOLD_CM);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main measurement loop --- */
    while (g_running) {
        /* Reset echo state */
        g_echo.start_tick   = 0;
        g_echo.end_tick     = 0;
        g_echo.got_rising   = false;
        g_echo.got_falling  = false;

        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t waited = 0;
        while (!g_echo.got_falling && g_running && waited < ECHO_TIMEOUT_US) {
            gpioDelay(100);          /* 100 us granularity */
            waited += 100;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo.got_falling) {
            fprintf(stderr, "Warning: echo timeout (no echo received)\n");
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        uint32_t pulse_us = g_echo.end_tick - g_echo.start_tick;
        float distance_cm = calculate_distance_cm(pulse_us);

        printf("Distance: %.2f cm\n", distance_cm);
        control_buzzer(distance_cm);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);   /* unregister callback */
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

