/*
 * Parking-assist system for Raspberry Pi Zero W
 * HC-SR04 ultrasonic sensor: trigger=GPIO4, echo=GPIO17
 * SG90 servo: pulse width on GPIO18 (BCM)
 *
 * Build: gcc -O2 -Wall -o parking_assist parking_assist.c -lpigpio -lrt
 * Run:   sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      4
#define ECHO_PIN         17
#define SERVO_PIN        18

#define SPEED_OF_SOUND   34300.0   /* cm/s at 20 °C */
#define ECHO_TIMEOUT_US  30000     /* 30 ms max echo wait */
#define SAMPLE_PERIOD_US 100000    /* 100 ms between readings */

/* SG90 pulse-width range (500–2500 µs) maps to 0–180° */
#define SERVO_MIN_US     500
#define SERVO_MAX_US     2500

/* Distance thresholds (cm) and corresponding servo angles (°) */
#define DIST_MAX         200.0
#define DIST_MIN         20.0
#define ANGLE_MAX        0
#define ANGLE_MIN        180

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Measure distance (cm) using the HC-SR04.
 * Returns -1.0 on timeout or GPIO error.
 */
static double measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0)
        return -1.0;
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0)
        return -1.0;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0)
        return -1.0;

    /* Wait for echo rising edge (timeout if no object detected) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0)
            return -1.0;          /* no echo — sensor absent or out of range */
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0)
            return -1.0;          /* echo stuck high — sensor error */
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    return (double)diff * SPEED_OF_SOUND / 2000000.0;
}

/*
 * Set servo angle (0–180°) using pigpio hardware PWM.
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;

    int pulse_us = SERVO_MIN_US +
        (int)((double)angle / 180.0 * (SERVO_MAX_US - SERVO_MIN_US));

    if (gpioServo(SERVO_PIN, pulse_us) < 0)
        return -1;
    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set servo pin %d as output.\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Parking assist started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: sensor read error — retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        /* Proportional servo control: far → 0°, near → 180° */
        double ratio = (DIST_MAX - distance) / (DIST_MAX - DIST_MIN);
        if (ratio < 0.0)   ratio = 0.0;
        if (ratio > 1.0)   ratio = 1.0;

        int angle = (int)(ANGLE_MAX + ratio * (ANGLE_MIN - ANGLE_MAX));
        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Warning: failed to set servo angle.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);   /* stop PWM signal */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

