/*
 * VL53L1X gate controller for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Servo signal -> GPIO18 (BCM, hardware PWM-capable)
 *
 * Build:
 *   gcc -O2 -Wall -o gate gate.c -lpigpio -lrt
 * Run:
 *   sudo ./gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define SERVO_PIN            18
#define DISTANCE_THRESHOLD   200   /* mm  - close to object */
#define DISTANCE_THRESHOLD2  250   /* mm  - far from object  */
#define SERVO_CLOSED_US      1000  /* pulse width when object far */
#define SERVO_OPEN_US        2000  /* pulse width when object near */
#define SERVO_SMOOTHING_US   100   /* smoothing window for hysteresis */
#define LOG_FILE             "gate_log.txt"
#define POLL_DELAY_US        50000 /* 50 ms between distance polls */
#define INIT_TIMEOUT_MS      1000  /* max wait for sensor init */

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET       0x0003
#define REG_MODEL_ID         0x010F
#define REG_RANGE_START      0x0087
#define REG_RANGE_STATUS     0x0089
#define REG_DISTANCE         0x0096
#define REG_INTERMEAS_MS     0x001B
#define REG_TIMING_BUDGET    0x001C
#define REG_SYSTEM_MODE      0x0080
#define REG_GPIO_HV_MUX      0x0030
#define REG_GPIO_TIO_HV      0x0031
#define REG_GPIO_TIO_HV2     0x0032
#define REG_GPIO_TIO_HV3     0x0033
#define REG_GPIO_TIO_HV4     0x0034
#define REG_GPIO_TIO_HV5     0x0035
#define REG_GPIO_TIO_HV6     0x0036
#define REG_GPIO_TIO_HV7     0x0037
#define REG_GPIO_TIO_HV8     0x0038
#define REG_GPIO_TIO_HV9     0x0039
#define REG_GPIO_TIO_HV10    0x003A
#define REG_GPIO_TIO_HV11    0x003B
#define REG_GPIO_TIO_HV12    0x003C
#define REG_GPIO_TIO_HV13    0x003D
#define REG_GPIO_TIO_HV14    0x003E
#define REG_GPIO_TIO_HV15    0x003F
#define REG_GPIO_TIO_HV16    0x0040
#define REG_GPIO_TIO_HV17    0x0041
#define REG_GPIO_TIO_HV18    0x0042
#define REG_GPIO_TIO_HV19    0x0043
#define REG_GPIO_TIO_HV20    0x0044
#define REG_GPIO_TIO_HV21    0x0045
#define REG_GPIO_TIO_HV22    0x0046
#define REG_GPIO_TIO_HV23    0x0047
#define REG_GPIO_TIO_HV24    0x0048
#define REG_GPIO_TIO_HV25    0x0049
#define REG_GPIO_TIO_HV26    0x004A
#define REG_GPIO_TIO_HV27    0x004B
#define REG_GPIO_TIO_HV28    0x004C
#define REG_GPIO_TIO_HV29    0x004D
#define REG_GPIO_TIO_HV30    0x004E
#define REG_GPIO_TIO_HV31    0x004F

#define VL53L1X_MODEL_ID     0xEA

/* ---- Globals ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg16(uint8_t *buf, uint16_t reg, uint8_t val)
{
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return i2cWriteDevice(i2c_handle, (char *)buf, 3);
}

static int i2c_read_reg16(uint8_t *buf, uint16_t reg, uint8_t *out, int len)
{
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) < 0)
        return -1;
    return i2cReadDevice(i2c_handle, (char *)out, len);
}

/* ---- VL53L1X driver ---- */
static int vl53l1x_init(void)
{
    uint8_t buf[2];
    uint8_t model_id = 0;

    /* Soft reset */
    if (i2c_write_reg16(buf, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Verify model ID */
    if (i2c_read_reg16(buf, REG_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    /* Set timing budget to 50 ms (0x006B) */
    if (i2c_write_reg16(buf, REG_TIMING_BUDGET, 0x6B) < 0) {
        fprintf(stderr, "Error: failed to set timing budget\n");
        return -1;
    }

    /* Set inter-measurement period to 50 ms (0x006B) */
    if (i2c_write_reg16(buf, REG_INTERMEAS_MS, 0x6B) < 0) {
        fprintf(stderr, "Error: failed to set inter-measurement period\n");
        return -1;
    }

    /* Start ranging (bit 0 = 0x01) */
    if (i2c_write_reg16(buf, REG_RANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    uint8_t buf[2];
    uint8_t status = 0;
    int elapsed = 0;

    /* Poll range status until data ready (bit 0 of byte 0) */
    while (elapsed < INIT_TIMEOUT_MS * 1000) {
        if (i2c_read_reg16(buf, REG_RANGE_STATUS, &status, 1) < 0) {
            fprintf(stderr, "Error: failed to read range status\n");
            return -1;
        }
        if ((status & 0x01) != 0)
            break;
        gpioDelay(1000); /* 1 ms */
        elapsed += 1000;
    }
    if (elapsed >= INIT_TIMEOUT_MS * 1000) {
        fprintf(stderr, "Error: ranging timeout\n");
        return -1;
    }

    /* Read 16-bit distance (big-endian) */
    if (i2c_read_reg16(buf, REG_DISTANCE, (uint8_t *)distance_mm, 2) < 0) {
        fprintf(stderr, "Error: failed to read distance\n");
        return -1;
    }

    return 0;
}

/* ---- Servo control ---- */
static void set_servo_pulse(int pulse_us)
{
    gpioServo(SERVO_PIN, pulse_us);
}

/* ---- Logging ---- */
static void log_event(int gate_open)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s - Gate %s\n", timestamp,
                gate_open ? "opened" : "closed");
        fflush(log_file);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        uint8_t buf[2];
        /* Stop ranging */
        i2c_write_reg16(buf, REG_RANGE_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioServo(SERVO_PIN, 0); /* stop PWM */
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    uint16_t distance = 0;
    int gate_open = 0;
    int last_pulse_us = SERVO_CLOSED_US;
    uint8_t buf[2];

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VL53L1X gate controller running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        if (vl53l1x_read_distance(&distance) < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Hysteresis control with smoothing */
        if (distance > DISTANCE_THRESHOLD) {
            /* Far from object: close gate */
            if (last_pulse_us > SERVO_CLOSED_US + SERVO_SMOOTHING_US) {
                set_servo_pulse(SERVO_CLOSED_US);
                last_pulse_us = SERVO_CLOSED_US;
            } else if (last_pulse_us < SERVO_CLOSED_US) {
                last_pulse_us = SERVO_CLOSED_US;
            }
            if (!gate_open) {
                log_event(1);
                gate_open = 1;
            }
        } else if (distance < DISTANCE_THRESHOLD2) {
            /* Close to object: open gate */
            if (last_pulse_us < SERVO_OPEN_US - SERVO_SMOOTHING_US) {
                set_servo_pulse(SERVO_OPEN_US);
                last_pulse_us = SERVO_OPEN_US;
            } else if (last_pulse_us > SERVO_OPEN_US) {
                last_pulse_us = SERVO_OPEN_US;
            }
            if (gate_open) {
                log_event(0);
                gate_open = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

