/*
 * HC-SR04 ultrasonic distance measurement with a servo-controlled angle
 * output on a Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   HC-SR04 trigger -> GPIO23 (BCM)
 *   HC-SR04 echo    -> GPIO24 (BCM)
 *   Servo signal    -> GPIO18 (BCM)  [common ground with 5 V]
 *
 * Build:  gcc -O2 -Wall -o hcsr04_servo hcsr04_servo.c -lpigpio -lrt
 * Run:    sudo ./hcsr04_servo
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN  23
#define ECHO_PIN     24
#define SERVO_PIN    18

/* ---- Timing constants (microseconds) ---- */
#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   50000   /* 50 ms — covers ~5 m round-trip */
#define LOOP_DELAY_US     100000  /* 100 ms between measurements */
#define SERVO_SETTLE_US   50000   /* 50 ms for servo to settle */

/* ---- Distance / angle mapping ---- */
#define MIN_DISTANCE_CM   2.0f
#define MAX_DISTANCE_CM   400.0f
#define MIN_ANGLE_DEG     0.0f
#define MAX_ANGLE_DEG     180.0f
#define MIN_SERVO_US      500     /* 0°   */
#define MAX_SERVO_US      2500    /* 180° */
#define SOUND_SPEED_CM_S  34300.0f

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance (cm) from the HC-SR04.
 * Returns -1.0 on timeout or sensor error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Issue a 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger high) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if no object detected) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Warning: echo start timeout (no object?)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout if sensor is absent) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Warning: echo end timeout (sensor absent?)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance_cm = (pulse_us / 1000000.0f) * SOUND_SPEED_CM_S / 2.0f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n",
                distance_cm);
        return -1.0f;
    }
    return distance_cm;
}

/*
 * Map distance to servo angle (0–180°).
 * Returns -1.0 if the distance is invalid.
 */
static float distance_to_angle(float distance_cm)
{
    if (distance_cm < 0.0f) {
        return -1.0f;
    }
    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n",
                distance_cm);
        return -1.0f;
    }

    float frac = (distance_cm - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    if (frac < 0.0f) frac = 0.0f;
    if (frac > 1.0f) frac = 1.0f;

    return MIN_ANGLE_DEG + frac * (MAX_ANGLE_DEG - MIN_ANGLE_DEG);
}

/*
 * Set servo angle (0–180°) by issuing a pulse of the appropriate width.
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(float angle)
{
    if (angle < 0.0f || angle > 180.0f) {
        fprintf(stderr, "Error: angle %.2f out of range\n", angle);
        return -1;
    }

    int pulse_us = (int)(MIN_SERVO_US +
        (angle / 180.0f) * (MAX_SERVO_US - MIN_SERVO_US));

    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n",
                SERVO_PIN, pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(servo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger init) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement with servo control.\n");
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            printf("Distance: ERROR (timeout or out of range)\n");
        } else {
            float angle = distance_to_angle(distance);
            if (angle < 0.0f) {
                printf("Distance: %.2f cm  Angle: ERROR\n", distance);
            } else {
                printf("Distance: %.2f cm  Angle: %.2f degrees\n",
                       distance, angle);
            }
        }

        /* Pause before next measurement */
        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);   /* Stop servo PWM */
    gpioWrite(TRIGGER_PIN, 0); /* Ensure trigger is low */
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

