        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(servo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger init) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement with servo control.\n");
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            printf("Distance: ERROR (timeout or out of range)\n");
        } else {
            float angle = distance_to_angle(distance);
            if (angle < 0.0f) {
                printf("Distance: %.2f cm  Angle: ERROR\n", distance);
            } else {
                printf("Distance: %.2f cm  Angle: %.2f degrees\n",
                       distance, angle);
            }
        }

        /* Pause before next measurement */
        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);   /* Stop servo PWM */
    gpioWrite(TRIGGER_PIN, 0); /* Ensure trigger is low */
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

