#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40

#define SI7005_REG_MEASURE_TEMP 0x00
#define SI7005_REG_MEASURE_HUMID 0x01
#define SI7005_REG_CONFIG 0x02
#define SI7005_REG_MANUFACTURER_ID 0x0F
#define SI7005_REG_DEVICE_ID 0x0D

#define SI7005_MANUFACTURER_ID 0x0D
#define SI7005_DEVICE_ID 0x07

#define CONVERSION_DELAY_US 10000
#define LOOP_DELAY_US 2000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    int data = i2cReadByte(handle);
    if (data < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    return 0;
}

static int read_sensor_data(int handle, float *temperature, float *humidity) {
    uint8_t msb, lsb;

    if (read_register(handle, SI7005_REG_MEASURE_TEMP, &msb) < 0) return -1;
    if (read_register(handle, SI7005_REG_MEASURE_TEMP, &lsb) < 0) return -1;
    *temperature = ((float)((msb << 8) | lsb)) / 16.0f;

    if (read_register(handle, SI7005_REG_MEASURE_HUMID, &msb) < 0) return -1;
    if (read_register(handle, SI7005_REG_MEASURE_HUMID, &lsb) < 0) return -1;
    *humidity = ((float)((msb << 8) | lsb)) / 16.0f;

    return 0;
}

static int verify_sensor(int handle) {
    uint8_t manuf_id, dev_id;
    if (read_register(handle, SI7005_REG_MANUFACTURER_ID, &manuf_id) < 0) return -1;
    if (read_register(handle, SI7005_REG_DEVICE_ID, &dev_id) < 0) return -1;

    if (manuf_id != SI7005_MANUFACTURER_ID || dev_id != SI7005_DEVICE_ID) {
        fprintf(stderr, "Sensor verification failed: Manufacturer ID = 0x%02X, Device ID = 0x%02X (expected 0x%02X, 0x%02X)\n",
                manuf_id, dev_id, SI7005_MANUFACTURER_ID, SI7005_DEVICE_ID);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, SI7005_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (verify_sensor(handle) < 0) {
        fprintf(stderr, "Si7005 sensor not detected or incorrect device\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    printf("Si7005 sensor detected. Starting data acquisition...\n");

    while (running) {
        float temperature, humidity;
        if (read_sensor_data(handle, &temperature, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            printf("[%s] Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading sensor data. Attempting to re-initialize I2C...\n");
            i2cClose(handle);
            handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                running = 0;
            } else if (verify_sensor(handle) < 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                i2cClose(handle);
                handle = -1;
                running = 0;
            }
        }
        gpioDelay(LOOP_DELAY_US);
    }

    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

