/*
 * MPU-6050 accelerometer/gyroscope reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   MPU-6050 VCC  -> Pi 3.3 V (pin 1)
 *   MPU-6050 GND  -> Pi GND  (pin 9)
 *   MPU-6050 SCL  -> Pi GPIO3 / SCL (pin 5)
 *   MPU-6050 SDA  -> Pi GPIO2 / SDA (pin 3)
 *
 * I2C bus 1 (typical address 0x68 when AD0 tied to GND).
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6050 mpu6050.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68          /* AD0 tied to GND */
#define MPU6050_WHO_AM_I    0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1  0x6B
#define MPU6050_PWR_MGMT_2  0x6C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_TEMP_OUT_H   0x41
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C

/* ---- I2C bus ---- */
#define I2C_BUS "/dev/i2c-1"

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 100000          /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block: read %zd of %zu bytes failed: %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    uint8_t who = 0;
    if (i2c_read_block(fd, MPU6050_WHO_AM_I, &who, 1) != 0)
        return -1;
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    printf("MPU-6050 detected (WHO_AM_I = 0x%02X).\n", who);

    /* Wake up: clear SLEEP bit, use internal 8 MHz clock */
    if (i2c_write_reg(fd, MPU6050_PWR_MGMT_1, 0x00) != 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilise */

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg(fd, MPU6050_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /* DLPF_CFG = 0 -> bandwidth 256 Hz, delay 0.98 ms */
    if (i2c_write_reg(fd, MPU6050_CONFIG, 0x00) != 0)
        return -1;

    /* Gyro full-scale range +/- 250 deg/s (FS_SEL = 0) */
    if (i2c_write_reg(fd, MPU6050_GYRO_CONFIG, 0x00) != 0)
        return -1;

    /* Accel full-scale range +/- 2 g (AFS_SEL = 0) */
    if (i2c_write_reg(fd, MPU6050_ACCEL_CONFIG, 0x00) != 0)
        return -1;

    /* Disable sleep mode, enable all axes */
    if (i2c_write_reg(fd, MPU6050_PWR_MGMT_2, 0x00) != 0)
        return -1;

    return 0;
}

static int mpu6050_read(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz,
                         int16_t *temp)
{
    uint8_t buf[14];
    if (i2c_read_block(fd, MPU6050_ACCEL_XOUT_H, buf, sizeof(buf)) != 0)
        return -1;

    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    *temp = (int16_t)((buf[4]  << 8) | buf[5]);  /* re-use accel temp word */
    return 0;
}

int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (mpu6050_init(fd) != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 ready. Sampling at ~125 Hz. Press Ctrl-C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz, temp;
        if (mpu6050_read(fd, &ax, &ay, &az, &gx, &gy, &gz, &temp) != 0) {
            fprintf(stderr, "Read error — continuing.\n");
        } else {
            printf("Accel: %6d %6d %6d  |  Gyro: %6d %6d %6d  |  Temp: %6d\n",
                   ax, ay, az, gx, gy, gz, temp);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (close(fd) != 0)
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
    return EXIT_SUCCESS;
}

