        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_temperature(float *temperature) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[6];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "I2C write failed (attempt %d/%d): %s",
                     attempt + 1, MAX_RETRIES, strerror(errno));
            log_error(msg);
            gpioDelay(100000);
            continue;
        }

        gpioDelay(20000);

        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result != 6) {
            char msg[128];
            snprintf(msg, sizeof(msg), "I2C read failed (attempt %d/%d): expected 6 bytes, got %d",
                     attempt + 1, MAX_RETRIES, result);
            log_error(msg);
            gpioDelay(100000);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
        return 0;
    }

    return -1;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d: %s\n",
                STS30_I2C_ADDR, I2C_BUS, strerror(errno));
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts\n", MAX_RETRIES);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

