/*
 * SDP810-125Pa differential pressure & temperature logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   SDP810 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c
 * Run:    ./sdp810_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x5C          /* SDP810-125Pa default I2C address */

/* SDP810 continuous measurement command (MSB first) */
static const uint8_t CMD_CONT_MEAS[2] = {0x36, 0x2F};

/* SDP810 scale-factor registers (MSB first) */
#define REG_SCALE_FACTOR  0x36
#define REG_TEMP_SCALE    0x37

/* Measurement frame: pressure(2)+CRC, temp(2)+CRC, scale(2)+CRC, scale(2)+CRC */
#define FRAME_LEN         9
#define MEAS_DELAY_MS     1            /* SDP810 conversion time ~1 ms */
#define SAMPLE_PERIOD_S  1            /* log interval */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, init 0x00 */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_scale_factor(int fd, uint16_t *scale)
{
    if (i2c_write(fd, (uint8_t[]){REG_SCALE_FACTOR}, 1) != 0)
        return -1;
    uint8_t buf[2];
    if (i2c_read(fd, buf, 2) != 0)
        return -1;
    if (crc8(buf, 2) != 0) {
        fprintf(stderr, "CRC mismatch on scale-factor register\n");
        return -1;
    }
    *scale = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_measurement(int fd, int16_t *raw_pressure,
                            int16_t *raw_temp, uint16_t *scale)
{
    if (i2c_write(fd, CMD_CONT_MEAS, 2) != 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t buf[FRAME_LEN];
    if (i2c_read(fd, buf, FRAME_LEN) != 0)
        return -1;

    /* Validate CRC for each 2-byte data word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on frame word %d\n", i);
            return -1;
        }
    }

    *raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    *scale        = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Probe sensor: try a zero-length write to confirm device presence */
    if (i2c_write(fd, (uint8_t[]){0x00}, 0) != 0) {
        fprintf(stderr, "SDP810 not responding at 0x%02X\n", SDP810_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    uint16_t scale_factor = 0;
    if (read_scale_factor(fd, &scale_factor) != 0) {
        fprintf(stderr, "Failed to read scale factor; sensor may be absent or bus error.\n");
        close(fd);
        return EXIT_FAILURE;
    }
    printf("SDP810 scale factor: %u\n", scale_factor);

    FILE *fp = fopen("pressure_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "Cannot open pressure_log.csv: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0)
        fprintf(fp, "timestamp,pressure_pa,temperature_c\n");

    printf("Logging to pressure_log.csv (Ctrl+C to stop)...\n");

    while (g_running) {
        int16_t raw_pressure = 0, raw_temp = 0;
        uint16_t scale = 0;

        if (read_measurement(fd, &raw_pressure, &raw_temp, &scale) != 0) {
            fprintf(stderr, "Measurement read failed; continuing.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* Convert raw to physical units per SDP810 datasheet */
        float pressure = (float)raw_pressure / (float)scale_factor;
        float temperature = (float)raw_temp / 200.0f;

        log_data(fp, pressure, temperature);
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

