/*
 * SHT40 humidity/temperature logger for Raspberry Pi 3 Model B+
 * Uses standard Linux I2C ioctl interface (no wiringPi dependency).
 *
 * Wiring:
 *   SHT40 SDA  -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   SHT40 SCL  -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   SHT40 VDD  -> 3.3 V
 *   SHT40 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht40_logger sht40_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define SHT40_ADDR       0x44          /* SHT40 7-bit I2C address */
#define SHT40_CMD_MEAS_H 0x2400        /* High repeatability, clock stretching disabled */
#define SHT40_MEAS_MS    10            /* Min measurement time (ms) */
#define LOG_FILE         "sht40_log.txt"
#define SAMPLE_PERIOD_S  5             /* Seconds between samples */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8                                                     */
/* ------------------------------------------------------------------ */
/* Polynomial 0x31, initial value 0xFF, no reflection, no final XOR.   */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[I2C] write(0x%04X) failed: %s (wrote %zd bytes)\n",
                cmd, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "[I2C] read failed: %s (got %zd of %zu)\n",
                strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * SHT40 high-repeatability measurement command (0x2400):
 *   Byte 0: 0x24  (MSB of command)
 *   Byte 1: 0x00  (LSB of command)
 *   Byte 2: 0x00  (dummy CRC byte, response contains real CRC)
 * The sensor responds with 6 bytes:
 *   [T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC]
 *   (Temperature: 0.01 °C per LSB; Humidity: 0.01 %RH per LSB)
 */
static int sht40_read(int fd, float *temperature, float *humidity)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, SHT40_CMD_MEAS_H) != 0)
        return -1;

    usleep(SHT40_MEAS_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    /* Validate CRCs */
    if (sensirion_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[SHT40] temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[SHT40] humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[LOG] strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                ts, temperature, humidity) < 0) {
        fprintf(stderr, "[LOG] fprintf failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0)
        fprintf(stderr, "[LOG] fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[MAIN] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[MAIN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[MAIN] open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "[MAIN] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SHT40_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[MAIN] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[MAIN] SHT40 logger started. Logging to %s every %d s. "
           "Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_PERIOD_S);

    while (g_running) {
        float temperature, humidity;

        if (sht40_read(g_i2c_fd, &temperature, &humidity) == 0) {
            log_data(g_log_fp, temperature, humidity);
            printf("[MAIN] T=%.2f C  H=%.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "[MAIN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++)
            sleep(1);
    }

    printf("\n[MAIN] Shutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

