/*
 * SDP31 differential pressure & temperature logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP31 VDD  -> Pi 3V3  (pin 1)
 *   SDP31 GND  -> Pi GND  (pin 9)
 *   SDP31 SDA  -> Pi GPIO2 / I2C1 SDA (pin 3)
 *   SDP31 SCL  -> Pi GPIO3 / I2C1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -li2c
 * Run:    ./airflow   (requires root or i2c group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP31_ADDR      0x40
#define LOG_FILE        "airflow.log"
#define SAMPLE_MS       100
#define MAX_RETRIES     3
#define MEAS_DELAY_MS   1

/* SDP31 continuous measurement command (MSB first) */
static const uint8_t CMD_CONT_MEAS[2] = {0x36, 0x2F};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Compute Sensirion CRC-8 (polynomial 0x31, init 0xFF) */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* Write a 2-byte command to the SDP31 */
static int sdp_write(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Read exactly `len` bytes from the SDP31 */
static int sdp_read(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* Trigger continuous measurement and read 6 bytes with retries */
static int sdp_read_measurement(int fd, float *pressure, float *temperature)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (sdp_write(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
            usleep(1000 * (1 << attempt));
            continue;
        }
        usleep(MEAS_DELAY_MS * 1000);

        uint8_t buf[6];
        if (sdp_read(fd, buf, sizeof(buf)) != 0) {
            usleep(1000 * (1 << attempt));
            continue;
        }

        /* Validate CRCs */
        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Pressure CRC mismatch (attempt %d)\n", attempt + 1);
            usleep(1000 * (1 << attempt));
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            usleep(1000 * (1 << attempt));
            continue;
        }

        int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);

        *pressure    = (float)raw_p / 60.0f;   /* Pa */
        *temperature = (float)raw_t / 200.0f;  /* °C */
        return 0;
    }
    return -1;
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP31_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP31_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP31 airflow logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (sdp_read_measurement(fd, &pressure, &temperature) == 0) {
            time_t now = time(NULL);
            struct tm tmv;
            char ts[32];
            if (localtime_r(&now, &tmv)) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
            } else {
                snprintf(ts, sizeof(ts), "1970-01-01 00:00:00");
            }

            fprintf(log, "%s,%.2f,%.2f\n", ts, pressure, temperature);
            fflush(log);
            printf("%s  Pressure: %.2f Pa  Temperature: %.2f °C\n",
                   ts, pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read SDP31 after %d retries.\n", MAX_RETRIES);
        }

        /* Sleep SAMPLE_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 10)
            usleep(10 * 1000);
    }

    /* Clean resource release */
    printf("\nShutting down...\n");
    fclose(log);
    close(fd);
    return EXIT_SUCCESS;
}

