#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define CMD_TEMP_HOLD 0xE3
#define CMD_HUM_HOLD 0xE5
#define CMD_RESET 0xFE
#define LOG_FILE "sensor_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define MEASURE_TIMEOUT_MS 20

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int si7015_reset(int handle) {
    char cmd = CMD_RESET;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to send reset command\n");
        return -1;
    }
    gpioDelay(15000); /* 15 ms reset recovery */
    return 0;
}

static int read_measurement(int handle, uint8_t cmd, uint16_t *raw) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        char cmd_buf[1] = {cmd};
        if (i2cWriteDevice(handle, cmd_buf, 1) != 0) {
            fprintf(stderr, "Error: failed to write measurement command 0x%02X (retry %d)\n", cmd, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASURE_TIMEOUT_MS * 1000);

        int bytes_read = i2cReadDevice(handle, buf, 2);
        if (bytes_read == 2) {
            *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }

        fprintf(stderr, "Error: failed to read measurement 0x%02X (got %d bytes, retry %d)\n", cmd, bytes_read, retries + 1);
        retries++;
        gpioDelay(10000);
    }
    return -1;
}

static float convert_temperature(uint16_t raw) {
    return (175.72f * raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw) {
    float h = (125.0f * raw / 65536.0f) - 6.0f;
    if (h < 0.0f) h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

static int log_data(float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp, hum);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C bus %d at address 0x%02X (pigpio error %d)\n", I2C_BUS, SI7015_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (si7015_reset(i2c_handle) != 0) {
        fprintf(stderr, "Error: Si7015 reset failed (sensor may be absent)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si7015 sensor initialized on I2C bus %d at address 0x%02X. Logging to '%s' every %d seconds.\n", I2C_BUS, SI7015_ADDR, LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t raw_temp = 0, raw_hum = 0;

        if (read_measurement(i2c_handle, CMD_TEMP_HOLD, &raw_temp) != 0) {
            fprintf(stderr, "Error: failed to read temperature after %d retries\n", MAX_RETRIES);
            break;
        }

        if (read_measurement(i2c_handle, CMD_HUM_HOLD, &raw_hum) != 0) {
            fprintf(stderr, "Error: failed to read humidity after %d retries\n", MAX_RETRIES);
            break;
        }

        float temp = convert_temperature(raw_temp);
        float hum = convert_humidity(raw_hum);

        if (log_data(temp, hum) != 0) {
            fprintf(stderr, "Error: failed to log data\n");
        }

        printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", "sample", temp, hum);

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return 0;
}

