    /* Temperature: bytes 0–1, CRC byte 2 */
    if (sensirion_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[SHT40] temperature CRC mismatch\n");
        return -1;
    }

    /* Humidity: bytes 3–4, CRC byte 5 */
    if (sensirion_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[SHT40] humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            ts, temperature, humidity);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[I2C] open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire sensor device */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "[I2C] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SHT40_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[LOG] open(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Monitor — SHT40 logging to %s every %d s\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float temperature, humidity;

        if (sht40_read(g_i2c_fd, &temperature, &humidity) == 0) {
            log_data(g_log_fp, temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "[SHT40] read failed — continuing\n");
        }

        /* Sleep but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

