/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_logger sdp800_logger.c
 * Run:    ./sdp800_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR     0x25          /* SDP8xx-5xx series default I2C address */
#define LOG_FILE        "airflow_data.txt"
#define MEAS_DELAY_MS   1000          /* SDP800 needs >= 1 ms after a continuous-start command */
#define SAMPLE_PERIOD_S 5             /* Sample every 5 seconds */

/* SDP8xx CRC-8: polynomial 0x31, init 0xFF, no reflection */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 validation                                                    */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * SDP800 continuous measurement command (0x36).
 * The sensor responds with 6 bytes:  [P_MSB, P_LSB, P_CRC, T_MSB, T_LSB, T_CRC]
 * Pressure is signed 16-bit, scaled by 0.01 Pa per LSB.
 * Temperature is signed 16-bit, scaled by 0.01 °C per LSB.
 */
static int read_sdp800(int fd, float *pressure, float *temperature)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, 0x36) != 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(&data[0], 2), data[2]);
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(&data[3], 2), data[5]);
        return -1;
    }

    int16_t raw_p = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_t = (int16_t)((data[3] << 8) | data[4]);

    *pressure    = (float)raw_p * 0.01f;
    *temperature = (float)raw_t * 0.01f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, float pressure, float temperature)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_local) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire sensor address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP800 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD_S);

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sdp800(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            if (log_sample(g_log_fp, pressure, temperature) != 0)
                fprintf(stderr, "Logging failed for this sample.\n");
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

