/*
 * Si7021 humidity/temperature monitor with hysteresis fan control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Si7021 on address 0x40
 * Fan:    GPIO18 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_fan si7021_fan.c -lpigpio -lrt
 * Run:    sudo ./si7021_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SI7021_ADDR          0x40
#define FAN_GPIO             18
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define BUFFER_SIZE          60
#define SAMPLE_INTERVAL_S    2
#define FAN_COOLDOWN_MS      10
#define MAX_RETRIES          3
#define INVALID_TEMP         (-1000.0f)

/* Si7021 register addresses */
#define SI7021_MEASURE_TEMP_HOLD  0xE3
#define SI7021_MEASURE_HUMID_HOLD 0xE5
#define SI7021_RESET              0xFE
#define SI7021_WHO_AM_I           0x0F

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    time_t timestamp;
    float  temperature;
} TemperatureReading;

static TemperatureReading g_buffer[BUFFER_SIZE];
static int g_buffer_index = 0;
static int g_buffer_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByte(handle, cmd);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteByte(0x%02X) failed (rc=%d, attempt %d/%d)\n",
                cmd, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(1000); /* 1 ms back-off */
    }
    return -1;
}

static int i2c_read_word(int handle, uint8_t cmd, uint16_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByte(handle, cmd);
        if (rc != 0) {
            fprintf(stderr, "[WARN] i2cWriteByte(0x%02X) failed (rc=%d, attempt %d/%d)\n",
                    cmd, rc, attempt + 1, MAX_RETRIES);
            gpioDelay(1000);
            continue;
        }
        gpioDelay(1000); /* sensor conversion time */

        char buf[2];
        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadDevice(0x%02X) returned %d (attempt %d/%d)\n",
                cmd, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Si7021 sensor                                                      */
/* ------------------------------------------------------------------ */
static int si7021_reset(int handle)
{
    if (i2c_write_cmd(handle, SI7021_RESET) != 0) {
        fprintf(stderr, "[ERROR] Si7021 reset failed\n");
        return -1;
    }
    gpioDelay(15000); /* datasheet: 15 ms reset recovery */
    return 0;
}

static int si7021_verify(int handle)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByte(handle, SI7021_WHO_AM_I);
        if (rc != 0) {
            fprintf(stderr, "[WARN] WHO_AM_I write failed (rc=%d, attempt %d/%d)\n",
                    rc, attempt + 1, MAX_RETRIES);
            gpioDelay(1000);
            continue;
        }
        gpioDelay(1000);
        char buf[1];
        rc = i2cReadDevice(handle, buf, 1);
        if (rc == 1 && (uint8_t)buf[0] == 0x0D) {
            return 0; /* Si7021 */
        }
        fprintf(stderr, "[WARN] WHO_AM_I mismatch (got 0x%02X, expected 0x0D, attempt %d/%d)\n",
                (uint8_t)buf[0], attempt + 1, MAX_RETRIES);
        gpioDelay(1000);
    }
    return -1;
}

static float si7021_read_temperature(int handle)
{
    uint16_t raw;
    if (i2c_read_word(handle, SI7021_MEASURE_TEMP_HOLD, &raw) != 0) {
        fprintf(stderr, "[ERROR] Temperature read failed\n");
        return INVALID_TEMP;
    }
    /* 14-bit left-justified in 16-bit result; shift right 2 to get 14-bit signed */
    int16_t t = (int16_t)raw;
    t >>= 2;
    return (float)t * 0.01f;
}

static float si7021_read_humidity(int handle)
{
    uint16_t raw;
    if (i2c_read_word(handle, SI7021_MEASURE_HUMID_HOLD, &raw) != 0) {
        fprintf(stderr, "[ERROR] Humidity read failed\n");
        return -1.0f;
    }
    /* 12-bit, shifted right 4 */
    int16_t h = (int16_t)raw;
    h >>= 4;
    return (float)h * 0.0405f + 0.0f;
}

/* ------------------------------------------------------------------ */
/* Fan control                                                         */
/* ------------------------------------------------------------------ */
static void fan_set(int state)
{
    if (gpioWrite(FAN_GPIO, state ? 1 : 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d) failed\n", state);
    }
}

static void control_fan(float temperature)
{
    static bool fan_on = false;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        fan_set(1);
        fan_on = true;
        printf("[INFO] Fan ON  (T=%.2f C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        fan_set(0);
        fan_on = false;
        printf("[INFO] Fan OFF (T=%.2f C)\n", temperature);
    }
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
static void buffer_add(float temperature)
{
    g_buffer[g_buffer_index].timestamp = time(NULL);
    g_buffer[g_buffer_index].temperature = temperature;
    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE)
        g_buffer_count++;
}

static void buffer_print(void)
{
    printf("\n--- Temperature History (%d entries) ---\n", g_buffer_count);
    for (int i = 0; i < g_buffer_count; ++i) {
        int idx = (g_buffer_index - g_buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                 localtime(&g_buffer[idx].timestamp));
        printf("  [%s]  %.2f C\n", ts, g_buffer[idx].temperature);
    }
    printf("-----------------------------------------\n\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    fan_set(0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- fan GPIO setup --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fan_set(0);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- sensor presence check --- */
    if (si7021_verify(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si7021 not detected at 0x%02X on bus %d\n",
                SI7021_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- reset sensor --- */
    if (si7021_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si7021 reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Si7021 fan controller started.  Bus %d, addr 0x%02X, fan GPIO%d\n",
           I2C_BUS, SI7021_ADDR, FAN_GPIO);
    printf("[INFO] Sampling every %d s.  Ctrl+C to exit.\n\n", SAMPLE_INTERVAL_S);

    /* --- main loop --- */
    while (g_running) {
        float temperature = si7021_read_temperature(g_i2c_handle);

        if (temperature <= INVALID_TEMP + 0.001f) {
            fprintf(stderr, "[ERROR] Temperature read failed; skipping cycle\n");
        } else {
            printf("[INFO] Temperature: %.2f C\n", temperature);
            buffer_add(temperature);
            buffer_print();
            control_fan(temperature);
        }

        /* fan cooldown so we don't retrigger immediately after a read failure */
        gpioDelay(FAN_COOLDOWN_MS * 1000);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

