/*
 * Si7021 humidity/temperature monitor with hysteresis fan control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Si7021 on address 0x40
 * Fan:    GPIO18 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_fan si7021_fan.c -lpigpio -lrt
 * Run:    sudo ./si7021_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SI7021_ADDR          0x40
#define FAN_GPIO             18
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define BUFFER_SIZE          60
#define SAMPLE_INTERVAL_S    2
#define FAN_COOLDOWN_MS      10
#define MAX_RETRIES          3
#define INVALID_TEMP         (-1000.0f)

/* Si7021 register addresses */
#define SI7021_MEASURE_TEMP_HOLD  0xE3
#define SI7021_MEASURE_HUMID_HOLD 0xE5
#define SI7021_RESET              0xFE
#define SI7021_WHO_AM_I           0x0F

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    time_t timestamp;
    float  temperature;
} TemperatureReading;

static TemperatureReading g_buffer[BUFFER_SIZE];
static int g_buffer_index = 0;
static int g_buffer_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByte(handle, cmd);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteByte(0x%02X) failed (rc=%d, attempt %d/%d)\n",
                cmd, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(1000); /* 1 ms back-off */
    }
    return -1;
}

static int i2c_read_word(int handle, uint8_t cmd, uint16_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByte(handle, cmd);
        if (rc != 0) {
            fprintf(stderr, "[WARN] i2cWriteByte(0x%02X) failed (rc=%d, attempt %d/%d)\n",
                    cmd, rc, attempt + 1, MAX_RETRIES);
            gpioDelay(1000);
            continue;
        }
        gpioDelay(1000); /* sensor conversion time */

        char buf[2];
        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadDevice(0x%02X) returned %d (attempt %d/%d)\n",
                cmd, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Si7021 sensor                                                      */
/* ------------------------------------------------------------------ */
static int si7021_reset(int handle)
{
    if (i2c_write_cmd(handle, SI7021_RESET) != 0) {
        fprintf(stderr, "[ERROR] Si7021 reset failed\n");
        return -1;
    }
    gpioDelay(15000); /* datasheet: 15 ms reset recovery */
    return 0;
}

static int si7021_verify(int handle)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByte(handle, SI7021_WHO_AM_I);
        if (rc != 0) {
            fprintf(stderr, "[WARN] WHO_AM_I write failed (rc=%d, attempt %d/%d)\n",
                    rc, attempt + 1, MAX_RETRIES);
            gpioDelay(1000);
            continue;
        }
        gpioDelay(1000);
        char buf[1];
        rc = i2cReadDevice(handle, buf, 1);
        if (rc == 1 && (uint8_t)buf[0] == 0x0D) {
            return 0; /* Si7021 */
        }
        fprintf(stderr, "[WARN] WHO_AM_I mismatch (got 0x%02X, expected 0x0D, attempt %d/%d)\n",
                (uint8_t)buf[0], attempt + 1, MAX_RETRIES);
        gpioDelay(1000);
    }
    return -1;
}

static float si7021_read_temperature(int handle)
{
    uint16_t raw;
    if (i2c_read_word(handle, SI7021_MEASURE_TEMP_HOLD, &raw) != 0) {
        fprintf(stderr, "[ERROR] Temperature read failed\n");
        return INVALID_TEMP;
    }
    /* 14-bit left-justified in 16-bit result; shift right 2 to get 14-bit signed */
    int16_t t = (int16_t)raw;
    t >>= 2;
    return (float)t * 0.01f;
}

static float si7021_read_humidity(int handle)
{
    uint16_t raw;
    if (i2c_read_word(handle, SI7021_MEASURE_HUMID_HOLD, &raw) != 0) {
        fprintf(stderr, "[ERROR] Humidity read failed\n");
        return -1.0f;
    }
    /* 12-bit, shifted right 4 */
    int16_t h = (int16_t)raw;
    h >>= 4;
    return (float)h * 0.0405f + 0.0f;
}

/* ------------------------------------------------------------------ */
/* Fan control                                                         */
/* ------------------------------------------------------------------ */
static void fan_set(int state)
{
    if (gpioWrite(FAN_GPIO, state ? 1 : 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d) failed\n", state);
    }
}

static void control_fan(float temperature)
{
    static bool fan_on = false;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        fan_set(1);
        fan_on = true;
        printf("[INFO] Fan ON  (T=%.2f C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        fan_set(0);
        fan_on = false;
        printf("[INFO] Fan OFF (T=%.2f C)\n", temperature);
    }
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
static void buffer_add(float temperature)
{
    g_buffer[g_buffer_index].timestamp = time(NULL);
    g_buffer[g_buffer_index].temperature = temperature;
    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE)
        g_buffer_count++;
}

static void buffer_print(void)
{
    printf("\n--- Temperature History (%d entries) ---\n", g_buffer_count);
    for (int i = 0; i < g_buffer_count; ++i) {
        int idx = (g_buffer_index - g_buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                 localtime(&g_buffer[idx].timestamp));
        printf("  [%s]  %.2f C\n", ts, g_buffer[idx].temperature);
    }
    printf("-----------------------------------------\n\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    fan_set(0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- fan GPIO setup --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fan_set(0);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- sensor presence check --- */
    if (si7021_verify(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si7021 not detected at 0x%02X on bus %d\n",
                SI7021_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- reset sensor --- */
    if (si7021_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si7021 reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Si7021 fan controller started.  Bus %d, addr 0x%02X, fan GPIO%d\n",
           I2C_BUS, SI7021_ADDR, FAN_GPIO);
    printf("[INFO] Sampling every %d s.  Ctrl+C to exit.\n\n", SAMPLE_INTERVAL_S);

    /* --- main loop --- */
    while (g_running) {
        float temperature = si7021_read_temperature(g_i2c_handle);

        if (temperature <= INVALID_TEMP + 0.001f) {
            fprintf(stderr, "[ERROR] Temperature read failed; skipping cycle\n");
        } else {
            printf("[INFO] Temperature: %.2f C\n", temperature);
            buffer_add(temperature);
            buffer_print();
            control_fan(temperature);
        }

        /* fan cooldown so we don't retrigger immediately after a read failure */
        gpioDelay(FAN_COOLDOWN_MS * 1000);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * Raspberry Pi Zero W – Sensirion SCD40 CO2 / Temperature / Humidity logger
 *
 * Wiring:
 *   SCD40 VDD  -> Pi 3V3  (pin 1)
 *   SCD40 GND  -> Pi GND  (pin 9)
 *   SCD40 SDA  -> Pi GPIO2 / I2C1 SDA (pin 3)
 *   SCD40 SCL  -> Pi GPIO3 / I2C1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o air_quality air_quality.c -li2c
 *
 * The SCD40 is a photoacoustic sensor: ambient light is required for its
 * measurement.  The sensor is configured to start periodic measurement,
 * wait one second, then poll the data-ready flag every 5 s, read the
 * 9-byte data block, verify CRC-8, and append CSV lines to
 * "air_quality.log".
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SCD40_I2C_ADDR        0x61
#define I2C_BUS               "/dev/i2c-1"
#define LOG_FILE              "air_quality.log"
#define POLL_INTERVAL_SEC     5
#define FIRST_MEAS_DELAY_SEC  1
#define MEAS_READY_TIMEOUT    30   /* max seconds to wait for first data */

/* SCD40 command opcodes (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC    0x21B1
#define CMD_STOP_PERIODIC     0x3FF9
#define CMD_READ_MEASUREMENT  0x3618

/* SCD40 data-ready flag bit in the first byte of the 9-byte block */
#define DATA_READY_BIT        0x07

/* ------------------------------------------------------------------ */
/* Globals for signal-safe cleanup                                    */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (want %zu, got %zd): %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF, no final XOR)          */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Sensor driver                                                       */
/* ------------------------------------------------------------------ */
typedef struct {
    int fd;
} scd40_t;

static int scd40_init(scd40_t *s)
{
    s->fd = open(I2C_BUS, O_RDWR);
    if (s->fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(s->fd, I2C_SLAVE, SCD40_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SCD40_I2C_ADDR, strerror(errno));
        close(s->fd);
        s->fd = -1;
        return -1;
    }
    return 0;
}

static void scd40_stop_periodic(scd40_t *s)
{
    if (s->fd >= 0) {
        (void)i2c_write_cmd(s->fd, CMD_STOP_PERIODIC);
        /* flush any stale data */
        uint8_t dummy[9];
        (void)i2c_read_block(s->fd, dummy, sizeof(dummy));
    }
}

static int scd40_start_periodic(scd40_t *s)
{
    if (i2c_write_cmd(s->fd, CMD_START_PERIODIC) != 0)
        return -1;
    /* Datasheet: first measurement ready after ~5 s */
    sleep(5);
    return 0;
}

/*
 * Returns 0 on success and fills *co2, *temp, *rh.
 * Returns -1 on I/O or CRC error.
 */
static int scd40_read_measurement(scd40_t *s, uint16_t *co2,
                                  float *temp, float *rh)
{
    if (i2c_write_cmd(s->fd, CMD_READ_MEASUREMENT) != 0)
        return -1;

    uint8_t buf[9];
    if (i2c_read_block(s->fd, buf, sizeof(buf)) != 0)
        return -1;

    /* Data-ready flag is the low three bits of the first byte */
    if ((buf[0] & DATA_READY_BIT) == 0) {
        fprintf(stderr, "SCD40 data not ready (0x%02X)\n", buf[0]);
        return -1;
    }

    /* Verify CRC for each 2-byte word */
    for (int i = 0; i < 6; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw  = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw   = ((uint16_t)buf[6] << 8) | buf[7];

    *co2  = co2_raw;
    *temp = -45.0f + (float)temp_raw / 200.0f;
    *rh   = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t co2, float temp, float rh)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            co2, temp, rh);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    scd40_t sensor;
    if (scd40_init(&sensor) != 0)
        return EXIT_FAILURE;

    g_i2c_fd = sensor.fd;
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(sensor.fd);
        return EXIT_FAILURE;
    }

    if (scd40_start_periodic(&sensor) != 0) {
        fprintf(stderr, "Failed to start periodic measurement.\n");
        fclose(g_log_fp);
        close(sensor.fd);
        return EXIT_FAILURE;
    }

    printf("SCD40 periodic measurement started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        sleep(FIRST_MEAS_DELAY_SEC);

        uint16_t co2;
        float temp, rh;
        if (scd40_read_measurement(&sensor, &co2, &temp, &rh) == 0) {
            log_data(g_log_fp, co2, temp, rh);
            printf("CO2: %u ppm  Temp: %.2f C  RH: %.2f %%\n",
                   co2, temp, rh);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

        /* Sleep in 1 s increments so SIGINT is noticed promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    scd40_stop_periodic(&sensor);
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (sensor.fd >= 0) {
        close(sensor.fd);
        sensor.fd = -1;
    }
    return EXIT_SUCCESS;
}

