/*
 * SCD40 CO2 sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   SCD40 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *   LED anode -> GPIO17 (with ~330 Ω series resistor to GND)
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_reader scd40_reader.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SCD40_I2C_ADDR        0x61
#define I2C_BUS               "/dev/i2c-1"
#define GPIO_LED              17
#define CO2_THRESHOLD         1000
#define BUFFER_SIZE           20
#define SAMPLE_INTERVAL_SEC   5

/* SCD40 command opcodes (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC    0x0010
#define CMD_STOP_PERIODIC     0x0104
#define CMD_READ_MEASUREMENT  0x0202
#define CMD_SOFT_RESET        0x0013

/* SCD40 measurement data word lengths */
#define WORD_LEN_CO2          3   /* 2 data bytes + 1 CRC byte */
#define WORD_LEN_TEMP         3
#define WORD_LEN_HUMID        3

typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static int      g_gpio_fd  = -1;
static bool     g_sensor_started = false;
static circular_buffer_t g_buffer;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void buffer_init(circular_buffer_t *buf)
{
    buf->head  = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t d)
{
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (want %zu, got %zd): %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write byte failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t *data, size_t len)
{
    return i2c_read_bytes(fd, data, len);
}

static int scd40_soft_reset(int fd)
{
    if (i2c_write_cmd(fd, CMD_SOFT_RESET) != 0)
        return -1;
    usleep(10000); /* 10 ms */
    return 0;
}

static int scd40_start_periodic(int fd)
{
    if (i2c_write_cmd(fd, CMD_START_PERIODIC) != 0)
        return -1;
    usleep(2000); /* 2 ms */
    return 0;
}

static int scd40_stop_periodic(int fd)
{
    if (i2c_write_cmd(fd, CMD_STOP_PERIODIC) != 0)
        return -1;
    usleep(2000); /* 2 ms */
    return 0;
}

static int scd40_read_measurement(int fd, uint8_t *buf)
{
    if (i2c_write_cmd(fd, CMD_READ_MEASUREMENT) != 0)
        return -1;
    usleep(2000); /* 2 ms */
    return i2c_read_bytes(fd, buf, 9);
}

static int scd40_read_data(int fd, uint8_t *buf)
{
    if (i2c_write_cmd(fd, CMD_READ_MEASUREMENT) != 0)
        return -1;
    usleep(2000); /* 2 ms */
    return i2c_read_bytes(fd, buf, 9);
}

static int scd40_init(int fd)
{
    if (scd40_soft_reset(fd) != 0) {
        fprintf(stderr, "Soft reset failed.\n");
        return -1;
    }
    usleep(100000); /* 100 ms after reset */

    /* Verify sensor presence by reading the serial number (6 bytes) */
    uint8_t sn[6];
    if (i2c_read_bytes(fd, sn, sizeof(sn)) != 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X.\n", SCD40_I2C_ADDR);
        return -1;
    }
    if (crc8(sn, 2) != sn[2] || crc8(sn + 3, 2) != sn[5]) {
        fprintf(stderr, "CRC mismatch on serial number.\n");
        return -1;
    }
    printf("SCD40 serial number: %02X%02X%02X%02X%02X%02X\n",
           sn[0], sn[1], sn[3], sn[4], sn[6], sn[7]);

    if (scd40_start_periodic(fd) != 0) {
        fprintf(stderr, "Failed to start periodic measurement.\n");
        return -1;
    }
    g_sensor_started = true;
    return 0;
}

static int scd40_read(int fd, sensor_data_t *out)
{
    uint8_t buf[9];
    if (scd40_read_data(fd, buf) != 0)
        return -1;

    /* Validate CRC for each 2-byte data word */
    if (crc8(buf, 2) != buf[2] ||
        crc8(buf + 3, 2) != buf[5] ||
        crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on measurement data.\n");
        return -1;
    }

    uint16_t co2_raw  = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t hum_raw  = ((uint16_t)buf[6] << 8) | buf[7];

    out->co2          = co2_raw;
    out->temperature  = -45.0f + (float)temp_raw / 200.0f;
    out->humidity     = (float)hum_raw / 200.0f;
    return 0;
}

static void print_data(const sensor_data_t *d)
{
    printf("CO2: %u ppm, Temperature: %.2f C, Humidity: %.2f %%RH\n",
           d->co2, d->temperature, d->humidity);
}

static void control_led(int co2_ppm)
{
    int val = (co2_ppm > CO2_THRESHOLD) ? 1 : 0;
    if (val != 0 && val != 1) {
        fprintf(stderr, "Invalid LED state %d\n", val);
        return;
    }
    if (gpioWrite(g_gpio_fd, GPIO_LED, val) < 0)
        fprintf(stderr, "Failed to write GPIO %d: %s\n",
                GPIO_LED, strerror(errno));
}

static void cleanup(void)
{
    if (g_sensor_started) {
        scd40_stop_periodic(g_i2c_fd);
        g_sensor_started = false;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_gpio_fd >= 0) {
        gpioClose(g_gpio_fd);
        g_gpio_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SCD40_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SCD40_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (scd40_init(g_i2c_fd) != 0) {
        fprintf(stderr, "SCD40 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO driver */
    g_gpio_fd = gpioOpen(0);
    if (g_gpio_fd < 0) {
        fprintf(stderr, "Cannot open GPIO driver: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(g_gpio_fd, GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Cannot set GPIO %d as output: %s\n",
                GPIO_LED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(g_gpio_fd, GPIO_LED, 0);

    buffer_init(&g_buffer);

    printf("SCD40 reader started. Sampling every %d s. Press Ctrl+C to stop.\n",
           SAMPLE_INTERVAL_SEC);

    while (g_running) {
        sensor_data_t data;
        if (scd40_read(g_i2c_fd, &data) == 0) {
            buffer_add(&g_buffer, data);
            print_data(&data);
            control_led(data.co2);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

