/*
 * TMP05 temperature monitor for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TMP05 VDD  -> 3.3 V (pin 1)
 *   TMP05 GND  -> GND  (pin 9)
 *   TMP05 OUT  -> GPIO4 (BCM 4, physical pin 7)  [PWM-style output]
 *
 * The TMP05 PWM output is a digital signal whose duty cycle encodes
 * temperature.  A high pulse width proportional to the temperature.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tmp05_monitor tmp05_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./tmp05_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN            4
#define LOG_FILE            "temperature_log.txt"
#define SAMPLE_INTERVAL_S   5
#define EDGE_TIMEOUT_US     50000   /* 50 ms edge wait timeout */
#define MAX_CONSECUTIVE_ERR 3

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                   */
/* ------------------------------------------------------------------ */

static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tm);
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_message(const char *msg)
{
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));

    if (g_log_fp) {
        fprintf(g_log_fp, "%s %s\n", ts, msg);
        fflush(g_log_fp);
    }
    fprintf(stderr, "%s %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* TMP05 measurement                                                  */
/* ------------------------------------------------------------------ */

/*
 * Wait for the GPIO pin to reach the requested level, returning the
 * elapsed microsecond count.  Returns -1 on timeout.
 */
static long wait_for_level(int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    uint32_t now;

    do {
        now = gpioTick();
        if (now - start > timeout_us)
            return -1;
    } while (gpioRead(GPIO_PIN) != level);

    return (long)(now - start);
}

/*
 * Read one TMP05 sample.
 * Returns 0 on success and stores temperature in *out_temp_c.
 * Returns -1 on timeout or invalid duty cycle.
 */
static int read_tmp05(float *out_temp_c)
{
    uint32_t start_tick = gpioTick();

    /* Wait for falling edge (end of low period) */
    long low_us = wait_for_level(0, EDGE_TIMEOUT_US);
    if (low_us < 0) {
        log_message("ERROR: Timeout waiting for falling edge (low period)");
        return -1;
    }

    /* Wait for rising edge (start of high period) */
    long high_us = wait_for_level(1, EDGE_TIMEOUT_US);
    if (high_us < 0) {
        log_message("ERROR: Timeout waiting for rising edge (high period)");
        return -1;
    }

    /* Wait for falling edge (end of high period) */
    long high_end_us = wait_for_level(0, EDGE_TIMEOUT_US);
    if (high_end_us < 0) {
        log_message("ERROR: Timeout waiting for falling edge (high end)");
        return -1;
    }

    uint32_t total_us = high_end_us - start_tick;
    if (total_us == 0) {
        log_message("ERROR: Zero total cycle width");
        return -1;
    }

    uint32_t tl_us = (uint32_t)low_us;
    uint32_t th_us = (uint32_t)high_us;

    /*
     * TMP05 PWM:  duty = TL / (TL + TH)
     * Temperature = duty * 100 °C  (linear scale)
     */
    float duty = (float)tl_us / (float)(tl_us + th_us);
    float temp = duty * 100.0f;

    if (temp < -40.0f || temp > 150.0f) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "ERROR: Temperature out of range: %.2f °C", temp);
        log_message(msg);
        return -1;
    }

    *out_temp_c = temp;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "FATAL: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("FATAL: Cannot open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("INFO: TMP05 monitor started");

    int consecutive_errors = 0;

    while (g_running) {
        float temp_c;

        if (read_tmp05(&temp_c) == 0) {
            consecutive_errors = 0;

            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Temperature: %.2f °C", temp_c);
            log_message(msg);
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERR) {
                log_message("ERROR: Sensor malfunction (consecutive failures)");
                consecutive_errors = 0;  /* reset to avoid spam */
            }
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    /* ---- cleanup ---- */
    log_message("INFO: Shutting down");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

