#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x45
#define MEASURE_CMD_HIGH_REP 0x2400
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define LOG_FILE "environmental_data.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define MEASUREMENT_DELAY_US 15000
#define SAMPLE_INTERVAL_US 5000000
#define GREENHOUSE_DURATION_S 3600

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD_HIGH_REP >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD_HIGH_REP & 0xFF)
    };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t hum_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static float apply_greenhouse_offset(float value, int offset_type) {
    float offset = 0.0f;
    float time_fraction = (float)(gpioTick() % (GREENHOUSE_DURATION_S * 1000000)) / 1000000.0f;
    if (offset_type == 0) {
        offset = 2.0f * sinf(2.0f * M_PI * time_fraction);
    } else if (offset_type == 1) {
        offset = 5.0f * sinf(2.0f * M_PI * time_fraction);
    }
    return value + offset;
}

static void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;
    int retry_count;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        retry_count = 0;
        while (retry_count < RETRY_COUNT && !terminate) {
            if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
                temperature = apply_greenhouse_offset(temperature, 0);
                humidity = apply_greenhouse_offset(humidity, 1);
                log_data(temperature, humidity);
                break;
            } else {
                fprintf(stderr, "Warning: Read failed, retry %d/%d\n", retry_count + 1, RETRY_COUNT);
                retry_count++;
                if (retry_count < RETRY_COUNT) gpioDelay(RETRY_DELAY_US);
            }
        }

        if (retry_count == RETRY_COUNT && !terminate) {
            fprintf(stderr, "Error: All retries exhausted, logging NaN\n");
            log_data(NAN, NAN);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

