/*
 * SDP810-125Pa differential pressure sensor logger for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c
 * Run:    ./sdp810_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x5B          /* SDP810-125Pa default I2C address */

/* SDP810 continuous measurement command (MSB first) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x2F };

/* SDP810 measurement data: 9 bytes (3 words + 3 CRCs) */
#define SDP810_DATA_LEN  9

/* Conversion time per datasheet: ~45 ms for 125 Pa */
#define CONVERSION_MS   45

/* Sampling interval */
#define SAMPLE_MS       1000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0x00) per SDP810 datasheet              */
/* ------------------------------------------------------------------ */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data conversion                                              */
/* ------------------------------------------------------------------ */
static int sdp810_convert(const uint8_t *raw, float *pressure, float *temp)
{
    /* Raw values are 16-bit two's-complement, big-endian */
    int16_t raw_p = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t raw_t = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t raw_s = (int16_t)((raw[6] << 8) | raw[7]);

    /* CRC validation */
    if (sdp_crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (sdp_crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sdp_crc8(&raw[6], 2) != raw[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    /* Scale factor is 0.01 Pa per LSB; raw_s is signed */
    float scale = (float)raw_s * 0.01f;

    /* Pressure: raw_p / scale_factor */
    *pressure = (float)raw_p / scale;

    /* Temperature: raw_t / 200 */
    *temp = (float)raw_t / 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(float pressure, float temperature)
{
    FILE *fp = fopen("airflow.csv", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open airflow.csv: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire sensor address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("SDP810 logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        /* Send continuous measurement command */
        if (i2c_write_cmd(g_i2c_fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
            fprintf(stderr, "Sensor not responding or bus error.\n");
            break;
        }

        /* Wait for conversion to complete */
        struct timespec ts = { CONVERSION_MS / 1000, (CONVERSION_MS % 1000) * 1000000L };
        nanosleep(&ts, NULL);

        /* Read 9-byte measurement block */
        uint8_t raw[SDP810_DATA_LEN];
        if (i2c_read_data(g_i2c_fd, raw, sizeof(raw)) != 0) {
            fprintf(stderr, "Failed to read sensor data.\n");
            break;
        }

        float pressure, temperature;
        if (sdp810_convert(raw, &pressure, &temperature) != 0) {
            fprintf(stderr, "CRC validation failed; skipping sample.\n");
            continue;
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Logging failed.\n");
        }

        /* Sleep for the remainder of the sampling interval */
        struct timespec rem = { 0, (SAMPLE_MS - CONVERSION_MS) * 1000000L };
        nanosleep(&rem, NULL);
    }

    /* Graceful shutdown */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

