/*
 * SHT35 environmental monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   SHT35 VDD  -> Pi 3V3  (pin 1)
 *   SHT35 GND  -> Pi GND  (pin 9)
 *   SHT35 SDA  -> Pi GPIO2 / I2C bus 1 SDA (pin 3)
 *   SHT35 SCL  -> Pi GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht35_monitor sht35_monitor.c
 * Run:    ./sht35_monitor   (user must be in the 'i2c' group or root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT35_ADDR     0x45
#define CSV_FILE       "environment.csv"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MEASURE_DELAY  20         /* ms — datasheet: typ 15 ms */
#define MAX_RETRIES    3

/* SHT35 single-shot, high-repeatability, clock-stretching disabled */
static const uint8_t CMD_MEASURE[2] = { 0x2C, 0x06 };

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8, polynomial 0x31, init 0xFF (Sensirion convention) */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Read temperature and humidity from the SHT35.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int sht35_read(int fd, float *temperature, float *humidity)
{
    uint8_t buf[6];

    /* Issue single-shot measurement command */
    if (write(fd, CMD_MEASURE, sizeof(CMD_MEASURE)) != (ssize_t)sizeof(CMD_MEASURE)) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Datasheet: measurement ready in ~15 ms; wait a bit longer */
    usleep(MEASURE_DELAY * 1000);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                sizeof(buf), n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Validate CRCs */
    if (sht35_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -2;
    }
    if (sht35_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -2;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity   = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int ensure_csv_header(const char *path)
{
    FILE *fp = fopen(path, "r");
    if (fp != NULL) {
        fclose(fp);
        return 0;                       /* file already exists */
    }
    if (errno != ENOENT) {
        fprintf(stderr, "Cannot stat %s: %s\n", path, strerror(errno));
        return -1;
    }

    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Cannot create %s: %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    fclose(fp);
    return 0;
}

static int log_data(const char *path, float temperature, float humidity)
{
    FILE *fp = fopen(path, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SHT35_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Ensure CSV header exists */
    if (ensure_csv_header(CSV_FILE) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SHT35 environmental monitor started. Logging to %s every %d s.\n",
           CSV_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    int consecutive_errors = 0;

    while (g_running) {
        float temperature, humidity;

        int rc = sht35_read(fd, &temperature, &humidity);
        if (rc == 0) {
            consecutive_errors = 0;
            printf("T=%.2f C  RH=%.2f %%\n", temperature, humidity);
            if (log_data(CSV_FILE, temperature, humidity) != 0)
                fprintf(stderr, "Warning: failed to log data.\n");
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read failed (rc=%d).\n", rc);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive errors reached; aborting.\n");
                break;
            }
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (close(fd) != 0)
        fprintf(stderr, "Warning: close(fd) failed: %s\n", strerror(errno));

    return EXIT_SUCCESS;
}

