/*
 * Si7021 greenhouse environmental monitor for Raspberry Pi Zero W.
 *
 * Wiring:
 *   Si7021 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   Si7021 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   Si7021 VDD  -> 3.3 V
 *   Si7021 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse greenhouse.c
 * Run:    ./greenhouse
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_PERIOD_S 5

/* Si7021 commands (8-bit, sent MSB first) */
#define CMD_MEASURE_TEMP_HOLD   0xE3
#define CMD_MEASURE_HUM_HOLD    0xE5
#define CMD_RESET               0xFE
#define CMD_READ_ID_1           0xFA
#define CMD_READ_ID_2           0x0F

/* CRC-8 parameters per Sensirion SHTC3 datasheet */
#define CRC8_POLY  0x31
#define CRC8_INIT  0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor reset                                                        */
/* ------------------------------------------------------------------ */
static int sensor_reset(int fd)
{
    if (i2c_write_cmd(fd, CMD_RESET) == -1)
        return -1;
    usleep(15000); /* datasheet: 15 ms max */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a measurement (hold master mode) with timeout                   */
/* ------------------------------------------------------------------ */
static int read_measurement(int fd, uint8_t cmd, uint16_t *raw)
{
    if (i2c_write_cmd(fd, cmd) == -1)
        return -1;

    uint8_t buf[3];
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    const long timeout_ns = (long)POLL_TIMEOUT_MS * 1000000L;

    for (;;) {
        if (i2c_read_bytes(fd, buf, sizeof(buf)) == 0)
            break;

        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ns = (now.tv_sec - start.tv_sec) * 1000000000L
                        + (now.tv_nsec - start.tv_nsec);
        if (elapsed_ns >= timeout_ns) {
            fprintf(stderr, "Timeout waiting for measurement (cmd 0x%02X)\n", cmd);
            return -1;
        }
        usleep(1000); /* 1 ms poll interval */
    }

    /* CRC covers the two data bytes; the third byte is the CRC itself */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on measurement (cmd 0x%02X)\n", cmd);
        return -1;
    }

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature (°C)                                               */
/* ------------------------------------------------------------------ */
static int read_temperature(int fd, float *temp)
{
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_TEMP_HOLD, &raw) == -1)
        return -1;
    *temp = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read relative humidity (%)                                          */
/* ------------------------------------------------------------------ */
static int read_humidity(int fd, float *hum)
{
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_HUM_HOLD, &raw) == -1)
        return -1;
    *hum = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*hum < 0.0f)   *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *ts, float temp, float hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fclose(fp);
    return 0;
}

static int log_error(const char *ts, const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify sensor presence with a soft reset */
    if (sensor_reset(g_i2c_fd) == -1) {
        fprintf(stderr, "Sensor not responding at 0x%02X — check wiring.\n",
                SI7021_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Optional: read device ID (0xFA 0x0F) for diagnostics */
    (void)i2c_write_cmd(g_i2c_fd, CMD_READ_ID_1);
    (void)i2c_write_cmd(g_i2c_fd, CMD_READ_ID_2);
    uint8_t id_buf[8];
    (void)i2c_read_bytes(g_i2c_fd, id_buf, sizeof(id_buf));

    /* Write CSV header if file is empty */
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
            fclose(fp);
        }
    } else {
        fclose(fp);
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (read_temperature(g_i2c_fd, &temp) == -1 ||
            read_humidity(g_i2c_fd, &hum) == -1) {
            fprintf(stderr, "%s — Sensor read error — resetting.\n", ts);
            (void)sensor_reset(g_i2c_fd);
            sleep(1);
            continue;
        }

        if (log_data(ts, temp, hum) == -1)
            fprintf(stderr, "%s — Logging failed.\n", ts);
        else
            printf("%s  T=%.2f °C  RH=%.2f %%\n", ts, temp, hum);

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

