/*
 * SDP810-500Pa differential pressure & temperature logger
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL), address 0x5B
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -li2c
 *
 * The SDP810 continuously measures differential pressure and temperature
 * and outputs 9 bytes:  [P_msb P_lsb P_crc T_msb T_lsb T_crc S1 S2 S3]
 *   P = (raw_pressure / 65536) * scale_factor  (Pa)
 *   T = (raw_temperature / 65536) * scale_factor  (°C)
 * CRC-8 polynomial 0x31, init 0x00, no final XOR.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x5B
#define MEASURE_CMD    0x361F   /* continuous measurement, no averaging */
#define CONV_TIME_US   20000   /* 20 ms worst-case conversion time */
#define SAMPLE_PERIOD  1000000 /* 1 s between samples */
#define LOG_FILE       "airflow.dat"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0x00, no final XOR */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Write a 16-bit command to the SDP810.
 * Returns 0 on success, -1 on error.
 */
static int sdp_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the SDP810.
 * Returns 0 on success, -1 on error.
 */
static int sdp_read_data(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/*
 * Read one sample from the SDP810.
 * Returns 0 on success, -1 on error.
 */
static int sdp_read_sample(int fd, float *pressure, float *temperature)
{
    if (sdp_write_cmd(fd, MEASURE_CMD) != 0)
        return -1;

    usleep(CONV_TIME_US);

    uint8_t data[9];
    if (sdp_read_data(fd, data, sizeof(data)) != 0)
        return -1;

    /* CRC checks */
    if (sdp_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (sdp_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);

    /* Scale factor bytes S1..S3 are the last three bytes */
    uint16_t scale = (uint16_t)((data[6] << 8) | data[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale;
    *temperature = (float)raw_temperature / (float)scale;
    return 0;
}

int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Open log file once and keep it open across samples */
    FILE *fp = fopen(LOG_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP810 airflow logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (sdp_read_sample(fd, &pressure, &temperature) != 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            if (fwrite(&pressure,    sizeof(float), 1, fp) != 1 ||
                fwrite(&temperature, sizeof(float), 1, fp) != 1) {
                fprintf(stderr, "File write failed: %s\n", strerror(errno));
                break;
            }
            fflush(fp);
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int ms = 0; ms < SAMPLE_PERIOD / 100000 && g_running; ms += 100)
            usleep(100000);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

