#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_I2C_ADDR 0x25
#define LOG_FILE "pressure_log.txt"
#define MEASUREMENT_INTERVAL 5
#define CONVERSION_TIME_MS 45

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp800(int handle, float *pressure) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(CONVERSION_TIME_MS * 1000);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from I2C device.\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC8 mismatch on pressure data word.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC8 mismatch on temperature data word.\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC8 mismatch on scale factor data word.\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t raw_scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

