/*
 * LPS33HW pressure & temperature logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   LPS33HW SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   LPS33HW SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   LPS33HW VDD  -> 3.3 V
 *   LPS33HW GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o lps33hw_logger lps33hw_logger.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LPS33HW register map (datasheet rev 1.0) ---- */
#define LPS33HW_I2C_ADDR        0x5C   /* SA0 tied to GND */
#define WHO_AM_I_REG            0x0F
#define WHO_AM_I_VAL            0xB1
#define CTRL_REG1               0x20
#define CTRL_REG2               0x21
#define PRESS_OUT_XL            0x28
#define TEMP_OUT_L              0x2B

#define LOG_FILE_NAME           "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC     1
#define I2C_BUS                 "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X = 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LPS33HW sensor driver ---- */

typedef struct {
    int fd;
    int16_t  press_raw;
    int16_t  temp_raw;
    int      who_am_i;
} lps33hw_t;

static int lps33hw_init(lps33hw_t *s)
{
    s->fd = open(I2C_BUS, O_RDWR);
    if (s->fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(s->fd, I2C_SLAVE, LPS33HW_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LPS33HW_I2C_ADDR, strerror(errno));
        close(s->fd);
        s->fd = -1;
        return -1;
    }

    /* Verify device identity */
    uint8_t who;
    if (i2c_read_reg8(s->fd, WHO_AM_I_REG, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        close(s->fd);
        s->fd = -1;
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        close(s->fd);
        s->fd = -1;
        return -1;
    }
    s->who_am_i = who;

    /* CTRL_REG1: PD=1 (power on), ODR=10 (1 Hz) */
    if (i2c_write_reg8(s->fd, CTRL_REG1, 0x41) != 0) {
        close(s->fd);
        s->fd = -1;
        return -1;
    }

    /* CTRL_REG2: reset FIFO, BDU enabled */
    if (i2c_write_reg8(s->fd, CTRL_REG2, 0x04) != 0) {
        close(s->fd);
        s->fd = -1;
        return -1;
    }

    return 0;
}

static void lps33hw_cleanup(lps33hw_t *s)
{
    if (s->fd >= 0) {
        /* Put sensor in standby (PD=0) before closing */
        (void)i2c_write_reg8(s->fd, CTRL_REG1, 0x00);
        close(s->fd);
        s->fd = -1;
    }
}

static int lps33hw_read(lps33hw_t *s)
{
    uint8_t p[3], t[2];

    if (i2c_read_reg8(s->fd, PRESS_OUT_XL, &p[0]) != 0) return -1;
    if (i2c_read_reg8(s->fd, PRESS_OUT_XL + 1, &p[1]) != 0) return -1;
    if (i2c_read_reg8(s->fd, PRESS_OUT_XL + 2, &p[2]) != 0) return -1;
    if (i2c_read_reg8(s->fd, TEMP_OUT_L, &t[0]) != 0) return -1;
    if (i2c_read_reg8(s->fd, TEMP_OUT_L + 1, &t[1]) != 0) return -1;

    s->press_raw = (int16_t)((p[2] << 8) | (p[1] << 8) | p[0]);
    s->temp_raw  = (int16_t)((t[1] << 8) | t[0]);
    return 0;
}

/* ---- Logging ---- */

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp) {
        fprintf(fp, "%s, ERROR: %s\n", ts, msg);
        fflush(fp);
        fclose(fp);
    }
    fprintf(stderr, "%s, ERROR: %s\n", ts, msg);
}

static void log_data(const lps33hw_t *s)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (!fp) {
        log_error("Cannot open log file");
        return;
    }

    float temp_c = (float)s->temp_raw / 100.0f;
    float press_hpa = (float)s->press_raw / 4096.0f;

    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f C\n",
            ts, press_hpa, temp_c);
    fflush(fp);
    fclose(fp);
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    lps33hw_t sensor;
    memset(&sensor, 0, sizeof(sensor));
    sensor.fd = -1;

    if (lps33hw_init(&sensor) != 0) {
        fprintf(stderr, "LPS33HW initialization failed.\n");
