/*
 * Raspberry Pi Zero W — STLM75 temperature monitor with LED indicator.
 *
 * Wiring:
 *   STLM75 SDA  -> GPIO2  (I2C bus 1, pin 3)
 *   STLM75 SCL  -> GPIO3  (I2C bus 1, pin 5)
 *   STLM75 VDD  -> 3.3 V
 *   STLM75 GND  -> GND
 *   LED anode   -> GPIO17 (pin 11) via 330 Ω resistor
 *   LED cathode -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o stlm75_monitor stlm75_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./stlm75_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1          /* /dev/i2c-1 on Raspberry Pi Zero W */
#define STLM75_ADDR         0x48       /* STLM75 default 7-bit address      */
#define STLM75_REG_TEMP     0x00       /* Temperature data register         */
#define STLM75_REG_CONFIG   0x01       /* Configuration register            */
#define STLM75_REG_HEATER   0x02       /* Heater control register           */

#define LED_GPIO            17         /* BCM 17                            */
#define TEMP_THRESHOLD      28.0f      /* °C                                */
#define BUFFER_SIZE         10
#define SAMPLE_PERIOD_US    1000000    /* 1 second                          */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Circular buffer ----------------------------- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C helpers ----------------------------- */
/*
 * Open the I2C bus and configure the STLM75 for continuous conversion.
 * Returns 0 on success, -1 on failure.
 */
static int initialize_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d).\n", g_i2c_handle);
        return -1;
    }

    /*
     * STLM75 configuration register (0x01):
     *   Bit 7 = 0  — continuous conversion mode
     *   Bit 6 = 0  — 1 Hz conversion rate (power-down mode)
     *   Bit 5 = 0  — 0.5°C resolution
     *   Bit 4 = 0  — 0.5°C resolution
     *   Bit 3 = 0  — 0.5°C resolution
     *   Bit 2 = 0  — 0.5°C resolution
     *   Bit 1 = 0  — 0.5°C resolution
     *   Bit 0 = 0  — 0.5°C resolution
     * Value = 0x00.
     */
    if (i2cWriteByteData(g_i2c_handle, STLM75_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write STLM75 config register.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /*
     * Heater control register (0x02):
     *   Bit 7 = 0  — heater disabled
     *   Bit 6 = 0  — heater disabled
     *   Bit 5 = 0  — heater disabled
     *   Bit 4 = 0  — heater disabled
     *   Bit 3 = 0  — heater disabled
     *   Bit 2 = 0  — heater disabled
     *   Bit 1 = 0  — heater disabled
     *   Bit 0 = 0  — heater disabled
     * Value = 0x00.
     */
    if (i2cWriteByteData(g_i2c_handle, STLM75_REG_HEATER, 0x00) < 0) {
        fprintf(stderr, "Warning: failed to write STLM75 heater register.\n");
    }

    return 0;
}

/*
 * Read the temperature from the STLM75.
 * Returns 0 on success and stores the temperature in *out_temp_c,
 * returns -1 on I2C failure.
 */
static int read_temperature(float *out_temp_c)
{
    int raw = i2cReadWordData(g_i2c_handle, STLM75_REG_TEMP);
    if (raw < 0) {
        fprintf(stderr, "Error: i2cReadWordData failed (pigpio error %d).\n", raw);
        return -1;
    }

    /*
     * pigpio returns the word as (high_byte << 8) | low_byte.
     * The STLM75 sends the temperature as two's-complement 16-bit
     * data in big-endian order.
     */
    int16_t raw16 = (int16_t)((raw & 0xFF00) >> 8) | (int16_t)((raw & 0x00FF) << 8);
    *out_temp_c = (float)raw16 / 256.0f;
    return 0;
}

/* ------------------------------- LED control ----------------------------- */
static void control_led(float average_temp)
{
    int level = (average_temp > TEMP_THRESHOLD) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed on GPIO %d.\n", LED_GPIO);
    }
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);  /* ensure LED is off at start */

    /* --- Initialize I2C --- */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Circular buffer --- */
    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    /* --- Main loop --- */
    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            cb_add(&temp_buffer, temperature);
            float avg = cb_average(&temp_buffer);
            control_led(avg);
            printf("Temperature: %.2f °C | Average: %.2f °C | LED: %s\n",
                   temperature, avg,
                   (avg > TEMP_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Skipping sample due to I2C read failure.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

