/*
 * air_quality.c — SCD30 CO2 / temperature / humidity logger with ventilation control.
 *
 * Build:  gcc -O2 -Wall -Wextra -o air_quality air_quality.c -lgpiod
 *
 * Hardware: Raspberry Pi 4 Model B, SCD30 on I2C bus 1 (SDA=GPIO2, SCL=GPIO3).
 *
 * Behaviour:
 *   - Samples every 5 s.
 *   - Logs CSV lines:  <timestamp>,<co2_ppm>,<temp_c>,<rh_pct>
 *   - Ventilation OFF  below 800 ppm
 *   - Ventilation LOW   800–1199 ppm
 *   - Ventilation HIGH  1200 ppm or above
 *   - On I2C / sensor errors the program logs the error and continues.
 *   - SIGINT / SIGTERM triggers a graceful shutdown.
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

