#define SCD30_CMD_START       0x0010
#define SCD30_CMD_STOP        0x0104
#define SCD30_CMD_READ        0x0202
#define SCD30_CMD_SOFT_RESET  0xD304
#define SCD30_MEAS_READY      0x001D
#define SCD30_MEAS_INTERVAL   5          /* seconds */
#define SCD30_MEAS_INTERVAL_H 0x0005
#define SCD30_MEAS_INTERVAL_L 0x0000
#define SCD30_MEAS_INTERVAL_REG 0x4600
#define SCD30_DATA_READY_REG  0x0300
#define SCD30_DATA_READY_LEN  3
#define SCD30_DATA_LEN        9          /* 3 words: CO2, T, RH */

#define VENT_OFF  0
#define VENT_LOW  1
#define VENT_HIGH 2

