#define GPIO_CHIP_NAME  "gpiochip4"   /* BCM2711/BCM2836 on Pi 4/5 */
#define GPIO_VENT_PIN   17            /* BCM17 */

/* ---- Globals ------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log    = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_vent = NULL;

/* ---- Signal handling ---------------------------------------------------- */
static void on_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ---- I2C helpers -------------------------------------------------------- */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write(0x%04X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- SCD30 CRC4 --------------------------------------------------------- */
static uint8_t scd30_crc4(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- SCD30 low-level helpers -------------------------------------------- */
static int scd30_soft_reset(void)
{
    if (i2c_write_cmd(g_i2c_fd, SCD30_CMD_SOFT_RESET) == -1)
        return -1;
    usleep(2000);                       /* datasheet: max 1 ms */
    return 0;
}

static int scd30_stop_periodic(void)
{
    return i2c_write_cmd(g_i2c_fd, SCD30_CMD_STOP);
}

static int scd30_start_periodic(void)
{
    if (i2c_write_cmd(g_i2c_fd, SCD30_CMD_START) == -1)
        return -1;
    usleep(2000);                       /* datasheet: max 1 ms */
    return 0;
}

static int scd30_set_interval(uint16_t interval)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(SCD30_MEAS_INTERVAL_REG >> 8);
    buf[1] = (uint8_t)(SCD30_MEAS_INTERVAL_REG & 0xFF);
    buf[2] = (uint8_t)(interval & 0xFF);
    if (write(g_i2c_fd, buf, 3) != 3) {
        fprintf(stderr, "set_interval write failed: %s\n", strerror(errno));
        return -1;
