        return -1;
    if (scd30_crc4(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on data-ready word\n");
        return -1;
    }
    *ready = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int scd30_read_measurement(uint16_t *co2, float *temp, float *rh)
{
    uint8_t cmd[2] = { (uint8_t)(SCD30_CMD_READ >> 8),
                       (uint8_t)(SCD30_CMD_READ & 0xFF) };
    if (write(g_i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "read_measurement write failed: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[SCD30_DATA_LEN];
    if (i2c_read_block(g_i2c_fd, buf, SCD30_DATA_LEN) == -1)
        return -1;

    /* Validate CRC for each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (scd30_crc4(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    *co2  = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t t_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw = ((uint16_t)buf[6] << 8) | buf[7];

