    fprintf(g_log, "%s,ERROR,%s\n", ts, msg);
    fflush(g_log);
}

/* ---- Ventilation control ------------------------------------------------ */
static int vent_set(int state)
{
    if (g_vent) {
        int v = (state == VENT_HIGH) ? 1 : 0;
