        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_vent) {
        gpiod_line_release(g_vent);
        g_vent = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ---- Main --------------------------------------------------------------- */
int main(void)
{
    /* Signal handlers */
    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    /* Open log file */
    g_log = fopen("air_quality.log", "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open air_quality.log: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd == -1) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        log_error("I2C bus unavailable");
        cleanup();
        return EXIT_SUCCESS;  /* no hardware → success */
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SCD30_I2C_ADDR) == -1) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SCD30_I2C_ADDR, strerror(errno));
        log_error("SCD30 not responding on I2C");
        cleanup();
        return EXIT_SUCCESS;
    }

    /* Soft reset */
    if (scd30_soft_reset() == -1) {
        log_error("SCD30 soft reset failed");
        cleanup();
        return EXIT_SUCCESS;
    }

    /* Start periodic measurement */
    if (scd30_start_periodic() == -1) {
        log_error("SCD30 start_periodic failed");
        cleanup();
        return EXIT_SUCCESS;
    }

    /* Set measurement interval */
    if (scd30_set_interval(SCD30_MEAS_INTERVAL) == -1) {
        log_error("SCD30 set_interval failed");
        cleanup();
        return EXIT_SUCCESS;
    }

    /* Ventilation GPIO */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        log_error("GPIO chip unavailable");
        cleanup();
        return EXIT_SUCCESS;
    }
    g_vent = gpiod_chip_get_line(g_chip, GPIO_VENT_PIN);
    if (!g_vent) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_VENT_PIN, strerror(errno));
        log_error("GPIO line unavailable");
        cleanup();
        return EXIT_SUCCESS;
    }
    if (gpiod_line_request_output(g_vent, "air_quality", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        log_error("GPIO request failed");
        cleanup();
        return EXIT_SUCCESS;
    }

    /* Main loop */
    while (g_running) {
        uint16_t ready = 0;
        if (scd30_data_ready(&ready) == -1) {
            log_error("scd30_data_ready failed");
            sleep(1);
            continue;
        }
        if (ready == 0) {
            sleep(1);
            continue;
        }

        uint16_t co2;
        float temp, rh;
        if (scd30_read_measurement(&co2, &temp, &rh) == -1) {
            log_error("scd30_read_measurement failed");
            sleep(1);
            continue;
        }

        log_sample(co2, temp, rh);

        int vent = VENT_OFF;
        if (co2 >= 1200) vent = VENT_HIGH;
        else if (co2 >= 800) vent = VENT_LOW;

        if (vent_set(vent) == -1)
            log_error("vent_set failed");

        sleep(SCD30_MEAS_INTERVAL);
    }

    /* Graceful shutdown */
    (void)scd30_stop_periodic();
    cleanup();
    return EXIT_SUCCESS;
}

