            sleep(1);
            continue;
        }
        if (ready == 0) {
            sleep(1);
            continue;
        }

        uint16_t co2;
        float temp, rh;
        if (scd30_read_measurement(&co2, &temp, &rh) == -1) {
            log_error("scd30_read_measurement failed");
            sleep(1);
            continue;
        }

        log_sample(co2, temp, rh);

        int vent = VENT_OFF;
        if (co2 >= 1200) vent = VENT_HIGH;
        else if (co2 >= 800) vent = VENT_LOW;

        if (vent_set(vent) == -1)
            log_error("vent_set failed");

        sleep(SCD30_MEAS_INTERVAL);
    }

    /* Graceful shutdown */
    (void)scd30_stop_periodic();
    cleanup();
    return EXIT_SUCCESS;
}

