#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SDP32_ADDR 0x25
#define SDP32_READ_MEASUREMENT 0x36
#define SDP32_SCALE_FACTOR 0x89
#define SDP32_SCALE_FACTOR_READ 0x36
#define SDP32_SCALE_FACTOR_WRITE 0x77
#define SDP32_SCALE_FACTOR_DEFAULT 32768.0f
#define SDP32_SCALE_FACTOR_MIN 100.0f
#define SDP32_SCALE_FACTOR_MAX 100000.0f
#define SDP32_PRESSURE_SCALE 0.0001f
#define SDP32_TEMPERATURE_SCALE 0.01f
#define SDP32_CRC8_POLYNOMIAL 0x31
#define SDP32_CRC8_INIT 0xFF
#define I2C_BUS 1
#define DEFAULT_INTERVAL_MS 1000
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = SDP32_CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ SDP32_CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int sdp32_write_command(int handle, uint8_t cmd) {
    char buf[1] = { (char)cmd };
    int rc = i2cWriteDevice(handle, buf, 1);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int sdp32_read_bytes(int handle, uint8_t *buf, int len) {
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "Error: i2cReadDevice expected %d bytes, got %d: %s\n", len, rc, strerror(errno));
        return -1;
    }
    return 0;
}

static int sdp32_read_measurement(int handle, float *pressure, float *temperature) {
    uint8_t buf[9];
    if (sdp32_write_command(handle, SDP32_READ_MEASUREMENT) < 0)
        return -1;
    gpioDelay(2000);
    if (sdp32_read_bytes(handle, buf, 9) < 0)
        return -1;
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Scale factor CRC mismatch\n");
        return -1;
    }
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);
    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0)\n");
        return -1;
    }
    *pressure = (float)raw_pressure / scale_factor * SDP32_PRESSURE_SCALE;
    *temperature = (float)raw_temperature / scale_factor * SDP32_TEMPERATURE_SCALE;
    return 0;
}

static int sdp32_set_scale_factor(int handle, float scale_factor) {
    if (scale_factor < SDP32_SCALE_FACTOR_MIN || scale_factor > SDP32_SCALE_FACTOR_MAX) {
        fprintf(stderr, "Error: Scale factor %.2f out of range [%.1f, %.1f]\n", scale_factor, SDP32_SCALE_FACTOR_MIN, SDP32_SCALE_FACTOR_MAX);
        return -1;
    }
    uint8_t buf[3];
    buf[0] = (uint8_t)(scale_factor / 256.0f);
    buf[1] = (uint8_t)(scale_factor / 256.0f);
    buf[2] = (uint8_t)(scale_factor / 256.0f);
    if (sdp32_write_command(handle, SDP32_SCALE_FACTOR_WRITE) < 0)
        return -1;
    gpioDelay(2000);
    if (sdp32_write_command(handle, SDP32_SCALE_FACTOR_READ) < 0)
        return -1;
    gpioDelay(2000);
    uint8_t read_buf[3];
    if (sdp32_read_bytes(handle, read_buf, 3) < 0)
        return -1;
    if (crc8(read_buf, 2) != read_buf[2]) {
        fprintf(stderr, "Error: Scale factor read CRC mismatch\n");
        return -1;
    }
    int16_t read_scale = (int16_t)((read_buf[0] << 8) | read_buf[1]);
    if (read_scale != (int16_t)scale_factor) {
        fprintf(stderr, "Error: Scale factor write failed (expected %.2f, got %d)\n", scale_factor, read_scale);
        return -1;
    }
    return 0;
}

static void print_timestamp(void) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s] ", ts);
}

int main(int argc, char *argv[]) {
    int interval_ms = DEFAULT_INTERVAL_MS;
    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Error: Interval must be a positive integer\n");
            return 1;
        }
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d): %s\n", g_i2c_handle, strerror(errno));
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    float scale_factor = SDP32_SCALE_FACTOR_DEFAULT;
    if (sdp32_set_scale_factor(g_i2c_handle, scale_factor) < 0) {
        fprintf(stderr, "Error: Failed to set scale factor %.2f\n", scale_factor);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("SDP32 reader started on I2C bus %d, addr 0x%02X, interval %d ms\n", I2C_BUS, SDP32_ADDR, interval_ms);
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sdp32_read_measurement(g_i2c_handle, &pressure, &temperature) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Warning: Read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
        if (success) {
            print_timestamp();
            printf("Pressure: %.4f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            print_timestamp();
            fprintf(stderr, "Error: Failed to read sensor after %d attempts\n", MAX_RETRIES);
        }
        if (g_running)
            gpioDelay(interval_ms * 1000);
    }
    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

