/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   SDP810 SCL  -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810 sdp810.c -lpigpio -lrt
 * Run:    sudo ./sdp810
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP810_ADDR    0x5C          /* SDP810-125Pa default I2C address */

/* SDP810 command bytes (MSB first) */
#define CMD_TRIGGER    0x36          /* single-shot measurement, no averaging */
#define CMD_READ_ID    0x78          /* returns 9 bytes: 3 words + 3 CRCs */

/* Timing (microseconds) */
#define TRIGGER_DELAY_US  45000       /* 45 ms conversion time */
#define LOOP_DELAY_US     1000000     /* 1 s between samples */

/* Globals for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* CRC-8 calculation (Sensirion: poly 0x31, init 0xFF, no final XOR)   */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 9 bytes from the SDP810 and parse into pressure, temperature,  */
/* and scale-factor words.  Returns 0 on success, -1 on error.        */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[9];
    int16_t raw_pressure, raw_temperature, raw_scale_factor;

    /* Trigger a single-shot measurement */
    if (i2cWriteByte(handle, CMD_TRIGGER) < 0) {
        fprintf(stderr, "[ERROR] I2C write failed (trigger command)\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(TRIGGER_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(2)+crc */
    int n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "[ERROR] I2C read failed: expected 9 bytes, got %d\n", n);
        return -1;
    }

    /* CRC validation */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Scale-factor CRC mismatch\n");
        return -1;
    }

    /* Convert raw values (big-endian, signed 16-bit) */
    raw_pressure        = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature     = (int16_t)((buf[3] << 8) | buf[4]);
    raw_scale_factor    = (int16_t)((buf[6] << 8) | buf[7]);

    /* SDP810-125Pa: pressure [Pa] = raw / scale_factor */
    *pressure    = (float)raw_pressure / (float)raw_scale_factor;
    *temperature = (float)raw_temperature / 200.0f;   /* [°C] */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — closes I2C and terminates pigpio                 */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the SDP810 address */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d). "
                        "Check wiring and that the sensor is present.\n",
                        g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810-125Pa reader started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] Read failed — continuing.\n");
        }

        /* Sleep 1 s, but wake early if a signal arrives */
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

