#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define HDC1000_TEMP_REG    0x00
#define HDC1000_HUM_REG     0x01
#define HDC1000_CONFIG_REG  0x02
#define HDC1000_RESET_REG   0x07

#define I2C_BUS             "/dev/i2c-1"
#define CONV_DELAY_MS       20
#define LOOP_DELAY_MS       5000

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, val, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    uint8_t buf[2];
    n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg16: read reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int hdc1000_init(int fd)
{
    /* Software reset */
    if (i2c_write_reg8(fd, HDC1000_RESET_REG, 0x00) < 0)
        return -1;
    usleep(15000); /* 15 ms reset settling */

    /* 14-bit temp + 14-bit humidity, heater off, mode = temp+hum */
    if (i2c_write_reg8(fd, HDC1000_CONFIG_REG, 0x1000) < 0)
        return -1;
    return 0;
}

static int hdc1000_read(int fd, float *temp, float *hum)
{
    /* Trigger a single conversion */
    if (i2c_write_reg8(fd, HDC1000_CONFIG_REG, 0x1000) < 0)
        return -1;

    usleep(CONV_DELAY_MS * 1000);

    uint16_t raw_t, raw_h;
    if (i2c_read_reg16(fd, HDC1000_TEMP_REG, &raw_t) < 0)
        return -1;
    if (i2c_read_reg16(fd, HDC1000_HUM_REG, &raw_h) < 0)
        return -1;

    *temp = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *hum  = ((float)raw_h / 65536.0f) * 100.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    if (hdc1000_init(g_fd) < 0) {
        fprintf(stderr, "HDC1000 initialization failed (sensor absent or bus error)\n");
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s (addr 0x%02X). Logging every %d ms.\n",
           I2C_BUS, HDC1000_ADDR, LOOP_DELAY_MS);

    while (g_running) {
        float temp, hum;
        if (hdc1000_read(g_fd, &temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read HDC1000 data\n");
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    return EXIT_SUCCESS;
}

