/*
 * MLX90833 absolute pressure reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX90833 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90833 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90833 VDD  -> 3.3 V
 *   MLX90833 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90833 mlx90833.c -li2c
 * Run:    ./mlx90833
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90833_ADDR  0x50          /* MLX90833 default I2C address */

/* MLX90833 register addresses (16-bit, big-endian on the bus) */
#define REG_DEVICE_ID   0x0000
#define REG_PRESSURE    0x0002
#define REG_CONFIG      0x0004
#define REG_STATUS      0x0006

/* Expected device ID for the MLX90833 (16-bit, big-endian) */
#define EXPECTED_DEV_ID 0x9083

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/* Write a 16-bit register address + 16-bit data payload. */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)(value >> 8);
    buf[3] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register (big-endian on the bus). */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t data[2];
    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    uint16_t dev_id = 0;

    /* Read the device ID register to confirm the sensor is present. */
    if (i2c_read_reg16(fd, REG_DEVICE_ID, &dev_id) == -1) {
        fprintf(stderr, "Cannot read DEVICE_ID — sensor may be absent.\n");
        return -1;
    }

    if (dev_id != EXPECTED_DEV_ID) {
        fprintf(stderr,
                "Unexpected DEVICE_ID: 0x%04X (expected 0x%04X).\n",
                dev_id, EXPECTED_DEV_ID);
        return -1;
    }

    printf("MLX90833 detected (DEVICE_ID = 0x%04X).\n", dev_id);

    /*
     * Optional configuration: enable continuous conversion mode.
     * The MLX90833 defaults to continuous mode upon power-up, but
     * we write it explicitly for clarity.
     */
    if (i2c_write_reg16(fd, REG_CONFIG, 0x0001) == -1) {
        fprintf(stderr, "Warning: failed to write CONFIG register.\n");
        /* Non-fatal: continue anyway. */
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Pressure reading                                                   */
/* ------------------------------------------------------------------ */
static int read_pressure(int fd, float *pressure)
{
    uint16_t raw = 0;

    if (i2c_read_reg16(fd, REG_PRESSURE, &raw) == -1) {
        return -1;
    }

    /*
     * The MLX90833 pressure register contains a 16-bit value.
     * The exact conversion depends on the specific variant and
     * the calibration data stored in EEPROM.  For the generic
     * 16-bit register, we assume a linear relationship.
     *
     * Here we scale the raw value by 0.1 Pa per LSB for demonstration
     * purposes.  Replace the constants with the actual calibration
     * values from your specific MLX90833 variant.
     */
    *pressure = (float)raw * 0.1f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main loop                                                           */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() == -1) {
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MLX90833_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MLX90833_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) == -1) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Starting pressure readings every 500 ms. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure = 0.0f;

        if (read_pressure(g_i2c_fd, &pressure) == -1) {
            fprintf(stderr, "Failed to read pressure.\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            } else {
                snprintf(ts, sizeof(ts), "unknown-time");
            }

            printf("[%s] Pressure: %.2f Pa\n", ts, pressure);
        }

        /* Sleep 500 ms, but wake early if a signal arrives. */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(10000); /* 10 ms */
        }
    }

    printf("\nExiting gracefully.\n");

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

