/*
 * Raspberry Pi Zero W – TDK ICP-10101 barometric pressure sensor reader
 *
 * Wiring:
 *   ICP-10101 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   ICP-10101 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   ICP-10101 VDD  -> 3.3 V
 *   ICP-10101 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10101 icp10101.c -li2c
 * Run:    ./icp10101
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10101_ADDR  0x40

/* ICP-10101 register addresses (16-bit, big-endian on the bus) */
#define REG_MEASURE    0x00
#define REG_RESET      0x40
#define REG_CONFIG     0x60
#define REG_TEMP_MSB   0x20
#define REG_TEMP_LSB   0x21
#define REG_PRESS_MSB  0x22
#define REG_PRESS_LSB  0x23
#define REG_STATUS     0x24

/* Default values returned by the sensor when not configured */
#define DEFAULT_TEMP_MSB 0x00
#define DEFAULT_TEMP_LSB 0x00
#define DEFAULT_PRESS_MSB 0x00
#define DEFAULT_PRESS_LSB 0x00

/* Measurement command: pressure + temperature, 1x oversampling */
#define MEASURE_CMD 0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the sensor (no data payload).            */
static int i2c_write_cmd(int fd, uint8_t reg)
{
    uint8_t buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write_cmd(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes starting at `reg` (16-bit address).               */
static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write_addr(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read(0x%02X, %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and wait for the conversion to complete.     */
static int trigger_measurement(int fd)
{
    if (i2c_write_cmd(fd, REG_MEASURE) != 0)
        return -1;
    usleep(7000); /* 7 ms conversion time */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reset the sensor.                                                   */
static int reset_sensor(int fd)
{
    if (i2c_write_cmd(fd, REG_RESET) != 0)
        return -1;
    usleep(2000); /* 2 ms reset recovery */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the sensor: pressure oversampling x1, temp x1, 1x.        */
static int configure_sensor(int fd)
{
    /* 0x00 = 1x oversampling for pressure, 1x for temperature */
    uint8_t config[2] = { REG_CONFIG, 0x00 };
    if (write(fd, config, 2) != 2) {
        fprintf(stderr, "I2C config write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature in degrees Celsius.                                */
static int read_temperature(int fd, float *temp)
{
    uint8_t buf[2];
    if (i2c_read_bytes(fd, REG_TEMP_MSB, buf, 2) != 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = (float)raw / 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure in Pascals.                                          */
static int read_pressure(int fd, float *press)
{
    uint8_t buf[2];
    if (i2c_read_bytes(fd, REG_PRESS_MSB, buf, 2) != 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *press = (float)raw / 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

/* ------------------------------------------------------------------ */
static bool is_default_data(uint8_t t_msb, uint8_t t_lsb,
                            uint8_t p_msb, uint8_t p_lsb)
{
    return (t_msb == DEFAULT_TEMP_MSB && t_lsb == DEFAULT_TEMP_LSB &&
            p_msb == DEFAULT_PRESS_MSB && p_lsb == DEFAULT_PRESS_LSB);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ICP10101_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (reset_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor reset failed – check wiring and address.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (configure_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor configuration failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ICP-10101 initialized on %s (addr 0x%02X).\n",
           I2C_BUS, ICP10101_ADDR);
    fflush(stdout);

    while (g_running) {
        if (trigger_measurement(g_i2c_fd) != 0) {
            fprintf(stderr, "Measurement trigger failed.\n");
            sleep(5);
            continue;
        }

        float temperature, pressure;
        if (read_temperature(g_i2c_fd, &temperature) != 0) {
            fprintf(stderr, "Temperature read failed.\n");
            sleep(5);
            continue;
        }
        if (read_pressure(g_i2c_fd, &pressure) != 0) {
            fprintf(stderr, "Pressure read failed.\n");
            sleep(5);
            continue;
        }

        uint8_t t_msb, t_lsb, p_msb, p_lsb;
        if (i2c_read_bytes(g_i2c_fd, REG_TEMP_MSB, &t_msb, 1) != 0 ||
            i2c_read_bytes(g_i2c_fd, REG_TEMP_LSB, &t_lsb, 1) != 0 ||
            i2c_read_bytes(g_i2c_fd, REG_PRESS_MSB, &p_msb, 1) != 0 ||
            i2c_read_bytes(g_i2c_fd, REG_PRESS_LSB, &p_lsb, 1) != 0) {
            fprintf(stderr, "Sensor data read failed.\n");
            sleep(5);
            continue;
        }

        if (is_default_data(t_msb, t_lsb, p_msb, p_lsb)) {
            fprintf(stderr, "Sensor returned default data – check wiring.\n");
            sleep(5);
            continue;
        }

        char ts[32];
        get_timestamp(ts, sizeof(ts));
        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
               ts, temperature, pressure);
        fflush(stdout);

        sleep(5);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

