    uint8_t status;
    uint8_t msb, lsb;

    if (i2c_read_reg8(fd, 0x00, &status) < 0) {
        return -1;
    }
    if (status & 0x01) {
        return -2; /* sensor not ready */
    }

    if (i2c_read_reg8(fd, 0x01, &msb) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, 0x02, &lsb) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    *pressure = (float)raw / 100.0f;
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

