    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MLX90819 pressure sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure;
        int rc = read_pressure(fd, &pressure);

        if (rc == 0) {
            print_timestamp();
            printf("Pressure: %.2f kPa\n", pressure);
        } else if (rc == -2) {
            print_timestamp();
            fprintf(stderr, "Sensor not ready.\n");
        } else {
            print_timestamp();
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        }

        sleep(READ_INTERVAL);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

