/*
 * HVAC Airflow Monitor — Raspberry Pi 3 Model B+
 * Sensor : Sensirion SDP800-500Pa (differential pressure)
 * Bus    : I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * Log    : pressure_log.txt (CSV: timestamp,pressure_pa,temp_c)
 *
 * Build  : gcc -O2 -Wall -Wextra -o airflow_monitor airflow_monitor.c
 * Run    : ./airflow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR     0x25
#define LOG_FILE        "pressure_log.txt"
#define SAMPLE_PERIOD_S 45
#define MEAS_DELAY_US   45000   /* 45 ms measurement time */
#define MAX_RETRIES     3

/* SDP800 CRC-8: polynomial 0x31, init 0xFF */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion style)                                             */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[I2C] write(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "[I2C] read failed: got %zd of %zu (%s)\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SDP800 measurement                                                  */
/* ------------------------------------------------------------------ */
/*
 * Trigger a measurement and read 9 bytes:
 *   word0 (2 bytes) + CRC-8
 *   word1 (2 bytes) + CRC-8
 *   word2 (2 bytes) + CRC-8
 *
 * Word layout (big-endian):
 *   word0 = differential pressure (raw)
 *   word1 = temperature (raw)
 *   word2 = scale factor (raw)
 */
static int sdp800_read(int fd, float *pressure_pa, float *temp_c)
{
    uint8_t buf[9];

    /* Trigger continuous measurement (0x36) */
    if (i2c_write_cmd(fd, 0x36) != 0)
        return -1;

    usleep(MEAS_DELAY_US);

    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRC for each 3-byte word */
    for (int w = 0; w < 3; w++) {
        if (crc8(&buf[w * 3], 2) != buf[w * 3 + 2]) {
            fprintf(stderr, "[SDP800] CRC mismatch on word %d\n", w);
            return -1;
        }
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "[SDP800] Invalid scale factor (0)\n");
        return -1;
    }

    *pressure_pa = (float)raw_pressure / (float)scale_factor;
    *temp_c      = (float)raw_temp / 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float pressure_pa, float temp_c)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[LOG] Cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temp_c);
    } else {
        fprintf(fp, "(time-error),%.2f,%.2f\n", pressure_pa, temp_c);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[SIG] sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[I2C] Cannot open %s: %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "[I2C] Cannot set slave 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("SDP800 HVAC airflow monitor started.\n");
    printf("Bus: %s | Address: 0x%02X | Log: %s\n",
           I2C_BUS, SDP800_ADDR, LOG_FILE);
    printf("Press Ctrl+C to exit.\n\n");

    int consecutive_errors = 0;

    while (g_running) {
        float pressure_pa = 0.0f;
        float temp_c      = 0.0f;

        if (sdp800_read(g_i2c_fd, &pressure_pa, &temp_c) == 0) {
            log_data(pressure_pa, temp_c);
            printf("Pressure: %.2f Pa | Temp: %.2f C\n",
                   pressure_pa, temp_c);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "[SDP800] Read failed (%d consecutive)\n",
                    consecutive_errors);

            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "[SDP800] Sensor absent or bus error — "
                                "exiting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

