code:
/*
 * MLX90821 relative-pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX90821 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90821 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90821 VDD  -> 3.3 V
 *   MLX90821 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pressure_logger pressure_logger.c -li2c
 *
 * Run:
 *   ./pressure_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Configuration ---- */
#define I2C_BUS        "/dev/i2c-1"
#define MLX90821_ADDR  0x50          /* MLX90821 default I2C address */
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define PRESSURE_MIN   200.0f        /* kPa — safe tire minimum */
#define PRESSURE_MAX   250.0f        /* kPa — safe tire maximum */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

/*
 * Open the I2C bus and set the slave address.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Write a 16-bit command to the sensor.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb)
{
    uint8_t buf[2] = { msb, lsb };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X%02X): %s\n",
                msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the sensor.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed (expected %zu bytes, got %zd): %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read the 16-bit raw pressure value from the MLX90821.
 * Returns 0 on success and stores the value in *raw; -1 on failure.
 */
static int read_pressure_raw(int fd, uint16_t *raw)
{
    uint8_t buf[2];

    /* Issue a single-shot measurement command (example register address 0x00). */
    if (i2c_write_cmd(fd, 0x00, 0x00) < 0)
        return -1;

    /* Wait for the conversion to complete (typical ~10 ms). */
    usleep(15000);

    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Convert raw ADC value to kPa.
 * The MLX90821 provides 16-bit signed two's-complement data.
 * This example linearizes it to kPa; in a real deployment the
 * datasheet transfer function should be applied.
 */
static float raw_to_kpa(uint16_t raw)
{
    int16_t signed_raw = (int16_t)raw;
    return (float)signed_raw * 0.1f;
}

/* ---- Logging ---- */

static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", path, strerror(errno));
        return -1;
    }

    /* Write header only if the file is empty. */
    long pos = ftell(fp);
    if (pos == 0) {
        fprintf(fp, "timestamp,pressure_kPa\n");
        fflush(fp);
    }
    return 0;
}

static int log_write(FILE *fp, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!fp) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus and set slave address. */
    g_i2c_fd = i2c_open(I2C_BUS, MLX90821_ADDR);
    if (g_i2c_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file. */
    g_log_fp = log_open(LOG_FILE);
    if (!g_log_fp) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90821 pressure logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw;

        if (read_pressure_raw(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "Read failed — re-opening I2C bus.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;

            /* Brief delay before retry to avoid hammering the bus. */
            sleep(1);

            g_i2c_fd = i2c_open(I2C_BUS, MLX90821_ADDR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "I2C re-open failed — exiting.\n");
                break;
            }
            continue;
        }

        float pressure = raw_to_kpa(raw);

        if (log_write(g_log_fp, pressure) < 0) {
            fprintf(stderr, "Logging failed — exiting.\n");
            break;
        }

        printf("Pressure: %.2f kPa\n", pressure);

        if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
            fprintf(stderr,
                    "WARNING: Pressure %.2f kPa is outside safe tire range "
                    "[%.0f, %.0f] kPa.\n",
                    pressure, PRESSURE_MIN, PRESSURE_MAX);
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal. */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
