#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HIH6130_ADDR        0x27
#define I2C_BUS             "/dev/i2c-1"
#define LOG_FILE            "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT (1024 * 1024)  /* 1 MB */
#define SAMPLE_INTERVAL_S   5
#define MEASURE_DELAY_MS    40

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_write_bytes(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short write: wrote %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_hih6130(int fd, float *temperature, float *humidity)
{
    uint8_t data[4];

    /* Trigger a measurement by writing 0x00 to the sensor */
    if (i2c_write_bytes(fd, data, 0) < 0)
        return -1;

    sleep_ms(MEASURE_DELAY_MS);

    /* Read 4 bytes: [status, humidity_msb, humidity_lsb, temperature_msb] */
    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    uint16_t raw_humidity = ((uint16_t)data[1] << 8) | data[2];
    uint16_t raw_temp     = ((uint16_t)data[3] << 6) | (data[0] >> 2);

    /* Status bits: bit 0 = T, bit 1 = RH, bit 2 = reserved */
    if (data[0] & 0x03) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", data[0] & 0x03);
        return -1;
    }

    *humidity    = (float)raw_humidity / 16383.0f * 100.0f;
    *temperature = (float)raw_temp     / 16383.0f * 165.0f - 40.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    /* Check file size and roll if necessary */
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (pos >= LOG_FILE_SIZE_LIMIT) {
        if (fclose(fp) != 0)
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        if (remove(filename) != 0)
            fprintf(stderr, "Warning: remove failed: %s\n", strerror(errno));
        fp = fopen(filename, "w");
        if (!fp) {
            fprintf(stderr, "Error opening log file '%s' after roll: %s\n", filename, strerror(errno));
            return -1;
        }
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the sensor */
    if (ioctl(fd, I2C_SLAVE, HIH6130_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                HIH6130_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("HIH6130 environmental monitor started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        if (read_hih6130(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Warning: failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            sleep_ms(100);
    }

    printf("\nShutting down gracefully.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        if (close(fd) != 0)
            fprintf(stderr, "Warning: close(fd) failed: %s\n", strerror(errno));
    }
    return rc;
}

