/*
 * MLX90824 SENT Pressure Sensor Reader for Raspberry Pi 3 Model B+
 * SENT single-wire protocol on GPIO4 (BCM), 3 us tick time.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90824 mlx90824.c -lpigpio -lrt
 * Run:    sudo ./mlx90824
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_GPIO          4
#define LOG_FILE           "pressure_log.txt"
#define SYNC_TICKS         56          /* 56 ticks = 168 us  */
#define MIN_TICKS          12          /* 12 ticks  = 36 us   */
#define MAX_TICKS          271         /* 271 ticks = 813 us  */
#define TIMEOUT_US         100000      /* 100 ms timeout       */
#define POLL_US            100         /* 100 us poll interval */
#define TICK_US            3           /* 3 us per tick        */
#define MAX_PULSES         8           /* status + 3 data + chk */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SENT protocol decoder                                               */
/* ------------------------------------------------------------------ */

/*
 * Decode a SENT frame from a raw pulse-width array.
 * Returns 0 on success, -1 on timeout, -2 on bus error.
 */
static int decode_sent(const uint32_t *ticks, int count, uint8_t *status,
                       uint8_t *data, uint8_t *checksum)
{
    if (count < 4)
        return -2;

    /* Synchronization pulse: 56 ticks (168 us) */
    if (ticks[0] < SYNC_TICKS - 2 || ticks[0] > SYNC_TICKS + 2)
        return -2;

    /* Status nibble */
    if (ticks[1] < MIN_TICKS || ticks[1] > MAX_TICKS)
        return -2;
    *status = (uint8_t)((ticks[1] - 12) / 2);

    /* Data nibbles 0..2 */
    for (int i = 0; i < 3; i++) {
        int idx = 2 + i;
        if (ticks[idx] < MIN_TICKS || ticks[idx] > MAX_TICKS)
            return -2;
