#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TMP117_I2C_ADDR 0x48
#define TMP117_REG_CONFIG 0x01
#define TMP117_REG_TEMP 0x00
#define TMP117_DEVICE_ID 0x48
#define TMP117_CONFIG_DEFAULT 0x0000
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value & 0xFF);
    buf[2] = (uint8_t)((value >> 8) & 0xFF);
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", TMP117_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    uint16_t device_id = 0;
    if (i2c_read_reg16(i2c_fd, TMP117_REG_CONFIG, &device_id) < 0) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if ((device_id & 0xFF) != TMP117_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n", device_id & 0xFF, TMP117_DEVICE_ID);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg16(i2c_fd, TMP117_REG_CONFIG, TMP117_CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    uint16_t raw_temp = 0;
    if (i2c_read_reg16(i2c_fd, TMP117_REG_TEMP, &raw_temp) < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }
    int16_t signed_temp = (int16_t)raw_temp;
    *temperature = (float)signed_temp / 256.0f;
    return 0;
}

static int log_temperature(float temperature) {
    if (fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }
    if (init_i2c() < 0) {
        return 1;
    }
    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    printf("Greenhouse temperature monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) == 0) {
                printf("Temperature: %.2f °C\n", temperature);
            } else {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }
    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

