#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHTC3_ADDR        0x70
#define SHTC3_CMD_MEASURE 0x361F  /* High repeatability, clock stretching disabled */
#define SHTC3_CMD_SOFT_RST 0x805D
#define SHTC3_CMD_SLEEP   0xB098
#define SHTC3_CMD_WAKE    0x3517
#define SHTC3_CMD_RESET   0x805D

#define LOG_FILE "shtc3_environment.log"
#define SAMPLE_INTERVAL_S 5
#define CONVERSION_DELAY_US 15000  /* 15 ms worst-case conversion time */
#define WAKEUP_DELAY_US  15000     /* 15 ms after wake before first read */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, init 0xFF */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int shtc3_send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: failed to send command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int shtc3_reset(void) {
    if (shtc3_send_command(SHTC3_CMD_RESET) != 0)
        return -1;
    gpioDelay(2000);  /* 2 ms reset recovery */
    return 0;
}

static int shtc3_sleep(void) {
    return shtc3_send_command(SHTC3_CMD_SLEEP);
}

static int shtc3_wake(void) {
    return shtc3_send_command(SHTC3_CMD_WAKE);
}

static int shtc3_measure(float *temperature, float *humidity) {
    uint8_t buf[6];
    int rc;

    rc = shtc3_wake();
    if (rc != 0) {
        fprintf(stderr, "Error: failed to wake SHTC3\n");
        return -1;
    }
    gpioDelay(WAKEUP_DELAY_US);

    rc = shtc3_send_command(SHTC3_CMD_MEASURE);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to send measurement command\n");
        shtc3_sleep();
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    rc = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 6)\n", rc);
        shtc3_sleep();
        return -1;
    }

    if (shtc3_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        shtc3_sleep();
        return -1;
    }
    if (shtc3_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        shtc3_sleep();
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Error: temperature out of range: %.2f C\n", *temperature);
        shtc3_sleep();
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Error: humidity out of range: %.2f %%\n", *humidity);
        shtc3_sleep();
        return -1;
    }

    shtc3_sleep();
    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (shtc3_reset() != 0) {
        fprintf(stderr, "Error: SHTC3 reset failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("SHTC3 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (shtc3_measure(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: measurement failed, will retry next cycle\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        shtc3_sleep();
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

