/*
 * Si7202 I2C Hall-effect sensor rotational speed & temperature logger.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Silicon Labs Si7202 (I2C address 0x28)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_temp_log mag_temp_log.c -li2c
 *
 * The Si7202 is a Hall-effect sensor with a digital output; this program
 * reads the raw magnetic field magnitude and temperature, converts them
 * to engineering units, and logs them to mag_temp_log.csv at 1-second
 * intervals.  SIGINT (Ctrl+C) triggers a clean shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si7202 constants (verified against datasheet) ---- */
#define SI7202_I2C_ADDR        0x28
#define SI7202_REG_STATUS      0x00
#define SI7202_REG_MAG_RAW     0x01
#define SI7202_REG_TEMP_RAW    0x02
#define SI7202_REG_CONFIG      0x03
#define SI7202_REG_ID          0x0F

#define SI7202_ID_VALUE        0x72  /* expected device ID byte */

/* Config register bits (write 0x00 after reset / power-up) */
#define SI7202_CFG_MAG_AVG_1   0x00
#define SI7202_CFG_TEMP_AVG_1  0x00
#define SI7202_CFG_MAG_LSB     0x00
#define SI7202_CFG_TEMP_LSB    0x00
#define SI7202_CFG_MAG_EN      0x01
#define SI7202_CFG_TEMP_EN     0x02
#define SI7202_CFG_DEFAULT     (SI7202_CFG_MAG_AVG_1 | \
                               SI7202_CFG_TEMP_AVG_1 | \
                               SI7202_CFG_MAG_LSB | \
                               SI7202_CFG_TEMP_LSB | \
                               SI7202_CFG_MAG_EN | \
                               SI7202_CFG_TEMP_EN)

/* Status register bits */
#define SI7202_STATUS_MAG_RDY  0x01
#define SI7202_STATUS_TEMP_RDY 0x02

/* Conversion constants (datasheet: 1 LSB = 0.1 mT, 1 LSB = 0.1 deg C) */
#define MAG_LSB_TO_MT          0.1f
#define TEMP_LSB_TO_C          0.1f

#define LOG_FILE_NAME          "mag_temp_log.csv"
#define I2C_BUS_NAME           "/dev/i2c-1"
#define SAMPLE_PERIOD_SEC      1.0
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a Si7202 register (MSB first).              */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int si7202_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a Si7202 register (MSB first).             */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int si7202_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si7202: verify device ID, configure, and read       */
/* a valid status word.                                               */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int si7202_init(int fd)
{
    uint16_t id = 0;

    /* Read device ID register (0x0F) to confirm sensor presence. */
    if (si7202_read_reg(fd, SI7202_REG_ID, &id) != 0) {
        fprintf(stderr, "Cannot read Si7202 ID register.\n");
        return -1;
    }

    if ((id & 0xFF) != SI7202_ID_VALUE) {
        fprintf(stderr, "Si7202 ID mismatch: got 0x%02X, expected 0x%02X.\n",
                id & 0xFF, SI7202_ID_VALUE);
        return -1;
    }

    /* Configure sensor: enable magnetic and temperature channels. */
    if (si7202_write_reg(fd, SI7202_REG_CONFIG, SI7202_CFG_DEFAULT) != 0) {
        fprintf(stderr, "Failed to configure Si7202.\n");
        return -1;
    }

    /* Allow configuration to settle. */
    usleep(10000);

    /* Verify configuration was accepted by reading back the register. */
    uint16_t cfg = 0;
    if (si7202_read_reg(fd, SI7202_REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "Failed to verify Si7202 configuration.\n");
        return -1;
    }

    if (cfg != SI7202_CFG_DEFAULT) {
        fprintf(stderr, "Si7202 configuration verification failed: "
                        "read 0x%04X, expected 0x%04X.\n",
                cfg, SI7202_CFG_DEFAULT);
        return -1;
    }

    /* Verify sensor is ready by checking status bits. */
    uint16_t status = 0;
    if (si7202_read_reg(fd, SI7202_REG_STATUS, &status) != 0) {
        fprintf(stderr, "Failed to read Si7202 status register.\n");
        return -1;
    }

    if ((status & (SI7202_STATUS_MAG_RDY | SI7202_STATUS_TEMP_RDY)) == 0) {
        fprintf(stderr, "Si7202 not ready: status = 0x%04X.\n", status);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read magnetic field magnitude and temperature.                      */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int si7202_read_data(int fd, float *mag_mt, float *temp_c)
{
    uint16_t mag_raw = 0;
    uint16_t temp_raw = 0;

    if (si7202_read_reg(fd, SI7202_REG_MAG_RAW, &mag_raw) != 0)
        return -1;

    if (si7202_read_reg(fd, SI7202_REG_TEMP_RAW, &temp_raw) != 0)
        return -1;

    *mag_mt = (float)mag_raw * MAG_LSB_TO_MT;
    *temp_c = (float)temp_raw * TEMP_LSB_TO_C;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a CSV row to the log file.  Creates the file if it does not  */
/* exist and writes a header row.                                     */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float mag_mt, float temp_c)
{
    /* Check if file is empty / new. */
    long pos = ftell(fp);
    if (pos == 0) {
        if (fprintf(fp, "Timestamp,Magnetic Field (mT),Temperature (C)\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            return -1;
        }
        fflush(fp);
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, mag_mt, temp_c) < 0) {
        fprintf(stderr, "Failed to write CSV row: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    fd = open(I2C_BUS_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7202_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI7202_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    /* ---- Initialize sensor ---- */
    if (si7202_init(fd) != 0) {
        fprintf(stderr, "Si7202 initialization failed.\n");
        goto cleanup;
    }

    /* ---- Open log file ---- */
    fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup;
    }

    printf("Si7202 rotational speed & temperature logger started.\n");
    printf("Logging to %s every %.1f s.  Press Ctrl+C to stop.\n",
           LOG_FILE_NAME, SAMPLE_PERIOD_SEC);

    /* ---- Main sampling loop ---- */
    int consecutive_errors = 0;

    while (g_running) {
        float mag_mt = 0.0f;
        float temp_c = 0.0f;
        int ok = 0;

        if (si7202_read_data(fd, &mag_mt, &temp_c) == 0) {
            ok = 1;
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read failed (%d consecutive).\n",
                    consecutive_errors);
        }

        if (ok) {
            if (log_data(fp, mag_mt, temp_c) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            /* Write a NaN line so the log remains complete. */
            time_t t = time(NULL);
            struct tm tm;
            if (localtime_r(&t, &tm) != NULL) {
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
                fprintf(fp, "%s,NaN,NaN\n", ts);
                fflush(fp);
            }
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }
    if (fd >= 0)
        close(fd);

    return rc;
}

