        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

