/*
 * Raspberry Pi Zero W – Honeywell HAF Series flow sensor logger
 *
 * Wiring:
 *   HAFUHH0025PA3 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   HAFUHH0025PA3 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   HAFUHH0025PA3 VDD  -> 3.3 V
 *   HAFUHH0025PA3 GND  -> GND
 *
 * The HAF Series family uses a 4-byte API call (no register pointer write):
 *   byte 0: command byte (0x00)
 *   byte 1: read command (0x01)
 *   byte 2: read command (0x02)
 *   byte 3: read command (0x03)
 * The response is 4 bytes: [status, flow_hi, flow_lo, temp_hi].
 *   flow = ((flow_hi & 0x3F) << 8) | flow_lo
 *   temp = (temp_hi << 4)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "flow_log.txt"
#define SAMPLE_PERIOD  1           /* seconds between samples */
#define MAX_INIT_READS  5           /* first 5 reads after power-up may be stale */

/* HAF Series command bytes */
#define CMD_READ_FLOW  0x01
#define CMD_READ_TEMP  0x02
#define CMD_READ_STATUS 0x03

/* HAF Series status bits */
#define STATUS_ERROR   0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and claim the sensor's address.                    */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int init_i2c(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    g_i2c_fd = fd;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 4 bytes from the HAF Series sensor.                            */
/* Returns 0 on success, -1 on I/O error.                              */
/* ------------------------------------------------------------------ */
static int read_sensor(uint8_t *buf)
{
    uint8_t cmd[4] = { CMD_READ_FLOW, CMD_READ_TEMP, CMD_READ_STATUS, 0x00 };

    for (size_t i = 0; i < sizeof(cmd); i++) {
        if (write(g_i2c_fd, &cmd[i], 1) != 1) {
            fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n",
                    cmd[i], strerror(errno));
            return -1;
        }
    }

    /* Small delay so the sensor can clock out the response */
    usleep(1000);

    ssize_t n = read(g_i2c_fd, buf, 4);
    if (n != 4) {
        fprintf(stderr, "I2C read failed: expected 4 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw bytes to flow (SLPM) and temperature (°C).              */
/* ------------------------------------------------------------------ */
static void convert_data(const uint8_t *buf, float *flow, float *temp)
{
    uint16_t raw_flow = ((uint16_t)(buf[1] & 0x3F) << 8) | buf[2];
    uint16_t raw_temp = (uint16_t)buf[3] << 4;

    *flow = (float)raw_flow * 0.01f;   /* SLPM */
    *temp = (float)raw_temp * 0.0625f; /* °C   */
}

/* ------------------------------------------------------------------ */
/* Log a measurement line.                                             */
/* ------------------------------------------------------------------ */
static void log_measurement(float flow, float temp)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        snprintf(ts, sizeof(ts), "1970-01-01 00:00:00");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_fp, "%s, Flow: %.2f SLPM, Temperature: %.2f C\n",
            ts, flow, temp);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c(I2C_BUS, 0x40) < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t buf[4];
    int init_reads = MAX_INIT_READS;

    while (g_running) {
        if (read_sensor(buf) == 0) {
            if (buf[0] & STATUS_ERROR) {
                fprintf(stderr, "Sensor status error (0x%02X).\n", buf[0]);
            } else {
                float flow, temp;
                convert_data(buf, &flow, &temp);
                log_measurement(flow, temp);
            }
        } else {
            fprintf(stderr, "Sensor read failed. Re-initializing I2C.\n");
            if (g_i2c_fd >= 0) {
                close(g_i2c_fd);
                g_i2c_fd = -1;
            }
            if (init_i2c(I2C_BUS, 0x40) < 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
            init_reads = MAX_INIT_READS;
        }

        /* Wait for next sample, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

