#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT31_ADDR             0x45
#define SHT31_MEASURE_CMD      0x2C
#define SHT31_MEASURE_HIGHREP  0x06
#define SHT31_MEASURE_DELAY_US 15000
#define SHT31_READ_LEN         6
#define LOG_FILE               "sht31d_data.log"
#define SAMPLE_INTERVAL_US     5000000
#define MAX_RETRIES            3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t sht31_crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sht31_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd = SHT31_MEASURE_CMD;
    uint8_t buf[SHT31_READ_LEN];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "[attempt %d] I2C write failed\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        gpioDelay(SHT31_MEASURE_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, SHT31_READ_LEN) != SHT31_READ_LEN) {
            fprintf(stderr, "[attempt %d] I2C read failed\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        if (sht31_crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "[attempt %d] temperature CRC mismatch\n", attempt + 1);
            continue;
        }
        if (sht31_crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "[attempt %d] humidity CRC mismatch\n", attempt + 1);
            continue;
        }

        uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
        uint16_t h_raw = (uint16_t)((buf[3] << 8) | buf[4]);

        *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
        *humidity    = 100.0f * (float)h_raw / 65535.0f;

        return 0;
    }

    return -1;
}

static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(stderr, "%s: %s\n", ts, msg);
    if (fp) {
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
        fflush(fp);
    }
}

int main(void)
{
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SHT31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        if (sht31_read(g_i2c_handle, &temperature, &humidity) == 0) {
            log_data(g_log_file, temperature, humidity);
        } else {
            log_error(g_log_file, "SHT31 read failed after retries");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (g_log_file)  fclose(g_log_file);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

