/*
 * MLX90824 Absolute Pressure Sensor Logger for Raspberry Pi 4 Model B
 *
 * Reads pressure and temperature from an MLX90824 via I2C and logs
 * timestamped readings to pressure_log.txt every 2 seconds.
 *
 * Wiring:
 *   MLX90824 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   MLX90824 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   MLX90824 VDD -> 3.3 V
 *   MLX90824 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90824_logger mlx90824_logger.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90824_ADDR  0x28          /* MLX90824 default I2C address */
#define LOG_FILE       "pressure_log.txt"
#define READ_INTERVAL  2             /* seconds between readings */

/* MLX90824 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE_MSB  0x00
#define REG_PRESSURE_LSB  0x01
#define REG_TEMP_MSB     0x02
#define REG_TEMP_LSB     0x03

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a 16-bit register address to the device.
 * The MLX90824 uses 16-bit register addresses, sent big-endian.
 */
static int i2c_write_reg16(int fd, uint8_t msb, uint8_t lsb)
{
    uint8_t buf[2] = { msb, lsb };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write reg16 0x%02X%02X failed: %s\n",
                msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read N bytes from the current register pointer.
 */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "[ERROR] I2C read %zu bytes failed: got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian register pair.
 */
static int i2c_read_reg16(int fd, uint8_t msb, uint8_t lsb, uint16_t *out)
{
    if (i2c_write_reg16(fd, msb, lsb) < 0)
        return -1;

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0)
        return -1;

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Read pressure (Pa) and temperature (°C) from the MLX90824.
 * Returns 0 on success, -1 on I/O error.
 */
static int read_mlx90824(int fd, float *pressure, float *temperature)
{
    uint16_t raw_p, raw_t;

    if (i2c_read_reg16(fd, REG_PRESSURE_MSB, REG_PRESSURE_LSB, &raw_p) < 0)
        return -1;

    if (i2c_read_reg16(fd, REG_TEMP_MSB, REG_TEMP_LSB, &raw_t) < 0)
        return -1;

    /* Convert raw 16-bit values to physical units.
     * Pressure: 0.1 Pa per LSB (typical for MLX90824).
     * Temperature: 0.01 °C per LSB. */
    *pressure    = (float)raw_p * 0.1f;
    *temperature = (float)raw_t * 0.01f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
            ts, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, ERROR: %s\n", ts, msg);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MLX90824 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MLX90824_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MLX90824_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90824 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, READ_INTERVAL);

    while (g_running) {
        float pressure, temperature;

        if (read_mlx90824(g_i2c_fd, &pressure, &temperature) == 0) {
            log_data(g_log_fp, pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
        } else {
            log_error(g_log_fp, "I2C read failure or sensor absent");
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

