 * The MLX90824 uses 16-bit register addresses, sent big-endian.
 */
static int i2c_write_reg16(int fd, uint8_t msb, uint8_t lsb)
{
    uint8_t buf[2] = { msb, lsb };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write reg16 0x%02X%02X failed: %s\n",
                msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read N bytes from the current register pointer.
 */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "[ERROR] I2C read %zu bytes failed: got %zd (%s)\n",
                len, n, strerror(errno));
