code:
/*
 * LM75B temperature monitor with hysteresis fan control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensor: STMicroelectronics LM75B on I2C bus 1, address 0x48
 * Fan:    GPIO18 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o lm75b_fan lm75b_fan.c -lpigpio -lrt
 * Run:    sudo ./lm75b_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  26.0f
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1.0   /* seconds */
#define POLL_DELAY     0.1   /* seconds between I2C polls */

#define LM75B_REG_TEMP 0x00
#define LM75B_REG_CONF 0x01

/* LM75B configuration: continuous conversion, 0.5°C resolution, fault queue 1 */
#define LM75B_CONF_VAL 0x00

typedef struct {
    float  temperature;
    time_t timestamp;
} TemperatureReading;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_fan_on     = false;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X val 0x%02X failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* LM75B sensor                                                       */
/* ------------------------------------------------------------------ */
static int lm75b_init(int handle)
{
    if (i2c_write_byte(handle, LM75B_REG_CONF, LM75B_CONF_VAL) < 0)
        return -1;

    /* Allow configuration to settle */
    time_sleep(0.01);
    return 0;
}

static int lm75b_read_temperature(int handle, float *temperature)
{
    uint8_t msb = 0, lsb = 0;

    if (i2c_read_byte(handle, LM75B_REG_TEMP, &msb) < 0)
        return -1;

    /* LM75B: 9-bit two's-complement, left-justified in 16-bit register */
    int16_t raw = (int16_t)((msb << 8) | lsb);
    raw >>= 5;                       /* arithmetic shift sign-extends */

    *temperature = (float)raw * 0.125f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                    */
/* ------------------------------------------------------------------ */
static void buffer_add(TemperatureReading *buf, int size,
                       float temp, time_t ts)
{
    buf[size % BUFFER_SIZE].temperature = temp;
    buf[size % BUFFER_SIZE].timestamp   = ts;
}

static float buffer_average(const TemperatureReading *buf, int size)
{
    if (size == 0)
        return 0.0f;

    double sum = 0.0;
    for (int i = 0; i < size; i++)
        sum += buf[i].temperature;
    return (float)(sum / size);
}

/* ------------------------------------------------------------------ */
/* Fan control with hysteresis                                         */
/* ------------------------------------------------------------------ */
static int fan_set(int gpio, bool on)
{
    int rc = gpioWrite(gpio, on ? 1 : 0);
    if (rc < 0) {
        fprintf(stderr, "[GPIO] write %d failed: %s\n",
                on ? 1 : 0, strerror(errno));
        return -1;
    }
    g_fan_on = on;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fan_on)
        (void)fan_set(FAN_GPIO, false);

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, LM75B_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- LM75B configure -------------------------------------------- */
    if (lm75b_init(g_i2c_handle) < 0) {
        fprintf(stderr, "LM75B initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Fan GPIO setup -------------------------------------------- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                FAN_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    (void)fan_set(FAN_GPIO, false);

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop -------------------------------------------------- */
    TemperatureReading temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_size  = 0;

    while (g_running) {
        float temperature = 0.0f;

        if (lm75b_read_temperature(g_i2c_handle, &temperature) < 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        time_t now = time(NULL);
        buffer_add(temperature_buffer, buffer_index, temperature, now);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_size < BUFFER_SIZE)
            buffer_size++;

        float avg = buffer_average(temperature_buffer, buffer_size);

        printf("Temperature: %.2f C, Average: %.2f C, Fan: %s\n",
               temperature, avg, g_fan_on ? "ON" : "OFF");

        /* Hysteresis control */
        if (avg > TEMP_THRESHOLD_HIGH && !g_fan_on) {
            if (fan_set(FAN_GPIO, true) == 0)
                printf("Fan turned ON (avg %.2f C > %.1f C)\n",
                       avg, TEMP_THRESHOLD_HIGH);
        } else if (avg < TEMP_THRESHOLD_LOW && g_fan_on) {
            if (fan_set(FAN_GPIO, false) == 0)
                printf("Fan turned OFF (avg %.2f C < %.1f C)\n",
                       avg, TEMP_THRESHOLD_LOW);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

