static int fan_set(int gpio, bool on)
{
    int rc = gpioWrite(gpio, on ? 1 : 0);
    if (rc < 0) {
        fprintf(stderr, "[GPIO] write %d failed: %s\n",
                on ? 1 : 0, strerror(errno));
        return -1;
    }
    g_fan_on = on;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fan_on)
        (void)fan_set(FAN_GPIO, false);

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, LM75B_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- LM75B configure -------------------------------------------- */
    if (lm75b_init(g_i2c_handle) < 0) {
        fprintf(stderr, "LM75B initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Fan GPIO setup -------------------------------------------- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                FAN_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    (void)fan_set(FAN_GPIO, false);

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop -------------------------------------------------- */
    TemperatureReading temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_size  = 0;

    while (g_running) {
        float temperature = 0.0f;

        if (lm75b_read_temperature(g_i2c_handle, &temperature) < 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        time_t now = time(NULL);
        buffer_add(temperature_buffer, buffer_index, temperature, now);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_size < BUFFER_SIZE)
            buffer_size++;

        float avg = buffer_average(temperature_buffer, buffer_size);

        printf("Temperature: %.2f C, Average: %.2f C, Fan: %s\n",
               temperature, avg, g_fan_on ? "ON" : "OFF");

        /* Hysteresis control */
        if (avg > TEMP_THRESHOLD_HIGH && !g_fan_on) {
            if (fan_set(FAN_GPIO, true) == 0)
                printf("Fan turned ON (avg %.2f C > %.1f C)\n",
                       avg, TEMP_THRESHOLD_HIGH);
        } else if (avg < TEMP_THRESHOLD_LOW && g_fan_on) {
            if (fan_set(FAN_GPIO, false) == 0)
                printf("Fan turned OFF (avg %.2f C < %.1f C)\n",
                       avg, TEMP_THRESHOLD_LOW);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

