/*
 * SDP810-500Pa differential pressure logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -li2c
 * Run:    ./airflow   (requires root or i2c group membership)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x25
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MEASURE_DELAY  45000      /* microseconds (45 ms) */
#define PRESSURE_THRESH 5.0f      /* Pa */
#define READ_LEN       9          /* 2 data + 2 CRC + 2 temp + 2 CRC */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no reflection, no final XOR. */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Read one 9-byte measurement frame from the SDP810.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int sdp810_read(int fd, float *pressure, float *temperature)
{
    uint8_t cmd = 0x36;            /* continuous measurement, no averaging */
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASURE_DELAY);

    uint8_t buf[READ_LEN];
    ssize_t r = read(fd, buf, READ_LEN);
    if (r != READ_LEN) {
        if (r < 0)
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read short: got %zd of %d bytes\n", r, READ_LEN);
        return -1;
    }

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -2;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -2;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure / 60.0f;   /* Pa */
    *temperature = (float)raw_temp     / 200.0f;  /* °C */
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    fprintf(fp, "# timestamp,pressure_Pa,temperature_C\n");
    fflush(fp);

    int consecutive_errors = 0;

    while (g_running) {
        float pressure, temperature;

        int rc = sdp810_read(fd, &pressure, &temperature);
        if (rc == 0) {
            consecutive_errors = 0;
            log_data(fp, pressure, temperature);
            if (pressure > PRESSURE_THRESH)
                fprintf(stderr, "Warning: pressure %.2f Pa exceeds threshold %.1f Pa\n",
                        pressure, PRESSURE_THRESH);
        } else if (rc == -1) {
            consecutive_errors++;
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        } else { /* rc == -2 */
            /* CRC error: skip this sample but keep running. */
        }

        sleep(SAMPLE_PERIOD);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    if (close(fd) < 0)
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));

    return EXIT_SUCCESS;
}

