code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x28
#define TEMP_REG       0x00
#define CONFIG_REG     0x01
#define LED_GPIO       17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_INTERVAL  1
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_temperature(int fd, float *temp_out)
{
    int16_t raw;
    if (i2c_read_reg16(fd, TEMP_REG, &raw) != 0)
        return -1;

    int16_t temp_raw = (int16_t)((raw >> 8) & 0xFF) | ((raw & 0xFF) << 8);
    *temp_out = (float)temp_raw / 256.0f;
    return 0;
}

static int control_led(int state)
{
    if (gpioWrite(LED_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d: %s\n", LED_GPIO, pigpio_error(gpioRead(LED_GPIO)));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (control_led(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", STTS2004_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(g_i2c_fd, CONFIG_REG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure STTS2004\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bool led_state = false;
    int consecutive_failures = 0;

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_fd, &temperature) == 0) {
            consecutive_failures = 0;
            printf("Temperature: %.2f C\n", temperature);
            fflush(stdout);

            if (temperature > TEMP_HIGH && !led_state) {
                if (control_led(1) == 0)
                    led_state = true;
            } else if (temperature < TEMP_LOW && led_state) {
                if (control_led(0) == 0)
                    led_state = false;
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Failed to read temperature (attempt %d/%d)\n", consecutive_failures, MAX_RETRIES);
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
        }

        sleep(POLL_INTERVAL);
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    control_led(0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

