        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (control_led(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", STTS2004_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(g_i2c_fd, CONFIG_REG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure STTS2004\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bool led_state = false;
    int consecutive_failures = 0;

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_fd, &temperature) == 0) {
            consecutive_failures = 0;
            printf("Temperature: %.2f C\n", temperature);
            fflush(stdout);

            if (temperature > TEMP_HIGH && !led_state) {
                if (control_led(1) == 0)
                    led_state = true;
            } else if (temperature < TEMP_LOW && led_state) {
                if (control_led(0) == 0)
                    led_state = false;
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Failed to read temperature (attempt %d/%d)\n", consecutive_failures, MAX_RETRIES);
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
        }

        sleep(POLL_INTERVAL);
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    control_led(0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

