#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASUREMENT_DELAY_US 45000
#define LOG_FILE "flow_data.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp800(int handle, float *pressure, float *temperature) {
    uint8_t cmd = 0x36;
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    uint8_t buffer[9];
    int bytes_read = i2cReadDevice(handle, (char *)buffer, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from I2C device (read %d bytes).\n", bytes_read);
        return -1;
    }

    if (crc8(&buffer[0], 2) != buffer[2]) {
        fprintf(stderr, "Error: CRC check failed for differential pressure data.\n");
        return -1;
    }
    if (crc8(&buffer[3], 2) != buffer[5]) {
        fprintf(stderr, "Error: CRC check failed for temperature data.\n");
        return -1;
    }
    if (crc8(&buffer[6], 3) != buffer[8]) {
        fprintf(stderr, "Error: CRC check failed for scale factor data.\n");
        return -1;
    }

    int16_t dp_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t temp_raw = (int16_t)((buffer[3] << 8) | buffer[4]);

    *pressure = (float)dp_raw / 60.0f;
    *temperature = (float)temp_raw / 200.0f;

    return 0;
}

static void log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s for writing.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f Pa, %.2f °C\n", timestamp, pressure, temperature);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d.\n", SDP800_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not install SIGINT handler.\n");
    }

    float pressure, temperature;

    while (running) {
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        gpioDelay(1000000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

