#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define CMD_MEAS_RH_NOHOLD  0xF5
#define CMD_MEAS_TEMP_NOHOLD 0xF3
#define CMD_READ_TEMP_PREV   0xE0
#define CMD_READ_ID_1        0xFA
#define CMD_READ_ID_2        0x0F
#define CMD_READ_FW_REV      0x84
#define MAX_RETRIES          3
#define SAMPLE_INTERVAL_S    60
#define MEAS_DELAY_US        25000
#define RETRY_DELAY_US       2000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (g_log_file) {
        fprintf(g_log_file, "%s,ERROR,%s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

static int i2c_write_cmd(int handle, uint8_t cmd) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByte(handle, cmd);
        if (rc == 0) return 0;
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len) return 0;
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int read_sensor(int handle, float *temp_c, float *hum_pct) {
    uint8_t buf[2];

    if (i2c_write_cmd(handle, CMD_MEAS_RH_NOHOLD) != 0) {
        log_error("Failed to send Measure RH No Hold command");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    if (i2c_read_bytes(handle, buf, 2) != 0) {
        log_error("Failed to read RH measurement");
        return -1;
    }
    int raw_hum = (buf[0] << 8) | buf[1];
    *hum_pct = (125.0f * (float)raw_hum / 65536.0f) - 6.0f;
    if (*hum_pct < 0.0f) *hum_pct = 0.0f;
    if (*hum_pct > 100.0f) *hum_pct = 100.0f;

    if (i2c_write_cmd(handle, CMD_READ_TEMP_PREV) != 0) {
        log_error("Failed to send Read Temperature from Previous RH command");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    if (i2c_read_bytes(handle, buf, 2) != 0) {
        log_error("Failed to read temperature measurement");
        return -1;
    }
    int raw_temp = (buf[0] << 8) | buf[1];
    *temp_c = (175.72f * (float)raw_temp / 65536.0f) - 46.85f;

    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("environment.log", "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t id_buf[8];
    if (i2c_write_cmd(g_i2c_handle, CMD_READ_ID_1) == 0 &&
        i2c_read_bytes(g_i2c_handle, id_buf, 8) == 0) {
        uint8_t fw_rev = id_buf[6];
        uint8_t sn[6] = {id_buf[0], id_buf[1], id_buf[2], id_buf[3], id_buf[4], id_buf[5]};
        char sn_str[32];
        snprintf(sn_str, sizeof(sn_str), "%02X%02X%02X%02X%02X%02X", sn[0], sn[1], sn[2], sn[3], sn[4], sn[5]);
        printf("Si7021 detected: SN=%s, FW=0x%02X\n", sn_str, fw_rev);
    } else {
        log_error("Sensor not responding or not a Si7021 (no ID read)");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp_c, hum_pct;
        if (read_sensor(g_i2c_handle, &temp_c, &hum_pct) == 0) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

            fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
            fflush(g_log_file);
            printf("%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
        } else {
            log_error("Sensor read failed; skipping log entry");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

