#define HDC1080_ADDR        0x40
#define HDC1080_TEMP_REG    0x00
#define HDC1080_CONFIG_REG  0x02
#define HDC1080_MANUFACTURER 0x5449
#define HDC1080_DEVICE_ID   0x1050

#define LOG_FILE "enviro_log.txt"
#define SAMPLE_INTERVAL_US 5000000
#define CONVERSION_DELAY_US 20000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hdc1080_init(int handle) {
    int manuf = i2cReadWordData(handle, 0x08);
    if (manuf < 0) {
        fprintf(stderr, "Error reading manufacturer ID: %d\n", manuf);
        return -1;
    }
    if ((manuf & 0xFFFF) != HDC1080_MANUFACTURER) {
        fprintf(stderr, "Manufacturer ID mismatch: 0x%04X (expected 0x%04X)\n",
                manuf & 0xFFFF, HDC1080_MANUFACTURER);
        return -1;
    }

    int dev_id = i2cReadWordData(handle, 0x0A);
    if (dev_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", dev_id);
        return -1;
    }
    if ((dev_id & 0xFFFF) != HDC1080_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch: 0x%04X (expected 0x%04X)\n",
                dev_id & 0xFFFF, HDC1080_DEVICE_ID);
        return -1;
    }

    /* Config: 14-bit temp, 14-bit humidity, heater off, mode = temp+hum */
    if (i2cWriteWordData(handle, HDC1080_CONFIG_REG, 0x1000) < 0) {
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }
    return 0;
}

static int hdc1080_read(int handle, float *temperature, float *humidity) {
    uint8_t buf[4];

    /* Trigger measurement: write pointer to temp register (0x00) */
    if (i2cWriteByte(handle, HDC1080_TEMP_REG) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONVERSION_DELAY_US);

    /* Read 4 bytes: temp MSB, temp LSB, hum MSB, hum LSB */
    if (i2cReadDevice(handle, (char *)buf, 4) != 4) {
        fprintf(stderr, "Error reading measurement data\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_hum  = ((uint16_t)buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (hdc1080_init(i2c_handle) < 0) {
        fprintf(stderr, "HDC1080 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("HDC1080 initialized. Logging to %s every 5 seconds. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        float temperature, humidity;

        if (hdc1080_read(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(LOG_FILE, temperature, humidity) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 50);
        }
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

