/*
 * HVAC Air-Duct Pressure Monitor — Raspberry Pi Zero W
 * Sensor : Sensirion SDP810-500Pa (differential pressure, I2C)
 * Bus    : /dev/i2c-1  (GPIO2=SDA, GPIO3=SCL)
 * Log    : hvac_pressure_log.txt  (CSV: timestamp,pressure_Pa,temperature_C)
 *
 * Build  : gcc -O2 -Wall -Wextra -o hvac_monitor hvac_monitor.c -li2c
 * Run    : sudo ./hvac_monitor   (root needed for /dev/i2c-1 on some kernels)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x25
#define LOG_FILE       "hvac_pressure_log.txt"
#define SAMPLE_PERIOD  1   /* seconds between samples */
#define MEAS_DELAY_MS  50  /* SDP810 measurement time */

/* SDP810 CRC-8: polynomial 0x31, init 0x00 (Sensirion convention) */
#define CRC8_POLY 0x31
#define CRC8_INIT 0x00

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion)                                                    */
/* ------------------------------------------------------------------ */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[I2C] write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "[I2C] read(%zu) failed: got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor measurement                                                  */
/* ------------------------------------------------------------------ */
/*
 * Trigger a single measurement and read the 9-byte result.
 * Returns 0 on success and fills *pressure, *temperature.
 * Returns -1 on I2C or CRC error.
 */
static int sdp810_read(int fd, float *pressure, float *temperature)
{
    uint8_t data[9];

    if (i2c_write_cmd(fd, 0x36) != 0)   /* trigger continuous measurement */
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

