    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);

    /* SDP810-500Pa: 1 Pa = 240 LSB (16-bit signed, 0.01 Pa/LSB) */
    *pressure    = (float)raw_pressure / 240.0f;
    *temperature = (float)raw_temp / 240.0f;

    return 0;
}

