        fprintf(g_log_fp, "timestamp,pressure_Pa,temperature_C\n");

    printf("HVAC pressure monitor started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* ---- main loop ---- */
    while (g_running) {
        float pressure, temperature;

        if (sdp810_read(g_i2c_fd, &pressure, &temperature) == 0) {
