static int stop_periodic_measurement(void) {
    if (i2c_write_cmd(CMD_STOP_PERIODIC) < 0) {
        log_error("Failed to stop periodic measurement");
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[9];
    if (i2c_read_data(buf, sizeof(buf)) < 0) {
        log_error("Failed to read sensor data");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CRC error in CO2 data");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("CRC error in temperature data");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("CRC error in humidity data");
        return -1;
    }

    data->co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (float)((buf[3] << 8) | buf[4]) / 100.0f;
    data->humidity = (float)((buf[6] << 8) | buf[7]) / 100.0f;
    return 0;
}

static void add_to_buffer(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static void *log_data_thread(void *arg) {
    (void)arg;
    log_thread_running = 1;
    while (running && log_thread_running) {
        sleep(LOG_INTERVAL_SEC);
        if (!running || !log_thread_running) break;

        pthread_mutex_lock(&buffer.mutex);
        int count = buffer.count;
        int tail = buffer.tail;
        int head = buffer.head;
        sensor_data_t data[BUFFER_SIZE];
        int copied = 0;
        for (int i = 0; i < count; i++) {
            int idx = (tail + i) % BUFFER_SIZE;
            data[copied++] = buffer.data[idx];
        }
        buffer.count = 0;
        buffer.head = 0;
        buffer.tail = 0;
        pthread_mutex_unlock(&buffer.mutex);

        char filename[256];
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        snprintf(filename, sizeof(filename), "%s/scd40_data_%d-%02d-%02d_%02d-%02d-%02d.csv",
                 LOG_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec);

        FILE *fp = fopen(filename, "w");
        if (fp == NULL) {
            log_error("Failed to open CSV file for writing");
            continue;
        }
        fprintf(fp, "timestamp,co2_ppm,temperature_c,humidity_rh\n");
        for (int i = 0; i < copied; i++) {
            char ts[32];
            struct tm tmv = *localtime(&t);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
            fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, data[i].co2, data[i].temperature, data[i].humidity);
            t += 1;
        }
        fclose(fp);
    }
    log_thread_running = 0;
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        stop_periodic_measurement();
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_thread_running) {
        log_thread_running = 0;
        pthread_join(log_thread, NULL);
    }
    pthread_mutex_destroy(&buffer.mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (mkdir(LOG_DIR, 0755) < 0 && errno != EEXIST) {
        perror("Failed to create log directory");
        return 1;
    }

    if (init_i2c() < 0) {
        return 1;
    }

    if (start_periodic_measurement() < 0) {
        cleanup();
        return 1;
    }

    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;
    if (pthread_mutex_init(&buffer.mutex, NULL) != 0) {
        log_error("Failed to initialize mutex");
        cleanup();
        return 1;
    }

    if (pthread_create(&log_thread, NULL, log_data_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }

    sleep(STARTUP_DELAY_SEC);

    while (running) {
        sensor_data_t data;
        if (read_sensor_data(&data) == 0) {
            add_to_buffer(&buffer, data);
        }
        sleep(READ_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

