#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP810_ADDR    0x5B
#define LOG_FILE       "sdp810_log.txt"
#define SAMPLE_PERIOD  1.0
#define MEASURE_DELAY  0.045

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0x00, no final XOR) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler for graceful shutdown ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read one 9-byte measurement frame from the SDP810 ---- */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[9];

    /* Trigger a single measurement by writing a zero-length register */
    if (i2cWriteByte(handle, 0x00) < 0) {
        fprintf(stderr, "[ERROR] I2C write trigger failed\n");
        return -1;
    }

    time_sleep(MEASURE_DELAY);

    int n = i2cReadDevice(handle, (char *)buf, sizeof(buf));
    if (n != (int)sizeof(buf)) {
        fprintf(stderr, "[ERROR] I2C read returned %d bytes (expected %zu)\n",
                n, sizeof(buf));
        return -1;
    }

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor    = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "[ERROR] Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

/* ---- Log a sample to the CSV file ---- */
static int log_sample(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s for append\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "timestamp,pressure_Pa,temperature_C\n");

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "[INFO] SDP810 logger started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_handle, &pressure, &temperature) == 0) {
            if (log_sample(g_log_file, pressure, temperature) != 0)
                fprintf(stderr, "[WARN] Logging failed for this sample\n");
        } else {
            fprintf(stderr, "[WARN] Sensor read/CRC error — continuing\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    fprintf(stderr, "\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

