#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define DATA_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int read_sensor(int handle, float *pressure, float *temperature) {
    char cmd[2] = {0x36, 0x2F};
    char data[6];

    if (i2cWriteDevice(handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    gpioDelay(SAMPLE_DELAY_US);

    if (i2cReadDevice(handle, data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    uint32_t raw_pressure = ((uint32_t)(data[0] & 0x0F) << 16) |
                           ((uint32_t)data[1] << 8) |
                           (uint32_t)data[2];
    uint16_t raw_temperature = ((uint16_t)data[3] << 8) | (uint16_t)data[4];

    *pressure = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temperature / 100.0f;

    return 0;
}

int main(void) {
    int handle = -1;
    FILE *fp = NULL;
    char timestamp[32];
    float pressure, temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen(DATA_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open data file '%s'\n", DATA_FILE);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    while (running) {
        if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Error: Failed to get timestamp\n");
        } else {
            if (read_sensor(handle, &pressure, &temperature) == 0) {
                fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
                fflush(fp);
                printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);
            } else {
                fprintf(stderr, "%s,ERROR\n", timestamp);
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "\nExiting gracefully...\n");

    if (fp != NULL) {
        fclose(fp);
    }
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

