/*
 * Raspberry Pi 4 Model B – TDK ICP-10125 barometric pressure monitor
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2  (I2C bus 1)
 *   ICP-10125 SCL  -> GPIO3  (I2C bus 1)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *   LED anode      -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode    -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icp10125_mon icp10125_mon.c -lpigpio -lrt
 * Run:
 *   sudo ./icp10125_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- I2C / sensor constants ---- */
#define I2C_BUS          "/dev/i2c-1"
#define ICP10125_ADDR    0x40          /* 7-bit I2C address (ADDR pin tied to GND) */

/* ICP-10125 command opcodes (MSB first) */
#define CMD_READ_ID      0xEF
#define CMD_READ_PRESS   0x00
#define CMD_READ_TEMP    0x01

/* ICP-10125 ID register values */
#define ID_REG_EXPECTED  0x01

/* ICP-10125 conversion time (datasheet: ~5.5 ms max) */
#define CONV_DELAY_US    6000

/* ICP-10125 poll interval (1 Hz) */
#define POLL_DELAY_US    1000000

/* ---- GPIO / LED constants ---- */
#define LED_PIN          17
#define LED_ON_US        500000   /* 500 ms on  -> 1 Hz */
#define LED_OFF_US       500000   /* 500 ms off -> 1 Hz */
#define LED_WARN_ON_US   100000   /* 100 ms on  -> 5 Hz */
#define LED_WARN_OFF_US  100000   /* 100 ms off -> 5 Hz */

/* ---- Pressure threshold (Pa) ---- */
#define PRESSURE_THRESHOLD 95000.0

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits and resources are     */
/* released in main().                                                  */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-4 calculation (polynomial 0x13, init 0x00, no reflect, no XOR).   */
/* ICP-10125 uses CRC-4 as per the datasheet.                           */
/* ------------------------------------------------------------------ */
static uint8_t icp10125_crc4(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x08)
                crc = (uint8_t)((crc << 1) ^ 0x13);
            else
                crc = (uint8_t)(crc << 1);
            crc &= 0x0F;
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read a 6-byte measurement frame from the ICP-10125.                 */
/* Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.          */
/* ------------------------------------------------------------------ */
static int icp10125_read_measurement(int fd, uint8_t *buf)
{
    /* Read pressure (0x00), temperature (0x01), and CRC (0x02) */
    uint8_t cmd = CMD_READ_PRESS;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (trigger) failed: %s\n", strerror(errno));
        return -1;
    }

    /* Datasheet: conversion time ~5.5 ms; allow margin */
    usleep(CONV_DELAY_US);

    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
        if (n < 0)
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read short: got %zd of 6 bytes\n", n);
        return -1;
    }

    /* Verify CRC for pressure bytes */
    uint8_t crc = icp10125_crc4(&buf[0], 2);
    if (crc != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure data (calc=0x%02X, got=0x%02X)\n",
                crc, buf[2]);
        return -2;
    }

    /* Verify CRC for temperature bytes */
    crc = icp10125_crc4(&buf[3], 2);
    if (crc != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature data (calc=0x%02X, got=0x%02X)\n",
                crc, buf[5]);
        return -2;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw 16-bit big-endian values to physical units.             */
/* ------------------------------------------------------------------ */
static double raw_to_pressure(uint16_t raw)
{
    /* Datasheet: pressure range 300..1100 hPa, 1 hPa / LSB */
    return (double)raw * 1.0;          /* Pa */
}

static double raw_to_temperature(uint16_t raw)
{
    /* Datasheet: temperature range -40..85 °C, 0.01 °C / LSB */
    return (double)raw * 0.01;         /* °C */
}

/* ------------------------------------------------------------------ */
/* Verify sensor identity via the ID register.                        */
/* ------------------------------------------------------------------ */
static int icp10125_verify_id(int fd)
{
    uint8_t cmd = CMD_READ_ID;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (ID trigger) failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        if (n < 0)
            fprintf(stderr, "I2C read (ID) failed: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read (ID) short: got %zd of 2 bytes\n", n);
        return -1;
    }

    if (buf[0] != ID_REG_EXPECTED) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0x%02X)\n",
                buf[0], ID_REG_EXPECTED);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup – release I2C and GPIO resources.                           */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ICP10125_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor identity ---- */
    if (icp10125_verify_id(g_i2c_fd) != 0) {
        fprintf(stderr, "ICP-10125 not detected on %s\n", I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    printf("ICP-10125 monitoring started (I2C %s, addr 0x%02X, LED GPIO%d).\n",
           I2C_BUS, ICP10125_ADDR, LED_PIN);
    printf("Pressure threshold: %.0f Pa. Press Ctrl+C to exit.\n",
           PRESSURE_THRESHOLD);

    /* ---- Main polling loop ---- */
    while (g_running) {
        uint8_t buf[6];
        int rc = icp10125_read_measurement(g_i2c_fd, buf);

        if (rc == 0) {
            uint16_t raw_p = ((uint16_t)buf[0] << 8) | buf[1];
            uint16_t raw_t = ((uint16_t)buf[3] << 8) | buf[4];
            double pressure = raw_to_pressure(raw_p);
            double temperature = raw_to_temperature(raw_t);

            printf("Pressure: %.2f Pa | Temperature: %.2f °C\n",
                   pressure, temperature);

            /* Drive LED: normal 1 Hz when above threshold, 5 Hz below */
            if (pressure < PRESSURE_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
                usleep(LED_WARN_ON_US);
                gpioWrite(LED_PIN, 0);
                usleep(LED_WARN_OFF_US);
            } else {
                gpioWrite(LED_PIN, 1);
                usleep(LED_ON_US);
                gpioWrite(LED_PIN, 0);
                usleep(LED_OFF_US);
            }
        } else if (rc == -1) {
            /* I/O error – blink LED rapidly to indicate trouble */
            gpioWrite(LED_PIN, 1);
            usleep(LED_WARN_ON_US);
            gpioWrite(LED_PIN, 0);
            usleep(LED_WARN_OFF_US);
        } else {
            /* CRC mismatch – blink rapidly */
            gpioWrite(LED_PIN, 1);
            usleep(LED_WARN_ON_US);
            gpioWrite(LED_PIN, 0);
            usleep(LED_WARN_OFF_US);
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

