/*
 * MLX90614ESF-BAA Temperature Monitor with Fan Control
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Melexis MLX90614ESF-BAA
 * Fan:    GPIO18 (BCM) – active-high relay module assumed
 *
 * Build:  gcc -O2 -Wall -o temp_monitor temp_monitor.c -li2c -lm
 * Run:    sudo ./temp_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define MLX90614_ADDR    0x5A          /* MLX90614 default 7-bit address   */
#define FAN_GPIO         18            /* BCM pin for the cooling fan      */
#define TEMP_THRESHOLD   30.0          /* °C – fan ON above this            */
#define TEMP_HYSTERESIS  28.0          /* °C – fan OFF below this           */
#define LOG_FILE         "temperature_log.txt"
#define SAMPLE_PERIOD_S  2             /* seconds between samples          */
#define I2C_RETRY_COUNT  3             /* consecutive failures before giving up */
#define I2C_RETRY_DELAY_MS 10          /* ms between I2C retry attempts     */

/* MLX90614 register addresses (16-bit, big-endian on the bus) */
#define MLX90614_TA      0x06          /* ambient temperature               */
#define MLX90614_TO      0x08          /* object temperature                */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static int  g_fan_state = 0;          /* 0 = off, 1 = on                    */

/* --------------------------- Function prototypes ------------------------- */
static void  signal_handler(int sig);
static int   init_i2c(void);
static int   read_temperature(float *ambient, float *object);
static void  log_temperature(float ambient, float object);
static void  control_fan(float object_temp);
static void  cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C init -------------------------------- */
static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MLX90614_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* --------------------------- Read temperature ---------------------------- */
/*
 * Reads the ambient (TA) and object (TO) temperature registers.
 * Returns 0 on success, -1 on failure.
 */
static int read_temperature(float *ambient, float *object)
{
    uint8_t reg;
    uint8_t buf[4];
    int     attempt;

    for (attempt = 0; attempt < I2C_RETRY_COUNT; ++attempt) {
        /* Read 4 bytes starting at TA (0x06): TA[0..1], TO[0..1] */
        reg = MLX90614_TA;
        if (write(g_i2c_fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg select) failed (attempt %d/%d): %s\n",
                    attempt + 1, I2C_RETRY_COUNT, strerror(errno));
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        if (read(g_i2c_fd, buf, 4) != 4) {
            fprintf(stderr, "I2C read (4 bytes) failed (attempt %d/%d): %s\n",
                    attempt + 1, I2C_RETRY_COUNT, strerror(errno));
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        /* MLX90614 sends data big-endian */
        uint16_t raw_ambient = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t raw_object  = ((uint16_t)buf[2] << 8) | buf[3];

        /* Sanity-check: temperatures are typically positive */
        if (raw_ambient == 0 || raw_object == 0) {
            fprintf(stderr, "Invalid raw data (0x%04X, 0x%04X) – skipping\n",
                    raw_ambient, raw_object);
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        /* Convert to °C (simplified linear approximation) */
        *ambient = (float)raw_ambient * 0.02f - 273.15f;
        *object  = (float)raw_object  * 0.02f - 273.15f;

        return 0;
    }

