#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD_HIGH 0x2C
#define MEASURE_CMD_LOW 0x06
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define MEASUREMENT_DELAY_US 10000
#define SERVER_PORT 8080
#define SERVER_ADDR "127.0.0.1"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_socket = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    unsigned char data[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            retries--;
            if (retries > 0) usleep(RETRY_DELAY_US);
            continue;
        }

        usleep(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)data, 6) != 6) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            retries--;
            if (retries > 0) usleep(RETRY_DELAY_US);
            continue;
        }

        unsigned short temp_ticks = (data[0] << 8) | data[1];
        unsigned short hum_ticks = (data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)temp_ticks / 65535.0f;
        *humidity = 100.0f * (float)hum_ticks / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    return -1;
}

static int send_data_to_server(int sock, float temperature, float humidity) {
    char buffer[256];
    int len = snprintf(buffer, sizeof(buffer),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: text/html\r\n"
        "Connection: close\r\n"
        "\r\n"
        "<html><head><title>SHT40 Sensor Data</title></head>"
        "<body><h1>SHT40 Sensor Data</h1>"
        "<p>Temperature: %.2f &deg;C</p>"
        "<p>Humidity: %.2f %%</p>"
        "</body></html>", temperature, humidity);

    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "Error formatting HTTP response\n");
        return -1;
    }

    if (send(sock, buffer, len, 0) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(SERVER_ADDR);
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_socket, 3) < 0) {
        perror("listen");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", SERVER_PORT);

    while (running) {
        int client_socket = accept(server_socket, NULL, NULL);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }

        float temperature, humidity;
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f &deg;C, Humidity: %.2f %%\n", temperature, humidity);
            if (send_data_to_server(client_socket, temperature, humidity) != 0) {
                fprintf(stderr, "Error sending data to server\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after retries\n");
            const char *err_msg = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\nConnection: close\r\n\r\n<html><body><h1>Error: Sensor read failed</h1></body></html>";
            send(client_socket, err_msg, strlen(err_msg), 0);
        }

        close(client_socket);
    }

    printf("\nShutting down...\n");
    if (server_socket >= 0) close(server_socket);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

