            if (send_data_to_server(client_socket, temperature, humidity) != 0) {
                fprintf(stderr, "Error sending data to server\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after retries\n");
            const char *err_msg = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\nConnection: close\r\n\r\n<html><body><h1>Error: Sensor read failed</h1></body></html>";
            send(client_socket, err_msg, strlen(err_msg), 0);
        }

        close(client_socket);
    }

    printf("\nShutting down...\n");
    if (server_socket >= 0) close(server_socket);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

