/*
 * HDC2010 Temperature & Humidity Sensor Reader
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Texas Instruments HDC2010
 *   - I2C address 0x40 (7-bit)
 *   - MEASUREMENT_CONFIG register (0x0E) bit 0 = measurement start
 *   - Temperature register (0x00), Humidity register (0x02)
 *   - 16-bit signed, 0.01 °C / 0.040 %RH
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc2010 hdc2010.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC2010_ADDR             0x40
#define REG_TEMP                 0x00
#define REG_HUMID                0x02
#define REG_MEASUREMENT_CONFIG   0x0E
#define MEASURE_CMD              0x01   /* bit 0 = start measurement */
#define MEASURE_TIMEOUT_MS       500
#define POLL_INTERVAL_MS         5000
#define MAX_RETRIES              3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                              */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* HDC2010 sends MSB first */
    *out = (int16_t)((uint16_t)buf[0] << 8 | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                  */
/* ------------------------------------------------------------------ */

static int hdc2010_start_measurement(int fd)
{
    return i2c_write_reg8(fd, REG_MEASUREMENT_CONFIG, MEASURE_CMD);
}

static int hdc2010_wait_for_measurement(int fd)
{
    uint8_t cfg;
    int elapsed = 0;

    while (elapsed < MEASURE_TIMEOUT_MS) {
        if (i2c_read_reg16(fd, REG_MEASUREMENT_CONFIG, (int16_t *)&cfg) != 0)
            return -1;
        if ((cfg & 0x01) == 0)
            return 0;                       /* measurement complete */
        usleep(1000);                       /* 1 ms */
        elapsed++;
    }
    fprintf(stderr, "HDC2010 measurement timeout (%d ms)\n", MEASURE_TIMEOUT_MS);
    return -1;
}

static int hdc2010_read_temperature(int fd, float *temp)
{
    int16_t raw;
    if (i2c_read_reg16(fd, REG_TEMP, &raw) != 0)
        return -1;
    *temp = (float)raw * 0.01f;
    return 0;
}

static int hdc2010_read_humidity(int fd, float *hum)
{
    int16_t raw;
    if (i2c_read_reg16(fd, REG_HUMID, &raw) != 0)
        return -1;
    *hum = (float)raw * 0.040f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 --- */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire sensor address --- */
    if (ioctl(fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                HDC2010_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("HDC2010 sensor reader started (I2C addr 0x%02X).\n", HDC2010_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int retries = 0;

        /* --- Start a measurement --- */
        if (hdc2010_start_measurement(fd) != 0) {
            fprintf(stderr, "Failed to start measurement (sensor may be absent).\n");
            goto sleep_and_retry;
        }

        /* --- Wait for completion --- */
        if (hdc2010_wait_for_measurement(fd) != 0) {
            fprintf(stderr, "Measurement failed after %d retries.\n", MAX_RETRIES);
            goto sleep_and_retry;
        }

        /* --- Read both registers --- */
        while (retries < MAX_RETRIES && g_running) {
            if (hdc2010_read_temperature(fd, &temperature) == 0 &&
                hdc2010_read_humidity(fd, &humidity) == 0)
            {
                printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n",
                       temperature, humidity);
                rc = EXIT_SUCCESS;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES)
                usleep(100000);  /* 100 ms back-off before retry */
        }

        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n",
                    MAX_RETRIES);
            rc = EXIT_FAILURE;
        }

    sleep_and_retry:
        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < POLL_INTERVAL_MS / 100 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly.\n");

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

