/*
 * Raspberry Pi 3 Model B+ — Sensirion SDP800-500Pa differential pressure reader
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x4B (7-bit) when SA0 is low.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800 sdp800.c -lpigpio -lrt
 * Run:    sudo ./sdp800
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x4B          /* SA0 = GND */
#define READ_INTERVAL  500           /* ms between samples */
#define MEASURE_MS     45            /* SDP800 measurement time */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static bool crc8_ok(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* Read one 6-byte measurement frame from the SDP800                    */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t buf[6];

    /*
     * Trigger a single-shot differential pressure + temperature
     * measurement.  The SDP800 returns 6 bytes: pressure(2) + CRC(1)
