/*
 * Raspberry Pi 3 Model B+ — Sensirion SDP800-500Pa differential pressure reader
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x4B (7-bit) when SA0 is low.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800 sdp800.c -lpigpio -lrt
 * Run:    sudo ./sdp800
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x4B          /* SA0 = GND */
#define READ_INTERVAL  500           /* ms between samples */
#define MEASURE_MS     45            /* SDP800 measurement time */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
