/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static bool crc8_ok(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc == expected;
}

