    gpioDelay(MEASURE_MS * 1000);   /* microseconds */

    int n = i2cReadDevice(handle, (char *)buf, sizeof(buf));
    if (n != (int)sizeof(buf)) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %zu)\n",
                n, sizeof(buf));
        return -1;
    }

    /* Validate CRCs. */
    if (!crc8_ok(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] pressure CRC mismatch\n");
        return -1;
    }
    if (!crc8_ok(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return -1;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

