#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX6675_READ_ERROR -1000.0f
#define MAX6675_FAULT_ERROR -2000.0f

#define KP 1.0f
#define KI 0.01f
#define KD 0.1f
#define MAX_OUTPUT 1.0f
#define MIN_OUTPUT 0.0f
#define SAMPLE_INTERVAL_US 1000000
#define LOOP_PERIOD_S 1

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;

static float target_temps[100];
static int target_times[100];
static int profile_size = 0;
static int current_profile_index = 0;
static float integral = 0.0f;
static float previous_error = 0.0f;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static float read_max6675(void) {
    if (spi_fd < 0) return MAX6675_FAULT_ERROR;

    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return MAX6675_FAULT_ERROR;
    }

    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    if (raw & 0x0001) {
        return MAX6675_FAULT_ERROR;
    }

    return (float)((raw >> 3) * 0.25f);
}

static int load_profile(void) {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        perror("Failed to open profile file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (profile_size >= 100) {
            fprintf(stderr, "Profile too large\n");
            break;
        }
        if (sscanf(line, "%d,%f", &target_times[profile_size], &target_temps[profile_size]) == 2) {
            profile_size++;
        } else {
            fprintf(stderr, "Invalid line: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

static float pid_control(float current_temp) {
    float error = target_temps[current_profile_index] - current_temp;
    integral += error;
    float derivative = error - previous_error;
    float output = KP * error + KI * integral + KD * derivative;

    if (output > MAX_OUTPUT) output = MAX_OUTPUT;
    if (output < MIN_OUTPUT) output = MIN_OUTPUT;

    previous_error = error;
    return output;
}

static int set_relay(float duty_cycle) {
    if (!relay_line) return -1;
    int val = (duty_cycle > 0.0f) ? 1 : 0;
    if (gpiod_line_set_value(relay_line, val) < 0) {
        perror("Failed to set relay GPIO");
        return -1;
    }
    return 0;
}

static int log_data(float temp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, temp);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get relay GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "reflow_relay", 0) < 0) {
        perror("Failed to request relay GPIO as output");
        cleanup();
        return 1;
    }

    if (load_profile() < 0) {
        cleanup();
        return 1;
    }

    if (profile_size == 0) {
        fprintf(stderr, "No valid profile data\n");
        cleanup();
        return 1;
    }

    printf("Reflow oven started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp = read_max6675();
        if (temp <= MAX6675_FAULT_ERROR) {
            fprintf(stderr, "Error reading temperature (sensor fault or bus error)\n");
            set_relay(0.0f);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (temp < 0) {
            fprintf(stderr, "Error reading temperature (SPI read error)\n");
            set_relay(0.0f);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (temp > 150.0f) {
            fprintf(stderr, "Warning: Temperature exceeds 150°C (%.2f°C)\n", temp);
        }

        log_data(temp);

        if (temp >= target_temps[current_profile_index]) {
            current_profile_index++;
            if (current_profile_index >= profile_size) {
                current_profile_index = profile_size - 1;
            }
            integral = 0.0f;
            previous_error = 0.0f;
        }

        float duty_cycle = pid_control(temp);
        set_relay(duty_cycle);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

