#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define DS18B20_DIR "/sys/bus/w1/devices/"
#define DS18B20_FILE "w1_slave"
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL 5
#define MAX_SENSORS 10

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static int i2c_fd = -1;

typedef struct {
    float Kp, Ki, Kd;
    float integral, previous_error;
    float setpoint;
} PIDController;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ds18b20_temperature(const char *sensor_id, float *temperature) {
    char path[256];
    char buffer[256];
    int fd, bytes_read;
    char *temp_str;
    long temp_raw;

    snprintf(path, sizeof(path), "%s%s/w1_slave", DS18B20_DIR, sensor_id);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';
    close(fd);

    temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Error: Could not find temperature data in %s\n", path);
        return -1;
    }

    temp_str += 2;
    temp_raw = strtol(temp_str, NULL, 10);
    *temperature = (float)temp_raw / 1000.0;
    return 0;
}

static int find_ds18b20_sensors(char sensor_ids[][20], int max_sensors) {
    DIR *dir;
    struct dirent *ent;
    int sensor_count = 0;

    dir = opendir(DS18B20_DIR);
    if (dir == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", DS18B20_DIR, strerror(errno));
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && sensor_count < max_sensors) {
        if (strstr(ent->d_name, "28-") != NULL) {
            strncpy(sensor_ids[sensor_count], ent->d_name, sizeof(sensor_ids[sensor_count]) - 1);
            sensor_ids[sensor_count][sizeof(sensor_ids[sensor_count]) - 1] = '\0';
            sensor_count++;
        }
    }

    closedir(dir);
    return sensor_count;
}

static float calculate_average_temperature(const char sensor_ids[][20], int sensor_count) {
    float sum = 0.0;
    float temperature;
    int valid_readings = 0;

    for (int i = 0; i < sensor_count; i++) {
        if (read_ds18b20_temperature(sensor_ids[i], &temperature) == 0) {
            sum += temperature;
            valid_readings++;
        } else {
            fprintf(stderr, "Error reading sensor %s\n", sensor_ids[i]);
        }
    }

    if (valid_readings > 0) {
        return sum / valid_readings;
    } else {
        return -999.0;
    }
}

static float pid_control(PIDController *pid, float current_temperature) {
    float error = pid->setpoint - current_temperature;
    pid->integral += error;
    float derivative = error - pid->previous_error;
    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    pid->previous_error = error;
    return output;
}

static void set_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error writing to relay GPIO %d\n", RELAY_GPIO);
    }
}

static void set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(PWM_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle on GPIO %d\n", PWM_GPIO);
    }
}

static void log_data(float average_temperature, float setpoint, float pid_output, int pwm_duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp != NULL) {
        fprintf(log_fp, "%s, %.2f, %.2f, %.2f, %d\n", timestamp, average_temperature, setpoint, pid_output, pwm_duty_cycle);
        fflush(log_fp);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(int argc, char *argv[]) {
    char sensor_ids[MAX_SENSORS][20];
    int sensor_count;
    PIDController pid;
    float current_temperature, average_temperature, pid_output, pwm_duty_cycle;
    int pwm_value;

    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    pid.setpoint = atof(argv[1]);
    pid.Kp = atof(argv[2]);
    pid.Ki = atof(argv[3]);
    pid.Kd = atof(argv[4]);
    pid.integral = 0.0;
    pid.previous_error = 0.0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0 || gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0 || gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error setting PWM parameters\n");
        gpioTerminate();
        return 1;
    }

    set_relay(0);
    set_pwm_duty_cycle(0);

    sensor_count = find_ds18b20_sensors(sensor_ids, MAX_SENSORS);
    if (sensor_count < 0) {
        gpioTerminate();
        return 1;
    }

    if (sensor_count == 0) {
        fprintf(stderr, "Error: No DS18B20 sensors found. Check wiring and 1-wire bus.\n");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        average_temperature = calculate_average_temperature(sensor_ids, sensor_count);

        if (average_temperature > -999.0) {
            pid_output = pid_control(&pid, average_temperature);
            pwm_duty_cycle = (pid_output < 0) ? 0 : (pid_output > PWM_RANGE) ? PWM_RANGE : pid_output;
            pwm_value = (int)pwm_duty_cycle;

            if (pwm_value > 0) {
                set_relay(1);
            } else {
                set_relay(0);
            }
            set_pwm_duty_cycle(pwm_value);
            log_data(average_temperature, pid.setpoint, pid_output, pwm_value);
        } else {
            fprintf(stderr, "Error: Invalid temperature reading. Check sensor connection.\n");
            set_relay(0);
            set_pwm_duty_cycle(0);
        }

        sleep(SAMPLE_INTERVAL);
    }

    set_relay(0);
    set_pwm_duty_cycle(0);
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();
    return 0;
}

