/*
 * AHT20 humidity monitor with dehumidifier relay control.
 *
 * Board:  Raspberry Pi 5 (BCM numbering)
 * Bus:    /dev/i2c-1  (I2C bus 1 on the main GPIO header)
 * Sensor: AHT20 on I2C address 0x38
 * Relay:  GPIO17 (BCM 17) — active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o aht20_monitor aht20_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP       "gpiochip4"   /* BCM GPIO controller on Pi 5 */
#define GPIO_LINE       17
#define HUMIDITY_HIGH   60.0f
#define HUMIDITY_LOW    55.0f
#define POLL_INTERVAL   5            /* seconds */
#define MAX_RETRIES     3
#define MEASURE_DELAY   80           /* ms */
#define RETRY_DELAY     10           /* ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * Write a single command byte to the AHT20.
 * Returns 0 on success, -1 on failure.
 */
static int aht20_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the AHT20.
 * Returns 0 on success, -1 on failure.
 */
static int aht20_read_data(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/*
 * Trigger a measurement and read the 6-byte result.
 * Returns 0 on success and fills *humidity; -1 on failure.
 */
static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t data[6];

    /* 1. Power on / wake */
    if (aht20_write_cmd(fd, 0x00) < 0) return -1;

    /* 2. Trigger measurement */
    if (aht20_write_cmd(fd, 0xAC) < 0) return -1;
    if (aht20_write_cmd(fd, 0x33) < 0) return -1;
    if (aht20_write_cmd(fd, 0x00) < 0) return -1;

    /* 3. Wait for conversion (datasheet: 80 ms max) */
    sleep_ms(MEASURE_DELAY);

    /* 4. Read 6 bytes: status(1) + humidity(2) + temp(2) + CRC(1) */
    if (aht20_read_data(fd, data, sizeof(data)) < 0) return -1;

    /* 5. Verify status: bit 7 = 0 (calibrated), bit 0 = 0 (not busy) */
    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 not calibrated (status=0x%02X)\n", data[0]);
        return -1;
    }
    if (data[0] & 0x01) {
        fprintf(stderr, "AHT20 busy (status=0x%02X)\n", data[0]);
        return -1;
    }

    /* 6. Convert humidity: 16-bit, 2^16 counts = 100 %RH */
    uint16_t raw = ((uint16_t)data[1] << 8) | data[2];
    *humidity = (float)raw / 65536.0f * 100.0f;
    return 0;
}

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request relay line --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay, "aht20_dehum", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("AHT20 humidity monitor started.  Polling every %d s.\n",
           POLL_INTERVAL);
    printf("  Relay on BCM GPIO%d | High: %.1f%% | Low: %.1f%%\n",
           GPIO_LINE, HUMIDITY_HIGH, HUMIDITY_LOW);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main loop --- */
    while (g_running) {
        float humidity = 0.0f;
        int ok = 0;

        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
            if (aht20_read_humidity(fd, &humidity) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES) {
                sleep_ms(RETRY_DELAY);
            }
        }

        if (ok) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

            printf("[%s] Humidity: %.2f%%  ", ts, humidity);

            if (humidity > HUMIDITY_HIGH) {
                if (gpiod_line_set_value(relay, 1) < 0) {
                    fprintf(stderr, "Relay ON failed: %s\n", strerror(errno));
                } else {
                    printf("  [DEHUMIDIFIER ON]");
                }
            } else if (humidity < HUMIDITY_LOW) {
                if (gpiod_line_set_value(relay, 0) < 0) {
                    fprintf(stderr, "Relay OFF failed: %s\n", strerror(errno));
                } else {
                    printf("  [DEHUMIDIFIER OFF]");
                }
            }
            printf("\n");
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read humidity after %d attempts.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int s = 0; s < POLL_INTERVAL && g_running; ++s) {
            sleep_ms(1000);
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay) {
        gpiod_line_set_value(relay, 0);   /* ensure relay off */
        gpiod_line_release(relay);
    }
    if (chip)  gpiod_chip_close(chip);
    if (fd >= 0) close(fd);
    return ret;
