#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int htu21d_read_humidity(float *humidity) {
    uint8_t cmd[2] = {0xE5, 0x00};
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, cmd, 2) != 2) {
            syslog(LOG_ERR, "I2C write failed (humidity read): %s", strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

        usleep(50000);

        ssize_t n = read(i2c_fd, buf, 3);
        if (n != 3) {
            syslog(LOG_ERR, "I2C read failed (humidity read): expected 3 bytes, got %zd (%s)", n, strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint8_t crc = buf[2];
        uint8_t expected_crc = (uint8_t)(raw & 0x0003) ^ ((raw >> 2) & 0x000F) ^ ((raw >> 4) & 0x00FF) ^ ((raw >> 6) & 0x003F) ^ ((raw >> 8) & 0x00FF);
        if (crc != expected_crc) {
            syslog(LOG_ERR, "CRC mismatch: calculated 0x%02X, received 0x%02X", expected_crc, crc);
            retries++;
            sleep(1);
            continue;
        }

        *humidity = -6.0f + 125.0f * ((float)raw / 65536.0f);
        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;
        return 0;
    }
    return -1;
}

static int http_post(const char *data) {
    struct addrinfo hints, *res;
    int sockfd = -1;
    int ret = -1;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(NULL, "80", &hints, &res) != 0) {
        syslog(LOG_ERR, "getaddrinfo failed: %s", strerror(errno));
        return -1;
    }

    sockfd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (sockfd < 0) {
        syslog(LOG_ERR, "socket creation failed: %s", strerror(errno));
        freeaddrinfo(res);
        return -1;
    }

    if (connect(sockfd, res->ai_addr, res->ai_addrlen) < 0) {
        syslog(LOG_ERR, "connect failed: %s", strerror(errno));
        close(sockfd);
        freeaddrinfo(res);
        return -1;
    }
    freeaddrinfo(res);

    char request[512];
    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: api.example.com\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             API_ENDPOINT, strlen(data), data);

    if (write(sockfd, request, strlen(request)) < 0) {
        syslog(LOG_ERR, "HTTP POST write failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char response[1024];
    ssize_t n = read(sockfd, response, sizeof(response) - 1);
    if (n > 0) {
        response[n] = '\0';
        syslog(LOG_INFO, "HTTP Response: %s", response);
    } else {
        syslog(LOG_ERR, "HTTP read failed: %s", strerror(errno));
    }

    close(sockfd);
    return 0;
}

int main(void) {
    openlog("htu21d_humidity", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (i2c_init() < 0) {
        syslog(LOG_ERR, "I2C initialization failed, exiting.");
        closelog();
        return 1;
    }

    while (running) {
        float humidity;
        if (htu21d_read_humidity(&humidity) == 0) {
            char json[128];
            snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (http_post(json) < 0) {
                syslog(LOG_ERR, "HTTP POST failed.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity after %d retries.", MAX_RETRIES);
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    if (i2c_fd >= 0) close(i2c_fd);
    closelog();
    return 0;
}

