        fprintf(stderr, "BMP280 init failed\n");
        close(i2c_fd);
        return 1;
    }

    if (bmp280_read_calib(i2c_fd) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float pressure;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && !success) {
