/*
 * logger.c — Raspberry Pi 4B daily CSV logger
 *
 * Sensors:
 *   TMP117  temperature  on /dev/i2c-1, address 0x48
 *   AHT20   humidity     on /dev/i2c-1, address 0x38
 *   PIR     motion       on GPIO17 (gpiochip4 line 17, input)
 *
 * Build:  gcc -o logger logger.c -lgpiod -lrt
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38
#define PIR_LINE       17
#define PIR_CHIP       "gpiochip4"
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define SAMPLE_MS      1000
#define LOG_PREFIX     "data_"

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* TMP117 — 16-bit two's-complement, 0.0075 °C / LSB                   */
/* ------------------------------------------------------------------ */
static int tmp117_read(int fd, float *temp)
{
    uint8_t cmd = 0x00;                       /* temperature, single-shot */
    uint8_t buf[3];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "TMP117 write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);                             /* conversion ~1.5 ms */

    if (read(fd, buf, 3) != 3) {
        fprintf(stderr, "TMP117 read failed: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = raw * 0.0075f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* AHT20 — 20-bit humidity + 12-bit temperature, 80 ms max conversion   */
/* ------------------------------------------------------------------ */
static int aht20_read(int fd, float *hum, float *temp)
{
    uint8_t cmd = 0xAC;                       /* single measurement, clock-stretching */
    uint8_t buf[6];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "AHT20 write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(20000);                            /* 20 ms max conversion */

    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "AHT20 read failed: %s\n", strerror(errno));
        return -1;
    }

    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 not ready\n");
        return -1;
    }

    uint32_t hum_raw  = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
    uint32_t temp_raw = ((uint32_t)(buf[3] & 0x0F) << 16) | ((uint32_t)buf[4] << 8) | buf[5];

    *hum  = hum_raw  * 100.0f / 0x100000;
    *temp = temp_raw * 200.0f / 0x100000 - 50.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* PIR — library-level API call (gpioget)                             */
/* ------------------------------------------------------------------ */
static int pir_read(struct gpiod_line *line)
{
    int v = gpiod_line_get_value(line);
    if (v < 0)
        fprintf(stderr, "PIR read failed: %s\n", strerror(errno));
    return v;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temp, float hum, int motion)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir  = NULL;
    int  i2c_fd = -1;
    FILE *fp   = NULL;
    int  rc    = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- PIR via libgpiod ---- */
    chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", PIR_CHIP, strerror(errno));
        goto cleanup;
    }
    pir = gpiod_chip_get_line(chip, PIR_LINE);
    if (!pir) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", PIR_LINE, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(pir, "pir-logger") < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- I2C ---- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "TMP117 ioctl: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "AHT20 ioctl: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Log file (new at midnight) ---- */
    time_t now = time(NULL);
    struct tm tm;
    localtime_r(&now, &tm);
    char filename[128];
    strftime(filename, sizeof(filename), LOG_PREFIX "%Y-%m-%d.csv", &tm);

    fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        goto cleanup;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");

    printf("Logging to %s — Ctrl+C to stop\n", filename);

    /* ---- Main loop ---- */
    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int   ok   = 1;

        /* TMP117 */
        for (int r = 0; r < MAX_RETRIES && g_running; r++) {
            if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
                fprintf(stderr, "TMP117 ioctl: %s\n", strerror(errno));
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            if (tmp117_read(i2c_fd, &temp) == 0)
                break;
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (errno) {
            fprintf(stderr, "TMP117 read failed after %d retries\n", MAX_RETRIES);
            ok = 0;
        }

        /* AHT20 */
        for (int r = 0; r < MAX_RETRIES && g_running; r++) {
            if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
                fprintf(stderr, "AHT20 ioctl: %s\n", strerror(errno));
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            if (aht20_read(i2c_fd, &hum, &temp) == 0)
                break;
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (errno) {
            fprintf(stderr, "AHT20 read failed after %d retries\n", MAX_RETRIES);
            ok = 0;
        }

        /* PIR */
        int motion = pir_read(pir);
        if (motion < 0)
            ok = 0;

        if (ok)
            log_data(fp, temp, hum, motion);

        /* Daily rollover */
        time_t now = time(NULL);
        struct tm tm;
        localtime_r(&now, &tm);
        if (tm.tm_hour == 0 && tm.tm_min == 0 && tm.tm_sec < 5) {
            fclose(fp);
            fp = NULL;
            strftime(filename, sizeof(filename), LOG_PREFIX "%Y-%m-%d.csv", &tm);
            fp = fopen(filename, "a");
            if (!fp) {
                fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
                g_running = 0;
            } else {
                fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
            }
        }

        usleep(SAMPLE_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp)  fclose(fp);
    if (i2c_fd >= 0) close(i2c_fd);
    if (pir)  gpiod_line_release(pir);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

