#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_SEC 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_msg(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int motor_init(void) {
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        log_msg("Error: failed to set ENA pin mode");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        log_msg("Error: failed to set IN1 pin mode");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        log_msg("Error: failed to set IN2 pin mode");
        return -1;
    }
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        log_msg("Error: failed to initialize ENA pin low");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        log_msg("Error: failed to initialize IN1 pin low");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_msg("Error: failed to initialize IN2 pin low");
        return -1;
    }
    return 0;
}

static int motor_stop(void) {
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        log_msg("Error: failed to stop motor (ENA low)");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        log_msg("Error: failed to stop motor (IN1 low)");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_msg("Error: failed to stop motor (IN2 low)");
        return -1;
    }
    return 0;
}

static int motor_run(void) {
    if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
        log_msg("Error: failed to set ENA high");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        log_msg("Error: failed to set IN1 high");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_msg("Error: failed to set IN2 low");
        return -1;
    }
    return 0;
}

static int rain_detected(void) {
    int val = gpioRead(RAIN_SENSOR_PIN);
    if (val < 0) {
        log_msg("Error: failed to read rain sensor");
        return -1;
    }
    return (val == 0) ? 1 : 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d)\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        log_msg("Error: failed to set rain sensor pin mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (motor_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_msg("Warning: failed to install SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_msg("Warning: failed to install SIGTERM handler");
    }

    log_msg("Rain sensor monitoring started (GPIO17). Press Ctrl+C to exit.");

    while (g_running) {
        int rain = rain_detected();
        if (rain < 0) {
            log_msg("Error: rain detection failed, retrying in 2s");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (rain) {
            log_msg("Rain detected! Closing window...");
            if (motor_run() < 0) {
                log_msg("Error: motor start failed, continuing to poll");
            } else {
                for (int i = 0; i < MOTOR_RUN_SEC && g_running; i++) {
                    sleep(1);
                }
                if (motor_stop() < 0) {
                    log_msg("Error: motor stop failed");
                } else {
                    log_msg("Window closed.");
                }
            }
        }

        if (g_running) {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    log_msg("Shutting down...");
    motor_stop();
    gpioTerminate();
    log_msg("Cleanup complete.");
    return EXIT_SUCCESS;
}

