/*
 * CPU Load RGB LED indicator for Raspberry Pi Zero W
 *
 * Wiring (common-anode RGB LED):
 *   Red   cathode -> GPIO17 (PWM0)
 *   Green cathode -> GPIO22 (PWM1)
 *   Blue  cathode -> GPIO27 (PWM2)
 *
 * Build: gcc -O2 -Wall -o cpu_led cpu_led.c -lpigpio -lrt
 * Run:   sudo ./cpu_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

/* Common-anode: 0 = full brightness, 255 = off */
#define PWM_RANGE 255

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CPU load reading                                                    */
/* ------------------------------------------------------------------ */
static int read_cpu_load(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    int matched = fscanf(fp,
        "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
        &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);
    fclose(fp);

    if (matched != 10) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        return -1;
    }

    static unsigned long long prev_idle = 0, prev_total = 0;
    unsigned long long idle_now = idle + iowait;
    unsigned long long total = user + nice + system + idle_now + irq + softirq + steal;

    unsigned long long total_diff = total - prev_total;
    unsigned long long idle_diff  = idle_now - prev_idle;

    if (total_diff == 0) {
        /* Avoid division by zero after first sample */
        prev_idle = idle_now;
        prev_total = total;
        return 0;
    }

    unsigned long long load = (total_diff > idle_diff)
        ? ((total_diff - idle_diff) * 100) / total_diff
        : 0;

    prev_idle = idle_now;
    prev_total = total;

    return (int)load;
}

/* ------------------------------------------------------------------ */
/* Color mapping                                                       */
/* ------------------------------------------------------------------ */
static void map_load_to_color(int load, int *r, int *g, int *b)
{
    if (load < 0)   { *r = 0; *g = 0; *b = 0; return; }
    if (load == 0)  { *r = 0; *g = 255; *b = 0; return; }
    if (load <= 50) { *r = 0; *g = 255; *b = 0; return; }
    if (load <= 100) { *r = 255; *g = 255; *b = 0; return; }
    *r = 255; *g = 0; *b = 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void set_led_color(int r, int g, int b)
{
    /* Common-anode: invert duty cycle */
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

static void led_off(void)
{
    set_led_color(0, 0, 0);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM pins --- */
