        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set PWM range (0-255) --- */
    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0)
    {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure LED is off at start --- */
    led_off();

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CPU Load RGB LED indicator running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int load = read_cpu_load();
        if (load < 0) {
            /* Sensor read failed; turn off LED for safety */
            led_off();
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int r, g, b;
        map_load_to_color(load, &r, &g, &b);
        set_led_color(r, g, b);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- Graceful shutdown --- */
    led_off();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

