/*
 * MAX31855 thermocouple fan controller for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MAX31855 VIN  -> 3V3 (Pin 1)
 *   MAX31855 GND  -> GND (Pin 6)
 *   MAX31855 CLK  -> GPIO11 (SPI0 SCLK, Pin 23)
 *   MAX31855 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *   MAX31855 DO   -> GPIO9  (SPI0 MISO, Pin 21)
 *   Fan PWM       -> GPIO18 (Pin 12) via hardware PWM
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o fan_ctrl fan_ctrl.c -lpigpio -lrt
 * Run:
 *   sudo ./fan_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)  */
#define SPI_SPEED      500000     /* 500 kHz            */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define FAN_GPIO       18          /* Hardware PWM pin   */
#define PWM_FREQ       1000        /* 1 kHz              */
#define PWM_RANGE      255         /* Duty 0..255        */

#define TEMP_BUFFER_SIZE 20
#define SAMPLE_INTERVAL  1          /* seconds            */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static double   g_temp_buffer[TEMP_BUFFER_SIZE];
static int      g_duty_buffer[TEMP_BUFFER_SIZE];
static time_t   g_time_buffer[TEMP_BUFFER_SIZE];
static int      g_buf_idx = 0;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  read_max31855(double *temp_c);
static int  set_fan_duty(int duty);
static void print_buffer(void);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MAX31855 read ----------------------------- */
/*
 * MAX31855 32-bit SPI payload (MSB first):
 *   D[31:18]  Thermocouple temperature, 14-bit signed, 0.25 °C / LSB
 *   D[17]     Reserved
 *   D[16]     Fault / open-circuit / short-circuit
 *   D[15:4]   Internal / cold-junction temperature, 12-bit signed, 0.0625 °C / LSB
 *   D[3]      Reserved
 *   D[2]      SCV fault (short to VCC)
 *   D[1]      SCG fault (short to GND)
 *   D[0]      OC  fault (open circuit)
 *
 * Returns 0 on success and stores temperature in *temp_c; returns -1 on error.
 */
static int read_max31855(double *temp_c)
{
    char rx[4] = {0, 0, 0, 0};
    int  status;

    status = spiRead(g_spi_handle, rx, 4);
    if (status != 4) {
        fprintf(stderr, "[ERROR] spiRead returned %d (expected 4)\n", status);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Fault bit D16 */
    if (raw & 0x00010000) {
        if (raw & 0x00000004) fprintf(stderr, "[FAULT] Open circuit\n");
        if (raw & 0x00000002) fprintf(stderr, "[FAULT] Short to GND\n");
        if (raw & 0x00000001) fprintf(stderr, "[FAULT] Short to VCC\n");
        return -1;
    }

    /* Thermocouple temperature: bits D31..D18, signed 14-bit */
    int16_t tc_raw = (int16_t)(raw >> 18);
    *temp_c = tc_raw * 0.25;
    return 0;
}

/* ----------------------------- Fan control ------------------------------- */
static int set_fan_duty(int duty)
{
    if (duty < 0)   duty = 0;
    if (duty > 255) duty = 255;

    if (gpioPWM(FAN_GPIO, duty) < 0) {
        fprintf(stderr, "[ERROR] gpioPWM(%d) failed\n", duty);
        return -1;
    }
    return 0;
}

/* ----------------------------- Circular buffer --------------------------- */
static void print_buffer(void)
{
    printf("\n--- Temperature / Duty Cycle Log (%d entries) ---\n",
           TEMP_BUFFER_SIZE);
    for (int i = 0; i < TEMP_BUFFER_SIZE; i++) {
        char ts[32];
        struct tm tm_info;
        time_t t = g_time_buffer[i];
        if (localtime_r(&t, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts, sizeof(ts), "unknown");
        }
        printf("  [%2d] %s  T=%.2f C  PWM=%d\n",
               i, ts, g_temp_buffer[i], g_duty_buffer[i]);
    }
    printf("--- End of Log ---\n\n");
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    /* Ensure fan is off before terminating pigpio */
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 500 kHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[FATAL] spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure fan PWM pin --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "[FATAL] gpioSetPWMfrequency(%d, %d) failed\n",
                FAN_GPIO, PWM_FREQ);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "[FATAL] gpioSetPWMrange(%d, %d) failed\n",
                FAN_GPIO, PWM_RANGE);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "[FATAL] gpioPWM(%d, 0) initialisation failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("MAX31855 fan controller started.\n");
    printf("  SPI channel : %d @ %d Hz, mode 0\n", SPI_CHANNEL, SPI_SPEED);
    printf("  Fan PWM     : GPIO%d @ %d Hz, range %d\n", FAN_GPIO, PWM_FREQ, PWM_RANGE);
    printf("  Sampling    : every %d s\n", SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main loop --- */
    while (g_running) {
        double temp_c = 0.0;
        int    duty   = 0;

        if (read_max31855(&temp_c) != 0) {
            fprintf(stderr, "[WARN] MAX31855 read failed; skipping fan update.\n");
        } else {
            /* Piecewise fan curve */
            if (temp_c < 25.0) {
                duty = 0;
            } else if (temp_c < 40.0) {
                duty = (int)((temp_c - 25.0) * 50.0 / 15.0);
            } else if (temp_c < 60.0) {
                duty = (int)((temp_c - 40.0) * 150.0 / 20.0) + 50;
            } else {
                duty = 255;
            }

            if (set_fan_duty(duty) != 0) {
                fprintf(stderr, "[WARN] Failed to set fan duty.\n");
            }
        }

        /* --- Circular buffer --- */
        g_temp_buffer[g_buf_idx]  = temp_c;
        g_duty_buffer[g_buf_idx]  = duty;
        g_time_buffer[g_buf_idx]  = time(NULL);
        g_buf_idx = (g_buf_idx + 1) % TEMP_BUFFER_SIZE;

        printf("T=%.2f C  PWM=%d\n", temp_c, duty);

        /* Sleep SAMPLE_INTERVAL seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL && g_running; s++) {
            sleep(1);
        }
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

