#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 2
#define LOG_FILE "altitude_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration_data(int fd) {
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MD, &md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    usleep(5000);
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    usleep(2000 + (3000 << BMP180_OSS));
    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *up = ((int32_t)msb << 16 | (int32_t)lsb << 8 | (int32_t)xlsb) >> (8 - BMP180_OSS);
    return 0;
}

static int calculate_b5(int32_t ut, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    *b5_out = x1 + x2;
    return 0;
}

static int calculate_temperature(int32_t b5, float *temp) {
    *temp = ((b5 + 8) >> 4) / 10.0f;
    return 0;
}

static int calculate_pressure(int32_t up, int32_t b5, float *pressure) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *pressure = (float)(p + ((x1 + x2 + 3791) >> 4));
    return 0;
}

static int log_data(float temp, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, pressure) < 0) return -1;
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (line) { gpiod_line_release(line); line = NULL; }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c bus"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) { perror("ioctl I2C_SLAVE"); cleanup(); return 1; }

    if (read_calibration_data(i2c_fd) < 0) { fprintf(stderr, "Failed to read calibration data\n"); cleanup(); return 1; }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) { perror("gpiod_chip_open"); cleanup(); return 1; }
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) { perror("gpiod_chip_get_line"); cleanup(); return 1; }
    if (gpiod_line_request_falling_edge_events(line, "bmp180_int") < 0) { perror("gpiod_line_request_falling_edge_events"); cleanup(); return 1; }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) { perror("fopen log"); cleanup(); return 1; }

    printf("BMP180 logging started. Press Ctrl+C to exit.\n");

    while (running) {
        struct timespec ts = {1, 0};
        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) { perror("gpiod_line_event_wait"); break; }
        if (ret > 0) {
            int32_t ut, up, b5;
            if (read_raw_temperature(i2c_fd, &ut) < 0) { fprintf(stderr, "Temp read error\n"); continue; }
            if (read_raw_pressure(i2c_fd, &up) < 0) { fprintf(stderr, "Pressure read error\n"); continue; }
            calculate_b5(ut, &b5);
            float temp, pressure;
            calculate_temperature(b5, &temp);
            calculate_pressure(up, b5, &pressure);
            if (log_data(temp, pressure) < 0) { fprintf(stderr, "Log write error\n"); break; }
        }
    }

    cleanup();
    return 0;
}

