/*
 * MAX31865 RTD-to-Digital Converter Reader for Raspberry Pi 5
 *
 * Wiring:
 *   MAX31865 VIN  -> 3.3V (Pin 1)
 *   MAX31865 GND  -> GND  (Pin 9)
 *   MAX31865 CLK  -> GPIO11 (SPI0 SCLK, Pin 23)
 *   MAX31865 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *   MAX31865 DO   -> GPIO9  (SPI0 MISO, Pin 21)
 *   MAX31865 VBIAS-> 3.3V (Pin 1)  (bias enabled)
 *
 * Build: gcc -O2 -Wall -o rtd_logger rtd_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define LOG_FILE        "rtd_log.csv"
#define SAMPLE_INTERVAL 5          /* seconds */

/* MAX31865 register addresses */
#define MAX31865_REG_CONFIG  0x00
#define MAX31865_REG_RTD_MSB 0x01
#define MAX31865_REG_RTD_LSB 0x02
#define MAX31865_REG_FAULT   0x03

/* Config register bits */
#define CONFIG_VBIAS        0x80
#define CONFIG_3WIRE        0x40
#define CONFIG_FAULTSTAT    0x04
#define CONFIG_FAULT_AUTO   0x02
#define CONFIG_FAULT_CLEAR  0x01

/* Fault status bits */
#define FAULT_OPEN          0x01
#define FAULT_GND           0x02
#define FAULT_VBIAS         0x04
#define FAULT_HOT           0x08
#define FAULT_COLD          0x10

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_xfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int max31865_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };
    return spi_xfer(fd, tx, rx, 2);
}

static int max31865_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };
    if (spi_xfer(fd, tx, rx, 2) < 0)
        return -1;
    *value = rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* MAX31865 configuration                                              */
/* ------------------------------------------------------------------ */
static int max31865_init(int fd)
{
    /* 3-wire mode, VBIAS enabled, fault status auto-clear */
    uint8_t cfg = CONFIG_VBIAS | CONFIG_3WIRE | CONFIG_FAULT_AUTO;
    if (max31865_write_reg(fd, MAX31865_REG_CONFIG, cfg) < 0) {
        fprintf(stderr, "Failed to write config register\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Fault handling                                                      */
/* ------------------------------------------------------------------ */
static void handle_fault(uint8_t fault_status)
{
    if (fault_status & FAULT_OPEN)
        fprintf(stderr, "Fault: Open circuit detected\n");
    if (fault_status & FAULT_GND)
        fprintf(stderr, "Fault: Short to GND detected\n");
    if (fault_status & FAULT_VBIAS)
        fprintf(stderr, "Fault: VBIAS fault (sensor absent or wiring fault)\n");
    if (fault_status & FAULT_HOT)
        fprintf(stderr, "Fault: RTD thermocouple too hot\n");
    if (fault_status & FAULT_COLD)
        fprintf(stderr, "Fault: RTD thermocouple too cold\n");
}

/* ------------------------------------------------------------------ */
/* Temperature computation (Callendar-Van Dusen)                       */
/* ------------------------------------------------------------------ */
static float rtd_to_celsius(uint16_t rtd_code)
{
    if (rtd_code == 0x0000)
        return -273.15f;  /* absolute zero */

    /* 3-wire mode: 11 bits data, 1 null bit */
    uint16_t rtd_data = rtd_code >> 1;
    float rtd_resistance = (float)rtd_data * 0.00390625f;  /* 0.25 mΩ / LSB */

    /* Callendar-Van Dusen (alpha, beta, R0, T0) */
    const float a = -3.9083e-3f;
    const float b = -5.775e-7f;
    const float r0 = 100.0f;
    const float t0 = 298.15f;
    const float r = rtd_resistance;
    const float t = t0 * (1.0f + a * (r / r0) + b * (r / r0) * (r / r0));

    return t - 273.15f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_temperature(float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MAX31865 */
    if (max31865_init(g_spi_fd) < 0) {
        fprintf(stderr, "MAX31865 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature_C\n");
        fflush(g_log_fp);
    }

    printf("MAX31865 RTD logger started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t rtd_msb = 0, rtd_lsb = 0, fault_status = 0;

        /* Read RTD MSB */
        if (max31865_read_reg(g_spi_fd, MAX31865_REG_RTD_MSB, &rtd_msb) < 0) {
            fprintf(stderr, "SPI read error (RTD MSB)\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Read RTD LSB */
        if (max31865_read_reg(g_spi_fd, MAX31865_REG_RTD_LSB, &rtd_lsb) < 0) {
            fprintf(stderr, "SPI read error (RTD LSB)\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Read fault status */
        if (max31865_read_reg(g_spi_fd, MAX31865_REG_FAULT, &fault_status) < 0) {
            fprintf(stderr, "SPI read error (fault status)\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (fault_status & CONFIG_FAULTSTAT) {
            handle_fault(fault_status);
            /* Clear fault by writing FAULT_AUTO | FAULT_CLEAR */
            uint8_t cfg = CONFIG_VBIAS | CONFIG_3WIRE | CONFIG_FAULT_AUTO | CONFIG_FAULT_CLEAR;
            max31865_write_reg(g_spi_fd, MAX31865_REG_CONFIG, cfg);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        uint16_t rtd_code = ((uint16_t)rtd_msb << 8) | rtd_lsb;
        float temperature = rtd_to_celsius(rtd_code);

        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

