/*
 * BMP180 Pressure Monitor — Raspberry Pi 4 Model B
 *
 * Samples the BMP180 on I2C bus 1 (address 0x77) every 50 ms using the
 * pigpio hardware timer, stores timestamped pressure readings in a
 * 60-second rolling buffer, computes a rolling average, and asserts
 * an active-HIGH alert on GPIO24 when the current pressure deviates
 * by more than 5 hPa from the rolling average.
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_monitor bmp180_monitor.c -lpigpio -lrt
 * Run:    sudo ./bmp180_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP180 constants (from datasheet) ---- */
#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE     0x34
#define BMP180_OSS             3

/* ---- Application constants ---- */
#define I2C_BUS                 1
#define ALERT_GPIO              24
#define SAMPLE_PERIOD_US        50000   /* 50 ms */
#define BUFFER_SIZE             60      /* seconds */
#define PRESSURE_THRESHOLD_HPA  5.0f
#define TIMER_ID                0       /* pigpio hardware timer 0 */

/* ---- Data structures ---- */
typedef struct {
    time_t timestamp;
    float  pressure_hpa;
} PressureReading;

typedef struct {
    PressureReading readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

/* ---- Globals (minimal) ---- */
static int            g_i2c_handle = -1;
static CircularBuffer g_buffer;
static volatile sig_atomic_t g_running = 1;

/* ---- Prototypes ---- */
static int  bmp180_read_raw_temperature(int handle, int32_t *raw);
static int  bmp180_read_raw_pressure(int handle, int32_t *raw);
static int  bmp180_read_pressure_hpa(int handle, float *pressure);
static void buffer_init(CircularBuffer *buf);
static void buffer_add(CircularBuffer *buf, float pressure);
static float buffer_average(const CircularBuffer *buf);
static void alert_set(int gpio, int level);
static void timer_callback(void *userdata);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- BMP180 helpers ---- */

/*
 * Read the raw 16-bit temperature value from the BMP180.
 * Returns 0 on success, -1 on I2C failure.
 */
static int bmp180_read_raw_temperature(int handle, int32_t *raw)
{
    char cmd = BMP180_CMD_TEMP;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "[BMP180] I2C write (temperature command) failed\n");
        return -1;
    }
    gpioDelay(5000);  /* 4.5 ms max conversion time */

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[BMP180] I2C read (temperature data) failed\n");
        return -1;
    }
    *raw = (int32_t)((uint8_t)buf[0] << 8 | (uint8_t)buf[1]);
    return 0;
}

/*
 * Read the raw 24-bit pressure value from the BMP180.
 * Returns 0 on success, -1 on I2C failure.
 */
static int bmp180_read_raw_pressure(int handle, int32_t *raw)
{
    char cmd = BMP180_CMD_PRESSURE | (BMP180_OSS << 6);
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "[BMP180] I2C write (pressure command) failed\n");
        return -1;
    }
    gpioDelay(2000 + (3000 << BMP180_OSS));  /* conversion time */

    char buf[3];
    if (i2cReadDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[BMP180] I2C read (pressure data) failed\n");
        return -1;
    }
    *raw = ((int32_t)(uint8_t)buf[0] << 16 |
            (int32_t)(uint8_t)buf[1] << 8  |
            (int32_t)(uint8_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

/*
 * Convert raw BMP180 pressure to hPa using the datasheet formula.
 * Returns 0 on success, -1 on I2C failure.
 */
static int bmp180_read_pressure_hpa(int handle, float *pressure)
{
    int32_t ut, up;
    if (bmp180_read_raw_temperature(handle, &ut) != 0)
        return -1;
    if (bmp180_read_raw_pressure(handle, &up) != 0)
        return -1;

    /* B5 = UT - 4000 */
    int32_t x1 = ((ut - 32768) * 5 + 16384) >> 15;
    int32_t x2 = (x1 * x1) >> 11;
    int32_t b5 = x1 + x2;

    /* B6 = B5 - 4000 */
    int32_t b6 = b5 - 4000;
    x1 = (b6 * b6) >> 12;
    x1 = (x1 * 3038) >> 16;
    x2 = (b6 * 6250) >> 12;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((b6 * 6250) + 128) >> 8) + x3;

    x1 = (b6 * b6) >> 12;
    x1 = (x1 * 3038) >> 16;
    x2 = (b6 * 6250) >> 12;
    x3 = x1 + x2;
    uint32_t b4 = (uint32_t)(x3 + 32768) * 1000 >> 15;
    uint32_t b7 = ((uint32_t)up - b4) * (50000 >> BMP180_OSS);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b3;
    else
        p = (b7 / b3) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    *pressure = (float)p / 100.0f;
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(CircularBuffer *buf)
{
    buf->head  = 0;
    buf->count = 0;
}

static void buffer_add(CircularBuffer *buf, float pressure)
{
    buf->readings[buf->head].timestamp  = time(NULL);
    buf->readings[buf->head].pressure_hpa = pressure;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static float buffer_average(const CircularBuffer *buf)
{
    if (buf->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buf->count; i++)
        sum += buf->readings[i].pressure_hpa;
    return sum / (float)buf->count;
}

/* ---- GPIO helpers ---- */
static void alert_set(int gpio, int level)
{
    if (gpioWrite(gpio, level) != 0)
        fprintf(stderr, "[GPIO] Failed to write GPIO %d to %d\n", gpio, level);
}

/* ---- Timer callback (runs in pigpio thread) ---- */
static void timer_callback(void *userdata)
{
    (void)userdata;

    float pressure;
    if (bmp180_read_pressure_hpa(g_i2c_handle, &pressure) != 0) {
        fprintf(stderr, "[BMP180] Sensor read failed — skipping sample\n");
        return;
    }

    buffer_add(&g_buffer, pressure);
    float avg = buffer_average(&g_buffer);

    if (g_buffer.count < BUFFER_SIZE) {
        /* Not enough samples yet — no alert yet */
        return;
    }

    if (pressure > avg + PRESSURE_THRESHOLD_HPA ||
        pressure < avg - PRESSURE_THRESHOLD_HPA) {
        alert_set(ALERT_GPIO, 1);
        fprintf(stderr,
                "[ALERT] Pressure %.2f hPa deviates %.2f hPa from rolling avg %.2f hPa\n",
                pressure, PRESSURE_THRESHOLD_HPA, avg);
    } else {
        alert_set(ALERT_GPIO, 0);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    alert_set(ALERT_GPIO, 0);
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    alert_set(ALERT_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (err %d)\n",
                I2C_BUS, BMP180_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    buffer_init(&g_buffer);

    /* Register signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Start 50 ms hardware timer */
    if (gpioSetTimerFuncEx(TIMER_ID, SAMPLE_PERIOD_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set hardware timer %d\n", TIMER_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 monitoring started. Sampling every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    /* Main loop — sleep until signal */
    while (g_running)
        sleep(1);

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

