    x2 = (-7357 * p) >> 16;
    return (float)(p + ((x1 + x2 + 3791) >> 4));
}

static void timer_callback(void *arg) {
    (void)arg;
    if (i2c_fd < 0) return;
    int32_t ut, up;
    if (read_raw_temperature(i2c_fd, &ut) < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return;
    }
    if (read_raw_pressure(i2c_fd, &up) < 0) {
        fprintf(stderr, "Error reading pressure: %s\n", strerror(errno));
        return;
    }
    bmp180_cal_t cal;
    if (read_calibration(i2c_fd, &cal) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return;
    }
    float temp = calculate_temperature(ut, &cal);
    float pres = calculate_pressure(up, ut, &cal);
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s, Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temp, pres);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(i2c_fd, &cal) < 0) {
        fprintf(stderr, "BMP180 not detected or calibration read failed: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct sigevent sev = {0};
    sev.sigev_notify = SIGEV_THREAD;
    sev.sigev_notify_function = timer_callback;
    sev.sigev_value.sival_ptr = NULL;
    timer_t timerid;
    if (timer_create(CLOCK_MONOTONIC, &sev, &timerid) < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    struct itimerspec its = {0};
    its.it_interval.tv_sec = TIMER_INTERVAL_MS / 1000;
    its.it_interval.tv_nsec = (TIMER_INTERVAL_MS % 1000) * 1000000L;
    its.it_value = its.it_interval;
    if (timer_settime(timerid, 0, &its, NULL) < 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        timer_delete(timerid);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    printf("BMP180 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        pause();
    }

    timer_delete(timerid);
    fclose(log_file);
    close(i2c_fd);
    printf("BMP180 logging stopped.\n");
    return 0;
}

