        fprintf(stderr, "Error setting PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error setting PWM range to %d\n", PWM_RANGE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_fan_speed(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp;
        if (read_temperature(&temp) != 0) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int duty = map_temperature_to_duty(temp);
        if (set_fan_speed(duty) != 0) {
            fprintf(stderr, "Error setting fan speed, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
