        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0);
    gpioTerminate();
    printf("Fan stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

