    return (double)p / 25600.0;
}

static int log_data(FILE *fp, double temp, double press) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(fp, "%s, Temperature: %.2f C, Pressure: %.2f hPa\n", ts, temp, press) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    int addr = BMP280_I2C_ADDR_DEFAULT;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return 1;
    }
    if (bmp280_init(fd) != 0) {
        fprintf(stderr, "BMP280 init failed at 0x%02X. Trying 0x%02X...\n", addr, BMP280_I2C_ADDR_ALT);
        addr = BMP280_I2C_ADDR_ALT;
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", addr, strerror(errno));
            close(fd);
            return 1;
        }
        if (bmp280_init(fd) != 0) {
            fprintf(stderr, "BMP280 init failed at 0x%02X. Exiting.\n", addr);
            close(fd);
            return 1;
        }
    }

    uint16_t dig_T1, dig_P1;
    int16_t dig_T2, dig_T3, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    if (bmp280_read_calibration(fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3, &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9) != 0) {
        fprintf(stderr, "Calibration read failed. Exiting.\n");
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    while (g_running) {
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(fd, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "Sensor read failed. Continuing.\n");
        } else {
            double temp = bmp280_compensate_temp(raw_t, &dig_T1, &dig_T2, &dig_T3);
            double press = bmp280_compensate_press(raw_p, (int32_t)temp, &dig_P1, &dig_P2, &dig_P3, &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9);
            if (log_data(fp, temp, press) != 0) {
                fprintf(stderr, "Logging failed. Continuing.\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return 0;
}

