/*
 * LM75 temperature monitor with alert LED on Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - LM75 sensor on I2C bus 1, address 0x48 (A0=A1=A2=0).
 *   - Alert LED on GPIO18 (BCM) with appropriate series resistor.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lm75_monitor lm75_monitor.c -lpigpio -lpthread
 * Run:
 *   sudo ./lm75_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define LM75_ADDR            0x48
#define ALERT_GPIO           18
#define TEMP_THRESHOLD       28.0f   /* °C — alert when above this */
#define BUFFER_SIZE          60
#define SAMPLE_PERIOD_US     1000000 /* 1 second */
#define POLL_DELAY_US        100000  /* 100 ms back-off on error */
#define I2C_RETRY_COUNT      3
#define I2C_RETRY_DELAY_US   100000  /* 100 ms between retries */

/* LM75 register addresses (8-bit, no register pointer needed after power-up) */
#define LM75_REG_TEMP        0x00
#define LM75_REG_CONFIG      0x01
#define LM75_REG_THYST       0x02
#define LM75_REG_TOS         0x03

/* LM75 config register bits */
#define LM75_CFG_SHUTDOWN    0x80
#define LM75_CFG_4BIT        0x00
#define LM75_CFG_12BIT       0x00
#define LM75_CFG_9BIT        0x08
#define LM75_CFG_10BIT       0x10
#define LM75_CFG_11BIT       0x18
#define LM75_CFG_5BIT        0x20
#define LM75_CFG_1BIT        0x28
#define LM75_CFG_2BIT        0x30
#define LM75_CFG_3BIT        0x38
#define LM75_CFG_POLARITY    0x04
#define LM75_CFG_FAULT       0x02
#define LM75_CFG_INT         0x01

/* LM75 default config: 12-bit, fault queue 1, active-low, comparator disabled */
#define LM75_DEFAULT_CONFIG  (LM75_CFG_12BIT | LM75_CFG_POLARITY | LM75_CFG_INT)

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static pthread_mutex_t g_buffer_mutex;
static float    g_buffer[BUFFER_SIZE];
static int      g_buffer_index = 0;
static int      g_buffer_count = 0;
static bool     g_alert_active = false;
static pthread_t g_alert_thread;
static pthread_mutex_t g_alert_mutex;

/* ----------------------------- Prototypes -------------------------------- */
static int  i2c_write_reg8(int fd, uint8_t reg, uint8_t value);
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *out);
static int  lm75_init(int fd);
static int  lm75_read_temperature(int fd, float *temperature);
static void buffer_add(float temperature);
static float buffer_average(void);
static void *alert_thread_func(void *arg);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; ++attempt) {
        if (i2cWriteDevice(fd, (char *)buf, 2) == 2)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRY_COUNT, strerror(errno));
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; ++attempt) {
        if (i2cWriteDevice(fd, (char *)&reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg select 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, I2C_RETRY_COUNT, strerror(errno));
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }
        if (i2cReadDevice(fd, (char *)out, 1) == 1)
            return 0;
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRY_COUNT, strerror(errno));
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ----------------------------- LM75 init ---------------------------------- */
static int lm75_init(int fd)
{
    uint8_t cfg = 0;
    if (i2c_read_reg8(fd, LM75_REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "Failed to read LM75 config register: %s\n", strerror(errno));
        return -1;
    }
    /* If shutdown bit is set, power-cycle the sensor to leave shutdown mode. */
    if (cfg & LM75_CFG_SHUTDOWN) {
        if (i2c_write_reg8(fd, LM75_REG_CONFIG, cfg & ~LM75_CFG_SHUTDOWN) != 0) {
            fprintf(stderr, "Failed to clear shutdown bit: %s\n", strerror(errno));
            return -1;
        }
        gpioDelay(10000); /* 10 ms power-up settling */
    }
    /* Restore default config: 12-bit, fault queue 1, active-low, comparator disabled */
    if (i2c_write_reg8(fd, LM75_REG_CONFIG, LM75_DEFAULT_CONFIG) != 0) {
        fprintf(stderr, "Failed to write LM75 config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Temperature read --------------------------- */
static int lm75_read_temperature(int fd, float *temperature)
{
    uint8_t msb = 0, lsb = 0;
    if (i2c_read_reg8(fd, LM75_REG_TEMP, &msb) != 0)
        return -1;
    if (i2c_read_reg8(fd, LM75_REG_TEMP + 1, &lsb) != 0)
        return -1;

    int16_t raw = (int16_t)((msb << 8) | lsb);
    /* 12-bit two's complement: shift right 4 bits */
    raw >>= 4;
    *temperature = (float)raw / 16.0f;
    return 0;
}

/* ----------------------------- Circular buffer ---------------------------- */
static void buffer_add(float temperature)
{
    pthread_mutex_lock(&g_buffer_mutex);
    g_buffer[g_buffer_index] = temperature;
    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE)
        g_buffer_count++;
    pthread_mutex_unlock(&g_buffer_mutex);
}

static float buffer_average(void)
{
    float sum = 0.0f;
    int count = 0;
    pthread_mutex_lock(&g_buffer_mutex);
    count = g_buffer_count;
    for (int i = 0; i < count; ++i)
        sum += g_buffer[i];
    pthread_mutex_unlock(&g_buffer_mutex);
    return (count > 0) ? (sum / (float)count) : 0.0f;
}

/* ----------------------------- Alert thread ------------------------------- */
static void *alert_thread_func(void *arg)
{
    (void)arg;
    while (g_running) {
        bool current = false;
        pthread_mutex_lock(&g_buffer_mutex);
        if (g_buffer_count > 0) {
            float avg = buffer_average();
            current = (avg > TEMP_THRESHOLD);
        }
        pthread_mutex_unlock(&g_buffer_mutex);

        bool need_set = false;
        pthread_mutex_lock(&g_alert_mutex);
        if (current != g_alert_active) {
            g_alert_active = current;
            need_set = true;
        }
        pthread_mutex_unlock(&g_alert_mutex);

        if (need_set) {
            if (gpioWrite(ALERT_GPIO, g_alert_active ? 1 : 0) != 0)
                fprintf(stderr, "Failed to write alert GPIO: %s\n", strerror(errno));
        }
        gpioDelay(100000); /* 100 ms poll interval */
    }
    return NULL;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_alert_thread) {
        pthread_join(g_alert_thread, NULL);
        g_alert_thread = 0;
    }
    pthread_mutex_lock(&g_alert_mutex);
    gpioWrite(ALERT_GPIO, 0);
    pthread_mutex_unlock(&g_alert_mutex);

    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    pthread_mutex_destroy(&g_buffer_mutex);
    pthread_mutex_destroy(&g_alert_mutex);
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize mutexes */
    if (pthread_mutex_init(&g_buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Failed to init buffer mutex: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (pthread_mutex_init(&g_alert_mutex, NULL) != 0) {
        fprintf(stderr, "Failed to init alert mutex: %s\n", strerror(errno));
        pthread_mutex_destroy(&g_buffer_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", ALERT_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d low: %s\n", ALERT_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, LM75_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize LM75 */
    if (lm75_init(g_i2c_fd) != 0) {
        fprintf(stderr, "LM75 initialisation failed — sensor may be absent or bus error.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start alert thread */
    if (pthread_create(&g_alert_thread, NULL, alert_thread_func, NULL) != 0) {
        fprintf(stderr, "Failed to create alert thread: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LM75 monitor started. Sampling every 1 s. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        float temperature = 0.0f;
        if (lm75_read_temperature(g_i2c_fd, &temperature) == 0) {
            buffer_add(temperature);
            float avg = buffer_average();
            printf("Temperature: %.2f °C | Avg: %.2f °C | Alert: %s\n",
                   temperature, avg, g_alert_active ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Temperature read failed — re-initialising I2C.\n");
            i2cClose(g_i2c_fd);
            g_i2c_fd = -1;
            gpioDelay(1000000); /* 1 s back-off */
            g_i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Re-open failed: %s\n", strerror(errno));
                gpioDelay(1000000);
                continue;
            }
            if (lm75_init(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-init failed — will retry next cycle.\n");
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

