#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    500000
#define SPI_MODE        SPI_MODE_1
#define SPI_BITS        8

#define HEATER_GPIO     18
#define PWM_FREQUENCY   1000
#define PWM_RANGE       1000

#define MAX_TEMP        80.0
#define PID_DT          0.1
#define PID_LOOP_DT     0.1
#define CONFIG_FILE     "config.json"

#define PT100_R0        100.0
#define R_REF           430.0

#define JSON_ERR        (-1)

typedef struct {
    double Kp, Ki, Kd;
    double target_temperature;
} PIDConfig;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static PIDConfig pid_config = {1.0, 0.1, 0.01, 25.0};
static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_max31865(double *temperature) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};

    if (spi_transfer(tx, rx, 4) < 0) return -1;

    if (rx[3] & 0x01) {
        fprintf(stderr, "MAX31865 fault detected (open circuit)\n");
        return -1;
    }
    if (rx[3] & 0x02) {
        fprintf(stderr, "MAX31865 fault detected (short to GND)\n");
        return -1;
    }
    if (rx[3] & 0x04) {
        fprintf(stderr, "MAX31865 fault detected (short to VCC)\n");
        return -1;
    }

    int16_t raw = (int16_t)((rx[0] << 8) | rx[1]);
    raw >>= 1;

    double r = (double)raw * R_REF / 32768.0;
    *temperature = (PT100_R0 * 100.0) / (r / 100.0) - 273.15;
    return 0;
}

static int load_config(const char *filename, PIDConfig *cfg) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file %s: %s. Using defaults.\n", filename, strerror(errno));
        return 0;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, ":");
        char *val = strtok(NULL, "\n");
        if (!key || !val) continue;

        while (*key == ' ' || *key == '\t') key++;
        while (*key != '\0' && (key[strlen(key) - 1] == ' ' || key[strlen(key) - 1] == '\t' || key[strlen(key) - 1] == '\n' || key[strlen(key) - 1] == '\r')) key[strlen(key) - 1] = '\0';

        while (*val == ' ' || *val == '\t') val++;
        while (*val != '\0' && (val[strlen(val) - 1] == ' ' || val[strlen(val) - 1] == '\t' || val[strlen(val) - 1] == '\n' || val[strlen(val) - 1] == '\r')) val[strlen(val) - 1] = '\0';

        if (strcmp(key, "target_temperature") == 0) cfg->target_temperature = atof(val);
        else if (strcmp(key, "Kp") == 0) cfg->Kp = atof(val);
        else if (strcmp(key, "Ki") == 0) cfg->Ki = atof(val);
        else if (strcmp(key, "Kd") == 0) cfg->Kd = atof(val);
    }

    fclose(fp);
    return 0;
}

static double calculate_pid(double setpoint, double actual) {
    double error = setpoint - actual;
    integral += error * PID_DT;
    double derivative = (error - previous_error) / PID_DT;
    double output = pid_config.Kp * error + pid_config.Ki * integral + pid_config.Kd * derivative;
    previous_error = error;
    return output;
}

static int set_heater_pwm(double duty) {
    if (duty < 0.0) duty = 0.0;
    if (duty > 100.0) duty = 100.0;
    int pwm = (int)(duty * PWM_RANGE / 100.0);
    if (gpioPWM(HEATER_GPIO, pwm) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", HEATER_GPIO, pigpio_error(0));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n", HEATER_GPIO, pigpio_error(0));
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d: %s\n", HEATER_GPIO, pigpio_error(0));
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n", HEATER_GPIO, pigpio_error(0));
        cleanup();
        return 1;
    }

    if (set_heater_pwm(0.0) < 0) {
        cleanup();
        return 1;
    }

    load_config(CONFIG_FILE, &pid_config);

    printf("Starting PID loop. Target: %.2f°C, Kp: %.2f, Ki: %.2f, Kd: %.2f\n", pid_config.target_temperature, pid_config.Kp, pid_config.Ki, pid_config.Kd);

    while (running) {
        double temperature = 0.0;
        if (read_max31865(&temperature) < 0) {
            fprintf(stderr, "Error reading temperature. Shutting down.\n");
            set_heater_pwm(0.0);
            cleanup();
            return 1;
        }

        if (temperature > MAX_TEMP) {
            fprintf(stderr, "Temperature exceeds maximum (%.2f°C). Shutting down.\n", MAX_TEMP);
            set_heater_pwm(0.0);
            cleanup();
            return 1;
        }

        double pid_output = calculate_pid(pid_config.target_temperature, temperature);
        double duty = pid_output;

        if (set_heater_pwm(duty) < 0) {
            fprintf(stderr, "Error setting heater PWM. Shutting down.\n");
            cleanup();
            return 1;
        }

        printf("Temp: %.2f°C, PID: %.2f, Duty: %.2f%%\n", temperature, pid_output, duty);

        time_sleep(PID_LOOP_DT);
    }

    printf("\nShutting down gracefully.\n");
    set_heater_pwm(0.0);
    cleanup();
    return 0;
}

