/*
 * BMP180 + Fan controller for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   BMP180 SDA -> GPIO2 (I2C bus 1 SDA)
 *   BMP180 SCL -> GPIO3 (I2C bus 1 SCL)
 *   BMP180 VDD -> 3.3 V
 *   BMP180 GND -> GND
 *   Fan control -> GPIO18 (active-high, 4.5–6 V typical)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o bmp180_fan bmp180_fan.c -lpigpio -lrt
 *   (pigpio must be running; use `sudo pigpiod` or run as root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP180 constants (from datasheet) ---- */
#define BMP180_ADDR             0x77
#define BMP180_REG_CAL_START    0xAA
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_DATA         0xF6
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESS_OSS0   0x34  /* OSS = 0 */
#define BMP180_TEMP_CONV_US    4500  /* microseconds */
#define BMP180_PRESS_CONV_US   4500  /* microseconds (OSS=0) */

/* ---- Fan / control ---- */
#define FAN_GPIO                18
#define TEMP_THRESHOLD_C        30.0f
#define SAMPLE_PERIOD_US        500000  /* 500 ms */

/* ---- Circular buffer ---- */
#define BUFFER_SIZE             60

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} Reading;

static Reading g_buffer[BUFFER_SIZE];
static int      g_buf_head = 0;
static int      g_buf_count = 0;

/* ---- Calibration coefficients ---- */
typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t g_cal;
static int32_t      g_b5 = 0;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, reg) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0)
        return -1;
    return 0;
}

/* ---- BMP180 calibration ---- */
static int read_calibration(int handle, bmp180_cal_t *cal)
{
    uint8_t buf[22];
    if (i2c_read_block(handle, BMP180_REG_CAL_START, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "Error: failed to read 22-byte calibration block\n");
        return -1;
    }

    cal->ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1  = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2  = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb  = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc  = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md  = (int16_t)((buf[20] << 8) | buf[21]);

    /* Sanity-check: AC1/AC6 are required fields; AC1 is unlikely to be 0 or -1
     * on a real BMP180, but a zero-value indicates a bus error or sensor
     * absence. */
    if (cal->ac1 == 0 || cal->ac1 == -1 || cal->ac6 == 0) {
        fprintf(stderr, "Error: calibration values invalid (AC1=%d AC6=%u)\n",
                cal->ac1, cal->ac6);
        return -1;
    }
    return 0;
}

/* ---- BMP180 temperature ---- */
static int read_raw_temperature(int handle, int32_t *raw)
{
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0)
        return -1;
    gpioDelay(BMP180_TEMP_CONV_US);
    uint8_t buf[2];
    if (i2c_read_block(handle, BMP180_REG_DATA, buf, 2) != 0)
        return -1;
    *raw = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float calculate_temperature(int32_t raw)
{
    int32_t x1 = ((raw - (int32_t)g_cal.ac6) * (int32_t)g_cal.ac5) >> 15;
    int32_t x2 = ((int32_t)g_cal.mc << 11) / (x1 + (int32_t)g_cal.md);
    g_b5 = x1 + x2;
    return ((float)(g_b5 + 8)) / 160.0f;
}

/* ---- BMP180 pressure (OSS = 0) ---- */
static int read_raw_pressure(int handle, int32_t *raw)
{
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESS_OSS0) != 0)
        return -1;
    gpioDelay(BMP180_PRESS_CONV_US);
    uint8_t buf[3];
    if (i2c_read_block(handle, BMP180_REG_DATA, buf, 3) != 0)
        return -1;
    *raw = (((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static float calculate_pressure(int32_t raw)
{
    int32_t b6 = g_b5 - 4000;
    int32_t x1 = ((int32_t)g_cal.b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)g_cal.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)g_cal.ac1 * 4 + x3) + 2) >> 2;

    uint32_t b4 = ((uint32_t)g_cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw - b3) * (50000 >> 0);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

/* ---- Circular buffer ---- */
static void buffer_add(float temp, float press)
{
    g_buffer[g_buf_head].timestamp  = time(NULL);
    g_buffer[g_buf_head].temperature = temp;
    g_buffer[g_buf_head].pressure    = press;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

/* ---- Fan control ---- */
static void control_fan(float temp)
{
    int level = (temp > TEMP_THRESHOLD_C) ? 1 : 0;
    if (gpioWrite(FAN_GPIO, level) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", FAN_GPIO, level);
}

/* ---- Timer callback ---- */
static void timer_callback(void *userdata)
{
    (void)userdata;

    int32_t raw_t = 0, raw_p = 0;
    float temp = 0.0f, press = 0.0f;

    if (read_raw_temperature(g_i2c_handle, &raw_t) != 0) {
        fprintf(stderr, "Timer: temperature read failed\n");
        return;
    }
    temp = calculate_temperature(raw_t);

    if (read_raw_pressure(g_i2c_handle, &raw_p) != 0) {
        fprintf(stderr, "Timer: pressure read failed\n");
        return;
    }
    press = calculate_pressure(raw_p);

    buffer_add(temp, press);
    control_fan(temp);

    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp, press);
    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioSetTimerFuncEx(0, 0, NULL, NULL); /* disable timer */
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Fan GPIO setup */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    /* I2C open */
    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                BMP180_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read calibration */
    if (read_calibration(g_i2c_handle, &g_cal) != 0) {
        fprintf(stderr, "Error: BMP180 calibration read failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Timer setup */
    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 fan controller running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running)
        gpioDelay(100000); /* 100 ms sleep */

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

