#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define HEATER_GPIO 17
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80
#define LOG_FILE "heater_log.csv"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(double *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: Open circuit\n");
        } else if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: Short to GND\n");
        } else if (raw & 0x00000004) {
            fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        } else {
            fprintf(stderr, "MAX31855 fault: Unknown\n");
        }
        return -1;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = (double)temp_raw * 0.25;
    return 0;
}

static int set_heater_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    if (gpioPWM(HEATER_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int log_data(double temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int duty_cycle = 0;
    double temperature = 0.0;

    while (running) {
        if (read_max31855(&temperature) != 0) {
            fprintf(stderr, "Error reading temperature, setting duty cycle to 0\n");
            duty_cycle = 0;
            set_heater_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle);
        } else {
            double error = TARGET_TEMPERATURE - temperature;
            int new_duty_cycle = duty_cycle + (int)(error * 10.0);

            if (new_duty_cycle < 0) new_duty_cycle = 0;
            if (new_duty_cycle > MAX_DUTY_CYCLE) new_duty_cycle = MAX_DUTY_CYCLE;

            if (set_heater_duty_cycle(new_duty_cycle) != 0) {
                fprintf(stderr, "Error setting heater duty cycle\n");
            }

            duty_cycle = new_duty_cycle;
            log_data(temperature, duty_cycle);
        }

        gpioDelay(100000);
    }

    fprintf(stderr, "Shutting down...\n");
    set_heater_duty_cycle(0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

