    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)buf;
    tr.len = len;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE failed");
        return -1;
    }
    return 0;
}

static int set_pwm(int fd, int pin, int duty) {
    char buf[3];
    buf[0] = 0x00;
    buf[1] = (char)pin;
    buf[2] = (char)duty;
    return spi_write(fd, buf, 3);
}

static int set_led_color(int fd, int r, int g, int b) {
    int inv_r = 255 - r;
    int inv_g = 255 - g;
    int inv_b = 255 - b;
    if (set_pwm(fd, RED_PIN,   inv_r) < 0) return -1;
    if (set_pwm(fd, GREEN_PIN, inv_g) < 0) return -1;
    if (set_pwm(fd, BLUE_PIN,  inv_b) < 0) return -1;
    return 0;
}

static void turn_off_led(int fd) {
    set_pwm(fd, RED_PIN, 255);
    set_pwm(fd, GREEN_PIN, 255);
    set_pwm(fd, BLUE_PIN, 255);
}

static int read_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        perror("fopen thermal_zone0/temp");
        return -1;
    }
    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        if (ferror(fp)) {
            perror("fscanf thermal_zone0/temp");
        } else {
            fprintf(stderr, "Failed to parse temperature\n");
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return 1;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return 1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return 1;
    }

    turn_off_led(spi_fd);

    while (running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Error reading CPU temperature, exiting\n");
            break;
        }

        int r, g, b;
        if (temp < 40000) {
            r = 0; g = 0; b = 255;
        } else if (temp < 60000) {
            r = 0; g = 255; b = 0;
        } else {
            r = 255; g = 0; b = 0;
        }

        if (set_led_color(spi_fd, r, g, b) < 0) {
            fprintf(stderr, "Error setting LED color, exiting\n");
            break;
        }

        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, r, g, b);
        fflush(stdout);

        usleep(500000);
    }

    turn_off_led(spi_fd);
    close(spi_fd);
    return 0;
}

