#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <fcntl.h>

#define DHT22_PIN 4
#define SERVER_IP "yourserver.com"
#define SERVER_PORT 80
#define API_ENDPOINT "/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define DHT22_TIMEOUT_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(int pin, float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int last_state = HIGH;
    int counter = 0;
    int j = 0;

    if (humidity == NULL || temperature == NULL) {
        return -1;
    }

    *humidity = -1.0f;
    *temperature = -1.0f;

    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", pin);
        return -1;
    }
    gpioWrite(pin, 0);
    gpioDelay(2000);
    gpioWrite(pin, 1);
    gpioDelay(30);
    if (gpioSetMode(pin, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", pin);
        return -1;
    }

    for (int i = 0; i < 85; i++) {
        counter = 0;
        while (gpioRead(pin) == last_state) {
            counter++;
            gpioDelay(1);
            if (counter > DHT22_TIMEOUT_US) {
                fprintf(stderr, "Error: Timeout waiting for DHT22 response\n");
                return -1;
            }
        }
        last_state = gpioRead(pin);

        if (i > 3 && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) {
                data[j / 8] |= 1;
            }
            j++;
        }
    }

    if (j < 40) {
        fprintf(stderr, "Error: DHT22 data incomplete (%d bits)\n", j);
        return -1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Error: DHT22 checksum mismatch\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

static int send_data_to_server(const char *json_data) {
    int sockfd = -1;
    struct sockaddr_in serv_addr;
    struct hostent *server;
    char request[1024];
    int n;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error: Could not create socket");
        return -1;
    }

    server = gethostbyname(SERVER_IP);
    if (server == NULL) {
        fprintf(stderr, "Error: No such host: %s\n", SERVER_IP);
        close(sockfd);
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);
    memcpy(&serv_addr.sin_addr.s_addr, server->h_addr, server->h_length);

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Error: Could not connect to server");
        close(sockfd);
        return -1;
    }

    snprintf(request, sizeof(request), "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n%s", API_ENDPOINT, SERVER_IP, strlen(json_data), json_data);

    n = write(sockfd, request, strlen(request));
    if (n < 0) {
        perror("Error: Could not send data");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    float humidity, temperature;
    char json_data[256];
    int retries;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    while (running) {
        retries = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_dht22(DHT22_PIN, &humidity, &temperature) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Error: DHT22 read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000);
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Error: DHT22 read failed after %d retries\n", MAX_RETRIES);
        } else {
            snprintf(json_data, sizeof(json_data), "{\"humidity\": %.1f, \"temperature\": %.1f}", humidity, temperature);
            if (send_data_to_server(json_data) == 0) {
                printf("Data sent successfully: %s\n", json_data);
            } else {
                fprintf(stderr, "Error: Failed to send data to server\n");
            }
        }

        if (running) {
            gpioDelay(5000000);
        }
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

