/*
 * BMP180 I2C pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   BMP180 SDA -> GPIO 2 (pin 3, I2C bus 1)
 *   BMP180 SCL -> GPIO 3 (pin 5, I2C bus 1)
 *   BMP180 VDD -> 3.3 V
 *   BMP180 GND -> GND
 *   Button    -> GPIO 4 (pin 7) to GND; internal pull-up enabled.
 *
 * The BMP180 is configured for oversampling setting OSS=3 (0x03).
 * The full Bosch BMP180 integer-only compensation algorithm is applied.
 * Data logging is toggled on GPIO 4 falling-edge interrupts (debounced
 * at 200 000 us).  When logging is enabled, pressure is read every 2 s
 * (BMP180 conversion time 26 ms), appended to pressure_log.txt, and
 * status printed to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_log bmp180_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- BMP180 register addresses ---- */
#define BMP180_REG_CONTROL   0xF4
#define BMP180_REG_MSB       0xF6
#define BMP180_REG_LSB       0xF7
#define BMP180_REG_XLSB      0xF8
#define BMP180_REG_CAL_AC1   0xAA

/* ---- BMP180 commands ---- */
#define BMP180_CMD_TEMP      0x2E
#define BMP180_CMD_PRESSURE  0x34  /* OSS=3 */

/* ---- GPIO / timing ---- */
#define BUTTON_GPIO          4
#define I2C_BUS              "/dev/i2c-1"
#define LOG_FILE             "pressure_log.txt"
#define SAMPLE_PERIOD_US     2000000   /* 2 s */
#define CONV_DELAY_US        26000     /* 26 ms (OSS=3) */
#define DEBOUNCE_US          200000    /* 200 ms */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_log_enabled = 0;
static volatile uint32_t     g_last_edge_tick = 0;

static int g_i2c_fd = -1;

/* ---- Calibration coefficients ---- */
static int16_t  g_cal_ac1, g_cal_ac2, g_cal_ac3;
static uint16_t g_cal_ac4, g_cal_ac5, g_cal_ac6;
static int16_t  g_cal_b1,  g_cal_b2,  g_cal_mb;
static int16_t  g_cal_mc,  g_cal_md;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit unsigned from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ---- BMP180 calibration ---- */
static int bmp180_read_calibration(int fd)
{
    if (i2c_read_reg16(fd, 0xAA, &g_cal_ac1) < 0) return -1;
    if (i2c_read_reg16(fd, 0xAC, &g_cal_ac2) < 0) return -1;
    if (i2c_read_reg16(fd, 0xAE, &g_cal_ac3) < 0) return -1;
    if (i2c_read_reg16u(fd, 0xB0, &g_cal_ac4) < 0) return -1;
    if (i2c_read_reg16u(fd, 0xB2, &g_cal_ac5) < 0) return -1;
    if (i2c_read_reg16u(fd, 0xB4, &g_cal_ac6) < 0) return -1;
    if (i2c_read_reg16(fd, 0xB6, &g_cal_b1)  < 0) return -1;
    if (i2c_read_reg16(fd, 0xB8, &g_cal_b2)  < 0) return -1;
    if (i2c_read_reg16(fd, 0xBA, &g_cal_mb)  < 0) return -1;
    if (i2c_read_reg16(fd, 0xBC, &g_cal_mc)  < 0) return -1;
    if (i2c_read_reg16(fd, 0xBE, &g_cal_md)  < 0) return -1;
    return 0;
}

/* ---- BMP180 raw temperature ---- */
static int bmp180_read_raw_temp(int fd, int32_t *ut)
{
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0)
        return -1;
    usleep(5000);  /* 4.5 ms max conversion time */

    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

/* ---- BMP180 raw pressure (OSS=3) ---- */
static int bmp180_read_raw_pressure(int fd, int32_t *up)
{
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) < 0)
        return -1;
    usleep(CONV_DELAY_US);

    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *up = ((int32_t)msb << 16) | ((int32_t)lsb << 8) | (int32_t)xlsb;
    *up >>= (8 - 3);  /* OSS=3 */
    return 0;
}

/* ---- BMP180 compensation (integer-only) ---- */
static int32_t bmp180_compute_b5(int32_t ut)
{
    int32_t x1 = ((ut - (int32_t)g_cal_ac6) * (int32_t)g_cal_ac5) >> 15;
    int32_t x2 = ((int32_t)g_cal_mc << 11) / (x1 + (int32_t)g_cal_md);
    return x1 + x2;
}

static float bmp180_compute_pressure_hpa(int32_t up, int32_t b5)
{
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)g_cal_b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)g_cal_ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)g_cal_ac1 * 4 + x3) << 3) + 2) >> 2);

    x1 = ((int32_t)g_cal_ac3 * b6) >> 13;
    x2 = ((int32_t)g_cal_b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)g_cal_ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 3);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p / 100.0f;
}

/* ---- Logging ---- */
static void log_pressure(float pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f hPa\n", ts, pressure);
    } else {
        fprintf(fp, "(time error), %.2f hPa\n", pressure);
    }
    fclose(fp);
}

/* ---- GPIO setup ---- */
static int gpio_setup(void)
{
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open /dev/gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    /* Request button as input with pull-up */
    if (ioctl(fd, GPIO_GET_LINE, BUTTON_GPIO) < 0) {
        fprintf(stderr, "GPIO_GET_LINE(%d) failed: %s\n", BUTTON_GPIO, strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, GPIO_SET_DIRECTION_INPUT, BUTTON_GPIO) < 0) {
        fprintf(stderr, "GPIO_SET_DIRECTION_INPUT(%d) failed: %s\n",
                BUTTON_GPIO, strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, GPIO_SET_PULL_UPDOWN, BUTTON_GPIO) < 0) {
        fprintf(stderr, "GPIO_SET_PULL_UPDOWN(%d) failed: %s\n",
                BUTTON_GPIO, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/* ---- Button interrupt handler ---- */
static void button_interrupt_handler(int gpio_fd, int gpio)
{
    (void)gpio;
    uint32_t now = (uint32_t)clock();
    uint32_t elapsed = now - (uint32_t)g_last_edge_tick;
    if (elapsed < DEBOUNCE_US)
        return;
    g_last_edge_tick = now;

    g_log_enabled = !g_log_enabled;
    printf("Logging %s\n", g_log_enabled ? "enabled" : "disabled");
    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_gpio_fd >= 0) {
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x77) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x77: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Read calibration */
    if (bmp180_read_calibration(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data.\n");
        fprintf(stderr, "Sensor absent or wiring incorrect.\n");
        cleanup();
        return 1;
    }

    /* GPIO setup */
    g_gpio_fd = gpio_setup();
    if (g_gpio_fd < 0) {
        cleanup();
        return 1;
    }

    /* Register button interrupt */
    if (ioctl(g_gpio_fd, GPIO_SET_ALERT, BUTTON_GPIO) < 0) {
        fprintf(stderr, "GPIO_SET_ALERT(%d) failed: %s\n",
                BUTTON_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    printf("BMP180 pressure logger started.  Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        if (g_log_enabled) {
            int32_t ut, up;
            if (bmp180_read_raw_temp(g_i2c_fd, &ut) < 0) {
                fprintf(stderr, "Temperature read failed; retrying next cycle.\n");
                usleep(SAMPLE_PERIOD_US);
                continue;
            }
            if (bmp180_read_raw_pressure(g_i2c_fd, &up) < 0) {
                fprintf(stderr, "Pressure read failed; retrying next cycle.\n");
                usleep(SAMPLE_PERIOD_US);
                continue;
            }
            int32_t b5 = bmp180_compute_b5(ut);
            float pressure = bmp180_compute_pressure_hpa(up, b5);
            log_pressure(pressure);
            printf("Pressure: %.2f hPa\n", pressure);
            fflush(stdout);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

