#define DHT22_READ_INTERVAL 10
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_TIMEOUT_US 1000
#define DHT22_BIT_THRESHOLD 50
#define MAX_DHT22_DATA 5
#define MAX_JSON_SIZE 256
#define MAX_URL_SIZE 512
#define MAX_RESPONSE_SIZE 1024

static volatile sig_atomic_t running = 1;
static char api_url[MAX_URL_SIZE] = "http://your-the-library’s-APICall.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts;
    ts.tv_sec = us / 1000000;
    ts.tv_nsec = (us % 1000000) * 1000;
    nanosleep(&ts, NULL);
}

static int gpio_set_mode(int gpio, int mode) {
