        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_write(int gpio, int value) {
    int fd = open("/dev/gpiochip0", O_RDWR);
