        syslog(LOG_ERR, "Failed to write GPIO %d: %s", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_read(int gpio) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /dev/gpiochip0: %s", strerror(errno));
        return -1;
