    req.config[0] = GPIO_LINE_REQUEST_DIRECTION_INPUT;
    int ret = ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", gpio, strerror(errno));
        close(fd);
        return -1;
    }
    int handle = ret;
    struct gpiohandle_data data;
    ret = ioctl(handle, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &data);
