    if (gpio_set_mode(gpio, GPIO_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        return -1;
    }
    gpio_write(gpio, 0);
    sleep_us(DHT22_START_LOW_US);
    gpio_write(gpio, 1);
    sleep_us(DHT22_START_HIGH_US);

    if (gpio_set_mode(gpio, GPIO_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        return -1;
    }

    while (gpio_read(gpio) == 1) {
        if (++timeout > DHT22_TIMEOUT_US) {
            syslog(LOG_ERR, "DHT22 timeout waiting for sensor to pull low");
            return -1;
        }
        sleep_us(1);
    }

    timeout = 0;
    while (gpio_read(gpio) == 0) {
        if (++timeout > DHT22_TIMEOUT_US) {
            syslog(LOG_ERR, "DHT22 timeout waiting for sensor to pull high");
            return -1;
        }
        sleep_us(1);
    }

    timeout = 0;
    while (gpio_read(gpio) == 1) {
        if (++timeout > DHT22_TIMEOUT_US) {
            syslog(LOG_ERR, "DHT22 timeout waiting for sensor to pull low after response");
            return -1;
        }
        sleep_us(1);
    }

    for (int i = 0; i < 40; i++) {
        timeout = 0;
        while (gpio_read(gpio) == 0) {
            if (++timeout > DHT22_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22 timeout waiting for bit %d to go high", i);
                return -1;
            }
            sleep_us(1);
        }

