        return -1;
    }
    return 0;
}

static int send_http_request(const char *url, const char *json_data) {
    char request[MAX_JSON_SIZE + 512];
    int ret = snprintf(request, sizeof(request),
        "POST %s HTTP/1.1\r\n"
        "Host: example.com\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        url, strlen(json_data), json_data);
    if (ret < 0 || (size_t)ret >= sizeof(request)) {
        syslog(LOG_ERR, "HTTP request formatting failed");
        return -1;
    }

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo("example.com", "80", &hints, &res) != 0) {
        syslog(LOG_ERR, "getaddrinfo failed");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, res->ai_addr, res->ai_addrlen) < 0) {
        syslog(LOG_ERR, "Connect failed: %s", strerror(errno));
        freeaddrinfo(res);
        close(sockfd);
        return -1;
    }
    freeaddrinfo(res);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char response[MAX_RESPONSE_SIZE];
    ssize_t bytes_received = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    response[bytes_received] = '\0';
    close(sockfd);

    if (strstr(response, "200 OK") == NULL) {
        syslog(LOG_ERR, "HTTP request failed: %s", response);
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                strncpy(api_url, optarg, MAX_URL_SIZE - 1);
                api_url[MAX_URL_SIZE - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <api_url>]\n", argv[0]);
                return 1;
        }
    }

    openlog("dht22_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 sensor program");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float humidity = 0.0f, temperature = 0.0f;
        int retries = 0;
        bool success = false;

        while (retries < MAX_RETRIES && running) {
            if (dht22_read(DHT22_GPIO, &humidity, &temperature) == 0) {
                success = true;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(RETRY_DELAY);
            }
        }

        if (!success) {
            syslog(LOG_ERR, "Failed to read DHT22 after %d retries", MAX_RETRIES);
            sleep(DHT22_READ_INTERVAL);
            continue;
        }

        char json_string[MAX_JSON_SIZE];
        if (format_json(humidity, temperature, json_string, sizeof(json_string)) != 0) {
            syslog(LOG_ERR, "Failed to format JSON");
            sleep(DHT22_READ_INTERVAL);
            continue;
        }

        retries = 0;
        bool post_success = false;
        while (retries < MAX_RETRIES && running) {
            if (send_http_request(api_url, json_string) == 0) {
                post_success = true;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(RETRY_DELAY);
            }
        }

        if (!post_success) {
            syslog(LOG_ERR, "Failed to post data after %d retries", MAX_RETRIES);
        }

        sleep(DHT22_READ_INTERVAL);
    }

    syslog(LOG_INFO, "Shutting down DHT22 sensor program");
    closelog();
    return 0;
}

