            syslog(LOG_ERR, "Failed to read DHT22 after %d retries", MAX_RETRIES);
            sleep(DHT22_READ_INTERVAL);
            continue;
        }

        char json_string[MAX_JSON_SIZE];
        if (format_json(humidity, temperature, json_string, sizeof(json_string)) != 0) {
            syslog(LOG_ERR, "Failed to format JSON");
            sleep(DHT22_READ_INTERVAL);
            continue;
        }

        retries = 0;
        bool post_success = false;
        while (retries < MAX_RETRIES && running) {
            if (send_http_request(api_url, json_string) == 0) {
                post_success = true;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(RETRY_DELAY);
            }
        }

        if (!post_success) {
            syslog(LOG_ERR, "Failed to post data after %d retries", MAX_RETRIES);
        }

        sleep(DHT22_READ_INTERVAL);
    }

    syslog(LOG_INFO, "Shutting down DHT22 sensor program");
    closelog();
    return 0;
}

