#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5
#define TEMP_THRESHOLD_1 45
#define TEMP_THRESHOLD_2 55
#define TEMP_THRESHOLD_3 65
#define MAX_FAN_STATE 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(CPU_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", CPU_TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli;
}

static int read_fan_state(void) {
    FILE *fp = fopen(FAN_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    int state;
    if (fscanf(fp, "%d", &state) != 1) {
        fprintf(stderr, "Error reading fan state from %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return state;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s for appending: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "[%s] %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int set_fan_speed(int temp_milli) {
    int new_state = 0;

    if (temp_milli < TEMP_THRESHOLD_1) {
        new_state = 0;
    } else if (temp_milli < TEMP_THRESHOLD_2) {
        new_state = 1;
    } else if (temp_milli < TEMP_THRESHOLD_3) {
        new_state = 2;
    } else {
        new_state = 3;
    }

    int current_state = read_fan_state();
    if (current_state < 0) {
        fprintf(stderr, "Error reading current fan state\n");
        return -1;
    }

    if (new_state == current_state) {
        return 0;
    }

    if (write_fan_state(new_state) != 0) {
        fprintf(stderr, "Error writing new fan state\n");
        return -1;
    }

    char log_message[128];
    snprintf(log_message, sizeof(log_message), "Fan speed set to %d (Temperature: %.2f°C)", new_state, temp_milli / 1000.0);
    if (log_event(log_message) != 0) {
        fprintf(stderr, "Error logging event\n");
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (log_event("Fan control program started") != 0) {
        fprintf(stderr, "Error logging start event\n");
    }

    while (program_running) {
        int temp_milli = read_cpu_temp();
        if (temp_milli < 0) {
            fprintf(stderr, "Error reading CPU temperature, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (set_fan_speed(temp_milli) != 0) {
            fprintf(stderr, "Error setting fan speed\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (write_fan_state(0) != 0) {
        fprintf(stderr, "Error setting fan to off during shutdown\n");
    }

    if (log_event("Fan control program stopped") != 0) {
        fprintf(stderr, "Error logging stop event\n");
    }

    return 0;
}

