#define SPI_DEVICE           "/dev/spidev0.0"
#define SPI_SPEED_HZ         500000          /* MAX31855 max is 5 MHz; 500 kHz is safe */
#define SPI_BITS_PER_WORD    8
#define SPI_MODE             0               /* MAX31855 is SPI mode 0,0 */

#define PWM_FREQUENCY        1000            /* 1 kHz hardware PWM */
#define PWM_RANGE            100             /* 0-100 % duty cycle */

#define TARGET_TEMPERATURE   50.0
#define LOG_FILE             "heater_log.txt"

#define KP                   1.0
#define KI                   0.1
#define KD                   0.01

#define TEMPERATURE_MIN      0.0
#define TEMPERATURE_MAX      100.0

#define SAMPLE_INTERVAL_S    1

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static FILE    *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  spi_init(void);
static int  spi_transfer(uint8_t *tx, uint8_t *rx, size_t len);
static int  read_max31855(double *temperature);
static double pid_calculate(double setpoint, double actual, double *integral,
                            double *previous_error);
static void set_heater_pwm(double duty_percent);
static void log_data(double temperature, double duty, double pid_out);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI init ---------------------------------- */

static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/* ----------------------------- SPI transfer ------------------------------ */

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- MAX31855 read ----------------------------- */

static int read_max31855(double *temperature)
{
    uint8_t tx[4] = {0};
    uint8_t rx[4] = {0};

    if (spi_transfer(tx, rx, sizeof(rx)) < 0)
        return -1;

    /* Fault bit is the MSB of the 16-bit word (D2 of the 32-bit frame) */
    if (rx[3] & 0x01) {
        fprintf(stderr, "MAX31855 fault: ");
        if (rx[3] & 0x04)
            fprintf(stderr, "open circuit\n");
        else if (rx[3] & 0x02)
            fprintf(stderr, "short to GND\n");
        else if (rx[3] & 0x01)
            fprintf(stderr, "short to VCC\n");
        else
            fprintf(stderr, "unknown fault\n");
        return -1;
    }

    /*
     * 32-bit frame (MSB first):
     *   D31..D18 : thermocouple temperature, 14-bit signed, 0.25 °C / LSB
     *   D17      : reserved
     *   D16      : fault (already checked above)
     *   D15..D4  : internal / cold-junction temperature, 12-bit signed, 0.0625 °C / LSB
     *   D3       : reserved
     *   D2        : fault (already checked above)
     *   D1        : reserved
     *   D0        : open circuit / short to VCC (already checked above)
     */
    int16_t raw = (int16_t)((rx[0] << 8) | rx[1]);
    *temperature = raw * 0.25;
    return 0;
}

/* ----------------------------- PID --------------------------------------- */

static double pid_calculate(double setpoint, double actual,
                            double *integral, double *previous_error)
{
    double error = setpoint - actual;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

/* ----------------------------- Heater PWM -------------------------------- */

static void set_heater_pwm(double duty_percent)
{
    if (duty_percent < 0.0) duty_percent = 0.0;
    if (duty_percent > 100.0) duty_percent = 100.0;

    int duty = (int)(duty_percent * (PWM_RANGE / 100.0));
    if (gpioPWM(HEATER_GPIO, duty) < 0)
        fprintf(stderr, "gpioPWM: %s\n", pigpio_error(PI_BAD_USER_GPIO));
}

/* ----------------------------- Logging ----------------------------------- */

static void log_data(double temperature, double duty, double pid_out)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s, Temperature: %.2f C, Duty: %.2f %%, PID: %.2f\n",
            ts, temperature, duty, pid_out);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure heater is off before terminating pigpio */
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d): %s\n", HEATER_GPIO, pigpio_error(PI_BAD_USER_GPIO));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency: %s\n", pigpio_error(PI_BAD_USER_GPIO));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange: %s\n", pigpio_error(PI_BAD_USER_GPIO));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_heater_pwm(0.0);

    /* --- SPI init --- */
    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- PID state --- */
    double integral = 0.0;
    double previous_error = 0.0;

    /* --- Main loop --- */
    while (g_running) {
        double temperature = 0.0;

        if (read_max31855(&temperature) < 0) {
            set_heater_pwm(0.0);
            integral = 0.0;
            previous_error = 0.0;
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (temperature < TEMPERATURE_MIN || temperature > TEMPERATURE_MAX) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
            set_heater_pwm(0.0);
            integral = 0.0;
            previous_error = 0.0;
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        double pid_out = pid_calculate(TARGET_TEMPERATURE, temperature,
                                       &integral, &previous_error);

        double duty = pid_out;
        if (duty < 0.0) duty = 0.0;
        if (duty > 100.0) duty = 100.0;

        set_heater_pwm(duty);
        log_data(temperature, duty, pid_out);

        sleep(SAMPLE_INTERVAL_S);
    }

    /* --- Graceful shutdown --- */
    set_heater_pwm(0.0);
    cleanup();
    return EXIT_SUCCESS;
}

