#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float temperature, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

static int set_fan_speed(float temperature) {
    if (temperature < MIN_TEMP) {
        temperature = MIN_TEMP;
    } else if (temperature > MAX_TEMP) {
        temperature = MAX_TEMP;
    }

    float duty_cycle = ((temperature - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * 100.0;

    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;

    int gpio_value = (int)(duty_cycle / 100.0 * 255.0);
    if (gpio_value < 0) gpio_value = 0;
    if (gpio_value > 255) gpio_value = 255;

    if (gpioPWM(FAN_GPIO, gpio_value) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return (int)duty_cycle;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, 255) != 255) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing PWM duty cycle\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        perror("Error creating log file");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return 1;
    }
    fprintf(fp, "Timestamp,Temperature (C),PWM Duty Cycle (%)\n");
    fclose(fp);

    while (running) {
        float temperature = (float)sysconf(_SC_TEMP) / 1000.0;
        int duty_cycle = set_fan_speed(temperature);

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(POLL_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("\nFan stopped and resources released. Exiting.\n");
    return 0;
}

