            }
        } else {
            fprintf(stderr, "Error reading flow data (sensor1=%d, sensor2=%d)\n", ret1, ret2);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

