        fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_A);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(CHANNEL_B, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_B);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(CHANNEL_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", CHANNEL_A);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(CHANNEL_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", CHANNEL_B);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
