    double position = 0.0;

    while (running) {
        int current_state = (gpioRead(CHANNEL_A) << 1) | gpioRead(CHANNEL_B);

        if (current_state != last_state) {
            int diff = current_state - last_state;
            if (diff == 1 || diff == -3) {
                position += (360.0 / PULSES_PER_REVOLUTION);
            } else if (diff == -1 || diff == 3) {
                position -= (360.0 / PULSES_PER_REVOLUTION);
