code:
/*
 * ADPD144RI Red/IR Photometric Sensor Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADPD144RI SDA -> GPIO2 (I2C1 SDA)
 *   ADPD144RI SCL -> GPIO3 (I2C1 SCL)
 *   ADPD144RI VDD -> 3.3 V
 *   ADPD144RI GND -> GND
 *   LED Anode    -> GPIO17 (with ~330 ohm series resistor to GND)
 *
 * Build: gcc -O2 -Wall -o adpd144ri_logger adpd144ri_logger.c -li2c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ADPD144RI I2C address (7-bit) */
#define ADPD144RI_ADDR 0x39

/* ADPD144RI register addresses (16-bit, big-endian on the bus) */
#define REG_DEVICE_CONFIG  0x0000
#define REG_RED_DATA       0x0002
#define REG_IR_DATA        0x0004
#define REG_DEVICE_ID      0x0006

/* Expected device ID for ADPD144RI (16-bit, big-endian) */
#define ADPD144RI_DEVICE_ID 0x1440

/* GPIO pin for LED */
#define LED_PIN 17

/* IR threshold for alert */
#define IR_THRESHOLD 2000

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/* Write a 16-bit register address + 16-bit value (big-endian) */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register (big-endian) */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    uint8_t data[2];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADPD144RI sensor interface                                          */
/* ------------------------------------------------------------------ */
static int adpd144ri_init(int fd)
{
    uint16_t device_id = 0;

    /* Verify device identity */
    if (i2c_read_reg16(fd, REG_DEVICE_ID, &device_id) < 0) {
        fprintf(stderr, "Cannot read DEVICE_ID — sensor may be absent.\n");
        return -1;
    }

    if (device_id != ADPD144RI_DEVICE_ID) {
        fprintf(stderr,
                "Device ID mismatch: got 0x%04X, expected 0x%04X.\n",
                device_id, ADPD144RI_DEVICE_ID);
        return -1;
    }

    /* Minimal configuration: enable red/IR channels */
    if (i2c_write_reg16(fd, REG_DEVICE_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Failed to configure DEVICE_CONFIG.\n");
        return -1;
    }

    return 0;
}

static int adpd144ri_read(int fd, uint16_t *red, uint16_t *ir)
{
    if (i2c_read_reg16(fd, REG_RED_DATA, red) < 0)
        return -1;
    if (i2c_read_reg16(fd, REG_IR_DATA, ir) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s,%u,%u\n", ts, red, ir) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t red = 0, ir = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed: %s\n", LED_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adpd144ri_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("adpd144ri_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "fopen adpd144ri_log.txt failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,red,ir\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction SIGINT failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction SIGTERM failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI logger started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (adpd144ri_read(g_i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            log_data(g_log_file, red, ir);

            if (ir > IR_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    gpioWrite(LED_PIN, 0);
    cleanup();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

