#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO%d.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void log_rpm(float rpm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, %.2f\n", timestamp, rpm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: log file not open.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        time_t start = time(NULL);

        pulse_count = 0;
        while (running && (time(NULL) - start) < SAMPLE_INTERVAL_SEC) {
            gpioDelay(100000); /* 100 ms */
        }

        int pulses;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pthread_mutex_unlock(&pulse_mutex);

        float rpm = (float)pulses * 60.0f / (float)SAMPLE_INTERVAL_SEC;

        log_rpm(rpm);
        printf("RPM: %.2f\n", rpm);
    }

    printf("\nShutting down...\n");
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    return EXIT_SUCCESS;
}

