#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x48
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL_MS 100

#define REG_MODE 0x00
#define REG_IR_DATA 0x04
#define REG_RED_DATA 0x06
#define REG_GREEN_DATA 0x08
#define REG_BLUE_DATA 0x0A
#define REG_STATUS 0x0C

#define MODE_POWER_DOWN 0x00
#define MODE_STANDBY 0x01
#define MODE_OPERATING 0x02

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_adpd144ri(int fd) {
    if (i2c_write_reg8(fd, REG_MODE, MODE_POWER_DOWN) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, REG_MODE, MODE_STANDBY) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, REG_MODE, MODE_OPERATING) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_sensor_data(int fd, uint16_t *red, uint16_t *ir) {
    if (i2c_read_reg16(fd, REG_RED_DATA, red) < 0) return -1;
    if (i2c_read_reg16(fd, REG_IR_DATA, ir) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u\n", timestamp, red, ir);
    fflush(fp);
}

static void control_led(struct gpiod_line *line, uint16_t ir) {
    int val = (ir > IR_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_adpd144ri(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize ADPD144RI sensor\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("ADPD144RI sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t red, ir;
        if (read_sensor_data(i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            log_data(log_file, red, ir);
            control_led(led_line, ir);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

