/*
 * Raspberry Pi Zero W – Sensirion SLF3S-4000B Liquid Flow Sensor Logger
 *
 * Wiring:
 *   SLF3S SDA  -> GPIO2 (I2C bus 1 SDA)
 *   SLF3S SCL  -> GPIO3 (I2C bus 1 SCL)
 *   SLF3S VDD  -> 3.3 V
 *   SLF3S GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lpigpio -lrt
 * Run:    sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- SLF3S-4000B I2C address (7-bit) ---- */
#define SLF3S_ADDR 0x60

/* ---- SLF3S-4000B register addresses ---- */
#define SLF3S_REG_MEASURE  0x3600  /* continuous measurement command */
#define SLF3S_REG_CONFIG   0x3601  /* configuration register        */
#define SLF3S_REG_STATUS   0x3602  /* status register               */
#define SLF3S_REG_FLOW     0x3603  /* flow rate MSB                 */
#define SLF3S_REG_FLOW_LSB 0x3604  /* flow rate LSB                 */
#define SLF3S_REG_CRC      0x3605  /* flow rate CRC-8                */

/* ---- I2C bus ---- */
#define I2C_BUS 1

/* ---- Sampling interval (microseconds) ---- */
#define SAMPLE_INTERVAL_US 1000000  /* 1 s */

/* ---- Log file name ---- */
#define LOG_FILE_NAME "flow_log.csv"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/*  Signal handler – set flag so main loop exits and resources are    */
/*  released cleanly.                                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  CRC-8 calculation (Sensirion polynomial 0x31, init 0xFF).          */
/*  Returns 0 on success, -1 on invalid input.                         */
/* ------------------------------------------------------------------ */
static int crc8(const uint8_t *data, size_t len, uint8_t expected)
{
    if (len == 0 || data == NULL)
        return -1;

    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return (crc == expected) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/*  Write a 16-bit command to the SLF3S (no data payload).              */
/*  Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int slf3s_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Read a 16-bit register + CRC-8.                                    */
/*  Returns 0 on success, -1 on I2C failure, -2 on CRC mismatch.       */
/* ------------------------------------------------------------------ */
static int slf3s_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    uint8_t cmd[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write (reg 0x%04X) failed\n", reg);
        return -1;
    }

    /* Small delay so the sensor can clock out the 3-byte response. */
    gpioDelay(2000);  /* 2 ms */

    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "[ERROR] I2C read (reg 0x%04X) returned %d bytes\n", reg, n);
        return -1;
    }

    if (crc8(buf, 2, buf[2]) != 0) {
        fprintf(stderr, "[ERROR] CRC mismatch on reg 0x%04X (calc=0x%02X recv=0x%02X)\n",
                reg, crc8(buf, 2, 0), buf[2]);
        return -2;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Trigger a continuous measurement and read the flow rate.           */
/*  Returns 0 on success, -1 on I2C/CRC failure.                       */
/* ------------------------------------------------------------------ */
static int slf3s_read_flow_rate(int handle, float *flow_rate_uL_min)
{
    /* Trigger continuous measurement. */
    if (slf3s_write_cmd(handle, SLF3S_REG_MEASURE) != 0)
        return -1;

    /* Small delay for the measurement to complete. */
    gpioDelay(2000);  /* 2 ms */

    /* Read flow rate (16-bit, MSB first). */
    uint16_t raw;
    if (slf3s_read_reg16(handle, SLF3S_REG_FLOW, &raw) != 0)
        return -1;

    /* Convert raw ticks to uL/min (SLF3S-4000B: 1 tick = 0.1 uL/min). */
    *flow_rate_uL_min = (float)raw / 10.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Log a flow rate reading to the CSV file.                            */
/*  Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, flow_rate) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush() failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/*  Cleanup – close I2C, flush file, close file, terminate pigpio.     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SLF3S_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append mode) ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE_NAME);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flow_rate_uL_min\n");
        fflush(g_log_file);
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction() failed; continuing without signal handling\n");
    }

    printf("SLF3S-4000B flow logger started. Logging to '%s' every 1 s.\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float flow_rate = 0.0f;

        if (slf3s_read_flow_rate(g_i2c_handle, &flow_rate) == 0) {
            printf("Flow rate: %.2f uL/min\n", flow_rate);
            if (log_flow_rate(g_log_file, flow_rate) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

