        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flow_rate_uL_min\n");
        fflush(g_log_file);
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction() failed; continuing without signal handling\n");
    }

    printf("SLF3S-4000B flow logger started. Logging to '%s' every 1 s.\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float flow_rate = 0.0f;

        if (slf3s_read_flow_rate(g_i2c_handle, &flow_rate) == 0) {
            printf("Flow rate: %.2f uL/min\n", flow_rate);
