                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
