/*
 * Raspberry Pi Zero W – Honeywell MICS-VZ-89TE VOC sensor logger
 *
 * Wiring:
 *   MICS-VZ-89TE SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   MICS-VZ-89TE SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   MICS-VZ-89TE VDD  -> 3.3 V
 *   MICS-VZ-89TE GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o air_quality air_quality.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MICS-VZ-89TE constants (datasheet) ---- */
#define I2C_BUS          "/dev/i2c-1"
#define I2C_ADDR         0x53          /* default 7-bit I2C address */
#define REG_STATUS       0x00
#define REG_TVOC         0x01
#define REG_ECO2         0x02
#define REG_CONFIG       0x70
#define REG_MEASURE      0x71
#define MEASURE_CMD      0x01          /* start a single measurement */

#define LOG_FILE         "air_quality_log.csv"
#define SAMPLE_PERIOD_S  5
#define MAX_RETRIES      3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;          /* tell main loop to exit cleanly          */
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.    */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes starting at `reg`; returns 0 on success, -1 on err.*/
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block(0x%02X): pointer write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read data bytes */
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_block(0x%02X): read failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MICS-VZ-89TE: configure measurement mode.            */
static int init_sensor(int fd)
{
    /* Read back status register to confirm sensor is present */
    uint8_t status = 0;
    if (i2c_read_block(fd, REG_STATUS, &status, 1) != 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X – check wiring.\n",
                I2C_ADDR);
        return -1;
    }
    if ((status & 0x0F) == 0x00) {
        fprintf(stderr, "Sensor status 0x%02X indicates no valid data yet.\n",
                status);
    }

    /* Software reset / configuration */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x00) != 0)
        return -1;
    usleep(2000);            /* allow reset to settle */

    /* Start a single measurement */
    if (i2c_write_reg8(fd, REG_MEASURE, MEASURE_CMD) != 0)
        return -1;
    usleep(2000);            /* measurement takes ~1 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read TVOC and eCO2; returns 0 on success, -1 on error.              */
static int read_sensor(int fd, uint16_t *tvoc, uint16_t *eco2)
{
    uint8_t data[3];
    if (i2c_read_block(fd, REG_TVOC, data, sizeof(data)) != 0)
        return -1;

    *tvoc = ((uint16_t)data[0] << 8) | data[1];
    *eco2 = ((uint16_t)data[2] << 8) | data[1];   /* typo in datasheet? */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute IAQ index from TVOC and eCO2.                              */
static float compute_iaq(uint16_t tvoc, uint16_t eco2)
{
    /* Placeholder linear mapping; real calibration requires datasheet
     * coefficients and a calibration curve. */
    return (float)tvoc * 0.5f + (float)eco2 * 0.3f;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float iaq, uint16_t tvoc, uint16_t eco2)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%u,%u\n", ts, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialisation failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append mode) ---- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log) == 0) {
        fprintf(g_log, "timestamp,IAQ,TVOC_ppb,eCO2_ppm\n");
        fflush(g_log);
    }

    printf("MICS-VZ-89TE logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t tvoc = 0, eco2 = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_sensor(g_i2c_fd, &tvoc, &eco2) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed.\n",
                    attempt + 1, MAX_RETRIES);
            usleep(100000);     /* 100 ms backoff before retry */
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d attempts – "
                            "continuing.\n", MAX_RETRIES);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float iaq = compute_iaq(tvoc, eco2);

        if (log_data(g_log, iaq, tvoc, eco2) != 0) {
            fprintf(stderr, "Logging failed – continuing.\n");
        }

        printf("TVOC=%u ppb  eCO2=%u ppm  IAQ=%.2f\n", tvoc, eco2, iaq);

        /* Sleep but wake early on SIGINT */
        for (int s = 0; s < SAMPLE_PERIOD_S && g_running; ++s)
            sleep(1);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log != NULL) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

