#include <pigpio.h>

#define GPIO_PIN 17
#define POLL_INTERVAL_US 100000   /* 100 ms */
#define ALERT_THRESHOLD_S 5       /* 5 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void cleanup(int *chip, int *line)
{
    if (line != NULL && *line >= 0) {
        gpioSetAlertFuncEx(*line, NULL, NULL);
        gpioSetMode(*line, PI_INPUT);
        gpioSetPullUpDown(*line, PI_PUD_OFF);
        *line = -1;
    }
    if (chip != NULL && *chip >= 0) {
        gpioTerminate();
        *chip = -1;
    }
}

int main(void)
{
    int chip = -1;
    int line = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpioInitialise();
    if (chip < 0) {
        fprintf(stderr, "gpioInitialise() failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpioGetMode(GPIO_PIN);
    if (line < 0) {
        fprintf(stderr, "gpioGetMode(%d) failed: %s\n", GPIO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed: %s\n", GPIO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_OFF) failed: %s\n", GPIO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d) failed: %s\n", GPIO_PIN, strerror(errno));
        goto cleanup;
    }

    printf("TTP223B touch sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);
    fflush(stdout);

    int last_state = 0;
    struct timespec touch_start;
    int have_touch = 0;

    while (running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead(%d) failed: %s\n", GPIO_PIN, strerror(errno));
            goto cleanup;
        }

        if (level == 1 && last_state == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &touch_start) != 0) {
                fprintf(stderr, "clock_gettime(CLOCK_MONOTONIC) failed: %s\n", strerror(errno));
                goto cleanup;
            }
            have_touch = 1;
        } else if (level == 0 && last_state == 1) {
            have_touch = 0;
        }

        if (have_touch) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
                fprintf(stderr, "clock_gettime(CLOCK_MONOTONIC) failed: %s\n", strerror(errno));
                goto cleanup;
            }
            double elapsed = (now.tv_sec - touch_start.tv_sec)
                           + (now.tv_nsec - touch_start.tv_nsec) / 1e9;
            if (elapsed >= ALERT_THRESHOLD_S) {
                printf("Intrusion detected on GPIO %d! Touch held for %.2f seconds.\n",
                       GPIO_PIN, elapsed);
                fflush(stdout);
                have_touch = 0;
            }
        }

        last_state = level;
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup(&chip, &line);
    return ret;
}

