#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_SELECT_PIN 17
#define FILENAME "audio_capture.pcm"
#define SAMPLE_RATE 16000
#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define BUFFER_SIZE 1024

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int gpio_export(int pin) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Failed to write to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Failed to write to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) != (ssize_t)strlen(direction)) {
        fprintf(stderr, "Failed to write to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    char val = (value == 0) ? '0' : '1';
    if (write(fd, &val, 1) != 1) {
        fprintf(stderr, "Failed to write to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int i2s_init(void) {
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }

    int format = AFMT_S16_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        fprintf(stderr, "Failed to set I2S format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Failed to set I2S channels: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        fprintf(stderr, "Failed to set I2S sample rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int i2s_read(int fd, int16_t *buffer, size_t num_samples) {
    size_t total_bytes = num_samples * sizeof(int16_t);
    size_t bytes_read = 0;
    while (bytes_read < total_bytes) {
        ssize_t n = read(fd, buffer + bytes_read / sizeof(int16_t), total_bytes - bytes_read);
        if (n < 0) {
            if (errno == EINTR) {
                if (terminate) {
                    return -1;
                }
                continue;
            }
            fprintf(stderr, "I2S read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2S read returned 0 bytes unexpectedly\n");
            return -1;
        }
        bytes_read += n;
    }
    return 0;
}

static int write_pcm_file(const char *filename, const int16_t *buffer, size_t num_samples) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t written = fwrite(buffer, sizeof(int16_t), num_samples, fp);
    if (written != num_samples) {
        fprintf(stderr, "Failed to write to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_export(GPIO_SELECT_PIN) < 0) {
        return 1;
    }

    if (gpio_set_direction(GPIO_SELECT_PIN, "out") < 0) {
        gpio_unexport(GPIO_SELECT_PIN);
        return 1;
    }

    if (gpio_set_value(GPIO_SELECT_PIN, 0) < 0) {
        gpio_unexport(GPIO_SELECT_PIN);
        return 1;
    }

    int fd = i2s_init();
    if (fd < 0) {
        gpio_unexport(GPIO_SELECT_PIN);
        return 1;
    }

    int16_t *buffer = malloc(BUFFER_SIZE * sizeof(int16_t));
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate buffer: %s\n", strerror(errno));
        close(fd);
        gpio_unexport(GPIO_SELECT_PIN);
        return 1;
    }

    printf("Starting audio capture...\n");

    while (!terminate) {
        if (i2s_read(fd, buffer, BUFFER_SIZE) < 0) {
            break;
        }

        if (write_pcm_file(FILENAME, buffer, BUFFER_SIZE) < 0) {
            break;
        }

        gpio_set_value(GPIO_SELECT_PIN, 1);
        usleep(1000);
        gpio_set_value(GPIO_SELECT_PIN, 0);
        usleep(1000);
    }

    free(buffer);
    close(fd);
    gpio_unexport(GPIO_SELECT_PIN);

    printf("Audio capture stopped.\n");
    return 0;
}

