/*
 * Flame Detection System for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - SainSmart IR Flame Sensor Module (LM393 comparator with IR photodiode)
 *     DO  -> GPIO4  (BCM)
 *     VCC -> 3.3 V
 *     GND -> GND
 *   - Cooling fan (PWM-capable) on GPIO18 (BCM)
 *
 * Behavior:
 *   - Polls DO every 50 ms; debounces with a 50 ms software debounce.
 *   - On a LOW reading (flame detected) the fan is driven at 100 Hz via PWM.
 *   - Logs events to flame_log.txt with ISO-8601 timestamps.
 *   - Handles SIGINT / SIGTERM for clean shutdown.
 *   - Detects sensor-absent (no valid reading within a timeout) and logs it.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN          18

#define DEBOUNCE_MS      50
#define POLL_MS          50
#define PWM_FREQUENCY    100
#define PWM_DUTY_CYCLE   128   /* 50% of 255 */
#define TIMEOUT_MS       5000  /* sensor-absent timeout */

#define LOG_FILE         "flame_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (!g_log) return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log, "%s %s\n", ts, event);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", FLAME_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", FAN_PIN);
        return -1;
    }

    /* Ensure fan is off before starting PWM */
    if (gpioPWM(FAN_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM on GPIO%d.\n", FAN_PIN);
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void)
{
    int v = gpioRead(FLAME_SENSOR_PIN);
    if (v < 0) {
        fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return v;
}

static int start_fan(void)
{
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", FAN_PIN);
        return -1;
    }
    if (gpioPWM(FAN_PIN, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO%d.\n", FAN_PIN);
        return -1;
    }
    return 0;
}

static int stop_fan(void)
{
    if (gpioPWM(FAN_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to stop PWM on GPIO%d.\n", FAN_PIN);
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void)
{
    stop_fan();
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);   /* safe default */
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
