/*
 * AWR1642 mmWave radar SPI data logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   AWR1642 SPI  -> Pi SPI0 (CE0/GPIO8, SCLK/GPIO11, MOSI/GPIO10, MISO/GPIO9)
 *   AWR1642 TRIG -> Pi GPIO23 (BCM)
 *   AWR1642 DRDY -> Pi GPIO24 (BCM)
 *
 * Build: gcc -O2 -Wall -o radar_logger radar_logger.c -lgpiod -lrt
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define TRIGGER_PIN     23
#define DATA_READY_PIN  24

#define FRAME_PERIOD_MS 100
#define FRAME_SIZE_BYTES 32768
#define LOG_FILE_NAME   "radar_data.bin"

#define MAGIC_NUMBER    0x4144U

typedef struct {
    uint32_t magic;
    uint64_t timestamp;
    struct {
        uint32_t start_freq_hz;
        uint32_t end_freq_hz;
        uint32_t num_chirps;
        uint32_t num_samples;
    } config;
} __attribute__((packed)) log_header_t;

typedef struct {
    uint64_t timestamp;
    uint32_t frame_number;
} __attribute__((packed)) frame_meta_t;

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_trigger = NULL;
static struct gpiod_line *g_drdy = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto fail;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto fail;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        perror("gpiod_chip_open");
        return -1;
    }

    g_trigger = gpiod_chip_get_line(g_chip, TRIGGER_PIN);
    if (!g_trigger) {
        perror("gpiod_chip_get_line(trigger)");
        goto fail;
    }

    g_drdy = gpiod_chip_get_line(g_chip, DATA_READY_PIN);
    if (!g_drdy) {
        perror("gpiod_chip_get_line(drdy)");
        goto fail;
    }

    if (gpiod_line_request_output(g_trigger, "radar_logger", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto fail;
    }

    if (gpiod_line_request_input(g_drdy, "radar_logger") < 0) {
        perror("gpiod_line_request_input(drdy)");
        goto fail;
    }

    return 0;

fail:
    if (g_trigger) gpiod_line_release(g_trigger);
    if (g_drdy)    gpiod_line_release(g_drdy);
    gpiod_chip_close(g_chip);
    g_chip = NULL;
    g_trigger = NULL;
    g_drdy = NULL;
    return -1;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_trigger) {
        gpiod_line_set_value(g_trigger, 0);
        gpiod_line_release(g_trigger);
        g_trigger = NULL;
    }
    if (g_drdy) {
        gpiod_line_release(g_drdy);
        g_drdy = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE_NAME, "wb");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE_NAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    log_header_t header;
    header.magic = MAGIC_NUMBER;
    header.timestamp = (uint64_t)time(NULL);
    header.config.start_freq_hz = 770000000U;
    header.config.end_freq_hz   = 790000000U;
    header.config.num_chirps    = 64U;
    header.config.num_samples   = 256U;

    if (fwrite(&header, sizeof(header), 1, g_log_fp) != 1) {
        perror("fwrite(header)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("AWR1642 data logger started. Logging to %s\n", LOG_FILE_NAME);
    printf("  SPI: %s @ %u Hz, mode %u\n", SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE);
    printf("  GPIO23: trigger, GPIO24: data-ready\n");
    printf("  Frame period: %d ms, frame size: %d bytes\n",
           FRAME_PERIOD_MS, FRAME_SIZE_BYTES);

    uint32_t frame_number = 0;
    uint32_t consecutive_errors = 0;

    while (g_running) {
        /* Wait for data-ready interrupt (active-low) */
        int val = gpiod_line_get_value(g_drdy);
        if (val < 0) {
            perror("gpiod_line_get_value(drdy)");
            break;
        }
        if (val == 0) {
            /* Data ready — assert trigger */
            if (gpiod_line_set_value(g_trigger, 1) < 0) {
                perror("gpiod_line_set_value(trigger high)");
                break;
            }

            /* Small delay to let sensor latch the frame */
            usleep(1000);

            /* Read the frame */
            uint8_t *frame = malloc(FRAME_SIZE_BYTES);
            if (!frame) {
                fprintf(stderr, "malloc failed: %s\n", strerror(errno));
                consecutive_errors++;
                if (consecutive_errors > 10) {
                    fprintf(stderr, "Too many consecutive malloc failures, aborting.\n");
                    break;
                }
                gpiod_line_set_value(g_trigger, 0);
                continue;
            }

            size_t total = 0;
            while (total < FRAME_SIZE_BYTES) {
                size_t remaining = FRAME_SIZE_BYTES - total;
                size_t chunk = (remaining > 4096) ? 4096 : remaining;

                struct spi_ioc_transfer tr;
                memset(&tr, 0, sizeof(tr));
                tr.tx_buf = 0;
                tr.rx_buf = (unsigned long)(frame + total);
                tr.len = chunk;
                tr.speed_hz = SPI_SPEED_HZ;
                tr.bits_per_word = SPI_BITS;
                tr.delay_usecs = 0;
                tr.cs_change = 0;

                if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
                    perror("ioctl(SPI_IOC_MESSAGE)");
                    free(frame);
                    consecutive_errors++;
                    if (consecutive_errors > 10) {
                        fprintf(stderr, "Too many consecutive SPI errors, aborting.\n");
                        break;
                    }
                    gpiod_line_set_value(g_trigger, 0);
                    goto next_frame;
                }
                total += chunk;
            }

            if (total != FRAME_SIZE_BYTES) {
                fprintf(stderr, "SPI transfer incomplete: %zu bytes received\n", total);
                free(frame);
                consecutive_errors++;
                if (consecutive_errors > 10) {
                    fprintf(stderr, "Too many consecutive SPI errors, aborting.\n");
                    break;
                }
                gpiod_line_set_value(g_trigger, 0);
                goto next_frame;
            }

            consecutive_errors = 0;

            /* Log frame metadata */
            frame_meta_t meta;
            meta.timestamp = (uint64_t)time(NULL);
            meta.frame_number = frame_number;

            if (fwrite(&meta, sizeof(meta), 1, g_log_fp) != 1) {
                perror("fwrite(meta)");
                free(frame);
                break;
            }

            if (fwrite(frame, FRAME_SIZE_BYTES, 1, g_log_fp) != 1) {
                perror("fwrite(frame)");
                free(frame);
                break;
            }

            frame_number++;

            free(frame);
        }

    next_frame:
        /* De-assert trigger and wait for next frame */
        if (gpiod_line_set_value(g_trigger, 0) < 0) {
            perror("gpiod_line_set_value(trigger low)");
            break;
        }
        usleep(FRAME_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

