#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 20
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_flame_state(int flame_detected) {
    char timestamp[32];
    FILE *fp;

    if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Error: Failed to generate timestamp.\n");
        return -1;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s - Flame %s\n", timestamp, flame_detected ? "Detected" : "Cleared") < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;
    int prev_state = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_input(line, "ky026-flame") < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        if (value != prev_state) {
            if (log_flame_state(value) != 0) {
                fprintf(stderr, "Error: Failed to log flame state.\n");
            } else {
                printf("Flame %s\n", value ? "Detected" : "Cleared");
            }
            prev_state = value;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup_chip:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

