/*
 * OPT3001 Ambient Light Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   OPT3001 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   OPT3001 VDD  -> 3.3 V
 *   OPT3001 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3001_logger opt3001_logger.c -li2c
 * Run:    ./opt3001_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x44

/* OPT3001 register addresses */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01
#define REG_MANUFACTURER_ID 0x7E
#define REG_DEVICE_ID   0x7F

/* Configuration register bits */
#define CFG_RANGING_AUTO  0x0000  /* Automatic full-scale range */
#define CFG_CONV_TIME_100 0x0000  /* Conversion time 100 ms */
#define CFG_MODE_CONTINUOUS 0x0000 /* Continuous conversion mode */
#define CFG_LUX_1        0x0000  /* Full-scale range 1.0 to 40.0 lux */
#define CFG_DEFAULT      (CFG_RANGING_AUTO | CFG_CONV_TIME_100 | CFG_MODE_CONTINUOUS | CFG_LUX_1)

#define LOG_FILE        "light_data.txt"
#define SAMPLE_DELAY_US 100000  /* 100 ms */
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write16 to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* OPT3001 driver                                                      */
/* ------------------------------------------------------------------ */
static int opt3001_init(int fd)
{
    uint16_t manuf_id = 0, dev_id = 0;

    if (i2c_read16(fd, REG_MANUFACTURER_ID, &manuf_id) < 0) {
        fprintf(stderr, "Cannot read manufacturer ID — sensor may be absent.\n");
        return -1;
    }
    if (manuf_id != 0x5449) {
        fprintf(stderr, "Manufacturer ID mismatch: 0x%04X (expected 0x5449).\n", manuf_id);
        return -1;
    }

    if (i2c_read16(fd, REG_DEVICE_ID, &dev_id) < 0) {
        fprintf(stderr, "Cannot read device ID — sensor may be absent.\n");
        return -1;
    }
    if (dev_id != 0x3001) {
        fprintf(stderr, "Device ID mismatch: 0x%04X (expected 0x3001).\n", dev_id);
        return -1;
    }

    if (i2c_write16(fd, REG_CONFIG, CFG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to configure OPT3001.\n");
        return -1;
    }

    /* Allow first conversion to complete */
    usleep(100000);
    return 0;
}

static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read16(fd, REG_RESULT, &raw) == 0) {
            /* Result register: bits [15:1] = exponent, bits [0:0] = exponent status */
            uint16_t exponent = (raw >> 1) & 0x3FFF;
            uint16_t exponent_status = raw & 0x0001;
            if (exponent_status != 0) {
                fprintf(stderr, "Lux conversion not complete (status bit set).\n");
                return -1;
            }
            *lux_out = (float)exponent * 0.01f;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(10000);
        }
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                OPT3001_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (opt3001_init(g_i2c_fd) < 0) {
        fprintf(stderr, "OPT3001 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("OPT3001 initialized. Logging to %s every 100 ms. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        float lux;
        if (opt3001_read_lux(g_i2c_fd, &lux) == 0) {
            if (log_data(lux) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value after %d retries.\n", MAX_RETRIES);
        }
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

