/*
 * flame_detect.c — SainSmart IR Flame Detection Sensor reader
 *
 * Board : Raspberry Pi 3 Model B+
 * Sensor: SainSmart IR Flame Detection Module (DOUT on GPIO17, BCM)
 * Logic : DOUT is active-low (0 = flame detected, 1 = no flame).
 *
 * Build : gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17 */
#define POLL_INTERVAL_S  1           /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        perror("localtime_r()");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tmv) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }
    printf("%s", buf);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- open GPIO chip ------------------------------------------- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"" GPIO_CHIP_NAME "\")");
        return EXIT_FAILURE;
    }

    /* ---- get the line for BCM 17 ---------------------------------- */
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line(17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* ---- request the line as input with pull-up ------------------- */
    /*
     * The SainSmart module has an on-board pull-up; request it so the
     * line is never left floating.  The consumer label helps with
     * diagnostics.
     */
    struct gpiod_line_request_config req_cfg = {
        .consumer     = "flame-detector",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags        = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    if (gpiod_line_request(line, &req_cfg, 0) < 0) {
        perror("gpiod_line_request(BCM 17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame detection started on BCM GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* ---- main loop ------------------------------------------------- */
    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value()");
            break;
        }

        print_timestamp();
        printf(" Flame Detected: %s\n", (val == 0) ? "YES" : "NO");
        fflush(stdout);

        /* sleep() is interrupted by signals; loop will re-check g_running */
        unsigned int remaining = POLL_INTERVAL_S;
        while (remaining > 0 && g_running) {
            remaining = sleep(remaining);
        }
    }

    /* ---- cleanup --------------------------------------------------- */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

