#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LEFT_PIN   17
#define CENTER_PIN 18
#define RIGHT_PIN  27
#define POLL_US    50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int left, center, right;
    int rc;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Configure pins as inputs --- */
    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", LEFT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", CENTER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", RIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop --- */
    while (g_running) {
        left   = gpioRead(LEFT_PIN);
        center = gpioRead(CENTER_PIN);
        right  = gpioRead(RIGHT_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "gpioRead failed (L=%d C=%d R=%d)\n",
                    left, center, right);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        usleep(POLL_US);
    }

    /* --- Graceful shutdown --- */
    gpioTerminate();
    return EXIT_SUCCESS;
}

