#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL &&
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
        printf("[%s] ", buffer);
    } else {
        printf("[unknown] ");
    }
}

int main(void)
{
    int ret;
    int values[NUM_CHANNELS];
    int i;
    int exit_code = EXIT_SUCCESS;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure each GPIO pin as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpioSetMode(gpio_pins[i], PI_INPUT);
        if (ret != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM GPIO %u (code %d)\n",
                    gpio_pins[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Pins: OUT1=BCM2, OUT2=BCM3, OUT3=BCM4, OUT4=BCM5, OUT5=BCM6, OUT6=BCM7, OUT7=BCM8, OUT8=BCM9\n");
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        print_timestamp();

        for (i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpioRead(gpio_pins[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Error: gpioRead failed for BCM GPIO %u (code %d)\n",
                        gpio_pins[i], values[i]);
                exit_code = EXIT_FAILURE;
                goto cleanup;
            }
            printf("CH%u=%d ", i + 1, values[i]);
        }
        printf("\n");
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    gpioTerminate();
    printf("\nProgram terminated.\n");
    return exit_code;
}

