/*
 * Raspberry Pi 3 Model B+ — Dual TMAG5110 Hall-Effect Latch Sensor Logger
 *
 * Wiring:
 *   Sensor 1 OUT  -> BCM GPIO4  (physical pin 7)
 *   Sensor 2 OUT  -> BCM GPIO5  (physical pin 29)
 *   VCC           -> 3.3 V (physical pin 1)
 *   GND           -> GND   (physical pin 9)
 *   Both sensor OUT pins are open-drain with external pull-ups.
 *
 * Behavior:
 *   Every 500 ms the program reads the two sensor outputs and logs
 *   "Sensor 1: HIGH" or "Sensor 1: LOW" and "Sensor 2: HIGH" or
 *   "Sensor 2: LOW" to stdout.  A clean shutdown on SIGINT.
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lthe_driver_library -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#include <the_driver_library.h>  /* TMAG5110 driver header */

#define SENSOR1_PIN 4
#define SENSOR2_PIN 5
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* Retry if interrupted by a signal */
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    /* Initialize the TMAG5110 driver library */
    if (the_driver_library_init() != 0) {
        fprintf(stderr, "Error: TMAG5110 driver library initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs (external pull-ups drive the
     * sensor outputs high when a magnet is present). */
    if (the_driver_library_set_pin_mode(SENSOR1_PIN, THE_DRIVER_LIBRARY_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR1_PIN);
        the_driver_library_terminate();
        return EXIT_FAILURE;
    }
    if (the_driver_library_set_pin_mode(SENSOR2_PIN, THE_DRIVER_LIBRARY_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR2_PIN);
        the_driver_library_terminate();
        return EXIT_FAILURE;
    }

    printf("TMAG5110 dual sensor logger started.  Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int s1 = the_driver_library_read_pin(SENSOR1_PIN);
        int s2 = the_driver_library_read_pin(SENSOR2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Warning: read error on GPIO%d.\n", SENSOR1_PIN);
        }
        if (s2 < 0) {
            fprintf(stderr, "Warning: read error on GPIO%d.\n", SENSOR2_PIN);
        }

        printf("Sensor 1: %s | Sensor 2: %s\n",
               s1 == 0 ? "HIGH" : "LOW",
               s2 == 0 ? "HIGH" : "LOW");
        fflush(stdout);

        sleep_ms(POLL_INTERVAL_MS);
    }

    /* Clean shutdown */
    the_driver_library_terminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

