/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (TTP226 OUT -> Pi BCM pin):
 *   CH1 -> BCM2  (physical pin 3)
 *   CH2 -> BCM3  (physical pin 5)
 *   CH3 -> BCM4  (physical pin 7)
 *   CH4 -> BCM17 (physical pin 11)
 *   CH5 -> BCM27 (physical pin 13)
 *   CH6 -> BCM22 (physical pin 15)
 *   CH7 -> BCM10 (physical pin 19)
 *   CH8 -> BCM9  (physical pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226 ttp226.c -lpigpio -lrt
 * Run:    sudo ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 50000   /* 50 ms */
#define TIMESTAMP_LEN 32

static const unsigned int channel_pins[NUM_CHANNELS] = {
    2, 3, 4, 17, 27, 22, 10, 9
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1)
        return -1;
    if (localtime_r(&rawtime, &timeinfo) == NULL)
        return -1;
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0)
        return -1;
    return 0;
}

int main(void)
{
    int i;
    int ret;
    int values[NUM_CHANNELS];
    char timestamp[TIMESTAMP_LEN];

    /* --- Install signal handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure each channel as input with bias disabled --- */
    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpioSetMode(channel_pins[i], PI_INPUT);
        if (ret != 0) {
            fprintf(stderr,
                    "Error: gpioSetMode failed for BCM pin %u (code %d).\n",
                    channel_pins[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        ret = gpioSetPullUpDown(channel_pins[i], PI_PUD_OFF);
        if (ret != 0) {
            fprintf(stderr,
                    "Error: gpioSetPullUpDown failed for BCM pin %u (code %d).\n",
                    channel_pins[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Warning: failed to generate timestamp.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        for (i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpioRead(channel_pins[i]);
            if (values[i] < 0) {
                fprintf(stderr,
                        "Error: gpioRead failed for BCM pin %u (code %d).\n",
                        channel_pins[i], values[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
               timestamp,
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

