#define TILT_PIN 4
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int ret;
    int last_state = -1;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure tilt sensor pin as input with internal pull-up */
    ret = gpioSetMode(TILT_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input (code %d)\n", TILT_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(TILT_PIN, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d (code %d)\n", TILT_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", TILT_PIN);
    fflush(stdout);

    while (running) {
        int tilted = gpioRead(TILT_PIN);
        if (tilted < 0) {
            fprintf(stderr, "Error reading GPIO%d (code %d)\n", TILT_PIN, tilted);
            break;
        }

        if (tilted != last_state) {
            if (tilted == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            last_state = tilted;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

