#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UV_INDEX0 0x2C
#define SI1145_REG_UV_INDEX1 0x2D

#define SI1145_PART_ID 0x45

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Error: Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) {
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE1, 0x00) < 0) {
        return -1;
    }

    return 0;
}

static int read_si1145_data(int fd, float *uv_index, uint16_t *als_visible) {
    uint16_t uv_raw;
    if (i2c_read_reg16(fd, SI1145_REG_UV_INDEX0, &uv_raw) < 0) {
        return -1;
    }
    *uv_index = (float)uv_raw / 100.0f;

    if (i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, als_visible) < 0) {
        return -1;
    }

    return 0;
}

static void log_data(FILE *fp, float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(fp);
}

int main() {
    int fd = -1;
    FILE *fp = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        goto cleanup;
    }

    if (init_si1145(fd) < 0) {
        fprintf(stderr, "Error: Failed to initialize Si1145 sensor.\n");
        goto cleanup;
    }

    fp = fopen("uv_als_log.csv", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        goto cleanup;
    }

    while (running) {
        float uv_index;
        uint16_t als_visible;

        if (read_si1145_data(fd, &uv_index, &als_visible) < 0) {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
            break;
        }

        printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
        log_data(fp, uv_index, als_visible);

        sleep(1);
    }

    ret = 0;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

