/*
 * Raspberry Pi 5 – Dual SLF3S-0600F Liquid Flow Sensor Monitor
 *
 * Wiring:
 *   Sensor 1 SDA -> GPIO2 (I2C1 SDA), SCL -> GPIO3 (I2C1 SCL)
 *   Sensor 2 SDA -> GPIO2 (I2C1 SDA), SCL -> GPIO3 (I2C1 SCL)
 *   Alarm    -> GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define ALARM_GPIO_LINE  17
#define LOG_FILE         "flow_log.txt"
#define FLOW_THRESHOLD   0.5f
#define SAMPLE_PERIOD_S  1
#define STARTUP_DELAY_S  0.1
#define MEAS_DELAY_S     1.0

/* SLF3S-0600F command opcodes (16-bit, big-endian on the wire) */
#define CMD_START_MEAS   0x3600
#define CMD_READ_MEAS    0x3601

/* SLF3S-0600F measurement data layout (big-endian) */
#define MEAS_LEN         6
#define MEAS_FLOW_MSB    0
#define MEAS_FLOW_LSB    1
#define MEAS_SCALE_MSB   2
#define MEAS_SCALE_LSB   3
#define MEAS_CRC         4

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion 8-bit CRC4, polynomial 0x31, init 0x00 */
static uint8_t crc4(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x08) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc & 0x0F;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int start_sensor(int fd)
{
    return i2c_write_cmd(fd, CMD_START_MEAS);
}

static int read_flow_rate(int fd, float *flow_out)
{
    uint8_t buf[MEAS_LEN];

    if (i2c_write_cmd(fd, CMD_READ_MEAS) < 0)
        return -1;

    usleep(2000); /* 2 ms conversion time */

    if (i2c_read_data(fd, buf, MEAS_LEN) < 0)
        return -1;

    if (crc4(&buf[MEAS_FLOW_MSB], 2) != buf[MEAS_CRC]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[MEAS_FLOW_MSB] << 8) | buf[MEAS_FLOW_LSB];
    uint16_t scale = ((uint16_t)buf[MEAS_SCALE_MSB] << 8) | buf[MEAS_SCALE_LSB];

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor 0\n");
        return -1;
    }

    *flow_out = (float)raw / (float)scale;
    return 0;
}

static void log_flow(FILE *fp, float avg, bool alarm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Average Flow: %.2f ml/min, Alarm: %s\n",
            ts, avg, alarm ? "ON" : "OFF");
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request alarm line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    struct gpiod_line *alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO_LINE);
    if (!alarm_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(alarm_line, "flow_monitor", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Start both sensors */
    if (start_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Failed to start sensor 1\n");
        fclose(log_fp);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    usleep(STARTUP_DELAY_S * 1000000);

    printf("Monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float sum = 0.0f;
        int valid = 0;

        for (int i = 0; i < 2; i++) {
            float flow;
            if (read_flow_rate(i2c_fd, &flow) == 0) {
                sum += flow;
                valid++;
            } else {
                fprintf(stderr, "Sensor %d read failed; skipping\n", i + 1);
            }
        }

        if (valid == 0) {
            fprintf(stderr, "No valid readings; skipping cycle\n");
        } else {
            float avg = sum / (float)valid;
            bool alarm = (avg < FLOW_THRESHOLD);
            if (gpiod_line_set_value(alarm_line, alarm ? 1 : 0) < 0)
                perror("gpiod_line_set_value");
            log_flow(log_fp, avg, alarm);
        }

        sleep(SAMPLE_PERIOD_S);
    }

    /* Clean shutdown */
    gpiod_line_set_value(alarm_line, 0);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    fclose(log_fp);
    close(i2c_fd);
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

