    uint16_t scale = ((uint16_t)buf[MEAS_SCALE_MSB] << 8) | buf[MEAS_SCALE_LSB];

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor 0\n");
        return -1;
    }

    *flow_out = (float)raw / (float)scale;
    return 0;
}

static void log_flow(FILE *fp, float avg, bool alarm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Average Flow: %.2f ml/min, Alarm: %s\n",
            ts, avg, alarm ? "ON" : "OFF");
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request alarm line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    struct gpiod_line *alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO_LINE);
    if (!alarm_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(alarm_line, "flow_monitor", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Start both sensors */
    if (start_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Failed to start sensor 1\n");
        fclose(log_fp);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    usleep(STARTUP_DELAY_S * 1000000);

    printf("Monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float sum = 0.0f;
        int valid = 0;

        for (int i = 0; i < 2; i++) {
            float flow;
            if (read_flow_rate(i2c_fd, &flow) == 0) {
                sum += flow;
                valid++;
            } else {
                fprintf(stderr, "Sensor %d read failed; skipping\n", i + 1);
            }
        }

        if (valid == 0) {
            fprintf(stderr, "No valid readings; skipping cycle\n");
        } else {
            float avg = sum / (float)valid;
            bool alarm = (avg < FLOW_THRESHOLD);
            if (gpiod_line_set_value(alarm_line, alarm ? 1 : 0) < 0)
                perror("gpiod_line_set_value");
            log_flow(log_fp, avg, alarm);
        }

        sleep(SAMPLE_PERIOD_S);
    }

    /* Clean shutdown */
    gpiod_line_set_value(alarm_line, 0);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    fclose(log_fp);
    close(i2c_fd);
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

