#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 50000

typedef struct {
    time_t timestamp;
    int    obstacle_detected;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int obstacle_detected) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }
    circular_buffer[buffer_index].timestamp = now;
    circular_buffer[buffer_index].obstacle_detected = obstacle_detected;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void dump_buffer(void) {
    printf("\n--- Circular Buffer Dump (oldest first) ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        if (localtime_r(&circular_buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts, sizeof(ts), "<time-error>");
        }
        printf("[%s] Obstacle: %s\n", ts,
               circular_buffer[idx].obstacle_detected ? "DETECTED" : "clear");
    }
    printf("--- End of Dump ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO%d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", SENSOR_PIN);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int obstacle_detected = (level == 0) ? 1 : 0;

        if (obstacle_detected) {
            printf("Obstacle detected!\n");
            log_data(1);
        } else {
            log_data(0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    dump_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

