/*
 * Raspberry Pi 5 - Omron D7S Vibration Sensor Logger
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (BCM 2, I2C1 SDA)
 *   D7S SCL  -> GPIO3 (BCM 3, I2C1 SCL)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *
 * I2C bus: /dev/i2c-1  Address: 0x50 (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- D7S constants (verified against datasheet) ---- */
#define D7S_I2C_ADDR        0x50
#define I2C_BUS             "/dev/i2c-1"

#define REG_MODE            0x00
#define REG_X_LSB           0x02
#define REG_X_MSB           0x03
#define REG_Y_LSB           0x04
#define REG_Y_MSB           0x05
#define REG_Z_LSB           0x06
#define REG_Z_MSB           0x07
#define REG_STATUS          0x0A

#define MODE_ACTIVE         0x01
#define MODE_STANDBY        0x00

#define ACTIVE_TIMEOUT_SEC  1
#define POLL_INTERVAL_MS    500
#define CSV_FILENAME        "fan_health.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* D7S requires a register pointer write before a repeated-start read. */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg pointer 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd of %zu)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int d7s_set_mode(int fd, uint8_t mode)
{
    return i2c_write_byte(fd, REG_MODE, mode);
}

/* ------------------------------------------------------------------ */
static int d7s_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, REG_X_LSB, raw, sizeof(raw)) != 0)
        return -1;

    *x = (int16_t)((raw[1] << 8) | raw[0]);
    *y = (int16_t)((raw[3] << 8) | raw[2]);
    *z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int d7s_wait_active(int fd)
{
    time_t start = time(NULL);
    uint8_t status;

    while (g_running) {
        if (i2c_read_block(fd, REG_STATUS, &status, 1) != 0)
            return -1;

        if ((status & 0x01) == MODE_ACTIVE)
            return 0;

        if (time(NULL) - start >= ACTIVE_TIMEOUT_SEC) {
            fprintf(stderr, "D7S did not become active within %d s\n",
                    ACTIVE_TIMEOUT_SEC);
            return -1;
        }
        usleep(50 * 1000); /* 50 ms */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int csv_open(const char *filename)
{
    int is_new = (access(filename, F_OK) != 0);
    FILE *f = fopen(filename, "a");
    if (!f) {
        fprintf(stderr, "Cannot open CSV '%s': %s\n", filename, strerror(errno));
        return -1;
    }
    if (is_new) {
        fprintf(f, "timestamp,x,y,z\n");
        fflush(f);
    }
    return fileno(f);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Put sensor in standby first, then active mode. */
    if (d7s_set_mode(g_i2c_fd, MODE_STANDBY) != 0) {
        fprintf(stderr, "Failed to set D7S to standby mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(10 * 1000);

    if (d7s_set_mode(g_i2c_fd, MODE_ACTIVE) != 0) {
        fprintf(stderr, "Failed to set D7S to active mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (d7s_wait_active(g_i2c_fd) != 0) {
        fprintf(stderr, "D7S did not become active\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_csv = fdopen(csv_open(CSV_FILENAME), "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot fdopen CSV: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging D7S vibration data to %s (Ctrl+C to stop)\n", CSV_FILENAME);

    while (g_running) {
        int16_t x, y, z;
        if (d7s_read_xyz(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error; retrying next cycle\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

        fprintf(g_csv, "%s,%d,%d,%d\n", ts, x, y, z);
        fflush(g_csv);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

