/*
 * Raspberry Pi 4 Model B — Dual KY-032 IR Obstacle Avoidance Sensor
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   KY-032 #1 OUT -> GPIO23 (BCM)
 *   KY-032 #2 OUT -> GPIO24 (BCM)
 *   LED anode     -> GPIO25 (BCM) via 220-330 ohm resistor to GND
 *
 * Behavior:
 *   Polls the two sensors every 100 ms.  Lights the LED when either
 *   sensor reads LOW (obstacle detected), and turns it off when both
 *   sensors read HIGH.  Checks every library call and releases all
 *   resources on every exit path (including SIGINT/SIGTERM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN      25

#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Turn LED off before terminating pigpio */
    if (gpioInitialise() >= 0) {
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    /* Initialize pigpio */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts OFF */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW.\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    if (install_signal_handlers() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-032 sensors on GPIO%d and GPIO%d.\n",
           SENSOR_1_PIN, SENSOR_2_PIN);
    printf("LED on GPIO%d. Press Ctrl+C to exit.\n", LED_PIN);

    /* Main polling loop */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Warning: sensor read error (s1=%d, s2=%d).\n",
                    s1, s2);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-032 OUT is active-LOW: 0 => obstacle detected */
        bool obstacle = (s1 == 0 || s2 == 0);

        if (gpioWrite(LED_PIN, obstacle ? 1 : 0) != 0) {
            fprintf(stderr, "Warning: failed to write LED state.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

