/*
 * MLX90217 Hall-effect RPM logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX90217 VCC  -> 3.3 V (Pin 1)
 *   MLX90217 GND  -> GND   (Pin 9)
 *   MLX90217 OUT  -> GPIO4 (Pin 7, BCM 4)
 *
 * The internal pull-up on the GPIO line is enabled so the line is never
 * floating when the sensor is absent or not rotating.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rpm_logger rpm_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./rpm_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN          4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE          "rpm_log.txt"
#define SAMPLE_PERIOD_S   1          /* seconds between logged samples */
#define PULSES_PER_REV    1          /* MLX90217 one pulse per revolution */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static FILE                 *g_log_fp      = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* tell main loop to exit cleanly          */
}

/* ------------------------------------------------------------------ */
/* GPIO alert callback (runs in pigpio's notification thread)           */
/* ------------------------------------------------------------------ */

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {       /* rising edge: one pulse counted          */
        __sync_fetch_and_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void get_timestamp(char *buf, size_t len)
{
    time_t     t  = time(NULL);
    struct tm  tm;

    if (localtime_r(&t, &tm) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(buf, len, "----/--/-- --:--:--");
    }
}

static void log_rpm(float rpm)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s %.2f\n", ts, rpm);
        fflush(g_log_fp);
    }
    printf("%s %.2f\n", ts, rpm);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Disable the alert callback so no more notifications arrive. */
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    /* Disable the timer alert. */
    gpioSetTimerFuncEx(0, 0, NULL, NULL);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for BCM GPIO%d.\n",
                GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for BCM GPIO%d.\n",
                GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- register alert callback ---- */
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx failed for BCM GPIO%d.\n",
                GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- start 1-second timer ---- */
    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_S * 1000, NULL, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM logger started.  GPIO%d, %d pulses/rev, %d s interval.\n",
           GPIO_PIN, PULSES_PER_REV, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        gpioDelay(100 * 1000);   /* 100 ms sleep to reduce CPU usage */

        uint32_t pulses = __sync_fetch_and_and(&g_pulse_count, 0);
        float    rpm    = (float)pulses / (float)PULSES_PER_REV * (60.0f / (float)SAMPLE_PERIOD_S);

        log_rpm(rpm);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

