code:
/*
 * Quadrature Hall-effect rotation logger for Raspberry Pi Zero W.
 *
 * Two Melexis MLX90217 unipolar Hall sensors are wired to the GPIO bus:
 *   Sensor A -> GPIO17 (BCM)
 *   Sensor B -> GPIO27 (BCM)
 * Hardware pull-ups (90° electrical offset) are required for the quadrature
 * detection to distinguish clockwise/counter-clockwise rotation.
 *
 * The program logs each rotation event to rotation_log.txt with millisecond
 * precision timestamps: "YYYY-MM-DD HH:MM:SS.mmm".
 *
 * Build:  gcc -O2 -Wall -Wextra -o rotation_logger rotation_logger.c -lpigpio -lrt
 * Run:    sudo ./rotation_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE     "rotation_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms main-loop sleep */

/* ------------------------------------------------------------------ */
/* Shared state between ISR and main thread                           */
/* ------------------------------------------------------------------ */

typedef struct {
    int      a;          /* 0 or 1 */
    int      b;          /* 0 or 1 */
    int      direction;  /* 1 = CW, -1 = CCW, 0 = no change */
    int      valid;      /* 1 if both edges seen, 0 otherwise */
} quadrature_state_t;

static quadrature_state_t g_state = {0, 0, 0, 0};
static FILE              *g_log   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* ISR — pigpio dispatches this on a dedicated thread                   */
/* ------------------------------------------------------------------ */

static void isr_handler(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)tick;
    (void)userdata;

    if (level != 1)            /* only rising edges */
        return;

    int a = gpioRead(SENSOR_A_PIN);
    int b = gpioRead(SENSOR_B_PIN);

    if (a < 0 || b < 0) {
        fprintf(stderr, "ISR: gpioRead failed on pin %d (a=%d, b=%d)\n",
                gpio, a, b);
        return;
    }

    quadrature_state_t *st = &g_state;

    /* Quadrature state transition table */
    if (a == 1 && b == 0) {
        if (st->a == 1 && st->b == 0) { /* 00 -> 01 */
            st->direction = 1;
        } else {                       /* 10 -> 01 */
            st->direction = -1;
        }
        st->a = 1; st->b = 0;
    } else if (a == 0 && b == 1) {
        if (st->a == 0 && st->b == 1) { /* 01 -> 00 */
            st->direction = -1;
        } else {                       /* 01 -> 10 */
            st->direction = 1;
        }
        st->a = 0; st->b = 1;
    } else {
        /* Invalid transition — ignore */
        return;
    }

    st->valid = 1;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void timestamp_ms(char *buf, size_t len)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "TIMESTAMP_ERROR");
        return;
    }

    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);

    char date[32];
    strftime(date, sizeof(date), "%Y-%m-%d %H:%M:%S", &tm);

    snprintf(buf, len, "%s.%03ld", date, ts.tv_nsec / 1000000L);
}

static void log_rotation(int direction)
{
    char ts[32];
    timestamp_ms(ts, sizeof(ts));

    if (g_log) {
        fprintf(g_log, "%s, Direction: %s\n", ts,
                direction == 1 ? "CW" : "CCW");
        fflush(g_log);
    } else {
        fprintf(stderr, "Log file not open; event lost: %s, Direction: %s\n",
                ts, direction == 1 ? "CW" : "CCW");
    }
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure pins ---- */
    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_A_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_B_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so the sensors read 1 when idle */
    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_A_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_B_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- register ISR ---- */
    if (gpioSetISRFuncEx(SENSOR_A_PIN, RISING_EDGE, 0, isr_handler, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO%d\n", SENSOR_A_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Quadrature rotation logger started.\n");
    printf("  Sensor A: GPIO%d\n  Sensor B: GPIO%d\n  Log: %s\n",
           SENSOR_A_PIN, SENSOR_B_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        if (g_state.valid) {
            log_rotation(g_state.direction);
            g_state.valid = 0;
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

