#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>

#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO          18
#define POLL_INTERVAL_MS  50
#define CONSUMER_NAME     "touch_led"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static void log_event(int priority, const char *message)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char time_buf[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
        syslog(priority, "[%s] %s", time_buf, message);
    } else {
        syslog(priority, "%s", message);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    openlog(CONSUMER_NAME, LOG_PID | LOG_CONS, LOG_USER);

    log_event(LOG_INFO, "Starting touch sensor monitoring...");

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_event(LOG_ERR, "Failed to register SIGINT handler");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_event(LOG_ERR, "Failed to register SIGTERM handler");
        goto cleanup;
    }

    /* Open the default GPIO chip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        log_event(LOG_ERR, "Failed to open gpiochip0: " + strerror(errno));
        goto cleanup;
    }

    /* Get the touch sensor line (input) */
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_GPIO);
    if (touch_line == NULL) {
        log_event(LOG_ERR, "Failed to get GPIO line " + TO_STRING(TOUCH_SENSOR_GPIO) + ": " + strerror(errno));
        goto cleanup;
    }

    /* Request the touch sensor line as input */
    if (gpiod_line_request_input(touch_line, CONSUMER_NAME) < 0) {
        log_event(LOG_ERR, "Failed to request GPIO " + TO_STRING(TOUCH_SENSOR_GPIO) + " as input: " + strerror(errno));
        goto cleanup;
    }

    /* Get the LED line (output) */
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (led_line == NULL) {
        log_event(LOG_ERR, "Failed to get GPIO line " + TO_STRING(LED_GPIO) + ": " + strerror(errno));
        goto cleanup;
    }

    /* Request the LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, CONSUMER_NAME, 0) < 0) {
        log_event(LOG_ERR, "Failed to request GPIO " + TO_STRING(LED_GPIO) + " as output: " + strerror(errno));
        goto cleanup;
    }

    log_event(LOG_INFO, "GPIO initialization complete. Monitoring touch sensor...");

    /* Main polling loop */
    while (program_running) {
        int touch_value = gpiod_line_get_value(touch_line);
        if (touch_value < 0) {
            log_event(LOG_ERR, "Failed to read touch sensor value: " + strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (touch_value == 1) {
            /* Touch detected: turn LED on */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                log_event(LOG_ERR, "Failed to turn LED on: " + strerror(errno));
            } else {
                log_event(LOG_INFO, "Touch detected, LED turned ON");
            }
        } else {
            /* No touch: turn LED off */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                log_event(LOG_ERR, "Failed to turn LED off: " + strerror(errno));
            } else {
                log_event(LOG_INFO, "No touch, LED turned OFF");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event(LOG_INFO, "Shutting down...");
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off on exit */
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    log_event(LOG_INFO, "Program terminated.");
    closelog();
    return ret;
}

