/*
 * TTP223B capacitive touch sensor → LED toggle on Raspberry Pi 3 Model B+
 * Touch input : SainSmart TTP223B OUT  → GPIO17 (physical pin 11)
 * LED output  : GPIO18 (physical pin 12)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_led touch_led.c -lgpiod
 *
 * The TTP223B has an internal pull-down so the line reads LOW when touched
 * and HIGH when untouched.  We request rising-edge events so the LED toggles
 * on each new touch.
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define TOUCH_PIN  17   /* GPIO17, physical pin 11 */
#define LED_PIN    18   /* GPIO18, physical pin 12 */

#define DEBOUNCE_MS 50   /* software debounce after a rising edge */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    while (nanosleep(&ts, &ts) != 0) {
        if (errno != EINTR)
            break;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    /* Open the default gpiochip (gpiochip0 on Pi 3B+). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (touch_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW. */
    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line %d as output: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request touch line for rising-edge events. */
    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223b-touch") < 0) {
        fprintf(stderr, "Failed to request touch line %d for rising-edge events: %s\n",
                TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor ready.  Touch GPIO%d to toggle LED on GPIO%d.\n",
           TOUCH_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    bool led_state = false;

    while (g_running) {
        /*
         * Block up to 1 s waiting for a rising edge on the touch line.
         * If a signal arrives during the wait, gpiod_line_event_wait()
         * returns -1 with errno set to EINTR.
         */
        int rc = gpiod_line_event_wait(touch_line, &(struct timespec){1, 0});
        if (rc < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        if (rc == 0)
            continue;                       /* timeout, no event */

        /* Consume the event so it is not lost. */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n",
                    strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE)
            continue;

        /* Debounce: ignore events within DEBOUNCE_MS of the last one. */
        sleep_ms(DEBOUNCE_MS);

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state ? 1 : 0) < 0) {
            fprintf(stderr, "Failed to set LED line value: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        printf("Touch detected — LED %s\n", led_state ? "ON" : "OFF");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL)
        gpiod_line_release(led_line);
    if (touch_line != NULL)
        gpiod_line_release(touch_line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

