         * If a signal arrives during the wait, gpiod_line_event_wait()
         * returns -1 with errno set to EINTR.
         */
        int rc = gpiod_line_event_wait(touch_line, &(struct timespec){1, 0});
        if (rc < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        if (rc == 0)
            continue;                       /* timeout, no event */

        /* Consume the event so it is not lost. */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n",
                    strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE)
            continue;

        /* Debounce: ignore events within DEBOUNCE_MS of the last one. */
        sleep_ms(DEBOUNCE_MS);

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state ? 1 : 0) < 0) {
            fprintf(stderr, "Failed to set LED line value: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        printf("Touch detected — LED %s\n", led_state ? "ON" : "OFF");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL)
        gpiod_line_release(led_line);
    if (touch_line != NULL)
        gpiod_line_release(touch_line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

