#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22
#define BUFFER_SIZE 100
#define DEBOUNCE_US 50000

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} TouchEvent;

static TouchEvent touch_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_tail = 0;
static int overflow_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_touch_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    touch_buffer[buffer_head].sensor_pin = sensor_pin;
    touch_buffer[buffer_head].timestamp = now;
    touch_buffer[buffer_head].state = state;

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    if (buffer_head == buffer_tail) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        overflow_count++;
    }
}

static void print_log_buffer(void) {
    printf("\n--- Touch Event Log ---\n");
    if (buffer_tail == buffer_head) {
        printf("No events recorded.\n");
    } else {
        int count = 0;
        int idx = buffer_tail;
        while (idx != buffer_head) {
            printf("  [%d] Sensor: %d, Timestamp: %ld, State: %d\n",
                   count,
                   touch_buffer[idx].sensor_pin,
                   (long)touch_buffer[idx].timestamp,
                   touch_buffer[idx].state);
            idx = (idx + 1) % BUFFER_SIZE;
            count++;
        }
    }
    printf("Overflow count: %d\n", overflow_count);
    printf("--- End of Log ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED GPIO%d to LOW\n", LED_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED GPIO%d to LOW\n", LED_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int prev_state1 = gpioRead(SENSOR_1_PIN);
    int prev_state2 = gpioRead(SENSOR_2_PIN);

    if (prev_state1 < 0 || prev_state2 < 0) {
        fprintf(stderr, "Initial sensor read failed\n");
        gpioWrite(LED_1_PIN, 0);
        gpioWrite(LED_2_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int cur_state1 = gpioRead(SENSOR_1_PIN);
        int cur_state2 = gpioRead(SENSOR_2_PIN);

        if (cur_state1 < 0 || cur_state2 < 0) {
            fprintf(stderr, "Sensor read error (s1=%d, s2=%d)\n", cur_state1, cur_state2);
        } else {
            if (cur_state1 != prev_state1) {
                gpioWrite(LED_1_PIN, cur_state1);
                log_touch_event(SENSOR_1_PIN, cur_state1);
                prev_state1 = cur_state1;
            }
            if (cur_state2 != prev_state2) {
                gpioWrite(LED_2_PIN, cur_state2);
                log_touch_event(SENSOR_2_PIN, cur_state2);
                prev_state2 = cur_state2;
            }
        }

        gpioDelay(DEBOUNCE_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    print_log_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

