#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_DELAY_US 5000
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio) {
    return gpioRead(gpio);
}

static void log_data(int s1, int s2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%d,%d\n", ts, s1, s2);
    } else {
        fprintf(fp, "timestamp_error,%d,%d\n", s1, s2);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

static void calculate_rpm(int s1, int s2) {
    static int prev_s1 = -1, prev_s2 = -1;
    static uint32_t last_change_tick = 0;

    uint32_t now = gpioTick();

    if (s1 != prev_s1 || s2 != prev_s2) {
        if (prev_s1 != -1 && prev_s2 != -1) {
            uint32_t elapsed = now - last_change_tick;
            if (elapsed > 0) {
                float rpm = 60000000.0f / (float)elapsed;
                printf("RPM: %.2f\n", rpm);
            }
        }
        prev_s1 = s1;
        prev_s2 = s2;
        last_change_tick = now;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring shaft RPM on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n", SENSOR1_GPIO, SENSOR2_GPIO);

    while (running) {
        int s1 = read_sensor(SENSOR1_GPIO);
        int s2 = read_sensor(SENSOR2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor GPIOs\n");
            break;
        }

        log_data(s1, s2);
        calculate_rpm(s1, s2);

        gpioDelay(DEBOUNCE_DELAY_US);
