#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_INT_STATUS 0x04
#define REG_MEAS_RATE 0x05
#define REG_ALS_RATE 0x06
#define REG_ALS_DATA 0x07
#define REG_HR_DATA 0x08
#define REG_SPO2_DATA 0x09
#define REG_COMMAND 0x0A

#define CMD_RESET 0x01
#define CMD_START 0x02
#define CMD_STOP 0x03

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int init_si1182(void) {
    uint8_t part_id = 0;
    if (read_reg(REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    fprintf(stderr, "Si1182 part ID: 0x%02X\n", part_id);

    if (write_reg(REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10000); /* 10 ms reset delay */

    if (write_reg(REG_MEAS_RATE, 0x0A) < 0) return -1;
    if (write_reg(REG_ALS_RATE, 0x0A) < 0) return -1;
    if (write_reg(REG_INT_CFG, 0x00) < 0) return -1;

    if (write_reg(REG_COMMAND, CMD_START) < 0) return -1;
    gpioDelay(10000); /* 10 ms start-up delay */
    return 0;
}

static int read_sensor_data(uint8_t *hr, uint8_t *spo2) {
    uint8_t hr_val = 0, spo2_val = 0;

    if (read_reg(REG_HR_DATA, &hr_val) < 0) return -1;
    if (read_reg(REG_SPO2_DATA, &spo2_val) < 0) return -1;

    *hr = hr_val;
    *spo2 = spo2_val;
    return 0;
}

static void log_data(uint8_t hr, uint8_t spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %u BPM, SpO2: %u%%\n", timestamp, hr, spo2);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1182() < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(stderr, "Starting data acquisition. Press Ctrl+C to stop.\n");

    while (running) {
        uint8_t hr = 0, spo2 = 0;
        if (read_sensor_data(&hr, &spo2) == 0) {
            log_data(hr, spo2);
        } else {
            fprintf(stderr, "Sensor read error; continuing.\n");
        }
        gpioDelay(1000000); /* 1 second */
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

