/*
 * Bridge Integrity Monitor — Raspberry Pi Zero W
 *
 * Sensors : 2 × Omron D7E-3 tilt switches (digital, active-HIGH)
 *   Sensor 1 : GPIO17 (BCM)
 *   Sensor 2 : GPIO18 (BCM)
 * Alarm   : Active-HIGH buzzer/LED on GPIO27 (BCM)
 *
 * Behavior:
 *   - Polls each sensor every 100 ms.
 *   - Logs tilt events to bridge_integrity.log (ISO-8601 timestamps).
 *   - Activates alarm if either sensor reads HIGH for > 2 s.
 *   - Deactivates alarm when both sensors return to LOW.
 *   - Clean shutdown on SIGINT / SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o bridge_monitor bridge_monitor.c -lpigpio -lrt
 * Run  :  sudo ./bridge_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SENSOR_1_PIN  17
#define SENSOR_2_PIN  18
#define ALARM_PIN     27

/* ---- Timing constants ---- */
#define POLL_INTERVAL_US   100000   /* 100 ms */
#define ALARM_HOLD_US      2000000  /* 2 s   */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;            /* tell main loop to exit cleanly        */
}

/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, const char *event)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];

    if (localtime_r(&now, &tm_buf) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s %s\n", ts, event) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_1_PIN) failed\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_2_PIN) failed\n");
        return -1;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ALARM_PIN) failed\n");
        return -1;
    }

    /* Internal pull-down so the line reads LOW when sensor is idle */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR_1_PIN) failed\n");
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR_2_PIN) failed\n");
        return -1;
    }

    /* Start with alarm OFF */
    if (gpioWrite(ALARM_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(ALARM_PIN, 0) failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Best-effort alarm-off and pigpio teardown */
    if (g_log) {
        gpioWrite(ALARM_PIN, 0);
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log = fopen("bridge_integrity.log", "a");
    if (!g_log) {
        perror("fopen(bridge_integrity.log)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize GPIO ---- */
    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitor started.  Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    int alarm_active = 0;

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d s2=%d)\n", s1, s2);
            break;
        }

        /* Sensor 1 — tilt-start / tilt-end */
        if (s1 == 1 && !alarm_active) {
            log_event(g_log, "Tilt_Start");
            alarm_active = 1;
            if (gpioWrite(ALARM_PIN, 1) < 0) {
                fprintf(stderr, "gpioWrite(ALARM_PIN, 1) failed\n");
                break;
            }
        } else if (s1 == 0 && alarm_active) {
            log_event(g_log, "Tilt_End");
            alarm_active = 0;
            if (gpioWrite(ALARM_PIN, 0) < 0) {
                fprintf(stderr, "gpioWrite(ALARM_PIN, 0) failed\n");
                break;
            }
        }

        /* Sensor 2 — threshold-exceeded */
        if (s2 == 1 && alarm_active) {
            log_event(g_log, "Threshold_Exceeded");
        }

        /* Alarm hold timer (2 s) — if both sensors return LOW, reset */
        if (s1 == 0 && s2 == 0 && alarm_active) {
            alarm_active = 0;
            if (gpioWrite(ALARM_PIN, 0) < 0) {
                fprintf(stderr, "gpioWrite(ALARM_PIN, 0) failed\n");
                break;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    printf("Bridge integrity monitor stopped.\n");
    return EXIT_SUCCESS;
}

