    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log = fopen("bridge_integrity.log", "a");
    if (!g_log) {
        perror("fopen(bridge_integrity.log)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize GPIO ---- */
    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitor started.  Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    int alarm_active = 0;

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d s2=%d)\n", s1, s2);
            break;
        }

        /* Sensor 1 — tilt-start / tilt-end */
        if (s1 == 1 && !alarm_active) {
            log_event(g_log, "Tilt_Start");
            alarm_active = 1;
            if (gpioWrite(ALARM_PIN, 1) < 0) {
                fprintf(stderr, "gpioWrite(ALARM_PIN, 1) failed\n");
                break;
            }
        } else if (s1 == 0 && alarm_active) {
            log_event(g_log, "Tilt_End");
            alarm_active = 0;
            if (gpioWrite(ALARM_PIN, 0) < 0) {
                fprintf(stderr, "gpioWrite(ALARM_PIN, 0) failed\n");
                break;
            }
        }

        /* Sensor 2 — threshold-exceeded */
        if (s2 == 1 && alarm_active) {
            log_event(g_log, "Threshold_Exceeded");
        }

        /* Alarm hold timer (2 s) — if both sensors return LOW, reset */
        if (s1 == 0 && s2 == 0 && alarm_active) {
            alarm_active = 0;
            if (gpioWrite(ALARM_PIN, 0) < 0) {
                fprintf(stderr, "gpioWrite(ALARM_PIN, 0) failed\n");
                break;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    printf("Bridge integrity monitor stopped.\n");
    return EXIT_SUCCESS;
}

