/*
 * Seismic sensor monitor for Raspberry Pi 3 Model B+
 * Sensor : Omron D7S-A0011 on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * LED    : Alert on GPIO17 (BCM)
 * Build  : gcc -O2 -Wall -o seismic seismic.c -lthe driver library -lm -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS             1
#define I2C_ADDR            0x1C          /* D7S-A0011 7-bit I2C address */
#define LED_GPIO            17
#define VIBRATION_THRESHOLD 500.0f
#define POLL_INTERVAL_US    100000        /* 100 ms */
#define ALERT_DURATION_US   1000000       /* 1 s   */
#define MAX_RETRIES         3
#define LOG_FILE            "seismic_events.log"

/* ---- D7S-A0011 register addresses ---- */
#define D7S_WHO_AM_I        0x0F
#define D7S_WHO_AM_I_VAL    0x0D
#define D7S_CTRL1           0x20
#define D7S_OUT_X_L         0x28
#define D7S_OUT_X_H         0x29
#define D7S_OUT_Y_L         0x2A
#define D7S_OUT_Y_H         0x2B
#define D7S_OUT_Z_L         0x2C
#define D7S_OUT_Z_H         0x2D

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0)
        return -1;
    char data[1];
    if (i2cReadDevice(i2c_handle, data, 1) != 1)
        return -1;
    *val = (uint8_t)data[0];
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0)
        return -1;
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

/* ---- Sensor init ---- */
static int init_sensor(void)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg(D7S_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register (I2C bus error or sensor absent).\n");
        return -1;
    }
    if (who_am_i != D7S_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, D7S_WHO_AM_I_VAL);
        return -1;
    }

    /* Clear power-down bit (CTRL1 bit 0 = PD) */
    if (i2c_write_reg(D7S_CTRL1, 0x00) < 0) {
        fprintf(stderr, "Error: cannot write CTRL1 register.\n");
        return -1;
    }
    return 0;
}

/* ---- Read vibration magnitude ---- */
static int read_vibration(float *magnitude)
{
    uint8_t raw[6];
    int16_t x, y, z;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_block(D7S_OUT_X_L, raw, 6) == 0) {
            x = (int16_t)((raw[1] << 8) | raw[0]);
            y = (int16_t)((raw[3] << 8) | raw[2]);
            z = (int16_t)((raw[5] << 8) | raw[4]);
            *magnitude = (float)sqrt((double)x * x + (double)y * y + (double)z * z);
            return 0;
        }
        fprintf(stderr, "Warning: I2C read failed (attempt %d/%d).\n",
                attempt + 1, MAX_RETRIES);
        gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

/* ---- Log event ---- */
static void log_event(float magnitude)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_file, "%s, %.2f\n", ts, magnitude);
    fflush(log_file);
    printf("%s, %.2f\n", ts, magnitude);
}

/* ---- Alert LED ---- */
static void trigger_alert(void)
{
    if (gpioWrite(LED_GPIO, 1) < 0)
        fprintf(stderr, "Warning: failed to turn LED on.\n");
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(LED_GPIO, 0) < 0)
        fprintf(stderr, "Warning: failed to turn LED off.\n");
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() < 0) {
        fprintf(stderr, "Error: sensor initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED GPIO %d.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        float magnitude = 0.0f;
        if (read_vibration(&magnitude) == 0) {
            if (magnitude > VIBRATION_THRESHOLD) {
                log_event(magnitude);
                trigger_alert();
            }
        } else {
            fprintf(stderr, "Error: failed to read vibration after %d retries.\n",
                    MAX_RETRIES);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

