/*
 * flame_monitor.c — KY-026 flame sensor monitor for Raspberry Pi 3 Model B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (root needed for /var/log write)
 *
