 *   BCM GPIO 27 -> physical pin 13
 *
 * Log:    /var/log/flame_events.log  (append-only, flock-ed)
 * Syslog: LOG_USER facility, "flame_monitor"
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_S 1
#define LOG_FILE "/var/log/flame_events.log"
#define DEBOUNCE_NS (DEBOUNCE_MS * 1000L * 1000L)

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void log_event(int sensor_id, int pin, int value)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s) failed: %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX) failed: %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf() failed: %s", strerror(errno));
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush() failed: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_WARNING, "flock(LOCK_UN) failed: %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_WARNING, "fclose() failed: %s", strerror(errno));
    }
}

static int debounce_read(struct gpiod_line *line, int pin)
{
    struct timespec ts = {0, DEBOUNCE_NS};
    int v = gpiod_line_get_value(line);
    if (v < 0) {
        syslog(LOG_ERR, "gpiod_line_get_value(debounce) failed on GPIO %d: %s",
               pin, strerror(errno));
        return -1;
    }
    nanosleep(&ts, NULL);
    int v2 = gpiod_line_get_value(line);
    if (v2 < 0) {
        syslog(LOG_ERR, "gpiod_line_get_value(debounce) failed on GPIO %d: %s",
               pin, strerror(errno));
        return -1;
    }
    return (v == 0 && v2 == 0) ? 1 : 0;
}

int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(\"gpiochip0\") failed: %s",
               strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    int line_acquired[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
        line_acquired[i] = 0;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(GPIO %u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        line_acquired[i] = 1;
    }

    syslog(LOG_INFO, "Flame sensor monitoring started (GPIO %u, %u, %u, %u, %u)",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(GPIO %u) failed: %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            if (v == 0) {
                int confirmed = debounce_read(lines[i], sensor_pins[i]);
                if (confirmed < 0) {
                    continue;
                }
                if (confirmed) {
                    log_event(i + 1, sensor_pins[i], v);
                }
            }
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Flame sensor monitoring stopped");

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (line_acquired[i] && lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return EXIT_SUCCESS;
}

