                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "[FATAL] I2C initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize PWM */
    if (init_pwm() != 0) {
        fprintf(stderr, "[FATAL] PWM initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
