/*
 * Adaptive Grow Light System
 * Board:  Raspberry Pi 4 Model B
 * Sensor: VEML7700 (I2C bus 1, address 0x10)
 * LED:    GPIO18 (BCM) via hardware PWM at 1000 Hz
 *
 * Build:  gcc -O2 -Wall -o grow_light grow_light.c -lpigpio -lrt
 * Run:    sudo ./grow_light
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VEML7700_ADDR        0x10
#define VEML7700_REG_CONF    0x00
#define VEML7700_REG_ALS     0x04
#define VEML7700_CONF_VAL    0x0000  /* ALS active, 400 ms integration, no IT */
#define PWM_GPIO             18
#define PWM_FREQUENCY        1000    /* Hz */
#define PWM_RANGE            100     /* duty 0..100 */
#define SAMPLE_INTERVAL_US   1000000 /* 1 s */
#define LOG_FILE             "grow_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_pwm(void);
static int  read_lux(uint16_t *lux_out);
static int  map_lux_to_brightness(uint16_t lux);
static int  set_led_brightness(int brightness);
static void log_data(uint16_t lux, int brightness, int error_code);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d addr=0x%02X): %s\n",
                I2C_BUS, VEML7700_ADDR, strerror(errno));
        return -1;
    }

    /* Probe the sensor by reading the configuration register */
    int probe = i2cReadWordData(g_i2c_handle, VEML7700_REG_CONF);
    if (probe < 0) {
        fprintf(stderr, "[ERROR] VEML7700 not responding at 0x%02X: %s\n",
                VEML7700_ADDR, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Configure sensor: ALS active, 400 ms integration, no IT */
    if (i2cWriteWordData(g_i2c_handle, VEML7700_REG_CONF, VEML7700_CONF_VAL) < 0) {
        fprintf(stderr, "[ERROR] Failed to write VEML7700 config: %s\n",
                strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- PWM init ---------------------------------- */
static int init_pwm(void)
{
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d) failed\n", PWM_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "[ERROR] gpioSetPWMfrequency(%d) failed\n", PWM_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "[ERROR] gpioSetPWMrange(%d) failed\n", PWM_GPIO);
        return -1;
    }
    if (gpioPWM(PWM_GPIO, 0) < 0) {
        fprintf(stderr, "[ERROR] gpioPWM(%d, 0) failed\n", PWM_GPIO);
        return -1;
    }
    return 0;
}

/* ----------------------------- Lux read ---------------------------------- */
static int read_lux(uint16_t *lux_out)
{
    int raw = i2cReadWordData(g_i2c_handle, VEML7700_REG_ALS);
    if (raw < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(0x%04X) failed: %s\n",
                VEML7700_REG_ALS, strerror(errno));
        return -1;
    }
    *lux_out = (uint16_t)raw;
    return 0;
}

/* ----------------------------- Mapping ----------------------------------- */
static int map_lux_to_brightness(uint16_t lux)
{
    if (lux < 100)   return 100;
    if (lux < 500)   return 75;
    if (lux < 1000)  return 50;
    return 25;
}

/* ----------------------------- LED control ------------------------------- */
static int set_led_brightness(int brightness)
{
    if (brightness < 0)   brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;

    if (gpioPWM(PWM_GPIO, brightness) < 0) {
        fprintf(stderr, "[ERROR] gpioPWM(%d, %d) failed\n", PWM_GPIO, brightness);
        return -1;
    }
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(uint16_t lux, int brightness, int error_code)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s, Lux: %u, Brightness: %d, Error: %d\n",
                ts, lux, brightness, error_code);
        fflush(g_log_file);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Turn LED off first for safety */
    if (g_i2c_handle >= 0) {
        gpioPWM(PWM_GPIO, 0);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "[FATAL] I2C initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize PWM */
    if (init_pwm() != 0) {
