#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    FILE *fp;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open touch_log.txt for appending\n");
        return -1;
    }

    if (fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error: writing to touch_log.txt failed\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: closing touch_log.txt failed\n");
        return -1;
    }

    return 0;
}

int main(void) {
    int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
    int last_state[NUM_CHANNELS];
    int led_state = 0;
    int i;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        last_state[i] = gpioRead(channel_pins[i]);
        if (last_state[i] < 0) {
            fprintf(stderr, "Error: gpioRead failed for pin %d\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED pin %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for LED pin %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int any_touched = 0;

        for (i = 0; i < NUM_CHANNELS; i++) {
            int current = gpioRead(channel_pins[i]);
            if (current < 0) {
                fprintf(stderr, "Error: gpioRead failed for pin %d\n", channel_pins[i]);
                running = 0;
                break;
            }

            if (current == 1 && last_state[i] == 0) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Warning: failed to log touch event for channel %d\n", i + 1);
                }
                any_touched = 1;
            }
            last_state[i] = current;
        }

        if (any_touched && !led_state) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: gpioWrite failed to turn on LED\n");
            } else {
                led_state = 1;
            }
        } else if (!any_touched && led_state) {
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: gpioWrite failed to turn off LED\n");
            } else {
                led_state = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

