#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000
#define ALERT_PULSE_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
            fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
            return -1;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "fflush on log file failed: %s\n", strerror(errno));
            return -1;
        }
        return 0;
    }

    fprintf(stderr, "Log file not open; event not logged: %s\n", message);
    return -1;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", FLAME_SENSOR_PIN, pigpio_error(value));
        return -1;
    }
    return value;
}

static int set_alert_pin(int state) {
    int result = gpioWrite(ALERT_PIN, state);
    if (result < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n", ALERT_PIN, state, pigpio_error(result));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALERT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
