#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x60
#define CMD_MEASURE    0x3602
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define SAMPLE_PERIOD  1
#define FIRST_DELAY_MS 2
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s (got %zd of %zu)\n",
                strerror(errno), n, len);
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SLF3S_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_flow_rate(int fd, float *flow_out, uint16_t *flags_out)
{
    uint8_t buf[3];

    if (i2c_write_cmd(fd, CMD_MEASURE) < 0)
        return -1;

    usleep(FIRST_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 100.0f;
    *flags_out = (uint16_t)raw & 0x0FFF;
    return 0;
}

static void log_data(FILE *fp, float flow, uint16_t flags, const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[24];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%s,%u\n", ts, flow, status, flags);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("cooling_log.csv", "a");
    if (!g_log_fp) {
        perror("fopen cooling_log.csv");
        return EXIT_FAILURE;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "Timestamp,Flow Rate (ml/min),Status,RawFlags\n");
    fflush(g_log_fp);

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) {
        fclose(g_log_fp);
        return EXIT_FAILURE;
    }

    printf("SLF3S flow monitor started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float flow = 0.0f;
        uint16_t flags = 0;
        const char *status = "OK";
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_flow_rate(g_i2c_fd, &flow, &flags) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            usleep(100000);
        }

        if (ok) {
            if (flow < FLOW_MIN || flow > FLOW_MAX)
                status = "INVALID";
            log_data(g_log_fp, flow, flags, status);
            printf("Flow: %.2f ml/min  Status: %s  Raw: %u\n", flow, status, flags);
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; re-initializing I2C.\n",
                    MAX_RETRIES);
            if (g_i2c_fd >= 0) {
                close(g_i2c_fd);
                g_i2c_fd = -1;
            }
            g_i2c_fd = init_i2c();
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Re-init failed; exiting.\n");
                break;
            }
        }

        sleep(SAMPLE_PERIOD);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    if (g_log_fp)
        fclose(g_log_fp);

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

