 * Build:  gcc -Wall -Wextra -O2 -o obstacle_logger obstacle_logger.c -lgpiod
 * Run:    ./obstacle_logger
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define LEFT_SENSOR_PIN   17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22
#define LOG_FILE_NAME     "path_log.csv"
#define SAMPLE_PERIOD_US  50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int write_csv_header(FILE *fp)
{
    if (fprintf(fp, "timestamp,left,middle,right\n") < 0) {
        perror("fprintf(header)");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush(header)");
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, int left, int middle, int right)
{
    time_t rawtime;
    struct tm tm_info;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, left, middle, right) < 0) {
        perror("fprintf(data)");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush(data)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    const unsigned int pins[3] = { LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN };
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM GPIO%u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_input(lines[i], "obstacle_logger") != 0) {
            fprintf(stderr, "gpiod_line_request_input failed for BCM GPIO%u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        goto cleanup;
    }

    if (write_csv_header(fp) != 0)
        goto cleanup;

    while (g_running) {
        int left   = gpiod_line_get_value(lines[0]);
        int middle = gpiod_line_get_value(lines[1]);
        int right  = gpiod_line_get_value(lines[2]);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "gpiod_line_get_value error: %s\n", strerror(errno));
            goto cleanup;
        }

        if (log_data(fp, left, middle, right) != 0)
            goto cleanup;

        usleep(SAMPLE_PERIOD_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0)
            perror("fclose");
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

