/*
 * touch_lamp.c — Raspberry Pi 5 touch-triggered LED lamp
 *
 * Wiring:
 *   TTP223 capacitive touch sensor  OUT -> GPIO23 (BCM 23)
 *   LED                             + -> GPIO24 (BCM 24) via 330 Ω resistor
 *   LED                             - -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_lamp touch_lamp.c -lgpiod
 *
 * Run:
 *   sudo ./touch_lamp
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "/dev/gpiochip4"
#define TOUCH_PIN       23
#define LED_PIN         24
#define LOG_FILE        "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(FILE *log, int led_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log, "%s - Touch detected, LED %s\n",
                timestamp, led_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    FILE *log = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* --- Get touch sensor line --- */
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- Get LED line --- */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- Request touch line as input --- */
    if (gpiod_line_request_input(touch_line, "touch_lamp") != 0) {
        fprintf(stderr, "gpiod_line_request_input(touch) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Request LED line as output, initial value LOW --- */
    if (gpiod_line_request_output(led_line, "touch_lamp", 0) != 0) {
        fprintf(stderr, "gpiod_line_request_output(led) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Touch lamp ready. Touch GPIO%d to toggle LED GPIO%d.\n",
           TOUCH_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    int led_state = 0;

    while (g_running) {
        struct gpiod_line_event event;
        int rv;

        rv = gpiod_line_event_wait(touch_line, &(struct timespec){
            .tv_sec  = POLL_TIMEOUT_MS / 1000,
            .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L
        });

        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        if (rv == 0) {
            /* Timeout — no event, loop back to check g_running */
            continue;
        }

        /* Event detected — read it to clear the event buffer */
        if (gpiod_line_event_read(touch_line, &event) != 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n",
                    strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) != 0) {
            fprintf(stderr, "gpiod_line_set_value failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        log_event(log, led_state);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
