#include <stdlib.h>

#include <gpiod.h>

#define FLAME_SENSOR_PIN  17   /* BCM 17 — KY-026 DO */
#define BUZZER_PIN        18   /* BCM 18 — buzzer control */

#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_S 2
#define POLL_SLICE_MS     100

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, const char *event)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
static int activate_buzzer(struct gpiod_line *buzzer)
{
    if (gpiod_line_set_value(buzzer, 1) < 0) {
        fprintf(stderr, "Failed to set buzzer HIGH: %s\n", strerror(errno));
        return -1;
    }

    /*
     * Break the 2-second buzzer-on duration into 100 ms slices so the
     * program can respond promptly to shutdown signals.
     */
    for (int i = 0; i < BUZZER_DURATION_S * 10 && g_running; i++) {
        usleep(POLL_SLICE_MS * 1000);
    }

    if (gpiod_line_set_value(buzzer, 0) < 0) {
        fprintf(stderr, "Failed to set buzzer LOW: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

