    log_fp = fopen("alert_log.txt", "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Cannot open alert_log.txt: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_event(log_fp, "System started");
    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    /* ---- Open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Get lines ------------------------------------------------ */
    flame  = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (flame == NULL || buzzer == NULL) {
        fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines ------------------------------------------- */
    if (gpiod_line_request_input(flame, "flame_sensor") < 0) {
        fprintf(stderr, "Request flame line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer, "buzzer", 0) < 0) {
        fprintf(stderr, "Request buzzer line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Main polling loop --------------------------------------- */
    int prev_flame = 1;   /* assume no flame at startup (DO is HIGH) */

    while (g_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        /* Detect HIGH -> LOW transition (flame newly detected) */
        if (val == 0 && prev_flame == 1) {
            log_event(log_fp, "FLAME DETECTED");
            if (activate_buzzer(buzzer) < 0) {
                goto cleanup;
            }
        }

        prev_flame = val;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* ---- Graceful shutdown --------------------------------------- */
    log_event(log_fp, "System stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer != NULL) {
        gpiod_line_set_value(buzzer, 0);
        gpiod_line_release(buzzer);
    }
    if (flame != NULL) {
        gpiod_line_release(flame);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    return ret;
}

