/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Sensors: 3x TMAG5110A1 (open-drain latch output)
 *   OUT1 -> GPIO4   (BCM)
 *   OUT2 -> GPIO17  (BCM)
 *   OUT3 -> GPIO27  (BCM)
 *
 * The TMAG5110A1 drives the latch output low when a south pole is
 * present (magnet present) and releases it high when the magnet
 * is removed (magnet removed).  We poll every 100 ms and log every
 * state change to magnet_log.txt with an ISO-8601 timestamp.
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamped message to the log file              */
/* ------------------------------------------------------------------ */
static void log_message(const char *message)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *tstruct = localtime_r(&now, &tm_buf);
    if (tstruct == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s %s\n", ts, message);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "%s %s\n", ts, message);
    }
}

/* ------------------------------------------------------------------ */
/* Configure a GPIO pin as input with internal pull-up, returning     */
/* 0 on success and -1 on failure.                                    */
/* ------------------------------------------------------------------ */
static int configure_sensor_pin(unsigned pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %u as input\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %u\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 (magnet present) or 1 (magnet absent)  */
/* on success, or -1 on read error.                                   */
/* ------------------------------------------------------------------ */
static int read_sensor(unsigned pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %u\n", pin);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins ---- */
    if (configure_sensor_pin(SENSOR1_PIN) != 0 ||
        configure_sensor_pin(SENSOR2_PIN) != 0 ||
        configure_sensor_pin(SENSOR3_PIN) != 0) {
        fprintf(stderr, "Sensor pin configuration failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* ---- Initialise state for each sensor ---- */
    int s1_prev = read_sensor(SENSOR1_PIN);
    int s2_prev = read_sensor(SENSOR2_PIN);
    int s3_prev = read_sensor(SENSOR3_PIN);

    if (s1_prev < 0 || s2_prev < 0 || s3_prev < 0) {
        fprintf(stderr, "Initial sensor read failed; aborting\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            log_message("ERROR: sensor read failure");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (s1 != s1_prev) {
            log_message(s1 ? "Sensor 1: magnet removed" : "Sensor 1: magnet present");
            s1_prev = s1;
        }
        if (s2 != s2_prev) {
            log_message(s2 ? "Sensor 2: magnet removed" : "Sensor 2: magnet present");
            s2_prev = s2;
        }
        if (s3 != s3_prev) {
            log_message(s3 ? "Sensor 3: magnet removed" : "Sensor 3: magnet present");
            s3_prev = s3;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Clean shutdown ---- */
    log_message("Shutting down magnet monitor");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

