#define SI1182_REG_HR_RATE44   0xEC
#define SI1182_REG_HR_THRESH44 0xED
#define SI1182_REG_HR_COUNT44  0xEE
#define SI1182_REG_HR_STATE44  0xEF
#define SI1182_REG_HR_CONFIG44 0xF0
#define SI1182_REG_HR_RATE45   0xF1
#define SI1182_REG_HR_THRESH45 0xF2
#define SI1182_REG_HR_COUNT45  0xF3
#define SI1182_REG_HR_STATE45  0xF4
#define SI1182_REG_HR_CONFIG45 0xF5
#define SI1182_REG_HR_RATE46   0xF6
#define SI1182_REG_HR_THRESH46 0xF7
#define SI1182_REG_HR_COUNT46  0xF8
#define SI1182_REG_HR_STATE46  0xF9
#define SI1182_REG_HR_CONFIG46 0xFA
#define SI1182_REG_HR_RATE47   0xFB
#define SI1182_REG_HR_THRESH47 0xFC
#define SI1182_REG_HR_COUNT47  0xFD
#define SI1182_REG_HR_STATE47  0xFE
#define SI1182_REG_HR_CONFIG47 0xFF

#define SI1182_PART_ID        0x82
#define SI1182_HW_REV         0x01

#define I2C_BUS              "/dev/i2c-1"
#define LOG_FILE             "heart_rate.csv"
#define SAMPLE_PERIOD_SEC    1
#define HR_VALID_MIN         30
#define HR_VALID_MAX         220
#define MOVING_AVG_SIZE      5
#define I2C_RETRY_COUNT      3
#define I2C_RETRY_DELAY_MS   10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ---- Si1182-A-GM initialization ---- */
static int si1182_init(int fd)
{
    uint8_t part_id, hw_rev;

    if (i2c_read_byte(fd, SI1182_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X) — "
                        "wrong sensor or not present\n",
                part_id, SI1182_PART_ID);
        return -1;
    }

    if (i2c_read_byte(fd, SI1182_REG_HW_REV, &hw_rev) < 0)
        return -1;
    if (hw_rev != SI1182_HW_REV) {
        fprintf(stderr, "Unexpected HW_REV 0x%02X (expected 0x%02X)\n",
                hw_rev, SI1182_HW_REV);
        return -1;
    }

    /* Mandatory HW_KEY write (required after reset) */
    if (i2c_write_byte(fd, SI1182_REG_HW_KEY, 0x17) < 0)
        return -1;

    /* Configure measurement rate to 100 ms (0x64 = 100 ms × 1.28 = 128 ms) */
    if (i2c_write_byte(fd, SI1182_REG_MEAS_RATE, 0x64) < 0)
        return -1;

    /* Configure LED current for PS1 (LED1) */
    if (i2c_write_byte(fd, SI1182_REG_PS_LED21, 0x0F) < 0)  /* ~22.4 mA */
        return -1;

    /* Enable HR measurement (bit 0 of HR_CONFIG) */
    if (i2c_write_byte(fd, SI1182_REG_HR_CONFIG, 0x01) < 0)
        return -1;

    return 0;
}

/* ---- Read a 16-bit HR register (little-endian on Si1182) ---- */
static int si1182_read_hr_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_byte(fd, reg, &lo) < 0)
        return -1;
    if (i2c_read_byte(fd, reg + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ---- Read filtered heart-rate (BPM) ---- */
static int si1182_read_hr(int fd, int *hr_bpm)
{
    uint16_t hr_raw;
    int      hr_count;
    int      hr_bpm_sum = 0;
    int      valid_count = 0;

    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        if (si1182_read_hr_reg(fd, SI1182_REG_HR_RATE, &hr_raw) < 0)
            return -1;

        /* hr_raw is in BPM × 10 (e.g. 72 = 7.2 BPM) */
        int hr = (int)hr_raw / 10;

        if (hr >= HR_VALID_MIN && hr <= HR_VALID_MAX) {
            hr_bpm_sum += hr;
            valid_count++;
        }

        /* Wait for next measurement to complete (128 ms × 5 = 640 ms) */
        usleep(128000);
    }

    if (valid_count == 0) {
        fprintf(stderr, "No valid HR readings in moving-average window\n");
        return -1;
    }

    *hr_bpm = hr_bpm_sum / valid_count;
    return 0;
}

/* ---- Append a timestamped reading to the CSV log ---- */
static int log_reading(int hr_bpm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(g_log_fp, "%s,%d\n", ts, hr_bpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

/* ---- Cleanup resources ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    /* Initialize sensor */
    if (si1182_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        cleanup();
        return 1;
    }

    /* Open log file (append mode) */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,bpm\n");
        fflush(g_log_fp);
    }

    printf("Si1182 heart-rate monitor started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int hr_bpm = 0;
        int ok = 0;

        for (int attempt = 0; attempt < I2C_RETRY_COUNT && g_running; attempt++) {
            if (si1182_read_hr(g_i2c_fd, &hr_bpm) == 0) {
                ok = 1;
                break;
            }
            if (attempt < I2C_RETRY_COUNT - 1)
                usleep(I2C_RETRY_DELAY_MS * 1000);
        }

        if (ok) {
            printf("HR: %d BPM\n", hr_bpm);
            if (log_reading(hr_bpm) < 0)
                fprintf(stderr, "Logging failed (continuing)\n");
        } else {
            fprintf(stderr, "Failed to read HR after %d retries\n",
                    I2C_RETRY_COUNT);
        }

        /* Sleep SAMPLE_PERIOD_SEC, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD_SEC && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

