        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int set_output_all(struct gpiod_line_bulk *bulk, int value)
{
    if (gpiod_line_set_value_bulk(bulk, value) < 0) {
        fprintf(stderr, "gpiod_line_set_value_bulk failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk sensor_bulk;
    struct gpiod_line_bulk output_bulk;
    int counter = 0;
    int ret = EXIT_FAILURE;

    install_signal_handlers();

