    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Build bulk containers for the sensor and output lines. */
    gpiod_line_bulk_init(&sensor_bulk);
    gpiod_line_bulk_init(&output_bulk);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *s = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!s) {
            fprintf(stderr, "Failed to get sensor line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&sensor_bulk, s);

        struct gpiod_line *o = gpiod_chip_get_line(chip, output_pins[i]);
        if (!o) {
            fprintf(stderr, "Failed to get output line %u: %s\n",
                    output_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&output_bulk, o);

        /* Request sensor line as input with pull-down (TTP226 OUTs idle low). */
        if (gpiod_line_request_input_flags(s, "ttp226-sensor",
                GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
            fprintf(stderr, "Failed to request sensor line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        /* Request output line as output, initial value 0. */
        if (gpiod_line_request_output(o, "ttp226-output", 0) < 0) {
            fprintf(stderr, "Failed to request output line %u: %s\n",
                    output_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Stabilize sensor lines. */
    usleep(STABILIZE_US);

    printf("TTP226 touch counter running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int prev_counter = counter;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(gpiod_line_bulk_get_line(&sensor_bulk, i));
            if (val < 0) {
                fprintf(stderr, "Sensor read error on channel %d (line %u): %s\n",
                        i + 1, sensor_pins[i], strerror(errno));
                continue;
            }

            /* Rising edge: 0 -> 1 (idle -> touched). */
            if (val == 1) {
                counter = (counter + 1) & 0xFF;

                if (set_output_all(&output_bulk, counter) < 0) {
                    fprintf(stderr, "Output write error on channel %d\n", i + 1);
                }

                if (log_event(i + 1, counter) < 0) {
                    fprintf(stderr, "Logging error on channel %d\n", i + 1);
                }

                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }

        /* If counter changed, log the new value. */
        if (counter != prev_counter && log_event(0, counter) < 0) {
            fprintf(stderr, "Logging error for counter update\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Reset all output pins to 0 on exit. */
    if (gpiod_line_bulk_num_lines(&output_bulk) > 0) {
        (void)set_output_all(&output_bulk, 0);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

