#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define LED_GPIO     22
#define LOG_FILE     "obstacle_log.csv"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR1_GPIO);
        return -1;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR2_GPIO);
        return -1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        return -1;
    }

    /* Start with LED off */
    if (gpioWrite(LED_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n",
                LED_GPIO);
        return -1;
    }

    return 0;
}

static int read_sensor(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n",
                gpio, v);
        return -1;
    }
    return v;
}

static int control_led(int state)
{
    if (gpioWrite(LED_GPIO, state) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on GPIO%d (code %d).\n",
                LED_GPIO, state);
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, int s1, int s2, int led)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        /* Non-fatal: data is in kernel buffer, will flush on close. */
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Best-effort LED off; ignore errors during shutdown. */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = read_sensor(SENSOR1_GPIO);
        int s2 = read_sensor(SENSOR2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: sensor read failure — skipping cycle.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int led_state = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (control_led(led_state) != 0) {
            fprintf(stderr, "Error: LED control failed — continuing.\n");
        }

        if (log_data(g_log_fp, s1, s2, led_state) != 0) {
            fprintf(stderr, "Error: logging failed — continuing.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

