/*
 * Raspberry Pi 4 Model B — TDK InvenSense ICS-40180 analog MEMS microphone
 * sampling and peak-detection with LED alert.
 *
 * Wiring:
 *   ICS-40180 VDD  -> 3.3 V (Pin 1)
 *   ICS-40180 GND  -> GND  (Pin 9)
 *   ICS-40180 OUT  -> GPIO4 (BCM 4, Pin 7)  [analog out, ~0–3 V]
 *   LED anode     -> GPIO17 (BCM 17, Pin 11) via 330 Ω resistor
 *   LED cathode   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mic_peak mic_peak.c -lpigpio -lrt
 *   (or use -lwiringPi if you prefer the pigpio-compatible API)
 *
 * Run:
 *   sudo ./mic_peak
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_GPIO        4
#define LED_GPIO        17
#define SAMPLE_PERIOD_US 125          /* 8 kHz polling rate */
#define LED_ON_US       100000        /* 100 ms LED pulse */
#define POLL_TIMEOUT_US 1000          /* pigpio read returns 0 on timeout */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIC_GPIO);
        return -1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        return -1;
    }

    /* Start with LED off */
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n",
                LED_GPIO);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sampling                                                            */
/* ------------------------------------------------------------------ */
/*
 * Poll the microphone pin at ~8 kHz.  Returns 0 on success and
 * stores the current microsecond tick in *now_us; on timeout returns -1.
 */
static int read_microphone(uint32_t *now_us)
{
    int level = gpioRead(MIC_GPIO);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d (rc=%d).\n",
                MIC_GPIO, level);
        return -1;
    }
    *now_us = gpioTick();
    return 0;
}

/*
 * Detect a rising edge on the microphone pin.
 * Returns 1 if a peak is detected, 0 otherwise, and stores the
 * timestamp in *peak_us.
 */
static int detect_peak(uint32_t *peak_us)
{
    static int prev_level = 0;
    int level;

    if (read_microphone(peak_us) != 0)
        return 0;

    level = gpioRead(MIC_GPIO);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed during peak detection.\n");
        return 0;
    }

    if (level == 1 && prev_level == 0) {
        prev_level = 1;
        return 1;
    }

    prev_level = level;
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED alert                                                          */
/* ------------------------------------------------------------------ */
static void trigger_led_alert(uint32_t peak_us)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    printf("[%ld.%03ld] Peak detected on GPIO%d\n",
           (long)ts.tv_sec, ts.tv_nsec / 1000000L, MIC_GPIO);

    if (gpioWrite(LED_GPIO, 1) != 0) {
        fprintf(stderr, "Warning: failed to turn on LED on GPIO%d.\n",
                LED_GPIO);
        return;
    }

    gpioDelay(LED_ON_US);   /* blocking 100 ms pulse */

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off LED on GPIO%d.\n",
                LED_GPIO);
