#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define LEFT_PIN   2
#define MIDDLE_PIN 3
#define RIGHT_PIN  4
#define POLL_MS    100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/*
 * Read a single GPIO line using the gpioget ioctl.
 * Returns 0 on success (value stored in *out), -1 on error.
 */
static int read_gpio_line(int gpio, int *out)
{
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(/dev/gpiochip0): %s\n", strerror(errno));
        return -1;
    }

    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.lineoffsets[0] = gpio;
    req.flags = 0;
    req.default_values[0] = 0;
    req.config_flags = 0;

    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        fprintf(stderr, "GPIO_GET_LINEHANDLE_IOCTL(gpio=%d): %s\n",
                gpio, strerror(errno));
        close(fd);
        return -1;
    }

    struct gpiohandle_data data;
    memset(&data, 0, sizeof(data));
    if (ioctl(req.fd, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &data) < 0) {
        fprintf(stderr, "GPIOHANDLE_GET_LINE_VALUES_IOCTL(gpio=%d): %s\n",
                gpio, strerror(errno));
        close(req.fd);
        close(fd);
        return -1;
    }

    *out = data.values[0];
    close(req.fd);
    close(fd);
    return 0;
}

int main(void)
{
    if (install_sigint_handler() < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int left, middle, right;

    while (g_running) {
        int l_ok = read_gpio_line(LEFT_PIN, &left);
        int m_ok = read_gpio_line(MIDDLE_PIN, &middle);
        int r_ok = read_gpio_line(RIGHT_PIN, &right);

        if (l_ok < 0 || m_ok < 0 || r_ok < 0) {
            fprintf(stderr, "Error reading sensor values. Exiting.\n");
            return EXIT_FAILURE;
        }

        printf("L:%d M:%d R:%d\n", left, middle, right);
        fflush(stdout);

        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

