/*
 * TTP226 8-channel capacitive touch sensor poller for Raspberry Pi 3 Model B+.
 *
 * Wiring (TTP226 OUT -> Pi BCM pin):
 *   TP1 -> GPIO5  (BCM 5)
 *   TP2 -> GPIO6  (BCM 6)
 *   TP3 -> GPIO13 (BCM 13)
 *   TP4 -> GPIO19 (BCM 19)
 *   TP5 -> GPIO26 (BCM 26)
 *   TP6 -> GPIO12 (BCM 12)
 *   TP7 -> GPIO16 (BCM 16)
 *   TP8 -> GPIO20 (BCM 20)
 *
 * Build: gcc -o touch_poll touch_poll.c -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        printf("[%ld.%03lds] ", ts.tv_sec, ts.tv_nsec / 1000000);
    } else {
        printf("[?] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int line_values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each GPIO line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", touch_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n", touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor polling started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        print_timestamp();

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO line %u: %s\n", touch_pins[i], strerror(errno));
                goto cleanup;
            }
            line_values[i] = val;
        }

        printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               line_values[0], line_values[1], line_values[2], line_values[3],
               line_values[4], line_values[5], line_values[6], line_values[7]);
        fflush(stdout);

        /* Sleep for POLL_INTERVAL_MS, checking program_running every 10 ms */
        for (int ms = 0; ms < POLL_INTERVAL_MS && program_running; ms += 10) {
            usleep(10 * 1000);
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release each line and close the chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

