#include <syslog.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define FADE_STEPS    50
#define FADE_DURATION 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %m");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %m");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", RED_PIN);
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GREEN_PIN);
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", BLUE_PIN);
        return -1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on GPIO %d", RED_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on GPIO %d", GREEN_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on GPIO %d", BLUE_PIN);
        return -1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range on GPIO %d", RED_PIN);
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range on GPIO %d", GREEN_PIN);
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range on GPIO %d", BLUE_PIN);
        return -1;
    }

    return 0;
}

static void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

static void fade_color(int start_red, int start_green, int start_blue,
                       int end_red, int end_green, int end_blue,
                       int duration_seconds)
{
    int red_delta = end_red - start_red;
    int green_delta = end_green - start_green;
    int blue_delta = end_blue - start_blue;

    int red_step = red_delta / FADE_STEPS;
    int green_step = green_delta / FADE_STEPS;
    int blue_step = blue_delta / FADE_STEPS;

    int red_value = start_red;
    int green_value = start_green;
    int blue_value = start_blue;

    for (int i = 0; i < FADE_STEPS && g_running; i++) {
        red_value += red_step;
        green_value += green_step;
        blue_value += blue_step;

        if (red_value < 0) red_value = 0;
        if (red_value > 255) red_value = 255;
        if (green_value < 0) green_value = 0;
        if (green_value > 255) green_value = 255;
        if (blue_value < 0) blue_value = 0;
        if (blue_value > 255) blue_value = 255;

        set_led_color(red_value, green_value, blue_value);
        gpioDelay((duration_seconds * 1000000) / FADE_STEPS);
    }

    set_led_color(end_red, end_green, end_blue);
}

static void generate_random_hue(int *red, int *green, int *blue)
{
    int hue = rand() % 360;
    double rad = hue * 3.14159265358979323846 / 180.0;
    *red = (int)(127.5 + 127.5 * cos(rad));
    *green = (int)(127.5 + 127.5 * sin(rad));
    *blue = 0;
}

int main(void)
{
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    int red, green, blue;
    generate_random_hue(&red, &green, &blue);
    set_led_color(red, green, blue);

    while (g_running) {
        int new_red, new_green, new_blue;
        generate_random_hue(&new_red, &new_green, &new_blue);

        fade_color(red, green, blue, new_red, new_green, new_blue, FADE_DURATION);

        red = new_red;
        green = new_green;
        blue = new_blue;
    }

    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

