/*
 * TCS34725 Color Sensor reader with LED control on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TCS34725 SDA  -> BCM GPIO2  (I2C bus 1 SDA)
 *   TCS34725 SCL  -> BCM GPIO3  (I2C bus 1 SCL)
 *   TCS34725 VDD  -> 3.3 V
 *   TCS34725 GND  -> GND
 *   LED anode     -> BCM GPIO17 (with ~330 ohm series resistor to GND)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tcs34725_led tcs34725_led.c -lgpiod
 *
 * Run:
 *   ./tcs34725_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- TCS34725 register definitions (command bit 0x80) ---- */
#define TCS34725_CMD_BIT        0x80
#define TCS34725_REG_ENABLE     0x00
#define TCS34725_REG_ATIME      0x01
#define TCS34725_REG_ID         0x12
#define TCS34725_REG_CDATA      0x14
#define TCS34725_REG_RDATA      0x16
#define TCS34725_REG_GDATA      0x18
#define TCS34725_REG_BDATA      0x1A

#define TCS34725_ENABLE_PON     0x01
#define TCS34725_ENABLE_AEN     0x02
#define TCS34725_ENABLE_AEN_PON 0x03
#define TCS34725_ID_VALUE       0x44

/* ATIME: 2.4 ms * (256 - 154) = 154.4 ms integration time */
#define TCS34725_ATIME_154MS    154

/* ---- GPIO / I2C ---- */
#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x29
#define GPIO_CHIP      "gpiochip4"   /* BCM GPIO on Pi 4 */
#define LED_OFFSET     17            /* BCM 17 */

/* ---- Calibration ---- */
#define RED_THRESHOLD  200

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_led  = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register. Returns 0 on success, -1 err. */
static int tcs_write_reg(uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_CMD_BIT), val };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register. Returns 0 on success, -1 err. */
static int tcs_read_reg(uint8_t reg, uint8_t *val)
{
    uint8_t cmd = (uint8_t)(reg | TCS34725_CMD_BIT);
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (cmd) for reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int tcs_init(void)
{
    uint8_t id = 0;

    /* Power on (PON) */
    if (tcs_write_reg(TCS34725_REG_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    usleep(3000);  /* 2.4 ms min power-up; 3 ms is safe */

    /* Verify device identity */
    if (tcs_read_reg(TCS34725_REG_ID, &id) < 0)
        return -1;
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x%02X) — wrong sensor?\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Enable RGBC (AEN) */
    if (tcs_write_reg(TCS34725_REG_ENABLE, TCS34725_ENABLE_AEN_PON) < 0)
        return -1;

    /* Integration time ~154 ms */
    if (tcs_write_reg(TCS34725_REG_ATIME, TCS34725_ATIME_154MS) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int tcs_read_rgbc(uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c)
{
    uint8_t r_lo, r_hi, g_lo, g_hi, b_lo, b_hi, c_lo, c_hi;

    if (tcs_read_reg(TCS34725_REG_RDATA, &r_lo) < 0) return -1;
    if (tcs_read_reg(TCS34725_REG_RDATA + 1, &r_hi) < 0) return -1;
    if (tcs_read_reg(TCS34725_REG_GDATA, &g_lo) < 0) return -1;
    if (tcs_read_reg(TCS34725_REG_GDATA + 1, &g_hi) < 0) return -1;
    if (tcs_read_reg(TCS34725_REG_BDATA, &b_lo) < 0) return -1;
    if (tcs_read_reg(TCS34725_REG_BDATA + 1, &b_hi) < 0) return -1;
    if (tcs_read_reg(TCS34725_REG_CDATA, &c_lo) < 0) return -1;
    if (tcs_read_reg(TCS34725_REG_CDATA + 1, &c_hi) < 0) return -1;

    *r = (uint16_t)((r_hi << 8) | r_lo);
    *g = (uint16_t)((g_hi << 8) | g_lo);
    *b = (uint16_t)((b_hi << 8) | b_lo);
    *c = (uint16_t)((c_hi << 8) | c_lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static void control_led(uint16_t red)
{
    int val = (red > RED_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(g_led, val) < 0)
        fprintf(stderr, "Warning: failed to set LED GPIO: %s\n",
                strerror(errno));
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (tcs_init() < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request LED line */
