/*
 * BH1750 Ambient Light Sensor -> WS2812B LED Brightness Mapper
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensor: BH1750FVI on I2C bus 1, address 0x23
 * LED:    WS2812B strip, 10 LEDs, data line on GPIO18 (PCM_CLK, BCM 18)
 *
 * Build:  gcc -O2 -Wall -o light_led light_led.c -lm
 *
 * The BH1750 auto-sleep mode is disabled so the conversion is continuous
 * and the sensor command is issued after a 180 ms wait.  The WS2812B
 * timing is generated via the hardware PWM/waveform output (channel 0
 * on GPIO18) using the Linux kernel's pwm subsystem.  The program
 * exits cleanly on SIGINT/SIGTERM and releases all resources.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/pwm.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_CONT_HIGH_RES 0x10   /* continuous H-Resolution mode */
#define BH1750_CONV_MS 180             /* max conversion time (ms) */

#define LED_GPIO       18               /* BCM 18, hardware PWM channel 0 */
#define NUM_LEDS       10
#define PWM_PERIOD_NS  400              /* 2.5 us per bit (800 kHz) */
#define PWM_DUTY_NS    350              /* > 1.25 us per bit -> 1 logic 1 */

#define MAX_LUX        10000.0f
#define MIN_LUX        0.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* BH1750                                                              */
/* ------------------------------------------------------------------ */

static int bh1750_init(int fd)
{
    /* Power on, one-time H-Resolution mode, ~120 ms conversion */
    if (i2c_write_byte(fd, BH1750_CMD_CONT_HIGH_RES) < 0)
        return -1;
    usleep(120000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* WS2812B PWM                                                          */
/* ------------------------------------------------------------------ */

static int pwm_init(void)
{
    int fd = open("/dev/pwm0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open /dev/pwm0: %s\n", strerror(errno));
        return -1;
    }

    /* Channel 0 on GPIO18 */
    struct pwm_channel_config cfg = {
        .channel = 0,
        .flags   = 0,
        .period  = PWM_PERIOD_NS,
        .duty    = 0,
        .polarity = 0,
    };
    if (ioctl(fd, PWM_SET_CHANNELS, &cfg) < 0) {
        fprintf(stderr, "PWM_SET_CHANNELS failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static void pwm_set_color(int fd, uint8_t r, uint8_t g, uint8_t b)
{
    /* WS2812B expects GRB order */
    uint8_t rgb[3] = { g, r, b };
    for (int i = 0; i < 3; i++) {
        uint8_t byte = rgb[i];
        for (int j = 7; j >= 0; j--) {
            uint8_t bit = (byte >> j) & 1;
            uint32_t duty = bit ? PWM_DUTY_NS : 0;
            struct pwm_channel_config cfg = {
                .channel = 0,
                .duty    = duty,
            };
            ioctl(fd, PWM_SET_CHANNEL_DUTY_CYCLE, &cfg);
            usleep(1);                 /* > 800 ns per bit */
        }
    }
    /* Reset line low for > 50 us before next frame */
    struct pwm_channel_config cfg = {
        .channel = 0,
        .duty    = 0,
    };
    ioctl(fd, PWM_SET_CHANNEL_DUTY_CYCLE, &cfg);
    usleep(60);
}

static void pwm_off(int fd)
{
    struct pwm_channel_config cfg = {
        .channel = 0,
        .duty    = 0,
    };
    ioctl(fd, PWM_SET_CHANNEL_DUTY_CYCLE, &cfg);
    close(fd);
}

/* ------------------------------------------------------------------ */
/* LED brightness mapping                                              */
/* ------------------------------------------------------------------ */

static float map_lux_to_brightness(float lux)
{
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;
    return log10f(lux + 1.0f) / log10f(MAX_LUX + 1.0f);
}

static void set_leds(int fd, float brightness)
{
    uint8_t grb[NUM_LEDS][3];
    for (int i = 0; i < NUM_LEDS; i++) {
        float b = brightness * (float)i / (float)(NUM_LEDS - 1);
        uint8_t g = (uint8_t)(b * 255.0f);
        grb[i][0] = g; grb[i][1] = g; grb[i][2] = g;
    }
    for (int i = 0; i < NUM_LEDS; i++)
        pwm_set_color(fd, grb[i][0], grb[i][1], grb[i][2]);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int pwm_fd = pwm_init();
    if (pwm_fd < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("BH1750 ready. Reading ambient light and mapping to %d LEDs.\n",
           NUM_LEDS);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Read error; retrying in 1 s...\n");
            sleep(1);
            continue;
        }

        float brightness = map_lux_to_brightness(lux);
        set_leds(pwm_fd, brightness);

        printf("Lux: %.2f  Brightness: %.2f\n", lux, brightness);
        usleep(BH1750_CONV_MS * 1000);
    }

    printf("\nShutting down...\n");
    pwm_off(pwm_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

