/*
 * Raspberry Pi Zero W — BH1750 ambient light sensor → APA102 LED strip.
 *
 * Wiring:
 *   BH1750 SDA  → GPIO2  (I2C bus 1)
 *   BH1750 SCL  → GPIO3  (I2C bus 1)
 *   BH1750 VCC  → 3.3 V
 *   BH1750 GND  → GND
 *   APA102 DIN  → GPIO10 (SPI0 MOSI, /dev/spidev0.0)
 *   APA102 VCC  → 5 V
 *   APA102 GND  → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lm
 *
 * Run:
 *   ./light_led [led_count]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_BUS        "/dev/spidev0.0"
#define BH1750_ADDR    0x23
#define BH1750_PWR_ON  0x01
#define BH1750_RESET   0x07
#define BH1750_CONT_HI 0x10
#define BH1750_CONV_MS 120

#define APA102_ZERO    0xE0
#define APA102_END     0x00
#define APA102_WS2812B 0x00

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read16 failed (got %zd bytes): %s\n", n, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd)
{
    if (i2c_write(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write(fd, BH1750_RESET)  < 0) return -1;
    return 0;
}

static int bh1750_read(int fd, uint16_t *lux)
{
    if (i2c_write(fd, BH1750_CONT_HI) < 0) return -1;
    usleep(BH1750_CONV_MS * 1000);
    return i2c_read16(fd, lux);
}

