#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_ADDR_3 0x45
#define BH1750_CONV_TIME_MS 180
#define SPI_SPEED_HZ 1000000
#define SPI_BITS 8
#define SPI_DELAY_US 0
#define APA102_NUM_LEDS 60
#define FADE_DURATION_MS 500
#define LOOP_DELAY_MS 100
#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS];
static int spi_fd = -1;
static int i2c_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_open(int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, float *lux) {
    uint8_t cmd = 0x10; /* Continuous High-Resolution Mode */
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing to BH1750 (addr 0x%02X): %s\n", fd, strerror(errno));
        return -1;
    }
    gpioDelay(BH1750_CONV_TIME_MS * 1000);
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750 (addr 0x%02X): %s\n", fd, strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int spi_open(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int apa102_write(const uint8_t *data, int len) {
    if (spi_fd < 0) return -1;
    int ret = write(spi_fd, data, len);
    if (ret < 0) {
        fprintf(stderr, "Error writing to APA102 SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int apa102_fade(uint8_t r, uint8_t g, uint8_t b, int duration_ms) {
    uint8_t start[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end[4] = {0xE0, r, g, b};
    int steps = duration_ms / 10;
    if (steps <= 0) steps = 1;
    for (int i = 0; i <= steps && running; i++) {
        float frac = (float)i / steps;
        uint8_t frame[4 * APA102_NUM_LEDS + 8];
        frame[0] = 0x00;
        frame[1] = 0x00;
        frame[2] = 0x00;
        frame[3] = 0x00;
        for (int j = 0; j < APA102_NUM_LEDS; j++) {
            int idx = 4 + j * 4;
            frame[idx] = 0xE0;
            frame[idx + 1] = (uint8_t)(start[1] + (end[1] - start[1]) * frac);
            frame[idx + 2] = (uint8_t)(start[2] + (end[2] - start[2]) * frac);
            frame[idx + 3] = (uint8_t)(start[3] + (end[3] - start[3]) * frac);
        }
        frame[4 + APA102_NUM_LEDS * 4] = 0xFF;
        frame[5 + APA102_NUM_LEDS * 4] = 0xFF;
        frame[6 + APA102_NUM_LEDS * 4] = 0xFF;
        frame[7 + APA102_NUM_LEDS * 4] = 0xFF;
        apa102_write(frame, sizeof(frame));
        gpioDelay(10000);
    }
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        uint8_t off[4] = {0x00, 0x00, 0x00, 0x00};
        apa102_write(off, 4);
        close(spi_fd);
        spi_fd = -1;
    }
    for (int i = 0; i < i2c_count; i++) {
        if (i2c_handles[i] >= 0) {
            close(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = -1;
    }
    int addrs[NUM_SENSORS] = {BH1750_ADDR_1, BH1750_ADDR_2, BH1750_ADDR_3};
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2c_open(addrs[i]);
        if (i2c_handles[i] >= 0) {
            i2c_count++;
        }
    }
    if (i2c_count == 0) {
        fprintf(stderr, "No BH1750 sensors found on I2C bus\n");
        cleanup();
        return 1;
    }
    spi_fd = spi_open();
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        float sum = 0.0f;
        int valid = 0;
        for (int i = 0; i < i2c_count; i++) {
            float lux;
            if (bh1750_read(i2c_handles[i], &lux) == 0) {
                sum += lux;
                valid++;
            }
        }
        float avg = (valid > 0) ? (sum / valid) : 0.0f;
        uint8_t target = (uint8_t)(avg / 100.0f * 255.0f);
        if (target > 255) target = 255;
        apa102_fade(target, target, target, FADE_DURATION_MS);
        gpioDelay(LOOP_DELAY_MS * 1000);
    }
    cleanup();
    return 0;
}

