#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define VEML7700_ADDR  0x10
#define VEML7700_CONF  0x00
#define VEML7700_ALS   0x04
#define VEML7700_ALS_CONF 0x01
#define VEML7700_ALS_TH  0x02
#define VEML7700_ALS_LSB 0x03

#define LED_PIN        18
#define NUM_LEDS       1
#define RETRY_COUNT    3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS  200

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (write(fd, buf, 2) == 2) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, i + 1, RETRY_COUNT, strerror(errno));
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg select) failed (attempt %d/%d): %s\n",
                    i + 1, RETRY_COUNT, strerror(errno));
            sleep_ms(RETRY_DELAY_MS);
            continue;
        }
        if (read(fd, buf, 2) == 2) {
            *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
            return 0;
        }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, i + 1, RETRY_COUNT, strerror(errno));
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1;
}

static int veml7700_init(int fd) {
    if (i2c_write_reg8(fd, VEML7700_CONF, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, VEML7700_ALS_CONF, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, VEML7700_ALS_TH, 0x00) < 0) return -1;
    return 0;
}

