        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg select) failed (attempt %d/%d): %s\n",
                    i + 1, RETRY_COUNT, strerror(errno));
            sleep_ms(RETRY_DELAY_MS);
