#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define BLINK_ON_MS 500
#define BLINK_OFF_MS 500
#define BLINK_ERROR_MS 100
#define BLINK_ERROR_COUNT 5
#define POLL_INTERVAL_MS 50
#define SELF_TEST_SAMPLES 5
#define SELF_TEST_SAMPLE_INTERVAL_MS 100
#define BUZZER_PATTERN_MS_1 200
#define BUZZER_PATTERN_MS_2 200
#define BUZZER_PATTERN_MS_3 600
#define BUZZER_PATTERN_REPEATS 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, event);
    fflush(stdout);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set flame sensor pin %d as input\n", FLAME_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n", BUZZER_PIN);
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED pin %d as output\n", LED_PIN);
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0 || gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO outputs to LOW\n");
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

static int read_flame_sensor(void) {
    int v = gpioRead(FLAME_SENSOR_PIN);
    if (v < 0) {
        fprintf(stderr, "Error: failed to read flame sensor on pin %d\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return v;
}

static void blink_led(int on_ms, int off_ms, int count) {
    for (int i = 0; i < count && running; i++) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Warning: failed to turn LED on\n");
        }
        gpioDelay(on_ms * 1000);
        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Warning: failed to turn LED off\n");
        }
        gpioDelay(off_ms * 1000);
    }
}

static void self_test(void) {
    log_event("Starting self-test...");
    int error = 0;
    for (int i = 0; i < SELF_TEST_SAMPLES && running; i++) {
        int v = read_flame_sensor();
        if (v < 0) {
            error = 1;
            break;
        }
        if (v == 0) {
            log_event("Flame detected during self-test");
        }
        gpioDelay(SELF_TEST_SAMPLE_INTERVAL_MS * 1000);
    }
    if (error) {
        log_event("Self-test failed: GPIO read error");
    } else if (read_flame_sensor() == 0) {
        log_event("Self-test failed: flame detected on all samples");
        error = 1;
    } else {
        log_event("Self-test passed");
    }
    if (error) {
        blink_led(BLINK_ERROR_MS, BLINK_ERROR_MS, BLINK_ERROR_COUNT);
        if (running) {
            log_event("Self-test error: signaling buzzer");
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(1000);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(1000);
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(1000);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(1000);
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(1000);
            gpioWrite(BUZZER_PIN, 0);
        }
    }
}

static void trigger_alarm(void) {
    log_event("Flame detected: activating alarm");
    gpioWrite(BUZZER_PIN, 1);
    gpioWrite(LED_PIN, 1);
    while (running) {
        int v = read_flame_sensor();
        if (v == 1) {
            log_event("Flame cleared");
            break;
        }
        if (v < 0) {
            log_event("Error: flame detection failed during alarm");
            break;
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }
    if (init_gpio() != 0) {
        return 1;
    }
    self_test();
    if (!running) {
        cleanup_gpio();
        return 0;
    }
    log_event("Entering main loop");
    while (running) {
        int v = read_flame_sensor();
        if (v < 0) {
            log_event("Error: GPIO read failed in main loop");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }
        if (v == 0) {
            trigger_alarm();
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }
    log_event("Shutting down");
    cleanup_gpio();
    return 0;
}

