#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BH1750_ADDR             0x23
#define BH1750_CONT_HIGH_RES    0x10
#define BH1750_CONT_LOW_RES     0x13
#define BH1750_POWER_DOWN       0x00
#define I2C_BUS                 "/dev/i2c-1"
#define GPIO_CHIP               "gpiochip4"
#define LED_PIN                 17
#define BUFFER_SIZE             60
#define MIN_LUX                 0.0f
#define MAX_LUX                 1000.0f
#define MIN_FREQUENCY           0.5f
#define MAX_FREQUENCY           5.0f
#define SAMPLE_INTERVAL_SEC     1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd)
{
    if (i2c_write_byte(fd, BH1750_POWER_DOWN) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES) < 0) return -1;
    usleep(180000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void set_led_frequency(struct gpiod_line *line, float lux)
{
    float freq = MIN_FREQUENCY +
                 (lux - MIN_LUX) * (MAX_FREQUENCY - MIN_FREQUENCY) /
                 (MAX_LUX - MIN_LUX);
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;

    float period_us = 1000000.0f / freq;
    float half_period = period_us / 2.0f;

    struct timespec ts = {0, (long)(half_period * 1000.0f)};
    while (g_running) {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "LED on failed: %s\n", strerror(errno));
            break;
        }
        nanosleep(&ts, NULL);
        if (!g_running) break;
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "LED off failed: %s\n", strerror(errno));
            break;
        }
        nanosleep(&ts, NULL);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "bh1750_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (g_running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        } else {
            lux_buffer[buffer_index] = lux;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) buffer_count++;

            float sum = 0.0f;
            for (int i = 0; i < buffer_count; i++) sum += lux_buffer[i];
            float avg = sum / (float)buffer_count;
            printf("Lux: %.2f, Average: %.2f\n", lux, avg);
            fflush(stdout);

            set_led_frequency(led_line, avg);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    fprintf(stderr, "\nShutting down...\n");
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

