#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

/* BCM pin numbers for 74HC595 bit-bang interface */
#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

/* Segment bit patterns for common-cathode display (1 = ON) */
#define SEG_A 0x01
#define SEG_B 0x02
#define SEG_C 0x04
#define SEG_D 0x08
#define SEG_E 0x10
#define SEG_F 0x20
#define SEG_G 0x40
#define SEG_DP 0x80  /* unused here */

/* Digit 5 pattern: segments a,b,c,d,e,f (g off) */
#define DIGIT_5 (SEG_A | SEG_B | SEG_C | SEG_D | SEG_E | SEG_F)

/* 74HC595 bit-bang shift-out: MSB first, latch on rising edge */
static void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        if (gpioWrite(DATA_PIN, (data >> i) & 0x01) < 0) {
            fprintf(stderr, "Error: failed to write data pin\n");
            return;
        }
        if (gpioWrite(CLOCK_PIN, 1) < 0) {
            fprintf(stderr, "Error: failed to set clock high\n");
            return;
        }
        gpioDelay(1);  /* 1 µs clock high */
        if (gpioWrite(CLOCK_PIN, 0) < 0) {
            fprintf(stderr, "Error: failed to set clock low\n");
            return;
        }
        gpioDelay(1);  /* 1 µs clock low */
    }
    if (gpioWrite(LATCH_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set latch high\n");
        return;
    }
    gpioDelay(1);  /* 1 µs latch high */
    if (gpioWrite(LATCH_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set latch low\n");
        return;
    }
    gpioDelay(1);  /* 1 µs latch low */
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins as outputs */
    if (gpioSetMode(DATA_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set DATA_PIN %d as output\n", DATA_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set CLOCK_PIN %d as output\n", CLOCK_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LATCH_PIN %d as output\n", LATCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure all lines start LOW */
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    /* Blink digit 5 on the display */
    while (1) {
        shift_out(DIGIT_5);
        gpioDelay(500000);  /* 500 ms on */
        shift_out(0x00);    /* blank */
        gpioDelay(500000);  /* 500 ms off */
    }

    /* Unreachable in normal operation, but kept for completeness */
    gpioTerminate();
    return EXIT_SUCCESS;
}

