#include <unistd.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define LED_LINE        17          /* BCM 17, physical pin 11 */
#define BUTTON_LINE     18          /* BCM 18, physical pin 12 */
#define BLINK_PERIOD_S  2           /* 2 s on + 2 s off */
#define POLL_TIMEOUT_S  1           /* 1 s per poll() */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led  = NULL;
    struct gpiod_line *btn  = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean Ctrl-C exit --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* --- Get the LED line (BCM 17) --- */
    led = gpiod_chip_get_line(chip, LED_LINE);
    if (!led) {
        perror("gpiod_chip_get_line(LED)");
        goto cleanup;
    }

    /* Request LED as output, initial value LOW */
    if (gpiod_line_request_output(led, "blink_button", 0) < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* --- Get the button line (BCM 18) --- */
    btn = gpiod_chip_get_line(chip, BUTTON_LINE);
    if (!btn) {
        perror("gpiod_chip_get_line(BUTTON)");
        goto cleanup;
    }

    /* Request button as input with pull-up, falling-edge events */
    if (gpiod_line_request_input_flags(btn, "blink_button",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP |
            GPIOD_LINE_REQUEST_FLAG_EVENT_FALLING_EDGE) < 0) {
        perror("gpiod_line_request_input_flags(BUTTON)");
        goto cleanup;
    }

    printf("Blinking LED on GPIO%d (2 s period) and waiting for "
           "falling-edge button on GPIO%d.\n", LED_LINE, BUTTON_LINE);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* --- Main blink loop --- */
    while (g_running) {
        /* Turn LED on */
        if (gpiod_line_set_value(led, 1) < 0) {
            perror("gpiod_line_set_value(LED on)");
            goto cleanup;
        }

        /* Sleep for the first half of the period */
        for (int i = 0; i < POLL_TIMEOUT_S && g_running; i++)
            sleep(1);

        if (!g_running)
            break;

        /* Turn LED off */
        if (gpiod_line_set_value(led, 0) < 0) {
            perror("gpiod_line_set_value(LED off)");
            goto cleanup;
        }

        /* Sleep for the second half of the period */
        for (int i = 0; i < POLL_TIMEOUT_S && g_running; i++)
            sleep(1);
    }

    /* --- Graceful exit: ensure LED is off, release lines --- */
    if (led)
        gpiod_line_set_value(led, 0);
    ret = EXIT_SUCCESS;

cleanup:
    if (led)
        gpiod_line_release(led);
    if (btn)
        gpiod_line_release(btn);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

