#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN    24
#define BUTTON_PIN 22
#define BLINK_MS   500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    int led_line = gpioGetMode(LED_PIN);
    if (led_line < 0) {
        fprintf(stderr, "Failed to get LED line mode: %s\n", pigpio_error(led_line));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (led_line != PI_OUTPUT) {
        int rc = gpioSetMode(LED_PIN, PI_OUTPUT);
        if (rc < 0) {
            fprintf(stderr, "Failed to set LED line mode: %s\n", pigpio_error(rc));
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int btn_line = gpioGetMode(BUTTON_PIN);
    if (btn_line < 0) {
        fprintf(stderr, "Failed to get button line mode: %s\n", pigpio_error(btn_line));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (btn_line != PI_INPUT) {
        int rc = gpioSetMode(BUTTON_PIN, PI_INPUT);
        if (rc < 0) {
            fprintf(stderr, "Failed to set button line mode: %s\n", pigpio_error(rc));
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int rc = gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN);
    if (rc < 0) {
        fprintf(stderr, "Failed to set pull-down on button line: %s\n", pigpio_error(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise LED state.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Press the button (GPIO%d) to blink the LED (GPIO%d).\n", BUTTON_PIN, LED_PIN);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        if (gpioRead(BUTTON_PIN) == 1) {
            if (gpioWrite(LED_PIN, 1) < 0) {
                fprintf(stderr, "Failed to turn LED on.\n");
                break;
            }
            gpioDelay(BLINK_MS * 1000);
            if (!g_running) break;
            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "Failed to turn LED off.\n");
                break;
            }
            gpioDelay(BLINK_MS * 1000);
        } else {
            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "Failed to turn LED off.\n");
                break;
            }
            gpioDelay(10000);
        }
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

