#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_NS 10000000ULL  /* 10 ms -> 100 Hz */
#define STEP_NS       1000000ULL   /* 1 ms per step  */
#define STEP_COUNT    (PWM_PERIOD_NS / STEP_NS)

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ns(unsigned long long ns) {
    struct timespec req = {
        .tv_sec  = (time_t)(ns / 1000000000ULL),
        .tv_nsec = (long)(ns % 1000000000ULL)
    };
    while (nanosleep(&req, &req) == -1) {
        /* Retry on EINTR */
    }
}

static void sleep_ms(unsigned long ms) {
    sleep_ns((unsigned long long)ms * 1000000ULL);
}

static int set_line_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int pwm_channel(struct gpiod_line *line, int intensity) {
    if (intensity < 0) intensity = 0;
    if (intensity > 100) intensity = 100;

    unsigned long long on_ns  = (unsigned long long)intensity * PWM_PERIOD_NS / 100ULL;
    unsigned long long off_ns = PWM_PERIOD_NS - on_ns;

    if (set_line_value(line, 1) < 0) return -1;
    sleep_ns(on_ns);
    if (set_line_value(line, 0) < 0) return -1;
    sleep_ns(off_ns);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red   = NULL;
    struct gpiod_line *green = NULL;
    struct gpiod_line *blue  = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    red   = gpiod_chip_get_line(chip, RED_PIN);
    green = gpiod_chip_get_line(chip, GREEN_PIN);
    blue  = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red || !green || !blue) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red,   "rgb-pwm", 0) < 0 ||
        gpiod_line_request_output(green, "rgb-pwm", 0) < 0 ||
        gpiod_line_request_output(blue,  "rgb-pwm", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int r = rand() % 101;
        int g = rand() % 101;
        int b = rand() % 101;

        if (pwm_channel(red,   r) < 0) goto cleanup;
        if (pwm_channel(green, g) < 0) goto cleanup;
        if (pwm_channel(blue,  b) < 0) goto cleanup;

        sleep_ms(100);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red)   gpiod_line_release(red);
    if (green) gpiod_line_release(green);
    if (blue)  gpiod_line_release(blue);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

