/*
 * LSM303DLHC Impact Detector for Raspberry Pi Zero W
 *
 * Polls the accelerometer on I2C bus 1 at 10 Hz, computes the total G-force
 * magnitude, and pulses GPIO17 (BCM) HIGH for 50 ms when the magnitude
 * exceeds a configurable threshold.
 *
 * Build:  gcc -O2 -Wall -o impact_detector impact_detector.c -lm
 * Run:    ./impact_detector [-t threshold_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_ACCEL_OUT_X_H_A   0x29
#define LSM303_ACCEL_OUT_Y_L_A   0x2A
#define LSM303_ACCEL_OUT_Y_H_A   0x2B
#define LSM303_ACCEL_OUT_Z_L_A   0x2C
#define LSM303_ACCEL_OUT_Z_H_A   0x2D

/* ---- GPIO ---- */
#define INTERRUPT_PIN 17

/* ---- Defaults ---- */
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_RATE_HZ    10
#define SAMPLE_PERIOD_US  (1000000 / SAMPLE_RATE_HZ)
#define LOG_FILE          "impact_log.txt"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_accel = -1;
static int  g_i2c_mag   = -1;
static int  g_gpio_init = 0;
static float g_threshold = DEFAULT_THRESHOLD;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_accel >= 0) {
        close(g_i2c_accel);
        g_i2c_accel = -1;
    }
    if (g_i2c_mag >= 0) {
        close(g_i2c_mag);
        g_i2c_mag = -1;
    }
    if (g_gpio_init) {
        gpioWrite(INTERRUPT_PIN, 0);
        gpioTerminate();
        g_gpio_init = 0;
    }
}

/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_accelerometer(void)
{
    g_i2c_accel = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_accel < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_accel, I2C_SLAVE, LSM303_ACCEL_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303_ACCEL_ADDR, strerror(errno));
        return -1;
    }

    /* Enable X/Y/Z axes, 10 Hz ODR, normal mode */
    if (i2c_write_byte(g_i2c_accel, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int init_magnetometer(void)
{
    g_i2c_mag = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_mag < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_mag, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        return -1;
    }

    /* Continuous conversion mode, 10 Hz ODR */
    if (i2c_write_byte(g_i2c_mag, 0x00, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accelerometer(float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(g_i2c_accel, LSM303_ACCEL_OUT_X_L_A | 0x80, raw, 6) < 0)
        return -1;

    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);

    /* Sensitivity: 1 mg/LSB at +/-2g, 0.061 mg/LSB at +/-4g, 0.122 mg/LSB at +/-8g */
    const float sens = 0.061f;  /* +/-4g range */
    *x = (float)rx * sens / 1000.0f;
    *y = (float)ry * sens / 1000.0f;
    *z = (float)rz * sens / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
static void trigger_interrupt(void)
{
    gpioWrite(INTERRUPT_PIN, 1);
    gpioDelay(50000);          /* 50 ms pulse */
    gpioWrite(INTERRUPT_PIN, 0);
}

/* ------------------------------------------------------------------ */
static void log_data(float x, float y, float z, float mag)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f, Y: %.3f, Z: %.3f, Mag: %.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z, mag);
    } else {
        fprintf(fp, "(time error), X: %.3f, Y: %.3f, Z: %.3f, Mag: %.3f\n",
                x, y, z, mag);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            g_threshold = (float)atof(optarg);
            if (g_threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be positive.\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

