    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_gpio_init = 1;

    if (gpioSetMode(INTERRUPT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", INTERRUPT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(INTERRUPT_PIN, 0);

    /* Initialize sensors */
    if (init_accelerometer() < 0) {
        fprintf(stderr, "Accelerometer initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (init_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

