static int read_als(uint16_t *als) {
    uint8_t lsb, msb;
    if (read_reg(REG_ALS_LSB, &lsb) < 0) return -1;
    if (read_reg(REG_ALS_MSB, &msb) < 0) return -1;
    *als = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int read_color(uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t rl, rh, gl, gh, bl, bh;
    if (read_reg(REG_RED_LSB, &rl) < 0) return -1;
    if (read_reg(REG_RED_MSB, &rh) < 0) return -1;
    if (read_reg(REG_GREEN_LSB, &gl) < 0) return -1;
    if (read_reg(REG_GREEN_MSB, &gh) < 0) return -1;
    if (read_reg(REG_BLUE_LSB, &bl) < 0) return -1;
    if (read_reg(REG_BLUE_MSB, &bh) < 0) return -1;
    *r = (uint16_t)((rh << 8) | rl);
    *g = (uint16_t)((gh << 8) | gl);
    *b = (uint16_t)((bh << 8) | bl);
    return 0;
}

static void set_led_brightness(uint16_t als) {
    int pwm = (int)(als / 4);
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    if (pwm < 0) pwm = 0;
    gpioPWM(LED_GPIO, pwm);
}

static void log_data(uint16_t als, uint16_t r, uint16_t g, uint16_t b) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s,%u,%u,%u,%u\n", ts, als, r, g, b);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", ADPD188BI_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_reg(REG_MODE, MODE_POWER_ON) < 0) {
        fprintf(stderr, "Failed to power on sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);

    if (write_reg(REG_MODE, MODE_ALS) < 0) {
        fprintf(stderr, "Failed to set ALS mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioPWM(LED_GPIO, 0);

    log_file = fopen("color_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open color_log.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "timestamp,als,red,green,blue\n");
    fflush(log_file);

    while (running) {
        uint16_t als, r, g, b;
        if (read_als(&als) == 0 && read_color(&r, &g, &b) == 0) {
            set_led_brightness(als);
            log_data(als, r, g, b);
        } else {
            fprintf(stderr, "Sensor read error, retrying in 100ms\n");
            gpioPWM(LED_GPIO, 0);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Shutting down...\n");
    gpioPWM(LED_GPIO, 0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

