/*
 * FXOS8700CQ Impact Logger for Raspberry Pi Zero W
 *
 * Reads acceleration (±2 g) from the Adafruit FXOS8700CQ over I2C bus 1
 * at 200 Hz, logs impacts (magnitude > THRESHOLD) to impact_log.txt.
 *
 * Build:  gcc -O2 -Wall -o impact_logger impact_logger.c -li2c -lm
 * Run:    sudo ./impact_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- FXOS8700CQ constants (verified against Adafruit breakout) ---- */
#define FXOS8700_I2C_ADDR        0x1F
#define FXOS8700_WHO_AM_I        0x0D
#define FXOS8700_WHO_AM_I_VAL    0xC7
#define FXOS8700_CTRL_REG1       0x2A
#define FXOS8700_M_CTRL_REG1     0x5B
#define FXOS8700_M_CTRL_REG2     0x5C
#define FXOS8700_XYZ_DATA_CFG    0x0E
#define FXOS8700_OUT_X_MSB       0x01

#define I2C_BUS                 "/dev/i2c-1"
#define IMPACT_THRESHOLD        1.0f
#define LOG_FILE                "impact_log.txt"
#define SAMPLE_PERIOD_US        50000   /* 50 ms -> 200 Hz */

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes starting at OUT_X_MSB (acceleration) into big-endian int16. */
static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t reg = FXOS8700_OUT_X_MSB;
    uint8_t buf[6];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "read_acceleration: write reg select failed: %s\n",
                strerror(errno));
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "read_acceleration: read 6 bytes failed: %s\n",
                strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_impact(int16_t x, int16_t y, int16_t z, float magnitude)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_impact: fopen(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_impact: localtime_r failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d,%d,%.3f\n", ts, x, y, z, magnitude);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static int init_fxos8700(int fd)
{
    uint8_t whoami = 0;

    if (i2c_read_reg8(fd, FXOS8700_WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "init_fxos8700: cannot read WHO_AM_I\n");
        return -1;
    }
    if (whoami != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "init_fxos8700: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                whoami, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby first so configuration changes take effect immediately. */
    if (i2c_write_reg8(fd, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Magnetic sensor standby (M_CTRL_REG1 bit 0 = 0). */
    if (i2c_write_reg8(fd, FXOS8700_M_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Magnetic sensor mode (M_CTRL_REG2 bit 0 = 0 -> hybrid). */
    if (i2c_write_reg8(fd, FXOS8700_M_CTRL_REG2, 0x00) != 0)
        return -1;

    /* ±2 g range (XYZ_DATA_CFG = 0x00). */
    if (i2c_write_reg8(fd, FXOS8700_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Active mode, 200 Hz ODR (CTRL_REG1 = 0x01). */
    if (i2c_write_reg8(fd, FXOS8700_CTRL_REG1, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, FXOS8700_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                FXOS8700_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (init_fxos8700(g_i2c_fd) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Logging impacts (|a| > %.2f g) to %s\n",
           IMPACT_THRESHOLD, LOG_FILE);

    while (g_running) {
        int16_t x, y, z;

        if (read_acceleration(g_i2c_fd, &x, &y, &z) != 0) {
            /* I2C error: back off briefly and retry rather than crash. */
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float magnitude = sqrtf((float)x * x + (float)y * y + (float)z * z);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(x, y, z, magnitude);
            printf("Impact: x=%d y=%d z=%d |a|=%.3f g\n", x, y, z, magnitude);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        /* Put sensor back in standby before closing. */
        (void)i2c_write_reg8(g_i2c_fd, FXOS8700_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

