/*
 * GY-50 L3G4200D Gyroscope Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   L3G4200D SDA  -> GPIO2  (I2C bus 1 SDA)
 *   L3G4200D SCL  -> GPIO3  (I2C bus 1 SCL)
 *   L3G4200D VCC  -> 3.3 V
 *   L3G4200D GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_logger gyro_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D register definitions (verified against datasheet) ---- */
#define L3G4200D_WHO_AM_I   0x0F
#define L3G4200D_WHO_AM_I_VAL 0xD3
#define L3G4200D_CTRL_REG1  0x20
#define L3G4200D_CTRL_REG4  0x23
#define L3G4200D_OUT_X_L    0x28
#define L3G4200D_OUT_X_H    0x29
#define L3G4200D_OUT_Y_L    0x2A
#define L3G4200D_OUT_Y_H    0x2B
#define L3G4200D_OUT_Z_L    0x2C
#define L3G4200D_OUT_Z_H    0x2D

/* ---- Calibration parameters ---- */
#define CALIBRATION_SAMPLES 100
#define CALIBRATION_PERIOD_MS 50
#define ALERT_THRESHOLD_DPS 50.0f
#define SAMPLE_PERIOD_MS 50
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "gyro_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Calibration offsets (dps) ---- */
static float g_x_offset = 0.0f;
static float g_y_offset = 0.0f;
static float g_z_offset = 0.0f;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, val, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, buf, len);
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read block from 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Gyroscope data structure ---- */
typedef struct {
    float x, y, z;
} gyro_data_t;

/* ---- Read one sample ---- */
static int read_gyro_sample(int fd, gyro_data_t *out)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, L3G4200D_OUT_X_L, raw, sizeof(raw)) != 0)
        return -1;

    int16_t x = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z = (int16_t)((raw[5] << 8) | raw[4]);

    out->x = (float)x / 32.0f;   /* 1 deg/sec / 32 counts */
    out->y = (float)y / 32.0f;
    out->z = (float)z / 32.0f;
    return 0;
}

/* ---- Calibrate: compute zero-rate offsets ---- */
static int calibrate_gyro(int fd)
{
    gyro_data_t sum = { 0.0f, 0.0f, 0.0f };
    int valid = 0;

    printf("Calibrating gyroscope (%d samples)...\n", CALIBRATION_SAMPLES);
    fflush(stdout);

    for (int i = 0; i < CALIBRATION_SAMPLES && g_running; i++) {
        gyro_data_t d;
        if (read_gyro_sample(fd, &d) != 0) {
            fprintf(stderr, "Calibration read error at sample %d\n", i);
            return -1;
        }
        sum.x += d.x;
        sum.y += d.y;
        sum.z += d.z;
        valid++;
        usleep(CALIBRATION_PERIOD_MS * 1000);
    }

    if (!g_running) {
        fprintf(stderr, "Calibration interrupted by signal\n");
        return -1;
    }

    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid samples\n");
        return -1;
    }

    g_x_offset = sum.x / valid;
    g_y_offset = sum.y / valid;
    g_z_offset = sum.z / valid;

    printf("Calibration complete. Offsets: X=%.2f Y=%.2f Z=%.2f dps\n",
           g_x_offset, g_y_offset, g_z_offset);
    return 0;
}

/* ---- Log one sample with timestamp ---- */
static void log_gyro_data(FILE *fp, const gyro_data_t *d)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, d->x, d->y, d->z);
    fflush(fp);
}

/* ---- Log alert line ---- */
static void log_alert(FILE *fp, const gyro_data_t *d)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,ALERT,%.2f,%.2f,%.2f\n", ts, d->x, d->y, d->z);
    fflush(fp);
    fprintf(stderr, "ALERT: X=%.2f Y=%.2f Z=%.2f dps\n", d->x, d->y, d->z);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor identity ---- */
    uint8_t who;
    if (i2c_read_reg8(g_i2c_fd, L3G4200D_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (who != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, L3G4200D_WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("L3G4200D detected (WHO_AM_I=0x%02X)\n", who);

    /* ---- Configure: 200 Hz ODR, all axes enabled ---- */
    if (i2c_write_reg8(g_i2c_fd, L3G4200D_CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Calibration ---- */
    if (calibrate_gyro(g_i2c_fd) != 0) {
        fprintf(stderr, "Calibration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s at 20 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    /* ---- Main loop ---- */
    while (g_running) {
        gyro_data_t d;
        if (read_gyro_sample(g_i2c_fd, &d) != 0) {
            fprintf(stderr, "Read error — skipping sample\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        /* Apply offsets */
        d.x -= g_x_offset;
        d.y -= g_y_offset;
        d.z -= g_z_offset;

        log_gyro_data(g_log_fp, &d);

        /* Alert */
        if (fabsf(d.x) > ALERT_THRESHOLD_DPS ||
            fabsf(d.y) > ALERT_THRESHOLD_DPS ||
            fabsf(d.z) > ALERT_THRESHOLD_DPS) {
            log_alert(g_log_fp, &d);
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

