#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS        0x53
#define ADXL345_DEVID          0x00
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_DATA_FORMAT    0x31
#define ADXL345_DATAX0         0x32
#define ADXL345_BW_RATE        0x2C
#define ADXL345_FIFO_CTL       0x38
#define ADXL345_INT_ENABLE     0x2E
#define ADXL345_INT_MAP        0x2F
#define ADXL345_INT_SOURCE     0x30
#define ADXL345_THRESH_ACT     0x24
#define ADXL345_ACT_INACT_CTL  0x27
#define ADXL345_THRESH_INACT   0x28
#define ADXL345_TIME_INACT     0x29
#define ADXL345_INACT_CTL      0x2A
#define ADXL345_THRESH_FF      0x28
#define ADXL345_TIME_FF        0x29
#define ADXL345_TAP_AXES       0x2D
#define ADXL345_FIFO_STATUS    0x35
#define ADXL345_FIFO_DATA      0x36
#define ADXL345_DEVID_VALUE    0xE5

#define LED_PIN                17
#define SAMPLE_INTERVAL_US     100000
#define ACCEL_THRESHOLD_G      2.0f
#define ACCEL_RANGE_G          2.0f
#define ACCEL_SCALE            (ACCEL_RANGE_G / 256.0f)

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int adxl345_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, len %u): %d\n", reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C block read short read (reg 0x%02X, expected %u, got %d)\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int adxl345_init(int handle) {
    uint8_t devid = 0;
    if (adxl345_read_reg(handle, ADXL345_DEVID, &devid) != 0) {
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "ADXL345 device ID mismatch: got 0x%02X, expected 0x%02X\n", devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (adxl345_write_reg(handle, ADXL345_BW_RATE, 0x0A) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x08) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_DATA_FORMAT, 0x08) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_FIFO_CTL, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_INT_ENABLE, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_INT_MAP, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_INT_SOURCE, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_THRESH_ACT, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_ACT_INACT_CTL, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_THRESH_INACT, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_TIME_INACT, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_INACT_CTL, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_THRESH_FF, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_TIME_FF, 0x00) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_TAP_AXES, 0x00) < 0) return -1;

    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (adxl345_read_block(handle, ADXL345_DATAX0, buf, 6) != 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);
}

static void control_led(float x, float y, float z) {
    bool above = (fabsf(x) > ACCEL_THRESHOLD_G) || (fabsf(y) > ACCEL_THRESHOLD_G) || (fabsf(z) > ACCEL_THRESHOLD_G);
    gpioWrite(LED_PIN, above ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %d\n", ADXL345_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    g_log_file = fopen("accel_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open accel_log.txt for appending\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    while (g_running) {
        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

