/*
 * GY-51 LSM303DLHC Tilt-Compensated Heading Logger
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Wiring:
 *   LSM303DLHC VCC -> 3.3 V
 *   LSM303DLHC GND -> GND
 *   LSM303DLHC SDA -> GPIO2 (I2C1 SDA)
 *   LSM303DLHC SCL -> GPIO3 (I2C1 SCL)
 *   LSM303DLHC ADDR -> GND (I2C address 0x1E)
 *
 * Build:  gcc -O2 -Wall -o compass compass.c -lm -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x1E
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_ACCEL_OUT_X_H_A   0x29
#define LSM303_ACCEL_OUT_Y_L_A   0x2A
#define LSM303_ACCEL_OUT_Y_H_A   0x2B
#define LSM303_ACCEL_OUT_Z_L_A   0x2C
#define LSM303_ACCEL_OUT_Z_H_A   0x2D

#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03
#define LSM303_MAG_OUT_X_L_M     0x04
#define LSM303_MAG_OUT_Z_H_M     0x05
#define LSM303_MAG_OUT_Z_L_M     0x06
#define LSM303_MAG_OUT_Y_H_M     0x07
#define LSM303_MAG_OUT_Y_L_M     0x08

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_accel_fd = -1;
static int g_mag_fd   = -1;

/* ---- Accelerometer scale factor (g/LSB) ---- */
#define ACCEL_SCALE 0.000244f  /* 1 mg/LSB => 0.244 mg/LSB => 0.000244 g/LSB */

/* ---- Magnetometer scale factor (gauss/LSB) ---- */
#define MAG_SCALE 0.00014f     /* 1 mGauss/LSB => 0.14 mGauss/LSB => 0.00014 gauss/LSB */

/* ---- Tilt-compensation constants (LSM303DLHC datasheet) ---- */
#define ACCEL_X_OFFSET 0.0f
#define ACCEL_Y_OFFSET 0.0f
#define ACCEL_Z_OFFSET 0.0f

#define MAG_X_OFFSET 0.0f
#define MAG_Y_OFFSET 0.0f
#define MAG_Z_OFFSET 0.0f

/* ---- Sampling interval ---- */
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* ---- Data structure ---- */
typedef struct {
    float accel_x, accel_y, accel_z;  /* g */
    float mag_x, mag_y, mag_z;        /* gauss */
    float heading;                    /* degrees */
} sensor_data_t;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Accelerometer ---- */
static int init_accelerometer(int fd)
{
    /* CTRL_REG1_A: 0x27 = 0b0010_0111
     *   ODR=50 Hz (0x02), all axes enabled (0x07) */
    if (i2c_write_reg8(fd, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0)
        return -1;
    /* CTRL_REG4_A: 0x08 = 0b0000_1000
     *   Full-scale ±2g, high-resolution mode */
    if (i2c_write_reg8(fd, LSM303_ACCEL_CTRL_REG4_A, 0x08) < 0)
        return -1;
    return 0;
}

static int read_accelerometer(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, LSM303_ACCEL_OUT_X_L_A | 0x80, buf, 6) < 0)  /* auto-increment */
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

/* ---- Magnetometer ---- */
static int init_magnetometer(int fd)
{
    /* MR_REG_M: 0x00 = 0b0000_0000
     *   Temp comp off, 8-average, 15 Hz ODR, normal mode */
    if (i2c_write_reg8(fd, LSM303_MAG_MR_REG_M, 0x00) < 0)
        return -1;
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, LSM303_MAG_OUT_X_H_M, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_z = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_y = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x * MAG_SCALE;
    *y = (float)raw_y * MAG_SCALE;
    *z = (float)raw_z * MAG_SCALE;
    return 0;
}

/* ---- Tilt-compensated heading ---- */
static float calculate_heading(float ax, float ay, float az,
                                float mx, float my, float mz)
{
    /* Remove offsets */
    ax -= ACCEL_X_OFFSET;
    ay -= ACCEL_Y_OFFSET;
    az -= ACCEL_Z_OFFSET;
    mx -= MAG_X_OFFSET;
    my -= MAG_Y_OFFSET;
    mz -= MAG_Z_OFFSET;

    /* Normalize acceleration */
    float norm_a = sqrtf(ax * ax + ay * ay + az * az);
    if (norm_a < 1e-6f) {
        fprintf(stderr, "Warning: acceleration vector near zero; heading invalid\n");
        return 0.0f;
    }
    ax /= norm_a;
    ay /= norm_a;
    az /= norm_a;

    /* Normalize magnetometer */
    float norm_m = sqrtf(mx * mx + my * my + mz * mz);
    if (norm_m < 1e-6f) {
        fprintf(stderr, "Warning: magnetometer vector near zero; heading invalid\n");
        return 0.0f;
    }
    mx /= norm_m;
    my /= norm_m;
    mz /= norm_m;

    /* Tilt-compensated heading (degrees) */
    float heading = atan2f(my, mx) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ---- Logging ---- */
static int log_data(const sensor_data_t *data)
{
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening compass_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            data->heading,
            data->accel_x, data->accel_y, data->accel_z,
            data->mag_x, data->mag_y, data->mag_z);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing compass_log.txt: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_accel_fd >= 0) {
        close(g_accel_fd);
        g_accel_fd = -1;
    }
    if (g_mag_fd >= 0) {
        close(g_mag_fd);
        g_mag_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    /* Open I2C bus 1 */
    g_accel_fd = open("/dev/i2c-1", O_RDWR);
    if (g_accel_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1 for accelerometer: %s\n", strerror(errno));
        return 1;
    }
    g_mag_fd = open("/dev/i2c-1", O_RDWR);
    if (g_mag_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1 for magnetometer: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Set slave addresses */
    if (ioctl(g_accel_fd, I2C_SLAVE, LSM303_ACCEL_ADDR) < 0) {
        fprintf(stderr, "Error setting accelerometer I2C address: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(g_mag_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Error setting magnetometer I2C address: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Initialize sensors */
    if (init_accelerometer(g_accel_fd) < 0) {
        fprintf(stderr, "Accelerometer initialization failed\n");
        cleanup();
        return 1;
    }
    if (init_magnetometer(g_mag_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        cleanup();
        return 1;
    }

    /* Write CSV header if file is new/empty */
    FILE *fp = fopen("compass_log.txt", "r");
    if (!fp) {
        fp = fopen("compass_log.txt", "w");
        if (fp) {
            fprintf(fp, "timestamp,heading,accel_x,accel_y,accel_z,mag_x,mag_y,mag_z\n");
            fclose(fp);
        } else {
            fprintf(stderr, "Warning: could not create compass_log.txt header: %s\n", strerror(errno));
        }
    } else {
        fclose(fp);
    }

    printf("LSM303DLHC compass logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_accelerometer(g_accel_fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accelerometer read error; skipping sample\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        if (read_magnetometer(g_mag_fd, &mx, &my, &mz) < 0) {
