/*
 * GY-51 LSM303DLHC Tilt-Compensated Heading Logger
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Wiring:
 *   LSM303DLHC VCC -> 3.3 V
 *   LSM303DLHC GND -> GND
 *   LSM303DLHC SDA -> GPIO2 (I2C1 SDA)
 *   LSM303DLHC SCL -> GPIO3 (I2C1 SCL)
 *   LSM303DLHC ADDR -> GND (I2C address 0x1E)
 *
 * Build:  gcc -O2 -Wall -o compass compass.c -lm -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x1E
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_ACCEL_OUT_X_H_A   0x29
#define LSM303_ACCEL_OUT_Y_L_A   0x2A
#define LSM303_ACCEL_OUT_Y_H_A   0x2B
#define LSM303_ACCEL_OUT_Z_L_A   0x2C
#define LSM303_ACCEL_OUT_Z_H_A   0x2D

#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03
#define LSM303_MAG_OUT_X_L_M     0x04
#define LSM303_MAG_OUT_Z_H_M     0x05
#define LSM303_MAG_OUT_Z_L_M     0x06
#define LSM303_MAG_OUT_Y_H_M     0x07
#define LSM303_MAG_OUT_Y_L_M     0x08

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_accel_fd = -1;
static int g_mag_fd   = -1;

/* ---- Accelerometer scale factor (g/LSB) ---- */
#define ACCEL_SCALE 0.000244f  /* 1 mg/LSB => 0.244 mg/LSB => 0.000244 g/LSB */

/* ---- Magnetometer scale factor (gauss/LSB) ---- */
#define MAG_SCALE 0.00014f     /* 1 mGauss/LSB => 0.14 mGauss/LSB => 0.00014 gauss/LSB */

/* ---- Tilt-compensation constants (LSM303DLHC datasheet) ---- */
#define ACCEL_X_OFFSET 0.0f
#define ACCEL_Y_OFFSET 0.0f
#define ACCEL_Z_OFFSET 0.0f

#define MAG_X_OFFSET 0.0f
#define MAG_Y_OFFSET 0.0f
#define MAG_Z_OFFSET 0.0f

/* ---- Sampling interval ---- */
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* ---- Data structure ---- */
typedef struct {
    float accel_x, accel_y, accel_z;  /* g */
    float mag_x, mag_y, mag_z;        /* gauss */
    float heading;                    /* degrees */
} sensor_data_t;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Accelerometer ---- */
static int init_accelerometer(int fd)
{
    /* CTRL_REG1_A: 0x27 = 0b0010_0111
     *   ODR=50 Hz (0x02), all axes enabled (0x07) */
    if (i2c_write_reg8(fd, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0)
        return -1;
    /* CTRL_REG4_A: 0x08 = 0b0000_1000
     *   Full-scale ±2g, high-resolution mode */
    if (i2c_write_reg8(fd, LSM303_ACCEL_CTRL_REG4_A, 0x08) < 0)
        return -1;
    return 0;
}

static int read_accelerometer(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, LSM303_ACCEL_OUT_X_L_A | 0x80, buf, 6) < 0)  /* auto-increment */
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

/* ---- Magnetometer ---- */
static int init_magnetometer(int fd)
{
    /* MR_REG_M: 0x00 = 0b0000_0000
     *   Temp comp off, 8-average, 15 Hz ODR, normal mode */
    if (i2c_write_reg8(fd, LSM303_MAG_MR_REG_M, 0x00) < 0)
        return -1;
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, LSM303_MAG_OUT_X_H_M, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_z = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_y = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x * MAG_SCALE;
    *y = (float)raw_y * MAG_SCALE;
    *z = (float)raw_z * MAG_SCALE;
    return 0;
}

/* ---- Tilt-compensated heading ---- */
static float calculate_heading(float ax, float ay, float az,
                                float mx, float my, float mz)
{
    /* Remove offsets */
    ax -= ACCEL_X_OFFSET;
    ay -= ACCEL_Y_OFFSET;
    az -= ACCEL_Z_OFFSET;
    mx -= MAG_X_OFFSET;
    my -= MAG_Y_OFFSET;
    mz -= MAG_Z_OFFSET;

    /* Normalize acceleration */
    float norm_a = sqrtf(ax * ax + ay * ay + az * az);
    if (norm_a < 1e-6f) {
        fprintf(stderr, "Warning: acceleration vector near zero; heading invalid\n");
        return 0.0f;
    }
    ax /= norm_a;
    ay /= norm_a;
    az /= norm_a;

    /* Normalize magnetometer */
    float norm_m = sqrtf(mx * mx + my * my + mz * mz);
    if (norm_m < 1e-6f) {
        fprintf(stderr, "Warning: magnetometer vector near zero; heading invalid\n");
        return 0.0f;
    }
    mx /= norm_m;
    my /= norm_m;
    mz /= norm_m;

    /* Tilt-compensated heading (degrees) */
    float heading = atan2f(my, mx) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ---- Logging ---- */
static int log_data(const sensor_data_t *data)
{
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening compass_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            data->heading,
            data->accel_x, data->accel_y, data->accel_z,
            data->mag_x, data->mag_y, data->mag_z);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing compass_log.txt: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_accel_fd >= 0) {
        close(g_accel_fd);
        g_accel_fd = -1;
    }
    if (g_mag_fd >= 0) {
        close(g_mag_fd);
        g_mag_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    /* Open I2C bus 1 */
    g_accel_fd = open("/dev/i2c-1", O_RDWR);
    if (g_accel_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1 for accelerometer: %s\n", strerror(errno));
        return 1;
    }
    g_mag_fd = open("/dev/i2c-1", O_RDWR);
    if (g_mag_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1 for magnetometer: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Set slave addresses */
    if (ioctl(g_accel_fd, I2C_SLAVE, LSM303_ACCEL_ADDR) < 0) {
        fprintf(stderr, "Error setting accelerometer I2C address: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(g_mag_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Error setting magnetometer I2C address: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Initialize sensors */
    if (init_accelerometer(g_accel_fd) < 0) {
        fprintf(stderr, "Accelerometer initialization failed\n");
        cleanup();
        return 1;
    }
    if (init_magnetometer(g_mag_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        cleanup();
        return 1;
    }

    /* Write CSV header if file is new/empty */
    FILE *fp = fopen("compass_log.txt", "r");
    if (!fp) {
        fp = fopen("compass_log.txt", "w");
        if (fp) {
            fprintf(fp, "timestamp,heading,accel_x,accel_y,accel_z,mag_x,mag_y,mag_z\n");
            fclose(fp);
        } else {
            fprintf(stderr, "Warning: could not create compass_log.txt header: %s\n", strerror(errno));
        }
    } else {
        fclose(fp);
    }

    printf("LSM303DLHC compass logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_accelerometer(g_accel_fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accelerometer read error; skipping sample\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        if (read_magnetometer(g_mag_fd, &mx, &my, &mz) < 0) {
            fprintf(stderr, "Magnetometer read error; skipping sample\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        sensor_data_t data;
        data.accel_x = ax;
        data.accel_y = ay;
        data.accel_z = az;
        data.mag_x   = mx;
        data.mag_y   = my;
        data.mag_z   = mz;
        data.heading = calculate_heading(ax, ay, az, mx, my, mz);

        if (log_data(&data) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

code:
/*
 * Raspberry Pi 4 Model B — Dual IMP23ABSU Ultrasonic MEMS Microphone Sampler
 *
 * Wiring:
 *   Sensor 1 SDA -> GPIO2 (I2C bus 1 SDA)
 *   Sensor 1 SCL -> GPIO3 (I2C bus 1 SCL)
 *   Sensor 2 SDA -> GPIO2 (I2C bus 1 SDA)
 *   Sensor 2 SCL -> GPIO3 (I2C bus 1 SCL)
 *   VDD -> 3.3 V, GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_sampler audio_sampler.c -lpigpio -lrt
 * Run:    sudo ./audio_sampler
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define SENSOR1_ADDR         0x0A
#define SENSOR2_ADDR         0x0B
#define SAMPLE_INTERVAL_US   10000   /* 10 ms */
#define LOG_FILE             "audio_log.dat"

/* IMP23ABSU register map (16-bit signed, little-endian on bus) */
#define REG_DATA_MSB         0x00
#define REG_DATA_LSB         0x01

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle1 = -1;
static int  g_i2c_handle2 = -1;
static FILE *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one 16-bit signed sample from an IMP23ABSU at `addr`.          */
/* Returns 0 on success and stores the sample in *out; returns -1 on   */
/* I2C error or sensor-absent (no ACK).                               */
/* ------------------------------------------------------------------ */
static int read_sensor_sample(int handle, int16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(handle, REG_DATA_MSB, buf, 2);
    if (rc != 2) {
        if (rc < 0)
            fprintf(stderr, "I2C read error (handle %d): %s\n",
                    handle, strerror(errno));
        else
            fprintf(stderr, "I2C short read (handle %d): %d bytes\n",
                    handle, rc);
        return -1;
    }

    /* IMP23ABSU is little-endian: LSB first, MSB second */
    *out = (int16_t)((uint16_t)buf[1] << 8 | (uint8_t)buf[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, SENSOR2_ADDR, strerror(errno));
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "sec,nsec,sensor1,sensor2,tdoa\n");
        fflush(g_log_file);
    }

    printf("Sampling IMP23ABSU sensors on I2C bus %d (addr 0x%02X, 0x%02X).\n",
           I2C_BUS, SENSOR1_ADDR, SENSOR2_ADDR);
    printf("Logging to '%s'. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        struct timespec ts;
        int16_t s1 = 0, s2 = 0;
        int     rc1, rc2;

        clock_gettime(CLOCK_REALTIME, &ts);

        rc1 = read_sensor_sample(g_i2c_handle1, &s1);
        rc2 = read_sensor_sample(g_i2c_handle2, &s2);

        if (rc1 == 0 && rc2 == 0) {
            long tdoa_ns = (long)s1 - (long)s2;
            fprintf(g_log_file, "%ld,%ld,%d,%d,%ld\n",
                    (long)ts.tv_sec, (long)ts.tv_nsec,
                    s1, s2, tdoa_ns);
            fflush(g_log_file);
        } else {
            /* On error, skip this sample but keep running */
            if (rc1 != 0)
                fprintf(stderr, "Sensor 1 read failed; skipping sample.\n");
            if (rc2 != 0)
                fprintf(stderr, "Sensor 2 read failed; skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

