        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "sec,nsec,sensor1,sensor2,tdoa\n");
        fflush(g_log_file);
    }

    printf("Sampling IMP23ABSU sensors on I2C bus %d (addr 0x%02X, 0x%02X).\n",
           I2C_BUS, SENSOR1_ADDR, SENSOR2_ADDR);
    printf("Logging to '%s'. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        struct timespec ts;
        int16_t s1 = 0, s2 = 0;
        int     rc1, rc2;

        clock_gettime(CLOCK_REALTIME, &ts);

        rc1 = read_sensor_sample(g_i2c_handle1, &s1);
        rc2 = read_sensor_sample(g_i2c_handle2, &s2);

        if (rc1 == 0 && rc2 == 0) {
            long tdoa_ns = (long)s1 - (long)s2;
            fprintf(g_log_file, "%ld,%ld,%d,%d,%ld\n",
                    (long)ts.tv_sec, (long)ts.tv_nsec,
                    s1, s2, tdoa_ns);
            fflush(g_log_file);
        } else {
            /* On error, skip this sample but keep running */
            if (rc1 != 0)
                fprintf(stderr, "Sensor 1 read failed; skipping sample.\n");
            if (rc2 != 0)
                fprintf(stderr, "Sensor 2 read failed; skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

