/*
 * ADIS16488A IMU reader for Raspberry Pi 4 Model B
 *
 * SPI0 CE0 (BCM GPIO8)  -> ADIS16488A CS
 * SPI0 SCLK (BCM GPIO11) -> ADIS16488A SCLK
 * SPI0 MOSI (BCM GPIO10) -> ADIS16488A DIN
 * SPI0 MISO (BCM GPIO9)  -> ADIS16488A DOUT
 *
 * SPI: 1 MHz, mode 3 (CPOL=1, CPHA=1), 16-bit words, 40 us stall time.
 *
 * Build:  gcc -O2 -Wall -Wextra -o imu_reader imu_reader.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ---- ADIS16488A register addresses (16-bit, MSB=0) ---- */
#define REG_X_GYRO_OUT  0x04
#define REG_Y_GYRO_OUT  0x06
#define REG_Z_GYRO_OUT  0x08
#define REG_X_ACCEL_OUT 0x0A
#define REG_Y_ACCEL_OUT 0x0C
#define REG_Z_ACCEL_OUT 0x0E

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        3          /* CPOL=1, CPHA=1 */
#define SAMPLE_PERIOD_US 100000U   /* 100 ms */
#define STALL_TIME_US   40U        /* >= 40 us between requests */
#define CSV_FILENAME    "imu_data.csv"

/* ---- Globals for cleanup ---- */
static int      spi_fd = -1;
static FILE    *csv_fp = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- SPI transfer helper ---- */
static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- ADIS16488A register read ----
 * 16-bit command: [0x00][reg_addr | 0x80]  (MSB=1 = read)
 * Result: next 16-bit transfer returns [0x00][data_hi][data_lo]
 */
static int adis_read_reg(uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(0x80 | (reg & 0x7F)), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    /* Small stall between request and data transfer */
    usleep(STALL_TIME_US);

    tx[0] = 0x00;
    tx[1] = 0x00;
    rx[0] = 0;
    rx[1] = 0;

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    *out = (int16_t)((rx[1] << 8) | rx[0]);
    return 0;
}

/* ---- Read a signed 16-bit sample ---- */
static int read_axis(uint8_t reg, float *out, float scale)
{
    int16_t raw;
    if (adis_read_reg(reg, &raw) < 0)
        return -1;
    *out = (float)raw * scale;
    return 0;
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t cur = strlen(buf);
    snprintf(buf + cur, len - cur, ".%03ld", ts.tv_nsec / 1000000L);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (csv_fp) {
        fflush(csv_fp);
        fclose(csv_fp);
        csv_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ---- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open CSV ---- */
    csv_fp = fopen(CSV_FILENAME, "w");
    if (!csv_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(csv_fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(csv_fp);

    /* ---- Register cleanup ---- */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "atexit registration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (running) {
        float gx = 0.0f, gy = 0.0f, gz = 0.0f;
        float ax = 0.0f, ay = 0.0f, az = 0.0f;
        int err = 0;

        if (read_axis(REG_X_GYRO_OUT, &gx, 0.005f) < 0) err = 1;
        if (read_axis(REG_Y_GYRO_OUT, &gy, 0.005f) < 0) err = 1;
        if (read_axis(REG_Z_GYRO_OUT, &gz, 0.005f) < 0) err = 1;
        if (read_axis(REG_X_ACCEL_OUT, &ax, 0.00025f) < 0) err = 1;
        if (read_axis(REG_Y_ACCEL_OUT, &ay, 0.00025f) < 0) err = 1;
        if (read_axis(REG_Z_ACCEL_OUT, &az, 0.00025f) < 0) err = 1;

        if (err) {
            fprintf(stderr, "Skipping sample due to SPI read error\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(csv_fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                ts, gx, gy, gz, ax, ay, az);
        fflush(csv_fp);

        /* Non-blocking sleep so signals are caught promptly */
        for (int i = 0; i < 10 && running; i++)
            usleep(10000); /* 10 × 10 ms = 100 ms */
    }

    return EXIT_SUCCESS;
}

