#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8

#define ADIS16448_REG_GLOB_CMD 0x00
#define ADIS16448_REG_X_GYRO_OUT 0x04
#define ADIS16448_REG_Y_GYRO_OUT 0x06
#define ADIS16448_REG_Z_GYRO_OUT 0x08
#define ADIS16448_REG_X_ACCEL_OUT 0x0A
#define ADIS16448_REG_Y_ACCEL_OUT 0x0C
#define ADIS16448_REG_Z_ACCEL_OUT 0x0E

#define GYRO_SCALE 0.02f
#define ACCEL_SCALE 0.00025f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        return -1;
    }

    *value = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int read_imu_data(int fd, float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    uint16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (read_register(fd, ADIS16448_REG_X_GYRO_OUT, &raw_gyro_x) < 0) return -1;
    if (read_register(fd, ADIS16448_REG_Y_GYRO_OUT, &raw_gyro_y) < 0) return -1;
    if (read_register(fd, ADIS16448_REG_Z_GYRO_OUT, &raw_gyro_z) < 0) return -1;
    if (read_register(fd, ADIS16448_REG_X_ACCEL_OUT, &raw_accel_x) < 0) return -1;
    if (read_register(fd, ADIS16448_REG_Y_ACCEL_OUT, &raw_accel_y) < 0) return -1;
    if (read_register(fd, ADIS16448_REG_Z_ACCEL_OUT, &raw_accel_z) < 0) return -1;

    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCEL_SCALE;
    *accel_y = (float)raw_accel_y * ACCEL_SCALE;
    *accel_z = (float)raw_accel_z * ACCEL_SCALE;

    return 0;
}

int main(void) {
    int fd = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        goto cleanup;
    }

    printf("ADIS16448 IMU Reader (SPI0, CS0, Mode 3, 1 MHz)\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_imu_data(fd, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Error reading IMU data. Retrying...\n");
            usleep(100000);
            continue;
        }

        printf("Gyro X: %+.2f dps, Y: %+.2f dps, Z: %+.2f dps, "
               "Accel X: %+.3f g, Y: %+.3f g, Z: %+.3f g\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        usleep(100000);
    }

    printf("\nExiting cleanly.\n");
    ret = 0;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

