#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* ADIS16448 register addresses (16-bit, upper byte = 0x00) */
#define REG_GYRO_X_OUT  0x04
#define REG_GYRO_Y_OUT  0x06
#define REG_GYRO_Z_OUT  0x08
#define REG_ACCEL_X_OUT 0x0A
#define REG_ACCEL_Y_OUT 0x0C
#define REG_ACCEL_Z_OUT 0x0E

#define GYRO_SCALE  0.05f   /* deg/sec per LSB  */
#define ACCEL_SCALE 0.00025f /* g per LSB       */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a 16-bit register using the two-cycle protocol.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    /* First transfer: send read command (bit 15 = 1) */
    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Stall time: at least 40 µs (datasheet: 50 µs typ) */
    gpioDelay(50);

    /* Second transfer: clock out the 16-bit data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, 1 MHz, Mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU reader started (SPI ch%d, %d Hz). Press Ctrl+C to stop.\n",
           SPI_CHANNEL, SPI_SPEED);

    while (g_running) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accel_x, accel_y, accel_z;

        if (read_register(REG_GYRO_X_OUT, &gyro_x) ||
            read_register(REG_GYRO_Y_OUT, &gyro_y) ||
            read_register(REG_GYRO_Z_OUT, &gyro_z) ||
            read_register(REG_ACCEL_X_OUT, &accel_x) ||
            read_register(REG_ACCEL_Y_OUT, &accel_y) ||
            read_register(REG_ACCEL_Z_OUT, &accel_z)) {
            fprintf(stderr, "SPI transfer error — continuing\n");
            gpioDelay(100000);
            continue;
        }

        float gyro_x_dps  = gyro_x  * GYRO_SCALE;
        float gyro_y_dps  = gyro_y  * GYRO_SCALE;
        float gyro_z_dps  = gyro_z  * GYRO_SCALE;
        float accel_x_g   = accel_x * ACCEL_SCALE;
        float accel_y_g   = accel_y * ACCEL_SCALE;
        float accel_z_g   = accel_z * ACCEL_SCALE;

        printf("Gyro:  X=%.2f  Y=%.2f  Z=%.2f  deg/s | Accel:  X=%.4f  Y=%.4f  Z=%.4f  g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

