/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MPU-6886 SDA  -> GPIO 2 (pin 3, I2C bus 1)
 *   MPU-6886 SCL  -> GPIO 3 (pin 5, I2C bus 1)
 *   MPU-6886 VDD  -> 3.3 V
 *   MPU-6886 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6886 mpu6886.c
 * Run:    ./mpu6886   (Ctrl-C to exit)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6886 constants (verified against datasheet) ---- */
#define MPU6886_ADDR        0x68          /* ADDR pin low  -> 0x68, high -> 0x69 */
#define MPU6886_BUS         "/dev/i2c-1"

#define REG_SMPLRT_DIV      0x19
#define REG_CONFIG          0x1A
#define REG_GYRO_CONFIG    0x1B
#define REG_ACCEL_CONFIG   0x1C
#define REG_ACCEL_XOUT_H   0x3B
#define REG_GYRO_XOUT_H    0x43
#define REG_PWR_MGMT_1     0x6B
#define REG_WHO_AM_I       0x75

#define WHO_AM_I_EXPECTED  0x68          /* MPU-6886 returns 0x68 */

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, val, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, val, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_burst: write(0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_burst: read(0x%02X, %zu) failed: %s (read %zd bytes)\n",
                reg, len, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization ---- */

static int mpu6886_init(int fd)
{
    uint8_t who = 0;
    if (i2c_read_reg8(fd, REG_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (who != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_EXPECTED);
        return -1;
    }

    /* Wake up: clear SLEEP bit in PWR_MGMT_1 (use internal 8 MHz clock) */
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) != 0)
        return -1;

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /* DLPF_CFG = 0 -> bandwidth 184 Hz, delay 2.9 ms */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x00) != 0)
        return -1;

    /* Gyro full-scale range ±250 dps (FS_SEL = 0) */
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, 0x00) != 0)
        return -1;

    /* Accel full-scale range ±2 g (AFS_SEL = 0) */
    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) != 0)
        return -1;

    return 0;
}

/* ---- Data acquisition ---- */

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, REG_ACCEL_XOUT_H, buf, sizeof(buf)) != 0)
        return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int read_gyro(int fd, int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, REG_GYRO_XOUT_H, buf, sizeof(buf)) != 0)
        return -1;
    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(MPU6886_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", MPU6886_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MPU6886_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (mpu6886_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6886 ready.  Reading at 50 ms intervals (Ctrl-C to exit).\n");

    const struct timespec sleep_ts = { 0, 50 * 1000 * 1000 }; /* 50 ms */

    while (g_running) {
        int16_t ax = 0, ay = 0, az = 0;
        int16_t gx = 0, gy = 0, gz = 0;
        bool ok = true;

        for (int attempt = 0; attempt < 3 && g_running; ++attempt) {
            if (read_accel(g_i2c_fd, &ax, &ay, &az) != 0) {
                ok = false;
                break;
            }
            if (read_gyro(g_i2c_fd, &gx, &gy, &gz) != 0) {
                ok = false;
                break;
            }
            break; /* success */
        }

        if (!ok) {
            if (g_running)
                fprintf(stderr, "Read failed after 3 attempts; continuing.\n");
            nanosleep(&sleep_ts, NULL);
            continue;
        }

        printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Gyro: X=%6d  Y=%6d  Z=%6d\n",
               ax, ay, az, gx, gy, gz);
        fflush(stdout);

        nanosleep(&sleep_ts, NULL);
    }

    printf("\nExiting cleanly.\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

