#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADXL345 register definitions (verified against datasheet) ---- */
#define ADXL345_ADDRESS        0x53
#define ADXL345_DEVID          0x00
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_DATAX0         0x32
#define ADXL345_BW_RATE        0x2C
#define ADXL345_DATA_FORMAT    0x31

/* ---- Application constants ---- */
#define I2C_BUS               1
#define LED_GPIO              17
#define IMPACT_THRESHOLD_G    2.5f
#define POLL_DELAY_US         10000   /* 10 ms */
#define LED_ON_DURATION_US    500000  /* 500 ms */
#define LOG_FILE_NAME         "impact_log.txt"

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Function prototypes ---- */
static int  adxl345_init(int handle);
static int  adxl345_read_xyz(int handle, float *x, float *y, float *z);
static float calculate_magnitude(float x, float y, float z);
static void log_impact(float x, float y, float z, float magnitude);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Cleanup: release all resources ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- ADXL345 initialization ---- */
static int adxl345_init(int handle)
{
    /* Verify device identity */
    int devid = i2cReadByteData(handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: failed to read DEVID register (I2C error %d).\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Error: DEVID mismatch (got 0x%02X, expected 0xE5). "
                        "Sensor not present or wrong device.\n", devid);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set standby mode.\n");
        return -1;
    }

    /* Data format: full resolution, ±2g range (0x0B) */
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: failed to set data format.\n");
        return -1;
    }

    /* Output data rate: 100 Hz (0x0A) */
    if (i2cWriteByteData(handle, ADXL345_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error: failed to set data rate.\n");
        return -1;
    }

    /* Clear standby bit, enable measurement */
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: failed to set measurement mode.\n");
        return -1;
    }

    return 0;
}

/* ---- Read X/Y/Z acceleration (full-resolution, ±2g) ---- */
static int adxl345_read_xyz(int handle, float *x, float *y, float *z)
{
    char raw[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6-byte acceleration block.\n");
        return -1;
    }

    x_raw = (int16_t)(((uint16_t)raw[1] << 8) | (uint8_t)raw[0]);
    y_raw = (int16_t)(((uint16_t)raw[3] << 8) | (uint8_t)raw[2]);
    z_raw = (int16_t)(((uint16_t)raw[5] << 8) | (uint8_t)raw[4]);

    /* Full-resolution ±2g: 3.9 mg/LSB = 256 LSB/g */
    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;

    return 0;
}

/* ---- Calculate magnitude of acceleration vector ---- */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ---- Log impact event to file ---- */
static void log_impact(float x, float y, float z, float magnitude)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed.\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n",
                ts, x, y, z, magnitude) < 0) {
        fprintf(stderr, "Warning: failed to write to log file.\n");
    }
    fflush(log_file);
}

int main(void)
{
    float x, y, z, magnitude;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (code %d).\n",
                I2C_BUS, ADXL345_ADDRESS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 impact monitor running. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (running) {
        if (adxl345_read_xyz(i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD_G) {
                printf("Impact: magnitude %.3f g (X=%.3f Y=%.3f Z=%.3f)\n",
                       magnitude, x, y, z);

                if (gpioWrite(LED_GPIO, 1) < 0) {
                    fprintf(stderr, "Warning: failed to turn on LED.\n");
                }
                gpioDelay(LED_ON_DURATION_US);
                if (gpioWrite(LED_GPIO, 0) < 0) {
                    fprintf(stderr, "Warning: failed to turn off LED.\n");
                }

                log_impact(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

