#define GYRO_CONFIG 0x1B

#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_imu(int handle) {
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU (PWR_MGMT_1).\n");
        return -1;
    }
    gpioDelay(100000);

    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range.\n");
        return -1;
    }

    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range.\n");
        return -1;
    }

    return 0;
}

static int read_imu_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz) {
    char buf[14];

    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error: Could not read IMU data block.\n");
        return -1;
    }

    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

static void log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d,%d,%d,%d\n",
            timestamp, ax, ay, az, gx, gy, gz);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device on bus %d, addr 0x%02X.\n",
                I2C_BUS, ICM20602_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_imu(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening imu_log.csv");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");

    int16_t ax, ay, az, gx, gy, gz;

    while (running) {
        if (read_imu_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(log_file, ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: I2C read failed, continuing.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

