#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1
#define MMA8451_ADDR   0x1D   /* SA0 tied to GND on GY-45 breakout */

#define REG_STATUS     0x00
#define REG_OUT_X_MSB  0x01
#define REG_WHO_AM_I   0x0D
#define REG_XYZ_DATA_CFG 0x0E
#define REG_CTRL_REG1  0x2A
#define REG_CTRL_REG2  0x2B

#define WHO_AM_I_VAL   0x2A   /* MMA8451Q returns 0x2A */

#define LED_PIN        17
#define THRESHOLD_G    2.0f
#define POLL_DELAY_US  100000  /* 100 ms */
#define LED_ON_US      500000  /* 500 ms */

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    return i2cWriteByteData(i2c_handle, reg, val);
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    int r = i2cReadByteData(i2c_handle, reg);
    if (r < 0) return -1;
    *val = (uint8_t)r;
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    return i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
}

/* ---- MMA8451Q init ---- */
static int mma8451_init(void)
{
    uint8_t who;

    /* Verify device identity */
    if (i2c_read_reg(REG_WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2c_write_reg(REG_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set standby mode\n");
        return -1;
    }

    /* ±2 g range: FS=0, OSR=0 (800 Hz output data rate) */
    if (i2c_write_reg(REG_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set data range\n");
        return -1;
    }

    /* Active mode, 800 Hz ODR */
    if (i2c_write_reg(REG_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error: failed to set active mode\n");
        return -1;
    }

    return 0;
}

/* ---- Read acceleration (returns 0 on success, -1 on error) ---- */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    if (i2c_read_block(REG_OUT_X_MSB, buf, 6) < 0) {
        fprintf(stderr, "Error: failed to read acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ---- Log impact with timestamp ---- */
static void log_impact(int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    int16_t x, y, z;
    float mag;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MMA8451_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, MMA8451_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (mma8451_init() < 0) {
        fprintf(stderr, "Error: MMA8451Q initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open log file */
    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open impact_log.txt\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring acceleration (threshold %.1f g)... Press Ctrl+C to exit.\n",
           THRESHOLD_G);

    /* Main loop */
    while (running) {
        if (read_acceleration(&x, &y, &z) == 0) {
            mag = sqrtf((float)x * x + (float)y * y + (float)z * z);
            mag /= 1024.0f;  /* ±2 g range: 1 g = 1024 counts */

            if (mag > THRESHOLD_G) {
                printf("Impact detected! Magnitude: %.2f g\n", mag);
                log_impact(x, y, z);

                gpioWrite(LED_PIN, 1);
                gpioDelay(LED_ON_US);
                gpioWrite(LED_PIN, 0);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

