/*
 * Free-fall detection on a SparkFun ADXL345 (I2C) using a Raspberry Pi 4.
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA, physical pin 3)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL, physical pin 5)
 *   ADXL345 INT1 -> GPIO17 (physical pin 11, BCM 17)  [active-low, open-drain]
 *   ADXL345 VDD  -> 3.3 V
 *   ADXL345 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -lgpiod -lm
 *
 * Run:
 *   ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- ADXL345 register map ---- */
#define ADXL345_DEVID        0x00
#define ADXL345_BW_RATE      0x2C
#define ADXL345_POWER_CTL    0x2D
#define ADXL345_INT_ENABLE   0x2E
#define ADXL345_INT_MAP      0x2F
#define ADXL345_INT_SOURCE   0x30
#define ADXL345_DATA_FORMAT  0x31
#define ADXL345_DATAX0       0x32
#define ADXL345_FIFO_CTL     0x38
#define ADXL345_FIFO_STATUS  0x39

#define ADXL345_DEVID_VAL    0xE5
#define ADXL345_I2C_ADDR     0x53

/* ---- GPIO / I2C ---- */
#define I2C_BUS             "/dev/i2c-1"
#define GPIO_CHIP           "gpiochip4"   /* BCM GPIO on Pi 4/5 */
#define GPIO_LINE_OFFSET    17            /* BCM 17 */

