        fprintf(stderr, "Cannot request falling-edge events on GPIO %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started.  Press Ctrl+C to exit.\n");

    struct timespec last_sample = {0, 0};
    struct timespec now;
    int   freefall_active = 0;
    int   first_sample    = 1;
    int16_t x, y, z;

