            if (mag < FREEFALL_THRESHOLD) {
                if (!freefall_active) {
                    freefall_active = 1;
                    clock_gettime(CLOCK_MONOTONIC, &last_sample);
                    printf("Free-fall detected — logging started.\n");
                }
                if (freefall_active) {
                    clock_gettime(CLOCK_MONOTONIC, &now);
                    long ts_ms = (now.tv_sec - last_sample.tv_sec) * 1000L
                               + (now.tv_nsec - last_sample.tv_nsec) / 1000000L;
                    if (fprintf(g_log_file, "%ld,%d,%d,%d\n",
                                ts_ms, (int)(xg * 1000.0f),
                                (int)(yg * 1000.0f), (int)(zg * 1000.0f)) < 0) {
                        fprintf(stderr, "CSV write failed: %s\n", strerror(errno));
                        break;
                    }
                    fflush(g_log_file);
                }
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

