/*
 * LSM6DSR IMU fall-detection logger for Raspberry Pi 3 Model B+
 * Uses libi2c-dev (Linux i2c-dev interface) — no wiringPi dependency.
 *
 * Wiring:
 *   LSM6DSR SDA  -> GPIO2 (BCM 2, I2C1 SDA)
 *   LSM6DSR SCL  -> GPIO3 (BCM 3, I2C1 SCL)
 *   LSM6DSR VDD  -> 3.3 V
 *   LSM6DSR GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o lsm6dsr_fall lsm6dsr_fall.c -lm
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM6DSR constants (verified against datasheet) ---- */
#define LSM6DSR_ADDR        0x6A
#define WHO_AM_I_REG        0x0F
#define WHO_AM_I_VAL        0x6A
#define CTRL1_XL            0x10
#define CTRL2_G             0x11
#define OUTX_L_G            0x22
#define OUTX_H_G            0x23
#define OUTY_L_G            0x24
#define OUTY_H_G            0x25
#define OUTZ_L_G            0x26
#define OUTZ_H_G            0x27
#define OUTX_L_XL           0x28
#define OUTX_H_XL           0x29
#define OUTY_L_XL           0x2A
#define OUTY_H_XL           0x2B
#define OUTZ_L_XL           0x2C
#define OUTZ_H_XL           0x2D

#define ACCEL_SCALE_2G      0.061f   /* mg/LSB */
#define GYRO_SCALE_250DPS   8.75f    /* mdps/LSB */
#define FALL_THRESHOLD_G    0.2f
#define IMPACT_THRESHOLD_G  2.5f
#define IMPACT_WINDOW_S     1.0
#define SAMPLE_PERIOD_US    10000    /* 10 ms ≈ 104 Hz */
#define LOG_FILE            "motion_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

/* ---- Fall-detection state machine ---- */
typedef enum {
    STATE_IDLE,
    STATE_FREEFALL,
    STATE_IMPACT
} fall_state_t;

static fall_state_t g_state = STATE_IDLE;
static struct timespec g_freefall_start;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_lsm6dsr(int fd)
{
    uint8_t who;
    if (i2c_read_burst(fd, WHO_AM_I_REG, &who, 1) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }

    /* Accel: ±2 g, 104 Hz ODR, BW 400 Hz → 0x80 | 0x40 | 0x00 = 0xC0 */
    if (i2c_write_reg(fd, CTRL1_XL, 0xC0) < 0)
        return -1;
    /* Gyro: ±250 dps, 104 Hz ODR → 0x80 | 0x40 | 0x00 = 0xC0 */
    if (i2c_write_reg(fd, CTRL2_G, 0xC0) < 0)
        return -1;

    return 0;
}

/* ---- Read one sample ---- */
static int read_imu(int fd, float *ax, float *ay, float *az,
                    float *gx, float *gy, float *gz)
{
    uint8_t xl[6], gy[6];

    if (i2c_read_burst(fd, OUTX_L_XL, xl, 6) < 0)
        return -1;
    if (i2c_read_burst(fd, OUTX_L_G, gy, 6) < 0)
        return -1;

    int16_t rx = (int16_t)((xl[1] << 8) | xl[0]);
    int16_t ry = (int16_t)((xl[3] << 8) | xl[2]);
    int16_t rz = (int16_t)((xl[5] << 8) | xl[4]);
    int16_t gx_s = (int16_t)((gy[1] << 8) | gy[0]);
    int16_t gy_s = (int16_t)((gy[3] << 8) | gy[2]);
    int16_t gz_s = (int16_t)((gy[5] << 8) | gy[4]);

    *ax = (float)rx * ACCEL_SCALE_2G / 1000.0f;
    *ay = (float)ry * ACCEL_SCALE_2G / 1000.0f;
    *az = (float)rz * ACCEL_SCALE_2G / 1000.0f;
    *gx = (float)gx_s * GYRO_SCALE_250DPS / 1000.0f;
    *gy = (float)gy_s * GYRO_SCALE_250DPS / 1000.0f;
    *gz = (float)gz_s * GYRO_SCALE_250DPS / 1000.0f;
    return 0;
}

/* ---- Fall-detection logic ---- */
static void detect_fall(float ax, float ay, float az)
{
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    switch (g_state) {
    case STATE_IDLE:
        if (mag < FALL_THRESHOLD_G) {
            g_state = STATE_FREEFALL;
            clock_gettime(CLOCK_MONOTONIC, &g_freefall_start);
        }
        break;
    case STATE_FREEFALL:
        if (mag > IMPACT_THRESHOLD_G) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double dt = (now.tv_sec - g_freefall_start.tv_sec)
                       + (now.tv_nsec - g_freefall_start.tv_nsec) / 1e9;
            if (dt <= IMPACT_WINDOW_S) {
                g_state = STATE_IMPACT;
                printf("Impact detected!\n");
            }
        }
        break;
    case STATE_IMPACT:
        /* Stay in IMPACT until we re-enter FREEFALL */
        if (mag < FALL_THRESHOLD_G) {
            g_state = STATE_FREEFALL;
            clock_gettime(CLOCK_MONOTONIC, &g_freefall_start);
        }
        break;
    }
}

/* ---- Logging ---- */
static void log_data(FILE *f, float ax, float ay, float az,
                     float gx, float gy, float gz)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(f, "%ld.%09ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            ax, ay, az, gx, gy, gz);
    fflush(f);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM6DSR init failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log, "# timestamp_s,ax_g,ay_g,az_g,gx_dps,gy_dps,gz_dps\n");
    fflush(g_log);

    printf("LSM6DSR fall-detection running. Press Ctrl+C to stop.\n");

    while (g_running) {
        float ax, ay, az, gx, gy, gz;
        if (read_imu(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        detect_fall(ax, ay, az);
        log_data(g_log, ax, ay, az, gx, gy, gz);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

