/*
 * ADIS16266 Gyroscope SPI Logger for Raspberry Pi 3 Model B+
 * Uses the Linux spidev interface (no wiringPi).
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (BCM 8, SPI CE0)
 *   ADIS16266 SCLK-> GPIO11 (BCM 11, SPI SCLK)
 *   ADIS16266 DIN -> GPIO10 (BCM 10, SPI MOSI)
 *   ADIS16266 DOUT-> GPIO9  (BCM 9,  SPI MISO)
 *   ADIS16266 VDD -> 3.3 V
 *   ADIS16266 GND -> GND
 *
 * Build: gcc -O2 -Wall -o gyro_log gyro_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_3  /* CPOL=1, CPHA=1 */

#define ADIS16266_WHO_AM_I  0x01
#define ADIS16266_GLOB_CMD  0x08
#define ADIS16266_GYRO_OUT  0x04
#define ADIS16266_SCALE     0.0305f   /* deg/sec per LSB */

#define SAMPLE_PERIOD_US   10000U    /* 10 ms */
#define LOG_FILE_NAME      "gyro_log.csv"

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

/* Open the spidev device and configure SPI mode/bits/speed. */
static int spi_open(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }
    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * ADIS16266 SPI transactions are 16-bit big-endian.
 *   Byte 0: [7:1] command/register address, [0]: R/W bit (1 = read).
 *   Byte 1: dummy (clocks out the response).
 *   Byte 2: dummy (clocks out the response).
 *   Byte 3: dummy (clocks out the response).
 *   Response: 16-bit big-endian data in bytes 1-3.
 */
static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register (address | 0x80 = read command). */
static int adis_read_reg(uint8_t addr, uint16_t *out)
{
    uint8_t tx[4] = { (uint8_t)(addr | 0x80), 0x00, 0x00, 0x00 };
    uint8_t rx[4] = { 0 };

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    *out = ((uint16_t)rx[1] << 8) | rx[2];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gyroscope data                                                      */
/* ------------------------------------------------------------------ */
static int read_gyro_data(float *gyro_x, float *gyro_y, float *gyro_z)
{
    uint16_t raw_x, raw_y, raw_z;

    if (adis_read_reg(ADIS16266_GYRO_OUT, &raw_x) < 0) return -1;
    if (adis_read_reg(ADIS16266_GYRO_OUT, &raw_y) < 0) return -1;
    if (adis_read_reg(ADIS16266_GYRO_OUT, &raw_z) < 0) return -1;

    *gyro_x = (float)raw_x * ADIS16266_SCALE;
    *gyro_y = (float)raw_y * ADIS16266_SCALE;
    *gyro_z = (float)raw_z * ADIS16266_SCALE;
    return 0;
}

