        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,gyro_x,gyro_y,gyro_z\n");
        fflush(g_log_fp);
    }

    /* Verify device identity */
    uint16_t whoami = 0;
    if (adis_read_reg(ADIS16266_WHO_AM_I, &whoami) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (whoami != 0x0166) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x0166.\n", whoami);
        cleanup();
        return EXIT_FAILURE;
