/*
 * GY-50 L3G4200D Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   VCC  -> 3.3 V (Pin 1)
 *   GND  -> GND  (Pin 9)
 *   SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -o gyro_log gyro_log.c -lm
 * Run:    ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D register definitions (verified against datasheet) ---- */
#define L3G4200D_WHO_AM_I   0x0F
#define L3G4200D_WHO_AM_I_VAL 0xD3
#define L3G4200D_CTRL_REG1  0x20
#define L3G4200D_CTRL_REG4  0x23
#define L3G4200D_OUT_X_L    0x28
#define L3G4200D_OUT_X_H    0x29
#define L3G4200D_OUT_Y_L    0x2A
#define L3G4200D_OUT_Y_H    0x2B
#define L3G4200D_OUT_Z_L    0x2C
#define L3G4200D_OUT_Z_H    0x2D

/* CTRL_REG1: 0x0F = 1 kHz ODR, all axes enabled, normal mode */
#define L3G4200D_CTRL_REG1_VAL 0x0F
/* CTRL_REG4: 0x00 = 8.75 mdps/LSB, continuous update, no self-test */
#define L3G4200D_CTRL_REG4_VAL 0x00

/* Sensitivity for 8.75 mdps/LSB: 1 / 114.285 */
#define GYRO_SCALE  (1.0 / 114.285)

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define LOG_FILE       "gyro_log.csv"
#define SAMPLE_PERIOD  10000   /* microseconds (10 ms) */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an L3G4200D register; retry on transient errors.   */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2)
            return 0;
        usleep(1000);
    }
    return -1;
}

/* Read a byte from an L3G4200D register; retry on transient errors.  */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, value, 1) == 1)
                return 0;
        }
        usleep(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int gyro_init(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg(fd, L3G4200D_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register (I2C bus error or sensor absent).\n");
        return -1;
    }
    if (who_am_i != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, L3G4200D_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg(fd, L3G4200D_CTRL_REG1, L3G4200D_CTRL_REG1_VAL) != 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1.\n");
        return -1;
    }
    if (i2c_write_reg(fd, L3G4200D_CTRL_REG4, L3G4200D_CTRL_REG4_VAL) != 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG4.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int gyro_read(int fd, float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg(fd, L3G4200D_OUT_X_L, &xl) != 0) return -1;
    if (i2c_read_reg(fd, L3G4200D_OUT_X_H, &xh) != 0) return -1;
    if (i2c_read_reg(fd, L3G4200D_OUT_Y_L, &yl) != 0) return -1;
    if (i2c_read_reg(fd, L3G4200D_OUT_Y_H, &yh) != 0) return -1;
    if (i2c_read_reg(fd, L3G4200D_OUT_Z_L, &zl) != 0) return -1;
    if (i2c_read_reg(fd, L3G4200D_OUT_Z_H, &zh) != 0) return -1;

    int16_t rx = (int16_t)((xh << 8) | xl);
    int16_t ry = (int16_t)((yh << 8) | yl);
    int16_t rz = (int16_t)((zh << 8) | zl);

    *x = (float)rx * GYRO_SCALE;
    *y = (float)ry * GYRO_SCALE;
    *z = (float)rz * GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gyro_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "w");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_fp, "Timestamp,X,Y,Z\n") < 0) {
        perror("fprintf(header)");
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(g_log_fp);

    printf("Logging gyroscope data to %s (Ctrl+C to stop)...\n", LOG_FILE);

    while (g_running) {
        float x, y, z;
        if (gyro_read(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        if (fprintf(g_log_fp, "%ld.%09ld,%.3f,%.3f,%.3f\n",
                    (long)ts.tv_sec, ts.tv_nsec, x, y, z) < 0) {
            perror("fprintf(data)");
            break;
        }
        fflush(g_log_fp);

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

