    if (i2c_read_reg(fd, L3G4200D_OUT_Y_L, &yl) != 0) return -1;
    if (i2c_read_reg(fd, L3G4200D_OUT_Y_H, &yh) != 0) return -1;
    if (i2c_read_reg(fd, L3G4200D_OUT_Z_L, &zl) != 0) return -1;
    if (i2c_read_reg(fd, L3G4200D_OUT_Z_H, &zh) != 0) return -1;

    int16_t rx = (int16_t)((xh << 8) | xl);
    int16_t ry = (int16_t)((yh << 8) | yl);
    int16_t rz = (int16_t)((zh << 8) | zl);

    *x = (float)rx * GYRO_SCALE;
    *y = (float)ry * GYRO_SCALE;
    *z = (float)rz * GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gyro_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "w");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_fp, "Timestamp,X,Y,Z\n") < 0) {
        perror("fprintf(header)");
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(g_log_fp);

    printf("Logging gyroscope data to %s (Ctrl+C to stop)...\n", LOG_FILE);

    while (g_running) {
        float x, y, z;
        if (gyro_read(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        if (fprintf(g_log_fp, "%ld.%09ld,%.3f,%.3f,%.3f\n",
                    (long)ts.tv_sec, ts.tv_nsec, x, y, z) < 0) {
            perror("fprintf(data)");
            break;
        }
        fflush(g_log_fp);

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

