#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME     "flame_events.log"
#define POLL_INTERVAL_US  500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a timestamped flame-event line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_flame_event(FILE *fp, int flame_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s – Flame detected: %s\n",
                timestamp, flame_detected ? "YES" : "NO") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO17 as input with internal pull-up --- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", FLAME_SENSOR_GPIO);
        goto cleanup_gpio;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        goto cleanup_gpio;
    }

    /* --- Open log file in append mode --- */
    fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        goto cleanup_gpio;
    }

    printf("Flame sensor monitoring started on GPIO%d.\n", FLAME_SENSOR_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int level = gpioRead(FLAME_SENSOR_GPIO);

        if (level == PI_BAD_GPIO) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n",
                    FLAME_SENSOR_GPIO);
            if (log_flame_event(fp, 0) != 0) {
                fprintf(stderr, "Failed to log error event.\n");
            }
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* KY-026 open-collector output: LOW = flame detected */
        int flame_detected = (level == 0) ? 1 : 0;

        if (log_flame_event(fp, flame_detected) != 0) {
            fprintf(stderr, "Failed to log flame event.\n");
        }

        if (flame_detected) {
            printf("FLAME DETECTED!\n");
            fflush(stdout);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

    /* --- Clean resource release --- */
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
    }

cleanup_gpio:
    gpioTerminate();
    return ret;
}

