#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x50
#define REG_X_LSB      0x02
#define REG_X_MSB      0x03
#define REG_Y_LSB      0x04
#define REG_Y_MSB      0x05
#define REG_Z_LSB      0x06
#define REG_Z_MSB      0x07
#define REG_STATUS     0x00
#define STATUS_ERROR   0x01
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read (reg 0x%02X, %zu bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t status = 0;
    if (i2c_read_reg8(fd, REG_STATUS, &status) < 0)
        return -1;
    if (status & STATUS_ERROR) {
        fprintf(stderr, "Sensor reports error status 0x%02X\n", status);
        return -1;
    }

    uint8_t raw[6];
    if (i2c_read_block(fd, REG_X_LSB, raw, sizeof(raw)) < 0)
        return -1;

    *x = (int16_t)((raw[1] << 8) | raw[0]);
    *y = (int16_t)((raw[3] << 8) | raw[2]);
    *z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("vibration_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open vibration_log.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "Timestamp,X,Y,Z\n");

    printf("Logging D7S-0001 vibration data to vibration_log.csv (Ctrl+C to stop)\n");

    while (g_running) {
        int16_t x = 0, y = 0, z = 0;

        if (read_sensor_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Skipping sample due to read error\n");
        } else {
            char ts[32];
            get_iso8601_timestamp(ts, sizeof(ts));
            fprintf(g_log_fp, "%s,%d,%d,%d\n", ts, x, y, z);
            fflush(g_log_fp);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

