/*
 * Metal detector using Adafruit LIS3MDL (Triple Axis Magnetometer)
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C (SDA=GPIO2/BCM3, SCL=GPIO3/BCM5), address 0x1E
 * Log:    magnetic_log.txt (one sample per line: X,Y,Z)
 * Alert:  > 800 mG total field magnitude
 *
 * Build:  gcc -O2 -Wall -Wextra -o metal_detector metal_detector.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LIS3MDL constants (verified against Adafruit breakout / datasheet) ---- */
#define LIS3MDL_ADDR        0x1E
#define LIS3MDL_WHO_AM_I    0x0F
#define LIS3MDL_WHO_AM_I_VAL 0x3D
#define LIS3MDL_CTRL_REG1   0x20
#define LIS3MDL_CTRL_REG2   0x21
#define LIS3MDL_CTRL_REG3   0x22
#define LIS3MDL_CTRL_REG4   0x23
#define LIS3MDL_CTRL_REG5   0x24
#define LIS3MDL_OUT_X_L     0x28
#define LIS3MDL_OUT_X_H     0x29
#define LIS3MDL_OUT_Y_L     0x2A
#define LIS3MDL_OUT_Y_H     0x2B
#define LIS3MDL_OUT_Z_L     0x2C
#define LIS3MDL_OUT_Z_H     0x2D

#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "magnetic_log.txt"
#define SAMPLE_PERIOD_US   100000   /* 10 Hz */
#define METAL_THRESHOLD_MG 800.0f
#define SENSITIVITY_MG_LSB  0.146f   /* ±4 gauss, 0.146 mG per LSB */
#define MAX_RETRIES        3

/* Calibration constants (example values; replace with your own) */
static const float X_OFFSET = 0.0f;
static const float Y_OFFSET = 0.0f;
static const float Z_OFFSET = 0.0f;
static const float X_SCALE  = 1.0f;
static const float Y_SCALE  = 1.0f;
static const float Z_SCALE  = 1.0f;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_lis3mdl(int fd)
{
    uint8_t who;
    if (i2c_read_block(fd, LIS3MDL_WHO_AM_I, &who, 1) != 0)
        return -1;
    if (who != LIS3MDL_WHO_AM_I_VAL) {
        fprintf(stderr, "[LIS3MDL] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LIS3MDL_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: temp enable, X/Y/Z axes enabled, 10 Hz ODR */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG1, 0x70) != 0)
        return -1;
    /* CTRL_REG2: full-scale ±4 gauss (default) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG2, 0x00) != 0)
        return -1;
    /* CTRL_REG3: continuous-conversion mode (default) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG3, 0x00) != 0)
        return -1;
    /* CTRL_REG4: Z-axis high-performance mode (default) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG4, 0x0C) != 0)
        return -1;
    /* CTRL_REG5: no FIFO, no interrupt */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG5, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, LIS3MDL_OUT_X_L, raw, 6) != 0)
        return -1;

    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);

    *x = ((float)rx - X_OFFSET) * X_SCALE;
    *y = ((float)ry - Y_OFFSET) * Y_SCALE;
    *z = ((float)rz - Z_OFFSET) * Z_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(FILE *f, float x, float y, float z)
{
    fprintf(f, "%.3f,%.3f,%.3f\n", x, y, z);
    fflush(f);
}

/* ------------------------------------------------------------------ */
static void metal_alert(float x, float y, float z, float mag_mg)
{
    (void)x; (void)y; (void)z;
    fprintf(stderr, "[ALERT] Metal detected! |B| = %.2f mG\n", mag_mg);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", LIS3MDL_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int ok = 0;
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            ok = 1;
            break;
        }
        fprintf(stderr, "LIS3MDL init attempt %d/%d failed\n", attempt, MAX_RETRIES);
        usleep(1000000);
    }
    if (!ok) {
        fprintf(stderr, "LIS3MDL initialization failed after %d attempts\n", MAX_RETRIES);
        cleanup();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "w");
    if (!g_log) {
        fprintf(stderr, "fopen %s failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Metal detector running. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "[WARN] read_magnetometer failed; retrying next cycle\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float mag_mg = sqrtf(x * x + y * y + z * z) * SENSITIVITY_MG_LSB;
        log_sample(g_log, x, y, z);

        if (mag_mg > METAL_THRESHOLD_MG)
            metal_alert(x, y, z, mag_mg);

        usleep(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

