#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define LOG_FILE        "vibration_log.txt"
#define SAMPLE_PERIOD_US 100000
#define MAX_RETRIES     3

/* ADXL354B register addresses */
#define REG_STATUS      0x02
#define REG_XDATA_L     0x08
#define REG_XDATA_H     0x09
#define REG_YDATA_L     0x0A
#define REG_YDATA_H     0x0B
#define REG_ZDATA_L     0x0C
#define REG_ZDATA_H     0x0D
#define REG_TEMP_L      0x0E
#define REG_TEMP_H      0x0F
#define REG_POWER_CTL   0x1F
#define REG_RESET       0x1E
#define REG_PARTID      0x0C

#define ADXL354B_PARTID 0xAD
#define ADXL354B_RESET  0x52

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl354b_read_register(int fd, uint8_t reg, uint8_t *val) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(fd, tx, rx, 2) == 0) {
            *val = rx[1];
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int adxl354b_write_register(int fd, uint8_t reg, uint8_t val) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), val };
    uint8_t rx[2] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(fd, tx, rx, 2) == 0) {
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int adxl354b_read_acceleration(int fd, int32_t *x, int32_t *y, int32_t *z) {
    uint8_t tx[7] = { (uint8_t)(REG_XDATA_L | 0xC0), 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 };
    uint8_t rx[7] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(fd, tx, rx, 7) == 0) {
            *x = (int32_t)((rx[2] << 16) | (rx[1] << 8) | rx[0]) >> 4;
            *y = (int32_t)((rx[5] << 16) | (rx[4] << 8) | rx[3]) >> 4;
            *z = (int32_t)((rx[6] << 16) | (rx[5] << 8) | rx[4]) >> 4;
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int adxl354b_reset(int fd) {
    if (adxl354b_write_register(fd, REG_RESET, ADXL354B_RESET) != 0) {
        fprintf(stderr, "Failed to write reset register\n");
        return -1;
    }
    usleep(1000);

    uint8_t partid = 0;
    if (adxl354b_read_register(fd, REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != ADXL354B_PARTID) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354B_PARTID);
        return -1;
    }
    return 0;
}

static int adxl354b_init(int fd) {
    if (adxl354b_reset(fd) != 0) {
        return -1;
    }

    if (adxl354b_write_register(fd, REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to clear power control register\n");
        return -1;
    }
    usleep(1000);

    uint8_t status = 0;
    for (int i = 0; i < 100; i++) {
        if (adxl354b_read_register(fd, REG_STATUS, &status) != 0) {
            fprintf(stderr, "Failed to read status register\n");
            return -1;
        }
        if ((status & 0x01) != 0) {
            break;
        }
        usleep(1000);
    }
    if ((status & 0x01) == 0) {
        fprintf(stderr, "Sensor not stable (STABLE bit not set)\n");
        return -1;
    }

    if (adxl354b_write_register(fd, REG_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Failed to set RUN bit\n");
        return -1;
    }
    usleep(1000);
    return 0;
}

static void log_data(FILE *fp, int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(g_spi_fd);
        return 1;
    }

    if (adxl354b_init(g_spi_fd) != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        close(g_spi_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_spi_fd);
        return 1;
    }

    printf("ADXL354B vibration logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int32_t x, y, z;
        if (adxl354b_read_acceleration(g_spi_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
    }
    return 0;
}

