#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses (16-bit read protocol) */
#define ADIS16362_REG_XGYRO_OUT  0x04
#define ADIS16362_REG_YGYRO_OUT  0x06
#define ADIS16362_REG_ZGYRO_OUT  0x08
#define ADIS16362_REG_XACCEL_OUT 0x0A
#define ADIS16362_REG_YACCEL_OUT 0x0C
#define ADIS16362_REG_ZACCEL_OUT 0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000  /* 1 MHz */
#define SPI_FLAGS   0x00000007 /* Mode 3: CPOL=1, CPHA=1, active-low CE */

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE  0.05f   /* degrees/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

/* Sampling interval (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16362 using pigpio's SPI        */
/* 16-bit read protocol: send address byte (MSB=1) + dummy byte,       */
/* then read the 16-bit data word on the next transfer.               */
/* ------------------------------------------------------------------ */
static int read_register16(int handle, uint8_t reg, int16_t *out)
{
    char tx[2];
    char rx[2];

    /* Phase 1: send read command (address + R/W bit) */
    tx[0] = (char)(reg | 0x80); /* MSB = 1 for read */
    tx[1] = 0x00;               /* dummy byte */

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read command failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* Small delay to let the sensor clock out the data */
    gpioDelay(20);

    /* Phase 2: read the 16-bit data word */
    tx[0] = 0x00;
    tx[1] = 0x00;

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI data read failed for reg 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all six sensor channels and convert to engineering units      */
/* ------------------------------------------------------------------ */
static int read_imu_data(int handle,
                         float *x_gyro, float *y_gyro, float *z_gyro,
                         float *x_accel, float *y_accel, float *z_accel)
{
    int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;

    if (read_register16(handle, ADIS16362_REG_XGYRO_OUT, &raw_gx) != 0) return -1;
    if (read_register16(handle, ADIS16362_REG_YGYRO_OUT, &raw_gy) != 0) return -1;
    if (read_register16(handle, ADIS16362_REG_ZGYRO_OUT, &raw_gz) != 0) return -1;
    if (read_register16(handle, ADIS16362_REG_XACCEL_OUT, &raw_ax) != 0) return -1;
    if (read_register16(handle, ADIS16362_REG_YACCEL_OUT, &raw_ay) != 0) return -1;
    if (read_register16(handle, ADIS16362_REG_ZACCEL_OUT, &raw_az) != 0) return -1;

    *x_gyro = (float)raw_gx * GYRO_SCALE;
    *y_gyro = (float)raw_gy * GYRO_SCALE;
    *z_gyro = (float)raw_gz * GYRO_SCALE;
    *x_accel = (float)raw_ax * ACCEL_SCALE;
    *y_accel = (float)raw_ay * ACCEL_SCALE;
    *z_accel = (float)raw_az * ACCEL_SCALE;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data record to the CSV file                                 */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x_gyro, float y_gyro, float z_gyro,
                    float x_accel, float y_accel, float z_accel)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                x_gyro, y_gyro, z_gyro,
                x_accel, y_accel, z_accel) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — called on every exit path                                 */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, 1 MHz, Mode 3 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d baud, flags 0x%08X): %s\n",
                SPI_CHANNEL, SPI_BAUD, SPI_FLAGS, pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("imu_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file,
                "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(g_log_file);
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel;

        if (read_imu_data(g_spi_handle,
                          &x_gyro, &y_gyro, &z_gyro,
                          &x_accel, &y_accel, &z_accel) != 0) {
            fprintf(stderr, "IMU read error — skipping sample\n");
        } else {
            if (log_data(g_log_file, x_gyro, y_gyro, z_gyro,
                         x_accel, y_accel, z_accel) != 0) {
                fprintf(stderr, "Logging error — continuing\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

