        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file,
                "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(g_log_file);
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel;

        if (read_imu_data(g_spi_handle,
                          &x_gyro, &y_gyro, &z_gyro,
                          &x_accel, &y_accel, &z_accel) != 0) {
            fprintf(stderr, "IMU read error — skipping sample\n");
        } else {
            if (log_data(g_log_file, x_gyro, y_gyro, z_gyro,
                         x_accel, y_accel, z_accel) != 0) {
                fprintf(stderr, "Logging error — continuing\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

