    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input */
    ret = gpiod_line_request_input(line, "e18-d80nk-parking");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_message("Parking sensor monitoring started (GPIO17). Press Ctrl+C to exit.");

    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        /* E18-D80NK output is LOW when an obstacle is detected */
        if (value == 0) {
            log_message("Obstacle detected! Starting self-parking sequence.");
            /* Simulated self-parking routine */
            sleep(2);
            log_message("Self-parking sequence completed.");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    /* Clean up resources */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    log_message("Parking sensor monitoring stopped.");
    return EXIT_SUCCESS;
}

