/*
 * KY-032 IR obstacle-avoidance sensor poller for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT -> GPIO27 (physical pin 13)
 *   VCC         -> 3.3 V (physical pin 1)
 *   GND         -> GND  (physical pin 9)
 *
 * The KY-032 is an active-low output: 0 = obstacle detected, 1 = clear.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o ky032_poll ky032_poll.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./ky032_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read both KY-032 sensors in a single bulk transfer.
 * Returns 0 on success and fills *s1 and *s2 with the raw GPIO levels
 * (0 = obstacle detected, 1 = clear).  Returns -1 on error.
 */
static int read_sensors(int s1, int s2, int *s1_out, int *s2_out)
{
    int v1 = gpioRead(s1);
    if (v1 < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d (rc=%d)\n", s1, v1);
        return -1;
    }

    int v2 = gpioRead(s2);
    if (v2 < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d (rc=%d)\n", s2, v2);
        return -1;
    }

    *s1_out = v1;
    *s2_out = v2;
    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure sensor GPIOs as inputs --- */
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Allow the pull-up resistors to settle --- */
    gpioDelay(100000);  /* 100 ms */

    printf("KY-032 obstacle-avoidance poller started.\n");
    printf("  Sensor 1: GPIO%d (physical pin 11)\n", SENSOR1_GPIO);
    printf("  Sensor 2: GPIO%d (physical pin 13)\n", SENSOR2_GPIO);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = 0, s2 = 0;

        if (read_sensors(SENSOR1_GPIO, SENSOR2_GPIO, &s1, &s2) != 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* KY-032 is active-low: 0 = obstacle, 1 = clear */
        const char *s1_txt = (s1 == 0) ? "OBSTACLE" : "clear";
        const char *s2_txt = (s2 == 0) ? "OBSTACLE" : "clear";

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        if (t != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        } else {
            snprintf(ts, sizeof(ts), "unknown-time");
        }

        printf("[%s] Sensor 1: %s | Sensor 2: %s\n", ts, s1_txt, s2_txt);
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
    printf("pigpio terminated.\n");
    return EXIT_SUCCESS;
}

