code:
/*
 * ADIS16266 Gyroscope Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (SPI0 CE0, /dev/spidev0.0)
 *   ADIS16266 SCLK-> GPIO11 (SPI0 SCLK)
 *   ADIS16266 DOUT-> GPIO9  (SPI0 MISO)
 *   ADIS16266 DIN -> GPIO10 (SPI0 MOSI)
 *   ADIS16266 VDD -> 3.3 V
 *   ADIS16266 GND -> GND
 *
 * Build: gcc -O2 -Wall -o adis16266 adis16266.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SAMPLE_PERIOD   100000U    /* 100 ms in microseconds */
#define GYRO_SCALE      0.02f      /* deg/sec per LSB */

/* ADIS16266 register addresses (16-bit, MSB-first on the bus) */
#define REG_XGYRO_OUT   0x04
#define REG_YGYRO_OUT   0x06
#define REG_ZGYRO_OUT   0x08
#define REG_SMPL_PRD    0x36
#define REG_GLOB_CMD    0x68

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Open and configure the SPI device.
 * Returns fd >= 0 on success, -1 on failure.
 */
static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read a 16-bit register from the ADIS16266.
 * Returns 0 on success, -1 on SPI error.
 */
static int read_register(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint16_t)rx[1] << 8) | rx[2]);
    return 0;
}

/*
 * Write a 16-bit value to a 16-bit register on the ADIS16266.
 * Returns 0 on success, -1 on SPI error.
 */
static int write_register(int fd, uint8_t reg, uint16_t value)
{
    uint8_t tx[3] = { (uint8_t)(reg & 0x7F), (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE (reg 0x%02X write): %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Initialize the ADIS16266: set sample period to 1 ms (0x0001) and
 * clear the GLOB_CMD register to clear any pending errors.
 */
static int init_adis16266(int fd)
{
    if (write_register(fd, REG_SMPL_PRD, 0x0001) < 0) {
        fprintf(stderr, "Failed to set sample period\n");
        return -1;
    }
    if (write_register(fd, REG_GLOB_CMD, 0x0000) < 0) {
        fprintf(stderr, "Failed to clear GLOB_CMD\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = spi_open(SPI_DEVICE);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    if (init_adis16266(fd) < 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADIS16266 initialized. Reading gyro data every 100 ms (Ctrl+C to exit)...\n");

    while (g_running) {
        int16_t x_raw = 0, y_raw = 0, z_raw = 0;

        if (read_register(fd, REG_XGYRO_OUT, &x_raw) < 0 ||
            read_register(fd, REG_YGYRO_OUT, &y_raw) < 0 ||
            read_register(fd, REG_ZGYRO_OUT, &z_raw) < 0) {
            fprintf(stderr, "SPI read error — continuing\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        float x_rate = (float)x_raw * GYRO_SCALE;
        float y_rate = (float)y_raw * GYRO_SCALE;
        float z_rate = (float)z_raw * GYRO_SCALE;

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
        } else {
            printf("X: %8.2f deg/s  Y: %8.2f deg/s  Z: %8.2f deg/s  |  %ld.%03ld s\n",
                   x_rate, y_rate, z_rate,
                   (long)ts.tv_sec, ts.tv_nsec / 1000000L);
        }

