#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND on the breakout) */
#define LSM6DSR_ADDR 0x6A

/* LSM6DSR register addresses */
#define LSM6DSR_WHO_AM_I   0x0F
#define LSM6DSR_CTRL1_XL   0x10
#define LSM6DSR_CTRL2_G    0x11
#define LSM6DSR_OUTX_L_G   0x22
#define LSM6DSR_OUTX_L_XL  0x28

#define LSM6DSR_WHO_AM_I_VAL 0x6A

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C short read at reg 0x%02X: got %d of %u bytes\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    uint8_t whoami = 0;

    if (i2c_read_burst(handle, LSM6DSR_WHO_AM_I, &whoami, 1) != 0)
        return -1;

    if (whoami != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    /* Enable accelerometer: 12 Hz ODR, +/-2g full-scale */
    if (i2c_write_reg(handle, LSM6DSR_CTRL1_XL, 0x60) != 0)
        return -1;

    /* Enable gyroscope: 12 Hz ODR, 245 dps full-scale */
    if (i2c_write_reg(handle, LSM6DSR_CTRL2_G, 0x60) != 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t xl[6], g[6];

    if (i2c_read_burst(handle, LSM6DSR_OUTX_L_XL, xl, 6) != 0)
        return -1;
    if (i2c_read_burst(handle, LSM6DSR_OUTX_L_G, g, 6) != 0)
        return -1;

    *ax = (int16_t)((xl[1] << 8) | xl[0]);
    *ay = (int16_t)((xl[3] << 8) | xl[2]);
    *az = (int16_t)((xl[5] << 8) | xl[4]);
    *gx = (int16_t)((g[1]  << 8) | g[0]);
    *gy = (int16_t)((g[3]  << 8) | g[2]);
    *gz = (int16_t)((g[5]  << 8) | g[4]);

    return 0;
}

int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at addr 0x%02X: %d\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("%d,%d,%d,%d,%d,%d\n", ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }
        gpioDelay(100000); /* 100 ms */
    }

    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

