 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- FXOS8700 constants (verified against Adafruit breakout datasheet) ---- */
#define FXOS8700_I2C_ADDR        0x1F   /* SA0 tied to GND on breakout board */
#define FXOS8700_WHO_AM_I        0x0D
#define FXOS8700_WHO_AM_I_VAL    0xC7
#define FXOS8700_CTRL_REG1       0x2A
#define FXOS8700_CTRL_REG2       0x2B
#define FXOS8700_M_CTRL_REG1     0x5B
#define FXOS8700_M_CTRL_REG2     0x5C
#define FXOS8700_OUT_X_MSB_A     0x01   /* accel X MSB */
#define FXOS8700_OUT_X_MSB_M     0x33   /* mag X MSB  */

#define I2C_BUS                 "/dev/i2c-1"
#define SAMPLE_PERIOD_US        100000  /* 100 ms */
#define MAX_RETRIES             3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, val, 1) != 1)
        return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2)
        return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, buf, len) != (ssize_t)len)
        return -1;
    return 0;
}

/* ---- Sensor driver ---- */

typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t mag_x, mag_y, mag_z;
} sensor_data_t;

static int fxos8700_init(int fd)
{
    uint8_t whoami = 0;

    if (i2c_read_reg8(fd, FXOS8700_WHO_AM_I, &whoami) < 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register: %s\n",
                strerror(errno));
        return -1;
    }
    if (whoami != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                whoami, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2c_write_reg8(fd, FXOS8700_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: writing CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    /* Reset magnetometer */
    if (i2c_write_reg8(fd, FXOS8700_CTRL_REG2, 0x40) < 0) {
        fprintf(stderr, "Error: writing CTRL_REG2: %s\n", strerror(errno));
        return -1;
    }
    usleep(1000);

    /* Magnetometer: hybrid mode, OSR=1, auto-reset */
    if (i2c_write_reg8(fd, FXOS8700_M_CTRL_REG1, 0x1F) < 0) {
        fprintf(stderr, "Error: writing M_CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    /* Magnetometer: low noise, high performance */
    if (i2c_write_reg8(fd, FXOS8700_M_CTRL_REG2, 0x20) < 0) {
        fprintf(stderr, "Error: writing M_CTRL_REG2: %s\n", strerror(errno));
        return -1;
    }

    /* Active mode, 100 Hz ODR, accel range +/-2g */
    if (i2c_write_reg8(fd, FXOS8700_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error: writing CTRL_REG1 (active): %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

static int fxos8700_read(int fd, sensor_data_t *out)
{
    uint8_t buf[12];
    int16_t raw;

    if (i2c_read_block(fd, FXOS8700_OUT_X_MSB_A, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Error: I2C block read failed: %s\n", strerror(errno));
        return -1;
    }

    /* Accelerometer: 14-bit left-justified, shift right 2 to get 14-bit value */
    raw = (int16_t)((buf[0] << 8) | buf[1]);
    out->accel_x = raw >> 2;
    raw = (int16_t)((buf[2] << 8) | buf[3]);
    out->accel_y = raw >> 2;
    raw = (int16_t)((buf[4] << 8) | buf[5]);
    out->accel_z = raw >> 2;

    /* Magnetometer: 16-bit */
    raw = (int16_t)((buf[6] << 8) | buf[7]);
    out->mag_x = raw;
    raw = (int16_t)((buf[8] << 8) | buf[9]);
    out->mag_y = raw;
    raw = (int16_t)((buf[10] << 8) | buf[11]);
    out->mag_z = raw;

    return 0;
}

/* ---- Main ---- */

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, FXOS8700_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: ioctl I2C_SLAVE 0x%02X: %s\n",
                FXOS8700_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    if (fxos8700_init(fd) < 0) {
        fprintf(stderr, "Error: FXOS8700 initialization failed.\n");
        goto cleanup;
    }

    printf("FXOS8700 initialized. Reading data every 100 ms (Ctrl+C to exit)...\n");

    while (g_running) {
        sensor_data_t data;
        int retries = 0;

        do {
            if (fxos8700_read(fd, &data) == 0)
                break;
            retries++;
            usleep(10000);
        } while (retries < MAX_RETRIES && g_running);

        if (!g_running)
            break;

        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Error: FXOS8700 read failed after %d retries.\n",
                    MAX_RETRIES);
            continue;
        }

        printf("Accel X: %6d  Y: %6d  Z: %6d  |  Mag X: %6d  Y: %6d  Z: %6d\n",
               data.accel_x, data.accel_y, data.accel_z,
               data.mag_x, data.mag_y, data.mag_z);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

