/*
 * ADXL345 Tilt Monitor for Raspberry Pi 5
 * Reads acceleration data over I2C, evaluates tilt angle, and logs events
 * exceeding a 30.0-degree threshold to /var/log/tilt_events.log.
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   ADXL345 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   ADXL345 VDD -> 3.3 V
 *   ADXL345 GND -> GND
 *
 * Build: gcc -O2 -Wall -o tilt_monitor tilt_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ADXL345 register definitions ---- */
#define ADXL345_ADDRESS        0x53
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_DATAX0         0x32
#define ADXL345_DATA_FORMAT    0x31

/* ---- I2C bus and device ---- */
#define I2C_BUS                "/dev/i2c-1"
#define LOG_FILE               "/var/log/tilt_events.log"

/* ---- Tilt threshold (degrees) ---- */
#define TILT_THRESHOLD         30.0

/* ---- Sampling interval (microseconds) ---- */
#define SAMPLE_INTERVAL_US     100000  /* 100 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register                              */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes starting at `reg`                                 */
/* ------------------------------------------------------------------ */
static int adxl_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg ptr 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read the data bytes */
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd of %zu)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADXL345: standby -> set full resolution mode        */
/* ------------------------------------------------------------------ */
static int adxl345_init(int fd)
{
    /* Enter standby mode (clear measure bit) */
    if (adxl_write_reg(fd, ADXL345_POWER_CTL, 0x00) < 0)
        return -1;
    usleep(1000);

    /* Set full resolution mode (bit D3 = 1) */
    if (adxl_write_reg(fd, ADXL345_DATA_FORMAT, 0x08) < 0)
        return -1;

    /* Clear standby mode to begin measurement */
    if (adxl_write_reg(fd, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration data (6 bytes) and convert to g                  */
/* ------------------------------------------------------------------ */
static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (adxl_read_burst(fd, ADXL345_DATAX0, raw, sizeof(raw)) < 0)
        return -1;

    /* 10-bit left-justified two's-complement: shift right 6 */
    int16_t x_raw = (int16_t)((raw[1] << 8) | raw[0]) >> 6;
    int16_t y_raw = (int16_t)((raw[3] << 8) | raw[2]) >> 6;
    int16_t z_raw = (int16_t)((raw[5] << 8) | raw[4]) >> 6;

    /* Full resolution range ±4 g: 3.9 mg/LSB */
    const float scale = 0.0039f;
    *x = x_raw * scale;
    *y = y_raw * scale;
    *z = z_raw * scale;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute tilt angle from acceleration vector                        */
/* ------------------------------------------------------------------ */
static float calculate_tilt_angle(float x, float y, float z)
{
    /* Tilt angle in degrees */
    return atan2f(sqrtf(x * x + y * y), z) * 180.0f / (float)M_PI;
}

/* ------------------------------------------------------------------ */
/* Log a tilt event with timestamp                                     */
/* ------------------------------------------------------------------ */
static int log_tilt_event(float tilt_angle)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s - Tilt Angle: %.2f degrees\n", ts, tilt_angle);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put sensor back in standby mode before closing */
        if (g_i2c_fd >= 0)
            adxl_write_reg(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire ADXL345 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                ADXL345_ADDRESS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed (sensor may be absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 tilt monitor started. Sampling every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_US / 1000);

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error — continuing after 100 ms backoff.\n");
            usleep(100000);
            continue;
        }

        float tilt = calculate_tilt_angle(x, y, z);

        if (tilt > TILT_THRESHOLD) {
            printf("Tilt angle: %.2f degrees\n", tilt);
            if (log_tilt_event(tilt) < 0)
                fprintf(stderr, "Warning: failed to log tilt event.\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

