    fprintf(fp, "%s - Tilt Angle: %.2f degrees\n", ts, tilt_angle);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put sensor back in standby mode before closing */
        if (g_i2c_fd >= 0)
            adxl_write_reg(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire ADXL345 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                ADXL345_ADDRESS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed (sensor may be absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 tilt monitor started. Sampling every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_US / 1000);

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error — continuing after 100 ms backoff.\n");
            usleep(100000);
            continue;
        }

        float tilt = calculate_tilt_angle(x, y, z);

        if (tilt > TILT_THRESHOLD) {
            printf("Tilt angle: %.2f degrees\n", tilt);
            if (log_tilt_event(tilt) < 0)
                fprintf(stderr, "Warning: failed to log tilt event.\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

