#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_GPIO 17
#define WINDOW_DURATION_SEC 5
#define SAMPLE_INTERVAL_US 1000
#define PAUSE_BETWEEN_WINDOWS_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int parse_threshold(const char *arg, int *out) {
    char *endptr = NULL;
    long val = strtol(arg, &endptr, 10);
    if (endptr == arg || *endptr != '\0') {
        fprintf(stderr, "Error: threshold must be a non-negative integer.\n");
        return -1;
    }
    if (val < 0) {
        fprintf(stderr, "Error: threshold must be non-negative.\n");
        return -1;
    }
    *out = (int)val;
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int threshold;
    if (parse_threshold(argv[1], &threshold) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d (threshold=%d)...\n", SOUND_SENSOR_GPIO, threshold);
    fflush(stdout);

    while (running) {
        time_t start_time = time(NULL);
        if (start_time == (time_t)-1) {
            fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
            break;
        }

        int high_count = 0;
        int error_occurred = 0;

        while (running && (time(NULL) - start_time) < WINDOW_DURATION_SEC) {
            int level = gpioRead(SOUND_SENSOR_GPIO);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", SOUND_SENSOR_GPIO);
                error_occurred = 1;
                break;
            }
            if (level == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (error_occurred) {
            break;
        }

        time_t current_time = time(NULL);
        if (current_time == (time_t)-1) {
            fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
            break;
        }

        char time_buf[32];
        struct tm *tm_info = localtime(&current_time);
        if (tm_info == NULL) {
            fprintf(stderr, "Error: localtime() failed.\n");
            break;
        }
        if (strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", tm_info) == 0) {
            fprintf(stderr, "Error: strftime() failed.\n");
            break;
        }

        if (high_count > threshold) {
            printf("%s ALERT: %d high readings in %d seconds\n", time_buf, high_count, WINDOW_DURATION_SEC);
        } else {
            printf("%s Status: %d high readings in %d seconds\n", time_buf, high_count, WINDOW_DURATION_SEC);
        }
        fflush(stdout);

        if (running) {
            for (int i = 0; i < PAUSE_BETWEEN_WINDOWS_SEC && running; i++) {
                gpioDelay(1000000);
            }
        }
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

