/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two 12 V electric door locks driven by TIP120-driven 5 V active-HIGH
 * relay modules on the GPIO bus.  BCM 17 = Door A, BCM 27 = Door B.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define DOOR_A_PIN      17
#define DOOR_B_PIN      27
#define UNLOCK_DURATION 5          /* seconds */
#define CODE_LENGTH     6
#define LOG_FILE        "access_log.txt"
#define CHIP_NAME       "gpiochip4" /* BCM GPIO controller on Pi 4 */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int generate_code(int code[CODE_LENGTH])
{
    for (int i = 0; i < CODE_LENGTH; i++)
        code[i] = (rand() % 10) + 1;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_code(int code[CODE_LENGTH])
{
    char input[64];
    char *endptr;
    long val;

    printf("Enter the security code: ");
    fflush(stdout);

    if (fgets(input, sizeof(input), stdin) == NULL)
        return -1;

    /* Strip trailing newline */
    input[strcspn(input, "\r\n")] = '\0';

    errno = 0;
    val = strtol(input, &endptr, 10);
    if (errno != 0 || endptr == input || *endptr != '\0') {
        fprintf(stderr, "Invalid input. Please enter a numeric code.\n");
        return -1;
    }

    if (val < 100000 || val > 999999) {
        fprintf(stderr, "Code must be between 100000 and 999999.\n");
        return -1;
    }

    for (int i = 0; i < CODE_LENGTH; i++)
        code[i] = (int)(val / (long)pow(10, CODE_LENGTH - 1 - i)) % 10;

    return 0;
}

/* ------------------------------------------------------------------ */
static int compare_code(const int code1[CODE_LENGTH],
                        const int code2[CODE_LENGTH])
{
    for (int i = 0; i < CODE_LENGTH; i++)
        if (code1[i] != code2[i])
            return 0;
    return 1;
}

/* ------------------------------------------------------------------ */
static int log_access(const int code[CODE_LENGTH])
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d%d%d%d%d%d\n",
                timestamp,
                code[0], code[1], code[2],
                code[3], code[4], code[5]) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int unlock_doors(struct gpiod_line *line_a, struct gpiod_line *line_b)
{
    if (gpiod_line_set_value(line_a, 1) < 0) {
        perror("gpiod_line_set_value(Door A unlock)");
        return -1;
    }
    if (gpiod_line_set_value(line_b, 1) < 0) {
        perror("gpiod_line_set_value(Door B unlock)");
        (void)gpiod_line_set_value(line_a, 0); /* best-effort return */
        return -1;
    }

    sleep(UNLOCK_DURATION);

    if (gpiod_line_set_value(line_a, 0) < 0) {
        perror("gpiod_line_set_value(Door A lock)");
        return -1;
    }
    if (gpiod_line_set_value(line_b, 0) < 0) {
        perror("gpiod_line_set_value(Door B lock)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int code[CODE_LENGTH];
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() < 0)
        goto cleanup;

    srand((unsigned)time(NULL));

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name(" CHIP_NAME ")");
        goto cleanup;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        perror("gpiod_chip_get_line(Door A)");
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        perror("gpiod_chip_get_line(Door B)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(Door A)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(Door B)");
        goto cleanup;
    }

    printf("Door access control system started.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int code_input[CODE_LENGTH];

        if (generate_code(code) < 0) {
            fprintf(stderr, "Failed to generate code.\n");
            continue;
        }

        printf("Generated code: %d%d%d%d%d%d\n",
               code[0], code[1], code[2],
               code[3], code[4], code[5]);

        if (read_code(code_input) < 0) {
            if (!g_running)
                break;
            continue;
        }

        if (compare_code(code, code_input)) {
            printf("Access granted!\n");
            if (log_access(code) < 0)
                fprintf(stderr, "Warning: failed to log access.\n");
            if (unlock_doors(line_a, line_b) < 0)
                fprintf(stderr, "Warning: failed to unlock doors.\n");
        } else {
            printf("Access denied!\n");
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Ensure doors are locked on every exit path */
    if (line_a)
        (void)gpiod_line_set_value(line_a, 0);
    if (line_b)
        (void)gpiod_line_set_value(line_b, 0);

    if (line_a)
        gpiod_line_release(line_a);
    if (line_b)
        gpiod_line_release(line_b);
    if (chip)
        gpiod_chip_close(chip);

    printf("Door access control system stopped.\n");
    return rc;
}

