        goto cleanup;

    srand((unsigned)time(NULL));

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name(" CHIP_NAME ")");
        goto cleanup;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        perror("gpiod_chip_get_line(Door A)");
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        perror("gpiod_chip_get_line(Door B)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(Door A)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(Door B)");
        goto cleanup;
    }

    printf("Door access control system started.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int code_input[CODE_LENGTH];

        if (generate_code(code) < 0) {
            fprintf(stderr, "Failed to generate code.\n");
            continue;
        }

        printf("Generated code: %d%d%d%d%d%d\n",
               code[0], code[1], code[2],
               code[3], code[4], code[5]);

        if (read_code(code_input) < 0) {
            if (!g_running)
                break;
            continue;
        }

        if (compare_code(code, code_input)) {
            printf("Access granted!\n");
            if (log_access(code) < 0)
                fprintf(stderr, "Warning: failed to log access.\n");
            if (unlock_doors(line_a, line_b) < 0)
                fprintf(stderr, "Warning: failed to unlock doors.\n");
        } else {
            printf("Access denied!\n");
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Ensure doors are locked on every exit path */
    if (line_a)
        (void)gpiod_line_set_value(line_a, 0);
    if (line_b)
        (void)gpiod_line_set_value(line_b, 0);

    if (line_a)
        gpiod_line_release(line_a);
    if (line_b)
        gpiod_line_release(line_b);
    if (chip)
        gpiod_chip_close(chip);

    printf("Door access control system stopped.\n");
    return rc;
}

