#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_PIN 18
#define PORT 12345
#define LOG_FILE "frequency_log.txt"
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define PWM_DUTY 500
#define SAMPLE_INTERVAL_US 20000
#define PLAYBACK_DURATION_S 5

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int server_fd = -1;
static int client_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(2000);

    if (i2c_write_reg8(fd, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCL_FALLING, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDL_FALLING, 0x02) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_E0TTH, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_E0RTH, 0x0A) < 0) return -1;

    return 0;
}

static int read_touch_data(int fd, uint16_t *touch_data) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *touch_data = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int calculate_frequency(uint16_t touch_data) {
    if (touch_data == 0) return 0;
    return 1000 + (int)((touch_data & 0x0FFF) * 1000 / 4095);
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fclose(fp);
}

static void play_tone(int frequency, int duration_s) {
    if (frequency <= 0) return;
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioPWM(PWM_PIN, PWM_DUTY);
    sleep(duration_s);
    gpioPWM(PWM_PIN, 0);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, MPR121_SOFTRESET, 0x63);
        i2c_close(i2c_fd);
        i2c_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_fd = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPR121_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin %d as output\n", PWM_PIN);
        cleanup();
        return 1;
    }
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    gpioPWM(PWM_PIN, 0);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        cleanup();
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (running) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }

        char buffer[1024];
        ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (n < 0) {
            perror("recv");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        if (n == 0) {
            close(client_fd);
            client_fd = -1;
            continue;
        }
        buffer[n] = '\0';

        if (strncmp(buffer, "MOTION_DETECTED:MySecretKey", 23) == 0) {
            uint16_t touch_data;
            if (read_touch_data(i2c_fd, &touch_data) < 0) {
                fprintf(stderr, "Failed to read touch data\n");
            } else {
                int frequency = calculate_frequency(touch_data);
                log_frequency(frequency);
                play_tone(frequency, PLAYBACK_DURATION_S);
            }
        } else {
            fprintf(stderr, "Invalid command: %s\n", buffer);
        }

        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

