/*
 * LSM303DLHC Magnetometer → LED PWM brightness logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC SDA  → Pi GPIO2  (I2C bus 1 SDA, physical pin 3)
 *   LSM303DLHC SCL  → Pi GPIO3  (I2C bus 1 SCL, physical pin 5)
 *   LSM303DLHC VDD  → 3.3 V
 *   LSM303DLHC GND  → GND
 *   LED anode      → Pi GPIO17 (physical pin 11) via 330 Ω resistor
 *   LED cathode    → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mag_led mag_led.c -lpigpio -lrt
 * Run:
 *   sudo ./mag_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- LSM303DLHC magnetometer constants (datasheet) ---- */
#define LSM303_MAG_ADDR        0x1E   /* SA0 tied to GND */
#define LSM303_MAG_CTRL_REG1   0x20
#define LSM303_MAG_CTRL_REG2   0x21
#define LSM303_MAG_MR_REG_M    0x02
#define LSM303_MAG_OUT_X_H_M   0x03   /* first data register after MR */

#define I2C_BUS               "/dev/i2c-1"
#define LED_GPIO              17
#define PWM_RANGE             255
#define SAMPLE_PERIOD_US      100000  /* 100 ms */
#define LOG_FILE_PATH         "mag_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_magnetometer(int fd)
{
    /* CTRL_REG1: temp enable, ODR 80 Hz, normal mode */
    if (i2c_write_reg8(fd, LSM303_MAG_CTRL_REG1, 0x70) < 0)
        return -1;
    /* CTRL_REG2: full-scale +/- 4 gauss */
    if (i2c_write_reg8(fd, LSM303_MAG_CTRL_REG2, 0x00) < 0)
        return -1;
    /* MR_M: continuous-conversion mode */
    if (i2c_write_reg8(fd, LSM303_MAG_MR_REG_M, 0x00) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, float *z_magnitude)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, LSM303_MAG_OUT_X_H_M, raw, sizeof(raw)) < 0)
        return -1;

    /* LSM303DLHC magnetometer outputs X/Y/Z in little-endian pairs */
    int16_t z = (int16_t)((raw[4] << 8) | raw[5]);

    /* Convert to Gauss (gain +/- 4 gauss → 0.14 Gauss/LSB) */
    *z_magnitude = (float)z * 0.14f;
    return 0;
}

/* ------------------------------------------------------------------ */
static void set_led_brightness(float z_magnitude)
{
    /* Map Z magnitude to 0–255 range; positive Z → brighter */
    int brightness = (int)lroundf(fabsf(z_magnitude) * 10.0f);
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    if (brightness < 0)         brightness = 0;

    if (gpioPWM(LED_GPIO, brightness) < 0) {
        fprintf(stderr, "gpioPWM failed on GPIO %d\n", LED_GPIO);
    }
}

/* ------------------------------------------------------------------ */
static void log_data(float z_magnitude)
{
    if (!g_log_fp) return;
    fprintf(g_log_fp, "%.3f\n", z_magnitude);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303DLHC magnetometer not detected or init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioPWM(LED_GPIO, 0);

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE_PATH, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_PATH, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM303DLHC magnetometer → LED PWM logger running. Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        float z_magnitude = 0.0f;

        if (read_magnetometer(g_i2c_fd, &z_magnitude) == 0) {
            set_led_brightness(z_magnitude);
            log_data(z_magnitude);
        } else {
            fprintf(stderr, "Skipping sample due to I2C error.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

