/*
 * HMC5883L Hard-Iron Offset Magnetometer Reader for Raspberry Pi Zero W
 *
 * Uses the Linux i2c-dev interface (no deprecated wiringPi).
 * Build: gcc -O2 -Wall -o hmc5883l_offset hmc5883l_offset.c
 *
 * Wiring:
 *   HMC5883L VCC -> Pi 3V3 (Pin 1)
 *   HMC5883L GND -> Pi GND (Pin 9)
 *   HMC5883L SDA -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   HMC5883L SCL -> Pi GPIO3 / I2C1 SCL (Pin 5)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HMC5883L_ADDR  0x1E

/* HMC5883L register addresses */
#define HMC5883L_CONFIG_A   0x00
#define HMC5883L_CONFIG_B   0x01
#define HMC5883L_MODE       0x02
#define HMC5883L_DATA_X_MSB 0x03

#define NUM_SAMPLES 100
#define SAMPLE_PERIOD_MS 500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to an HMC5883L register; returns 0 on success, -1 on error. */
static int hmc_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read `len` bytes starting from `reg`; returns 0 on success, -1 on error. */
static int hmc_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Initialize the HMC5883L: continuous measurement mode, 8-average, 15 Hz. */
static int hmc_init(int fd)
{
    /* Config A: 8-average, 15 Hz, normal measurement */
    if (hmc_write_reg(fd, HMC5883L_CONFIG_A, 0x70) < 0)
        return -1;
    /* Config B: gain 1.3 Ga (0x20) */
    if (hmc_write_reg(fd, HMC5883L_CONFIG_B, 0x20) < 0)
        return -1;
    /* Mode: continuous */
    if (hmc_write_reg(fd, HMC5883L_MODE, 0x00) < 0)
        return -1;
    return 0;
}

/* Read raw X/Y/Z magnetic field data (6 bytes starting at 0x03). */
static int hmc_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (hmc_read_block(fd, HMC5883L_DATA_X_MSB, buf, 6) < 0)
        return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Maintain a running average of the last NUM_SAMPLES samples. */
static void update_offsets(int16_t x, int16_t y, int16_t z,
                           int16_t *ox, int16_t *oy, int16_t *oz,
                           int *idx, int16_t *buf)
{
    buf[*idx] = x;
    (*idx)++;
    if (*idx >= NUM_SAMPLES) *idx = 0;

    int32_t sx = 0, sy = 0, sz = 0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        sx += buf[i];
        sy += buf[i + NUM_SAMPLES];
        sz += buf[i + 2 * NUM_SAMPLES];
    }
    *ox = (int16_t)(sx / NUM_SAMPLES);
    *oy = (int16_t)(sy / NUM_SAMPLES);
    *oz = (int16_t)(sz / NUM_SAMPLES);
}

int main(void)
{
    int fd = -1;
    int16_t offsets[3] = {0, 0, 0};
    int buf[NUM_SAMPLES * 3];
    int idx = 0;
    int rc = EXIT_FAILURE;

    memset(buf, 0, sizeof(buf));

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the HMC5883L slave address */
    if (ioctl(fd, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                HMC5883L_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize sensor */
    if (hmc_init(fd) < 0) {
        fprintf(stderr, "HMC5883L initialization failed.\n");
        goto cleanup;
    }

    printf("HMC5883L initialized. Reading magnetic field data...\n");
    printf("Press Ctrl+C to exit.\n");

    struct timespec delay = {0, SAMPLE_PERIOD_MS * 1000000L};

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (hmc_read_raw(fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Failed to read raw data. Retrying...\n");
            nanosleep(&delay, NULL);
            continue;
        }

        update_offsets(raw_x, raw_y, raw_z,
                       &offsets[0], &offsets[1], &offsets[2],
                       &idx, buf);

        int16_t x = raw_x - offsets[0];
        int16_t y = raw_y - offsets[1];
        int16_t z = raw_z - offsets[2];

        printf("X: %6d  Y: %6d  Z: %6d\n", x, y, z);
