/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * Reads tri-axial acceleration data over I2C at ~10 ms intervals and
 * dumps the last 10 buffered samples on a rising edge of the INT1 pin
 * (BCM GPIO 23, physical pin 16).
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * Wiring:
 *   LSM303D SDA  -> Pi GPIO2  (physical pin 3,  I2C bus 1)
 *   LSM303D SCL  -> Pi GPIO3  (physical pin 5,  I2C bus 1)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *   LSM303D INT1 -> Pi GPIO23 (physical pin 16, active-high, rising edge)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D constants (verified against datasheet) ---- */
#define LSM303D_ADDR        0x19
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49
#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_OUT_X_L_A   0x28
#define LSM303D_INT1_CFG    0x30
#define LSM303D_INT1_THS    0x32
#define LSM303D_INT1_DURATION 0x33
#define LSM303D_CTRL_REG3   0x22
#define LSM303D_CTRL_REG5   0x24
#define LSM303D_CTRL_REG6   0x25
#define LSM303D_CTRL_REG7   0x26
#define LSM303D_CTRL_REG8   0x27

#define I2C_BUS            "/dev/i2c-1"
#define GPIO_CHIP          "gpiochip0"
#define GPIO_INT1_OFFSET   23          /* BCM GPIO 23, physical pin 16 */
#define BUFFER_SIZE        64
#define SAMPLE_PERIOD_US   10000       /* 10 ms */
#define THRESHOLD_MG       2000.0f
#define SENSITIVITY_MG_LSB  0.061f      /* mg per LSB at +/-2g, FS=0 */

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

static accel_sample_t accel_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D init ---- */
static int init_lsm303d(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, LSM303D_WHO_AM_I, &who_am_i) != 0)
        return -1;
    if (who_am_i != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 0x57 = 0b0101_0111
     *   ODR=50 Hz (bits[3:0]=0101), all axes enabled (bits[7:6]=11)
     */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x57) != 0)
        return -1;

    /* CTRL_REG4: 0x00 = +/-2g full-scale, high-resolution disabled */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG4, 0x00) != 0)
        return -1;

    /* CTRL_REG5: 0x00 = no self-test, no boot, no FIFO */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG5, 0x00) != 0)
        return -1;

    /* CTRL_REG6: 0x00 = no block data update, no SIM */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG6, 0x00) != 0)
        return -1;

    /* CTRL_REG7: 0x00 = no anti-alias filter, no low-power mode */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG7, 0x00) != 0)
        return -1;

    /* CTRL_REG8: 0x00 = no test mode, no high-resolution */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG8, 0x00) != 0)
        return -1;

    /* INT1_CFG: 0x24 = 0b00100100
     *   ZHIE=1, ZLIE=1, YHIE=1, YLIE=1, XHIE=1, XLIE=1 => any high
     */
    if (i2c_write_reg8(fd, LSM303D_INT1_CFG, 0x24) != 0)
        return -1;

    /* INT1_THS: threshold in mg / 0.0625 mg/LSB = 2000 mg / 0.0625 = 320 */
    uint8_t ths = (uint8_t)(THRESHOLD_MG / SENSITIVITY_MG_LSB);
    if (i2c_write_reg8(fd, LSM303D_INT1_THS, ths) != 0)
        return -1;

    /* INT1_DURATION: 0x00 = 1 sample duration (immediate) */
    if (i2c_write_reg8(fd, LSM303D_INT1_DURATION, 0x00) != 0)
        return -1;

    /* CTRL_REG3: 0x04 = 0b00000100
     *   SIM bit cleared, MD=10 (high-resolution mode)
     */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG3, 0x04) != 0)
        return -1;

    return 0;
}

/* ---- Read acceleration ---- */
static int read_acceleration(int fd, accel_sample_t *sample)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, LSM303D_OUT_X_L_A, raw, sizeof(raw)) != 0)
        return -1;

    /* LSM303D is little-endian: X/Y low byte first, Z low byte first */
    sample->x = (int16_t)((raw[1] << 8) | raw[0]);
    sample->y = (int16_t)((raw[3] << 8) | raw[2]);
    sample->z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ---- Buffer management ---- */
static void store_sample(const accel_sample_t *sample)
{
    accel_buffer[buffer_index] = *sample;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

/* ---- Dump last N samples ---- */
static void dump_samples(void)
{
    int start = (buffer_count < BUFFER_SIZE)
               ? 0
               : (buffer_index - buffer_count + BUFFER_SIZE) % BUFFER_SIZE;

    printf("--- Last %d samples ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        float x = accel_buffer[idx].x * SENSITIVITY_MG_LSB;
        float y = accel_buffer[idx].y * SENSITIVITY_MG_LSB;
        float z = accel_buffer[idx].z * SENSITIVITY_MG_LSB;
        printf("  [%d] X=%+7.2f  Y=%+7.2f  Z=%+7.2f  mg\n",
               i, x, y, z);
    }
    printf("--- End of samples ---\n");
    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_int1_line) {
        gpiod_line_release(g_int1_line);
        g_int1_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer: clear MD bit in CTRL_REG3 */
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG3, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize LSM303D */
    if (init_lsm303d(g_i2c_fd) != 0) {
        fprintf(stderr, "LSM303D initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }
    g_int1_line = gpiod_chip_get_line(g_chip, GPIO_INT1_OFFSET);
    if (!g_int1_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_rising_edge_events(g_int1_line, "lsm303d_mon") < 0) {
        perror("gpiod_line_request_rising_edge_events");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D monitoring started (INT1=BCM23, threshold=%.1f mg).\n",
           THRESHOLD_MG);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        accel_sample_t sample;
        if (read_acceleration(g_i2c_fd, &sample) != 0) {
            fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        store_sample(&sample);

        /* Check for rising edge on INT1 */
        if (gpiod_line_event_wait(g_int1_line, NULL) == 1) {
            struct gpiod_line_event ev;
            if (gpiod_line_event_read(g_int1_line, &ev) == 0) {
                if (ev.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    dump_samples();
                }
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

