#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS       500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_solenoid(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, state=%d) failed\n", pin, state);
        return -1;
    }
    return 0;
}

static int sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    return nanosleep(&ts, NULL);
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure solenoid pins as outputs --- */
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(pin=%d, PI_OUTPUT) failed\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(pin=%d, PI_OUTPUT) failed\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure both solenoids are OFF at startup --- */
    if (set_solenoid(SOLENOID_1_PIN, 0) != 0 ||
        set_solenoid(SOLENOID_2_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int active_pin = SOLENOID_1_PIN;
    int inactive_pin = SOLENOID_2_PIN;

    while (g_running) {
        if (set_solenoid(inactive_pin, 1) != 0) {
            break;
        }
        if (sleep_ms(DELAY_MS) != 0) {
            perror("nanosleep");
            break;
        }
        if (!g_running) {
            break;
        }
        if (set_solenoid(inactive_pin, 0) != 0) {
            break;
        }
        if (sleep_ms(DELAY_MS) != 0) {
            perror("nanosleep");
            break;
        }

        /* Alternate active and inactive solenoid pins */
        int tmp = active_pin;
        active_pin = inactive_pin;
        inactive_pin = tmp;
    }

    /* --- Clean shutdown: ensure both solenoids are OFF --- */
    (void)set_solenoid(SOLENOID_1_PIN, 0);
    (void)set_solenoid(SOLENOID_2_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

