/*
 * dual_uart_door_lock.c — Raspberry Pi 4 Model B
 *
 * Reads 6-digit codes from two UART ports (/dev/serial0 and /dev/serial1)
 * at 9600 baud, 8N1 framing, and unlocks a 12 V electromagnetic door lock
 * when both codes match the expected constant "123456".
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o dual_uart_door_lock dual_uart_door_lock.c \
 *       -lpigpio -lrt
 *
 * Wiring:
 *   /dev/serial0  -> GPIO14 (RXD) / GPIO15 (TXD)  [Pi UART1]
 *   /dev/serial1  -> GPIO16 (RXD) / GPIO17 (TXD)  [Pi UART2]
 *   Relay 1 (12 V) -> GPIO17 (BCM)
 *   Relay 2 (12 V) -> GPIO27 (BCM)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define UART0_DEVICE   "/dev/serial0"
#define UART1_DEVICE   "/dev/serial1"
#define EXPECTED_CODE  "123456"
#define UNLOCK_TIME_US 2000000   /* 2 seconds */
#define READ_TIMEOUT_S 5
#define CODE_BUF_SIZE  32

#define RELAY1_GPIO 17
#define RELAY2_GPIO 27

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    fprintf(stderr, "[ERROR] %s (errno: %s)\n", msg, strerror(errno));
}

static void log_info(const char *msg)
{
    fprintf(stderr, "[INFO] %s\n", msg);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int safe_gpio_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* String comparison (constant-time, avoids timing side-channel)       */
/* ------------------------------------------------------------------ */
static bool strings_match(const char *a, const char *b, size_t n)
{
    uint8_t result = 0;
    for (size_t i = 0; i < n; i++) {
        result |= (uint8_t)(a[i] ^ b[i]);
    }
    return result == 0;
}

/* ------------------------------------------------------------------ */
/* Door lock control                                                   */
/* ------------------------------------------------------------------ */
static int unlock_locks(void)
{
    log_info("Unlocking both door locks...");

    if (safe_gpio_write(RELAY1_GPIO, 1) < 0)
        return -1;
    if (safe_gpio_write(RELAY2_GPIO, 1) < 0)
        return -1;

    gpioDelay(UNLOCK_TIME_US);   /* blocking 2 s delay */

    if (safe_gpio_write(RELAY1_GPIO, 0) < 0)
        return -1;
    if (safe_gpio_write(RELAY2_GPIO, 0) < 0)
        return -1;

    log_info("Door locks locked.");
    return 0;
}

/* ------------------------------------------------------------------ */
/* UART read callback (runs in pigpio thread)                           */
/* ------------------------------------------------------------------ */
static void uart_callback(int handle, char *data, int count)
{
    (void)handle;

    if (count <= 0)
        return;

    /* Reset buffer on any non-digit character */
    for (int i = 0; i < count; i++) {
        if (data[i] < '0' || data[i] > '9') {
            data[0] = '\0';
            return;
        }
    }

    /* Build the 6-digit code */
    char code[CODE_BUF_SIZE];
    int len = (count < (int)sizeof(code) - 1) ? count : (int)sizeof(code) - 1;
    memcpy(code, data, len);
    code[len] = '\0';

    /* Compare with expected code (constant-time) */
    if (strings_match(code, EXPECTED_CODE, strlen(EXPECTED_CODE))) {
        log_info("Matched expected code. Unlocking door locks.");
        if (unlock_locks() < 0) {
            log_error("Failed to unlock door locks.");
        }
    } else {
        fprintf(stderr, "[WARN] Code received but does not match expected code.\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_error("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        log_error("gpioInitialise() failed");
        return EXIT_FAILURE;
    }

    /* --- Configure relay GPIOs as outputs --- */
    if (gpioSetMode(RELAY1_GPIO, PI_OUTPUT) < 0) {
        log_error("gpioSetMode(RELAY1_GPIO)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY2_GPIO, PI_OUTPUT) < 0) {
        log_error("gpioSetMode(RELAY2_GPIO)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure locks start locked */
    if (safe_gpio_write(RELAY1_GPIO, 0) < 0 ||
        safe_gpio_write(RELAY2_GPIO, 0) < 0) {
        log_error("Failed to initialize relay GPIOs to LOW");
        gpioTerminate();
        return EXIT_FAILURE;
    }

