    int handle0 = serOpen(UART0_DEVICE, 9600, 0);
    if (handle0 < 0) {
        log_error("serOpen(UART0_DEVICE)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open UART1 --- */
    int handle1 = serOpen(UART1_DEVICE, 9600, 0);
    if (handle1 < 0) {
        log_error("serOpen(UART1_DEVICE)");
        serClose(handle0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register callbacks (non-blocking, 5 s timeout) --- */
    if (serRead(handle0, NULL, 0) < 0) {
        log_error("serRead(handle0, NULL, 0)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (serRead(handle1, NULL, 0) < 0) {
        log_error("serRead(handle1, NULL, 0)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (serSetBaud(handle0, 9600) < 0) {
        log_error("serSetBaud(handle0)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (serSetBaud(handle1, 9600) < 0) {
        log_error("serSetBaud(handle1)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (serSetDataBits(handle0, 8) < 0) {
        log_error("serSetDataBits(handle0)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (serSetDataBits(handle1, 8) < 0) {
        log_error("serSetDataBits(handle1)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (serSetParity(handle0, 0) < 0) {
        log_error("serSetParity(handle0)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (serSetParity(handle1, 0) < 0) {
        log_error("serSetParity(handle1)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (serSetFlowControl(handle0, 0, 0) < 0) {
        log_error("serSetFlowControl(handle0)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (serSetFlowControl(handle1, 0, 0) < 0) {
        log_error("serSetFlowControl(handle1)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (serSetTimeout(handle0, READ_TIMEOUT_S) < 0) {
        log_error("serSetTimeout(handle0)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (serSetTimeout(handle1, READ_TIMEOUT_S) < 0) {
        log_error("serSetTimeout(handle1)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register callbacks for both UARTs --- */
    if (serReadStart(handle0, uart_callback) < 0) {
        log_error("serReadStart(handle0)");
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (serReadStart(handle1, uart_callback) < 0) {
        log_error("serReadStart(handle1)");
        serReadStop(handle0);
        serClose(handle0);
        serClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_info("Door lock authentication system started.");
    log_info("Listening on /dev/serial0 and /dev/serial1 for 6-digit codes...");

    /* --- Main loop --- */
    while (g_running) {
        gpioDelay(100000);  /* 100 ms */
    }

    /* --- Clean shutdown --- */
    log_info("Shutting down...");

    /* Stop callbacks */
    serReadStop(handle0);
    serReadStop(handle1);

    /* Force relays LOW (locked) */
    safe_gpio_write(RELAY1_GPIO, 0);
    safe_gpio_write(RELAY2_GPIO, 0);

    /* Close UART handles */
    serClose(handle0);
    serClose(handle1);

    /* Terminate pigpio */
    gpioTerminate();

    log_info("Door lock authentication system stopped.");
    return EXIT_SUCCESS;
}

