/*
 * PIR-triggered door strike controller for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - HC-SR501 PIR sensor data line  -> GPIO4  (physical pin 7)
 *   - Door-strike relay control line -> GPIO17 (physical pin 11)
 *
 * Behavior:
 *   Polls the PIR every 50 ms.  On a HIGH reading the relay is energized
 *   for 1 s, then de-energized.  If the PIR stays HIGH for > 10 s a
 *   failsafe is triggered: the relay is de-energized, a WARNING is
 *   logged, and a shutdown event is logged, then the program exits.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_strike door_strike.c -lgpiod
 *
 * Run:
 *   sudo ./door_strike
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define PIR_PIN        4
#define RELAY_PIN      17

#define POLL_INTERVAL_US  50000   /* 50 ms  */
#define RELAY_ON_US       1000000 /* 1 s    */
#define FAILSAFE_TIMEOUT_S 10      /* 10 s   */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *msg)
{
    time_t now = time(NULL);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
    syslog(priority, "[%s] %s", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0)
        goto cleanup;

    /* Open the default gpiochip (gpiochip0 on Pi 4). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request PIR line as input. */
    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        syslog(LOG_ERR, "Failed to request GPIO%d as input: %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request relay line as output, initial value LOW. */
    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO%d as output: %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    log_event(LOG_INFO, "Door strike controller started.");

    bool relay_on = false;
    time_t last_motion = time(NULL);

    while (g_running) {
        int val = gpiod_line_get_value(pir_line);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read PIR line: %s", strerror(errno));
            break;
        }

        if (val == 1) {
            if (!relay_on) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    syslog(LOG_ERR, "Failed to energize relay: %s", strerror(errno));
                    break;
                }
                relay_on = true;
                log_event(LOG_INFO, "Relay energized.");
            }
            last_motion = time(NULL);
        } else {
            if (relay_on) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
                    break;
                }
                relay_on = false;
                log_event(LOG_INFO, "Relay de-energized.");
            }
        }

        /* Failsafe: if no motion for FAILSAFE_TIMEOUT_S the relay is
         * de-energized, a warning is logged, and the program exits. */
        if (difftime(time(NULL), last_motion) > FAILSAFE_TIMEOUT_S) {
            if (relay_on) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failsafe: failed to de-energize relay: %s", strerror(errno));
                    break;
                }
                relay_on = false;
            }
            log_event(LOG_WARNING, "Potential PIR sensor malfunction: relay de-energized.");
            log_event(LOG_INFO, "Shutting down due to failsafe condition.");
            break;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Ensure relay is de-energized on exit. */
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line)
        gpiod_line_release(pir_line);
    if (chip)
        gpiod_chip_close(chip);

    log_event(LOG_INFO, "Door strike controller stopped.");
    closelog();
    ret = EXIT_SUCCESS;

cleanup:
    return ret;
}

