        /* Failsafe: if no motion for FAILSAFE_TIMEOUT_S the relay is
         * de-energized, a warning is logged, and the program exits. */
        if (difftime(time(NULL), last_motion) > FAILSAFE_TIMEOUT_S) {
            if (relay_on) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failsafe: failed to de-energize relay: %s", strerror(errno));
                    break;
                }
                relay_on = false;
            }
            log_event(LOG_WARNING, "Potential PIR sensor malfunction: relay de-energized.");
            log_event(LOG_INFO, "Shutting down due to failsafe condition.");
            break;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Ensure relay is de-energized on exit. */
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line)
        gpiod_line_release(pir_line);
    if (chip)
        gpiod_chip_close(chip);

    log_event(LOG_INFO, "Door strike controller stopped.");
    closelog();
    ret = EXIT_SUCCESS;

cleanup:
    return ret;
}

