#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define CYCLE_INTERVAL_SEC 60
#define RELAY_ON_TIME_SEC 300
#define PAUSE_BETWEEN_RELAYS_SEC 60

#define NUM_RELAYS 4

static volatile sig_atomic_t running = 1;

static const int relay_pins[NUM_RELAYS] = {
    RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as output", relay_pins[i]);
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to write HIGH to GPIO %d", relay_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 1);
    }
}

static void activate_relay(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        syslog(LOG_ERR, "Failed to write LOW to GPIO %d", pin);
    } else {
        syslog(LOG_INFO, "Relay on GPIO %d activated", pin);
    }
}

static void deactivate_relay(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        syslog(LOG_ERR, "Failed to write HIGH to GPIO %d", pin);
    } else {
        syslog(LOG_INFO, "Relay on GPIO %d deactivated", pin);
    }
}

static void log_cycle_state(int relay_index, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        syslog(LOG_ERR, "Failed to get local time");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    syslog(LOG_INFO, "%s - Relay %d (GPIO %d): %s",
           timestamp, relay_index + 1, relay_pins[relay_index],
           state ? "ON" : "OFF");
}

static void timer_callback(void *userdata) {
    (void)userdata;
    static int relay_index = 0;
    static int cycle_active = 0;

    if (!cycle_active) {
        cycle_active = 1;
        activate_relay(relay_pins[relay_index]);
        log_cycle_state(relay_index, 1);
        relay_index = (relay_index + 1) % NUM_RELAYS;
    } else {
        deactivate_relay(relay_pins[relay_index]);
        log_cycle_state(relay_index, 0);
        relay_index = (relay_index + 1) % NUM_RELAYS;
        activate_relay(relay_pins[relay_index]);
        log_cycle_state(relay_index, 1);
        relay_index = (relay_index + 1) % NUM_RELAYS;
    }
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    deactivate_all_relays();

    if (gpioSetTimerFunc(0, CYCLE_INTERVAL_SEC * 1000, timer_callback) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        deactivate_all_relays();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Irrigation system started");

    while (running) {
        sleep(1);
    }

    syslog(LOG_INFO, "Shutting down irrigation system");

    deactivate_all_relays();
    gpioSetTimerFunc(0, 0, NULL);
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

