/*
 * MPU6050 accelerometer sampler for Raspberry Pi 4 Model B.
 *
 * Samples at 100 Hz using a POSIX per-process timer (SIGEV_SIGNAL).
 * Data is stored in a circular buffer and made available via a
 * /sys/kernel/mpu6050_accel/latest interface.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6050_sampler mpu6050_sampler.c
 * Run:    ./mpu6050_sampler
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define POLL_MS        10
#define BUFFER_SIZE    100
#define LIB_PATH       "/sys/kernel/mpu6050_accel/latest"

/* MPU6050 registers */
#define REG_PWR_MGMT_1 0x6B
#define REG_ACCEL_XOUT_H 0x3B

/* Accelerometer scale: 16384 LSB/g */
#define ACCEL_SCALE 16384.0f

typedef struct {
    float x, y, z;
} accel_data_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_lib_file = NULL;
static accel_data_t *g_buffer = NULL;
static int g_buf_head = 0;
static int g_buf_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void on_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg ptr 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read len bytes back */
    ssize_t n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read burst from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPU6050                                                             */
/* ------------------------------------------------------------------ */
static int mpu6050_init(int fd)
{
    /* Wake up the device (clear SLEEP bit) */
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) == -1)
        return -1;

    /* Allow oscillator to stabilise */
    usleep(100000);
    return 0;
}

static int mpu6050_read_accel(int fd, accel_data_t *out)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, REG_ACCEL_XOUT_H, raw, sizeof(raw)) == -1)
        return -1;

    int16_t x = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t y = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t z = (int16_t)((raw[4] << 8) | raw[5]);

    out->x = (float)x / ACCEL_SCALE;
    out->y = (float)y / ACCEL_SCALE;
    out->z = (float)z / ACCEL_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
static void buffer_add(accel_data_t d)
{
    g_buffer[g_buf_head] = d;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static int buffer_latest(accel_data_t *out)
{
    if (g_buf_count == 0)
        return -1;
    int idx = (g_buf_head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    *out = g_buffer[idx];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Driver library interface                                            */
/* ------------------------------------------------------------------ */
static int lib_init(void)
{
    g_lib_file = fopen(LIB_PATH, "w");
    if (!g_lib_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LIB_PATH, strerror(errno));
        return -1;
    }
    return 0;
}

static void lib_update(accel_data_t d)
{
    if (g_lib_file) {
        fprintf(g_lib_file, "%.4f,%.4f,%.4f\n", d.x, d.y, d.z);
        fflush(g_lib_file);
    }
}

static void lib_fini(void)
{
    if (g_lib_file) {
        fclose(g_lib_file);
        g_lib_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Timer callback                                                      */
/* ------------------------------------------------------------------ */
static void timer_cb(struct sigevent *ev)
{
    (void)ev;

    accel_data_t d;
    if (mpu6050_read_accel(g_i2c_fd, &d) == -1) {
        /* Sensor absent or bus error: log and keep going */
        fprintf(stderr, "MPU6050 read failed; skipping sample\n");
        return;
    }

    buffer_add(d);
    lib_update(d);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    lib_fini();

    if (g_i2c_fd != -1) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    if (g_buffer) {
        free(g_buffer);
        g_buffer = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* --- I2C --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd == -1) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) == -1) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_i2c_fd) == -1) {
        fprintf(stderr, "MPU6050 init failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Circular buffer --- */
    g_buffer = calloc(BUFFER_SIZE, sizeof(accel_data_t));
    if (!g_buffer) {
        fprintf(stderr, "calloc failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Driver library --- */
    if (lib_init() == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Timer --- */
    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;

    struct itimerspec its;
    memset(&its, 0, sizeof(its));
    its.it_interval.tv_nsec = POLL_MS * 1000000L;
    its.it_value.tv_nsec   = POLL_MS * 1000000L;

    if (timer_create(CLOCK_MONOTONIC, &sev, &its) == -1) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU6050 sampler running at 100 Hz. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        pause();
        if (!g_running)
            break;
    }

    timer_delete(&its);
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

