#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME  "gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const unsigned int prime_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_for_interval(const struct timespec *interval)
{
    struct timespec remaining;
    while (nanosleep(interval, &remaining) == -1 && errno == EINTR) {
        if (!program_running)
            return;
        remaining = remaining;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int line_states[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "relay_toggle", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
        line_states[i] = 0;
    }

    printf("Relay toggling started. Press Ctrl+C to exit.\n");

    while (program_running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpiod_line_set_value(lines[i], line_states[i]) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
            line_states[i] = !line_states[i];
        }

        struct timespec interval;
        interval.tv_sec  = prime_intervals[0];
        interval.tv_nsec = 0;
        sleep_for_interval(&interval);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nRelay toggling stopped. All relays turned off.\n");

    return ret;
}

