#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define LOG_FILE "alarm_log.txt"
#define POLL_INTERVAL_US 100000
#define RELAY_ACTIVE_US 3000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: Sound event detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_relay(int pin, int duration_us) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error setting relay pin %d HIGH: %s\n", pin, pigpio_error(gpioRead(pin)));
        return -1;
    }

    gpioDelay(duration_us);

    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error setting relay pin %d LOW: %s\n", pin, pigpio_error(gpioRead(pin)));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting sound sensor pin %d as input: %s\n", SOUND_SENSOR_PIN, pigpio_error(gpioRead(SOUND_SENSOR_PIN)));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting relay pin %d as output: %s\n", RELAY_PIN, pigpio_error(gpioRead(RELAY_PIN)));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing relay pin %d LOW: %s\n", RELAY_PIN, pigpio_error(gpioRead(RELAY_PIN)));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_state = gpioRead(SOUND_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error reading sound sensor pin %d: %s\n", SOUND_SENSOR_PIN, pigpio_error(last_state));
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(SOUND_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error reading sound sensor pin %d: %s\n", SOUND_SENSOR_PIN, pigpio_error(current_state));
            break;
        }

        if (current_state != last_state) {
            if (current_state == 1) {
                printf("Sound detected!\n");
                if (log_event(LOG_FILE) < 0) {
                    fprintf(stderr, "Failed to log event.\n");
                }
                if (activate_relay(RELAY_PIN, RELAY_ACTIVE_US) < 0) {
                    fprintf(stderr, "Failed to activate relay.\n");
                }
            }
            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

