    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing MPU6050.\n");
        cleanup();
        return 1;
    }

    printf("MPU6050 initialized. Reading gyroscope data...\n");

    while (running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) < 0) {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
            usleep(100000);
            continue;
        }

        add_to_buffer(&gyro_buffer, gyro_data);
        check_threshold(gyro_data);

        usleep(10000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
