/*
 * MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 9600 baud 8N1
 * TXD -> GPIO14 (BCM), RXD -> GPIO15 (BCM)
 * Logs JSON to co2_log.json and error events to co2_error.log
 * Build: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe_driver -lrt
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>

#include "the_driver.h"

#define UART_DEVICE        "/dev/serial0"
#define BAUD_RATE          B9600
#define LOG_FILE           "co2_log.json"
#define ERROR_LOG_FILE     "co2_error.log"
#define READ_INTERVAL_SEC  5
#define READ_TIMEOUT_MS    1000
#define RESPONSE_LEN       9
#define RETRY_COUNT        3
#define RETRY_DELAY_MS     100
#define MAX_RETRIES        ((READ_TIMEOUT_MS * 1000) / (RETRY_DELAY_MS * 1000))

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* UART initialisation                                                 */
/* ------------------------------------------------------------------ */
static int init_uart(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag  = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK |
                     ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag  = 0;
    tty.c_lflag  = 0;

    tty.c_cc[VMIN]  = RESPONSE_LEN;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_err_fp) return;

    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm;
    localtime_r(&tv.tv_sec, &tm);

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(g_err_fp, "%s.%06ld %s\n", ts, (long)tv.tv_usec, msg);
    fflush(g_err_fp);
}

/* ------------------------------------------------------------------ */
/* JSON logging                                                        */
/* ------------------------------------------------------------------ */
static void log_json(int co2_ppm, int error)
{
    if (!g_log_fp) return;

    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm;
    localtime_r(&tv.tv_sec, &tm);

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(g_log_fp, "{\"timestamp\":\"%s.%06ld\",\"co2_ppm\":%d,\"error\":%d}\n",
            ts, (long)tv.tv_usec, co2_ppm, error);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* MH-Z19B driver wrapper                                              */
/* ------------------------------------------------------------------ */
static int mhz19b_read(int fd, int *co2_ppm)
{
    uint8_t cmd[9] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    uint8_t rx[RESPONSE_LEN];

    for (int attempt = 0; attempt < RETRY_COUNT; ++attempt) {
        tcflush(fd, TCIOFLUSH);

        if (write(fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
            log_error("UART write failed");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        /* Wait for response with timeout */
        fd_set rfds;
        struct timeval tv;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);
        tv.tv_sec  = READ_TIMEOUT_MS / 1000;
        tv.tv_usec = (READ_TIMEOUT_MS % 1000) * 1000;

        int rc = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (rc < 0) {
            if (errno == EINTR) continue;
            log_error("select() error");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (rc == 0) {
            log_error("UART read timeout");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        ssize_t n = read(fd, rx, RESPONSE_LEN);
        if (n != RESPONSE_LEN) {
            char buf[64];
            snprintf(buf, sizeof(buf), "UART read short: %zd bytes", n);
            log_error(buf);
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        /* Verify checksum (sum of bytes 0..7 modulo 256) */
        uint8_t sum = 0;
        for (int i = 0; i < 8; ++i)
            sum += rx[i];
        if (sum != rx[8]) {
            char buf[128];
            snprintf(buf, sizeof(buf),
                     "Checksum mismatch: calc=0x%02X recv=0x%02X",
                     sum, rx[8]);
            log_error(buf);
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        *co2_ppm = ((rx[2] << 8) | rx[3]) & 0xFFFF;
        return 0;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp)  { fclose(g_log_fp);  g_log_fp  = NULL; }
    if (g_err_fp)  { fclose(g_err_fp);  g_err_fp  = NULL; }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen error log");
        fclose(g_log_fp);
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        log_error("UART init failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MH-Z19B CO2 monitor started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        int co2_ppm = 0;
        int rc = mhz19b_read(g_uart_fd, &co2_ppm);

        if (rc == 0) {
            log_json(co2_ppm, 0);
            printf("CO2: %d ppm\n", co2_ppm);
        } else {
            log_json(0, 1);
            log_error("CO2 read failed after retries");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && g_running; ++i)
            usleep(100 * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

