#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define CONFIG_REG_A 0x00
#define CONFIG_REG_B 0x01
#define MODE_REG 0x02
#define DATA_X_MSB 0x03
#define DATA_X_LSB 0x04
#define DATA_Z_MSB 0x05
#define DATA_Z_LSB 0x06
#define DATA_Y_MSB 0x07
#define DATA_Y_LSB 0x08

#define GPIO_PIN 17
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define SAMPLE_INTERVAL_US 100000
#define HARD_IRON_X_OFFSET 100
#define HARD_IRON_Y_OFFSET -50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_regs(int handle, uint8_t reg, char *buf, int count) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
        return -1;
    }
    return i2cReadDevice(handle, buf, count);
}

static int initialize_hmc5883l(int handle) {
    if (i2c_write_reg(handle, CONFIG_REG_A, 0x70) != 0) {
        fprintf(stderr, "Error writing to CONFIG_REG_A\n");
        return -1;
    }
    if (i2c_write_reg(handle, CONFIG_REG_B, 0x20) != 0) {
        fprintf(stderr, "Error writing to CONFIG_REG_B\n");
        return -1;
    }
    if (i2c_write_reg(handle, MODE_REG, 0x00) != 0) {
        fprintf(stderr, "Error writing to MODE_REG\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2c_read_regs(handle, DATA_X_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static double calculate_heading(int16_t x, int16_t y) {
    double heading = atan2((double)y, (double)x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

static double apply_hard_iron_compensation(int16_t x, int16_t y) {
    return calculate_heading(x - HARD_IRON_X_OFFSET, y - HARD_IRON_Y_OFFSET);
}

static void log_heading(double heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Heading: %.2f degrees\n", timestamp, heading);
}

static void control_gpio(double heading) {
    double deviation = fabs(heading - TARGET_HEADING);
    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_hmc5883l(handle) != 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double heading_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer_data(handle, &x, &y, &z) == 0) {
            double heading = apply_hard_iron_compensation(x, y);
            log_heading(heading);

            heading_buffer[buffer_index] = heading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) {
                buffer_count++;
            }

            control_gpio(heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_PIN, 0);
    i2cClose(handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

