#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BH1750_ADDR             0x23
#define BH1750_CONTINUOUS_HIGH  0x10
#define BH1750_CONV_TIME_MS     120
#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22
#define LOG_FILE   "lighting_log.txt"
#define I2C_BUS    "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (red_line)   gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line)  gpiod_line_release(blue_line);
    if (chip)       gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fp)     fclose(log_fp);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
            return -1;
        }
    }

    red_line   = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line  = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(red_line,   "bh1750_rgb", 0) < 0 ||
        gpiod_line_request_output(green_line, "bh1750_rgb", 0) < 0 ||
        gpiod_line_request_output(blue_line,  "bh1750_rgb", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    uint8_t cmd = BH1750_CONTINUOUS_HIGH;
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void set_led_states(float lux) {
    int r = 0, g = 0, b = 0;
    if (lux < 50.0f)   r = 1;
    else if (lux < 150.0f) g = 1;
    else if (lux < 300.0f) b = 1;
    else { r = g = b = 1; }
    gpiod_line_set_value(red_line,   r);
    gpiod_line_set_value(green_line, g);
    gpiod_line_set_value(blue_line,  b);
}

static void log_data(float lux, int r, int g, int b) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_fp, "%s, Lux: %.2f, R: %d, G: %d, B: %d\n", ts, lux, r, g, b);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0 || init_i2c() < 0 || init_log() < 0) {
        cleanup();
        return 1;
    }

    while (running) {
        float lux;
        if (read_lux(&lux) == 0) {
            set_led_states(lux);
            int r = gpiod_line_get_value(red_line);
            int g = gpiod_line_get_value(green_line);
            int b = gpiod_line_get_value(blue_line);
            log_data(lux, r, g, b);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

