/*
 * Raspberry Pi 3 Model B+ — Dual L298N DC Motor Control
 *
 * Motor A: IN1 -> GPIO17, IN2 -> GPIO18
 * Motor B: IN3 -> GPIO22, IN4 -> GPIO23
 *
 * PWM on IN2 (GPIO18) and IN4 (GPIO23) via hardware PWM (BCM 18/23).
 *
 * Build:  gcc -O2 -Wall -Wextra -o motor_control motor_control.c -lpigpio -lrt
 * Run:    sudo ./motor_control 30 70
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255

#define DISTANCE_THRESHOLD 50
#define MIN_DISTANCE       10
#define MAX_DISTANCE       100

#define LOOP_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_motor_direction(int in1, int in2, int in3, int in4,
                               int speed_a, int speed_b)
{
    if (speed_a < 0) speed_a = 0;
    if (speed_a > PWM_RANGE) speed_a = PWM_RANGE;
    if (speed_b < 0) speed_b = 0;
    if (speed_b > PWM_RANGE) speed_b = PWM_RANGE;

    if (gpioWrite(in1, speed_a > 0 ? 1 : 0) < 0) {
