#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define LOG_FILE "solar_tracker.log"
#define SERVO_MIN_PULSE 500000
#define SERVO_MAX_PULSE 2500000
#define SERVO_CENTER_PULSE 1500000
#define SERVO_RANGE 180
#define SERVO_CENTER 90
#define SERVO_MIN 0
#define SERVO_MAX 180
#define SAMPLE_DELAY_MS 100
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_reg8(fd, 0x6B, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, 0x1C, 0x10) < 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, 0x1B, 0x08) < 0) {
        return -1;
    }
    return 0;
}

static int read_accel(int fd, float *ax, float *ay, float *az) {
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16(fd, 0x3B, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, 0x3D, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, 0x3F, &raw_z) < 0) return -1;
    *ax = (float)raw_x / 16384.0f;
    *ay = (float)raw_y / 16384.0f;
    *az = (float)raw_z / 16384.0f;
    return 0;
}

static int read_gyro(int fd, float *gx, float *gy, float *gz) {
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16(fd, 0x43, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, 0x45, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, 0x47, &raw_z) < 0) return -1;
    *gx = (float)raw_x / 131.0f;
    *gy = (float)raw_y / 131.0f;
    *gz = (float)raw_z / 131.0f;
    return 0;
}

static float calculate_pitch(float ax, float az) {
    return atan2f(-ax, az) * 180.0f / M_PI;
}

static float calculate_roll(float ay, float az) {
    return atan2f(ay, az) * 180.0f / M_PI;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN) angle = SERVO_MIN;
    if (angle > SERVO_MAX) angle = SERVO_MAX;
    int pulse = SERVO_MIN_PULSE + (angle - SERVO_CENTER) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / (SERVO_MAX - SERVO_CENTER);
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    FILE *period_fp = fopen(path, "w");
    if (!period_fp) return -1;
    fprintf(period_fp, "%d", PWM_PERIOD_NS);
    fclose(period_fp);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    FILE *duty_fp = fopen(path, "w");
    if (!duty_fp) return -1;
    fprintf(duty_fp, "%d", pulse);
    fclose(duty_fp);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    FILE *enable_fp = fopen(path, "w");
    if (!enable_fp) return -1;
    fprintf(enable_fp, "1");
    fclose(enable_fp);
    return 0;
}

static int log_data(float pitch, float roll, int position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_fp) {
        fprintf(log_fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, position);
        fflush(log_fp);
        return 0;
    }
    return -1;
}

static int get_servo_position(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    FILE *enable_fp = fopen(path, "r");
    if (!enable_fp) return -1;
    int enabled;
    if (fscanf(enable_fp, "%d", &enabled) != 1) {
        fclose(enable_fp);
        return -1;
    }
    fclose(enable_fp);
    if (enabled != 1) return -1;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    FILE *duty_fp = fopen(path, "r");
    if (!duty_fp) return -1;
    int duty;
    if (fscanf(duty_fp, "%d", &duty) != 1) {
        fclose(duty_fp);
        return -1;
    }
    fclose(duty_fp);
    int pulse = duty;
    int angle = SERVO_CENTER + (pulse - (PWM_PERIOD_NS / 2)) * (SERVO_MAX - SERVO_CENTER) / (PWM_PERIOD_NS / 2);
    if (angle < SERVO_MIN) angle = SERVO_MIN;
    if (angle > SERVO_MAX) angle = SERVO_MAX;
    return angle;
}

static int initialize(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing MPU6050: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    FILE *export_fp = fopen(path, "w");
    if (export_fp) {
        fprintf(export_fp, "%d", PWM_CHANNEL);
        fclose(export_fp);
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    FILE *period_fp = fopen(path, "w");
    if (!period_fp) {
        fprintf(stderr, "Error setting PWM period: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    fprintf(period_fp, "%d", PWM_PERIOD_NS);
    fclose(period_fp);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    FILE *duty_fp = fopen(path, "w");
    if (!duty_fp) {
        fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    fprintf(duty_fp, "%d", PWM_PERIOD_NS / 2);
    fclose(duty_fp);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    FILE *enable_fp = fopen(path, "w");
    if (!enable_fp) {
        fprintf(stderr, "Error enabling PWM: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    fprintf(enable_fp, "1");
    fclose(enable_fp);
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
        FILE *enable_fp = fopen(path, "w");
        if (enable_fp) {
            fprintf(enable_fp, "0");
            fclose(enable_fp);
        }
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    if (initialize() < 0) {
        return 1;
    }
    int servo_position = SERVO_CENTER;
    int retries = 0;
    while (running) {
        float ax, ay, az, gx, gy, gz;
        int read_ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_accel(i2c_fd, &ax, &ay, &az) == 0 && read_gyro(i2c_fd, &gx, &gy, &gz) == 0) {
                read_ok = 1;
                break;
            }
            retries++;
            if (retries > 10) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                running = 0;
                break;
            }
            usleep(1000000 * (1 << attempt));
        }
        if (!read_ok) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", retries);
            continue;
        }
        retries = 0;
        float pitch = calculate_pitch(ax, az);
        float roll = calculate_roll(ay, az);
        int new_servo_position = (int)(pitch + 90.0f);
        if (new_servo_position < SERVO_MIN) new_servo_position = SERVO_MIN;
        if (new_servo_position > SERVO_MAX) new_servo_position = SERVO_MAX;
        if (set_servo_angle(new_servo_position) < 0) {
            fprintf(stderr, "Error setting servo angle.\n");
        }
        servo_position = new_servo_position;
        int current_position = get_servo_position();
        if (current_position < 0) {
            fprintf(stderr, "Error getting servo position.\n");
        }
        if (log_data(pitch, roll, current_position) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }
    cleanup();
    return 0;
}

