/*
 * Raspberry Pi Zero W – HC-SR04 Ultrasonic Distance Sensor → PWM Theremin
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM)
 *   Buzzer      -> GPIO18 (BCM) via suitable driver / transistor
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 * Run:
 *   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define SPEED_OF_SOUND   34300.0f   /* cm/s at ~20 °C */
#define MIN_FREQUENCY    100.0f     /* Hz */
#define MAX_FREQUENCY    1000.0f    /* Hz */
#define MIN_DISTANCE     2.0f       /* cm */
#define MAX_DISTANCE     400.0f     /* cm */
#define TIMEOUT_US       30000      /* 30 ms echo timeout */
#define LOOP_DELAY_US    20000      /* 20 ms → ~50 Hz */
#define TRIGGER_PULSE_US 10         /* 10 µs trigger pulse */
#define MIN_GAP_US       60000      /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance (cm) from the HC-SR04.
 * Returns >= 0 on success, -1.0 on timeout / sensor error.
 */
static float get_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Issue a 10 µs trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed on pin %d\n", TRIGGER_PIN);
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if sensor absent) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: HC-SR04 echo start timeout (sensor absent?)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout if sensor absent) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: HC-SR04 echo end timeout (sensor absent?)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    return (float)diff * SPEED_OF_SOUND / 2000000.0f;
}

/*
 * Map distance to a frequency suitable for a buzzer.
 * Returns the clamped frequency, or -1.0 if the distance is outside the
 * valid range.
 */
static float map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0f;
    }
    return MIN_FREQUENCY + (distance - MIN_DISTANCE) *
           (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
}

static void set_buzzer_frequency(float frequency)
{
    if (frequency < 0.0f) {
        gpioPWM(BUZZER_PIN, 0);
        return;
    }

    if (frequency < 100.0f) frequency = 100.0f;
    if (frequency > 1000.0f) frequency = 1000.0f;

    if (gpioSetPWMfrequency(BUZZER_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed on pin %d\n", BUZZER_PIN);
        return;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", BUZZER_PIN);
    }
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for TRIGGER_PIN %d\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for BUZZER_PIN %d\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); /* 1 ms settle */

    uint32_t last_measurement_tick = gpioTick();

    while (g_running) {
        uint32_t now = gpioTick();

        /* Enforce minimum 60 ms gap between measurements */
        if ((int32_t)(now - last_measurement_tick) < (int32_t)MIN_GAP_US) {
            gpioDelay(1000);
            continue;
        }
        last_measurement_tick = now;

        float distance = get_distance();

        if (distance < 0.0f) {
            /* Sensor error: silence buzzer for safety */
            set_buzzer_frequency(-1.0f);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float frequency = map_distance_to_frequency(distance);
        set_buzzer_frequency(frequency);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: silence buzzer and release pigpio */
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

