 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_FREQ  1000   /* Hz — common anode: 0 = full brightness, 255 = off */
#define PWM_RANGE 255    /* 8-bit resolution */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

static void set_led_color(int red, int green, int blue)
{
    /* Common anode: invert duty cycle (0 = full brightness, 255 = off) */
    if (gpioPWM(RED_PIN,   PWM_RANGE - red)   < 0)
        fprintf(stderr, "Warning: gpioPWM failed on GPIO%d\n", RED_PIN);
    if (gpioPWM(GREEN_PIN, PWM_RANGE - green) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on GPIO%d\n", GREEN_PIN);
    if (gpioPWM(BLUE_PIN,  PWM_RANGE - blue)  < 0)
        fprintf(stderr, "Warning: gpioPWM failed on GPIO%d\n", BLUE_PIN);
}

static void cleanup(void)
{
    /* Turn off LED and release PWM resources */
    set_led_color(0, 0, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handler() != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    /* Configure PWM pins as outputs */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", RED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", GREEN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", BLUE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range for each channel */
    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO%d\n", RED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO%d\n", GREEN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO%d\n", BLUE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO%d\n", RED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO%d\n", GREEN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO%d\n", BLUE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    set_led_color(0, 0, 0);

    double t = 0.0;
    const double dt = 0.01;  /* 10 ms steps */

    while (g_running) {
        double proximity = 0.5 * (1.0 + 0.5 * sin(t));
        int r = (int)(255.0 * proximity);
        int g = (int)(255.0 * proximity);
        int b = (int)(255.0 * proximity);

        set_led_color(r, g, b);

        t += dt;
        if (t > 2.0 * M_PI) {
            t -= 2.0 * M_PI;
        }

        usleep(10000);  /* 10 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

