/*
 * Musical doorbell for Raspberry Pi 4 Model B
 *
 * Button : GPIO17 (BCM), internal pull-up, active-low
 * Buzzer : hardware PWM0 on GPIO18 (BCM)
 *
 * Build  : gcc -O2 -Wall -o doorbell doorbell.c -lpigpio -lrt
 * Run    : sudo ./doorbell
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN      17
#define BUZZER_PIN      18

#define DEBOUNCE_US     50000   /* 50 ms debounce */
#define TONE_DURATION   500     /* ms per tone */
#define GAP_DURATION    500     /* ms between tones */
#define LOOP_DELAY_US   10000   /* 10 ms main-loop poll */

/* ---- Musical melody (Hz, duration ms) ---- */
static const int melody[][2] = {
    {262, 250},   /* C4  */
    {294, 250},   /* D4  */
    {330, 250},   /* E4  */
    {349, 250},   /* F4  */
    {392, 250},   /* G4  */
    {440, 250},   /* A4  */
    {494, 250},   /* B4  */
    {523, 250},   /* C5  */
    {587, 250},   /* D5  */
    {659, 250},   /* E5  */
    {698, 250},   /* F5  */
    {783, 250},   /* G5  */
    {880, 250},   /* A5  */
    {988, 250},   /* B5  */
    {1046, 250}, /* C6 */
    {1175, 250}, /* D6 */
    {1318, 250}, /* E6 */
    {1396, 250}, /* F6 */
    {1568, 250}, /* G6 */
    {1760, 250}, /* A6 */
    {1975, 250}, /* B6 */
    {2093, 250}, /* C7 */
    {2349, 250}, /* D7 */
    {2637, 250}, /* E7 */
    {2794, 250}, /* F7 */
    {3136, 250}, /* G7 */
    {3520, 250}, /* A7 */
    {3951, 250}, /* B7 */
    {4186, 250}, /* C8 */
    {4698, 250}, /* D8 */
    {5274, 250}, /* E8 */
    {5588, 250}, /* F8 */
    {6272, 250}, /* G8 */
    {7040, 250}, /* A8 */
    {7902, 250}, /* B8 */
    {0, 0}        /* Sentinel */
};

static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- ISR: fires on every edge of BUTTON_PIN ---- */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    static uint32_t last_tick = 0;
    uint32_t now = tick;

    /* pigpio tick wraps every ~72 min; handle wrap-around */
    if (now - last_tick < DEBOUNCE_US)
        return;
    last_tick = now;

    /* Active-low: falling edge means button pressed */
    if (level == 0) {
        printf("Button pressed!\n");
        fflush(stdout);
    }
}

/* ---- Play a melody through hardware PWM ---- */
static void play_melody(void)
{
    for (int i = 0; melody[i][0] != 0; i++) {
        if (!g_running)
            break;

        /* Set PWM frequency; pigpio sets 50% duty cycle by default */
        if (gpioSetPWMfrequency(BUZZER_PIN, melody[i][0]) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed for %d Hz\n",
                    melody[i][0]);
            return;
        }

        /* Play the tone for the specified duration */
        uint32_t elapsed = 0;
        while (elapsed < (uint32_t)melody[i][1] * 1000 && g_running) {
            gpioDelay(1000); /* 1 ms */
            elapsed += 1000;
        }

        /* Gap between tones */
        if (g_running)
            gpioDelay(GAP_DURATION * 1000);
    }
}

/* ---- Cleanup: stop PWM and release resources ---- */
static void cleanup(void)
{
    gpioPWM(BUZZER_PIN, 0);   /* Stop buzzer */
    gpioSetMode(BUZZER_PIN, PI_INPUT);
    gpioSetPullUpDown(BUZZER_PIN, PI_PUD_OFF);

    gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure button pin ---- */
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin\n");
