#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define WINDOW_SIZE      5
#define DEFAULT_TIMEOUT  1000
#define LOG_FILE         "vibration_events.log"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        perror("time()");
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r()");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    return 0;
}

static int log_event(FILE *log_fp, int value)
{
    char ts[32];
    if (get_iso8601_timestamp(ts, sizeof(ts)) != 0) {
        return -1;
    }
    if (fprintf(log_fp, "%s, %d\n", ts, value) < 0) {
        perror("fprintf(log)");
        return -1;
    }
    if (fflush(log_fp) != 0) {
        perror("fflush(log)");
        return -1;
    }
    return 0;
}

static int check_earthquake(int *window, int size)
{
    int high_count = 0;
    for (int i = 0; i < size; i++) {
        if (window[i] == 1) {
            high_count++;
        }
    }
    return (high_count >= 3) ? 1 : 0;
}

int main(int argc, char *argv[])
{
    int timeout_ms = DEFAULT_TIMEOUT;
    if (argc > 1) {
        char *endptr = NULL;
        long val = strtol(argv[1], &endptr, 10);
        if (endptr == argv[1] || *endptr != '\0' || val <= 0 || val > 60000) {
            fprintf(stderr, "Invalid timeout '%s'. Using default %d ms.\n",
                    argv[1], DEFAULT_TIMEOUT);
        } else {
            timeout_ms = (int)val;
        }
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name()");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line()");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(line, "sw420-vibration") < 0) {
        perror("gpiod_line_request_rising_edge_events()");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_falling_edge_events(line, "sw420-vibration") < 0) {
        perror("gpiod_line_request_falling_edge_events()");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(log)");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int window[WINDOW_SIZE] = {0};
    int window_idx = 0;
    int earthquake_count = 0;

    printf("Monitoring SW-420 vibration sensor on GPIO17 (BCM). "
           "Press Ctrl+C to exit.\n");

    while (g_running) {
        int ret = gpiod_line_event_wait(line, &(struct timespec){
            .tv_sec  = timeout_ms / 1000,
            .tv_nsec = (long)(timeout_ms % 1000) * 1000000L
        });

        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait()");
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read()");
            continue;
        }

        int value = (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) ? 1 : 0;
        window[window_idx] = value;
        window_idx = (window_idx + 1) % WINDOW_SIZE;

        if (log_event(log_fp, value) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        if (check_earthquake(window, WINDOW_SIZE)) {
            earthquake_count++;
            if (earthquake_count >= 3) {
                char ts[32];
                if (get_iso8601_timestamp(ts, sizeof(ts)) == 0) {
                    printf("[%s] EARTHQUAKE ALERT: 3 consecutive HIGH events detected.\n",
                           ts);
                }
                earthquake_count = 0;
            }
        } else {
            earthquake_count = 0;
        }
    }

    printf("\nShutting down cleanly...\n");
    fclose(log_fp);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

