#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LSM303_MAG_ADDR 0x1E

#define LSM303_MAG_MR_REG_M 0x02
#define LSM303_MAG_OUT_X_H_M 0x03

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define NUM_DIRS 8
static const char *dir_names[NUM_DIRS] = {
    "N", "NE", "E", "SE", "S", "SW", "W", "NW"
};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read burst from 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd) {
    if (i2c_write_reg8(fd, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to set magnetometer to continuous mode\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t raw[6];
    if (i2c_read_burst(fd, LSM303_MAG_OUT_X_H_M, raw, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((raw[0] << 8) | raw[1]);
    *y = (int16_t)((raw[2] << 8) | raw[3]);
    *z = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

static void calibrate_magnetometer(int16_t x, int16_t y, int16_t z,
                                   int16_t *cx, int16_t *cy, int16_t *cz) {
    *cx = x - X_OFFSET;
    *cy = y - Y_OFFSET;
    *cz = z - Z_OFFSET;
}

static float calculate_heading(int16_t cx, int16_t cy) {
    float heading = atan2f((float)cy, (float)cx) * 180.0f / (float)M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    return heading;
}

static int determine_direction(float heading) {
    int idx = (int)(heading / 45.0f);
    if (idx < 0) idx = 0;
    if (idx >= NUM_DIRS) idx = NUM_DIRS - 1;
    return idx;
}

static int log_data(FILE *fp, int16_t cx, int16_t cy, int16_t cz, float heading) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, %d, %d, %d, %.2f\n", ts, cx, cy, cz, heading) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (init_magnetometer(fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("mag_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(mag_log.csv) failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        fflush(fp);
    }

    while (g_running) {
        int16_t raw_x, raw_y, raw_z, cal_x, cal_y, cal_z;
        if (read_magnetometer(fd, &raw_x, &raw_y, &raw_z) < 0) {
