static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed: %s\n",
                pin, state, pigpio_error(gpioRead(pin)));
        return -1;
    }
    return 0;
}

static void deactivate_all(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i)
        (void)set_relay(pins[i], 1);
}

static int log_irrigation(int relay_num, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log, "%s, Relay %d, Moisture Level: %d\n",
                timestamp, relay_num, moisture_level) < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log) == EOF) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int irrigate(int relay_num, int moisture_level) {
    if (log_irrigation(relay_num, moisture_level) != 0)
        return -1;

    if (set_relay(relay_num, 0) != 0)
        return -1;

    printf("Irrigating Relay %d (Moisture: %d%%)\n", relay_num, moisture_level);

    for (int elapsed = 0; elapsed < IRRIGATION_DURATION && g_running; elapsed++)
        gpioDelay(1000000);

    if (set_relay(relay_num, 1) != 0)
        return -1;

    return 0;
}

int main(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int initialized = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    initialized = 1;

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", pins[i]);
            goto cleanup;
        }
        if (gpioWrite(pins[i], 1) < 0) {
            fprintf(stderr, "Error: gpioWrite(%d, 1) failed\n", pins[i]);
            goto cleanup;
        }
    }

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        int moisture_level = rand() % 101;
        printf("Moisture Level: %d%%\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
                if (irrigate((int)pins[i], moisture_level) != 0) {
                    fprintf(stderr, "Warning: irrigation failed for Relay %d\n", (int)pins[i]);
                }
                if (i < sizeof(pins) / sizeof(pins[0]) - 1 && g_running)
                    gpioDelay(1000000);
            }
        }

        for (int elapsed = 0; elapsed < POLL_INTERVAL && g_running; elapsed++)
            gpioDelay(1000000);
    }

cleanup:
    deactivate_all();
    if (g_log != NULL) {
        if (fclose(g_log) == EOF)
            fprintf(stderr, "Error: fclose failed: %s\n", strerror(errno));
        g_log = NULL;
    }
    if (initialized)
        gpioTerminate();
    return EXIT_SUCCESS;
}

