/*
 * Automated Plant Watering System for Raspberry Pi Zero W
 * Controls two SG90 servo motors via the library's API call.
 *
 * Build: gcc -Wall -Wextra -O2 -o watering watering.c -lthe_driver_library -lrt
 *
 * Wiring:
 *   Valve servo signal  -> GPIO17 (physical pin 11, BCM 17)
 *   Nozzle servo signal -> GPIO18 (physical pin 12, BCM 18)
 *   Servo VCC           -> 5V (pin 2 or 4)
 *   Servo GND           -> GND (pin 6 or 9)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

/* ---- Configuration ---- */
#define VALVE_SERVO_PIN      17
#define NOZZLE_SERVO_PIN     18

#define MOISTURE_THRESHOLD   50
#define SERVO_OPEN_PULSE_US  1500   /* ~90 degrees */
#define SERVO_CLOSE_PULSE_US 500    /* ~0 degrees  */

#define NOZZLE_ANGLE_0   0
#define NOZZLE_ANGLE_45  45
#define NOZZLE_ANGLE_90  90
#define NOZZLE_ANGLE_135 135
#define NOZZLE_ANGLE_180 180

#define NOZZLE_ANGLE_0_PULSE_US   500
#define NOZZLE_ANGLE_45_PULSE_US  1000
#define NOZZLE_ANGLE_90_PULSE_US  1500
#define NOZZLE_ANGLE_135_PULSE_US 2000
#define NOZZLE_ANGLE_180_PULSE_US 2500

#define SERVO_SETTLE_MS   500
#define SPRAY_DURATION_MS 5000
#define CYCLE_DELAY_MS    5000
#define MAX_RETRIES       3
#define RETRY_DELAY_MS    100

/* ---- Library API (placeholder) ---- */
/* The actual library name must be substituted at build-time. */
#include <the_driver_library.h>

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Helpers ---- */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static int set_servo_pulse(int pin, int pulse_us)
{
    int rc = the_servo_set_pulse(pin, pulse_us);
    if (rc != 0) {
        fprintf(stderr, "Error: the_servo_set_pulse(pin=%d, pulse=%d) failed (rc=%d)\n",
                pin, pulse_us, rc);
    }
    return rc;
}

static int open_valve(void)
{
    printf("Opening valve...\n");
    int rc = set_servo_pulse(VALVE_SERVO_PIN, SERVO_OPEN_PULSE_US);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to open valve (rc=%d)\n", rc);
        return -1;
    }
    sleep_ms(SERVO_SETTLE_MS);
    return 0;
}

static int close_valve(void)
{
    printf("Closing valve...\n");
    int rc = set_servo_pulse(VALVE_SERVO_PIN, SERVO_CLOSE_PULSE_US);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to close valve (rc=%d)\n", rc);
        return -1;
    }
    sleep_ms(SERVO_SETTLE_MS);
    return 0;
}

static int set_nozzle_angle(int angle)
{
    int pulse_us;
    switch (angle) {
        case NOZZLE_ANGLE_0:   pulse_us = NOZZLE_ANGLE_0_PULSE_US;   break;
        case NOZZLE_ANGLE_45:  pulse_us = NOZZLE_ANGLE_45_PULSE_US;  break;
        case NOZZLE_ANGLE_90:  pulse_us = NOZZLE_ANGLE_90_PULSE_US;  break;
        case NOZZLE_ANGLE_135: pulse_us = NOZZLE_ANGLE_135_PULSE_US; break;
        case NOZZLE_ANGLE_180: pulse_us = NOZZLE_ANGLE_180_PULSE_US; break;
        default:
            fprintf(stderr, "Error: invalid nozzle angle %d\n", angle);
            return -1;
    }
    int rc = set_servo_pulse(NOZZLE_SERVO_PIN, pulse_us);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set nozzle angle %d (rc=%d)\n", angle, rc);
        return -1;
    }
    return 0;
}

static int read_soil_moisture(void)
{
    static int idx = 0;
    static const int seq[] = {20, 40, 60, 80, 100};
    int v = seq[idx];
    idx = (idx + 1) % (int)(sizeof(seq) / sizeof(seq[0]));
    printf("Soil moisture: %d\n", v);
    return v;
}

static int water_plant(void)
{
    printf("Watering plant...\n");
    if (open_valve() != 0)
        return -1;

    int angles[] = {NOZZLE_ANGLE_0, NOZZLE_ANGLE_45, NOZZLE_ANGLE_90,
                    NOZZLE_ANGLE_135, NOZZLE_ANGLE_180};
    for (size_t i = 0; i < sizeof(angles) / sizeof(angles[0]); ++i) {
        if (!g_running)
            return -1;
        if (set_nozzle_angle(angles[i]) != 0) {
            fprintf(stderr, "Warning: nozzle position %d failed\n", angles[i]);
            continue;
        }
        sleep_ms(2000);
        if (!g_running)
            return -1;
        printf("Spraying for %d ms...\n", SPRAY_DURATION_MS);
        sleep_ms(SPRAY_DURATION_MS);
    }

    if (close_valve() != 0) {
        fprintf(stderr, "Warning: valve close failed\n");
        return -1;
    }
    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize library */
    int rc = the_init();
    if (rc != 0) {
        fprintf(stderr, "Error: the_init() failed (rc=%d)\n", rc);
        return EXIT_FAILURE;
    }

    /* Configure servo pins */
    rc = the_servo_config(VALVE_SERVO_PIN, 500, 2500);
    if (rc != 0) {
        fprintf(stderr, "Error: the_servo_config(valve, 500, 2500) failed (rc=%d)\n", rc);
        the_cleanup();
        return EXIT_FAILURE;
    }
    rc = the_servo_config(NOZZLE_SERVO_PIN, 500, 2500);
    if (rc != 0) {
        fprintf(stderr, "Error: the_servo_config(nozzle, 500, 2500) failed (rc=%d)\n", rc);
        the_cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure servos are stopped at startup */
    (void)set_servo_pulse(VALVE_SERVO_PIN, SERVO_CLOSE_PULSE_US);
    (void)set_servo_pulse(NOZZLE_SERVO_PIN, SERVO_CLOSE_PULSE_US);
    sleep_ms(100);

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = read_soil_moisture();
        if (moisture < 0) {
            fprintf(stderr, "Error: soil moisture read failed\n");
            break;
        }

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture %d below threshold %d, watering...\n",
                   moisture, MOISTURE_THRESHOLD);
            int retries = 0;
            int attempt = 0;
            int water_ok = 0;
            while (retries < MAX_RETRIES && g_running) {
                attempt++;
                if (water_plant() == 0) {
                    water_ok = 1;
                    break;
                }
                fprintf(stderr, "Watering attempt %d/%d failed, retrying...\n",
                        attempt, MAX_RETRIES);
                sleep_ms(RETRY_DELAY_MS);
                retries++;
            }
            if (!water_ok) {
                fprintf(stderr, "Error: watering failed after %d attempts\n", MAX_RETRIES);
            }
        } else {
            printf("Moisture %d above threshold %d, skipping watering.\n",
                   moisture, MOISTURE_THRESHOLD);
        }

        if (g_running)
            sleep_ms(CYCLE_DELAY_MS);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    (void)set_servo_pulse(VALVE_SERVO_PIN, SERVO_CLOSE_PULSE_US);
    (void)set_servo_pulse(NOZZLE_SERVO_PIN, SERVO_CLOSE_PULSE_US);
    sleep_ms(100);
    the_cleanup();
    printf("Plant watering system stopped.\n");
    return EXIT_SUCCESS;
}

