/*
 * MPU-6050 Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6050 VCC  -> Pi 3.3V (Pin 1)
 *   MPU-6050 GND  -> Pi GND  (Pin 9)
 *   MPU-6050 SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   MPU-6050 SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *
 * I2C bus: /dev/i2c-1
 * Address: 0x68 (AD0 tied to GND)
 *
 * Build: gcc -O2 -Wall -o gyro_logger gyro_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_PWR_MGMT_1  0x6B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_XOUT_L 0x44
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_YOUT_L 0x46
#define MPU6050_GYRO_ZOUT_H 0x47
#define MPU6050_GYRO_ZOUT_L 0x48

#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "gyro_log.txt"
#define SAMPLE_PERIOD_US   100000  /* 10 Hz */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* tell main loop to exit cleanly          */
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register.                               */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X): write returned %zd (errno %d: %s)\n",
                reg, n, errno, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at `reg` using a combined SMBus-style        */
/* transfer (write register address, then repeated-start read).        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (len == 0) return 0;

    /* Phase 1: write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst(0x%02X): write reg pointer failed (errno %d: %s)\n",
                reg, errno, strerror(errno));
        return -1;
    }

    /* Phase 2: read the data bytes (repeated-start) */
    ssize_t n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_burst(0x%02X): read returned %zd (expected %zu, errno %d: %s)\n",
                reg, n, len, errno, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6050: wake it from sleep mode.                   */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int mpu6050_init(int fd)
{
    /* PWR_MGMT_1 = 0x00 selects internal 8 MHz oscillator; bit 6 = 0
     * wakes the device from sleep. */
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "MPU-6050 not responding at 0x%02X on %s\n",
                MPU6050_ADDR, I2C_BUS);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 16-bit gyro sample (high byte first).                      */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_gyro_axis(int fd, uint8_t reg_high, int16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_burst(fd, reg_high, buf, sizeof(buf)) != 0)
        return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row: timestamp, X, Y, Z.                             */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire the MPU-6050 slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (mpu6050_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6050 logging to %s at 10 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_gyro_axis(g_i2c_fd, MPU6050_GYRO_XOUT_H, &x) != 0 ||
            read_gyro_axis(g_i2c_fd, MPU6050_GYRO_YOUT_H, &y) != 0 ||
            read_gyro_axis(g_i2c_fd, MPU6050_GYRO_ZOUT_H, &z) != 0) {
