    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0)
            fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        g_log_fp = NULL;
    }

    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) != 0)
            fprintf(stderr, "close(i2c_fd) failed: %s\n", strerror(errno));
        g_i2c_fd = -1;
    }

    printf("Done.\n");
    return EXIT_SUCCESS;
}

