static void step_set(int step)
{
    switch (step) {
    case 0: gpioWrite(IN1, 1); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 0); break;
    case 1: gpioWrite(IN1, 0); gpioWrite(IN2, 1); gpioWrite(IN3, 0); gpioWrite(IN4, 0); break;
    case 2: gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 1); gpioWrite(IN4, 0); break;
    case 3: gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 1); break;
    default: gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 0); break;
    }
}

/*
 * Rotate the stepper by `steps` clockwise.
 * Returns 0 on success, -1 on pigpio write failure.
 */
static int rotate_clockwise(int steps)
{
    for (int i = 0; i < steps && g_running; i++) {
        for (int s = 0; s < 4 && g_running; s++) {
            step_set(s);
            gpioDelay(STEP_DELAY_US);
        }
    }
    return 0;
}

/*
 * Rotate the stepper by `steps` counter-clockwise.
 * Returns 0 on success, -1 on pigpio write failure.
 */
static int rotate_counter_clockwise(int steps)
{
    for (int i = 0; i < steps && g_running; i++) {
        for (int s = 3; s >= 0 && g_running; s--) {
            step_set(s);
            gpioDelay(STEP_DELAY_US);
        }
    }
    return 0;
}

/*
 * De-energize all coils to reduce power consumption and heat.
 */
static void deenergize(void)
{
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

/*
 * Safely de-energize coils and terminate pigpio.
 * Returns 0 on success, -1 on pigpio termination failure.
 */
static int cleanup(void)
{
    deenergize();
    if (gpioTerminate() != 0) {
        fprintf(stderr, "Warning: gpioTerminate() failed in cleanup\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(IN4, PI_OUTPUT) != 0 ||
        gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- internal pull-ups on buttons ---- */
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Door lock/unlock simulator ready.\n");
    printf("  LOCK   = GPIO%d (active-low, pull-up)\n", LOCK_BUTTON);
    printf("  UNLOCK = GPIO%d (active-low, pull-up)\n", UNLOCK_BUTTON);
    printf("Press Ctrl-C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state < 0 || unlock_state < 0) {
            fprintf(stderr, "Error: gpioRead failed (lock=%d, unlock=%d)\n",
                    lock_state, unlock_state);
            break;
        }

        /* LOCK button pressed (active-low) */
        if (lock_state == 0) {
            printf("Locking door...\n");
            if (rotate_clockwise(STEPS_PER_REV) != 0) {
                fprintf(stderr, "Error: rotate_clockwise failed\n");
                break;
            }
            deenergize();
            printf("Door locked.\n");

            /* wait for button release with debounce */
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                gpioDelay(DEBOUNCE_US);
            }
        }

        /* UNLOCK button pressed (active-low) */
        if (unlock_state == 0) {
            printf("Unlocking door...\n");
            if (rotate_counter_clockwise(STEPS_PER_REV) != 0) {
                fprintf(stderr, "Error: rotate_counter_clockwise failed\n");
                break;
            }
            deenergize();
            printf("Door unlocked.\n");

            /* wait for button release with debounce */
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                gpioDelay(DEBOUNCE_US);
            }
        }

        /* small idle sleep to reduce CPU usage */
        gpioDelay(10000);  /* 10 ms */
    }

    /* ---- graceful shutdown ---- */
    cleanup();
    printf("\nExiting.\n");
    return EXIT_SUCCESS;
}

