#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000
#define SAMPLE_INTERVAL_US 1000000
#define MEASURE_PAUSE_US  60000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_distance(float *distance_out) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1;
    }

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        gpioDelay(1);
        timeout--;
    }
    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }
    start_tick = gpioTick();

    timeout = ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        gpioDelay(1);
        timeout--;
    }
    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    *distance_out = (float)diff * SPEED_OF_SOUND_CM_PER_US / 2.0f;
    return 0;
}

static void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open distance_log.txt: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
            if (log_file != NULL) {
                fprintf(log_file, "Error reading distance\n");
                fflush(log_file);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return 0;
}

