/*
 * VL53L1X distance monitor with relay control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: VL53L1X on default I2C address 0x29
 * Relay:  GPIO18 (BCM), active-HIGH
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_monitor vl53l1x_monitor.c -li2c
 *
 * The VL53L1X is a time-of-flight sensor: the readout is a single
 * 16-bit distance value (mm) returned in register 0x1E.
 * The relay is driven HIGH when the distance is <= 50 cm, LOW otherwise.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define VL53L1X_ADDR     0x29
#define RELAY_PIN        18
#define DISTANCE_THRESHOLD_CM 50
#define POLL_DELAY_MS    100
#define MAX_DISTANCE_MM  4000   /* VL53L1X range limit (mm) */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SYSTEM_RANGE_START  0x00
#define REG_RESULT_RANGE_STATUS 0x14
#define REG_RESULT_DISTANCE     0x1E

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ----------------------------- Signal handler ---------------------------- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* VL53L1X returns big-endian 16-bit values */
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ----------------------------- VL53L1X driver ---------------------------- */
static int vl53l1x_init(int fd)
{
    /* Start continuous ranging mode */
    if (i2c_write_reg8(fd, REG_SYSTEM_RANGE_START, 0x01) != 0)
        return -1;
    usleep(10000);  /* allow first measurement to complete */
    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status;
    if (i2c_read_reg8(fd, REG_RESULT_RANGE_STATUS, &status) != 0)
        return -1;

    /* Bit 0 of RESULT_RANGE_STATUS indicates data ready */
    if ((status & 0x01) == 0) {
        /* No new data yet — not an error */
        return 1;  /* non-fatal: caller should retry */
    }

    if (i2c_read_reg16(fd, REG_RESULT_DISTANCE, distance_mm) != 0)
        return -1;

    /* Clear the data-ready flag so the next conversion can be latched */
    if (i2c_write_reg8(fd, REG_RESULT_RANGE_STATUS, 0x01) != 0)
        return -1;

    return 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor --- */
    if (vl53l1x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error).\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* --- Configure relay pin --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO%d LOW.\n", RELAY_PIN);
        gpioTerminate();
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance monitor started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(g_i2c_fd, &distance_mm);

        if (rc == 0) {
            int distance_cm = distance_mm / 10;
            printf("Distance: %d cm\n", distance_cm);

            int relay_state = (distance_cm <= DISTANCE_THRESHOLD_CM) ? 1 : 0;
            if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                fprintf(stderr, "Warning: failed to write relay GPIO%d.\n",
                        RELAY_PIN);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        }
        /* rc == 1: data not ready — not an error, just skip */

        usleep(POLL_DELAY_MS * 1000);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

