/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 * Uses the standard Linux I2C character-device interface (/dev/i2c-1).
 *
 * Wiring:
 *   MPU-6050 VCC  -> Pi 3.3V (Pin 1)
 *   MPU-6050 GND  -> Pi GND  (Pin 9)
 *   MPU-6050 SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   MPU-6050 SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -o mpu6050_reader mpu6050_reader.c
 * Run:    sudo ./mpu6050_reader   (or ensure user is in the 'i2c' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68          /* Default I2C address when AD0 tied to GND */
#define I2C_BUS            "/dev/i2c-1"

/* Register addresses */
#define REG_SMPLRT_DIV     0x19
#define REG_CONFIG         0x1A
#define REG_GYRO_CONFIG    0x1B
#define REG_GYRO_XOUT_H    0x43
#define REG_PWR_MGMT_1     0x6B

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I   0x68

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* tell main loop to exit cleanly */
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read one byte */
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register pair (high then low). */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t hi, lo;
    if (i2c_read_reg8(fd, reg, &hi) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &lo) != 0)
        return -1;
    *out = (int16_t)((uint16_t)hi << 8 | (uint16_t)lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_mpu6050(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, 0x75, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register — sensor absent or bus error.\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MPU6050_WHO_AM_I);
        return -1;
    }

    /* Wake up the device (clear SLEEP bit in PWR_MGMT_1) */
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) != 0)
        return -1;

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz internal sample rate */
    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /* DLPF_CFG = 1 -> 184 Hz bandwidth, 1 kHz output rate */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x01) != 0)
        return -1;

    /* GYRO_CONFIG = 0 -> ±250 °/s full scale */
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the device */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (init_mpu6050(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading angular velocity every 100 ms (Ctrl+C to stop)...\n");

    while (g_running) {
        int16_t gx, gy, gz;

        if (i2c_read_reg16(g_i2c_fd, REG_GYRO_XOUT_H, &gx) != 0 ||
            i2c_read_reg16(g_i2c_fd, REG_GYRO_XOUT_H + 2, &gy) != 0 ||
            i2c_read_reg16(g_i2c_fd, REG_GYRO_XOUT_H + 4, &gz) != 0) {
            fprintf(stderr, "Error reading gyroscope data — continuing.\n");
        } else {
            printf("X: %6d  Y: %6d  Z: %6d  (raw)\n", gx, gy, gz);
        }

        sleep_ms(100);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        /* Put the device back to sleep */
        (void)i2c_write_reg8(g_i2c_fd, REG_PWR_MGMT_1, 0x40);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

