/*
 * Automated plant watering system for Raspberry Pi 4 Model B.
 *
 * Four 5 V relay modules (active-low) on BCM GPIO17, GPIO18, GPIO27, GPIO22.
 * Library: libgpiod (modern Linux GPIO character-device API).
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 * Run:    sudo ./watering   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define RELAY_PINS      {17, 18, 27, 22}
#define RELAY_ACTIVE_MS 5000
#define CYCLE_PERIOD_S  86400   /* 24 hours */
#define LOG_FILE        "watering_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int log_cycle_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", ts) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void)
{
    const unsigned int relay_pins[NUM_RELAYS] = RELAY_PINS;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
