/*
 * Automated plant watering system for Raspberry Pi 4 Model B.
 *
 * Four 5 V relay modules (active-low) on BCM GPIO17, GPIO18, GPIO27, GPIO22.
 * Library: libgpiod (modern Linux GPIO character-device API).
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 * Run:    sudo ./watering   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define RELAY_PINS      {17, 18, 27, 22}
#define RELAY_ACTIVE_MS 5000
#define CYCLE_PERIOD_S  86400   /* 24 hours */
#define LOG_FILE        "watering_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int log_cycle_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", ts) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void)
{
    const unsigned int relay_pins[NUM_RELAYS] = RELAY_PINS;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    /* Request all four lines as outputs, initial value HIGH (relays OFF). */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "plant_watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            for (int j = 0; j < i; j++)
                gpiod_line_release(lines[j]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            printf("Activating relay on GPIO%u for %d ms...\n",
                   relay_pins[i], RELAY_ACTIVE_MS);

            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%u, 0) failed: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }

            /* Sleep in 100 ms increments so signals are caught promptly. */
            for (int ms = 0; ms < RELAY_ACTIVE_MS && g_running; ms += 100)
                usleep(100 * 1000);

            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%u, 1) failed: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        if (g_running && log_cycle_start() != 0)
            fprintf(stderr, "Warning: failed to log cycle start.\n");

        /* Sleep for the remainder of the 24-hour cycle (coarse granularity). */
        for (int s = 0; s < CYCLE_PERIOD_S && g_running; s += 10)
            sleep(10);
    }

cleanup:
    /* Ensure all relays are OFF before releasing. */
    for (int i = 0; i < NUM_RELAYS; i++)
        (void)gpiod_line_set_value(lines[i], 1);

    for (int i = 0; i < NUM_RELAYS; i++)
        gpiod_line_release(lines[i]);
    gpiod_chip_close(chip);

    printf("Plant watering system stopped.\n");
    return EXIT_SUCCESS;
}

