#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOG_FILE "smart_lighting.log"
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800
#define STEP_DELAY 1
#define NUM_RELAYS 4

static const int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (log_file == NULL) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            return -1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", relay_pins[i]);
            return -1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", relay_pins[i]);
            return -1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialize PWM on GPIO %d\n", relay_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void set_relay_intensity(int pin, int intensity) {
    if (intensity < 0) intensity = 0;
    if (intensity > PWM_RANGE) intensity = PWM_RANGE;
    if (gpioPWM(pin, intensity) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", pin);
    }
}

static void sunrise_effect(void) {
    int step_delay = SUNRISE_DURATION / (PWM_RANGE + 1);
    for (int intensity = 0; intensity <= PWM_RANGE && running; intensity++) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            set_relay_intensity(relay_pins[i], intensity);
        }
        log_message("Sunrise step complete");
        sleep(step_delay);
    }
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relay_pins[i], 0);
        gpioSetMode(relay_pins[i], PI_INPUT);
    }
    gpioTerminate();
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    log_message("Smart lighting system started");

    if (initialize_gpio() != 0) {
        log_message("GPIO initialization failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handlers");
        cleanup_gpio();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    sunrise_effect();

    if (running) {
        log_message("Sunrise effect complete");
    } else {
        log_message("Sunrise effect interrupted by signal");
    }

    cleanup_gpio();
    log_message("Smart lighting system stopped");
    fclose(log_file);
    return EXIT_SUCCESS;
}

