/*
 * MPU-6050 gyroscope reader with LED threshold indicator.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2  (BCM)
 *   MPU-6050 SCL -> GPIO3  (BCM)
 *   MPU-6050 VCC -> 3.3 V
 *   MPU-6050 GND -> GND
 *   LED anode   -> GPIO17 (BCM) via 330 ohm resistor
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -o mpu6050_led mpu6050_led.c -lpigpio -lrt
 * Run:    sudo ./mpu6050_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68          /* default I2C address (AD0 tied to GND) */
#define MPU6050_SMPLRT_DIV  0x19          /* sample rate divider */
#define MPU6050_CONFIG      0x1A          /* DLPF config + sleep mode */
#define MPU6050_GYRO_CONFIG 0x1B          /* full-scale range */
#define MPU6050_GYRO_XOUT_H 0x43          /* high byte of X-axis gyro data */
#define MPU6050_PWR_MGMT_1  0x6B          /* power management */

/* ---- Application constants ---- */
#define I2C_BUS            1
#define LED_GPIO           17
#define BUFFER_SIZE        100
#define SAMPLE_PERIOD_US   50000          /* 50 ms -> 20 Hz */
#define THRESHOLD_GYRO     250.0f         /* deg/s */
#define MAX_REINIT_ATTEMPTS 3
#define POLL_RETRIES       10

/* ---- Data structures ---- */
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static int      i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static circular_buffer_t gyro_buffer;

/* ---- Prototypes ---- */
static int  init_mpu6050(void);
static int  read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(circular_buffer_t *buf, float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Initialize MPU-6050 ---- */
static int init_mpu6050(void)
{
    /* Wake up the device (clear SLEEP bit). */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 (wake).\n");
        return -1;
    }
    gpioDelay(100000);  /* 100 ms settle */

    /* Sample rate divider = 0 -> 1 kHz / (1 + 0) = 1 kHz internal clock. */
    if (i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV.\n");
        return -1;
    }

    /* DLPF config: 1 kHz internal, 184 Hz bandwidth -> 1 kHz / 184 = 5.26 Hz output. */
    if (i2cWriteByteData(i2c_handle, MPU6050_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error: failed to write CONFIG.\n");
        return -1;
    }

    /* Gyro full-scale range: ±250 deg/s (FS_SEL = 0). */
    if (i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG.\n");
        return -1;
    }

    return 0;
}

/* ---- Read 6 bytes of gyro data ---- */
static int read_gyro_data(float *x, float *y, float *z)
{
    char buf[6];
    int  bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C block read returned %d (expected 6).\n", bytes_read);
        return -1;
    }

    /* MPU-6050 is little-endian: [low][high][low][high][low][high] per axis. */
    int16_t raw_x = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    int16_t raw_y = (int16_t)((uint16_t)buf[2] | ((uint16_t)buf[3] << 8));
    int16_t raw_z = (int16_t)((uint16_t)buf[4] | ((uint16_t)buf[5] << 8));

    /* ±250 deg/s full-scale => 131 LSB per deg/s. */
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* ---- Add timestamped data to circular buffer ---- */
static void add_to_buffer(circular_buffer_t *buf, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    buf->data[buf->head].timestamp = ts;
    buf->data[buf->head].x = x;
    buf->data[buf->head].y = y;
    buf->data[buf->head].z = z;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) {
        buf->count++;
    }
}

/* ---- Check threshold and drive LED ---- */
static void check_threshold(float x, float y, float z)
{
    bool above = (fabsf(x) > THRESHOLD_GYRO ||
                  fabsf(y) > THRESHOLD_GYRO ||
                  fabsf(z) > THRESHOLD_GYRO);

    if (gpioWrite(LED_GPIO, above ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed on LED GPIO %d.\n", LED_GPIO);
    }
}

int main(void)
{
    float x, y, z;
    int   reinit_attempts = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED GPIO %d.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (handle %d).\n",
                I2C_BUS, MPU6050_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 gyroscope reader started. Sampling at 20 Hz, LED on GPIO%d.\n",
           LED_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(&gyro_buffer, x, y, z);
            check_threshold(x, y, z);
            reinit_attempts = 0;
        } else {
