#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 3900000
#define LED_PIN 17
#define BUFFER_SIZE 64
#define GYRO_THRESHOLD 200.0f
#define SAMPLE_PERIOD_US 100000

#define MPU6050_ADDR 0x68
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43

#define GYRO_SCALE 131.0f

typedef struct {
    float x, y, z;
    struct timespec ts;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_read_register(int handle, uint8_t reg, uint8_t *val) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };
    if (spiXfer(handle, tx, rx, 2) != 2) return -1;
    *val = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(int handle, uint8_t reg, uint8_t val) {
    char tx[2] = { (char)(reg & 0x7F), (char)val };
    char rx[2] = { 0, 0 };
    if (spiXfer(handle, tx, rx, 2) != 2) return -1;
    return 0;
}

static int spi_read_burst(int handle, uint8_t reg, uint8_t *buf, int len) {
    char tx[1 + len];
    char rx[1 + len];
    tx[0] = (char)(reg | 0x80);
    memset(tx + 1, 0, len);
    if (spiXfer(handle, tx, rx, 1 + len) != (1 + len)) return -1;
    memcpy(buf, rx + 1, len);
    return 0;
}

static int init_mpu6050(int handle) {
    uint8_t who_am_i = 0;
    if (spi_read_register(handle, MPU6050_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n", who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    if (spi_write_register(handle, MPU6050_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to wake up MPU6050.\n");
        return -1;
    }
    if (spi_write_register(handle, MPU6050_GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to configure gyro range.\n");
        return -1;
    }
    return 0;
}

static int read_gyro_data(int handle, gyro_data_t *data) {
    uint8_t buf[6];
    if (spi_read_burst(handle, MPU6050_GYRO_XOUT_H, buf, 6) != 0) {
        fprintf(stderr, "Error: Failed to read gyro data.\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)raw_x / GYRO_SCALE;
    data->y = (float)raw_y / GYRO_SCALE;
    data->z = (float)raw_z / GYRO_SCALE;
    clock_gettime(CLOCK_MONOTONIC, &data->ts);
    return 0;
}

static void add_to_buffer(const gyro_data_t *data) {
    gyro_buffer[buffer_index] = *data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void blink_led(int pin, int duration_ms) {
    gpioWrite(pin, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(pin, 0);
    gpioDelay(duration_ms * 1000);
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld.%09ld,%.2f,%.2f,%.2f\n",
               gyro_buffer[idx].ts.tv_sec, gyro_buffer[idx].ts.tv_nsec,
               gyro_buffer[idx].x, gyro_buffer[idx].y, gyro_buffer[idx].z);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed (handle=%d).\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (init_mpu6050(spi_handle) != 0) {
        fprintf(stderr, "Error: MPU6050 initialisation failed.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Monitoring gyroscope data... Press Ctrl+C to exit.\n");

    while (running) {
        gyro_data_t data;
        if (read_gyro_data(spi_handle, &data) == 0) {
            add_to_buffer(&data);
            if (fabsf(data.x) > GYRO_THRESHOLD ||
                fabsf(data.y) > GYRO_THRESHOLD ||
                fabsf(data.z) > GYRO_THRESHOLD) {
                blink_led(LED_PIN, 500);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, continuing...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    print_buffer();

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

