#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_PWR_MGMT_2   0x6C

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 21

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0f

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup happens   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an MPU-6050 register                         */
/* ------------------------------------------------------------------ */
static bool mpu_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, value, rc);
        return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6050: wake up, configure sample rate, etc.       */
/* ------------------------------------------------------------------ */
static bool mpu_init(int handle)
{
    /* Wake up the device (clear SLEEP bit) */
    if (!mpu_write_reg(handle, MPU6050_PWR_MGMT_1, 0x00))
        return false;

    /* Sample rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (!mpu_write_reg(handle, MPU6050_SMPLRT_DIV, 0x07))
        return false;

    /* DLPF config = 0 → bandwidth 256 Hz, delay 0 */
    if (!mpu_write_reg(handle, MPU6050_CONFIG, 0x00))
        return false;

    /* Gyro full-scale range ±250 dps (FS_SEL = 0) */
    if (!mpu_write_reg(handle, MPU6050_GYRO_CONFIG, 0x00))
        return false;

    /* Accel full-scale range ±2 g (AFS_SEL = 0) */
    if (!mpu_write_reg(handle, MPU6050_ACCEL_CONFIG, 0x00))
        return false;

    /* Clear sleep mode bit in power management 2 */
    if (!mpu_write_reg(handle, MPU6050_PWR_MGMT_2, 0x00))
        return false;

    return true;
}

/* ------------------------------------------------------------------ */
/* Read 14 bytes of accelerometer + temperature + gyro data            */
/* ------------------------------------------------------------------ */
static bool mpu_read_raw(int handle, int16_t *ax, int16_t *ay,
                         int16_t *az, int16_t *gx, int16_t *gy,
                         int16_t *gz)
{
    char buf[14];
    int rc = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buf, 14);
    if (rc != 14) {
        fprintf(stderr, "I2C block read failed: expected 14 bytes, got %d\n", rc);
        return false;
    }

    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);
    return true;
}

/* ------------------------------------------------------------------ */
/* Convert raw gyro data to degrees per second                         */
/* ------------------------------------------------------------------ */
static float gyro_to_dps(int16_t raw)
{
    /* ±250 dps → 131 LSB per dps */
    return (float)raw / 131.0f;
}

/* ------------------------------------------------------------------ */
/* Convert raw accel data to g                                        */
/* ------------------------------------------------------------------ */
static float accel_to_g(int16_t raw)
{
    /* ±2 g → 16384 LSB per g */
    return (float)raw / 16384.0f;
}

/* ------------------------------------------------------------------ */
/* Compute roll and pitch from accel data                              */
/* ------------------------------------------------------------------ */
static void calculate_roll_pitch(float ax_g, float ay_g, float az_g,
                                  float *roll, float *pitch)
{
    *roll  = atan2f(ay_g, az_g) * 180.0f / (float)M_PI;
    *pitch = atan2f(-ax_g, sqrtf(ay_g * ay_g + az_g * az_g))
             * 180.0f / (float)M_PI;
}

/* ------------------------------------------------------------------ */
/* Append a CSV line to the tilt log file                              */
/* ------------------------------------------------------------------ */
static bool log_tilt(float roll, float pitch)
{
    FILE *fp = fopen("tilt_log.txt", "a");
    if (!fp) {
        perror("fopen(tilt_log.txt)");
        return false;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return false;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);

    if (fclose(fp) != 0) {
        perror("fclose(tilt_log.txt)");
        return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPU-6050 address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (!mpu_init(g_i2c_handle)) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 tilt monitor running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (!mpu_read_raw(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz)) {
            fprintf(stderr, "Sensor read error — continuing\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float ax_g = accel_to_g(ax);
        float ay_g = accel_to_g(ay);
        float az_g = accel_to_g(az);
        float roll, pitch;

        calculate_roll_pitch(ax_g, ay_g, az_g, &roll, &pitch);

        printf("Roll: %7.2f  Pitch: %7.2f\n", roll, pitch);

        if (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        if (!log_tilt(roll, pitch)) {
            fprintf(stderr, "Logging failed — continuing\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* ---- Cleanup ---- */
    gpioWrite(LED_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

