#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x60
#define LED_GPIO       17
#define PROX_THRESHOLD 100
#define LOG_FILE       "biometric_log.txt"
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define SAMPLE_DELAY_MS 100

/* Si1145 register addresses (from datasheet) */
#define REG_PART_ID     0x00
#define REG_REV_ID      0x01
#define REG_SEQ_ID      0x02
#define REG_INT_CFG     0x03
#define REG_IRQ_ENABLE  0x04
#define REG_IRQ_MODE1   0x05
#define REG_IRQ_MODE2   0x06
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE0  0x08
#define REG_MEAS_RATE1  0x09
#define REG_ALS_RATE    0x0A
#define REG_ALS_IR_ADCMUX 0x0F
#define REG_ALS_VIS_ADCMUX 0x10
#define REG_ALS_IR_DATA0  0x22
#define REG_ALS_VIS_DATA0 0x24
#define REG_PS1_DATA0   0x26
#define REG_COMMAND     0x30
#define REG_RESPONSE    0x20

#define CMD_RESET       0x01
#define CMD_PS_FORCE    0x05
#define CMD_ALS_FORCE   0x06
#define CMD_PSALS_FORCE 0x07

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int si1145_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_COMMAND, CMD_RESET) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, REG_HW_KEY, 0x17) < 0) return -1;
    if (i2c_write_reg8(fd, REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ALS_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ALS_IR_ADCMUX, 0x03) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ALS_VIS_ADCMUX, 0x03) < 0) return -1;
    if (i2c_write_reg8(fd, REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_IRQ_MODE2, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_INT_CFG, 0x00) < 0) return -1;

    return 0;
}

static int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    int retries = MAX_RETRIES;
    while (retries > 0) {
        if (i2c_write_reg8(fd, REG_COMMAND, CMD_PSALS_FORCE) < 0) {
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(10000);

        uint8_t als_vis_hi, als_vis_lo, ps1_hi, ps1_lo;
        if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0, &als_vis_hi) < 0) {
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0 + 1, &als_vis_lo) < 0) {
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_read_reg8(fd, REG_PS1_DATA0, &ps1_hi) < 0) {
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_read_reg8(fd, REG_PS1_DATA0 + 1, &ps1_lo) < 0) {
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        *ambient_light = ((uint16_t)als_vis_hi << 8) | als_vis_lo;
        *proximity = ((uint16_t)ps1_hi << 8) | ps1_lo;
        return 0;
    }
    return -1;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Turn off LED */
    if (LED_GPIO >= 0) {
        FILE *fp = fopen("/sys/class/gpio/gpio17/value", "w");
        if (fp) {
            fprintf(fp, "0");
            fclose(fp);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    if (si1145_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    /* Set LED GPIO as output */
    FILE *led_fp = fopen("/sys/class/gpio/export", "w");
    if (led_fp) {
        fprintf(led_fp, "17");
        fclose(led_fp);
        usleep(100000);
    }
    led_fp = fopen("/sys/class/gpio/gpio17/direction", "w");
    if (led_fp) {
        fprintf(led_fp, "out");
        fclose(led_fp);
    }

    while (g_running) {
        uint16_t ambient_light = 0, proximity = 0;
        if (read_sensor_data(g_i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(g_log_fp, ambient_light, proximity);
            if (proximity > PROX_THRESHOLD) {
                led_fp = fopen("/sys/class/gpio/gpio17/value", "w");
                if (led_fp) {
                    fprintf(led_fp, "1");
                    fclose(led_fp);
                }
            } else {
                led_fp = fopen("/sys/class/gpio/gpio17/value", "w");
                if (led_fp) {
                    fprintf(led_fp, "0");
                    fclose(led_fp);
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after retries\n");
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

