        if (fp) {
            fprintf(fp, "0");
            fclose(fp);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    if (si1145_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    /* Set LED GPIO as output */
    FILE *led_fp = fopen("/sys/class/gpio/export", "w");
    if (led_fp) {
        fprintf(led_fp, "17");
        fclose(led_fp);
        usleep(100000);
    }
    led_fp = fopen("/sys/class/gpio/gpio17/direction", "w");
    if (led_fp) {
        fprintf(led_fp, "out");
        fclose(led_fp);
    }

    while (g_running) {
        uint16_t ambient_light = 0, proximity = 0;
        if (read_sensor_data(g_i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(g_log_fp, ambient_light, proximity);
            if (proximity > PROX_THRESHOLD) {
                led_fp = fopen("/sys/class/gpio/gpio17/value", "w");
                if (led_fp) {
                    fprintf(led_fp, "1");
                    fclose(led_fp);
                }
            } else {
                led_fp = fopen("/sys/class/gpio/gpio17/value", "w");
                if (led_fp) {
                    fprintf(led_fp, "0");
                    fclose(led_fp);
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after retries\n");
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

