/*
 * ADXRS290 dual-axis gyroscope reader for Raspberry Pi Zero W.
 *
 * SPI0: CE0 (GPIO8), SCLK (GPIO11), MOSI (GPIO10), MISO (GPIO9)
 * LED:  GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_monitor gyro_monitor.c -lpigpio -lrt
 * Run:    sudo ./gyro_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (BCM 8) */
#define SPI_SPEED_HZ     1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* mode 0, active-low CE */

#define LED_PIN          17         /* BCM 17 */
#define GYRO_THRESHOLD   20.0f      /* deg/s */
#define BUFFER_SIZE      100
#define SAMPLE_PERIOD_US 10000      /* 10 ms */

/* ADXRS290 register addresses (MSB = 1 for read) */
#define REG_XGYRO_OUT    0x01
#define REG_YGYRO_OUT    0x02
#define REG_TEMP_OUT     0x03
#define REG_STATUS       0x04
#define REG_CTRL         0x05
#define REG_ID           0x0F

/* ---- Data structures ---- */
typedef struct {
    struct timespec timestamp;
    float x_rate;
    float y_rate;
} gyro_data_t;

typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

/* ---- Globals ---- */
static int           spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

/* ---- Prototypes ---- */
static int  spi_read_register(uint8_t reg, uint8_t *data, uint8_t len);
static int  spi_write_register(uint8_t reg, uint8_t value);
static int  read_gyro_data(float *x_rate, float *y_rate);
static void add_to_buffer(circular_buffer_t *cb, gyro_data_t data);
static bool check_threshold(float x_rate, float y_rate, float threshold);
static void control_led(int state);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- SPI helpers ---- */
static int spi_read_register(uint8_t reg, uint8_t *data, uint8_t len)
{
    char tx[8];
    char rx[8];

    if (len > 7) {
        fprintf(stderr, "Error: read length %u exceeds max 7\n", len);
        return -1;
    }

    memset(tx, 0, sizeof(tx));
    tx[0] = (char)(reg | 0x80);          /* MSB = 1 for read */
    memset(rx, 0, sizeof(rx));

    if (spiXfer(spi_handle, tx, rx, len + 1) != (int)(len + 1)) {
        fprintf(stderr, "Error: SPI read transfer failed\n");
        return -1;
    }

    memcpy(data, rx + 1, len);
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value)
{
    char tx[2];

    tx[0] = (char)(reg & 0x7F);          /* MSB = 0 for write */
    tx[1] = (char)value;

    if (spiWrite(spi_handle, tx, 2) != 2) {
        fprintf(stderr, "Error: SPI write transfer failed\n");
        return -1;
    }
    return 0;
}

/* ---- Gyro read ---- */
static int read_gyro_data(float *x_rate, float *y_rate)
{
    uint8_t x_raw[2], y_raw[2];

    if (spi_read_register(REG_XGYRO_OUT, x_raw, 2) != 0)
        return -1;
    if (spi_read_register(REG_YGYRO_OUT, y_raw, 2) != 0)
        return -1;

    int16_t x_raw16 = (int16_t)((x_raw[1] << 8) | x_raw[0]);
    int16_t y_raw16 = (int16_t)((y_raw[1] << 8) | y_raw[0]);

    *x_rate = (float)x_raw16 / 32768.0f * 2000.0f;   /* 16-bit signed, 1 deg/s LSB */
    *y_rate = (float)y_raw16 / 32768.0f * 2000.0f;

    return 0;
}

/* ---- Circular buffer ---- */
static void add_to_buffer(circular_buffer_t *cb, gyro_data_t data)
{
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE)
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    else
        cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

/* ---- Threshold check ---- */
static bool check_threshold(float x_rate, float y_rate, float threshold)
{
    return (fabsf(x_rate) > threshold || fabsf(y_rate) > threshold);
}

/* ---- LED control ---- */
static void control_led(int state)
{
    if (gpioWrite(LED_PIN, state) != 0)
        fprintf(stderr, "Warning: gpioWrite(LED) failed\n");
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    control_led(0);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    gpioTerminate();
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_led(0);

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED_HZ, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz)\n",
                SPI_CHANNEL, SPI_SPEED_HZ);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    memset(&gyro_buffer, 0, sizeof(gyro_buffer));
    if (pthread_mutex_init(&gyro_buffer.mutex, NULL) != 0) {
        fprintf(stderr, "Error: mutex init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXRS290 gyroscope monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        float x_rate, y_rate;

        if (read_gyro_data(&x_rate, &y_rate) != 0) {
            fprintf(stderr, "Error: gyro read failed\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
            perror("clock_gettime");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        gyro_data_t data = { .timestamp = ts, .x_rate = x_rate, .y_rate = y_rate };
        add_to_buffer(&gyro_buffer, data);

        if (check_threshold(x_rate, y_rate, GYRO_THRESHOLD))
            control_led(1);
        else
            control_led(0);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    pthread_mutex_destroy(&gyro_buffer.mutex);
    return EXIT_SUCCESS;
}

