    /* Initialize circular buffer */
    memset(&gyro_buffer, 0, sizeof(gyro_buffer));
    if (pthread_mutex_init(&gyro_buffer.mutex, NULL) != 0) {
        fprintf(stderr, "Error: mutex init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXRS290 gyroscope monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        float x_rate, y_rate;

        if (read_gyro_data(&x_rate, &y_rate) != 0) {
            fprintf(stderr, "Error: gyro read failed\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
            perror("clock_gettime");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        gyro_data_t data = { .timestamp = ts, .x_rate = x_rate, .y_rate = y_rate };
        add_to_buffer(&gyro_buffer, data);

        if (check_threshold(x_rate, y_rate, GYRO_THRESHOLD))
            control_led(1);
        else
            control_led(0);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    pthread_mutex_destroy(&gyro_buffer.mutex);
    return EXIT_SUCCESS;
}

