        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", LAMP3_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_lamp_brightness(int pin, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(pin, brightness);
}

