        fprintf(stderr, "  duration_seconds: integer 1-3600\n");
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0') {
        fprintf(stderr, "Error: '%s' is not a valid integer.\n", argv[1]);
        return EXIT_FAILURE;
    }

    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: duration must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator\n");
    printf("Lamp 1: GPIO%d | Lamp 2: GPIO%d | Lamp 3: GPIO%d\n",
           LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);
    printf("Fade duration: %ld seconds\n", duration);
    printf("Press Ctrl+C to interrupt at any time.\n");

    int lamp_pins[] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    int num_lamps = (int)(sizeof(lamp_pins) / sizeof(lamp_pins[0]));

    for (int i = 0; i < num_lamps; i++) {
        set_lamp_brightness(lamp_pins[i], PWM_RANGE);
    }

    printf("Starting sunset simulation...\n");

    for (long elapsed = 0; elapsed < duration && g_running; elapsed++) {
        for (int i = 0; i < num_lamps && g_running; i++) {
            int brightness = (int)(((float)elapsed / duration) * PWM_RANGE);
            set_lamp_brightness(lamp_pins[i], brightness);
            printf("Lamp %d: brightness %d/%d (%.1f%%)\n",
                   i + 1, brightness, PWM_RANGE,
                   (brightness / (float)PWM_RANGE) * 100.0);
        }
        time_sleep(1);
    }

    if (g_running) {
        printf("Sunset complete!\n");
    } else {
        printf("\nInterrupted by signal. Turning off lamps and exiting.\n");
    }

    cleanup();
    return EXIT_SUCCESS;
}

