/*
 * traffic_light.c — Raspberry Pi 4 Model B
 *
 * Four 5V relay modules (active-low) on BCM GPIO17, 22, 23, 24.
 * Sequence: red 10 s, red+yellow 2 s, green 10 s, yellow 3 s, repeat.
 * Relays are active-low: LOW energizes relay, HIGH de-energizes.
 *
 * Build:  gcc -O2 -Wall -Wextra -o traffic_light traffic_light.c -lgpiod
 * Run:    ./traffic_light
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define NUM_RELAYS 4
#define CONSUMER   "traffic-light"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};

/* Active-low: LOW energizes relay, HIGH de-energizes. */
static const int relay_levels[NUM_RELAYS] = {0, 0, 0, 0};

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_seconds(unsigned int seconds)
{
    for (unsigned int i = 0; i < seconds && g_running; ++i)
        sleep(1);
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running)
        ;
}

static void all_relays_off(struct gpiod_line *lines[NUM_RELAYS])
{
    for (int i = 0; i < NUM_RELAYS; ++i) {
        if (lines[i]) {
            if (gpiod_line_set_value(lines[i], 1) < 0)   /* HIGH de-energizes */
                fprintf(stderr, "Warning: failed to de-energize relay %u: %s\n",
                        relay_pins[i], strerror(errno));
        }
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS] = {NULL};
    int rc = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the default gpiochip (gpiochip0 on Pi 4) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Request each relay line as output, initial HIGH (de-energized) --- */
    for (int i = 0; i < NUM_RELAYS; ++i) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u): %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], CONSUMER, 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u): %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Traffic light simulation started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main cycle loop --- */
    while (g_running) {
        /* RED: 10 s */
        for (int i = 0; i < NUM_RELAYS && g_running; ++i)
            if (gpiod_line_set_value(lines[i], relay_levels[i]) < 0)
                fprintf(stderr, "set RED relay %u: %s\n", relay_pins[i], strerror(errno));
        if (g_running) {
            printf("RED\n");
            fflush(stdout);
            sleep_seconds(10);
        }

        /* RED + YELLOW: 2 s */
        if (g_running) {
            for (int i = 0; i < NUM_RELAYS && g_running; ++i)
                if (gpiod_line_set_value(lines[i], 1 - relay_levels[i]) < 0)
                    fprintf(stderr, "set RED+YELLOW relay %u: %s\n", relay_pins[i], strerror(errno));
            printf("RED + YELLOW\n");
            fflush(stdout);
            sleep_seconds(2);
        }

        /* GREEN: 10 s */
        if (g_running) {
            for (int i = 0; i < NUM_RELAYS && g_running; ++i)
                if (gpiod_line_set_value(lines[i], relay_levels[i]) < 0)
                    fprintf(stderr, "set GREEN relay %u: %s\n", relay_pins[i], strerror(errno));
            printf("GREEN\n");
            fflush(stdout);
            sleep_seconds(10);
        }

        /* YELLOW: 3 s */
        if (g_running) {
            for (int i = 0; i < NUM_RELAYS && g_running; ++i)
                if (gpiod_line_set_value(lines[i], 1 - relay_levels[i]) < 0)
                    fprintf(stderr, "set YELLOW relay %u: %s\n", relay_pins[i], strerror(errno));
            printf("YELLOW\n");
            fflush(stdout);
            sleep_seconds(3);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    all_relays_off(lines);
    for (int i = 0; i < NUM_RELAYS; ++i) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    if (rc == EXIT_SUCCESS)
        printf("\nTraffic light simulation stopped.\n");
    return rc;
}

