#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define POLL_INTERVAL_US 10000
#define LOG_FILE "touch_relay.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE0_TOUCHTHRESHOLD 0x41
#define MPR121_ELECTRODE0_RELEASETHRESHOLD 0x42
#define MPR121_ELECTRODECONFIG 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_error(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_error(msg);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_ELECTRODECONFIG, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ELECTRODE0_TOUCHTHRESHOLD, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_ELECTRODE0_RELEASETHRESHOLD, 0x05) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    int low = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) {
        log_error("Failed to read touch status low byte");
        return -1;
    }
    int high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) {
        log_error("Failed to read touch status high byte");
        return -1;
    }
    *status = ((uint16_t)high << 8) | (uint16_t)low;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioSetMode(RELAY_GPIO, PI_INPUT);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C device at 0x%02X on bus %d", MPR121_ADDR, I2C_BUS);
        log_error(msg);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        log_error("MPR121 initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set relay GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t prev_touch = 0;
    uint32_t last_debounce_time = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint32_t now = gpioTick();
        if ((touch_status & 0x01) && (now - last_debounce_time) > (DEBOUNCE_DELAY_MS * 1000)) {
            last_debounce_time = now;
            int current_state = gpioRead(RELAY_GPIO);
            if (gpioWrite(RELAY_GPIO, !current_state) < 0) {
                log_error("Failed to toggle relay GPIO");
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Relay toggled to %s", current_state ? "OFF" : "ON");
                log_error(msg);
            }
        }
        prev_touch = touch_status;
        gpioDelay(POLL_INTERVAL_US);
    }

    log_error("Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

