#define LED_PIN          23
#define CONSECUTIVE_READS 3
#define POLL_INTERVAL_US  50000  /* 50 ms */
#define LOG_FILE          "flame_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", FLAME_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BUZZER_PIN);
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        return -1;
    }

    /* Ensure buzzer and LED are off at start */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d.\n", BUZZER_PIN);
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d.\n", LED_PIN);
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void)
{
    int level = gpioRead(FLAME_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d.\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return level;
}

static void log_flame_detection(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(log_file, "%s: Flame Detected\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed.\n");
    }
}

static void activate_alert(void)
{
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate buzzer.\n");
    }
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate LED.\n");
    }
}

static void deactivate_alert(void)
{
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate buzzer.\n");
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate LED.\n");
    }
}

static void cleanup(void)
{
    deactivate_alert();

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error: failed to close log file.\n");
        }
        log_file = NULL;
    }

    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    int consecutive_reads = 0;
    int flame_active = 0;

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            break;
        }

        if (sensor_value == 0) {
            consecutive_reads++;
            if (consecutive_reads >= CONSECUTIVE_READS) {
                if (!flame_active) {
                    printf("Flame detected!\n");
                    log_flame_detection();
                    activate_alert();
                    flame_active = 1;
                }
            }
        } else {
            consecutive_reads = 0;
            if (flame_active) {
                deactivate_alert();
                flame_active = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

