#define DISPENSE_INTERVAL_MS 5000
#define TOTAL_DISPENSE_TIME_MS 1000
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_dispense(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Solenoid 1 (GPIO%d): ON, Solenoid 2 (GPIO%d): ON, Duration: %d ms\n",
            timestamp, solenoid1_pin, solenoid2_pin, duration_ms);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error activating solenoid on GPIO%d\n", pin);
