#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

/* Motor A pins */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define ENA 24

/* Motor B pins */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENB 25

/* PID parameters */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Obstacle avoidance threshold */
#define OBSTACLE_THRESHOLD 20.0

/* PWM range */
#define PWM_RANGE 255

/* Global variables */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* PID state */
static double integral = 0.0;
static double previous_error = 0.0;

/* Function prototypes */
static int initialize_gpio(void);
static void set_motor_speed(int motor, int speed);
static double calculate_tilt_error(void);
static double calculate_distance(void);
static double pid_control(double error);
static void obstacle_avoidance(double distance);
static void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Initialize GPIO pins using pigpio */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Set motor control pins as outputs */
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    /* Set enable pins as outputs and set HIGH to enable PWM */
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    /* Set PWM range */
    gpioSetPWMrange(ENA, PWM_RANGE);
    gpioSetPWMrange(ENB, PWM_RANGE);

    return 0;
}

/* Set motor speed using pigpio PWM */
static void set_motor_speed(int motor, int speed) {
    if (speed < -PWM_RANGE) speed = -PWM_RANGE;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (motor == 1) {
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENA, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
            gpioPWM(ENA, -speed);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENA, 0);
        }
    } else if (motor == 2) {
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENB, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
            gpioPWM(ENB, -speed);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENB, 0);
        }
    }
}

/* Calculate simulated tilt error (random float between -10.0 and 10.0) */
static double calculate_tilt_error(void) {
    return ((double)rand() / (double)RAND_MAX) * 20.0 - 10.0;
}

/* Calculate simulated distance (random float between 2.0 and 400.0) */
static double calculate_distance(void) {
    return ((double)rand() / (double)RAND_MAX) * 398.0 + 2.0;
}

/* PID control algorithm */
static double pid_control(double error) {
    double proportional = KP * error;
    integral += KI * error;
    double derivative = KD * (error - previous_error);
    double output = proportional + integral + derivative;
    previous_error = error;
    return output;
}

/* Obstacle avoidance logic */
static void obstacle_avoidance(double distance) {
    if (distance < OBSTACLE_THRESHOLD) {
        set_motor_speed(1, -PWM_RANGE / 2);
        set_motor_speed(2, -PWM_RANGE / 2);
    }
}

/* Log data to file */
static void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

/* Cleanup resources */
static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Seed random number generator */
    srand(time(NULL));

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return 1;
    }

    /* Open log file */
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Main control loop */
    while (running) {
        double tilt_error = calculate_tilt_error();
        double distance = calculate_distance();

        double pid_output = pid_control(tilt_error);
        int motor_a_speed = (int)pid_output;
        int motor_b_speed = (int)pid_output;

        set_motor_speed(1, motor_a_speed);
        set_motor_speed(2, motor_b_speed);

        obstacle_avoidance(distance);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioDelay(50000); /* 50ms delay */
    }

    /* Stop motors and cleanup */
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    cleanup();

    return 0;
}

