#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed. "
                        "Is the pigpio daemon running? Stop it first.\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with pull-down */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Read touch sensor state */
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Warning: failed to read GPIO%d.\n", TOUCH_SENSOR_PIN);
            gpioDelay(DEBOUNCE_DELAY_US);
            continue;
        }

        if (touch_state == 1) {
            /* Toggle relay state */
            int current_relay_state = gpioRead(RELAY_PIN);
            if (current_relay_state < 0) {
                fprintf(stderr, "Warning: failed to read relay GPIO%d.\n", RELAY_PIN);
            } else {
                int new_relay_state = !current_relay_state;
                if (gpioWrite(RELAY_PIN, new_relay_state) != 0) {
                    fprintf(stderr, "Warning: failed to write relay GPIO%d.\n", RELAY_PIN);
                } else {
                    printf("Touch detected! Relay toggled to %s.\n",
                           new_relay_state ? "ON" : "OFF");
                }
            }

            /* Debounce delay to prevent immediate retrigger */
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        /* Small delay to prevent busy-waiting */
        gpioDelay(10000); /* 10 ms */
    }

    /* Cleanup: ensure relay is OFF and release pigpio resources */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

