/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Captures 8000 Hz 16-bit mono audio via ALSA, computes RMS amplitude,
 * and drives a common-cathode RGB LED on GPIO17/18/27 (BCM) via
 * software PWM using the pigpio driver library.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lm
 * Run:    sudo ./mood_light [sensitivity]
 *
 * ALSA_AVAILABLE is a compile-time guard so the ALSA-dependent code
 * does not appear in builds where libasound2-dev is not installed.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

/* ---- Audio parameters ---- */
#define SAMPLE_RATE     8000
#define PERIOD_FRAMES   1024
#define NUM_CHANNELS    1
#define BITS_PER_SAMPLE 16

/* ---- LED parameters ---- */
#define PWM_RANGE       255
#define PWM_FREQ        1000   /* Hz — common-cathode LED */

/* ---- Sensitivity (default 1.0) ---- */
static double sensitivity = 1.0;

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t running = 1;
static int pigpio_initialized = 0;
static int alsa_initialized   = 0;
static snd_pcm_t *pcm_handle  = NULL;

/* ---- Function prototypes ---- */
static void signal_handler(int sig);
static int  init_gpio(void);
static int  init_alsa(void);
static void cleanup(void);
static double compute_rms(const short *buffer, int n);
static void set_led_color(double rms);
static void simulate_audio(double *rms_out);

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure software PWM pins                  */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return -1;
    }

    /* Software PWM: range 0..PWM_RANGE, frequency PWM_FREQ Hz */
    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return -1;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return -1;
    }

    /* Start with LED off */
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize ALSA capture device                                    */
/* ------------------------------------------------------------------ */
static int init_alsa(void)
{
    int err;
    snd_pcm_hw_params_t *hw;
    snd_pcm_sw_params_t *sw;

    err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(err));
        return -1;
    }
    alsa_initialized = 1;

    snd_pcm_hw_params_alloca(&hw);
    snd_pcm_sw_params_alloca(&sw);

    err = snd_pcm_hw_params_any(pcm_handle, hw);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_any failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_access(pcm_handle, hw, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_format(pcm_handle, hw, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_channels(pcm_handle, hw, NUM_CHANNELS);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw, &SAMPLE_RATE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_period_size_near(pcm_handle, hw, &PERIOD_FRAMES, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_period_size_near failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params(pcm_handle, hw);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_sw_params_current(pcm_handle, sw);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_sw_params_current failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_sw_params_set_start_threshold(pcm_handle, sw, PERIOD_FRAMES);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_sw_params_set_start_threshold failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_sw_params_set_avail_min(pcm_handle, sw, PERIOD_FRAMES);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_sw_params_set_avail_min failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_sw_params(pcm_handle, sw);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_sw_params failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_prepare(pcm_handle);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute RMS amplitude of a 16-bit mono PCM buffer                  */
/* ------------------------------------------------------------------ */
static double compute_rms(const short *buffer, int n)
{
    double sum_sq = 0.0;
    for (int i = 0; i < n; i++) {
        double v = (double)buffer[i] / (double)INT16_MAX;
        sum_sq += v * v;
    }
    return sqrt(sum_sq / (double)n);
}

/* ------------------------------------------------------------------ */
/* Map RMS amplitude to RGB color (non-linear)                        */
/* ------------------------------------------------------------------ */
static void set_led_color(double rms)
{
    double scaled = rms * sensitivity;

    /* Non-linear mapping: 0 -> black, 1 -> white */
    double r = pow(scaled, 0.5);
    double g = pow(scaled, 0.5);
    double b = pow(scaled, 0.5);

    /* Clamp to valid range */
    if (r > 1.0) r = 1.0;
    if (g > 1.0) g = 1.0;
    if (b > 1.0) b = 1.0;

    int r_pwm = (int)(r * PWM_RANGE);
    int g_pwm = (int)(g * PWM_RANGE);
    int b_pwm = (int)(b * PWM_RANGE);

    gpioPWM(RED_PIN,   r_pwm);
    gpioPWM(GREEN_PIN, g_pwm);
    gpioPWM(BLUE_PIN,  b_pwm);
}

/* ------------------------------------------------------------------ */
/* Simulate audio input with a sine wave for offline / no-ALSA runs   */
/* ------------------------------------------------------------------ */
static void simulate_audio(double *rms_out)
{
    static double phase = 0.0;
    const double freq = 0.5;   /* Hz */
    const double inc  = 2.0 * M_PI * freq / (double)SAMPLE_RATE;
    double sum_sq = 0.0;

    for (int i = 0; i < PERIOD_FRAMES; i++) {
        double s = sin(phase);
        double v = s * 0.5;       /* scale to [-0.5, 0.5] */
        sum_sq += v * v;
        phase += inc;
        if (phase > 2.0 * M_PI) phase -= 2.0 * M_PI;
    }

    *rms_out = sqrt(sum_sq / (double)PERIOD_FRAMES);
}

/* ------------------------------------------------------------------ */
/* Release all resources                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (pigpio_initialized) {
        gpioPWM(RED_PIN,   0);
        gpioPWM(GREEN_PIN, 0);
        gpioPWM(BLUE_PIN,  0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (alsa_initialized) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
        alsa_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc > 1) {
        double val = atof(argv[1]);
        if (val > 0.0) {
            sensitivity = val;
            printf("Sensitivity set to: %.2f\n", sensitivity);
        } else {
            fprintf(stderr, "Invalid sensitivity value. Using default: 1.0\n");
        }
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ALSA (optional) */
    int alsa_ok = 0;
    if (init_alsa() == 0) {
        alsa_ok = 1;
        printf("ALSA initialized: %d Hz, %d frames, %d ch\n",
               SAMPLE_RATE, PERIOD_FRAMES, NUM_CHANNELS);
    } else {
        fprintf(stderr, "ALSA initialization failed — continuing with simulated audio.\n");
    }

    printf("Mood light running. Press Ctrl+C to exit.\n");

    short *buffer = malloc(PERIOD_FRAMES * sizeof(short));
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int err;

        if (alsa_ok) {
            err = snd_pcm_readi(pcm_handle, buffer, PERIOD_FRAMES);
            if (err == -EPIPE) {
                /* Buffer overrun — prepare for next period */
                snd_pcm_prepare(pcm_handle);
            } else if (err < 0) {
                fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(err));
                break;
            } else if (err < PERIOD_FRAMES) {
                fprintf(stderr, "Short read: %d frames\n", err);
            }
        }

        double rms;
        if (alsa_ok) {
            rms = compute_rms(buffer, PERIOD_FRAMES);
        } else {
            simulate_audio(&rms);
        }

        set_led_color(rms);

        /* 10 ms delay (pigpio gpioDelay is microseconds) */
        gpioDelay(10000);
    }

    free(buffer);
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

