                fprintf(stderr, "Short read: %d frames\n", err);
            }
        }

        double rms;
        if (alsa_ok) {
            rms = compute_rms(buffer, PERIOD_FRAMES);
        } else {
            simulate_audio(&rms);
        }

        set_led_color(rms);

        /* 10 ms delay (pigpio gpioDelay is microseconds) */
        gpioDelay(10000);
    }

    free(buffer);
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

