/*
 * TCS34725 color sensor logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TCS34725 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   TCS34725 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   TCS34725 VDD  -> 3.3 V
 *   TCS34725 GND  -> GND
 *   TCS34725 INT  -> (optional, not used here)
 *
 * Build:  gcc -O2 -Wall -Wextra -o color_logger color_logger.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- TCS34725 register definitions (command bit 0x80) ---- */
#define TCS34725_I2C_ADDR        0x29
#define TCS34725_CMD_BIT         0x80

#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_ID              0x12
#define TCS34725_CDATAL          0x14
#define TCS34725_CDATAH          0x15
#define TCS34725_RDATAL          0x16
#define TCS34725_RDATAH          0x17
#define TCS34725_GDATAL          0x18
#define TCS34725_GDATAH          0x19
#define TCS34725_BDATAL          0x1A
#define TCS34725_BDATAH          0x1B

#define TCS34725_ENABLE_PON      0x01
#define TCS34725_ENABLE_AEN      0x02
#define TCS34725_ENABLE_PD       0x10

#define TCS34725_ATIME_154MS     0xDB  /* 154 ms integration, 2.4 ms step */

#define I2C_BUS                 "/dev/i2c-1"
#define CSV_FILENAME            "color_data.csv"
#define SAMPLE_PERIOD_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_CMD_BIT), val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_byte(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    uint8_t cmd = (uint8_t)(reg | TCS34725_CMD_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_read_block write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block read(0x%02X, %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_block(fd, TCS34725_ID, &id, 1) != 0)
        return -1;
    if (id != 0x44 && id != 0x4D) {
        fprintf(stderr, "Unexpected TCS34725 ID 0x%02X (expected 0x44 or 0x4D)\n", id);
        return -1;
    }

    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0)
        return -1;
    usleep(3000);  /* power-on delay */

    if (i2c_write_byte(fd, TCS34725_ATIME, TCS34725_ATIME_154MS) != 0)
        return -1;

    if (i2c_write_byte(fd, TCS34725_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0)
        return -1;

    return 0;
}

static int tcs34725_read(int fd, uint16_t *r, uint16_t *g,
                          uint16_t *b, uint16_t *c)
{
    uint8_t buf[8];
    if (i2c_read_block(fd, TCS34725_CDATAL, buf, sizeof(buf)) != 0)
        return -1;

    *c = (uint16_t)((buf[1] << 8) | buf[0]);
    *r = (uint16_t)((buf[3] << 8) | buf[2]);
    *g = (uint16_t)((buf[5] << 8) | buf[4]);
    *b = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

static void log_data(FILE *fp, uint16_t r, uint16_t g,
                     uint16_t b, uint16_t c)
{
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, r, g, b, c);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                TCS34725_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(CSV_FILENAME, "w");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    fprintf(fp, "timestamp,c,r,g,b\n");

    while (g_running) {
        uint16_t r, g, b, c;
        if (tcs34725_read(fd, &r, &g, &b, &c) == 0) {
            log_data(fp, r, g, b, c);
        } else {
            fprintf(stderr, "Sensor read failed; logging zeros.\n");
            log_data(fp, 0, 0, 0, 0);
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PD);
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

