#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 10080

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO pin %d\n", pin);
        return -1;
    }
    return 0;
}

int control_lamp(int pin, int duration, int phase) {
    int start_time = time(NULL);
    int elapsed_time;
    int duty_cycle;
    int current_state = 0;

    while ((elapsed_time = time(NULL) - start_time) < duration && program_running) {
        duty_cycle = (int)(((float)elapsed_time / duration) * 100.0);
        if (phase == 0) {
            duty_cycle = 100 - duty_cycle;
        }
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        if (duty_cycle > 50) {
            if (current_state == 0) {
                if (set_relay(pin, 1) != 0) return -1;
                current_state = 1;
            }
        } else {
            if (current_state == 1) {
                if (set_relay(pin, 0) != 0) return -1;
                current_state = 0;
            }
        }
        gpioDelay(100000);
    }

    if (current_state == 1) {
        if (set_relay(pin, 0) != 0) return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        if (control_lamp(RELAY1_PIN, SUNRISE_DURATION, 0) != 0) break;
        if (control_lamp(RELAY2_PIN, SUNRISE_DURATION, 0) != 0) break;
        if (control_lamp(RELAY3_PIN, SUNRISE_DURATION, 0) != 0) break;
        if (control_lamp(RELAY4_PIN, SUNRISE_DURATION, 0) != 0) break;

        if (!program_running) break;

        if (control_lamp(RELAY1_PIN, DAYTIME_DURATION, 1) != 0) break;
        if (control_lamp(RELAY2_PIN, DAYTIME_DURATION, 1) != 0) break;
        if (control_lamp(RELAY3_PIN, DAYTIME_DURATION, 1) != 0) break;
        if (control_lamp(RELAY4_PIN, DAYTIME_DURATION, 1) != 0) break;

        if (!program_running) break;

        if (control_lamp(RELAY1_PIN, SUNSET_DURATION, 0) != 0) break;
        if (control_lamp(RELAY2_PIN, SUNSET_DURATION, 0) != 0) break;
        if (control_lamp(RELAY3_PIN, SUNSET_DURATION, 0) != 0) break;
        if (control_lamp(RELAY4_PIN, SUNSET_DURATION, 0) != 0) break;

        if (!program_running) break;

        if (control_lamp(RELAY1_PIN, NIGHTTIME_DURATION, 1) != 0) break;
        if (control_lamp(RELAY2_PIN, NIGHTTIME_DURATION, 1) != 0) break;
        if (control_lamp(RELAY3_PIN, NIGHTTIME_DURATION, 1) != 0) break;
        if (control_lamp(RELAY4_PIN, NIGHTTIME_DURATION, 1) != 0) break;
    }

    set_relay(RELAY1_PIN, 0);
    set_relay(RELAY2_PIN, 0);
    set_relay(RELAY3_PIN, 0);
    set_relay(RELAY4_PIN, 0);

    gpioTerminate();
    return 0;
}

