#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPU6050_ADDR        0x68
#define PWR_MGMT_1          0x6B
#define GYRO_CONFIG         0x1B
#define GYRO_XOUT_H         0x43
#define GYRO_YOUT_H         0x45
#define GYRO_ZOUT_H         0x47
#define SAMPLE_RATE_HZ      100
#define SAMPLE_PERIOD_US    (1000000 / SAMPLE_RATE_HZ)
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_mpu6050(void) {
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake MPU6050 (PWR_MGMT_1).\n");
        return -1;
    }
    gpioDelay(100000);
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to configure gyro range.\n");
        return -1;
    }
    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyro data block.\n");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, double timestamp, int16_t x, int16_t y, int16_t z) {
    fprintf(fp, "%.3f,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X.\n", MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU6050 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open gyro_log.csv for writing.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    while (running) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
            log_data(log_file, timestamp, x, y, z);
        } else {
            fprintf(stderr, "Warning: I2C read failed, attempting re-initialisation...\n");
            int attempts = 0;
            while (attempts < MAX_REINIT_ATTEMPTS && running) {
                if (init_mpu6050() == 0) break;
                attempts++;
                fprintf(stderr, "Warning: Re-init attempt %d/%d failed.\n", attempts, MAX_REINIT_ATTEMPTS);
                gpioDelay(100000);
            }
            if (attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Error: Max re-init attempts reached, logging error and continuing.\n");
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
                fprintf(log_file, "%.3f,ERROR,I2C_READ_FAILURE\n", timestamp);
                fflush(log_file);
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

