#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH.\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return (rand() % 100) + 1;
}

static void control_relay(int pin, int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(pin, 0);
    } else {
        gpioWrite(pin, 1);
    }
}

static void log_data(int sensor_reading, int relay1_state, int relay2_state,
                     int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
                timestamp, sensor_reading,
                relay1_state ? "ON" : "OFF",
                relay2_state ? "ON" : "OFF",
                relay3_state ? "ON" : "OFF",
                relay4_state ? "ON" : "OFF");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: log file is not open.\n");
    }
}

static void cleanup(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioWrite(pins[i], 1);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int sensor_reading = read_moisture_sensor();
        int relay1_state = (sensor_reading < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay2_state = (sensor_reading < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay3_state = (sensor_reading < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay4_state = (sensor_reading < MOISTURE_THRESHOLD) ? 0 : 1;

        control_relay(RELAY1_PIN, sensor_reading);
        control_relay(RELAY2_PIN, sensor_reading);
        control_relay(RELAY3_PIN, sensor_reading);
        control_relay(RELAY4_PIN, sensor_reading);

        log_data(sensor_reading, relay1_state, relay2_state, relay3_state, relay4_state);

        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return 0;
}

