/*
 * ADXL345 Free-Fall Detector for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   ADXL345 VDD  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   Alarm LED    -> GPIO27 (with appropriate series resistor)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -lpigpio -lrt
 * Run:
 *   sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants (verified against datasheet) ---- */
#define ADXL345_ADDRESS        0x53
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_DATA_FORMAT    0x31
#define ADXL345_DATAX0         0x32
#define ADXL345_DEVID          0x00
#define ADXL345_EXPECTED_DEVID 0xE5

/* ---- Free-fall detection thresholds ---- */
#define FREEFALL_THRESHOLD_G   0.2f   /* 0.2 g */
#define FREEFALL_CONFIRM_MS    500    /* 0.5 s */
#define FREEFALL_ASSERT_MS     5000   /* 5 s  */
#define POLL_INTERVAL_MS       100    /* 0.1 s */

/* ---- GPIO / timing ---- */
#define ALARM_GPIO             27
#define I2C_BUS                1
#define LOG_FILE               "freefall.log"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; returns 0 on success.        */
static int adxl_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; returns 0 on success.       */
static int adxl_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data starting at DATAX0.               */
static int adxl_read_xyz(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed: %d (expected 6)\n", rc);
        return -1;
    }

    /* ADXL345 outputs little-endian two's-complement 16-bit values. */
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* Full-resolution default: 4 mg/LSB => 0.004 g/LSB */
    *x = (float)raw_x * 0.004f;
    *y = (float)raw_y * 0.004f;
    *z = (float)raw_z * 0.004f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, set full resolution mode. */
static int adxl_init(int handle)
{
    uint8_t devid = 0;
    if (adxl_read_reg(handle, ADXL345_DEVID, &devid) != 0)
        return -1;
    if (devid != ADXL345_EXPECTED_DEVID) {
        fprintf(stderr, "[ERROR] Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_EXPECTED_DEVID);
        return -1;
    }

    /* DATA_FORMAT: 0x0B = full resolution, +/-200 g, right-justified */
    if (adxl_write_reg(handle, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* POWER_CTL: 0x08 = measure mode (clear standby bit) */
    if (adxl_write_reg(handle, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a free-fall event to CSV.                                       */
static int log_freefall(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Assert the alarm GPIO for FREEFALL_ASSERT_MS milliseconds.          */
static void alarm_assert(void)
{
    if (gpioWrite(ALARM_GPIO, 1) < 0)
        fprintf(stderr, "[WARN] gpioWrite(ALARM, 1) failed\n");

    /* gpioDelay is microseconds; 5 s => 5000000 us */
    gpioDelay(FREEFALL_ASSERT_MS * 1000);

    if (gpioWrite(ALARM_GPIO, 0) < 0)
        fprintf(stderr, "[WARN] gpioWrite(ALARM, 0) failed\n");
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADXL345_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (adxl_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed\n", ALARM_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("ADXL345 free-fall detector running.  Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float x, y, z;

        if (adxl_read_xyz(g_i2c_handle, &x, &y, &z) != 0) {
            /* I2C error: back off briefly and retry. */
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        /* Free-fall: all axes below threshold for FREEFALL_CONFIRM_MS. */
        bool ff1 = (fabsf(x) < FREEFALL_THRESHOLD_G &&
                    fabsf(y) < FREEFALL_THRESHOLD_G &&
                    fabsf(z) < FREEFALL_THRESHOLD_G);

        if (ff1) {
            gpioDelay(FREEFALL_CONFIRM_MS * 1000);

            if (!g_running)
                break;

            if (adxl_read_xyz(g_i2c_handle, &x, &y, &z) != 0)
                continue;

            bool ff2 = (fabsf(x) < FREEFALL_THRESHOLD_G &&
                        fabsf(y) < FREEFALL_THRESHOLD_G &&
                        fabsf(z) < FREEFALL_THRESHOLD_G);

            if (ff2) {
                printf("[FREEFALL] X=%.3f Y=%.3f Z=%.3f g — alarm asserted\n",
                       x, y, z);
                if (log_freefall(x, y, z) != 0)
                    fprintf(stderr, "[WARN] Failed to log free-fall event\n");
                alarm_assert();
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioWrite(ALARM_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

