#define ECHO_TIMEOUT_US 23000
#define MAX_VALID_US  23000
#define MAX_VALID_CM  4.0
#define TIMEOUT_NS    100000000ULL
#define TICK_US       4294967296ULL

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static pthread_mutex_t g_mtx = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    uint32_t start_tick;
    uint32_t pulse_us;
    int      valid;
} echo_ctx_t;

static echo_ctx_t g_echo = {0, 0, 0};

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint64_t tick_diff(uint32_t start, uint32_t end) {
    uint64_t d = (uint64_t)(end - start);
    return d;
}

static void trig_pulse(void) {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

static void echo_rise(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pthread_mutex_lock(&g_mtx);
        g_echo.start_tick = tick;
        g_echo.valid = 0;
        pthread_mutex_unlock(&g_mtx);
    }
}

static void echo_fall(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        uint32_t start = 0;
        uint32_t dur   = 0;
        int      v     = 0;
        pthread_mutex_lock(&g_mtx);
        start = g_echo.start_tick;
        dur   = tick - start;
        v     = (dur > 0 && dur <= MAX_VALID_US) ? 1 : 0;
        g_echo.pulse_us = dur;
        g_echo.valid    = v;
        pthread_mutex_unlock(&g_mtx);
    }
}

static void log_reading(uint64_t ts_ns, double dist_cm) {
    if (g_log) {
        fprintf(g_log, "%llu,%.2f\n", (unsigned long long)ts_ns, dist_cm);
        fflush(g_log);
    }
}

static void log_error(uint64_t ts_ns, const char *msg) {
    if (g_log) {
        fprintf(g_log, "%llu,ERROR,%s\n", (unsigned long long)ts_ns, msg);
        fflush(g_log);
    }
    fprintf(stderr, "[%llu] ERROR: %s\n", (unsigned long long)ts_ns, msg);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIG_PIN %d as output\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(100000);

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_rise, NULL) != 0) {
        fprintf(stderr, "Failed to set rising edge ISR on ECHO_PIN %d\n", ECHO_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_fall, NULL) != 0) {
        fprintf(stderr, "Failed to set falling edge ISR on ECHO_PIN %d\n", ECHO_PIN);
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint64_t ts_ns = (uint64_t)time_time() * 1000000000ULL;
        uint32_t start_tick = gpioTick();

        trig_pulse();

        uint32_t elapsed = 0;
        int      got     = 0;
        pthread_mutex_lock(&g_mtx);
        g_echo.valid = 0;
        pthread_mutex_unlock(&g_mtx);

        uint32_t now = gpioTick();
        uint32_t deadline = start_tick + ECHO_TIMEOUT_US;
        while (now < deadline && g_running) {
            if (g_echo.valid) {
                got = 1;
                break;
            }
            gpioDelay(100);
            now = gpioTick();
        }

        pthread_mutex_lock(&g_mtx);
        uint32_t pulse_us = g_echo.pulse_us;
        int      valid    = g_echo.valid;
        pthread_mutex_unlock(&g_mtx);

        if (got) {
            double dist_cm = (double)pulse_us / 58.0;
            if (dist_cm > MAX_VALID_CM) {
                log_error(ts_ns, "Distance exceeds sensor range");
            } else {
                log_reading(ts_ns, dist_cm);
            }
        } else {
            log_error(ts_ns, "Timeout waiting for echo pulse");
        }

        if (g_running) {
            gpioDelay(CYCLE_DELAY_US);
        }
    }

    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioWrite(TRIG_PIN, 0);
    fclose(g_log);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

