/*
 * Impact Detection System using LIS3DH on Raspberry Pi 5
 *
 * Reads acceleration from the Adafruit LIS3DH (I2C address 0x19) on I2C bus 1.
 * Detects free-fall (magnitude < 0.2 g) and impact (magnitude > 1.5 g).
 * On impact, buzzes a buzzer on GPIO17 for 1 second.
 *
 * Build: gcc -O2 -Wall -o impact impact.c -lm
 * Run:   ./impact [freefall_g] [impact_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3DH_ADDR    0x19

/* LIS3DH registers */
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L   0x28
#define LIS3DH_OUT_X_H   0x29
#define LIS3DH_OUT_Y_L   0x2A
#define LIS3DH_OUT_Y_H   0x2B
#define LIS3DH_OUT_Z_L   0x2C
#define LIS3DH_OUT_Z_H   0x2D

#define BUZZER_GPIO      17
#define BUZZER_DURATION  1000000  /* microseconds */
#define SAMPLE_DELAY_US  10000    /* 10 ms */
#define I2C_RETRIES      3
#define I2C_RETRY_DELAY  10000    /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register with retry */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2)
            return 0;
        usleep(I2C_RETRY_DELAY);
    }
    return -1;
}

/* Read a single byte from an 8-bit register with retry */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, value, 1) == 1)
                return 0;
        }
        usleep(I2C_RETRY_DELAY);
    }
    return -1;
}

/* Read a 16-bit little-endian register pair (low then high) */
static int i2c_read_reg16(int fd, uint8_t reg_low, int16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_low, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg_low + 1, &hi) < 0)
        return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

static int init_lis3dh(int fd)
{
    /* CTRL_REG1: 0x27 = 0b0010_0111
     *   ODR=100Hz (0b001), all axes enabled (0b111), normal mode */
    if (i2c_write_reg8(fd, LIS3DH_CTRL_REG1, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }
    /* CTRL_REG4: 0x00 = 0b0000_0000
     *   Full-scale ±2g (default), no high-resolution, no self-test */
    if (i2c_write_reg8(fd, LIS3DH_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG4: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, LIS3DH_OUT_X_L, &raw_x) < 0) {
        fprintf(stderr, "Error: failed to read X axis: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_read_reg16(fd, LIS3DH_OUT_Y_L, &raw_y) < 0) {
        fprintf(stderr, "Error: failed to read Y axis: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_read_reg16(fd, LIS3DH_OUT_Z_L, &raw_z) < 0) {
        fprintf(stderr, "Error: failed to read Z axis: %s\n", strerror(errno));
        return -1;
    }

    /* Convert to g: ±2g full-scale => 16384 LSB/g */
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static void activate_buzzer(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Warning: gpioInitialise() failed; buzzer unavailable.\n");
        return;
    }
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Warning: gpioSetMode(%d) failed.\n", BUZZER_GPIO);
        gpioTerminate();
        return;
    }
    if (gpioWrite(BUZZER_GPIO, 1) < 0)
        fprintf(stderr, "Warning: gpioWrite(%d, 1) failed.\n", BUZZER_GPIO);
    usleep(BUZZER_DURATION);
    if (gpioWrite(BUZZER_GPIO, 0) < 0)
        fprintf(stderr, "Warning: gpioWrite(%d, 0) failed.\n", BUZZER_GPIO);
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    float freefall_threshold = 0.2f;
    float impact_threshold   = 1.5f;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
        if (freefall_threshold <= 0.0f) {
            fprintf(stderr, "Invalid freefall threshold '%s'; using default 0.2 g\n", argv[1]);
            freefall_threshold = 0.2f;
        }
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
        if (impact_threshold <= 0.0f) {
            fprintf(stderr, "Invalid impact threshold '%s'; using default 1.5 g\n", argv[2]);
            impact_threshold = 1.5f;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave 0x%02X: %s\n", LIS3DH_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (init_lis3dh(fd) < 0) {
        fprintf(stderr, "Error: LIS3DH initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Free-fall: %.2f g, Impact: %.2f g. Ctrl+C to exit.\n",
           freefall_threshold, impact_threshold);

    bool in_freefall = false;

    while (g_running) {
        float x, y, z;

        if (read_acceleration(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error: I2C read failed; continuing.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude < freefall_threshold) {
            if (!in_freefall) {
                printf("Free-fall detected!\n");
                in_freefall = true;
            }
        } else if (magnitude > impact_threshold) {
            if (in_freefall) {
                printf("Impact detected!\n");
                in_freefall = false;
                activate_buzzer();
            }
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

