#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x19
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000

#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, strerror(errno));
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
    }
    return rc;
}

static int init_lis3dh(int handle) {
    int who = read_reg(handle, LIS3DH_REG_WHO_AM_I);
    if (who < 0) return -1;
    if (who != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL1: 100 Hz ODR, all axes enabled, normal mode */
    if (write_reg(handle, LIS3DH_REG_CTRL1, 0x57) < 0) return -1;

    /* CTRL4: ±2 g, high-resolution, 12-bit left-justified */
    if (write_reg(handle, LIS3DH_REG_CTRL4, 0x08) < 0) return -1;

    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, LIS3DH_REG_OUT_X_L, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Accelerometer read failed (rc=%d): %s\n", rc, strerror(errno));
        *x = *y = *z = 0.0f;
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    /* ±2 g range, 12-bit left-justified: 4 mg/LSB */
    *x = (float)raw_x * 4.0f / 16384.0f;
    *y = (float)raw_y * 4.0f / 16384.0f;
    *z = (float)raw_z * 4.0f / 16384.0f;
    return 0;
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    } else {
        fprintf(fp, "(unknown time), X: %.2f g, Y: %.2f g, Z: %.2f g\n", x, y, z);
    }
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    float threshold = DEFAULT_THRESHOLD;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2c_address = (int)strtol(argv[i + 1], NULL, 16);
            if (i2c_address < 0x03 || i2c_address > 0x77) {
                fprintf(stderr, "Invalid I2C address: 0x%02X (must be 0x03-0x77)\n", i2c_address);
                return 1;
            }
            i++;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = strtof(argv[i + 1], NULL);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be positive\n");
                return 1;
            }
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_addr_hex] [-t threshold_g]\n", argv[0]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n",
                i2c_address, strerror(errno));
        gpioTerminate();
        return 0;
    }

    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Monitoring acceleration (threshold %.2f g) on I2C 0x%02X...\n", threshold, i2c_address);

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_event(x, y, z);
                printf("High acceleration detected! Logging and shutting down.\n");
                fflush(stdout);
                i2cClose(i2c_handle);
                gpioTerminate();
                system("sudo shutdown -h now");
                return 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

