/*
 * Autonomous Line-Following Robot — SunFounder 3-Way Tracking Sensor
 * Board: Raspberry Pi 5 (BCM GPIO numbering)
 * Sensors: Left=GPIO4, Center=GPIO17, Right=GPIO27
 * Alert: Active-high LED/buzzer on GPIO22
 *
 * Build: gcc -O2 -Wall -Wextra -o line_follow line_follow.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define LEFT_SENSOR_PIN    4
#define CENTER_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define ALERT_PIN          22

#define BUFFER_SIZE        5
#define POLL_DELAY_US      10000   /* 10 ms */
#define ALERT_DURATION_S   2       /* 2 s   */

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    int left[BUFFER_SIZE];
    int center[BUFFER_SIZE];
    int right[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head = 0;
    cb->count = 0;
}

static void cb_push(CircularBuffer *cb, int left, int center, int right)
{
    cb->left[cb->head]  = left;
    cb->center[cb->head] = center;
    cb->right[cb->head] = right;

    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* ------------------------------------------------------------------ */
/* Motor control (placeholder)                                         */
/* ------------------------------------------------------------------ */

static void motor_forward(void)
{
    printf("Motor: forward\n");
}

static void motor_turn_left(void)
{
    printf("Motor: turn left\n");
}

static void motor_turn_right(void)
{
    printf("Motor: turn right\n");
}

static void motor_stop(void)
{
    printf("Motor: stop\n");
}

/* ------------------------------------------------------------------ */
/* GPIO helpers (libgpiod)                                             */
/* ------------------------------------------------------------------ */

#include <gpiod.h>

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(struct gpiod_chip **chip,
                      struct gpiod_line **lines, const int pins[3])
{
    *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!*chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(*chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n",
                    pins[i], strerror(errno));
            return -1;
        }
    }

    /* Request sensor lines as inputs */
    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_input(lines[i], "line_follow") < 0) {
            fprintf(stderr, "Failed to request line %d as input: %s\n",
                    pins[i], strerror(errno));
            return -1;
        }
    }

    /* Request alert line as output, initial value LOW */
    if (gpiod_line_request_output(lines[3], "line_follow", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                pins[3], strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip,
                         struct gpiod_line *lines[4])
{
    if (chip) {
        for (int i = 0; i < 4; i++) {
            if (lines[i])
                gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct gpiod_chip  *chip  = NULL;
    struct gpiod_line  *lines[4];
    CircularBuffer     buffer;
    int                pins[4] = {LEFT_SENSOR_PIN, CENTER_SENSOR_PIN,
                                 RIGHT_SENSOR_PIN, ALERT_PIN};
    int                ret;

    for (int i = 0; i < 4; i++)
        lines[i] = NULL;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    ret = init_gpio(&chip, lines, pins);
    if (ret < 0) {
        cleanup_gpio(chip, lines);
        return EXIT_FAILURE;
    }

    cb_init(&buffer);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int left  = gpiod_line_get_value(lines[0]);
        int center = gpiod_line_get_value(lines[1]);
        int right  = gpiod_line_get_value(lines[2]);

        /* Sensor read failure — log and continue */
        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "GPIO read error: left=%d center=%d right=%d\n",
                    left, center, right);
            usleep(POLL_DELAY_US);
            continue;
        }

        cb_push(&buffer, left, center, right);

        /* Alert logic: center sensor reads HIGH (no line) for 5 consecutive
         * readings — sound alert for ALERT_DURATION_S seconds. */
        int alert_active = 0;
        if (buffer.count == BUFFER_SIZE) {
            int sum = 0;
            for (int i = 0; i < BUFFER_SIZE; i++)
                sum += buffer.center[i];
            if (sum == 0) {
                alert_active = 1;
                if (gpiod_line_set_value(lines[3], 1) < 0) {
                    fprintf(stderr, "Failed to set alert HIGH: %s\n",
                            strerror(errno));
                }
            }
        }

        if (alert_active) {
            /* Keep alert on for ALERT_DURATION_S seconds, but wake up
             * every 100 ms to check g_running so we can exit promptly. */
            for (int elapsed = 0; elapsed < ALERT_DURATION_S * 10 && g_running;
                 elapsed++) {
                usleep(100000);
            }
            if (g_running && gpiod_line_set_value(lines[3], 0) < 0) {
                fprintf(stderr, "Failed to set alert LOW: %s\n",
                        strerror(errno));
            }
        } else {
            /* Line detected: center LOW (logic 0) */
            if (center == 0) {
                if (left == 0)
                    motor_turn_left();
                else if (right == 0)
                    motor_turn_right();
                else
                    motor_forward();
            } else {
                motor_stop();
            }
        }

        usleep(POLL_DELAY_US);
    }

    /* Ensure alert is off */
    if (lines[3])
        gpiod_line_set_value(lines[3], 0);

    cleanup_gpio(chip, lines);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

