/*
 * Si7210 I2C Hall Effect Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Si7210 at I2C address 0x48
 * Relay:  GPIO17 (BCM), active high
 *
 * Build:  gcc -O2 -Wall -o si7210_monitor si7210_monitor.c -li2c -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define SI7210_ADDR      0x48
#define SI7210_REG_HR    0x00   /* Magnetic field data register */
#define SI7210_REG_SR   0x01   /* Status register */
#define SI7210_REG_CR   0x02   /* Control register */
#define SI7210_REG_LR   0x03   /* Limit register */
#define SI7210_REG_HL   0x04   /* Hysteresis register */
#define SI7210_REG_TL   0x05   /* Threshold register */
#define SI7210_REG_HR2  0x06   /* Magnetic field data register (high byte) */

#define RELAY_GPIO       17
#define FIELD_THRESHOLD  5.0f   /* milliTesla */
#define SAMPLE_PERIOD_MS 100
#define POLL_TIMEOUT_MS  50

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si7210 driver                                                      */
/* ------------------------------------------------------------------ */
static int si7210_init(int fd)
{
    /* Software reset: write 0x01 to CR */
    if (i2c_write_reg8(fd, SI7210_REG_CR, 0x01) < 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    /* Clear any stale status bits */
    uint8_t sr;
    if (i2c_read_reg8(fd, SI7210_REG_SR, &sr) < 0)
        return -1;

    /* Default: threshold = 0, hysteresis = 0, limit = 0 */
    if (i2c_write_reg8(fd, SI7210_REG_TL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI7210_REG_HL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI7210_REG_LR, 0x00) < 0) return -1;

    return 0;
}

static int si7210_read_field(int fd, float *field_mT)
{
    uint8_t hr, hr2;
    if (i2c_read_reg8(fd, SI7210_REG_HR,  &hr)  < 0) return -1;
    if (i2c_read_reg8(fd, SI7210_REG_HR2, &hr2) < 0) return -1;

    int16_t raw = (int16_t)((hr2 << 8) | hr);
    *field_mT = (float)raw / 10.0f;  /* 0.1 mT per LSB */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        fprintf(stderr, "Cannot open log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", ts, msg);
    } else {
        fprintf(fp, "(unknown-time) %s\n", msg);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7210_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI7210_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si7210_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si7210 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Relay GPIO setup */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed.\n", RELAY_GPIO);
        gpioTerminate();
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    log_event("System started: Si7210 monitoring started.");

    int relay_state = 0;
    int consecutive_errors = 0;

    while (g_running) {
        float field;
        if (si7210_read_field(g_i2c_fd, &field) < 0) {
            consecutive_errors++;
            log_event("Error: I2C read failed.");
            if (consecutive_errors >= 3) {
                log_event("Error: Too many consecutive I2C failures, aborting.");
                break;
            }
            gpioWrite(RELAY_GPIO, 0);
            relay_state = 0;
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }
        consecutive_errors = 0;

        printf("Field: %.2f mT\n", field);

        if (field > FIELD_THRESHOLD && relay_state == 0) {
            if (gpioWrite(RELAY_GPIO, 1) < 0) {
                log_event("Error: Failed to activate relay.");
            } else {
                relay_state = 1;
                log_event("Relay activated.");
            }
        } else if (field <= FIELD_THRESHOLD && relay_state == 1) {
            if (gpioWrite(RELAY_GPIO, 0) < 0) {
                log_event("Error: Failed to deactivate relay.");
            } else {
                relay_state = 0;
                log_event("Relay deactivated.");
            }
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* Cleanup */
    log_event("System shutting down.");
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    return EXIT_SUCCESS;
}

