#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <ctype.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define TCP_PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { close(server_fd); server_fd = -1; }
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (gpioInitialise() >= 0) {
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    if (client_fd >= 0) { shutdown(client_fd, SHUT_RDWR); }
    if (server_fd >= 0) { shutdown(server_fd, SHUT_RDWR); }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_tcp_server(void) {
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket creation failed");
        return -1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd); server_fd = -1;
        return -1;
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd); server_fd = -1;
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd); server_fd = -1;
        return -1;
    }
    return 0;
}

static void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;
    while ((bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        buffer[strcspn(buffer, "\r\n")] = '\0';
        char *command = buffer;
        while (*command && isspace((unsigned char)*command)) command++;
        if (*command == '\0') continue;
        char *end = command + strlen(command) - 1;
        while (end > command && isspace((unsigned char)*end)) *end-- = '\0';
        if (strcasecmp(command, "ON") == 0) {
            gpioWrite(RELAY_GPIO, 1);
            log_event("Relay turned ON");
            send(client_socket, "OK\n", 3, 0);
        } else if (strcasecmp(command, "OFF") == 0) {
            gpioWrite(RELAY_GPIO, 0);
            log_event("Relay turned OFF");
            send(client_socket, "OK\n", 3, 0);
        } else {
            log_event("Invalid command received");
            send(client_socket, "ERROR: Invalid command\n", 22, 0);
        }
    }
    if (bytes_received < 0) {
        perror("recv failed");
        log_event("Socket read error");
    }
    close(client_socket);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }
    if (init_gpio() != 0) return 1;
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }
    log_event("Relay control server started");
    if (init_tcp_server() != 0) {
        log_event("TCP server initialization failed");
        cleanup();
        return 1;
    }
    printf("Listening on port %d...\n", TCP_PORT);
    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            if (running) perror("accept failed");
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_address.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s:%d\n", client_ip, ntohs(client_address.sin_port));
        handle_client(client_fd);
    }
    log_event("Shutting down");
    cleanup();
    return 0;
}

