/*
 * Raspberry Pi Zero W — dual SLF3S-1300F liquid-flow monitor
 *
 * Sensors : 2 × Sensirion SLF3S-1300F (40 ml/min version)
 *   I2C   : bus 1, addresses 0x64 (sensor 1) and 0x65 (sensor 2)
 * Relay  : GPIO 18 (BCM), active-high
 * Log    : flow_log.txt  (append mode)
 *
 * Build  : gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Configuration ---- */
#define I2C_BUS              "/dev/i2c-1"
#define SENSOR1_ADDR         0x64
#define SENSOR2_ADDR         0x65
#define RELAY_GPIO           18
#define FLOW_THRESHOLD       5.0f   /* ml/min */
#define POLL_DELAY_MS        100
#define LOG_FILE             "flow_log.txt"

/* SLF3S-1300F start-measurement command (two bytes, no final XOR) */
static const uint8_t START_MEAS_CMD[2] = { 0x36, 0x2F };

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd1 = -1;
static int  g_i2c_fd2 = -1;
static int  g_relay_fd = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF, no final XOR) ---- */
static bool crc8_ok(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc == expected;
}

/* ---- I2C helpers ---- */
static int i2c_open(int addr)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "i2c_write_cmd(0x%02X): %s\n",
                cmd[0], strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read 3 bytes from a sensor.
