static int i2c_read_flow(int fd, float *flow_out)
{
    uint8_t buf[3];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_flow: expected 3 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    if (!crc8_ok(buf, 2, buf[2])) {
        fprintf(stderr, "i2c_read_flow: CRC mismatch (calc 0x%02X, got 0x%02X)\n",
