        return -1;
    }
    return 0;
}

/* ---- Logging ---- */
static void log_flow(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld,%.2f,%.2f\n", tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_relay_fd >= 0) {
        (void)relay_set(g_relay_fd, 0);
        close(g_relay_fd);
        g_relay_fd = -1;
    }
    if (g_i2c_fd1 >= 0) { close(g_i2c_fd1); g_i2c_fd1 = -1; }
    if (g_i2c_fd2 >= 0) { close(g_i2c_fd2); g_i2c_fd2 = -1; }
}

