    /* Open relay GPIO */
    g_relay_fd = open("/sys/class/gpio/gpio18/value", O_WRONLY);
    if (g_relay_fd < 0) {
        fprintf(stderr, "open(/sys/class/gpio/gpio18/value): %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C sensors */
    g_i2c_fd1 = i2c_open(SENSOR1_ADDR);
    if (g_i2c_fd1 < 0) { cleanup(); return EXIT_FAILURE; }
    g_i2c_fd2 = i2c_open(SENSOR2_ADDR);
    if (g_i2c_fd2 < 0) { cleanup(); return EXIT_FAILURE; }

    /* Start continuous measurement on both sensors */
    if (i2c_write_cmd(g_i2c_fd1, START_MEAS_CMD, sizeof(START_MEAS_CMD)) < 0) {
        cleanup(); return EXIT_FAILURE;
    }
    if (i2c_write_cmd(g_i2c_fd2, START_MEAS_CMD, sizeof(START_MEAS_CMD)) < 0) {
        cleanup(); return EXIT_FAILURE;
    }

    printf("Monitoring started. Ctrl+C to exit.\n");

    while (g_running) {
