        bool ok1 = (i2c_read_flow(g_i2c_fd1, &f1) == 0);
        bool ok2 = (i2c_read_flow(g_i2c_fd2, &f2) == 0);

        if (!ok1 || !ok2) {
            fprintf(stderr, "Sensor read error — relay unchanged.\n");
        } else {
            log_flow(f1, f2);
            int relay_state = (f1 >= FLOW_THRESHOLD && f2 >= FLOW_THRESHOLD) ? 1 : 0;
            if (relay_set(g_relay_fd, relay_state) < 0)
                fprintf(stderr, "Relay write failed.\n");
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

