 *   I2C   : bus 1, addresses 0x64 (sensor 1) and 0x65 (sensor 2)
 * Relay  : GPIO 18 (BCM), active-high
 * Log    : flow_log.txt  (append mode)
 *
 * Build  : gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
