#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define POLL_INTERVAL_US 200000
#define MOTOR_RUN_TIME_US 5000000
#define DRY_THRESHOLD 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        syslog(LOG_ERR, "gpioSetMode(%u, %u) failed: %s", pin, mode, strerror(errno));
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite(%u, %u) failed: %s", pin, level, strerror(errno));
        return -1;
    }
    return 0;
}

static int safe_call(const char *cmd) {
    int rc = system(cmd);
    if (rc == -1) {
        syslog(LOG_ERR, "system() failed to execute '%s': %s", cmd, strerror(errno));
        return -1;
    }
    if (rc != 0) {
        syslog(LOG_ERR, "system() returned %d for '%s'", rc, cmd);
        return -1;
    }
    return 0;
}

static void close_window(void) {
    syslog(LOG_INFO, "Closing window: motor ON, IN1=HIGH, IN2=LOW");
    if (safe_write(MOTOR_ENABLE_PIN, 1) < 0) return;
    if (safe_write(MOTOR_IN1_PIN, 1) < 0) { safe_write(MOTOR_ENABLE_PIN, 0); return; }
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) { safe_write(MOTOR_ENABLE_PIN, 0); safe_write(MOTOR_IN1_PIN, 0); return; }
    syslog(LOG_INFO, "Motor running for 5 seconds");
    usleep(MOTOR_RUN_TIME_US);
    syslog(LOG_INFO, "Stopping motor");
    if (safe_write(MOTOR_ENABLE_PIN, 0) < 0) { safe_write(MOTOR_IN1_PIN, 0); safe_write(MOTOR_IN2_PIN, 0); return; }
    if (safe_write(MOTOR_IN1_PIN, 0) < 0) { safe_write(MOTOR_IN2_PIN, 0); return; }
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) return;
}

static void cleanup(void) {
    syslog(LOG_INFO, "Shutting down: stopping motor and releasing pigpio");
    safe_write(MOTOR_ENABLE_PIN, 0);
    safe_write(MOTOR_IN1_PIN, 0);
    safe_write(MOTOR_IN2_PIN, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Rain sensor window controller starting");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised");

    if (safe_set_mode(RAIN_SENSOR_PIN, PI_INPUT) < 0) { cleanup(); return EXIT_FAILURE; }
    if (safe_set_mode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0) { cleanup(); return EXIT_FAILURE; }
    if (safe_set_mode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) { cleanup(); return EXIT_FAILURE; }
    if (safe_set_mode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) { cleanup(); return EXIT_FAILURE; }

    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%u, PI_PUD_UP) failed: %s", RAIN_SENSOR_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_write(MOTOR_ENABLE_PIN, 0) < 0) { cleanup(); return EXIT_FAILURE; }
    if (safe_write(MOTOR_IN1_PIN, 0) < 0) { cleanup(); return EXIT_FAILURE; }
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) { cleanup(); return EXIT_FAILURE; }

    int rain_state = 1; /* 1 = dry (pull-up high), 0 = wet (low) */
    int dry_count = 0;

    syslog(LOG_INFO, "Monitoring rain sensor on GPIO %d, motor control on GPIO %d/%d/%d",
           RAIN_SENSOR_PIN, MOTOR_ENABLE_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    while (running) {
        int level = gpioRead(RAIN_SENSOR_PIN);
        if (level < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed: %s", RAIN_SENSOR_PIN, strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (level == 0) {
            dry_count++;
            if (dry_count >= DRY_THRESHOLD && rain_state == 1) {
                syslog(LOG_INFO, "Rain detected (dry), starting window close sequence");
                close_window();
                dry_count = 0;
                rain_state = 0;
            }
        } else {
            dry_count = 0;
            if (rain_state == 0) {
                syslog(LOG_INFO, "Rain cleared (wet), resetting dry count");
                rain_state = 1;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Received shutdown signal, cleaning up");
    cleanup();
    return EXIT_SUCCESS;
}

