#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define STOP_PULSE_US   0

#define DEBOUNCE_US    50000   /* 50 ms */
#define POLL_DELAY_US  10000   /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "gpioServo failed for pulse %d us\n", pulse_us);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop the servo and release the pin. */
    gpioServo(SERVO_PIN, STOP_PULSE_US);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure buttons as inputs with internal pull-ups. */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set button modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-ups\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure servo is stopped at start. */
    if (set_servo_pulse(STOP_PULSE_US) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock actuator ready. Press Ctrl+C to exit.\n");
    printf("  Lock  : GPIO %d\n", LOCK_BUTTON);
    printf("  Unlock: GPIO %d\n", UNLOCK_BUTTON);
    printf("  Servo : GPIO %d\n", SERVO_PIN);
    fflush(stdout);

    int lock_pressed   = 0;
    int unlock_pressed = 0;

    while (g_running) {
        int l = gpioRead(LOCK_BUTTON);
        int u = gpioRead(UNLOCK_BUTTON);

        if (l < 0 || u < 0) {
            fprintf(stderr, "gpioRead error (lock=%d, unlock=%d)\n", l, u);
            break;
        }

        if (l == 0 && !lock_pressed) {
            lock_pressed = 1;
            printf("Lock button pressed\n");
            fflush(stdout);
            if (set_servo_pulse(LOCK_PULSE_US) < 0) {
                break;
            }
            gpioDelay(DEBOUNCE_US);
        } else if (l == 1 && lock_pressed) {
            lock_pressed = 0;
            gpioDelay(DEBOUNCE_US);
        }

        if (u == 0 && !unlock_pressed) {
            unlock_pressed = 1;
            printf("Unlock button pressed\n");
            fflush(stdout);
            if (set_servo_pulse(UNLOCK_PULSE_US) < 0) {
                break;
            }
            gpioDelay(DEBOUNCE_US);
        } else if (u == 1 && unlock_pressed) {
            unlock_pressed = 0;
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

