#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_GPIO 4
#define FLOODLIGHT_GPIO 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL_US 100000
#define FLOODLIGHT_DURATION_S 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event_type, const char *timestamp, double duration) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    if (duration >= 0.0) {
        fprintf(fp, "%s,%.2f\n", event_type, duration);
    } else {
        fprintf(fp, "%s\n", event_type);
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static int activate_floodlight(void) {
    if (gpioWrite(FLOODLIGHT_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set floodlight GPIO high\n");
        return -1;
    }
    return 0;
}

static int deactivate_floodlight(void) {
    if (gpioWrite(FLOODLIGHT_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to set floodlight GPIO low\n");
        return -1;
    }
    return 0;
}

static int log_and_deactivate(void) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }
    struct tm tm_info;
    if (!localtime_r(&now, &tm_info)) {
        perror("localtime_r");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (log_event("DEACTIVATED", timestamp, 0.0) != 0) {
        return -1;
    }
    if (deactivate_floodlight() != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FLOODLIGHT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set floodlight GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(FLOODLIGHT_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise floodlight GPIO low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        deactivate_floodlight();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        deactivate_floodlight();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security system started. Press Ctrl+C to exit.\n");

    int last_pir_state = gpioRead(PIR_GPIO);
    if (last_pir_state < 0) {
        fprintf(stderr, "Failed to read PIR GPIO\n");
        deactivate_floodlight();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int pir_state = gpioRead(PIR_GPIO);
        if (pir_state < 0) {
            fprintf(stderr, "Failed to read PIR GPIO\n");
            break;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            time_t activation_time = time(NULL);
            if (activation_time == (time_t)-1) {
                perror("time");
                break;
            }
            struct tm tm_info;
            if (!localtime_r(&activation_time, &tm_info)) {
                perror("localtime_r");
                break;
            }
            char timestamp[32];
            if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
                fprintf(stderr, "strftime failed\n");
                break;
            }
            if (log_event("ACTIVATED", timestamp, -1.0) != 0) {
                break;
            }
            if (activate_floodlight() != 0) {
                break;
            }
            time_t deactivation_time = activation_time + FLOODLIGHT_DURATION_S;
            time_t current_time;
            while (running) {
                current_time = time(NULL);
                if (current_time == (time_t)-1) {
                    perror("time");
                    break;
                }
                if (current_time >= deactivation_time) {
                    break;
                }
                gpioDelay(POLL_INTERVAL_US);
            }
            if (log_and_deactivate() != 0) {
                break;
            }
        }

        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    deactivate_floodlight();
    gpioTerminate();
    printf("Security system stopped.\n");
    return EXIT_SUCCESS;
}

