/*
 * MPR121 Capacitive Touch Sensor — Relay Toggle on Electrode 0
 * Board: Raspberry Pi 5 (I2C bus 1, GPIO17 relay)
 * Sensor: MPR121 at address 0x5A (A0=A1=GND)
 *
 * Build: gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:   sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS        1
#define MPR121_ADDR    0x5A
#define RELAY_GPIO     17

/* MPR121 register addresses (16-bit, auto-increment) */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_ELE0_T_L       0x04
#define MPR121_ELE0_R_L       0x06
#define MPR121_MHD_R          0x2B
#define MPR121_NHD_R          0x2C
#define MPR121_NCL_R          0x2D
#define MPR121_FDL_R          0x2E
#define MPR121_NHD_F          0x2F
#define MPR121_NCL_F          0x30
#define MPR121_FDL_F          0x31
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_ECR            0x5E
#define MPR121_SOFTRESET      0x80

/* ------------------------------- Globals --------------------------------- */
static int      g_i2c_handle = -1;
static volatile sig_atomic_t g_running = 1;

/* --------------------------- Forward Declarations ------------------------ */
static void signal_handler(int sig);
static int  mpr121_write(uint8_t reg, uint8_t val);
static int  mpr121_read(uint8_t reg, uint8_t *buf, uint8_t len);
static int  mpr121_init(void);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C Helpers ----------------------------- */
static int mpr121_write(uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(g_i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int mpr121_read(uint8_t reg, uint8_t *buf, uint8_t len)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(g_i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "[ERROR] I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------- MPR121 Init ----------------------------- */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write(MPR121_SOFTRESET, 0x63) != 0) return -1;
    gpioDelay(2000); /* 2 ms settle */

    /* Baseline filtering — rising */
    if (mpr121_write(MPR121_MHD_R, 0x01) != 0) return -1;
    if (mpr121_write(MPR121_NHD_R, 0x01) != 0) return -1;
    if (mpr121_write(MPR121_NCL_R, 0x00) != 0) return -1;
    if (mpr121_write(MPR121_FDL_R, 0x00) != 0) return -1;

    /* Baseline filtering — falling */
    if (mpr121_write(MPR121_NHD_F, 0x01) != 0) return -1;
    if (mpr121_write(MPR121_NCL_F, 0x00) != 0) return -1;
    if (mpr121_write(MPR121_FDL_F, 0x00) != 0) return -1;

    /* Touch / release thresholds for electrode 0 */
    if (mpr121_write(MPR121_E0TTH, 0x0C) != 0) return -1; /* touch  */
    if (mpr121_write(MPR121_E0RTH, 0x0A) != 0) return -1; /* release */

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write(MPR121_DEBOUNCE, 0x33) != 0) return -1;

    /* FFI=6 samples, CDC=16 µA, CDT=0.5 µs (default) */
    if (mpr121_write(MPR121_CONFIG1, 0x10) != 0) return -1;

    /* SFI=4 samples, ESI=4 ms (default) */
    if (mpr121_write(MPR121_CONFIG2, 0x20) != 0) return -1;

    /* Auto-config: enable, range 0x00–0x0C (12 electrodes) */
    if (mpr121_write(0x7B, 0x0C) != 0) return -1;
    if (mpr121_write(0x7D, 0x00) != 0) return -1;
    if (mpr121_write(0x7E, 0x00) != 0) return -1;
    if (mpr121_write(0x7F, 0x00) != 0) return -1;

    /* Enable 12 electrodes, baseline tracking, run */
    if (mpr121_write(MPR121_ECR, 0x8C) != 0) return -1;

    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
