{
    if (g_i2c_handle >= 0) {
        /* Put MPR121 in standby (ECR = 0) before closing */
        (void)mpr121_write(MPR121_ECR, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
