    while (g_running) {
        uint8_t buf[2] = {0};
        if (mpr121_read(MPR121_TOUCHSTATUS_L, buf, 2) != 0) {
            fprintf(stderr, "[WARN] Touch status read failed — continuing\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        uint8_t cur_touch = buf[0]; /* LSB: electrodes 0–7 */
