#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <stdarg.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define GPIO_SERVO 17
#define GPIO_PIR   4
#define PORT       5000
#define LOG_FILE   "security.log"
#define PWM_FREQ_HZ 50
#define PWM_RANGE   2000000  /* 2 ms period at 50 Hz */
#define PWM_DUTY_MIN 100000  /* 1 ms pulse */
#define PWM_DUTY_MAX 200000  /* 2 ms pulse */
#define POLL_TIMEOUT_MS 100

static volatile sig_atomic_t g_running = 1;
static int  g_sockfd = -1;
static FILE *g_logfp  = NULL;
static struct gpiod_chip  *g_chip  = NULL;
static struct gpiod_line  *g_servo = NULL;
static struct gpiod_line  *g_pir   = NULL;

static void log_msg(int priority, const char *fmt, ...)
{
    va_list ap;
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        snprintf(ts, sizeof(ts), "unknown-time");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    }

    if (g_logfp) {
        fprintf(g_logfp, "%s ", ts);
        va_start(ap, fmt);
        vfprintf(g_logfp, fmt, ap);
        va_end(ap);
        fputc('\n', g_logfp);
        fflush(g_logfp);
    }

    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", ts);
    va_start(ap, fmt);
    vsyslog(priority, fmt, ap);
    va_end(ap);
    closelog();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        log_msg(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }

    g_servo = gpiod_chip_get_line(g_chip, GPIO_SERVO);
    if (!g_servo) {
        log_msg(LOG_ERR, "Failed to get GPIO line %d: %s", GPIO_SERVO, strerror(errno));
        return -1;
    }

    g_pir = gpiod_chip_get_line(g_chip, GPIO_PIR);
    if (!g_pir) {
        log_msg(LOG_ERR, "Failed to get GPIO line %d: %s", GPIO_PIR, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(g_servo, "security_server", 0) < 0) {
        log_msg(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(g_pir, "security_server") < 0) {
        log_msg(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (g_servo) {
        gpiod_line_set_value(g_servo, 0);
        gpiod_line_release(g_servo);
        g_servo = NULL;
    }
    if (g_pir) {
        gpiod_line_release(g_pir);
        g_pir = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

static int init_socket(void)
{
    int fd;
    struct sockaddr_in addr;

    fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        log_msg(LOG_ERR, "socket() failed: %s", strerror(errno));
        return -1;
    }

    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_msg(LOG_WARNING, "setsockopt(SO_REUSEADDR) failed: %s", strerror(errno));
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_msg(LOG_ERR, "bind() failed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (listen(fd, 5) < 0) {
        log_msg(LOG_ERR, "listen() failed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    log_msg(LOG_INFO, "Listening on port %d", PORT);
    return fd;
}

static void send_all(int fd, const char *msg)
{
    size_t len = strlen(msg);
    size_t sent = 0;
    while (sent < len) {
        ssize_t n = send(fd, msg + sent, len - sent, MSG_NOSIGNAL);
        if (n < 0) {
            if (errno == EINTR) continue;
            log_msg(LOG_ERR, "send() failed: %s", strerror(errno));
            return;
        }
        sent += (size_t)n;
    }
}

static void handle_client(int client_fd)
{
    char buf[256];
    ssize_t n;

    while (g_running) {
        n = recv(client_fd, buf, sizeof(buf) - 1, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            log_msg(LOG_ERR, "recv() failed: %s", strerror(errno));
            break;
        }
        if (n == 0) {
            log_msg(LOG_INFO, "Client disconnected");
            break;
        }
        buf[n] = '\0';

        /* Strip trailing newline/CR */
        buf[strcspn(buf, "\r\n")] = '\0';

        log_msg(LOG_INFO, "Received: %s", buf);

        if (strncmp(buf, "PIR", 3) == 0) {
            int val = gpiod_line_get_value(g_pir);
            if (val < 0) {
                log_msg(LOG_ERR, "Failed to read PIR: %s", strerror(errno));
                send_all(client_fd, "PIR:ERROR\n");
            } else {
                char resp[16];
                snprintf(resp, sizeof(resp), "PIR:%d\n", val);
                send_all(client_fd, resp);
            }
        } else if (strncmp(buf, "the library's API call", 23) == 0) {
            int angle = atoi(buf + 24);
            if (angle < 0 || angle > 180) {
                log_msg(LOG_ERR, "Invalid angle %d (must be 0-180)", angle);
                send_all(client_fd, "ERROR: angle out of range\n");
            } else {
                int duty = PWM_DUTY_MIN + (angle * (PWM_DUTY_MAX - PWM_DUTY_MIN) / 180);
                if (gpiod_line_set_value(g_servo, 1) < 0) {
                    log_msg(LOG_ERR, "Failed to set servo high: %s", strerror(errno));
                    send_all(client_fd, "ERROR: servo high\n");
                } else {
                    struct timespec ts_on = { 0, duty };
                    struct timespec ts_off = { 0, PWM_RANGE - duty };
                    if (nanosleep(&ts_on, NULL) < 0) {
                        log_msg(LOG_ERR, "nanosleep(on) failed: %s", strerror(errno));
                    }
                    if (nanosleep(&ts_off, NULL) < 0) {
                        log_msg(LOG_ERR, "nanosleep(off) failed: %s", strerror(errno));
                    }
                    if (gpiod_line_set_value(g_servo, 0) < 0) {
                        log_msg(LOG_ERR, "Failed to set servo low: %s", strerror(errno));
                    }
                    send_all(client_fd, "OK\n");
                }
            }
        } else {
            log_msg(LOG_ERR, "Unknown command: %s", buf);
            send_all(client_fd, "ERROR: unknown command\n");
        }
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_logfp = fopen(LOG_FILE, "a");
    if (!g_logfp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        log_msg(LOG_ERR, "GPIO initialization failed, exiting");
        fclose(g_logfp);
        return EXIT_FAILURE;
    }

    g_sockfd = init_socket();
    if (g_sockfd < 0) {
        cleanup_gpio();
        fclose(g_logfp);
        return EXIT_FAILURE;
    }

    log_msg(LOG_INFO, "Security server started");

    while (g_running) {
        struct sockaddr_in caddr;
        socklen_t clen = sizeof(caddr);
        int cfd = accept(g_sockfd, (struct sockaddr *)&caddr, &clen);
        if (cfd < 0) {
            if (errno == EINTR) continue;
            if (!g_running) break;
            log_msg(LOG_ERR, "accept() failed: %s", strerror(errno));
            continue;
        }
        log_msg(LOG_INFO, "Connection from %s:%d",
                inet_ntoa(caddr.sin_addr), ntohs(caddr.sin_port));
        handle_client(cfd);
        close(cfd);
    }

    log_msg(LOG_INFO, "Shutting down");
    if (g_sockfd >= 0) close(g_sockfd);
    cleanup_gpio();
    if (g_logfp) fclose(g_logfp);
    return EXIT_SUCCESS;
}

