#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR             0x23
#define BH1750_CONT_HIGH_RES    0x10
#define BH1750_CONV_TIME_MS     120
#define I2C_BUS                 "/dev/i2c-1"
#define RELAY_PIN               23
#define LUX_THRESHOLD           150.0f
#define SAMPLE_INTERVAL_S       2
#define LOG_FILE                "grow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure relay is deactivated */
    if (RELAY_PIN >= 0) {
        /* Use the bcm2835 library if available; fall back to sysfs if not */
        FILE *relay_fp = fopen("/sys/class/gpio/gpio23/value", "w");
        if (relay_fp != NULL) {
            fprintf(relay_fp, "0\n");
            fclose(relay_fp);
        }
    }
}

static int init_relay(void)
{
    /* If bcm2835 is available, use it; otherwise sysfs */
    FILE *relay_fp = fopen("/sys/class/gpio/gpio23/value", "w");
    if (relay_fp != NULL) {
        /* bcm2835 already exported; write directly */
        fprintf(relay_fp, "0\n");
        fclose(relay_fp);
        return 0;
    }

    /* Fallback: try to export the pin */
    FILE *export_fp = fopen("/sys/class/gpio/export", "w");
    if (export_fp == NULL) {
        fprintf(stderr, "Failed to export GPIO23: %s\n", strerror(errno));
        return -1;
    }
    fprintf(export_fp, "23\n");
    fclose(export_fp);
    usleep(100000); /* 100 ms settle */

    /* Set direction to output */
    FILE *dir_fp = fopen("/sys/class/gpio/gpio23/direction", "w");
    if (dir_fp == NULL) {
        fprintf(stderr, "Failed to set GPIO23 direction: %s\n", strerror(errno));
        return -1;
    }
    fprintf(dir_fp, "out\n");
    fclose(dir_fp);

    /* Ensure relay is off at startup */
    FILE *val_fp = fopen("/sys/class/gpio/gpio23/value", "w");
    if (val_fp == NULL) {
        fprintf(stderr, "Failed to write GPIO23 value: %s\n", strerror(errno));
        return -1;
    }
    fprintf(val_fp, "0\n");
    fclose(val_fp);

    return 0;
}

static int read_bh1750(int fd, float *lux_out)
{
    uint8_t cmd = BH1750_CONT_HIGH_RES;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    usleep(BH1750_CONV_TIME_MS * 1000);

    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_relay() != 0) {
        fprintf(stderr, "Failed to initialize relay GPIO23\n");
        cleanup();
        return 1;
    }

    printf("Grow-light controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        if (read_bh1750(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "Sensor read failed; retrying next cycle.\n");
        } else {
            log_data(g_log_fp, lux);

            int relay_state = (lux < LUX_THRESHOLD) ? 1 : 0;
            FILE *relay_fp = fopen("/sys/class/gpio/gpio23/value", "w");
            if (relay_fp != NULL) {
                fprintf(relay_fp, "%d\n", relay_state);
                fclose(relay_fp);
            } else {
                fprintf(stderr, "Failed to write relay GPIO23 value: %s\n", strerror(errno));
            }

            printf("Lux: %.2f, Relay: %s\n", lux, relay_state ? "ON" : "OFF");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

