code:
/*
 * Raspberry Pi 3 Model B+ — TAL220B load cell (HX711) + solenoid lock
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO23 (physical pin 16)
 *   HX711 SCK   -> GPIO24 (physical pin 18)
 *   Solenoid    -> GPIO25 (physical pin 22)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o weight_monitor weight_monitor.c -lpigpio -lrt
 *   (or: gcc -O2 -Wall -Wextra -o weight_monitor weight_monitor.c -lgpiod)
 *
 * Run:
 *   ./weight_monitor [--threshold <grams>] [--scale <factor>] [--duration <ms>]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define HX711_DOUT_PIN      23
#define HX711_SCK_PIN       24
#define SOLENOID_PIN        25

#define DEFAULT_THRESHOLD   1000.0f   /* grams */
#define DEFAULT_SCALE       1.0f      /* raw -> grams */
#define DEFAULT_DURATION_MS 200       /* solenoid hold time (ms) */
#define NUM_TARE_READINGS   10
#define NUM_MEASUREMENTS    5
#define HX711_TIMEOUT_US    1000000   /* 1 s timeout waiting for DOUT low */
#define HX711_RETRIES       3
#define HX711_SETTLE_US     1         /* SCK high/low settle time */
#define MEASUREMENT_DELAY_US 500000   /* 500 ms between readings */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static float g_threshold = DEFAULT_THRESHOLD;
static float g_scale = DEFAULT_SCALE;
static int   g_duration_ms = DEFAULT_DURATION_MS;

/* ----------------------------- Prototypes -------------------------------- */

static int  initialize_gpio(void);
static int  read_hx711(int32_t *out_raw);
static float convert_to_weight(int32_t raw);
static void control_solenoid(int state);
static void tare_load_cell(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- Implementation ----------------------------- */

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(HX711_DOUT_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set DOUT pin %d as input", HX711_DOUT_PIN);
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set SCK pin %d as output", HX711_SCK_PIN);
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid pin %d as output", SOLENOID_PIN);
        return -1;
    }

    /* Start with SCK LOW and solenoid OFF */
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialise SCK pin LOW");
        return -1;
    }
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialise solenoid pin LOW");
        return -1;
    }

    return 0;
}

/*
 * Read 24-bit two's-complement value from HX711.
 * Returns 0 on success, -1 on error.
 * HX711 DOUT must go LOW within HX711_TIMEOUT_US; each clock pulse
 * clocks out one MSB bit; the 25th pulse selects Channel A gain 128.
 */
static int read_hx711(int32_t *out_raw)
{
    uint32_t raw = 0;
    int      attempt;

    for (attempt = 0; attempt < HX711_RETRIES; attempt++) {
        /* Wait for DOUT to go LOW (data ready) */
        uint32_t waited = 0;
        while (gpioRead(HX711_DOUT_PIN) == 1) {
            if (waited >= HX711_TIMEOUT_US) {
                syslog(LOG_ERR, "HX711 DOUT stuck HIGH (timeout %u us)",
                       HX711_TIMEOUT_US);
                return -1;
            }
            gpioDelay(1);
            waited++;
        }

        /* Read 24 data bits MSB first */
        for (int i = 0; i < 24; i++) {
            if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
                syslog(LOG_ERR, "SCK write HIGH failed");
                return -1;
            }
            gpioDelay(HX711_SETTLE_US);

            raw <<= 1;
            if (gpioRead(HX711_DOUT_PIN) == 1)
                raw |= 1U;

            if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
                syslog(LOG_ERR, "SCK write LOW failed");
                return -1;
            }
            gpioDelay(HX711_SETTLE_US);
        }

        /* 25th pulse: select Channel A gain 128 */
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            syslog(LOG_ERR, "SCK 25th pulse HIGH failed");
            return -1;
        }
        gpioDelay(HX711_SETTLE_US);
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            syslog(LOG_ERR, "SCK 25th pulse LOW failed");
            return -1;
        }
        gpioDelay(HX711_SETTLE_US);

        /* Convert 24-bit two's-complement to signed 32-bit */
        if (raw & 0x800000U)
            raw |= 0xFF000000U;

        *out_raw = (int32_t)raw;
        return 0;
    }

    syslog(LOG_ERR, "HX711 read failed after %d retries", HX711_RETRIES);
    return -1;
