/*
 * relay_controller.c — Raspberry Pi 4 Model B
 *
 * Controls a relay module on GPIO17 (BCM 17, physical pin 11) by subscribing
 * to MQTT topic home/lights/control on localhost:1883 with client ID
 * relay_controller_1.  Payload "ON" energizes the relay (GPIO HIGH),
 * "OFF" de-energizes it (GPIO LOW), and any other value is logged as an
 * error without changing the relay state.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *                 -lgpiod -lmosquitto
 *
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>

#include <gpiod.h>
#include <mosquitto.h>

#define MQTT_BROKER_HOST      "localhost"
#define MQTT_BROKER_PORT      1883
#define MQTT_CLIENT_ID        "relay_controller_1"
#define MQTT_TOPIC            "home/lights/control"
#define MQTT_KEEPALIVE        60
#define MQTT_QOS              0
#define MQTT_RECONNECT_DELAY  5   /* seconds between reconnect attempts */

#define GPIO_CHIP_NAME        "gpiochip4"   /* BCM GPIO on Pi 4 */
#define GPIO_LINE_OFFSET      17            /* BCM 17, physical pin 11 */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO                                                                */
/* ------------------------------------------------------------------ */
static int gpio_init(struct gpiod_line **line_out)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s): %s",
               GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s",
               GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "relay_controller", 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_output: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    *line_out = line;
    return 0;
}

static void gpio_set(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0)
        syslog(LOG_ERR, "gpiod_line_set_value(%d): %s", value, strerror(errno));
}

static void gpio_cleanup(struct gpiod_line *line)
{
    if (line) {
        gpio_set(line, 0);          /* relay OFF */
        gpiod_line_release(line);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT                                                                */
/* ------------------------------------------------------------------ */
static int mqtt_connect(struct mosquitto **mosq_out)
{
    struct mosquitto *mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "mosquitto_new: %s", strerror(errno));
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER_HOST, MQTT_BROKER_PORT,
                               MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        return -1;
    }

    *mosq_out = mosq;
    return 0;
}

static void mqtt_disconnect(struct mosquitto *mosq)
{
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
}

static void mqtt_message_callback(struct mosquitto *mosq,
                                   void *userdata,
                                   const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (!message || !message->payload || message->payloadlen <= 0) {
        syslog(LOG_ERR, "MQTT message: empty or invalid payload");
        return;
    }

    /* NUL-terminate the payload for safe string comparison */
    char payload[64];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload))
        len = sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        syslog(LOG_INFO, "Received ON — relay ON");
        gpio_set((struct gpiod_line *)userdata, 1);
    } else if (strcmp(payload, "OFF") == 0) {
        syslog(LOG_INFO, "Received OFF — relay OFF");
        gpio_set((struct gpiod_line *)userdata, 0);
    } else {
        syslog(LOG_ERR, "Invalid payload: '%s'", payload);
    }
}

static int mqtt_subscribe(struct mosquitto *mosq,
                          struct gpiod_line *line)
{
    int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_subscribe: %s", mosquitto_strerror(rc));
        return -1;
    }

    syslog(LOG_INFO, "Subscribed to %s (QoS %d)", MQTT_TOPIC, MQTT_QOS);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = NULL;
    if (gpio_init(&relay_line) < 0) {
        closelog();
        return EXIT_FAILURE;
    }

    struct mosquitto *mosq = NULL;
    if (mqtt_connect(&mosq) < 0) {
        gpio_cleanup(relay_line);
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_subscribe(mosq, relay_line) < 0) {
        mqtt_disconnect(mosq);
        gpio_cleanup(relay_line);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller started (GPIO17, %s:%d/%s)",
           MQTT_BROKER_HOST, MQTT_BROKER_PORT, MQTT_TOPIC);

    while (g_running) {
        int rc = mosquitto_loop(mosq, 100, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop: %s — retrying in %d s",
                   mosquitto_strerror(rc), MQTT_RECONNECT_DELAY);
            sleep(MQTT_RECONNECT_DELAY);
            continue;
        }
    }

    syslog(LOG_INFO, "Shutting down");
    mqtt_disconnect(mosq);
    gpio_cleanup(relay_line);
    closelog();
    return EXIT_SUCCESS;
}

