#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define SERVO1 7
#define SERVO2 8
#define SERVO3 9
#define SERVO4 10
#define SERVO5 11

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_SETTLE_US 3000000

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int servo_pins[] = {SERVO1, SERVO2, SERVO3, SERVO4, SERVO5};
    int target_pulse_widths[] = {1000, 1500, 2000, 500, 2500};
    int num_servos = sizeof(servo_pins) / sizeof(servo_pins[0]);

    for (int i = 0; i < num_servos; i++) {
        if (gpioSetMode(servo_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_servos; i++) {
        int pulse_width = target_pulse_widths[i];
        if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
            fprintf(stderr, "Pulse width %d for servo %d out of range [%d, %d]\n",
                    pulse_width, i + 1, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioServo(servo_pins[i], pulse_width) != 0) {
            fprintf(stderr, "Failed to set servo %d on GPIO %d\n", i + 1, servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Servos moved to target positions. Holding for 3 seconds...\n");
    gpioDelay(SERVO_SETTLE_US);

    for (int i = 0; i < num_servos; i++) {
        gpioServo(servo_pins[i], 0);
    }

    gpioTerminate();
    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

