/*
 * Closed-loop DC motor speed control for Raspberry Pi 3 Model B+
 * using quadrature encoders and a DRV8833 H-bridge.
 *
 * Wiring:
 *   DRV8833 IN1 -> BCM 17 (Motor A PWM)
 *   DRV8833 IN2 -> BCM 18 (Motor A direction)
 *   DRV8833 IN3 -> BCM 22 (Motor B PWM)
 *   DRV8833 IN4 -> BCM 23 (Motor B direction)
 *   Encoder A phase A -> BCM 4
 *   Encoder A phase B -> BCM 5
 *   Encoder B phase A -> BCM 6
 *   Encoder B phase B -> BCM 12
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM_PIN      17
#define MOTOR_A_DIR_PIN      18
#define MOTOR_B_PWM_PIN      22
#define MOTOR_B_DIR_PIN      23

#define ENCODER_A_PHASE_A    4
#define ENCODER_A_PHASE_B    5
#define ENCODER_B_PHASE_A    6
#define ENCODER_B_PHASE_B    12

/* ---- Physical constants ---- */
#define WHEEL_DIAMETER_M     0.1          /* meters */
#define COUNTS_PER_REV       64           /* quadrature encoder ticks per revolution */
#define GEAR_RATIO           1.0          /* encoder:output (1:1) */
#define TARGET_RPM           50.0         /* target motor speed in RPM */
#define PWM_FREQUENCY_HZ     10000        /* 10 kHz */
#define PWM_RANGE            255          /* 8-bit resolution */
#define CONTROL_PERIOD_US   100000       /* 100 ms */
#define STALL_TIMEOUT_S      2            /* seconds without ticks before stall warning */

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static volatile int32_t g_encoder_a_ticks = 0;
static volatile int32_t g_encoder_b_ticks = 0;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void set_motor_speed(int motor, int pwm_duty, bool direction);
static double calculate_rpm(int32_t ticks, double dt_s);
static double pid_control(double rpm, double dt_s);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Encoder ISRs (rising edge, single count per edge) ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_encoder_a_ticks++;
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_encoder_b_ticks++;
}

/* ---- Motor control ---- */
static void set_motor_speed(int motor, int pwm_duty, bool direction)
{
    int pwm_pin, dir_pin;

    if (motor == 1) {
        pwm_pin = MOTOR_A_PWM_PIN;
        dir_pin = MOTOR_A_DIR_PIN;
    } else if (motor == 2) {
        pwm_pin = MOTOR_B_PWM_PIN;
        dir_pin = MOTOR_B_DIR_PIN;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }

    if (gpioPWM(pwm_pin, pwm_duty) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on pin %d\n", pwm_pin);

    if (gpioWrite(dir_pin, direction ? 1 : 0) < 0)
        fprintf(stderr, "Warning: gpioWrite failed on pin %d\n", dir_pin);
}

/* ---- RPM calculation ---- */
static double calculate_rpm(int32_t ticks, double dt_s)
{
    double revolutions = (double)ticks / (double)COUNTS_PER_REV;
    return (revolutions / dt_s) * (60.0 / GEAR_RATIO);
}

/* ---- PID controller ---- */
static double pid_control(double rpm, double dt_s)
{
    static double integral = 0.0;
    static double previous_error = 0.0;
    double error = TARGET_RPM - rpm;
    double derivative = (error - previous_error) / dt_s;
    double output = 0.0;

    integral += error * dt_s;

    /* Anti-windup clamp */
    if (integral > 255.0) integral = 255.0;
    if (integral < -255.0) integral = -255.0;

    output = (0.1 * error) + (0.1 * integral) + (0.05 * derivative);

    if (output > 255.0) output = 255.0;
    if (output < 0.0)   output = 0.0;

    previous_error = error;
    return output;
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins */
    if (gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set encoder GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register encoder ISRs */
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_A_PHASE_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_PHASE_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register encoder ISRs.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY_HZ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motor control started. Press Ctrl+C to exit.\n");

    uint32_t last_tick = gpioTick();
    int stall_count = 0;

    while (g_running) {
        uint32_t now = gpioTick();
        uint32_t elapsed_us = now - last_tick;
        last_tick = now;

        if (elapsed_us == 0) elapsed_us = 1; /* avoid division by zero */

        double dt_s = (double)elapsed_us / 1000000.0;

        /* Read and reset encoder ticks */
        int32_t ticks_a = g_encoder_a_ticks;
        int32_t ticks_b = g_encoder_b_ticks;
        g_encoder_a_ticks = 0;
        g_encoder_b_ticks = 0;

        /* Stall detection */
        if (ticks_a == 0 && ticks_b == 0) {
            stall_count++;
            if (stall_count > (STALL_TIMEOUT_S * 100)) {
                fprintf(stderr, "Warning: encoder stall detected (no ticks for %d s).\n",
                        STALL_TIMEOUT_S);
                stall_count = 0;
            }
        } else {
            stall_count = 0;
        }

        /* Motor 1: forward */
        set_motor_speed(1, 255, true);

        /* Motor 2: forward */
        set_motor_speed(2, 255, true);

        /* Calculate RPM */
        double rpm_a = calculate_rpm(ticks_a, dt_s);
        double rpm_b = calculate_rpm(ticks_b, dt_s);

        /* PID control */
        double pwm_a = pid_control(rpm_a, dt_s);
        double pwm_b = pid_control(rpm_b, dt_s);

        /* Clamp PWM to valid range */
        if (pwm_a > 255.0) pwm_a = 255.0;
        if (pwm_a < 0.0)   pwm_a = 0.0;
        if (pwm_b > 255.0) pwm_b = 255.0;
        if (pwm_b < 0.0)   pwm_b = 0.0;

        /* Set PWM duty cycles */
        gpioPWM(MOTOR_A_PWM_PIN, (int)pwm_a);
        gpioPWM(MOTOR_B_PWM_PIN, (int)pwm_b);

        printf("Motor A: RPM = %.2f, PWM = %.2f | Motor B: RPM = %.2f, PWM = %.2f\n",
               rpm_a, pwm_a, rpm_b, pwm_b);

        gpioDelay(CONTROL_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    set_motor_speed(1, 0, false);
    set_motor_speed(2, 0, false);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

