#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD_ON 50.0
#define LUX_THRESHOLD_OFF 200.0
#define POLL_INTERVAL_SEC 5
#define BH1750_MEASURE_CMD 0x10
#define BH1750_POWER_DOWN_CMD 0x00
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int bh1750_init(int handle) {
    if (i2cWriteByte(handle, BH1750_POWER_DOWN_CMD) < 0) {
        log_event("Error: Failed to power down BH1750 (sensor may be absent).");
        return -1;
    }
    gpioDelay(10000);
    if (i2cWriteByte(handle, BH1750_MEASURE_CMD) < 0) {
        log_event("Error: Failed to send measurement command to BH1750.");
        return -1;
    }
    gpioDelay(180000);
    return 0;
}

static int read_lux(int handle, float *lux_out) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        log_event("Error: Failed to read 2 bytes from BH1750.");
        return -1;
    }
    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2;
    return 0;
}

static void control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        log_event("Error: Failed to write to relay GPIO.");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
    log_event(msg);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cWriteByte(i2c_handle, BH1750_POWER_DOWN_CMD);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error: Failed to open I2C bus to BH1750.");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bh1750_init(i2c_handle) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_event("Error: Failed to set relay GPIO mode.");
        cleanup();
        return EXIT_FAILURE;
    }
    control_relay(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    float lux = 0.0f;

    while (running) {
        if (read_lux(i2c_handle, &lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux = %.2f", lux);
            log_event(msg);

            if (lux < LUX_THRESHOLD_ON && relay_state == 0) {
                control_relay(RELAY_GPIO, 1);
                relay_state = 1;
            } else if (lux > LUX_THRESHOLD_OFF && relay_state == 1) {
                control_relay(RELAY_GPIO, 0);
                relay_state = 0;
            }
        } else {
            if (relay_state == 1) {
                control_relay(RELAY_GPIO, 0);
                relay_state = 0;
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

