/*
 * TTP223 capacitive touch sensor -> 5 V relay toggle on Raspberry Pi Zero W.
 *
 * Wiring:
 *   TTP223 VCC  -> 3.3 V (pin 1)
 *   TTP223 GND  -> GND   (pin 9)
 *   TTP223 OUT  -> GPIO4 (pin 7)
 *   Relay VCC   -> 5 V   (pin 2 or 4)
 *   Relay IN    -> GPIO17 (pin 11)
 *   Relay GND   -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN      4
#define RELAY_PIN      17
#define DEBOUNCE_US    50000   /* 50 ms */
#define POLL_US        10000   /* 10 ms */
#define LOG_BUF_LEN    80

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_state(bool relay_on)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[LOG_BUF_LEN];

    if (localtime_r(&now, &tm_buf) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    printf("[%s] Relay %s\n", ts, relay_on ? "ON" : "OFF");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (safe_set_mode(TOUCH_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with relay OFF */
    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bool relay_on = false;
    bool debounce_active = false;
    bool waiting_release = false;

    printf("Touch relay ready. Touch GPIO%d to toggle relay GPIO%d.\n",
           TOUCH_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- main loop ---- */
    while (g_running) {
        int touch = gpioRead(TOUCH_PIN);
        if (touch < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", TOUCH_PIN);
            break;
        }

        if (touch == 1) {
            if (!debounce_active) {
                /* Valid touch: start debounce */
                debounce_active = true;
                waiting_release = false;
            } else if (debounce_active && !waiting_release) {
                /* Still in debounce: wait for release */
                if (touch == 0) {
                    waiting_release = true;
                }
            }
        } else {
            /* No touch: reset debounce state */
            debounce_active = false;
            waiting_release = false;
        }

        if (waiting_release) {
            /* Wait for touch release with 10 ms poll */
            int t = gpioRead(TOUCH_PIN);
            if (t < 0) {
                fprintf(stderr, "gpioRead(%d) failed\n", TOUCH_PIN);
                break;
            }
            if (t == 0) {
                /* Confirmed release: toggle relay */
                relay_on = !relay_on;
                if (safe_write(RELAY_PIN, relay_on ? 1 : 0) != 0) {
                    break;
                }
                log_state(relay_on);
                /* Wait for next valid touch */
                waiting_release = false;
                debounce_active = false;
            }
        }

        gpioDelay(POLL_US);  /* 10 ms */
    }

    /* ---- cleanup ---- */
    printf("\nShutting down...\n");
    safe_write(RELAY_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

