                debounce_active = false;
            }
        }

        gpioDelay(POLL_US);  /* 10 ms */
    }

    /* ---- cleanup ---- */
    printf("\nShutting down...\n");
    safe_write(RELAY_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

