#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO    27
#define FLOW_THRESHOLD_HIGH 5.0
#define FLOW_THRESHOLD_LOW  4.5
#define DEBOUNCE_US        1000000  /* 1 s */
#define SAMPLE_INTERVAL_S  1
#define LOG_FILE           "water_flow.log"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static void log_event(const char *msg)
{
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static void cleanup(void)
{
    if (log_file) {
        log_event("Program terminating.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SOLENOID_GPIO, 1); /* safe open */
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on flow sensor GPIO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_GPIO, 1) < 0) { /* start with solenoid open */
        fprintf(stderr, "Failed to initialise solenoid GPIO state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US,
                         flow_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR on flow sensor GPIO\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started.");

    int solenoid_state = 1; /* 0 = closed, 1 = open */

    while (running) {
        sleep(SAMPLE_INTERVAL_S);

        int local_count;
        pthread_mutex_lock(&pulse_mutex);
        local_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double flow_rate = (double)local_count / (double)SAMPLE_INTERVAL_S;

        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM", flow_rate);
        log_event(msg);

        if (flow_rate > FLOW_THRESHOLD_HIGH && solenoid_state == 1) {
            if (gpioWrite(SOLENOID_GPIO, 0) == 0) {
                solenoid_state = 0;
                log_event("Solenoid closed.");
            } else {
                log_event("ERROR: Failed to close solenoid.");
            }
        } else if (flow_rate < FLOW_THRESHOLD_LOW && solenoid_state == 0) {
            if (gpioWrite(SOLENOID_GPIO, 1) == 0) {
                solenoid_state = 1;
                log_event("Solenoid opened.");
            } else {
                log_event("ERROR: Failed to open solenoid.");
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

