#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define PORT 12345
#define DEFAULT_CALIBRATION_FACTOR 100.0
#define DEFAULT_SCK_PULSE_US 1
#define DEFAULT_TIMEOUT_ATTEMPTS 1000
#define DEFAULT_STABILIZE_DELAY_S 1
#define DEFAULT_MIN_PULSE_US 1000
#define DEFAULT_MAX_PULSE_US 2000
#define DEFAULT_LOG_FILE "dispensing_log.json"
#define DEFAULT_CONFIG_FILE "config.ini"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static int min_pulse_us = DEFAULT_MIN_PULSE_US;
static int max_pulse_us = DEFAULT_MAX_PULSE_US;
static int sck_pulse_us = DEFAULT_SCK_PULSE_US;
static int timeout_attempts = DEFAULT_TIMEOUT_ATTEMPTS;
static int stabilize_delay_s = DEFAULT_STABILIZE_DELAY_S;
static char log_file_path[256] = DEFAULT_LOG_FILE;
static char config_file_path[256] = DEFAULT_CONFIG_FILE;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *sck_line = NULL;
static struct gpiod_line *servo_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (sck_line) {
        gpiod_line_set_value(sck_line, 0);
        gpiod_line_release(sck_line);
        sck_line = NULL;
    }
    if (data_line) {
        gpiod_line_release(data_line);
        data_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int read_config(void) {
    FILE *fp = fopen(config_file_path, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s. Using defaults.\n", config_file_path, strerror(errno));
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *val = strtok(NULL, "\n");
        if (!key || !val) continue;
        if (strcmp(key, "calibration_factor") == 0) calibration_factor = atof(val);
        else if (strcmp(key, "min_pulse_us") == 0) min_pulse_us = atoi(val);
        else if (strcmp(key, "max_pulse_us") == 0) max_pulse_us = atoi(val);
        else if (strcmp(key, "sck_pulse_us") == 0) sck_pulse_us = atoi(val);
        else if (strcmp(key, "timeout_attempts") == 0) timeout_attempts = atoi(val);
        else if (strcmp(key, "stabilize_delay_s") == 0) stabilize_delay_s = atoi(val);
        else if (strcmp(key, "log_file") == 0) {
            strncpy(log_file_path, val, sizeof(log_file_path) - 1);
            log_file_path[sizeof(log_file_path) - 1] = '\0';
        }
        else if (strcmp(key, "config_file") == 0) {
            strncpy(config_file_path, val, sizeof(config_file_path) - 1);
            config_file_path[sizeof(config_file_path) - 1] = '\0';
        }
    }
    fclose(fp);
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
            return -1;
        }
    }
    data_line = gpiod_chip_get_line(chip, HX711_DATA_PIN);
    sck_line = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!data_line || !sck_line || !servo_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(data_line, "hx711") < 0) {
        fprintf(stderr, "Failed to request DATA line as input: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(sck_line, "hx711", 0) < 0) {
        fprintf(stderr, "Failed to request SCK line as output: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        fprintf(stderr, "Failed to request SERVO line as output: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static long read_hx711(void) {
    if (!data_line || !sck_line) return -1;
    int timeout = timeout_attempts;
    while (gpiod_line_get_value(data_line) == 1) {
        if (--timeout <= 0) {
            fprintf(stderr, "HX711 timeout: DATA stuck HIGH\n");
            return -1;
        }
        usleep(1);
    }
    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck_line, 1) < 0) return -1;
        usleep(sck_pulse_us);
        value <<= 1;
        if (gpiod_line_set_value(sck_line, 0) < 0) return -1;
        usleep(sck_pulse_us);
        if (gpiod_line_get_value(data_line)) value |= 1;
    }
    if (gpiod_line_set_value(sck_line, 1) < 0) return -1;
    usleep(sck_pulse_us);
    if (gpiod_line_set_value(sck_line, 0) < 0) return -1;
    usleep(sck_pulse_us);
    if (value & 0x800000) value |= 0xFF000000;
    return value;
}

static int map_weight_to_pulse(double target_weight) {
    if (target_weight < 0) target_weight = 0;
    double range = (double)(max_pulse_us - min_pulse_us);
    double normalized = target_weight / calibration_factor;
    int pulse = min_pulse_us + (int)(normalized * range);
    if (pulse < min_pulse_us) pulse = min_pulse_us;
    if (pulse > max_pulse_us) pulse = max_pulse_us;
    return pulse;
}

static int dispense_ingredient(int pulse_us) {
    if (gpiod_line_set_value(servo_line, 1) < 0) return -1;
    usleep(pulse_us);
    if (gpiod_line_set_value(servo_line, 0) < 0) return -1;
    return 0;
}

static int log_dispensing_event(double target_weight, double actual_weight, const char *error_msg) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (!log_file) {
        log_file = fopen(log_file_path, "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return -1;
        }
    }
    fprintf(log_file, "{\"timestamp\":\"%s\",\"target_weight\":%.2f,\"actual_weight\":%.2f,\"error\":\"%s\"}\n",
            timestamp, target_weight, actual_weight, error_msg ? error_msg : "");
    fflush(log_file);
    return 0;
}

static int handle_client(int client_socket) {
    double target_weight;
    if (recv(client_socket, &target_weight, sizeof(target_weight), 0) <= 0) {
        fprintf(stderr, "Client disconnected\n");
        return -1;
    }
    if (target_weight < 0) {
        fprintf(stderr, "Invalid target weight: %.2f\n", target_weight);
        const char *err = "Invalid target weight";
        send(client_socket, err, strlen(err) + 1, 0);
        return -1;
    }
    printf("Target weight: %.2f grams\n", target_weight);
    if (dispense_ingredient(map_weight_to_pulse(target_weight)) < 0) {
        fprintf(stderr, "Servo dispense failed\n");
        const char *err = "Servo dispense failed";
        send(client_socket, err, strlen(err) + 1, 0);
        log_dispensing_event(target_weight, 0, err);
        return -1;
    }
    sleep(stabilize_delay_s);
    long raw = read_hx711();
    if (raw < 0) {
        fprintf(stderr, "HX711 read failed\n");
        const char *err = "HX711 read failed";
        send(client_socket, err, strlen(err) + 1, 0);
        log_dispensing_event(target_weight, 0, err);
        return -1;
    }
    double actual_weight = (double)raw / calibration_factor;
    printf("Actual weight: %.2f grams\n", actual_weight);
    send(client_socket, &actual_weight, sizeof(actual_weight), 0);
    log_dispensing_event(target_weight, actual_weight, NULL);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    read_config();
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Bind failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Listen failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    printf("Listening on 127.0.0.1:%d...\n", PORT);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            fprintf(stderr, "Accept failed: %s\n", strerror(errno));
            continue;
        }
        printf("Connection from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
        handle_client(client_socket);
        close(client_socket);
    }
    cleanup();
    return 0;
}

