#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;
    int relay_state = 0;

    if (argc > 1) {
        if (strcmp(argv[1], "-d") == 0 && argc > 2) {
            int val = atoi(argv[2]);
            if (val > 0) {
                debounce_ms = val;
            } else {
                fprintf(stderr, "Invalid debounce value. Using default: %d ms\n", DEFAULT_DEBOUNCE_MS);
            }
        } else {
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Failed to initialize relay state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Debounce interval: %d ms\n", debounce_ms);
    fflush(stdout);

    int last_touch = gpioRead(TOUCH_SENSOR_PIN);
    if (last_touch < 0) {
        fprintf(stderr, "Failed to read initial touch sensor state\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_touch = gpioRead(TOUCH_SENSOR_PIN);
        if (current_touch < 0) {
            fprintf(stderr, "Failed to read touch sensor\n");
            break;
        }

        if (current_touch == 1 && last_touch == 0) {
            gpioDelay(debounce_ms * 1000);
            current_touch = gpioRead(TOUCH_SENSOR_PIN);
            if (current_touch < 0) {
                fprintf(stderr, "Failed to read touch sensor during debounce\n");
                break;
            }
            if (current_touch == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Failed to write relay state\n");
                    break;
                }
                log_relay_state(relay_state);
            }
        }
        last_touch = current_touch;
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

