/*
 * servo_angle.c — Adjust a hobby servo on GPIO18 (BCM 18, physical pin 12)
 * via raw terminal input (+/- keys) using the pigpio library.
 *
 * Build:  gcc -O2 -Wall -Wextra -o servo_angle servo_angle.c -lpigpio -lrt
 * Run:    sudo ./servo_angle
 *
 * The SG90 servo accepts pulse widths between 500 µs (0°) and 2500 µs (180°).
 * A 50 Hz PWM frequency gives a 20 ms period; 500 µs ÷ 20 ms ≈ 2.5 Hz.
 * 50 Hz × 20 ms ÷ 4096 ≈ 20.48 Hz, which is well within the servo's tolerance.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SERVO_PIN        18          /* BCM 18, physical pin 12 */
#define SERVO_FREQ_HZ    50          /* 50 Hz hardware PWM */
#define SERVO_RANGE      4096        /* 12-bit resolution */
#define MIN_PULSE_US     500         /* 0°   */
#define MAX_PULSE_US     2500        /* 180° */
#define STEP_ANGLE       10          /* 10° per key press */
#define MIN_ANGLE        0
#define MAX_ANGLE        180

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Terminal helpers                                                    */
/* ------------------------------------------------------------------ */
static int set_raw_mode(int fd)
{
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }
    tty.c_lflag &= ~(ICANON | ECHO);   /* raw mode */
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int restore_term_mode(int fd, struct termios *old)
{
    if (old == NULL)
        return 0;
    if (tcsetattr(fd, TCSANOW, old) != 0) {
        perror("tcsetattr (restore)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */
static int angle_to_pulse(int angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US +
           (int)((long)angle * (MAX_PULSE_US - MIN_PULSE_US) / MAX_ANGLE);
}

static int set_servo_angle(int angle)
{
    int pulse = angle_to_pulse(angle);
    int rc = gpioServo(SERVO_PIN, pulse);
    if (rc < 0) {
        fprintf(stderr, "gpioServo failed: %s (rc=%d)\n", pigpio_error(rc), rc);
        return -1;
    }
    return 0;
}

static void stop_servo(void)
{
    gpioServo(SERVO_PIN, 0);   /* stop PWM pulses */
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = STDIN_FILENO;
    struct termios orig_termios;
    int angle = 90;
    int rc;

    /* ---- pigpio init ---- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_error(rc));
        return EXIT_FAILURE;
    }

    /* ---- restore state on exit ---- */
    if (atexit(gpioTerminate) != 0) {
        fprintf(stderr, "Warning: could not register atexit handler\n");
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- terminal raw mode ---- */
    if (set_raw_mode(fd) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (atexit(restore_term_mode) != 0) {
        fprintf(stderr, "Warning: could not register restore_term_mode\n");
    }

    /* ---- initial servo position ---- */
    if (set_servo_angle(angle) != 0) {
        restore_term_mode(fd, &orig_termios);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Servo initialised at %d° (%d µs). Press +/- to adjust.\n",
           angle, angle_to_pulse(angle));
    fflush(stdout);

    /* ---- main loop ---- */
    while (g_running) {
        char ch;
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            perror("read");
            break;
        }
        if (n == 0)
            continue;   /* EOF — shouldn't happen on stdin */

        switch (ch) {
        case '+':
            angle += STEP_ANGLE;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            break;
        case '-':
            angle -= STEP_ANGLE;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            break;
        case 'q':
        case 'Q':
        case '\x03':          /* Ctrl-C */
            g_running = 0;
            break;
        default:
            continue;
        }

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Failed to set servo angle.\n");
            break;
        }
        printf("Angle: %d° (%d µs)\n", angle, angle_to_pulse(angle));
        fflush(stdout);
    }

    /* ---- cleanup ---- */
    stop_servo();
    restore_term_mode(fd, &orig_termios);
    gpioTerminate();
    return EXIT_SUCCESS;
}

