        return -1;
    }
    return 0;
}

static int restore_term_mode(int fd, struct termios *old)
{
    if (old == NULL)
        return 0;
    if (tcsetattr(fd, TCSANOW, old) != 0) {
        perror("tcsetattr (restore)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */
static int angle_to_pulse(int angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US +
           (int)((long)angle * (MAX_PULSE_US - MIN_PULSE_US) / MAX_ANGLE);
}

static int set_servo_angle(int angle)
{
    int pulse = angle_to_pulse(angle);
    int rc = gpioServo(SERVO_PIN, pulse);
    if (rc < 0) {
        fprintf(stderr, "gpioServo failed: %s (rc=%d)\n", pigpio_error(rc), rc);
        return -1;
    }
    return 0;
}

static void stop_servo(void)
{
    gpioServo(SERVO_PIN, 0);   /* stop PWM pulses */
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = STDIN_FILENO;
    struct termios orig_termios;
    int angle = 90;
    int rc;

    /* ---- pigpio init ---- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_error(rc));
        return EXIT_FAILURE;
    }

    /* ---- restore state on exit ---- */
    if (atexit(gpioTerminate) != 0) {
        fprintf(stderr, "Warning: could not register atexit handler\n");
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- terminal raw mode ---- */
    if (set_raw_mode(fd) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (atexit(restore_term_mode) != 0) {
        fprintf(stderr, "Warning: could not register restore_term_mode\n");
    }

    /* ---- initial servo position ---- */
    if (set_servo_angle(angle) != 0) {
        restore_term_mode(fd, &orig_termios);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Servo initialised at %d° (%d µs). Press +/- to adjust.\n",
           angle, angle_to_pulse(angle));
    fflush(stdout);

    /* ---- main loop ---- */
    while (g_running) {
        char ch;
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            perror("read");
            break;
        }
        if (n == 0)
            continue;   /* EOF — shouldn't happen on stdin */

        switch (ch) {
        case '+':
            angle += STEP_ANGLE;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            break;
        case '-':
            angle -= STEP_ANGLE;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            break;
        case 'q':
        case 'Q':
        case '\x03':          /* Ctrl-C */
            g_running = 0;
            break;
        default:
            continue;
        }

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Failed to set servo angle.\n");
            break;
        }
        printf("Angle: %d° (%d µs)\n", angle, angle_to_pulse(angle));
        fflush(stdout);
    }

    /* ---- cleanup ---- */
    stop_servo();
    restore_term_mode(fd, &orig_termios);
    gpioTerminate();
    return EXIT_SUCCESS;
}

