/*
 * Conveyor-belt RPM monitor using an A3144 Hall-effect sensor.
 *
 * Hardware (Raspberry Pi 3 Model B+):
 *   - A3144 VCC  -> 3V3 (pin 1)
 *   - A3144 GND  -> GND (pin 9)
 *   - A3144 OUT  -> GPIO17 (pin 11, BCM 17) with internal pull-up
 *   - Two-pole magnet on the motor shaft
 *
 * The two-pole magnet produces one Hall-effect pulse per revolution.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_rpm motor_rpm.c -lpigpio -lrt
 * Run:
 *   sudo ./motor_rpm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN          17          /* BCM 17, physical pin 11 */
#define DEBOUNCE_US       2000        /* 2 ms debounce window */
#define SAMPLE_INTERVAL_S 5           /* seconds between RPM reports */
#define LOG_FILE          "motor_rpm.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_rpm(FILE *fp, double rpm)
{
    char ts[32];
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, rpm) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    if (install_signal_handlers() != 0) {
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main loop state ---- */
    struct {
        uint32_t last_tick;   /* pigpio tick of last accepted edge */
        uint32_t pulse_count; /* rising-edge events since last report */
    } state = {0, 0};

    printf("Monitoring RPM on GPIO%d (BCM). Press Ctrl+C to exit.\n",
           GPIO_PIN);

    while (g_running) {
        /* ---- Sample interval ---- */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            gpioDelay(1000000); /* 1 s */
        }
        if (!g_running) {
            break;
        }

        /* ---- Read and count rising edges ---- */
        uint32_t count = state.pulse_count;
        state.pulse_count = 0;

        /* pigpio tick is a 32-bit microsecond counter that wraps every ~71.6 min.
         * We use a simple monotonic window: if the next edge arrives after
         * DEBOUNCE_US microseconds of the last accepted edge, it is accepted. */
        uint32_t now_tick = gpioTick();

        while (g_running) {
            int level = gpioRead(GPIO_PIN);
            if (level < 0) {
                fprintf(stderr, "gpioRead(%d) failed\n", GPIO_PIN);
                break;
            }

            if (level == 1) {
                uint32_t delta = now_tick - state.last_tick;
                if (delta > DEBOUNCE_US) {
                    state.last_tick = now_tick;
                    count++;
                }
            }

            /* Poll every 10 ms; 2 ms debounce window covers a full revolution. */
            gpioDelay(10000);
            now_tick = gpioTick();
        }

        /* ---- Compute RPM ---- */
        double rpm = (double)count * 60.0 / (double)SAMPLE_INTERVAL_S;

        /* ---- Log and print ---- */
        if (log_rpm(fp, rpm) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("RPM: %.2f\n", rpm);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    fclose(fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

