#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL_US 50000
#define HOLD_TIMEOUT_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN, %d) failed\n", state);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(RELAY_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_relay(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        safe_set_relay(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch = 0;
    int hold_active = 0;

    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_PIN) failed\n");
            break;
        }

        if (touch && !last_touch) {
            relay_state = !relay_state;
            if (safe_set_relay(relay_state) != 0) {
                break;
            }
            hold_active = 1;
            printf("Touch detected, relay toggled to %d\n", relay_state);
        }

        if (hold_active && touch) {
            static time_t touch_start = 0;
            if (touch_start == 0) {
                touch_start = time(NULL);
            } else if (difftime(time(NULL), touch_start) > HOLD_TIMEOUT_S) {
                printf("Hold timeout reached, forcing relay OFF\n");
                if (safe_set_relay(0) != 0) {
                    break;
                }
                relay_state = 0;
                hold_active = 0;
            }
        } else {
            touch_start = 0;
            hold_active = 0;
        }

        last_touch = touch;
        usleep(POLL_INTERVAL_US);
    }

    safe_set_relay(0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

