code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define VALVE_GPIO          23
#define FLOW_SENSOR_GPIO    24
#define PWM_GPIO            18
#define PWM_RANGE           255
#define PWM_FREQ            1000
#define SAMPLE_INTERVAL_US  100000
#define LOG_FILE            "flow_log.csv"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t flow_count = 0;
static FILE *log_file = NULL;
static double target_flow_rate = 0.0;
static double kp = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    flow_count++;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_GPIO);
        return -1;
    }
    if (gpioWrite(VALVE_GPIO, 1) < 0) {
        fprintf(stderr, "Error: failed to write GPIO %d high.\n", VALVE_GPIO);
        return -1;
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_GPIO);
        return -1;
    }
    if (gpioPWM(PWM_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty cycle on GPIO %d.\n", PWM_GPIO);
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", FLOW_SENSOR_GPIO);
        return -1;
    }
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n", FLOW_SENSOR_GPIO);
        return -1;
    }

    return 0;
}

static int open_log_file(void) {
