/*
 * PID speed control for two L298N-driven DC motors with quadrature encoders.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring:
 *   Motor 1 ENA -> GPIO 23 (BCM)
 *   Motor 1 IN1 -> GPIO 24 (BCM)
 *   Motor 1 IN2 -> GPIO 25 (BCM)
 *   Motor 2 ENB -> GPIO 12 (BCM)
 *   Motor 2 IN3 -> GPIO 16 (BCM)
 *   Motor 2 IN4 -> GPIO 20 (BCM)
 *   Encoder 1 A -> GPIO 5  (BCM)
 *   Encoder 1 B -> GPIO 6  (BCM)
 *   Encoder 2 A -> GPIO 26 (BCM)
 *   Encoder 2 B -> GPIO 19 (BCM)
 *
 * Build:  gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lpthread
 * Run:    sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

/* ---- PID parameters ---- */
#define KP 1.0f
#define KI 0.01f
#define KD 0.1f

/* ---- Target speed (RPM) ---- */
#define TARGET_SPEED 60.0f

/* ---- PWM parameters ---- */
#define PWM_FREQUENCY 1000   /* Hz */
#define PWM_RANGE     1000   /* duty-cycle steps */

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

/* ---- Log file ---- */
#define LOG_FILE "motor_log.csv"

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ---- Encoder state ---- */
typedef struct {
    int32_t count;
    pthread_mutex_t mutex;
} encoder_t;

static encoder_t g_encoder1 = {0, PTHREAD_MUTEX_INITIALIZER};
static encoder_t g_encoder2 = {0, PTHREAD_MUTEX_INITIALIZER};

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Motor control ---- */
static void motor_set(int en, int in1, int in2, int duty)
{
    if (duty >= 0) {
        if (gpioWrite(en, 1) < 0) return;
        if (gpioWrite(in1, duty > 0 ? 1 : 0) < 0) return;
        if (gpioWrite(in2, duty > 0 ? 0 : 1) < 0) return;
    } else {
        if (gpioWrite(en, 0) < 0) return;
        if (gpioWrite(in1, 0) < 0) return;
        if (gpioWrite(in2, 0) < 0) return;
    }
}

static void motor1_set(int duty)
{
    motor_set(MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, duty);
}

static void motor2_set(int duty)
{
    motor_set(MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4, duty);
}

/* ---- Quadrature decoder (thread-safe) ---- */
static void encoder_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)tick;
    encoder_t *enc = (encoder_t *)userdata;
    if (!enc) return;

    int32_t prev = enc->count;

    if (gpio == ENCODER1_A) {
        if (level == 1) {
            if (gpioRead(ENCODER1_B) == 1) enc->count++;
            else                        enc->count--;
        } else if (level == 0) {
            if (gpioRead(ENCODER1_B) == 0) enc->count++;
            else                        enc->count--;
        }
    } else if (gpio == ENCODER2_A) {
        if (level == 1) {
            if (gpioRead(ENCODER2_B) == 1) enc->count++;
            else                        enc->count--;
        } else if (level == 0) {
            if (gpioRead(ENCODER2_B) == 0) enc->count++;
            else                        enc->count--;
        }
    }
}

/* ---- PID ---- */
static float pid_step(float setpoint, float actual, float *integral, float *prev_error)
{
    float error = setpoint - actual;
    *integral += error;
    float derivative = error - *prev_error;
    float out = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return out;
}

/* ---- Speed (RPM) ---- */
static float speed_rpm(int32_t count, float period_s)
{
    return (float)count / (float)PWM_RANGE / period_s * 60.0f;
}

/* ---- Log ---- */
static void log_data(float sp, float act1, float act2, float p, float i, float d, float out)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            ts, sp, act1, act2, p, i, d, out);
    fflush(g_log);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    motor1_set(0);
    motor2_set(0);

    gpioSetMode(MOTOR1_ENA, PI_INPUT);
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);

    gpioSetAlertFuncEx(ENCODER1_A, NULL, NULL);
    gpioSetAlertFuncEx(ENCODER2_A, NULL, NULL);

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log, "timestamp,setpoint_rpm,actual1_rpm,actual2_rpm,P,I,D,output\n");
    fflush(g_log);

    /* ---- Configure motor pins as outputs ---- */
    if (gpioSetMode(MOTOR1_ENA, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENB, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure encoder pins as inputs with pull-ups ---- */
    if (gpioSetMode(ENCODER1_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER1_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set encoder pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    /* ---- Request alert callbacks for both edges on encoders ---- */
    if (gpioSetAlertFuncEx(ENCODER1_A, encoder_callback, &g_encoder1) < 0 ||
        gpioSetAlertFuncEx(ENCODER2_A, encoder_callback, &g_encoder2) < 0) {
        fprintf(stderr, "Failed to set encoder alert callbacks\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Start with motors stopped ---- */
    motor1_set(0);
    motor2_set(0);

    /* ---- PID state ---- */
    float integral1 = 0.0f, prev_error1 = 0.0f;
    float integral2 = 0.0f, prev_error2 = 0.0f;

    /* ---- Main control loop ---- */
    while (g_running) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        /* ---- Read encoders (thread-safe) ---- */
        int32_t enc1, enc2;
        pthread_mutex_lock(&g_encoder1.mutex);
        enc1 = g_encoder1.count;
        pthread_mutex_unlock(&g_encoder1.mutex);

        pthread_mutex_lock(&g_encoder2.mutex);
        enc2 = g_encoder2.count;
        pthread_mutex_unlock(&g_encoder2.mutex);

        /* ---- Compute speeds ---- */
        float sp = TARGET_SPEED;
        float act1 = speed_rpm(enc1, 0.1f);
        float act2 = speed_rpm(enc2, 0.1f);

        /* ---- PID ---- */
        float out1 = pid_step(sp, act1, &integral1, &prev_error1);
        float out2 = pid_step(sp, act2, &integral2, &prev_error2);

        /* ---- Software PWM: map output to duty-cycle (0..1000) ---- */
        int duty1 = (int)out1;
        int duty2 = (int)out2;
        if (duty1 < 0) duty1 = 0;
        if (duty1 > PWM_RANGE) duty1 = PWM_RANGE;
        if (duty2 < 0) duty2 = 0;
        if (duty2 > PWM_RANGE) duty2 = PWM_RANGE;

        motor1_set(duty1);
        motor2_set(duty2);

        /* ---- Log ---- */
        log_data(sp, act1, act2, KP * (sp - act1), KI * integral1, KD * (sp - act1) - prev_error1, out1);
        log_data(sp, act1, act2, KP * (sp - act2), KI * integral2, KD * (sp - act2) - prev_error2, out2);

        /* ---- Sleep until next sample ---- */
        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L
                        + (end.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us < SAMPLE_PERIOD_US) {
            usleep(SAMPLE_PERIOD_US - elapsed_us);
        }
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

