        long elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L
                        + (end.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us < SAMPLE_PERIOD_US) {
            usleep(SAMPLE_PERIOD_US - elapsed_us);
        }
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

