/*
 * MPR121 Capacitive Touch Relay Controller for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MPR121 capacitive touch sensor on I2C bus 1, address 0x5A
 *   - Relay module on GPIO 17 (BCM)
 *
 * Behavior:
 *   Polls the MPR121 every 50 ms.  When any electrode is touched, the relay
 *   is energized (HIGH).  Every state change is appended to relay_log.txt
 *   with a timestamp.  Robust error handling ensures clean shutdown on
 *   I2C or GPIO failures, and SIGINT (Ctrl-C) triggers a graceful exit.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS          "/dev/i2c-1"
#define MPR121_ADDR      0x5A
#define RELAY_GPIO       17
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define LOG_FILE         "relay_log.txt"

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_MHDR           0x2B
#define MPR121_NHDR           0x2C
#define MPR121_NCLR           0x2D
#define MPR121_FDLR           0x2E
#define MPR121_MHDF           0x2F
#define MPR121_NHDF           0x30
#define MPR121_NCLF           0x31
#define MPR121_FDLF           0x32
#define MPR121_NHDT           0x33
#define MPR121_NCLT           0x34
#define MPR121_FDLT           0x35
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_ECR            0x5E

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_relay_state = 0;

/* ----------------------------- Signal handler ---------------------------- */

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- MPR121 driver ----------------------------- */

static int mpr121_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(1000);  /* allow reset to complete */

    /* Filtering — rising */
    if (i2c_write_reg8(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLR, 0x00) < 0) return -1;

    /* Filtering — falling */
    if (i2c_write_reg8(fd, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDF, 0x05) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLF, 0x00) < 0) return -1;

    /* Filtering — touch */
    if (i2c_write_reg8(fd, MPR121_NHDT, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLT, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLT, 0x00) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI = 6 samples, CDC = 16 µA */
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CDT = 0.5 µs, SFI = 4 samples, ESI = 4 ms */
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg8(fd, MPR121_E0TTH + (i * 2), 0x0F) < 0) return -1;
        if (i2c_write_reg8(fd, MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (i2c_write_reg8(fd, MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static int mpr121_read_touch(int fd, uint16_t *touch_status)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *touch_status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ----------------------------- Relay control ----------------------------- */

static int relay_set(int state)
{
    if (g_relay_state == state)
        return 0;

    if (g_i2c_fd >= 0) {
        if (i2c_write_reg8(g_i2c_fd, MPR121_ECR, 0x00) < 0) {
            fprintf(stderr, "Failed to disable electrodes during relay change\n");
            return -1;
        }
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", RELAY_GPIO, strerror(errno));
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        fprintf(stderr, "Failed to write GPIO %d: %s\n", RELAY_GPIO, strerror(errno));
        return -1;
    }

    g_relay_state = state;

    if (g_i2c_fd >= 0) {
        if (i2c_write_reg8(g_i2c_fd, MPR121_ECR, 0x8C) < 0) {
            fprintf(stderr, "Failed to re-enable electrodes after relay change\n");
            return -1;
        }
    }

    return 0;
}

/* ----------------------------- Logging ----------------------------------- */

static void log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Relay state: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                state ? "HIGH" : "LOW");
    } else {
        fprintf(fp, "[timestamp error] - Relay state: %s\n", state ? "HIGH" : "LOW");
    }

    fclose(fp);
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus '%s': %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading ECR */
    uint8_t ecr_val = 0;
    if (i2c_read_reg8(g_i2c_fd, MPR121_ECR, &ecr_val) < 0) {
        fprintf(stderr, "MPR121 not detected at address 0x%02X on %s\n",
                MPR121_ADDR, I2C_BUS);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in a known state */
    if (relay_set(0) < 0) {
        fprintf(stderr, "Failed to initialize relay state\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPR121 initialized at 0x%02X on %s. Relay on GPIO %d. Press Ctrl-C to exit.\n",
           MPR121_ADDR, I2C_BUS, RELAY_GPIO);

    /* Main polling loop */
    while (g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch(g_i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Touch read error — attempting to re-initialize MPR121\n");
            /* Attempt to recover by soft-resetting */
            if (i2c_write_reg8(g_i2c_fd, MPR121_SOFTRESET, 0x63) < 0) {
                fprintf(stderr, "Soft reset failed; exiting\n");
                break;
            }
            usleep(1000);
            if (mpr121_init(g_i2c_fd) < 0) {
                fprintf(stderr, "Re-initialization failed; exiting\n");
                break;
            }
            continue;
        }

        int any_touched = (touch_status != 0);
        if (relay_set(any_touched) < 0) {
            fprintf(stderr, "Relay write error\n");
            break;
        }

        if (any_touched) {
            log_relay_state(1);
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    relay_set(0);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

