/*
 * MPR121 Capacitive Touch Relay Controller for Raspberry Pi Zero W
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MPR121 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MPR121 ADDR -> GND (I2C address 0x5A)
 *   Relay IN  -> GPIO17 (BCM)
 *
 * Behavior:
 *   - Initializes MPR121 in stop mode.
 *   - Configures touch and release thresholds for all 12 electrodes.
 *   - Sets filter and charge time registers.
 *   - Sets electrode current.
 *   - Stabilizes for 100 ms.
 *   - Enters run mode.
 *   - Monitors touch status. On any electrode touch, toggles relay.
 *   - Prints relay status to stdout.
 *   - Handles SIGINT/SIGTERM for graceful shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPR121_ADDR        0x5A
#define RELAY_GPIO         17
#define I2C_BUS            "/dev/i2c-1"
#define POLL_DELAY_MS      100
#define STABILIZE_MS       100

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_ELE0_T_THRESH  0x41
#define MPR121_ELE0_R_THRESH  0x42
#define MPR121_MHD_F          0x2B
#define MPR121_NHD_F          0x2C
#define MPR121_NCL_F          0x2D
#define MPR121_FDL_F          0x2E
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_ECR            0x5E
#define MPR121_SOFTRESET      0x80

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(1000);

    /* Stop mode */
    if (i2c_write_reg8(fd, MPR121_ECR, 0x00) < 0) return -1;

    /* Filter / charge configuration */
    if (i2c_write_reg8(fd, MPR121_MHD_F, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHD_F, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCL_F, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDL_F, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg8(fd, MPR121_ELE0_T_THRESH + (i * 2), 0x0F) < 0) return -1;
        if (i2c_write_reg8(fd, MPR121_ELE0_R_THRESH + (i * 2), 0x0A) < 0) return -1;
    }

    /* Debounce: 3 samples for touch, 3 for release */
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, CDC=16 µA, CDT=0.5 µs */
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CDT=0.5 µs, SFI=4 samples, ESI=4 ms */
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enter run mode */
    if (i2c_write_reg8(fd, MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

static int mpr121_read_touch(int fd, uint16_t *touch_status) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L + 1, &hi) < 0) return -1;
    *touch_status = (uint16_t)((hi << 8) | lo);
    return 0;
}

int main(void) {
    int fd = -1;
    int relay_state = 0;
    int ret = EXIT_FAILURE;

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize MPR121 */
    if (mpr121_init(fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        goto cleanup;
    }

    /* Stabilize sensor */
    usleep(STABILIZE_MS * 1000);

    /* Configure relay GPIO */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        goto cleanup;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", RELAY_GPIO);
        goto cleanup;
    }

    if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
        fprintf(stderr, "Failed to write to GPIO %d.\n", RELAY_GPIO);
        goto cleanup;
    }

    printf("MPR121 relay controller started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch(fd, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status. Retrying...\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        if (touch_status > 0) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                fprintf(stderr, "Failed to write to relay GPIO.\n");
            } else {
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    gpioTerminate();
    return ret;
}

