    *touch_status = (uint16_t)((hi << 8) | lo);
    return 0;
}

int main(void) {
    int fd = -1;
    int relay_state = 0;
    int ret = EXIT_FAILURE;

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize MPR121 */
    if (mpr121_init(fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        goto cleanup;
    }

    /* Stabilize sensor */
    usleep(STABILIZE_MS * 1000);

    /* Configure relay GPIO */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        goto cleanup;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", RELAY_GPIO);
        goto cleanup;
    }

    if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
        fprintf(stderr, "Failed to write to GPIO %d.\n", RELAY_GPIO);
        goto cleanup;
    }

    printf("MPR121 relay controller started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch(fd, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status. Retrying...\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        if (touch_status > 0) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                fprintf(stderr, "Failed to write to relay GPIO.\n");
            } else {
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    gpioTerminate();
    return ret;
}

