#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_GPIO        17
#define RELAY_GPIO      18
#define UNLOCK_MS       500
#define RATE_LIMIT_S    2
#define POLL_MS         50
#define LOG_FILE        "door_events.log"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *event)
{
    if (!g_log) return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, event);
    fflush(g_log);
}

static void unlock_door(void)
{
    if (gpioWrite(RELAY_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to activate relay on GPIO %d\n", RELAY_GPIO);
        log_event("ERROR: relay activation failed");
        return;
    }
    log_event("Door unlocked");

    gpioDelay(UNLOCK_MS * 1000);

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to deactivate relay on GPIO %d\n", RELAY_GPIO);
        log_event("ERROR: relay deactivation failed");
        return;
    }
    log_event("Door locked");
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", PIR_GPIO);
        goto cleanup;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        goto cleanup;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", PIR_GPIO);
        goto cleanup;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay state on GPIO %d\n", RELAY_GPIO);
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");
    log_event("System started");

    int last_state = 0;
    time_t last_unlock_time = 0;

    while (g_running) {
        int pir = gpioRead(PIR_GPIO);
        if (pir < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", PIR_GPIO);
            log_event("ERROR: PIR read failed");
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        if (pir == 1 && last_state == 0) {
            time_t now = time(NULL);
            if (difftime(now, last_unlock_time) >= RATE_LIMIT_S) {
                unlock_door();
                last_unlock_time = now;
            } else {
                log_event("Motion detected (rate-limited)");
            }
        }
        last_state = pir;
        gpioDelay(POLL_MS * 1000);
    }

cleanup:
    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (g_log) {
        log_event("System stopped");
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

