#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DELAY_MS 50
#define MAX_DELAY_MS 200

typedef struct {
    int duty1;
    int duty2;
    int delay_ms;
} HapticPattern;

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int set_motor_pwm(int pin, int duty) {
    if (duty < MIN_DUTY || duty > MAX_DUTY) {
        fprintf(stderr, "Error: duty cycle %d out of range (0-%d)\n", duty, MAX_DUTY);
        return -1;
    }
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int generate_pattern(HapticPattern *pattern) {
    pattern->duty1 = (rand() % (MAX_DUTY + 1));
    pattern->duty2 = (rand() % (MAX_DUTY + 1));
    pattern->delay_ms = (rand() % (MAX_DELAY_MS - MIN_DELAY_MS + 1)) + MIN_DELAY_MS;
    return 0;
}

static void play_pattern(const HapticPattern *pattern) {
    set_motor_pwm(MOTOR1_PIN, pattern->duty1);
    set_motor_pwm(MOTOR2_PIN, pattern->duty2);
    gpioDelay(pattern->delay_ms * 1000);
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Haptic feedback started. Press Ctrl+C to stop.\n");

    while (!shutdown_flag) {
        int num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;
        HapticPattern *patterns = (HapticPattern *)malloc((size_t)num_steps * sizeof(HapticPattern));
        if (patterns == NULL) {
            fprintf(stderr, "Error: memory allocation failed\n");
            break;
        }

        for (int i = 0; i < num_steps; i++) {
            if (generate_pattern(&patterns[i]) != 0) {
                free(patterns);
                break;
            }
        }

        for (int i = 0; i < num_steps && !shutdown_flag; i++) {
            play_pattern(&patterns[i]);
        }

        free(patterns);
    }

    stop_motors();
    gpioTerminate();
    printf("Haptic feedback stopped.\n");
    return EXIT_SUCCESS;
}

