#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define HX711_TIMEOUT_US 500000
#define HX711_SETTLE_US 1
#define HX711_READ_INTERVAL_US 500000
#define CALIBRATION_SAMPLES 100

static volatile sig_atomic_t running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *out_value) {
    long value = 0;
    uint32_t start_tick = gpioTick();

    while (gpioRead(data_pin) == 1) {
        if ((int32_t)(gpioTick() - start_tick) > HX711_TIMEOUT_US) {
            return -1;
        }
        gpioDelay(HX711_SETTLE_US);
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(HX711_SETTLE_US);
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(HX711_SETTLE_US);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(HX711_SETTLE_US);
    gpioWrite(clock_pin, 0);
    gpioDelay(HX711_SETTLE_US);

    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }

    *out_value = value;
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, double *scale, double *offset) {
    long sum = 0;
    int valid_samples = 0;

    printf("Starting calibration (zero-load sampling)...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        long val;
        if (read_hx711(data_pin, clock_pin, &val) != 0) {
            fprintf(stderr, "Calibration read %d failed (timeout)\n", i);
            continue;
        }
        sum += val;
        valid_samples++;
        gpioDelay(10000);
    }

    if (valid_samples == 0) {
        fprintf(stderr, "Calibration failed: no valid samples\n");
        return -1;
    }

    long avg_zero = sum / valid_samples;
    printf("Calibration complete. Average raw value at zero load: %ld\n", avg_zero);

    sum = 0;
    valid_samples = 0;
    printf("Place known weight on sensor and press Enter to continue...\n");
    getchar();

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        long val;
        if (read_hx711(data_pin, clock_pin, &val) != 0) {
            fprintf(stderr, "Calibration read %d failed (timeout)\n", i);
            continue;
        }
        sum += val;
        valid_samples++;
        gpioDelay(10000);
    }

    if (valid_samples == 0) {
        fprintf(stderr, "Calibration failed: no valid samples\n");
        return -1;
    }

    long avg_weighted = sum / valid_samples;
    printf("Average raw value with weight: %ld\n", avg_weighted);

    *scale = (double)(avg_weighted - avg_zero) / 100.0;
    *offset = (double)avg_zero;

    printf("Calibration data: scale=%.2f, offset=%.2f\n", *scale, *offset);
    return 0;
}

static int load_calibration(const char *filename, double *scale, double *offset) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: calibration file '%s' not found (%s). Using defaults.\n",
                filename, strerror(errno));
        return -1;
    }

    if (fscanf(fp, "%lf %lf", scale, offset) != 2) {
        fprintf(stderr, "Warning: calibration file '%s' invalid. Using defaults.\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Loaded calibration: scale=%.2f, offset=%.2f\n", *scale, *offset);
    return 0;
}

static int save_calibration(const char *filename, double scale, double offset) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error: cannot write calibration file '%s' (%s)\n",
                filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "%.6f %.6f\n", scale, offset);
    fclose(fp);
    printf("Calibration saved to %s\n", filename);
    return 0;
}

static double calculate_weight(long raw_value, double scale, double offset) {
    return (double)(raw_value - offset) / scale;
}

static int log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file '%s' (%s)\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0 ||
        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);

    if (load_calibration(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset) != 0) {
            fprintf(stderr, "Error: calibration failed\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }
        save_calibration(CALIBRATION_FILE, scale_factor, offset);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler (%s)\n", strerror(errno));
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        long raw_value;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
            fprintf(stderr, "Warning: HX711 read timeout, skipping iteration\n");
            gpioDelay(HX711_READ_INTERVAL_US);
            continue;
        }

        double weight = calculate_weight(raw_value, scale_factor, offset);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight exceeded threshold (%.2f kg). Solenoid engaged.\n", weight);
