#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define MOTOR_RUN_TIME_S 5
#define CHECK_INTERVAL_S 60
#define POST_CLOSE_DELAY_S 60

#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define PWM_RANGE 255

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_rain_sensor(void) {
    int rain_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpioRead(RAIN_SENSOR_PIN);
        if (val < 0) {
            syslog(LOG_ERR, "gpioRead failed on rain sensor pin %d: %s", RAIN_SENSOR_PIN, strerror(errno));
            return -1;
        }
        if (val == 0) {
            rain_count++;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }
    return (rain_count >= 3) ? 1 : 0;
}

static int control_motor(int state) {
    if (state == 1) {
        if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
            syslog(LOG_ERR, "gpioWrite failed on IN1 pin %d: %s", MOTOR_IN1_PIN, strerror(errno));
            return -1;
        }
        if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
            syslog(LOG_ERR, "gpioWrite failed on IN2 pin %d: %s", MOTOR_IN2_PIN, strerror(errno));
            return -1;
        }
        if (gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE) < 0) {
            syslog(LOG_ERR, "gpioPWM failed on PWM pin %d: %s", MOTOR_PWM_PIN, strerror(errno));
            return -1;
        }
        syslog(LOG_INFO, "Motor running for %d seconds...", MOTOR_RUN_TIME_S);
        return 0;
    } else if (state == 0) {
        if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
            syslog(LOG_ERR, "gpioWrite failed on IN1 pin %d: %s", MOTOR_IN1_PIN, strerror(errno));
            return -1;
        }
        if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
            syslog(LOG_ERR, "gpioWrite failed on IN2 pin %d: %s", MOTOR_IN2_PIN, strerror(errno));
            return -1;
        }
        if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
            syslog(LOG_ERR, "gpioPWM failed on PWM pin %d: %s", MOTOR_PWM_PIN, strerror(errno));
            return -1;
        }
        syslog(LOG_INFO, "Motor stopped.");
        return 0;
    }
    syslog(LOG_ERR, "Invalid motor state: %d", state);
    return -1;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed for rain sensor pin %d: %s", RAIN_SENSOR_PIN, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed for IN1 pin %d: %s", MOTOR_IN1_PIN, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed for IN2 pin %d: %s", MOTOR_IN2_PIN, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed for PWM pin %d: %s", MOTOR_PWM_PIN, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed for PWM pin %d: %s", MOTOR_PWM_PIN, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_PWM_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed for PWM pin %d: %s", MOTOR_PWM_PIN, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0 || gpioWrite(MOTOR_IN2_PIN, 0) < 0 || gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Initial GPIO state write failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Window control system started.");

    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected < 0) {
            syslog(LOG_ERR, "Rain sensor read error, skipping cycle.");
        } else if (rain_detected == 1) {
            log_event("Rain detected!");
            if (control_motor(1) == 0) {
                for (int i = 0; i < MOTOR_RUN_TIME_S && program_running; i++) {
                    gpioDelay(1000000);
                }
                if (control_motor(0) == 0) {
                    log_event("Motor stopped after rain event.");
                } else {
                    log_event("Failed to stop motor after rain event.");
                }
            } else {
                log_event("Failed to start motor.");
            }
            for (int i = 0; i < POST_CLOSE_DELAY_S && program_running; i++) {
                gpioDelay(1000000);
            }
        } else {
            log_event("No rain detected.");
        }

        for (int i = 0; i < CHECK_INTERVAL_S && program_running; i++) {
            gpioDelay(1000000);
        }
    }

    syslog(LOG_INFO, "Shutting down window control system.");
    control_motor(0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

