#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define STOCK_THRESHOLD 100.0
#define LOCK_DURATION 5
#define LOG_FILE "stock_events.txt"
#define HX711_TIMEOUT_US 1000000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_hx711(int dt_pin, int sck_pin, long *out_value) {
    if (out_value == NULL) return -1;

    int timeout = 0;
    while (gpioRead(dt_pin) == 1) {
        gpioDelay(100);
        timeout += 100;
        if (timeout >= HX711_TIMEOUT_US) {
            log_event("HX711 timeout waiting for data ready");
            return -1;
        }
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(sck_pin, 1) < 0) {
            log_event("Failed to set SCK high");
            return -1;
        }
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(dt_pin)) {
            value |= 1;
        }
        if (gpioWrite(sck_pin, 0) < 0) {
            log_event("Failed to set SCK low");
            return -1;
        }
        gpioDelay(1);
    }

    if (gpioWrite(sck_pin, 1) < 0) {
        log_event("Failed to set SCK high for 30 us");
        return -1;
    }
    gpioDelay(30);
    if (gpioWrite(sck_pin, 0) < 0) {
        log_event("Failed to set SCK low after 30 us");
        return -1;
    }

    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }

    *out_value = value;
    return 0;
}

static float calculate_weight(long raw_value) {
    return (float)raw_value / 100.0;
}

static void activate_solenoid(int pin, int duration_seconds) {
    if (gpioWrite(pin, 1) < 0) {
        log_event("Failed to activate solenoid");
        return;
    }
    log_event("Solenoid activated");
    sleep(duration_seconds);
    if (gpioWrite(pin, 0) < 0) {
        log_event("Failed to deactivate solenoid");
    } else {
        log_event("Solenoid deactivated");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO modes");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(HX711_SCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_event("Failed to set signal handlers");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (running) {
        long raw_value = 0;
        if (read_hx711(HX711_DT_PIN, HX711_SCK_PIN, &raw_value) != 0) {
            log_event("Error reading HX711");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float weight = calculate_weight(raw_value);

        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Weight: %.2f g", weight);
        log_event(log_message);

        if (weight < STOCK_THRESHOLD) {
            activate_solenoid(SOLENOID_PIN, LOCK_DURATION);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Program terminated");
    gpioTerminate();
    return EXIT_SUCCESS;
}

