/*
 * Raspberry Pi 4 Model B – HX711 Load Cell Security Monitor
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO4  (BCM)
 *   HX711 PD_SCK-> GPIO17 (BCM)
 *   Solenoid    -> GPIO27 (BCM)
 *
 * Build: gcc -O2 -Wall -o security security.c -lpigpio -lrt
 * Run:   sudo ./security
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define HX711_DOUT_PIN      4
#define HX711_SCK_PIN       17
#define SOLENOID_PIN        27

#define CALIBRATION_FILE    "calibration.txt"
#define LOG_FILE            "security.log"

#define WEIGHT_THRESHOLD    5.0f   /* kg */
#define SOLENOID_HOLD_SEC   5      /* seconds */
#define SAMPLE_DELAY_US     100000 /* 100 ms between samples */
#define HX711_TIMEOUT_US    100000 /* 100 ms timeout for DOUT high */
#define CALIBRATION_TIMEOUT_US 1000000 /* 1 s timeout for known weight entry */

#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_US 100000 /* 100 ms between samples */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static FILE *g_cal_fp = NULL;

/* --------------------------- Function prototypes -------------------------- */
static int  hx711_init(void);
static int  hx711_read_raw(int32_t *out);
static float hx711_read_weight(int32_t raw, float cal_factor);
static int  hx711_calibrate(float *cal_factor);
static void solenoid_lock(void);
static void solenoid_unlock(void);
static void log_event(float weight);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- HX711 driver ----------------------------- */
static int hx711_init(void)
{
    if (gpioSetMode(HX711_DOUT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set DOUT pin %d as input\n", HX711_DOUT_PIN);
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SCK pin %d as output\n", HX711_SCK_PIN);
        return -1;
    }
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize SCK pin low\n");
        return -1;
    }
    return 0;
}

/*
 * Read 24 raw bits from the HX711, then send a 25th clock pulse to
 * select the gain channel A for the next reading.
 * Returns 0 on success, -1 on timeout or GPIO error.
 */
static int hx711_read_raw(int32_t *out)
{
    uint32_t count = 0;
    uint32_t elapsed = 0;

    /* Wait for DOUT to go low (data ready), with timeout */
    while (gpioRead(HX711_DOUT_PIN) == 1) {
        gpioDelay(100); /* 100 µs */
        elapsed += 100;
        if (elapsed >= HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 DOUT timeout (sensor absent or not ready)\n");
            return -1;
        }
    }

    /* Read 24 data bits, MSB first */
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            fprintf(stderr, "Error: failed to set SCK high\n");
            return -1;
        }
        gpioDelay(1); /* >0.2 µs high */

        count <<= 1;
        if (gpioRead(HX711_DOUT_PIN) == 1) {
            count |= 1;
        }

        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            fprintf(stderr, "Error: failed to set SCK low\n");
            return -1;
        }
        gpioDelay(1); /* >0.2 µs low */
    }

    /* 25th clock pulse: select channel A for next reading */
    if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set 25th SCK high\n");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set 25th SCK low\n");
        return -1;
    }
    gpioDelay(1);

    /* Sign-extend 24-bit two's-complement to 32-bit */
    if (count & 0x800000) {
        count |= 0xFF000000;
    }

    *out = (int32_t)count;
    return 0;
}

static float hx711_read_weight(int32_t raw, float cal_factor)
{
    return (float)raw / cal_factor;
}

/*
 * Calibrate the HX711 by averaging CALIBRATION_SAMPLES readings of a known
 * weight. Returns 0 on success, -1 on error.
 */
static int hx711_calibrate(float *cal_factor)
{
    int32_t raw;
    float sum = 0.0f;
    int valid = 0;

    printf("Calibration: place a known weight on the load cell.\n");
    printf("Press Enter when ready...");
    fflush(stdout);
    int c;
    while ((c = getchar()) != '\n' && c != EOF) {
        /* discard */
    }

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (hx711_read_raw(&raw) != 0) {
            fprintf(stderr, "Error: HX711 read failed during calibration (sample %d)\n", i + 1);
            return -1;
        }
        sum += (float)raw;
        valid++;
        gpioDelay(CALIBRATION_DELAY_US);
    }

    if (valid == 0) {
        fprintf(stderr, "Error: no valid calibration samples collected\n");
        return -1;
    }

    float avg = sum / valid;
    printf("Calibration average: raw = %.2f\n", avg);

    /* Prompt for the known weight in kg */
    float known_weight;
    printf("Enter the weight in kg: ");
    fflush(stdout);
    if (scanf("%f", &known_weight) != 1 || known_weight <= 0.0f) {
        fprintf(stderr, "Error: invalid weight input\n");
        return -1;
    }
    while (getchar() != '\n') {
        /* discard */
    }

    *cal_factor = avg / known_weight;
    printf("Calibration factor: %.4f\n", *cal_factor);
    return 0;
}

/* --------------------------- Solenoid control ----------------------------- */
static void solenoid_lock(void)
{
    printf("Locking solenoid for %d seconds...\n", SOLENOID_HOLD_SEC);
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set solenoid high\n");
        return;
    }
    gpioDelay(SOLENOID_HOLD_SEC * 1000000); /* 5 s */
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set solenoid low\n");
    }
    printf("Solenoid unlocked.\n");
}

static void solenoid_unlock(void)
{
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to unlock solenoid (low)\n");
    }
}

/* ------------------------------- Logging ---------------------------------- */
static void log_event(float weight)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (g_log_fp == NULL) {
        g_log_fp = fopen(LOG_FILE, "a");
        if (g_log_fp == NULL) {
            perror("Error opening log file");
            return;
        }
    }

    if (fprintf(g_log_fp, "%s, Weight: %.2f kg\n", ts, weight) < 0) {
        perror("Error writing to log file");
    }
    if (fflush(g_log_fp) != 0) {
        perror("Error flushing log file");
    }
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    solenoid_unlock();

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_cal_fp != NULL) {
        fclose(g_cal_fp);
        g_cal_fp = NULL;
    }

    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize HX711 */
    if (hx711_init() != 0) {
        fprintf(stderr, "Error: HX711 initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize solenoid pin */
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set solenoid pin %d as output\n", SOLENOID_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    solenoid_unlock();

    /* Open calibration file for reading */
    g_cal_fp = fopen(CALIBRATION_FILE, "r");
    if (g_cal_fp != NULL) {
        float cal_factor;
        if (fscanf(g_cal_fp, "%f", &cal_factor) == 1) {
            printf("Calibration factor loaded: %.4f\n", cal_factor);
        } else {
            fprintf(stderr, "Warning: calibration file unreadable, recalibrating...\n");
            fclose(g_cal_fp);
            g_cal_fp = NULL;
        }
    }

    if (g_cal_fp == NULL) {
        float cal_factor;
        if (hx711_calibrate(&cal_factor) != 0) {
            fprintf(stderr, "Error: calibration failed\n");
            cleanup();
            return EXIT_FAILURE;
        }
        g_cal_fp = fopen(CALIBRATION_FILE, "w");
        if (g_cal_fp == NULL) {
            perror("Error opening calibration file for writing");
            cleanup();
            return EXIT_FAILURE;
        }
        if (fprintf(g_cal_fp, "%.4f\n", cal_factor) < 0) {
            perror("Error writing calibration factor");
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(g_cal_fp) != 0) {
            perror("Error flushing calibration file");
        }
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring weight. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int32_t raw;
        if (hx711_read_raw(&raw) != 0) {
            fprintf(stderr, "Error: HX711 read failed, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float weight = hx711_read_weight(raw, 0.0f);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            solenoid_lock();
            log_event(weight);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

