#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN 16
#define RELAY_PIN  20
#define LOG_FILE   "relay_events.log"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *log_fp, int relay_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s - Relay %s\n", timestamp,
                relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *relay_line = NULL;
    FILE *log_fp = NULL;
    int relay_state = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (sensor_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (relay_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "ky022_sensor") < 0) {
        fprintf(stderr, "gpiod_line_request_input(sensor) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "sr05_relay", relay_state) < 0) {
        fprintf(stderr, "gpiod_line_request_output(relay) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Monitoring KY022 on GPIO%d, relay on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_PIN, RELAY_PIN);

    while (program_running) {
        int sensor_val = gpiod_line_get_value(sensor_line);
        if (sensor_val < 0) {
            fprintf(stderr, "gpiod_line_get_value(sensor) failed: %s\n",
                    strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* KY022 is active-low: LOW (0) means obstacle detected */
        if (sensor_val == 0) {
            relay_state = !relay_state;
            if (gpiod_line_set_value(relay_line, relay_state) < 0) {
                fprintf(stderr, "gpiod_line_set_value(relay) failed: %s\n",
                        strerror(errno));
            } else {
                if (log_event(log_fp, relay_state) < 0) {
                    fprintf(stderr, "Failed to log event.\n");
                }
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line != NULL) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line != NULL) {
        gpiod_line_release(sensor_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

