    }

    if (log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "fprintf() to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Activate the buzzer for BUZZER_DURATION_US microseconds             */
/* ------------------------------------------------------------------ */
static int activate_buzzer(void)
{
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set buzzer HIGH on GPIO %d\n", BUZZER_PIN);
        return -1;
    }

    usleep(BUZZER_DURATION_US);

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set buzzer LOW on GPIO %d\n", BUZZER_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — called on every exit path                                */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure buzzer is off */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off buzzer during cleanup\n");
    }

    /* Close log file */
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: fclose() failed: %s\n",
                    strerror(errno));
        }
        log_file = NULL;
    }

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure PIR pin as input ---- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure buzzer pin as output, initial value LOW ---- */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise buzzer state on GPIO %d\n",
                BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file for appending ---- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motion detection system started.\n");
    printf("  PIR sensor : GPIO %d (active-high)\n", PIR_PIN);
    printf("  Buzzer     : GPIO %d (2 s per event)\n", BUZZER_PIN);
    printf("  Log file   : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (running) {
        if (gpioRead(PIR_PIN) == 1) {
            printf("Motion detected!\n");

            if (activate_buzzer() != 0) {
                fprintf(stderr, "Buzzer activation failed; continuing.\n");
            }

            if (log_motion_event() != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }

        usleep(100000);  /* 100 ms poll interval */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

