/*
 * Timed watering system for Raspberry Pi 3 Model B+
 * Valve: Parker Hannifin Series 9 General Purpose Miniature Solenoid Valve
 *        (12 V, 1.6 W)  External N-channel MOSFET/relay module on GPIO18 (BCM)
 * Config: watering.conf, one line: duration=<seconds>
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define CONFIG_FILE      "watering.conf"
#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 18          /* BCM 18 */
#define MIN_DURATION     1           /* seconds */
#define MAX_DURATION     3600        /* seconds */
#define POLL_INTERVAL_S  1           /* seconds between status reports */

static volatile sig_atomic_t g_stop = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_stop = 1;
}

/* ------------------------------------------------------------------ */
/* Read watering duration from config file.
 * Returns 0 on success, -1 on error.  *duration is set on success.   */
static int read_watering_duration(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        if (feof(fp))
            fprintf(stderr, "Config file '%s' is empty.\n", filename);
        else
            fprintf(stderr, "Error reading config file '%s': %s\n",
                    filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Strip trailing whitespace / newline */
    line[strcspn(line, "\r\n")] = '\0';

    char *eq = strchr(line, '=');
    if (!eq) {
        fprintf(stderr, "Malformed config line (no '='): '%s'\n", line);
        return -1;
    }

    *eq = '\0';
    char *key = line;
    char *val = eq + 1;

    /* Strip leading whitespace from key */
    while (*key == ' ') key++;

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Unexpected config key '%s', expected 'duration'.\n", key);
        return -1;
    }

    errno = 0;
    char *end = NULL;
    long val_l = strtol(val, &end, 10);
    if (errno != 0 || end == val || *end != '\0') {
        fprintf(stderr, "Invalid duration value '%s'\n", val);
        return -1;
    }

    if (val_l < MIN_DURATION || val_l > MAX_DURATION) {
        fprintf(stderr, "Duration %ld out of range [%d, %d]\n",
                val_l, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val_l;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sleep for the given number of seconds, interruptible by signals.   */
static void sleep_interruptible(unsigned int seconds)
{
    while (seconds > 0 && !g_stop) {
        unsigned int remaining = (seconds > 60) ? 60 : seconds;
        remaining = sleep(remaining);
        seconds -= remaining;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Read watering duration ---- */
    int duration = 0;
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Failed to read watering duration from '%s'.\n",
                CONFIG_FILE);
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);
    fflush(stdout);

    /* ---- Open GPIO chip ---- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get GPIO line ---- */
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* ---- Request line as output, initial value LOW (valve off) ---- */
    if (gpiod_line_request_output(line, "watering-valve", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* ---- Activate valve ---- */
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to activate valve (set GPIO high): %s\n",
                strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    printf("Valve activated (GPIO %d HIGH)\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* ---- Watering duration ---- */
    sleep_interruptible((unsigned int)duration);

    /* ---- Deactivate valve ---- */
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Warning: failed to deactivate valve (set GPIO low): %s\n",
                strerror(errno));
    } else {
        printf("Valve deactivated (GPIO %d LOW)\n", GPIO_LINE_OFFSET);
        fflush(stdout);
    }

    /* ---- Cleanup ---- */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Watering cycle complete.\n");
    return EXIT_SUCCESS;
}

