    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set left sensor pin mode.\n");
        return -1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set middle sensor pin mode.\n");
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set right sensor pin mode.\n");
        return -1;
    }

    if (gpioSetMode(LEFT_MOTOR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set left motor pin mode.\n");
        return -1;
    }
    if (gpioSetMode(RIGHT_MOTOR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set right motor pin mode.\n");
        return -1;
    }

    if (gpioSetPWMfrequency(LEFT_MOTOR_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set left motor PWM frequency.\n");
        return -1;
    }
    if (gpioSetPWMfrequency(RIGHT_MOTOR_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set right motor PWM frequency.\n");
        return -1;
    }

    if (gpioSetPWMrange(LEFT_MOTOR_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set left motor PWM range.\n");
        return -1;
    }
    if (gpioSetPWMrange(RIGHT_MOTOR_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set right motor PWM range.\n");
        return -1;
    }

    return 0;
}

static void stop_motors(void)
{
    gpioPWM(LEFT_MOTOR_PIN, 0);
    gpioPWM(RIGHT_MOTOR_PIN, 0);
}

static void set_motor_speed(int left_speed, int right_speed)
{
    if (left_speed < 0) left_speed = 0;
    if (left_speed > PWM_RANGE) left_speed = PWM_RANGE;
    if (right_speed < 0) right_speed = 0;
    if (right_speed > PWM_RANGE) right_speed = PWM_RANGE;

    gpioPWM(LEFT_MOTOR_PIN, left_speed);
    gpioPWM(RIGHT_MOTOR_PIN, right_speed);
}

static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read sensor on pin %d.\n", pin);
        return -1;
    }
    return value;
}

static void log_data(int left_sensor, int middle_sensor, int right_sensor,
                     int left_speed, int right_speed)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(g_log_file, "%s, %d, %d, %d, %d, %d\n",
                timestamp, left_sensor, middle_sensor, right_sensor,
                left_speed, right_speed) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
    }
}

static void control_robot(int left_sensor, int middle_sensor, int right_sensor)
{
    if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 1) {
        set_motor_speed(BASE_SPEED, BASE_SPEED);
    } else if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 0) {
        set_motor_speed(TURN_SPEED, BASE_SPEED);
    } else if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 1) {
        set_motor_speed(BASE_SPEED, TURN_SPEED);
    } else {
        stop_motors();
    }
}

static void cleanup(void)
{
    stop_motors();

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int left_sensor  = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor  = read_sensor(RIGHT_SENSOR_PIN);

        if (left_sensor < 0 || middle_sensor < 0 || right_sensor < 0) {
            fprintf(stderr, "Error: sensor read failure, stopping motors.\n");
            stop_motors();
            break;
        }

        control_robot(left_sensor, middle_sensor, right_sensor);

        log_data(left_sensor, middle_sensor, right_sensor,
                 gpioGetPWMdutycycle(LEFT_MOTOR_PIN),
                 gpioGetPWMdutycycle(RIGHT_MOTOR_PIN));

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

