#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int read_lux(float *lux_out) {
    if (i2c_fd < 0) return -1;
    uint8_t cmd = 0x10; /* Continuous High-Resolution Mode */
    if (write(i2c_fd, &cmd, 1) != 1) {
        log_event("Error: Failed to write measurement command to BH1750");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000);
    uint8_t buf[2];
    ssize_t n = read(i2c_fd, buf, 2);
    if (n != 2) {
        log_event("Error: Failed to read 2 bytes from BH1750");
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    log_event("Program started");

    while (running) {
        float lux;
        if (read_lux(&lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (lux < LUX_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
                log_event("Grow lamp turned ON");
            } else {
                gpioWrite(RELAY_GPIO, 0);
                log_event("Grow lamp turned OFF");
            }
        } else {
            log_event("Error: Failed to read lux value");
        }
        gpioDelay(5000000);
    }

    log_event("Program stopped");
    gpioWrite(RELAY_GPIO, 0);
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

