#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_LOCK_PULSE 1000
#define SERVO_UNLOCK_PULSE 2000

#define DEBOUNCE_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button GPIOs as input\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up resistors\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(LOCK_BUTTON) == 0) {
                if (gpioServo(SERVO_PIN, SERVO_LOCK_PULSE) == 0) {
                    printf("Locking door...\n");
                } else {
                    fprintf(stderr, "Error: failed to set servo pulse\n");
                }
                while (running && gpioRead(LOCK_BUTTON) == 0) {
                    gpioDelay(10000);
                }
            }
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                if (gpioServo(SERVO_PIN, SERVO_UNLOCK_PULSE) == 0) {
                    printf("Unlocking door...\n");
                } else {
                    fprintf(stderr, "Error: failed to set servo pulse\n");
                }
                while (running && gpioRead(UNLOCK_BUTTON) == 0) {
                    gpioDelay(10000);
                }
            }
        }

        gpioDelay(10000);
    }

    cleanup();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

