/*
 * Haptic feedback system for Raspberry Pi 4 Model B
 *
 * Two Precision Microdrives 310-101 vibration motors are driven through
 * external NPN transistor circuits (e.g. ULN2003) on GPIO17 and GPIO27.
 *
 * Build:  gcc -O2 -Wall -Wextra -o haptic haptic.c -lgpiod
 *
 * Motor 1: GPIO17 (BCM)  -> NPN base  -> motor V+ (3 V)
 * Motor 2: GPIO27 (BCM)  -> NPN base  -> motor V+ (3 V)
 * Motor GND -> motor GND
 * NPN Emitter -> motor V+ via 1 kΩ resistor
 * NPN Collector -> motor GND
 * NPN Base -> GPIO (e.g. 1 kΩ pull-up, 1 kΩ pull-down)
 * NPN Base -> 3 V (motor supply)
 * NPN Base -> 1 kΩ -> GPIO (motor supply)
 * NPN Base -> 1 kΩ -> GND (motor supply)
 *
 * The Pi GPIO pins are NOT directly driven; the motors require 3 V at
 * 60 mA and the Pi GPIO only source ~3.3 V.  An external NPN transistor
 * with flyback diode is required to safely drive the motors.
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define MOTOR1_DURATION_MS 200
#define MOTOR2_DURATION_MS 300

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* Retry on EINTR so signals are caught promptly. */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 4). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line(MOTOR1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (motor off). */
    if (gpiod_line_request_output(line1, "haptic-motor1", 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "haptic-motor2", 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    printf("Haptic feedback started. Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Motor 1: GPIO17 HIGH for MOTOR1_DURATION_MS, then LOW. */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(line1, 1)");
            goto cleanup;
        }
        sleep_ms(MOTOR1_DURATION_MS);
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(line1, 0)");
            goto cleanup;
        }

        /* Motor 2: GPIO27 HIGH for MOTOR2_DURATION_MS, then LOW. */
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(line2, 1)");
            goto cleanup;
        }
        sleep_ms(MOTOR2_DURATION_MS);
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(line2, 0)");
            goto cleanup;
        }
    }

    /* Ensure motors are off on exit. */
    if (gpiod_line_set_value(line1, 0) < 0) {
        perror("gpiod_line_set_value(line1, 0) on exit");
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        perror("gpiod_line_set_value(line2, 0) on exit");
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path. */
    if (line1 != NULL) {
        gpiod_line_release(line1);
    }
    if (line2 != NULL) {
        gpiod_line_release(line2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nHaptic feedback stopped.\n");
    }
    return ret;
}

