#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>
#include <czmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    27
#define ZMQ_PORT         "tcp://*:5555"
#define ZMQ_SUB_PORT     "tcp://localhost:5555"
#define POLL_TIMEOUT_US  10000
#define ALARM_DURATION_S 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(ALARM_LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d low\n", ALARM_LED_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(ALARM_LED_PIN, 0);
    gpioTerminate();
}

static int setup_zmq(zsock_t **pub, zsock_t **sub) {
    *pub = zsock_new(ZMQ_PUB);
    if (!*pub) {
        fprintf(stderr, "Error: failed to create ZMQ publisher: %s\n", zmq_strerror(errno));
        return -1;
    }
    if (zsock_bind(*pub, ZMQ_PORT) != 0) {
        fprintf(stderr, "Error: failed to bind ZMQ publisher to %s: %s\n", ZMQ_PORT, zmq_strerror(errno));
        zsock_destroy(pub);
        *pub = NULL;
        return -1;
    }

    *sub = zsock_new(ZMQ_SUB);
    if (!*sub) {
        fprintf(stderr, "Error: failed to create ZMQ subscriber: %s\n", zmq_strerror(errno));
        zsock_destroy(pub);
        *pub = NULL;
        return -1;
    }
    if (zsock_connect(*sub, ZMQ_SUB_PORT) != 0) {
        fprintf(stderr, "Error: failed to connect ZMQ subscriber to %s: %s\n", ZMQ_SUB_PORT, zmq_strerror(errno));
        zsock_destroy(pub);
        zsock_destroy(sub);
        *pub = NULL;
        *sub = NULL;
        return -1;
    }
    if (zsock_set_subscribe(*sub, "SOUND_ALERTS") != 0) {
        fprintf(stderr, "Error: failed to set ZMQ subscription filter\n");
        zsock_destroy(pub);
        zsock_destroy(sub);
        *pub = NULL;
        *sub = NULL;
        return -1;
    }
    return 0;
}

static void cleanup_zmq(zsock_t *pub, zsock_t *sub) {
    if (pub) {
        zsock_destroy(&pub);
    }
    if (sub) {
        zsock_destroy(&sub);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  sound_sensor: poll LM393 on GPIO17 and publish alerts\n");
        fprintf(stderr, "  alarm_node:   subscribe to alerts and light LED for 1 s\n");
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Error: invalid mode '%s'. Choose 'sound_sensor' or 'alarm_node'.\n", mode);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    zsock_t *publisher = NULL;
    zsock_t *subscriber = NULL;
    int rc = EXIT_SUCCESS;

    if (strcmp(mode, "sound_sensor") == 0) {
        if (setup_gpio() != 0) {
            return EXIT_FAILURE;
        }
        if (setup_zmq(&publisher, &subscriber) != 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        printf("Sound sensor mode active. Polling GPIO%d every %d ms. Press Ctrl+C to exit.\n",
               SOUND_SENSOR_PIN, POLL_TIMEOUT_US / 1000);

        while (g_running) {
            int sound_level = gpioRead(SOUND_SENSOR_PIN);
            if (sound_level < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", SOUND_SENSOR_PIN);
                rc = EXIT_FAILURE;
                break;
            }
            if (sound_level == 0) {
                char timestamp[32];
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                if (tm_info) {
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                } else {
                    snprintf(timestamp, sizeof(timestamp), "unknown");
                }
                char message[256];
                snprintf(message, sizeof(message), "SOUND_ALERTS %s", timestamp);
                if (zsock_send(publisher, "s", message) != 0) {
                    fprintf(stderr, "Error: zsock_send failed: %s\n", zmq_strerror(errno));
                    rc = EXIT_FAILURE;
                    break;
                }
                printf("Sound detected at %s. Alert published.\n", timestamp);
            }
            gpioDelay(POLL_TIMEOUT_US);
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        if (setup_zmq(&publisher, &subscriber) != 0) {
            return EXIT_FAILURE;
        }
        if (setup_gpio() != 0) {
            cleanup_zmq(publisher, subscriber);
            return EXIT_FAILURE;
        }

        printf("Alarm node mode active. Listening on %s. Press Ctrl+C to exit.\n", ZMQ_SUB_PORT);

        while (g_running) {
            char *message = zsock_recv(subscriber);
            if (message) {
                printf("Received alert: %s\n", message);
                if (gpioWrite(ALARM_LED_PIN, 1) < 0) {
                    fprintf(stderr, "Error: failed to set GPIO%d high\n", ALARM_LED_PIN);
                    rc = EXIT_FAILURE;
                    break;
                }
                gpioDelay(ALARM_DURATION_S * 1000000);
                if (gpioWrite(ALARM_LED_PIN, 0) < 0) {
                    fprintf(stderr, "Error: failed to set GPIO%d low\n", ALARM_LED_PIN);
                    rc = EXIT_FAILURE;
                    break;
                }
                free(message);
            } else if (errno != EINTR) {
                fprintf(stderr, "Error: zsock_recv failed: %s\n", zmq_strerror(errno));
                rc = EXIT_FAILURE;
                break;
            }
        }
    }

    cleanup_gpio();
    cleanup_zmq(publisher, subscriber);
    printf("Clean shutdown complete.\n");
    return rc;
}

