/*
 * NEC IR decoder for Raspberry Pi 3 Model B+
 * IR receiver: TSOP38238 on GPIO17 (BCM)
 * MQTT broker: localhost, port 1883, topic ir/decoded
 *
 * Build: gcc -O2 -Wall -o ir_decoder ir_decoder.c -lpigpio -lmosquitto
 * Run:   sudo ./ir_decoder
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO          17
#define MQTT_HOST        "localhost"
#define MQTT_PORT        1883
#define MQTT_TOPIC       "ir/decoded"
#define MQTT_CLIENT_ID   "ir_decoder"
#define MQTT_QOS         0
#define MQTT_KEEPALIVE   60
#define MAX_PULSES       100
#define DEBOUNCE_US      100
#define NEC_HDR_MARK     9000
#define NEC_HDR_SPACE    4500
#define NEC_BIT_MARK     560
#define NEC_ONE_SPACE    1690
#define NEC_ZERO_SPACE   560
#define NEC_TOLERANCE    300
#define NEC_TIMEOUT_US   15000
#define NEC_MIN_BITS     2
#define NEC_MAX_BITS     32

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_buf[MAX_PULSES];
static volatile int          g_pulse_count = 0;
static volatile uint32_t     g_last_tick   = 0;
static volatile bool         g_rising      = false;
static volatile bool         g_frame_ready = false;
static volatile uint32_t     g_frame       = 0;

static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* NEC frame decoding                                                   */
/* ------------------------------------------------------------------ */
static bool in_range(uint32_t val, uint32_t target, uint32_t tol)
{
    return (val >= target - tol) && (val <= target + tol);
}

static bool decode_nec(uint32_t *frame)
{
    if (g_pulse_count < NEC_MIN_BITS + 1)
        return false;

    if (!in_range(g_pulse_buf[0], NEC_HDR_MARK, NEC_TOLERANCE))
        return false;

    if (!in_range(g_pulse_buf[1], NEC_HDR_SPACE, NEC_TOLERANCE))
        return false;

    uint32_t address = 0, command = 0;
    int bits = 0;

    for (int i = 2; i < g_pulse_count; i += 2) {
        if (bits >= NEC_MAX_BITS)
            return false;

        if (!in_range(g_pulse_buf[i], NEC_BIT_MARK, NEC_TOLERANCE))
            return false;

        uint32_t space = g_pulse_buf[i + 1];

        if (in_range(space, NEC_ONE_SPACE, NEC_TOLERANCE)) {
            if (bits < 16)
                address |= (1u << bits);
            else
                command |= (1u << (bits - 16));
        } else if (!in_range(space, NEC_ZERO_SPACE, NEC_TOLERANCE))
            return false;

        bits++;
    }

    if (bits < 32)
        return false;

    uint8_t addr_lo  = (address >> 0)  & 0xFF;
    uint8_t addr_hi  = (address >> 8)  & 0xFF;
    uint8_t cmd_lo   = (command >> 0)  & 0xFF;
    uint8_t cmd_hi   = (command >> 8)  & 0xFF;
    uint8_t addr_inv = ~addr_lo;
    uint8_t cmd_inv  = ~cmd_lo;

    if (addr_lo != addr_inv)
        return false;

    *frame = command;
    return true;
}

/* ------------------------------------------------------------------ */
/* GPIO alert callback (falling edge)                                   */
/* ------------------------------------------------------------------ */
static void ir_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level != 0)
        return;

    uint32_t diff = tick - g_last_tick;
    g_last_tick = tick;

    if (diff > NEC_TIMEOUT_US) {
        g_pulse_count = 0;
        g_frame_ready = false;
        return;
    }

    if (g_pulse_count < MAX_PULSES)
        g_pulse_buf[g_pulse_count++] = diff;
    else
        g_frame_ready = false;

    if (g_pulse_count >= 2) {
        uint32_t hdr_mark  = g_pulse_buf[0];
