#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR_BASE 0x23
#define BH1750_CMD_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_MS 180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux) {
    if (i2c_write_byte(fd, BH1750_CMD_CONT_HIGH_RES) < 0) {
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int send_multicast_data(float lux_values[NUM_SENSORS]) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }
    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt");
        close(sockfd);
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    char data[256];
    int len = snprintf(data, sizeof(data), "%d,%.2f;%d,%.2f;%d,%.2f;%d,%.2f",
                       1, lux_values[0], 2, lux_values[1], 3, lux_values[2], 4, lux_values[3]);
    if (len < 0 || (size_t)len >= sizeof(data)) {
        fprintf(stderr, "snprintf failed\n");
        close(sockfd);
        return -1;
    }
    if (sendto(sockfd, data, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }
    int i2c_fds[NUM_SENSORS];
    int i2c_opened = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        char path[64];
        snprintf(path, sizeof(path), "%s", I2C_BUS);
        i2c_fds[i] = open(path, O_RDWR);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "open %s: %s\n", path, strerror(errno));
            for (int j = 0; j < i; j++) {
                close(i2c_fds[j]);
            }
            return 1;
        }
        i2c_opened = 1;
        uint8_t addr = BH1750_ADDR_BASE + (uint8_t)(i * 2);
        if (ioctl(i2c_fds[i], I2C_SLAVE, addr) < 0) {
            fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", addr, strerror(errno));
            close(i2c_fds[i]);
            for (int j = 0; j < i; j++) {
                close(i2c_fds[j]);
            }
            return 1;
        }
    }
    while (!terminate) {
        float lux_values[NUM_SENSORS];
        int valid = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (read_bh1750(i2c_fds[i], &lux_values[i]) == 0) {
                valid++;
            } else {
                lux_values[i] = NAN;
            }
        }
        if (valid > 0) {
            if (send_multicast_data(lux_values) < 0) {
                fprintf(stderr, "Failed to send multicast data\n");
            }
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }
    return 0;
}

