/*
 * Raspberry Pi Zero W — Honeywell AWM7300V mass-airflow sensor logger
 *
 * Wiring:
 *   AWM7300V SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   AWM7300V SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   AWM7300V VDD  -> 3.3 V
 *   AWM7300V GND  -> GND
 *
 * The AWM7300V is an I2C slave at address 0x40.  A zero-length write
 * (i2c_smbus_write_byte_data(fd, 0, 0)) generates a start condition
 * and clocks out the device's two-byte data frame.  The first byte
 * contains the 14-bit flow value in bits 7..2, and the second byte
 * contains the remaining two bits in bits 1..0.
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300_ADDR   0x40
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1           /* seconds between samples */
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100         /* ms between I2C read retries */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Open the I2C bus and set the slave address.
 * Returns a valid file descriptor (>= 0) on success, or -1 on error.
 */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Issue a zero-length write to generate a start condition and clock
 * out the 2-byte data frame from the AWM7300V.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_sensor(int fd, uint8_t *buf, size_t len)
{
    if (len != 2) {
        fprintf(stderr, "i2c_read_sensor: unexpected length %zu\n", len);
        return -1;
    }

    /* Zero-length write: start condition, then device clocks out data. */
    if (i2c_smbus_write_byte_data(fd, 0, 0) < 0) {
        fprintf(stderr, "i2c_smbus_write_byte_data: %s\n", strerror(errno));
        return -1;
    }

    /* Small delay so the sensor has time to clock out the data. */
    usleep(2000);

    /* Read the two bytes back. */
    for (size_t i = 0; i < len; i++) {
        __s32 b = i2c_smbus_read_byte_data(fd, (uint8_t)i);
        if (b < 0) {
            fprintf(stderr, "i2c_smbus_read_byte_data[%zu]: %s\n",
                    i, strerror(errno));
            return -1;
        }
        buf[i] = (uint8_t)b;
    }
    return 0;
}

/*
 * Convert the 14-bit flow value (bits 7..2 of buf[0]) to SLPM.
 * Returns 0 on success, -1 on error.
 */
static int convert_to_slpm(const uint8_t *buf, float *slpm)
{
    if (slpm == NULL) {
        return -1;
    }

    uint16_t raw = ((uint16_t)(buf[0] & 0x3F) << 8) | (uint16_t)buf[1];
    *slpm = (float)raw * 0.01f;   /* SLPM per 0.01 SLPM per LSB */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float slpm)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r(): %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", ts, slpm) < 0) {
        fprintf(stderr, "fprintf(): %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush(): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for clean shutdown. */
    if (install_signal_handler() < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus and set the slave address. */
    g_i2c_fd = i2c_open(I2C_BUS, AWM7300_ADDR);
    if (g_i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode. */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started.  Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t buf[2];
        int ok = 0;

        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; attempt++) {
            if (i2c_read_sensor(g_i2c_fd, buf, sizeof(buf)) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d attempts; "
                            "continuing.\n", MAX_RETRIES);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float slpm;
        if (convert_to_slpm(buf, &slpm) != 0) {
            fprintf(stderr, "convert_to_slpm failed; continuing.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_data(g_log_fp, slpm) != 0) {
            fprintf(stderr, "log_data failed; continuing.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

