/*
 * AS7341 10-Channel Light/Color Sensor reader for Raspberry Pi 3 Model B+
 * Bus: /dev/i2c-1   Address: 0x39   Log: spectral_log.csv
 *
 * Build:  gcc -O2 -Wall -Wextra -o as7341_monitor as7341_monitor.c
 * Run:    ./as7341_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- AS7341 register definitions (per datasheet) ---- */
#define AS7341_I2C_ADDR        0x39
#define AS7341_REG_ENABLE      0x80
#define AS7341_REG_ATIME       0x81
#define AS7341_REG_CFG0        0x83
#define AS7341_REG_CFG1        0x84
#define AS7341_REG_CFG2        0x85
#define AS7341_REG_CFG3        0x86
#define AS7341_REG_CFG4        0x87
#define AS7341_REG_CFG5        0x88
#define AS7341_REG_CFG6        0x89
#define AS7341_REG_CFG7        0x8A
#define AS7341_REG_ID          0x92
#define AS7341_REG_STATUS      0x93
#define AS7341_REG_F1DATAL     0x94
#define AS7341_REG_F1DATAH     0x95
#define AS7341_REG_F2DATAL     0x96
#define AS7341_REG_F2DATAH     0x97
#define AS7341_REG_F3DATAL     0x98
#define AS7341_REG_F3DATAH     0x99
#define AS7341_REG_F4DATAL     0x9A
#define AS7341_REG_F4DATAH     0x9B
#define AS7341_REG_F5DATAL     0x9C
#define AS7341_REG_F5DATAH     0x9D
#define AS7341_REG_F6DATAL     0x9E
#define AS7341_REG_F6DATAH     0x9F
#define AS7341_REG_F7DATAL     0xA0
#define AS7341_REG_F7DATAH     0xA1
#define AS7341_REG_F8DATAL     0xA2
#define AS7341_REG_F8DATAH     0xA3
#define AS7341_REG_CDATAL      0xA4
#define AS7341_REG_CDATAH      0xA5
#define AS7341_REG_NDATAL      0xA6
#define AS7341_REG_NDATAH      0xA7

#define AS7341_ID_VALUE        0x33

/* ENABLE register bits */
#define AS7341_ENABLE_PON      0x01
#define AS7341_ENABLE_SP_EN    0x02

/* CFG6: SMUX selection (0x00 = 100ms integration, 1x gain, 1 sample) */
#define AS7341_CFG6_SMUX_100MS 0x00

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register. Returns 0 on success, -1 err.  */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "[I2C] write reg 0x%02X val 0x%02X failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from an 8-bit register. Returns 0 on success, -1 err. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "[I2C] write reg-select 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
static int as7341_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, AS7341_REG_ID, &id) != 0) {
        fprintf(stderr, "[AS7341] Cannot read ID register — sensor absent or bus error.\n");
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "[AS7341] ID mismatch: got 0x%02X, expected 0x%02X.\n",
                id, AS7341_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON) != 0)
        return -1;
    usleep(10000);  /* 10 ms power-up settle */

    /* Configure SMUX: 100 ms integration, 1x gain, 1 sample */
    if (i2c_write_reg8(fd, AS7341_REG_CFG6, AS7341_CFG6_SMUX_100MS) != 0)
        return -1;

    /* Enable spectral measurement */
    if (i2c_write_reg8(fd, AS7341_REG_ENABLE,
                       AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int as7341_read_spectral(int fd, uint16_t spectral[10])
{
    for (int i = 0; i < 10; i++) {
        uint8_t lo = 0, hi = 0;
        uint8_t reg_lo = 0, reg_hi = 0;
        switch (i) {
            case 0: reg_lo = AS7341_REG_F1DATAL; reg_hi = AS7341_REG_F1DATAH; break;
            case 1: reg_lo = AS7341_REG_F2DATAL; reg_hi = AS7341_REG_F2DATAH; break;
            case 2: reg_lo = AS7341_REG_F3DATAL; reg_hi = AS7341_REG_F3DATAH; break;
            case 3: reg_lo = AS7341_REG_F4DATAL; reg_hi = AS7341_REG_F4DATAH; break;
            case 4: reg_lo = AS7341_REG_F5DATAL; reg_hi = AS7341_REG_F5DATAH; break;
            case 5: reg_lo = AS7341_REG_F6DATAL; reg_hi = AS7341_REG_F6DATAH; break;
            case 6: reg_lo = AS7341_REG_F7DATAL; reg_hi = AS7341_REG_F7DATAH; break;
            case 7: reg_lo = AS7341_REG_F8DATAL; reg_hi = AS7341_REG_F8DATAH; break;
            case 8: reg_lo = AS7341_REG_CDATAL;  reg_hi = AS7341_REG_CDATAH;  break;
            case 9: reg_lo = AS7341_REG_NDATAL;  reg_hi = AS7341_REG_NDATAH;  break;
            default: return -1;
        }
        if (i2c_read_reg8(fd, reg_lo, &lo) != 0) return -1;
        if (i2c_read_reg8(fd, reg_hi, &hi) != 0) return -1;
        spectral[i] = (uint16_t)((hi << 8) | lo);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static float as7341_lux_approx(const uint16_t spectral[10])
{
    /* Simplified lux approximation using F1 (Red), F2 (Green), F3 (Blue),
       F4 (Clear), and F8 (NIR). */
    float red   = (float)spectral[0];
    float green = (float)spectral[1];
    float blue  = (float)spectral[2];
    float clear = (float)spectral[3];
    float nir   = (float)spectral[7];

    /* Empirical coefficients (adjust for your calibration) */
    float lux = 0.0f;
    if (clear > 0.0f) {
        float r_ratio = red   / clear;
        float g_ratio = green / clear;
        float b_ratio = blue  / clear;
        float n_ratio = nir   / clear;

        /* Red channel is often used for lux approximation */
        if (r_ratio > 0.0f) {
            lux = 500.0f * r_ratio;
        }
    }
    return lux;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const uint16_t spectral[10], float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                ts, spectral[0], spectral[1], spectral[2], spectral[3],
                spectral[4], spectral[5], spectral[6], spectral[7],
                spectral[8], lux) < 0) {
        fprintf(stderr, "[LOG] fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[LOG] fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[MAIN] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[MAIN] open /dev/i2c-1 failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "[MAIN] ioctl I2C_SLAVE 0x%02X failed: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (as7341_init(g_i2c_fd) != 0) {
        fprintf(stderr, "[MAIN] AS7341 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen("spectral_log.csv", "a");
    if (g_log == NULL) {
        fprintf(stderr, "[MAIN] fopen spectral_log.csv failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log) == 0) {
        fprintf(g_log, "timestamp,F1,FG,F3,FC,F5,F6,F7,F8,C,NIR,lux\n");
        fflush(g_log);
    }

    printf("[MAIN] AS7341 plant health monitor started. Press Ctrl+C to stop.\n");

    /* Main acquisition loop */
    while (g_running) {
        uint16_t spectral[10];
        if (as7341_read_spectral(g_i2c_fd, spectral) != 0) {
            fprintf(stderr, "[MAIN] Spectral read failed — continuing.\n");
            sleep(5);
            continue;
        }

        float lux = as7341_lux_approx(spectral);
        if (log_data(g_log, spectral, lux) != 0) {
            fprintf(stderr, "[MAIN] Logging failed — continuing.\n");
        }

        printf("Spectral: F1=%u FG=%u F3=%u FC=%u F5=%u F6=%u F7=%u F8=%u C=%u NIR=%u  Lux=%.2f\n",
               spectral[0], spectral[1], spectral[2], spectral[3],
               spectral[4], spectral[5], spectral[6], spectral[7],
               spectral[8], spectral[9], lux);

        sleep(5);
    }

    /* ---- Clean shutdown ---- */
    printf("\n[MAIN] Shutting down...\n");
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("[MAIN] Done.\n");
    return EXIT_SUCCESS;
}

code:
/*
 * D7S seismic sensor reader for Raspberry Pi Zero W
 *
 * Reads tri-axial acceleration (X, Y, Z) in g from an Omron D7S over I2C
 * and logs timestamped samples to a CSV file.  Error messages are also
 * timestamped and appended to seismic_error.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o seismic_reader seismic_reader.c
 * Run:    ./seismic_reader [-a i2c_addr] [-i interval_s] [-f filename]
 *
 * Defaults:  I2C address 0x50, interval 1 s, output seismic_data.csv
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <getopt.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Omron D7S register map (subset) ---- */
#define D7S_REG_X_LSB   0x00
#define D7S_REG_X_MSB   0x01
#define D7S_REG_Y_LSB   0x02
#define D7S_REG_Y_MSB   0x03
#define D7S_REG_Z_LSB   0x04
#define D7S_REG_Z_MSB   0x05
#define D7S_REG_STATUS  0x06
#define D7S_REG_CTRL    0x07

#define D7S_I2C_ADDR_DEFAULT 0x50
#define D7S_I2C_BUS         "/dev/i2c-1"
#define D7S_RETRIES         3
#define D7S_RETRY_DELAY_MS  10
#define D7S_CTRL_ACTIVE     0x01

#define SAMPLE_INTERVAL_S   1
#define SAMPLE_INTERVAL_NS  0

#define GRAVITY 9.80665

typedef struct {
    float x, y, z;
} sensor_data_t;

typedef struct {
    int  i2c_addr;
    int  interval_s;
    char filename[256];
} program_config_t;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;
static FILE *g_err   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void timestamp_str(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    timestamp_str(ts, sizeof ts);
    fprintf(stderr, "[%s] ERROR: %s (errno %d: %s)\n",
            ts, msg, errno, strerror(errno));
    if (g_err) {
        fprintf(g_err, "%s,ERROR,%s\n", ts, msg);
        fflush(g_err);
    }
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    for (int attempt = 0; attempt < D7S_RETRIES; ++attempt) {
        if (write(fd, buf, 2) == 2)
            return 0;
        char msg[128];
        snprintf(msg, sizeof msg, "I2C write to reg 0x%02X failed", reg);
        log_error(msg);
        if (attempt < D7S_RETRIES - 1)
            usleep(D7S_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    for (int attempt = 0; attempt < D7S_RETRIES; ++attempt) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, val, 1) == 1)
                return 0;
        }
        char msg[128];
        snprintf(msg, sizeof msg, "I2C read from reg 0x%02X failed", reg);
        log_error(msg);
        if (attempt < D7S_RETRIES - 1)
            usleep(D7S_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    for (int attempt = 0; attempt < D7S_RETRIES; ++attempt) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, buf, len) == (ssize_t)len)
                return 0;
        }
        char msg[128];
        snprintf(msg, sizeof msg, "I2C block read from reg 0x%02X failed", reg);
        log_error(msg);
        if (attempt < D7S_RETRIES - 1)
            usleep(D7S_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int init_i2c(int addr)
{
    int fd = open(D7S_I2C_BUS, O_RDWR);
    if (fd < 0) {
        log_error("open I2C bus failed");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_error("ioctl I2C_SLAVE failed");
        close(fd);
        return -1;
    }
    return fd;
}

/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    uint8_t status = 0;
    if (i2c_read_reg8(fd, D7S_REG_STATUS, &status) < 0)
        return -1;

    if (!(status & D7S_CTRL_ACTIVE)) {
        if (i2c_write_reg8(fd, D7S_REG_CTRL, D7S_CTRL_ACTIVE) < 0)
            return -1;
        usleep(10000); /* allow sensor to settle */
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, sensor_data_t *data)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, D7S_REG_X_LSB, raw, sizeof raw) < 0)
        return -1;

    int16_t x = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z = (int16_t)((raw[5] << 8) | raw[4]);

    data->x = (float)x * GRAVITY / 32768.0f;
    data->y = (float)y * GRAVITY / 32768.0f;
    data->z = (float)z * GRAVITY / 32768.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const sensor_data_t *data)
{
    char ts[32];
    timestamp_str(ts, sizeof ts);
    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", ts, data->x, data->y, data->z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_err) {
        fflush(g_err);
        fclose(g_err);
        g_err = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
static void parse_args(int argc, char *argv[], program_config_t *cfg)
{
    cfg->i2c_addr  = D7S_I2C_ADDR_DEFAULT;
    cfg->interval_s = SAMPLE_INTERVAL_S;
    strncpy(cfg->filename, "seismic_data.csv", sizeof cfg->filename - 1);
    cfg->filename[sizeof cfg->filename - 1] = '\0';

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
        case 'a':
            cfg->i2c_addr = (int)strtol(optarg, NULL, 0);
            break;
        case 'i':
            cfg->interval_s = atoi(optarg);
            if (cfg->interval_s <= 0)
                cfg->interval_s = SAMPLE_INTERVAL_S;
            break;
        case 'f':
            strncpy(cfg->filename, optarg, sizeof cfg->filename - 1);
            cfg->filename[sizeof cfg->filename - 1] = '\0';
            break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [-a i2c_addr] [-i interval_s] [-f filename]\n",
                    argv[0]);
            exit(EXIT_FAILURE);
        }
    }
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    program_config_t cfg;
    parse_args(argc, argv, &cfg);

    g_err = fopen("seismic_error.log", "a");
    if (!g_err) {
        perror("fopen seismic_error.log");
        return EXIT_FAILURE;
    }

    g_i2c_fd = init_i2c(cfg.i2c_addr);
    if (g_i2c_fd < 0) {
        log_error("I2C init failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        log_error("Sensor init failed (sensor absent or bus error)");
        cleanup();
        return EXIT_FAILURE;
    }

    g_csv = fopen(cfg.filename, "a");
    if (!g_csv) {
        log_error("fopen CSV failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
