#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE    "/dev/i2c-1"
#define BH1750_ADDR   0x23
#define BH1750_PWR_ON 0x01
#define BH1750_RESET  0x07
#define BH1750_CONT_H 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL            1
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_sock   = -1;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, unsigned char byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len)
{
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd)
{
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_RESET)  < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    unsigned char buf[2];
    if (i2c_write_byte(fd, BH1750_CONT_H) < 0) return -1;
    usleep(180000);
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int setup_multicast_socket(void)
{
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }
    int ttl = TTL;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(IP_MULTICAST_TTL)");
        close(sock);
        return -1;
    }
    return sock;
}

static int send_multicast(int sock, float lux)
{
    char buffer[32];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(sock, buffer, (size_t)len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_DEVICE);
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }
    if (bh1750_init(g_i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_sock = setup_multicast_socket();
    if (g_sock < 0) {
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        float lux;
        if (bh1750_read_lux(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error; retrying in %d s\n", SAMPLE_PERIOD);
        } else {
            if (send_multicast(g_sock, lux) < 0) {
                fprintf(stderr, "Multicast send error\n");
            }
        }
        sleep(SAMPLE_PERIOD);
    }

    if (g_sock >= 0) close(g_sock);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

