/*
 * AWR1642 mmWave radar UART reader for Raspberry Pi 3 Model B+
 * Reads TLV frames from /dev/ttyS0 at 921600 baud, extracts range/velocity
 * for each detected object, and appends rows to radar_data.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o radar_reader radar_reader.c -lpigpio -lrt
 * Run:    sudo ./radar_reader   (pigpio requires root for /dev/ttyS0)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE    "/dev/ttyS0"
#define BAUD_RATE      921600
#define CSV_FILE       "radar_data.csv"
#define READ_BUF_SIZE  4096
#define FRAME_BUF_SIZE 8192
#define MAGIC_WORD     {0x02, 0x01, 0x04, 0x03}
#define MAGIC_LEN      4
#define TLV_TYPE_RANGE 1
#define TLV_TYPE_VEL   2

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  UART driver (pigpio)                                               */
/* ------------------------------------------------------------------ */

typedef struct {
    int handle;
    int baud;
    int bytes_available;
    uint8_t rx_buf[READ_BUF_SIZE];
} uart_t;

static int uart_init(uart_t *u, const char *device, int baud)
{
    u->handle = serOpen((char *)device, baud, 0);
    if (u->handle < 0) {
        fprintf(stderr, "serOpen(%s, %d) failed: %s\n",
                device, baud, strerror(errno));
        return -1;
    }
    u->baud = baud;
    u->bytes_available = 0;
    return 0;
}

static int uart_read(uart_t *u, uint8_t *buf, int max_len)
{
    if (u->bytes_available == 0) {
        u->bytes_available = serDataAvailable(u->handle);
        if (u->bytes_available < 0) {
            fprintf(stderr, "serDataAvailable failed: %s\n", strerror(errno));
            return -1;
        }
        if (u->bytes_available == 0)
            return 0;                 /* no data right now */
    }

    int to_read = (max_len < u->bytes_available) ? max_len : u->bytes_available;
    int n = serRead(u->handle, (char *)buf, to_read);
    if (n < 0) {
        fprintf(stderr, "serRead failed: %s\n", strerror(errno));
        return -1;
    }
    u->bytes_available -= n;
    return n;
}

static void uart_close(uart_t *u)
{
    if (u->handle >= 0) {
        serClose(u->handle);
        u->handle = -1;
    }
}

/* ------------------------------------------------------------------ */
/*  CSV writer                                                         */
/* ------------------------------------------------------------------ */

typedef struct {
    FILE *fp;
    int   frame_count;
    int   obj_count;
} csv_t;

static int csv_open(csv_t *c, const char *path)
{
    c->fp = fopen(path, "a");
    if (!c->fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    if (fseek(c->fp, 0, SEEK_END) == 0 && ftell(c->fp) == 0)
        fprintf(c->fp, "timestamp,object_index,range_m,velocity_mps\n");
    c->frame_count = 0;
    c->obj_count   = 0;
    return 0;
}

static void csv_append(csv_t *c, int obj_idx, float range, float vel)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "1970-01-01 00:00:00");

    fprintf(c->fp, "%s,%d,%.3f,%.3f\n", ts, obj_idx, range, vel);
    fflush(c->fp);
    c->obj_count++;
}

static void csv_close(csv_t *c)
{
    if (c->fp) {
        fprintf(stderr, "Frame count: %d, object count: %d\n",
                c->frame_count, c->obj_count);
        fflush(c->fp);
        fclose(c->fp);
        c->fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/*  Frame parsing                                                      */
/* ------------------------------------------------------------------ */

typedef struct {
    uint32_t magic[MAGIC_LEN];
    uint32_t version;
    uint32_t total_packet_len;
    uint32_t platform;
    uint32_t frame_number;
    uint32_t time_subframe;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
    uint32_t subframe_number;
} __attribute__((packed)) frame_header_t;

typedef struct {
    uint32_t type;
    uint32_t length;
} __attribute__((packed)) tlv_header_t;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
    uint16_t x;
    uint16_t y;
    uint16_t z;
} __attribute__((packed)) range_t;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
} __attribute__((packed)) vel_t;

static int find_magic(const uint8_t *buf, int len)
{
    for (int i = 0; i <= len - MAGIC_LEN; i++) {
        if (memcmp(buf + i, MAGIC_WORD, MAGIC_LEN) == 0)
            return i;
    }
    return -1;
}

static int parse_frame(const uint8_t *frame, int frame_len, csv_t *csv)
{
    if (frame_len < (int)sizeof(frame_header_t))
        return -1;

    const frame_header_t *hdr = (const frame_header_t *)frame;
    if (hdr->total_packet_len > FRAME_BUF_SIZE ||
        hdr->total_packet_len < sizeof(frame_header_t))
        return -1;

    if (frame_len < (int)hdr->total_packet_len)
        return -1;                 /* partial frame */

    uint32_t num_tlvs = hdr->num_tlvs;
    uint32_t offset   = sizeof(frame_header_t);

    for (uint32_t i = 0; i < num_tlvs; i++) {
        if (offset + sizeof(tlv_header_t) > hdr->total_packet_len)
            return -1;
        const tlv_header_t *tlv = (const tlv_header_t *)(frame + offset);
        offset += sizeof(tlv_header_t);

        if (offset + tlv->length > hdr->total_packet_len)
            return -1;

        if (tlv->type == TLV_TYPE_RANGE) {
            uint32_t num_obj = tlv->length / sizeof(range_t);
            for (uint32_t j = 0; j < num_obj; j++) {
                const range_t *r = (const range_t *)(frame + offset +
                    j * sizeof(range_t));
                csv_append(csv, (int)j, (float)r->range_idx, 0.0f);
            }
        } else if (tlv->type == TLV_TYPE_VEL) {
            uint32_t num_obj = tlv->length / sizeof(vel_t);
            for (uint32_t j = 0; j < num_obj; j++) {
                const vel_t *v = (const vel_t *)(frame + offset +
                    j * sizeof(vel_t));
                csv_append(csv, (int)j, 0.0f, (float)v->doppler_idx);
            }
        }
        offset += tlv->length;
    }
    csv->frame_count++;
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    uart_t uart;
    if (uart_init(&uart, UART_DEVICE, BAUD_RATE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    csv_t csv;
    if (csv_open(&csv, CSV_FILE) != 0) {
        uart_close(&uart);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t frame_buf[FRAME_BUF_SIZE];
    int frame_len = 0;
    uint8_t read_buf[READ_BUF_SIZE];

    fprintf(stderr, "Radar reader started on %s @ %d baud. Ctrl+C to stop.\n",
            UART_DEVICE, BAUD_RATE);

    while (g_running) {
        int n = uart_read(&uart, read_buf, sizeof(read_buf));
        if (n < 0) {
            fprintf(stderr, "UART read error; continuing.\n");
            continue;
        }
        if (n == 0)
            continue;

        for (int i = 0; i < n && g_running; i++) {
            if (frame_len < (int)sizeof(frame_buf)) {
                frame_buf[frame_len++] = read_buf[i];
            } else {
                /* Buffer overflow: discard frame and resync on magic */
                int idx = find_magic(frame_buf, frame_len);
                if (idx < 0) {
                    frame_len = 0;
                    continue;
                }
                memmove(frame_buf, frame_buf + idx, frame_len - idx);
                frame_len -= idx;
                frame_buf[frame_len++] = read_buf[i];
            }

            int mw = find_magic(frame_buf, frame_len);
            if (mw < 0)
                continue;

            if (mw > 0) {
                /* Discard bytes before magic word */
                memmove(frame_buf, frame_buf + mw, frame_len - mw);
                frame_len -= mw;
            }

            if (frame_len < (int)sizeof(frame_header_t))
                continue;

            const frame_header_t *hdr = (const frame_header_t *)frame_buf;
            if (hdr->total_packet_len > FRAME_BUF_SIZE ||
                hdr->total_packet_len < sizeof(frame_header_t))
            {
                /* Corrupt header: discard frame */
                frame_len = 0;
                continue;
            }

            if (frame_len < (int)hdr->total_packet_len)
                continue;           /* need more data */

            parse_frame(frame_buf, hdr->total_packet_len, &csv);

            /* Shift remaining payload to front */
            int remaining = frame_len - hdr->total_packet_len;
            if (remaining > 0)
                memmove(frame_buf, frame_buf + hdr->total_packet_len, remaining);
            frame_len = remaining;
        }
    }

    fprintf(stderr, "\nShutting down...\n");
    csv_close(&csv);
    uart_close(&uart);
    gpioTerminate();
    return EXIT_SUCCESS;
}

