#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/time.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 512
#define READ_BUF_SIZE 256
#define POLL_TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_SEC 0.5

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);

    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = (cc_t)(INTER_BYTE_TIMEOUT_SEC * 10);

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void parse_line(const char *line) {
    char *copy = strdup(line);
    if (!copy) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return;
    }

    char *saveptr = NULL;
    char *token = strtok_r(copy, ",", &saveptr);
    if (!token) {
        free(copy);
        return;
    }

    char *endptr = NULL;
    long timestamp = strtol(token, &endptr, 10);
    if (endptr == token) {
        fprintf(stderr, "Invalid timestamp: %s\n", token);
        free(copy);
        return;
    }

    token = strtok_r(NULL, "\n", &saveptr);
    if (!token) {
        free(copy);
        return;
    }

    char *range_endptr = NULL;
    double range = strtod(token, &range_endptr);
    if (range_endptr == token) {
        fprintf(stderr, "Invalid range: %s\n", token);
        free(copy);
        return;
    }

    time_t rawtime = (time_t)timestamp;
    struct tm *timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "localtime failed\n");
        free(copy);
        return;
    }

    char time_str[32];
    if (strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        free(copy);
        return;
    }

    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
    fflush(stdout);
    free(copy);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = init_uart(UART_PORT, BAUD_RATE);
    if (g_uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[READ_BUF_SIZE];

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval tv;
        tv.tv_sec = POLL_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int ret = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            fprintf(stderr, "Sensor absent or bus error: no data within %d seconds\n", POLL_TIMEOUT_SEC);
            continue;
        }

        ssize_t bytes_read = read(g_uart_fd, read_buf, sizeof(read_buf));
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "UART closed by peer\n");
            break;
        }

        for (ssize_t i = 0; i < bytes_read; i++) {
            char c = read_buf[i];
            if (c == '\n') {
                line_buf[line_len] = '\0';
                parse_line(line_buf);
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line buffer overflow, discarding\n");
                    line_len = 0;
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    return 0;
}

