#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define UART_DEVICE       "/dev/ttyAMA0"
#define BAUD_RATE         B115200
#define POLL_DELAY_US     100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* UART setup                                                          */
/* ------------------------------------------------------------------ */
static int init_uart(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }

    /* Clear O_NDELAY so reads block */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        perror("fcntl F_SETFL");
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag  = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);

    tty.c_lflag  = 0;
    tty.c_oflag  = 0;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;   /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Emergency stop                                                      */
/* ------------------------------------------------------------------ */
static void emergency_stop(int fd)
{
    const char *msg = "EMERGENCY STOP!\n";
    ssize_t n = write(fd, msg, strlen(msg));
    if (n < 0) {
        perror("write emergency stop");
    } else if (n != (ssize_t)strlen(msg)) {
        fprintf(stderr, "partial write: %zd of %zu bytes\n",
                n, strlen(msg));
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(LEFT_SENSOR_PIN,   PI_INPUT) != 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN,  PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN,   PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(RIGHT_SENSOR_PIN,  PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- UART setup ---- */
    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("KY-033 3-Way Tracking Sensor Program\n");
    printf("Left=GPIO%d, Middle=GPIO%d, Right=GPIO%d, UART=%s @ 115200\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN,
           UART_DEVICE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "gpioRead error (left=%d mid=%d right=%d)\n",
                    left, middle, right);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-033: LOW = obstacle detected, HIGH = clear */
        int obstacle = (left == 0 || middle == 0 || right == 0) ? 1 : 0;

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        if (t != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        } else {
            snprintf(ts, sizeof(ts), "unknown");
        }

        printf("[%s] L=%d M=%d R=%d  ->  %s\n",
               ts, left, middle, right,
               obstacle ? "EMERGENCY STOP!" : "OK");

        if (obstacle) {
            emergency_stop(g_uart_fd);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

